-- full_schema.sql — COMPLETE public schema, generated by scripts/backup-schema.mjs
-- ============================================================================
-- Do not hand-edit: regenerate with `npm run backup:schema`.
--
-- WHY: the Supabase organisation is on the FREE plan and the backups endpoint
-- returns an EMPTY list. There are no automated backups of this database. This
-- file is the schema half of the answer; data is NOT in here (see below).
--
-- Contents: 9 extensions · 0 enums · 306 tables ·
-- 1413 constraints · 423 indexes · 867 functions ·
-- 296 triggers · 404 policies · 841 role grants ·
-- explicit REVOKEs for the closed perimeter.
--
-- WHAT THIS DOES NOT COVER, so nobody mistakes it for a full backup:
--   · no table DATA — tenants, users, documents, conversations are all absent
--   · no auth.users — accounts do not come back from this file
--   · no storage objects, no vault secrets, no edge-function code
--   · no pg_cron schedules
-- Restoring this yields an EMPTY, correctly-shaped, correctly-secured and
-- REACHABLE database — the last of those was missing until 2026-08-20: the file
-- carried the REVOKEs and none of the GRANTs, so a restore came back with every
-- table present and no API role able to read one (register A-12).
-- ============================================================================

-- ── Extensions ──────────────────────────────────────────────────────────────
CREATE EXTENSION IF NOT EXISTS "hypopg" WITH SCHEMA extensions;
CREATE EXTENSION IF NOT EXISTS "index_advisor" WITH SCHEMA extensions;
CREATE EXTENSION IF NOT EXISTS "pg_cron" WITH SCHEMA pg_catalog;
CREATE EXTENSION IF NOT EXISTS "pg_net" WITH SCHEMA public;
CREATE EXTENSION IF NOT EXISTS "pg_stat_statements" WITH SCHEMA extensions;
CREATE EXTENSION IF NOT EXISTS "pgcrypto" WITH SCHEMA extensions;
CREATE EXTENSION IF NOT EXISTS "supabase_vault" WITH SCHEMA vault;
CREATE EXTENSION IF NOT EXISTS "uuid-ossp" WITH SCHEMA extensions;
CREATE EXTENSION IF NOT EXISTS "vector" WITH SCHEMA public;

-- ── Enum types ──────────────────────────────────────────────────────────────

-- ── Functions ───────────────────────────────────────────────────────────────
-- BEFORE the tables, and this ordering is load-bearing. Found by running an
-- actual restore, not by reading the file: connectors has
--   CONSTRAINT connectors_base_url_safe_check CHECK (is_safe_external_url(base_url))
-- so a CHECK constraint depends on a function. With functions emitted last the
-- restore died on table 40-odd of 257. The file looked completely fine.
--
-- Functions in turn reference tables that do not exist yet, so body validation
-- is deferred: LANGUAGE sql bodies are parsed at CREATE time unless this is off.
-- pg_dump does the same thing for the same reason.
SET check_function_bodies = false;

CREATE OR REPLACE FUNCTION public._assert_caller_tenant(p_tenant_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  -- An unauthenticated PostgREST caller is NOT a trusted server caller, even
  -- though both present a NULL auth.uid(). Distinguish them by the request role.
  IF coalesce(
       nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'role',
       '') = 'anon' THEN
    RAISE EXCEPTION 'not_authorized_for_tenant';
  END IF;
  IF auth.uid() IS NULL THEN RETURN; END IF;   -- service role / cron / psql
  IF p_tenant_id IS NULL OR public.auth_tenant_id() IS DISTINCT FROM p_tenant_id THEN
    RAISE EXCEPTION 'not_authorized_for_tenant';
  END IF;
END$function$;

CREATE OR REPLACE FUNCTION public._assert_conv_member(p_conversation_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_tenant uuid;
begin
  if auth.uid() is null then raise exception 'not authenticated'; end if;
  select tenant_id into v_tenant from de_conversations where id = p_conversation_id;
  if v_tenant is null then raise exception 'conversation_not_found'; end if;
  if not (is_platform_admin() or exists (select 1 from profiles p where p.user_id = auth.uid() and p.tenant_id = v_tenant)) then
    raise exception 'not authorized for this workspace';
  end if;
  return v_tenant;
end;
$function$;

CREATE OR REPLACE FUNCTION public._dispatch_fn(p_path text, p_body jsonb DEFAULT '{}'::jsonb)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_secret text;
  v_anon   text := platform_anon_key();
  v_req    bigint;
BEGIN
  SELECT decrypted_secret INTO v_secret FROM vault.decrypted_secrets
   WHERE name = 'playbook_dispatch_secret' LIMIT 1;
  IF v_secret IS NULL THEN
    -- Same alert the original raised, kept so a missing secret is still loud
    -- rather than a silently dead cron.
    PERFORM raise_ops_alert('dispatch_secret_missing',
      format('playbook_dispatch_secret is missing from Vault — %s is doing NOTHING.', p_path),
      jsonb_build_object('path', p_path));
    RETURN NULL;
  END IF;
  SELECT net.http_post(
    url := platform_fn_url(p_path),
    body := p_body,
    headers := jsonb_build_object('Content-Type','application/json',
                                  'Authorization','Bearer '||v_anon,
                                  'apikey', v_anon,
                                  'x-dispatch-secret', v_secret),
    timeout_milliseconds := 30000
  ) INTO v_req;
  RETURN v_req;
EXCEPTION WHEN OTHERS THEN
  -- The original swallowed failures on two of the four posts. Now all four
  -- behave the same way AND say so, rather than one cron dying while its
  -- neighbours in the same function carry on.
  RAISE WARNING 'dispatch to % failed: %', p_path, SQLERRM;
  RETURN NULL;
END;
$function$;

CREATE OR REPLACE FUNCTION public._dispatch_overdue(p_fn text, p_window interval DEFAULT '01:00:00'::interval)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT NOT EXISTS (
    SELECT 1 FROM dispatch_log
     WHERE fn = p_fn AND created_at > now() - p_window
  )
$function$;

CREATE OR REPLACE FUNCTION public._pending_conflict_probe()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ SELECT EXISTS (SELECT 1 FROM knowledge_conflict_probe_queue WHERE probed_at IS NULL) $function$;

CREATE OR REPLACE FUNCTION public._pending_embed_backfill()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ SELECT EXISTS (SELECT 1 FROM knowledge_doc_chunks WHERE embedding IS NULL) $function$;

CREATE OR REPLACE FUNCTION public._pending_playbook_work()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (SELECT 1 FROM playbook_trigger_fires WHERE status = 'pending_start')
      OR EXISTS (SELECT 1 FROM playbook_runs
                  WHERE status = 'waiting' AND resume_at IS NOT NULL AND resume_at <= now())
      -- Broader than the worker, deliberately: it additionally checks whether
      -- the gating task was decided. Over-dispatching is the safe direction.
      OR EXISTS (SELECT 1 FROM playbook_runs
                  WHERE status = 'waiting' AND resume_at IS NULL AND waiting_task_id IS NOT NULL)
$function$;

CREATE OR REPLACE FUNCTION public._pending_reembed()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ SELECT EXISTS (SELECT 1 FROM knowledge_doc_chunks WHERE reembed_pending) $function$;

CREATE OR REPLACE FUNCTION public.access_permission_level(p_permission text)
 RETURNS integer
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select case p_permission
    when 'search' then 1
    when 'read' then 2
    when 'ingest' then 3
    when 'write_back' then 4
    else 0
  end;
$function$;

CREATE OR REPLACE FUNCTION public.account_review_draft(p_kind text, p_account uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_acct      customer_accounts;
  v_h         jsonb;
  v_measured  boolean;
  v_score     text;
  n_open_inv  int; v_known_out bigint; n_unverified int; n_overdue int;
  n_tickets   int; n_escal int;
  v_last_act  timestamptz;
  v_case      record;
  v_title     text;
  v_lines     text[] := '{}';
  v_findings  jsonb;
  v_days_to_renewal int;
  v_tenure_months int;
begin
  select * into v_acct from customer_accounts where id = p_account;
  if not found then return jsonb_build_object('error', 'account_not_found'); end if;

  v_h        := coalesce(v_acct.health_components, '{}'::jsonb);
  v_measured := coalesce((v_h->>'measured')::boolean, false);
  v_score    := case when v_measured then coalesce(v_acct.health_score::text, '?') || '/100'
                     else null end;

  select count(*) filter (where lower(coalesce(ri.status, '')) not in ('paid', 'void', 'cancelled')),
         coalesce(sum(ri.outstanding_cents) filter (where ri.outstanding_cents is not null
                    and lower(coalesce(ri.status, '')) not in ('paid', 'void', 'cancelled')), 0),
         count(*) filter (where ri.outstanding_cents is null
                    and lower(coalesce(ri.status, '')) not in ('paid', 'void', 'cancelled')),
         count(*) filter (where ri.due_date is not null and ri.due_date < current_date
                    and lower(coalesce(ri.status, '')) not in ('paid', 'void', 'cancelled'))
    into n_open_inv, v_known_out, n_unverified, n_overdue
    from renewal_invoices ri where ri.account_id = p_account;

  select count(*) filter (where st.status in ('open', 'pending')),
         count(*) filter (where st.status = 'escalated')
    into n_tickets, n_escal
    from support_tickets st where st.account_id = p_account;

  select max(ae.created_at) into v_last_act from activity_events ae where ae.account_id = p_account;

  select cc.stage_key, cc.risk_level, cc.next_step, cc.next_step_date
    into v_case
    from continuity_cases cc
   where cc.account_id = p_account and cc.outcome is null
   order by cc.updated_at desc limit 1;

  v_days_to_renewal := case when v_acct.renewal_date is null then null
                            else (v_acct.renewal_date - current_date) end;
  v_tenure_months := greatest(0, (extract(year from age(now(), v_acct.created_at)) * 12
                                  + extract(month from age(now(), v_acct.created_at)))::int);

  -- ── shared facts, in the approver's language ──
  if v_measured then
    v_lines := v_lines || format('Health: %s (%s). Penalties — open tickets %s, escalations %s, overdue invoices %s, activity recency %s.',
      v_score, coalesce(v_acct.status, 'active'),
      coalesce(v_h#>>'{open_tickets,count}', '0'), coalesce(v_h#>>'{escalations,count}', '0'),
      coalesce(v_h#>>'{overdue_invoices,count}', '0'),
      case when v_h#>>'{activity_recency,days_since}' is null then 'no activity ever recorded'
           else v_h#>>'{activity_recency,days_since}' || ' day(s) since last activity' end);
  else
    v_lines := v_lines || format('Health: NOT MEASURED — no tickets, invoices or activity are recorded for this account yet, so there is nothing to compute a score from. The score on file (%s) is whatever was entered by hand.',
      coalesce(v_acct.health_score::text, 'none'));
  end if;

  v_lines := v_lines || format('Receivables: %s open invoice(s)%s%s.',
    n_open_inv,
    case when v_known_out > 0 then format(', %s confirmed outstanding', to_char(v_known_out / 100.0, 'FM999,999,990.00')) else '' end,
    case when n_unverified > 0 then format(', %s with no reconciled balance (face value only)', n_unverified) else '' end)
    || case when n_overdue > 0 then format(' %s of them past due.', n_overdue) else '' end;

  v_lines := v_lines || case
    when v_acct.renewal_date is null then 'Renewal: no renewal date is recorded for this account.'
    when v_days_to_renewal < 0 then format('Renewal: %s — %s day(s) PAST.', to_char(v_acct.renewal_date, 'FMDD FMMonth YYYY'), -v_days_to_renewal)
    else format('Renewal: %s (in %s day(s)).', to_char(v_acct.renewal_date, 'FMDD FMMonth YYYY'), v_days_to_renewal) end;

  v_lines := v_lines || case
    when v_case.stage_key is not null then format('Continuity case: open at stage %s%s%s.',
      v_case.stage_key,
      case when v_case.next_step is not null then ', next step: ' || v_case.next_step else ', NO NEXT STEP recorded' end,
      case when v_case.next_step_date is not null then ' by ' || to_char(v_case.next_step_date, 'FMDD FMMonth YYYY') else '' end)
    else 'Continuity case: none open.' end;

  -- ── kind-specific framing ──
  if p_kind = 'health_check' then
    v_title := format('Monthly health check — %s', v_acct.name);
    v_lines := array_prepend(format('Monthly health check for %s (%s%s).',
      v_acct.name, coalesce(nullif(v_acct.tier, ''), 'no tier recorded'),
      case when v_acct.arr_cents is not null then format(', ARR %s', to_char(v_acct.arr_cents / 100.0, 'FM999,999,990')) else '' end), v_lines);
    v_lines := v_lines || 'Approve to file this review. Reject with a note if something here needs a different owner or a correction first.'::text;
  elsif p_kind = 'lifecycle' then
    v_title := format('Quarterly lifecycle review — %s', v_acct.name);
    v_lines := array_prepend(format('Quarterly lifecycle review for %s. Customer for %s month(s), tier %s%s.',
      v_acct.name, v_tenure_months, coalesce(nullif(v_acct.tier, ''), 'not recorded'),
      case when v_acct.arr_cents is not null then format(', ARR %s', to_char(v_acct.arr_cents / 100.0, 'FM999,999,990')) else '' end), v_lines);
    if v_days_to_renewal is not null and v_days_to_renewal between 0 and 90 and v_case.stage_key is null then
      v_lines := v_lines || 'The renewal is inside 90 days and no continuity case is open — opening one is the concrete next step.'::text;
    end if;
    v_lines := v_lines || 'No score history is kept yet; this review records today''s position so next quarter has something to compare against.'::text;
  elsif p_kind = 'churn_risk' then
    v_title := format('Churn-risk review — %s', v_acct.name);
    v_lines := array_prepend(format('Churn-risk review for %s — this account is marked AT RISK.', v_acct.name), v_lines);
    v_lines := v_lines || case
      when v_case.stage_key is null then 'A save plan needs a continuity case with a named next step and a date. There is none open — that is the gap to close first.'
      when v_case.next_step is null then 'The open continuity case has NO NEXT STEP recorded — a save plan without a next step is a label, not a plan.'
      else 'Keep the open case''s next step honest: if it has slipped, re-date it and say why.' end::text;
  else
    return jsonb_build_object('error', 'unknown_review_kind', 'kind', p_kind);
  end if;

  v_findings := jsonb_build_object(
    'health', v_h,
    'status', v_acct.status,
    'arr_cents', v_acct.arr_cents,
    'tier', v_acct.tier,
    'renewal_date', v_acct.renewal_date,
    'days_to_renewal', v_days_to_renewal,
    'tenure_months', v_tenure_months,
    'open_invoices', n_open_inv,
    'overdue_invoices', n_overdue,
    'known_outstanding_cents', v_known_out,
    'unverified_balance_invoices', n_unverified,
    'open_tickets', n_tickets,
    'escalated_tickets', n_escal,
    'last_activity_at', v_last_act,
    'continuity_case', case when v_case.stage_key is null then null
                            else jsonb_build_object('stage', v_case.stage_key, 'risk', v_case.risk_level,
                                                    'next_step', v_case.next_step, 'next_step_date', v_case.next_step_date) end);

  return jsonb_build_object('title', v_title,
                            'detail', array_to_string(v_lines, E'\n\n'),
                            'findings', v_findings);
end;
$function$;

CREATE OR REPLACE FUNCTION public.acknowledge_de_performance_review(p_review_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tenant uuid;
  v_row de_performance_reviews;
begin
  v_tenant := auth_tenant_id();
  if v_tenant is null then raise exception 'not a member of any workspace'; end if;
  if not auth_has_tenant_role(array['tenant_owner', 'tenant_admin']) then
    raise exception 'only workspace owners/admins can acknowledge a review';
  end if;
  update de_performance_reviews set status = 'acknowledged', acknowledged_by = auth.uid(), acknowledged_at = now()
  where id = p_review_id and tenant_id = v_tenant
  returning * into v_row;
  if v_row.id is null then raise exception 'review not found in this workspace'; end if;
  return jsonb_build_object('ok', true);
end;
$function$;

CREATE OR REPLACE FUNCTION public.add_group_member(p_group_id uuid, p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tenant uuid := auth_tenant_id(); v_my int; v_group int; v_name text; v_who text;
BEGIN
  IF v_tenant IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  SELECT name INTO v_name FROM knowledge_principal_groups WHERE id = p_group_id AND tenant_id = v_tenant;
  IF v_name IS NULL THEN RAISE EXCEPTION 'group_not_found'; END IF;

  v_my := public.knowledge_my_admin_level(NULL);
  IF v_my < 5 AND NOT is_platform_admin() THEN
    RAISE EXCEPTION 'insufficient_permission: managing groups requires knowledge manager';
  END IF;

  -- THE GUARD THIS FUNCTION EXISTS FOR. Membership confers everything the group
  -- holds, so adding somebody to a group is a grant of that level. Without this
  -- check a knowledge manager adds themselves to any group holding
  -- workspace_admin and has it a second later — laundering straight around
  -- mig 356's escalation guard.
  v_group := public.knowledge_group_max_level(p_group_id);
  IF v_group > v_my AND NOT is_platform_admin() THEN
    RAISE EXCEPTION 'insufficient_permission: "%" carries access above your level, so you cannot add people to it', v_name;
  END IF;

  -- The person must be a real, active member of THIS workspace.
  SELECT coalesce(full_name, 'a teammate') INTO v_who FROM profiles
   WHERE user_id = p_user_id AND tenant_id = v_tenant AND coalesce(is_active, true);
  IF v_who IS NULL THEN RAISE EXCEPTION 'that person is not a member of this workspace'; END IF;

  INSERT INTO knowledge_principal_group_members (tenant_id, group_id, user_id, added_by)
  VALUES (v_tenant, p_group_id, p_user_id, auth.uid())
  ON CONFLICT (group_id, user_id) DO NOTHING;

  PERFORM append_audit_event(v_tenant, 'Knowledge', 'human',
    format('Added %s to the group "%s"', v_who, v_name), 'access_control',
    jsonb_build_object('group_id', p_group_id, 'user_id', p_user_id));
  RETURN jsonb_build_object('ok', true);
END $function$;

CREATE OR REPLACE FUNCTION public.add_tenant_ip_allowlist_entry(p_tenant_id uuid, p_ip_range text, p_label text DEFAULT ''::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_id uuid;
  v_cidr cidr;
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;
  if not (
    is_platform_admin()
    or exists (
      select 1 from profiles p
      where p.user_id = auth.uid() and p.tenant_id = p_tenant_id
        and coalesce(p.is_active, true) = true
        and p.role in ('tenant_owner', 'tenant_admin')
    )
  ) then
    raise exception 'only workspace owners/admins can add an IP range';
  end if;

  begin
    v_cidr := p_ip_range::cidr;
  exception when others then
    raise exception '"%" is not a valid IP address or CIDR range (e.g. 192.168.1.0/24)', p_ip_range;
  end;

  insert into tenant_ip_allowlist_entries (tenant_id, ip_range, label, created_by)
  values (p_tenant_id, v_cidr, coalesce(trim(p_label), ''), auth.uid())
  returning id into v_id;

  perform append_audit_event_internal(
    p_tenant_id, 'You', 'human',
    format('IP range added to allowlist: %s', v_cidr),
    'config_change',
    jsonb_build_object('kind', 'ip_allowlist_entry_added', 'entry_id', v_id, 'ip_range', v_cidr::text)
  );

  return jsonb_build_object('id', v_id);
end;
$function$;

CREATE OR REPLACE FUNCTION public.advance_de_lifecycle(p_de_id uuid, p_to_stage text, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tenant uuid;
  v_de digital_employees;
  v_readiness jsonb;
  v_ok boolean;
  v_actor_name text;
  v_expected_from text;
begin
  v_tenant := auth_tenant_id();
  if v_tenant is null then raise exception 'not a member of any tenant'; end if;
  if not auth_has_tenant_role(array['tenant_owner', 'tenant_admin']) then
    raise exception 'only workspace owners/admins can advance an employee''s lifecycle';
  end if;

  select * into v_de from digital_employees where id = p_de_id and tenant_id = v_tenant;
  if v_de.id is null then raise exception 'employee not found in this workspace'; end if;
  if v_de.lifecycle_status in ('retired', 'archived') then
    raise exception 'this employee is retired — its lifecycle is closed';
  end if;
  if v_de.lifecycle_status = 'paused' then
    raise exception 'this employee is paused — use resume first';
  end if;

  v_expected_from := case p_to_stage
    when 'configured' then 'designed'
    when 'trained'    then 'configured'
    when 'tested'     then 'trained'
    when 'certified'  then 'tested'
    when 'published'  then 'certified'
    when 'assigned'   then 'published'
    when 'active'     then 'assigned'
    else null
  end;
  if v_expected_from is null then
    raise exception 'stage "%" is not reachable through advance (pause/resume/retire have their own controls)', p_to_stage;
  end if;
  if v_de.lifecycle_status <> v_expected_from then
    raise exception 'cannot advance to "%" from "%" — the chain is designed → configured → trained → tested → certified → published → assigned → active', p_to_stage, v_de.lifecycle_status;
  end if;

  v_readiness := compute_de_lifecycle_readiness(p_de_id);
  v_ok := case p_to_stage
    when 'configured' then (v_readiness->'criteria'->'configured'->>'identity_complete')::boolean
    when 'trained'    then (v_readiness->'criteria'->'trained'->>'control_fabric_grant')::boolean
                       and (v_readiness->'criteria'->'trained'->>'knowledge_in_scope')::boolean
                       and (v_readiness->'criteria'->'trained'->>'active_guardrails')::boolean
    when 'tested'     then (v_readiness->'criteria'->'tested'->>'knowledge_embedded')::boolean
    when 'certified'  then (v_readiness->'criteria'->'certified'->>'golden_qa_passed')::boolean
    when 'published'  then (v_readiness->'criteria'->'published'->>'certified_by_human')::boolean
    when 'assigned'   then (v_readiness->'criteria'->'assigned'->>'has_work_channel')::boolean
                           and coalesce((v_readiness->'criteria'->'assigned'->>'grounding_connected')::boolean, true)
    when 'active'     then (v_readiness->'criteria'->'active'->>'first_live_execution')::boolean
  end;
  if not coalesce(v_ok, false) then
    return jsonb_build_object('ok', false, 'blocked', true, 'readiness', v_readiness,
      'reason', format('Entry criteria for "%s" are not met yet — see readiness.', p_to_stage));
  end if;

  if p_to_stage = 'certified' and (p_note is null or trim(p_note) = '') then
    raise exception 'certification requires a note stating what was reviewed';
  end if;

  select full_name into v_actor_name from profiles where user_id = auth.uid();

  update digital_employees set
    lifecycle_status = p_to_stage,
    status = case when p_to_stage in ('assigned', 'active') then 'active' else status end,
    updated_at = now()
  where id = p_de_id;

  insert into de_lifecycle_events (tenant_id, de_id, from_stage, to_stage, actor_id, actor_label, note, criteria_snapshot)
  values (v_tenant, p_de_id, v_de.lifecycle_status, p_to_stage, auth.uid(), coalesce(v_actor_name, 'A workspace admin'), p_note, v_readiness);

  -- §9.5 (migration 129): the lifecycle checkpoint also issues the
  -- durable, expiring workspace certification.
  if p_to_stage = 'certified' then
    insert into de_certifications (tenant_id, de_id, cert_type, scope, note, issued_by, issued_by_name, expires_at)
    values (v_tenant, p_de_id, 'workspace', 'Pre-launch lifecycle certification', trim(p_note), auth.uid(),
            coalesce(v_actor_name, 'A workspace admin'), now() + interval '180 days');
  end if;

  perform append_audit_event_internal(
    v_tenant, coalesce(v_actor_name, 'A workspace admin'), 'human',
    format('%s advanced to %s%s', v_de.name, p_to_stage,
      case when p_note is not null and p_note <> '' then format(' — "%s"', left(p_note, 160)) else '' end),
    'config_change',
    jsonb_build_object('kind', 'lifecycle_advance', 'de_id', p_de_id, 'from', v_de.lifecycle_status, 'to', p_to_stage)
  );

  return jsonb_build_object('ok', true, 'stage', p_to_stage);
end;
$function$;

CREATE OR REPLACE FUNCTION public.advance_dunning_cadence()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_invoice uuid;
  v_stage   int;
  v_key     text;
  v_ref     text;
  v_now     boolean;
  v_was     boolean := false;
begin
  -- ── HAS THE CHASE ACTUALLY BEEN SENT? Through the ONE definition.
  v_now := public.action_execution_landed(new);

  -- The same question about the row BEFORE this statement. On INSERT there is
  -- no before — and OLD is unassigned there, so it must not be touched.
  if tg_op = 'UPDATE' then
    v_was := public.action_execution_landed(old);
  end if;

  -- Not sent: a gate row, a claim taken BEFORE the call, a preview, a failure,
  -- a rollback. The rung does not move for work that has not happened.
  if not v_now then return null; end if;
  -- Already sent before this statement: this UPDATE changed something else,
  -- and must not recompute a rung against a later `current_date`.
  if v_was then return null; end if;

  -- ── PATH A: the sweep's own key, unchanged. dunning:<invoice>:<stage> ────
  if new.dedupe_key is not null and new.dedupe_key like 'dunning:%' then
    v_invoice := nullif(split_part(new.dedupe_key, ':', 2), '')::uuid;
    v_stage   := nullif(split_part(new.dedupe_key, ':', 3), '')::int;

  -- ── PATH B (mig 661): the same chase, sent by an employee. ──────────────
  -- Recognise it by the ACTION it ran, resolve the invoice from the reference
  -- it was given, and read the rung out of the ladder.
  else
    select ad.action_key into v_key
      from action_definitions ad where ad.id = new.action_definition_id;
    if v_key is null then return null; end if;

    v_ref := nullif(btrim(new.params->>'external_ref'), '');
    if v_ref is null then return null; end if;

    -- Tenant-scoped by construction: the reference is caller-supplied text.
    select ri.id into v_invoice
      from renewal_invoices ri
     where ri.tenant_id = new.tenant_id
       and ri.source_external_ref = v_ref
     limit 1;
    if v_invoice is null then return null; end if;

    -- The highest rung this action can represent that the invoice has actually
    -- reached. Not the action's "usual" stage — action_key repeats across rungs.
    select max(r.stage) into v_stage
      from dunning_rungs r
      join dunning_ladders l on l.id = r.ladder_id
      join renewal_invoices ri on ri.id = v_invoice
     where l.active
       and (l.tenant_id = new.tenant_id or l.tenant_id is null)
       and r.action_key = v_key
       and ri.due_date is not null
       and (current_date - ri.due_date) >= coalesce(r.after_days_overdue, 0);
  end if;

  if v_invoice is null or v_stage is null then return null; end if;

  -- greatest(): a late-executing LOWER rung must never drag the ladder back
  -- down and re-open a chase the customer has already had.
  update renewal_invoices
     set cadence_stage = greatest(coalesce(cadence_stage, 0), v_stage),
         updated_at    = now()
   where id = v_invoice
     and tenant_id = new.tenant_id;

  return null;
exception when others then
  -- A malformed key or reference must not roll back an execution that has
  -- already reached a customer.
  return null;
end;
$function$;

CREATE OR REPLACE FUNCTION public.ai_apply_change(p_session_id uuid, p_kind text, p_target_id uuid, p_patch jsonb, p_summary text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tenant  uuid := public.auth_tenant_id();
  v_user    uuid := auth.uid();
  v_before  jsonb;
  v_after   jsonb;
  v_table   text;
  v_target  uuid := p_target_id;
  v_change  uuid;
BEGIN
  IF v_tenant IS NULL OR v_user IS NULL THEN
    RAISE EXCEPTION 'not_authenticated';
  END IF;

  -- The boundary the model cannot argue its way past.
  IF NOT public.ai_change_is_auto_appliable(p_kind) THEN
    RAISE EXCEPTION 'change_kind_requires_human_review: %', p_kind;
  END IF;

  -- Session must belong to this caller (prevents cross-user replay).
  IF p_session_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM ai_sessions s
    WHERE s.id = p_session_id AND s.tenant_id = v_tenant AND s.user_id = v_user
  ) THEN
    RAISE EXCEPTION 'session_not_found';
  END IF;

  IF p_kind = 'knowledge.create' THEN
    v_table := 'knowledge_docs';
    INSERT INTO knowledge_docs (tenant_id, title, content, source, tags, visibility)
    VALUES (
      v_tenant,
      coalesce(p_patch->>'title', 'Untitled'),
      coalesce(p_patch->>'content', ''),
      'ai_assistant',
      CASE WHEN jsonb_exists(p_patch, 'tags')
           THEN ARRAY(SELECT jsonb_array_elements_text(p_patch->'tags'))
           ELSE '{}'::text[] END,
      'tenant'
    )
    RETURNING id, to_jsonb(knowledge_docs.*) INTO v_target, v_after;

  ELSIF p_kind = 'knowledge.edit' THEN
    v_table := 'knowledge_docs';
    SELECT to_jsonb(k.*) INTO v_before FROM knowledge_docs k
    WHERE k.id = v_target AND k.tenant_id = v_tenant;
    IF v_before IS NULL THEN RAISE EXCEPTION 'knowledge_doc_not_found'; END IF;
    UPDATE knowledge_docs SET
      title   = coalesce(p_patch->>'title', title),
      content = coalesce(p_patch->>'content', content),
      updated_at = now()
    WHERE id = v_target AND tenant_id = v_tenant
    RETURNING to_jsonb(knowledge_docs.*) INTO v_after;

  ELSIF p_kind = 'playbook.draft_steps' THEN
    v_table := 'playbook_definitions';
    SELECT to_jsonb(d.*) INTO v_before FROM playbook_definitions d
    WHERE d.id = v_target AND d.tenant_id = v_tenant;
    IF v_before IS NULL THEN RAISE EXCEPTION 'playbook_not_found'; END IF;
    -- Draft-only: a published playbook is customer-affecting, so the
    -- assistant may never overwrite one in place.
    IF (v_before->>'status') = 'published' THEN
      RAISE EXCEPTION 'published_playbook_requires_human_review';
    END IF;
    UPDATE playbook_definitions SET
      steps = coalesce(p_patch->'steps', steps),
      name  = coalesce(p_patch->>'name', name),
      description = coalesce(p_patch->>'description', description),
      updated_at = now()
    WHERE id = v_target AND tenant_id = v_tenant
    RETURNING to_jsonb(playbook_definitions.*) INTO v_after;

  ELSIF p_kind = 'de.describe' THEN
    v_table := 'digital_employees';
    SELECT to_jsonb(d.*) INTO v_before FROM digital_employees d
    WHERE d.id = v_target AND d.tenant_id = v_tenant;
    IF v_before IS NULL THEN RAISE EXCEPTION 'de_not_found'; END IF;
    -- Identity/description ONLY. Deliberately cannot touch trust level,
    -- reply mode, lifecycle, model, or any guardrail-adjacent column.
    UPDATE digital_employees SET
      name              = coalesce(p_patch->>'name', name),
      persona_name      = coalesce(p_patch->>'persona_name', persona_name),
      description       = coalesce(p_patch->>'description', description),
      purpose_statement = coalesce(p_patch->>'purpose_statement', purpose_statement)
    WHERE id = v_target AND tenant_id = v_tenant
    RETURNING to_jsonb(digital_employees.*) INTO v_after;
  END IF;

  INSERT INTO ai_change_log (
    tenant_id, session_id, change_kind, target_table, target_id,
    summary, before_state, after_state, applied_by
  ) VALUES (
    v_tenant, p_session_id, p_kind, v_table, v_target,
    coalesce(nullif(p_summary, ''), p_kind), v_before, v_after, v_user
  ) RETURNING id INTO v_change;

  -- Auto-applied changes are still audited like everything else.
  PERFORM append_audit_event(
    v_tenant, 'Workspace Assistant', 'de',
    format('Auto-applied: %s', coalesce(nullif(p_summary, ''), p_kind)),
    'config_change',
    jsonb_build_object('change_id', v_change, 'kind', p_kind, 'target_id', v_target, 'undoable_until', now() + interval '120 hours')
  );

  RETURN jsonb_build_object(
    'ok', true, 'change_id', v_change, 'target_id', v_target,
    'undoable_until', (now() + interval '120 hours')::text
  );
END$function$;

CREATE OR REPLACE FUNCTION public.ai_change_is_auto_appliable(p_kind text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT p_kind IN (
    'knowledge.create',        -- add a knowledge document
    'knowledge.edit',          -- edit a knowledge document's title/content
    'playbook.draft_steps',    -- save DRAFT steps (never publish)
    'de.describe'              -- name / description / purpose / persona only
  );
$function$;

CREATE OR REPLACE FUNCTION public.ai_list_undoable(p_limit integer DEFAULT 20)
 RETURNS json
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT coalesce(json_agg(row_to_json(x)), '[]'::json) FROM (
    SELECT id, change_kind, summary, target_table, target_id,
           applied_at::text, expires_at::text
    FROM ai_change_log
    WHERE tenant_id = public.auth_tenant_id()
      AND undone_at IS NULL AND now() < expires_at
    ORDER BY applied_at DESC
    LIMIT greatest(1, least(p_limit, 100))
  ) x;
$function$;

CREATE OR REPLACE FUNCTION public.ai_undo_change(p_change_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tenant uuid := public.auth_tenant_id();
  v_user   uuid := auth.uid();
  v_row    ai_change_log;
BEGIN
  IF v_tenant IS NULL OR v_user IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;

  SELECT * INTO v_row FROM ai_change_log
  WHERE id = p_change_id AND tenant_id = v_tenant;
  IF v_row.id IS NULL THEN RAISE EXCEPTION 'change_not_found'; END IF;
  IF v_row.undone_at IS NOT NULL THEN RAISE EXCEPTION 'already_undone'; END IF;
  IF now() > v_row.expires_at THEN RAISE EXCEPTION 'undo_window_expired'; END IF;

  IF v_row.before_state IS NULL THEN
    -- The change created the row; undo = remove it.
    IF v_row.target_table = 'knowledge_docs' THEN
      DELETE FROM knowledge_docs WHERE id = v_row.target_id AND tenant_id = v_tenant;
    END IF;
  ELSIF v_row.target_table = 'knowledge_docs' THEN
    UPDATE knowledge_docs SET
      title = v_row.before_state->>'title',
      content = v_row.before_state->>'content',
      updated_at = now()
    WHERE id = v_row.target_id AND tenant_id = v_tenant;
  ELSIF v_row.target_table = 'playbook_definitions' THEN
    UPDATE playbook_definitions SET
      steps = v_row.before_state->'steps',
      name = v_row.before_state->>'name',
      description = v_row.before_state->>'description',
      updated_at = now()
    WHERE id = v_row.target_id AND tenant_id = v_tenant;
  ELSIF v_row.target_table = 'digital_employees' THEN
    -- DE scoping (mig 385/437). This branch alone: knowledge and playbooks
    -- are workspace assets and have their own ACL. Null-tolerant because
    -- ai_change_log.target_id is nullable.
    IF v_row.target_id IS NOT NULL AND NOT public.can_access_de(v_row.target_id) THEN
      RAISE EXCEPTION 'not_responsible_for_de: this employee is not in your reporting line';
    END IF;
    UPDATE digital_employees SET
      name = v_row.before_state->>'name',
      persona_name = v_row.before_state->>'persona_name',
      description = v_row.before_state->>'description',
      purpose_statement = v_row.before_state->>'purpose_statement'
    WHERE id = v_row.target_id AND tenant_id = v_tenant;
  END IF;

  UPDATE ai_change_log SET undone_at = now(), undone_by = v_user WHERE id = p_change_id;

  PERFORM append_audit_event(
    v_tenant, 'Workspace Assistant', 'human',
    format('Undone: %s', v_row.summary), 'config_change',
    jsonb_build_object('change_id', p_change_id, 'kind', v_row.change_kind)
  );

  RETURN jsonb_build_object('ok', true, 'restored', v_row.target_table);
END$function$;

CREATE OR REPLACE FUNCTION public.alert_cert_regression()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_fp text; v_pass role_certifications; v_name text; v_fresh boolean;
begin
  select * into v_pass from role_certifications
    where de_id = NEW.id and status = 'passed'
    order by evaluated_at desc nulls last, created_at desc limit 1;
  if v_pass.id is null then return NEW; end if;

  v_fp := public.de_config_fingerprint_row(NEW);
  -- Same predicate as the gate: fresh iff ANY passing cert matches.
  v_fresh := exists (select 1 from role_certifications c
                      where c.de_id = NEW.id and c.status = 'passed'
                        and c.config_fingerprint is not distinct from v_fp);
  if v_fresh then
    if v_pass.stale_alerted then
      update role_certifications set stale_alerted = false where id = v_pass.id;
    end if;
    return NEW;
  end if;
  if v_pass.stale_alerted then return NEW; end if;

  v_name := coalesce(NEW.persona_name, NEW.name, 'this employee');
  insert into activity_events (tenant_id, actor, actor_type, event_type, text, confidence)
  values (NEW.tenant_id, coalesce(NEW.persona_name, NEW.name, 'DE'), 'system', 'certification_stale',
    format('Configuration changed for %s after it was certified (%s%% on %s). Its certification is now STALE and no longer vouches for the current setup — re-run its evaluation or simulation and re-certify before relying on it or promoting it again.',
           v_name, v_pass.score_pct, coalesce(v_pass.evaluated_at::date::text, 'a prior run')),
    coalesce(v_pass.score_pct, 0));
  update role_certifications set stale_alerted = true where id = v_pass.id;
  return NEW;
end;
$function$;

CREATE OR REPLACE FUNCTION public.alert_on_stranded_approvals()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_row  record;
  v_kind text;
begin
  -- One pass per WORKSPACE holding a stranded approval for this definition.
  -- A platform-scope definition is visible to every tenant, so one retirement
  -- can strand tasks in several — and each workspace's operator needs to see
  -- their own, named.
  for v_row in
    select ht.tenant_id                          as tenant_id,
           coalesce(t.slug, ht.tenant_id::text)  as slug,
           count(*)                              as n_tasks,
           jsonb_agg(jsonb_build_object(
             'task_id',   ht.id,
             'title',     ht.title,
             'raised_at', ht.created_at) order by ht.created_at) as tasks
      from human_tasks ht
      join action_executions ae
        on (ae.task_id = ht.id or ae.resolves_task_id = ht.id)
      left join tenants t on t.id = ht.tenant_id
     where ae.action_definition_id = new.id
       and ht.type   = 'action_approval'
       and ht.status = 'pending'         -- only a task still awaiting a human
     group by ht.tenant_id, t.slug
  loop
    begin
      -- ⚠ THE TENANT AND THE DEFINITION ARE BOTH IN THE KIND. raise_ops_alert
      -- dedups on kind GLOBALLY (verified: 3 tenants, 1 shared kind -> 1 row
      -- landed), and ops_alerts has no tenant column, so a kind that does not
      -- carry the tenant reports one retirement when five happened.
      v_kind := 'stranded_approval_' || left(v_row.tenant_id::text, 8)
                || '_' || left(new.id::text, 8);

      if exists (select 1 from ops_alerts
                  where kind = v_kind and resolved_at is null) then
        continue;                        -- already open and unread; don't pile on
      end if;

      insert into ops_alerts (kind, message, detail) values (
        v_kind,
        v_row.slug || ': ' || v_row.n_tasks || ' pending approval'
          || case when v_row.n_tasks = 1 then '' else 's' end
          || ' can no longer be carried out. The action "' || new.action_key
          || '" just left status ''active'' for ''' || new.status
          || '''; connector-hub only ever resolves ACTIVE definitions, so '
          || 'approving ' || case when v_row.n_tasks = 1 then 'this task' else 'these tasks' end
          || ' would send nothing while the queue reads as done. First: '
          || coalesce(v_row.tasks->0->>'title', '(untitled)')
          || '. A person must withdraw or re-raise them — nothing has been decided here.',
        jsonb_build_object(
          'tenant_id',            v_row.tenant_id,
          'tenant_slug',          v_row.slug,
          'action_definition_id', new.id,
          'action_key',           new.action_key,
          'old_status',           old.status,
          'new_status',           new.status,
          'stranded_task_count',  v_row.n_tasks,
          'stranded_tasks',       v_row.tasks,
          'remedy',               'A human withdraws or re-raises each task. This alert never decides one.')
      );
    exception when others then
      -- ⛔ A BROKEN ALERT MUST NOT BLOCK A LEGITIMATE RETIREMENT, and one bad
      -- workspace must not cost the others their alert. Loud, not swallowed:
      -- a guard that fails quietly is the exact defect this migration exists
      -- to end.
      raise warning '704: could not raise the stranded-approval alert for tenant % on definition %: % (the retirement itself is unaffected)',
        v_row.tenant_id, new.id, sqlerrm;
    end;
  end loop;

  return new;   -- AFTER trigger: ignored. It cannot veto the UPDATE.
end;
$function$;

CREATE OR REPLACE FUNCTION public.analytics_action_volume(p_tenant_id uuid, p_days integer)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select jsonb_build_object(
    'window_days', p_days,
    'total', (select count(*) from action_executions where tenant_id = p_tenant_id
                and created_at >= now() - make_interval(days => greatest(1, p_days))),
    'by_decision', coalesce((select jsonb_object_agg(decision, c) from
       (select decision, count(*) c from action_executions where tenant_id = p_tenant_id
          and created_at >= now() - make_interval(days => greatest(1, p_days)) group by decision) d), '{}'::jsonb)
  );
$function$;

CREATE OR REPLACE FUNCTION public.analytics_de_workload(p_tenant_id uuid, p_de_id uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select jsonb_build_object(
    'objectives_by_status', coalesce((select jsonb_object_agg(status, c) from
       (select status, count(*) c from de_objectives where tenant_id = p_tenant_id and de_id = p_de_id
         -- 1. the caller's own workspace, or a trusted server
         and (coalesce(auth.role(), '') = 'service_role'
              or public.is_platform_admin()
              or p_tenant_id = public.auth_tenant_id())
         -- 2. and an employee they are responsible for (mig 385)
         and public.can_access_de(p_de_id) group by status) s), '{}'::jsonb),
    'work_items_by_status', coalesce((select jsonb_object_agg(status, c) from
       (select status, count(*) c from de_work_items where tenant_id = p_tenant_id and de_id = p_de_id
         -- 1. the caller's own workspace, or a trusted server
         and (coalesce(auth.role(), '') = 'service_role'
              or public.is_platform_admin()
              or p_tenant_id = public.auth_tenant_id())
         -- 2. and an employee they are responsible for (mig 385)
         and public.can_access_de(p_de_id) group by status) w), '{}'::jsonb)
  );
$function$;

CREATE OR REPLACE FUNCTION public.answer_playbook_gap(p_gap_id uuid, p_answer jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_gap    playbook_gaps;
  v_tenant uuid := public.auth_tenant_id();
  v_uid    uuid := auth.uid();
  v_actor  text;
begin
  if v_tenant is null or v_uid is null then
    raise exception 'not_authenticated';
  end if;
  select * into v_gap from playbook_gaps
   where id = p_gap_id and tenant_id = v_tenant
   for update;
  if v_gap.id is null then
    raise exception 'gap_not_found';
  end if;
  if v_gap.status in ('resolved', 'dismissed') then
    raise exception 'gap_already_closed: %', v_gap.status;
  end if;
  if v_gap.kind = 'missing_authority' then
    if not public.auth_has_tenant_role(array['tenant_owner','tenant_admin']) then
      raise exception 'authority_gap_requires_owner_or_admin';
    end if;
  else
    if not public.auth_has_tenant_role(array['tenant_owner','tenant_admin','tenant_manager']) then
      raise exception 'answering_requires_manager_role';
    end if;
  end if;
  if p_answer is null or jsonb_typeof(p_answer) <> 'object' then
    raise exception 'answer_must_be_an_object';
  end if;

  update playbook_gaps
     set answer = p_answer,
         status = 'answered',
         answered_by = v_uid,
         answered_at = now()
   where id = v_gap.id;

  select coalesce(nullif(full_name, ''), 'A workspace member') into v_actor
    from profiles where user_id = v_uid limit 1;
  perform append_audit_event(
    v_tenant, coalesce(v_actor, 'A workspace member'), 'human',
    format('Playbook gap answered — %s "%s" (%s)', v_gap.kind, v_gap.title, v_gap.gap_key),
    'config_change',
    jsonb_build_object('kind', 'playbook_gap_answered', 'gap_id', v_gap.id,
      'definition_id', v_gap.definition_id, 'gap_kind', v_gap.kind,
      'gap_key', v_gap.gap_key, 'answer', p_answer)
  );
  -- answered, NOT resolved — resolution is the recompile's verified verdict.
  return jsonb_build_object('ok', true, 'gap_id', v_gap.id, 'status', 'answered');
end $function$;

CREATE OR REPLACE FUNCTION public.append_audit_event_internal(p_tenant_id uuid, p_actor text, p_actor_type text, p_action text, p_category text, p_detail jsonb DEFAULT '{}'::jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_prev text;
  v_now  timestamptz;
  v_hash text;
  v_id   uuid;
  v_detail jsonb := coalesce(p_detail, '{}'::jsonb);
  v_block_de uuid;
begin
  -- Same per-employee stamp as append_audit_event (see that function's
  -- comment); kept in both sinks so the audited record does not depend on
  -- which write path a future guardrail writer picks.
  if p_category = 'guardrail_block' and p_actor_type = 'de' and not (v_detail ? 'de_id') then
    select min(id) into v_block_de
    from digital_employees
    where tenant_id = p_tenant_id
      and coalesce(nullif(persona_name, ''), name) = coalesce(nullif(p_actor, ''), 'system')
    having count(*) = 1;
    if v_block_de is not null then
      v_detail := v_detail || jsonb_build_object('de_id', v_block_de);
    end if;
  end if;

  perform pg_advisory_xact_lock(hashtext('audit_' || p_tenant_id::text));

  v_now  := clock_timestamp();                       -- mig 549: after the lock
  v_prev := public.audit_chain_tip(p_tenant_id);    -- mig 549: the true tip

  v_hash := encode(digest(v_prev || p_tenant_id::text || coalesce(p_action, '') ||
                          v_detail::text || v_now::text, 'sha256'), 'hex');

  insert into audit_events (tenant_id, actor, actor_type, action, category, detail, prev_hash, hash, created_at)
  values (p_tenant_id, p_actor, p_actor_type, p_action, p_category, v_detail, v_prev, v_hash, v_now)
  returning id into v_id;

  insert into audit_chain_state as s (tenant_id, head_hash, head_event_id, events, updated_at)
  values (p_tenant_id, v_hash, v_id, 1, v_now)
  on conflict (tenant_id) do update
    set head_hash = excluded.head_hash, head_event_id = excluded.head_event_id,
        events = s.events + 1, updated_at = excluded.updated_at;
end $function$;

CREATE OR REPLACE FUNCTION public.append_browser_task_step(p_task_id uuid, p_step jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF coalesce(auth.role(),'') <> 'service_role' THEN RAISE EXCEPTION 'service-role only'; END IF;
  UPDATE computer_use_tasks
     SET status = CASE WHEN status = 'claimed' THEN 'running' ELSE status END,
         audit = coalesce(audit, '[]'::jsonb) || jsonb_build_array(coalesce(p_step, '{}'::jsonb)),
         updated_at = now()
   WHERE id = p_task_id AND status IN ('claimed','running');
END; $function$;

CREATE OR REPLACE FUNCTION public.apply_account_writeback_internal(p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r account_writeback_requests; v_before text; v_act uuid;
BEGIN
  SELECT * INTO r FROM account_writeback_requests WHERE id = p_request_id;
  IF r.id IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'not_found'); END IF;
  IF r.status NOT IN ('pending_approval') THEN RETURN jsonb_build_object('ok', false, 'error', 'not_pending', 'status', r.status); END IF;

  IF r.op = 'log_activity' THEN
    INSERT INTO account_activities (tenant_id, account_id, de_id, objective_id, kind, summary, detail)
    VALUES (r.tenant_id, r.account_id, r.de_id, r.objective_id, 'activity_logged', r.composed->>'summary',
            jsonb_build_object('activity_kind', r.composed->>'activity_kind'))
    RETURNING id INTO v_act;

  ELSIF r.op = 'set_next_step' THEN
    UPDATE customer_accounts
       SET attributes = coalesce(attributes,'{}'::jsonb)
             || jsonb_build_object('next_step', r.composed->>'next_step', 'next_step_date', r.composed->>'next_step_date'),
           updated_at = now()
     WHERE id = r.account_id AND tenant_id = r.tenant_id;
    INSERT INTO account_activities (tenant_id, account_id, de_id, objective_id, kind, summary, detail)
    VALUES (r.tenant_id, r.account_id, r.de_id, r.objective_id, 'next_step_set',
            'Next step: ' || (r.composed->>'next_step'), r.composed) RETURNING id INTO v_act;

  ELSIF r.op = 'update_status' THEN
    SELECT status INTO v_before FROM customer_accounts WHERE id = r.account_id AND tenant_id = r.tenant_id;
    UPDATE customer_accounts SET status = r.composed->>'to_status', updated_at = now()
     WHERE id = r.account_id AND tenant_id = r.tenant_id;
    INSERT INTO account_activities (tenant_id, account_id, de_id, objective_id, kind, summary, detail)
    VALUES (r.tenant_id, r.account_id, r.de_id, r.objective_id, 'stage_changed',
            'Status ' || coalesce(v_before,'?') || ' → ' || (r.composed->>'to_status'),
            jsonb_build_object('from', v_before, 'to', r.composed->>'to_status')) RETURNING id INTO v_act;
  END IF;

  UPDATE account_writeback_requests
     SET status = 'applied', applied_at = now(), result = jsonb_build_object('activity_id', v_act)
   WHERE id = p_request_id;
  RETURN jsonb_build_object('ok', true, 'activity_id', v_act);
END; $function$;

CREATE OR REPLACE FUNCTION public.apply_config_template(p_tenant_id uuid, p_template_key text)
 RETURNS TABLE(type text, id uuid, name text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  PERFORM public._assert_caller_tenant(p_tenant_id);
  RETURN QUERY SELECT NULL::TEXT, NULL::UUID, NULL::TEXT WHERE FALSE;
END$function$;

CREATE OR REPLACE FUNCTION public.apply_continuity_writeback_internal(p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  r continuity_writeback_requests; c continuity_cases;
  v_before text; v_actor text; v_terminal boolean; v_category text;
BEGIN
  SELECT * INTO r FROM continuity_writeback_requests WHERE id = p_request_id;
  IF r.id IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'not_found'); END IF;
  IF r.status NOT IN ('pending_approval') THEN RETURN jsonb_build_object('ok', false, 'error', 'not_pending', 'status', r.status); END IF;
  SELECT * INTO c FROM continuity_cases WHERE objective_id = r.objective_id;
  IF c.objective_id IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'case_not_found'); END IF;
  v_actor := CASE WHEN r.de_id IS NOT NULL THEN 'de' ELSE 'human' END;

  IF r.op = 'log_activity' THEN
    INSERT INTO continuity_case_events (tenant_id, objective_id, motion, actor_kind, summary, detail)
    VALUES (r.tenant_id, r.objective_id, c.motion, v_actor, r.composed->>'summary',
            jsonb_build_object('activity_kind', r.composed->>'activity_kind'));

  ELSIF r.op = 'set_next_step' THEN
    UPDATE continuity_cases
       SET next_step = r.composed->>'next_step',
           next_step_date = nullif(r.composed->>'next_step_date','')::date,
           updated_at = now()
     WHERE objective_id = r.objective_id;
    INSERT INTO continuity_case_events (tenant_id, objective_id, motion, actor_kind, summary, detail)
    VALUES (r.tenant_id, r.objective_id, c.motion, v_actor, 'Next step: ' || (r.composed->>'next_step'), r.composed);

  ELSIF r.op = 'advance_stage' THEN
    v_before := c.stage_key;
    SELECT is_terminal, category INTO v_terminal, v_category
      FROM continuity_stage_config WHERE tenant_id = r.tenant_id AND stage_key = r.composed->>'to_stage';
    UPDATE continuity_cases
       SET stage_key = r.composed->>'to_stage',
           outcome = CASE WHEN coalesce(v_terminal,false) THEN v_category ELSE outcome END,
           updated_at = now()
     WHERE objective_id = r.objective_id;
    INSERT INTO continuity_case_events (tenant_id, objective_id, from_stage, to_stage, motion, actor_kind, summary, detail)
    VALUES (r.tenant_id, r.objective_id, v_before, r.composed->>'to_stage', c.motion, v_actor,
            'Stage ' || coalesce(v_before,'?') || ' → ' || (r.composed->>'to_stage'),
            jsonb_build_object('from', v_before, 'to', r.composed->>'to_stage', 'terminal', coalesce(v_terminal,false)));
  END IF;

  UPDATE continuity_writeback_requests SET status = 'applied', applied_at = now(), result = jsonb_build_object('op', r.op) WHERE id = p_request_id;
  RETURN jsonb_build_object('ok', true, 'op', r.op);
END; $function$;

CREATE OR REPLACE FUNCTION public.apply_entity_amendment(p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_am workforce_entity_amendments; v_cfg jsonb; begin
  select * into v_am from workforce_entity_amendments where id = p_id;
  if not found then raise exception 'amendment not found'; end if;
  if v_am.status = 'applied' then return jsonb_build_object('ok', true, 'already', true); end if;
  v_cfg := v_am.proposed_config;

  if v_am.entity_kind = 'de' then
    update digital_employees set
      persona_name = coalesce(v_cfg->>'persona_name', persona_name),
      description = coalesce(v_cfg->>'description', description),
      purpose_statement = coalesce(v_cfg->>'purpose_statement', purpose_statement)
    where id = v_am.entity_id and tenant_id = v_am.tenant_id;
  else
    -- specialist entities are digital_employees now; charter is jsonb {mission}
    update digital_employees
      set charter = jsonb_set(coalesce(charter, '{}'::jsonb), '{mission}', to_jsonb(coalesce(v_cfg->>'charter', charter->>'mission')))
      where id = v_am.entity_id and tenant_id = v_am.tenant_id;
  end if;

  update workforce_entity_amendments set status = 'applied' where id = p_id;
  begin perform append_audit_event(v_am.tenant_id, 'Practice Engine', 'de',
      format('%s amendment applied — improved config landed', v_am.entity_kind),
      'config_change', jsonb_build_object('kind','entity_amendment_applied','amendment_id',p_id,'entity_kind',v_am.entity_kind,'entity_id',v_am.entity_id));
  exception when others then null; end;
  return jsonb_build_object('ok', true, 'entity_id', v_am.entity_id);
end; $function$;

CREATE OR REPLACE FUNCTION public.apply_improvement(p_improvement_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare imp de_improvements; v_task_status text; v_doc uuid; v_arch text;
begin
  select * into imp from de_improvements where id = p_improvement_id for update;
  if imp.id is null then raise exception 'improvement not found'; end if;
  -- Prefix deleted. Reached only from trigger trg_sync_improvement on
  -- human_tasks, which fires under the deciding human's auth.uid().
  if not exists (
      select 1 from profiles p where p.user_id = auth.uid()
      and (p.layer = 'platform' or p.tenant_id = imp.tenant_id)) then
    raise exception 'not authorized';
  end if;
  -- DE scoping (mig 385/418). Before the already-applied early return, so a
  -- refused caller is not handed applied_doc_id. de_improvements.de_id is
  -- NOT NULL, so no null case. service_role still passes, by role name.
  if not public.can_access_de(imp.de_id) then
    raise exception 'not_responsible_for_de: this employee is not in your reporting line';
  end if;
  if imp.status = 'applied' then return imp.applied_doc_id; end if;
  if imp.status = 'rejected' then raise exception 'improvement was rejected'; end if;

  if imp.human_task_id is null then
    raise exception 'improvement has no review task — call create_improvement_review first';
  end if;
  select status into v_task_status from human_tasks where id = imp.human_task_id;
  if v_task_status is distinct from 'approved' then
    raise exception 'improvement is not human-approved (review task status: %) — a proposed fix can only be published after explicit approval', coalesce(v_task_status, 'missing');
  end if;

  -- T2.2: publish at role scope when the human chose it AND the DE's archetype
  -- resolves; otherwise the unchanged de-scoped path (today's behavior).
  v_arch := case when imp.publish_scope = 'role' then resolve_de_archetype(imp.de_id) end;
  if imp.publish_scope = 'role' and v_arch is not null then
    insert into knowledge_docs (tenant_id, title, content, source, visibility, is_current, tags, share_archetype_key)
    values (imp.tenant_id, imp.proposed_title, imp.proposed_content, 'self_improvement', 'role', true,
            array['self-improvement','team-learning'], v_arch)
    returning id into v_doc;
  else
    insert into knowledge_docs (tenant_id, title, content, source, visibility, is_current, tags)
    values (imp.tenant_id, imp.proposed_title, imp.proposed_content, 'self_improvement', 'scoped', true,
            array['self-improvement'])
    returning id into v_doc;
    insert into knowledge_doc_scopes (tenant_id, doc_id, subject_kind, subject_id)
    values (imp.tenant_id, v_doc, 'de', imp.de_id);
  end if;

  -- Chunk the published doc NOW, server-side (mig 481): this path fires from
  -- a trigger with no client to compensate, and nothing in the platform hunts
  -- for docs with zero chunks — unchunked here means keyword-only retrieval
  -- forever. Embeddings stay NULL; embed-backfill drains them within minutes.
  perform public.chunk_knowledge_doc_internal(v_doc);

  update de_improvements set status = 'applied', applied_doc_id = v_doc, updated_at = now()
   where id = p_improvement_id;

  insert into activity_events (tenant_id, actor, actor_type, event_type, text, confidence)
  select imp.tenant_id, coalesce(d.persona_name, d.name, 'DE'), 'system', 'config_change',
    format('Approved self-improvement published: "%s" (%s). Proposed from a failed answer, verified by replay, human-approved.',
           imp.proposed_title, case when imp.publish_scope = 'role' and v_arch is not null then 'shared with all '||v_arch||' employees' else 'scoped to '||coalesce(d.persona_name, d.name, 'this employee') end),
    coalesce((imp.replay->'after'->>'score')::numeric, 0)
  from digital_employees d where d.id = imp.de_id;

  return v_doc;
end;
$function$;

CREATE OR REPLACE FUNCTION public.apply_invoice_writeback_internal(p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r invoice_writeback_requests; v_before text; v_act uuid;
BEGIN
  SELECT * INTO r FROM invoice_writeback_requests WHERE id = p_request_id;
  IF r.id IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'not_found'); END IF;
  IF r.status NOT IN ('pending_approval') THEN RETURN jsonb_build_object('ok', false, 'error', 'not_pending', 'status', r.status); END IF;

  IF r.op = 'log_activity' THEN
    INSERT INTO invoice_activities (tenant_id, invoice_id, de_id, objective_id, kind, summary, detail)
    VALUES (r.tenant_id, r.invoice_id, r.de_id, r.objective_id, 'activity_logged', r.composed->>'summary',
            jsonb_build_object('activity_kind', r.composed->>'activity_kind')) RETURNING id INTO v_act;
  ELSIF r.op = 'set_next_step' THEN
    INSERT INTO invoice_activities (tenant_id, invoice_id, de_id, objective_id, kind, summary, detail)
    VALUES (r.tenant_id, r.invoice_id, r.de_id, r.objective_id, 'next_step_set',
            'Next step: ' || (r.composed->>'next_step'), r.composed) RETURNING id INTO v_act;
  ELSIF r.op = 'update_status' THEN
    SELECT status INTO v_before FROM renewal_invoices WHERE id = r.invoice_id AND tenant_id = r.tenant_id;
    UPDATE renewal_invoices SET status = r.composed->>'to_status', updated_at = now() WHERE id = r.invoice_id AND tenant_id = r.tenant_id;
    INSERT INTO invoice_activities (tenant_id, invoice_id, de_id, objective_id, kind, summary, detail)
    VALUES (r.tenant_id, r.invoice_id, r.de_id, r.objective_id, 'status_changed',
            'Status ' || coalesce(v_before,'?') || ' → ' || (r.composed->>'to_status'),
            jsonb_build_object('from', v_before, 'to', r.composed->>'to_status')) RETURNING id INTO v_act;
  END IF;

  UPDATE invoice_writeback_requests SET status = 'applied', applied_at = now(), result = jsonb_build_object('activity_id', v_act) WHERE id = p_request_id;
  RETURN jsonb_build_object('ok', true, 'activity_id', v_act);
END; $function$;

CREATE OR REPLACE FUNCTION public.apply_knowledge_revision(p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user          uuid := auth.uid();
  v_caller_tenant uuid;
  v_is_active     boolean;
  v_req           record;
  v_new_doc_id    uuid;
  v_actor_name    text;
  v_rep_inquiry   text;
  v_cluster       record;
begin
  select * into v_req from knowledge_revision_requests where id = p_request_id;
  if v_req.id is null then
    return jsonb_build_object('ok', false, 'error', 'request_not_found');
  end if;
  if v_req.status <> 'pending_approval' then
    return jsonb_build_object('ok', false, 'error', 'not_pending', 'status', v_req.status);
  end if;

  if v_user is not null then
    select tenant_id, coalesce(is_active, true) into v_caller_tenant, v_is_active from profiles where user_id = v_user;
    if v_caller_tenant is null or v_caller_tenant <> v_req.tenant_id then
      return jsonb_build_object('ok', false, 'error', 'not_tenant_member');
    end if;
    if not v_is_active then
      return jsonb_build_object('ok', false, 'error', 'not_tenant_member');
    end if;
  elsif coalesce(auth.role(), '') <> 'service_role' then
    return jsonb_build_object('ok', false, 'error', 'not_tenant_member');
  end if;

  select coalesce(full_name, 'A reviewer') into v_actor_name from profiles where user_id = v_user;
  v_actor_name := coalesce(v_actor_name, 'A reviewer');

  insert into knowledge_docs (
    tenant_id, title, content, source, tags, previous_version_id, is_current, visibility, lifecycle_status
  )
  select
    v_req.tenant_id, v_req.proposed_title, v_req.proposed_body_md, 'paste',
    coalesce((select tags from knowledge_docs where id = v_req.source_doc_id and tenant_id = v_req.tenant_id), '{}'),
    v_req.source_doc_id, true,
    coalesce((select visibility from knowledge_docs where id = v_req.source_doc_id and tenant_id = v_req.tenant_id), 'tenant'),
    -- 355: a revision of a draft stays a draft. Otherwise "propose an edit"
    -- becomes a way to publish without passing the publisher gate.
    coalesce((select lifecycle_status from knowledge_docs where id = v_req.source_doc_id and tenant_id = v_req.tenant_id), 'published')
  returning id into v_new_doc_id;

  -- Chunk server-side (mig 481): a service-role caller has no compensating
  -- client; the browser caller's follow-up ingest sees matching hash plus
  -- existing rows and no-ops straight into embedding.
  perform public.chunk_knowledge_doc_internal(v_new_doc_id);

  if v_req.source_doc_id is not null then
    update knowledge_docs set is_current = false where id = v_req.source_doc_id and tenant_id = v_req.tenant_id;
  end if;

  update knowledge_revision_requests
    set status = 'applied', decided_by = v_user, decided_at = now(), applied_doc_id = v_new_doc_id
    where id = p_request_id;

  perform append_audit_event(
    v_req.tenant_id, v_actor_name, case when v_user is null then 'system' else 'human' end,
    v_actor_name || ' approved and applied a knowledge revision — "' || v_req.proposed_title || '"',
    'knowledge_revision',
    jsonb_build_object('kind', 'knowledge_revision_applied', 'revision_request_id', p_request_id,
      'new_doc_id', v_new_doc_id, 'previous_doc_id', v_req.source_doc_id)
  );

  update knowledge_gap_clusters
  set status = 'resolved', fix_applied_at = now(), updated_at = now()
  where revision_request_id = p_request_id and status = 'revision_requested';

  -- Ledger-2B: seed the golden exam from the resolved gap — the cluster's
  -- representative question becomes an INACTIVE golden_qa row (founder
  -- reviews expected fragments and activates it). Dedup on exact question.
  select c.*, er.inquiry into v_cluster
  from knowledge_gap_clusters c
  left join evidence_runs er on er.id = c.representative_run_id
  where c.revision_request_id = p_request_id
  limit 1;
  v_rep_inquiry := v_cluster.inquiry;
  if v_rep_inquiry is not null and length(btrim(v_rep_inquiry)) >= 8 then
    insert into golden_qa (tenant_id, question, expected_fragments, min_confidence, category, active)
    select v_req.tenant_id, btrim(v_rep_inquiry), ARRAY[v_req.proposed_title], 60,
           coalesce(v_cluster.category, 'support'), false
    where not exists (
      select 1 from golden_qa g
      where g.tenant_id = v_req.tenant_id and g.question = btrim(v_rep_inquiry)
    );
  end if;

  return jsonb_build_object('ok', true, 'new_doc_id', v_new_doc_id, 'previous_doc_id', v_req.source_doc_id);
end $function$;

CREATE OR REPLACE FUNCTION public.apply_onboarding_verification(p_project_id uuid, p_key text, p_verified boolean, p_detail text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_proj      onboarding_projects;
  v_ver       onboarding_template_versions;
  v_def       jsonb;
  v_item      jsonb;
  v_idx       integer := -1;
  v_i         integer := 0;
  v_old       text;
  v_task_id   uuid;
  v_acct_name text;
  v_completed boolean := false;
  v_signoff   boolean;
begin
  select * into v_proj from onboarding_projects where id = p_project_id;
  -- Mig 547: onboarding-verify's check_due sweep loops EVERY active project
  -- across ALL tenants with no suspension filter, so this is the only place
  -- the check can live. A dormant workspace gains no verification tasks.
  if v_proj.id is not null and not tenant_is_operational(v_proj.tenant_id) then
    return jsonb_build_object('ok', false, 'skipped', 'tenant_suspended');
  end if;
  if not found then return jsonb_build_object('error', 'project_not_found'); end if;
  if v_proj.status <> 'active' then return jsonb_build_object('error', 'project_not_active'); end if;

  select * into v_ver from onboarding_template_versions where id = v_proj.template_version_id;
  select d into v_def from jsonb_array_elements(v_ver.items) d where d->>'key' = p_key limit 1;
  if v_def is null or v_def->'verify' is null then
    return jsonb_build_object('error', 'item_not_verifiable');
  end if;
  v_signoff := coalesce((v_def->>'requires_signoff')::boolean, false);

  for v_item in select * from jsonb_array_elements(v_proj.items_state) loop
    if v_item->>'key' = p_key then v_idx := v_i; exit; end if;
    v_i := v_i + 1;
  end loop;
  if v_idx < 0 then return jsonb_build_object('error', 'item_state_missing'); end if;
  v_old := v_item->>'status';

  if v_old in ('done', 'signed_off') then
    -- Already complete (by whatever means) — record the check for the
    -- audit trail but don't re-run completion side effects.
    v_item := v_item || jsonb_build_object(
      'last_check_at', now(), 'last_check_result', case when p_verified then 'verified' else 'not_yet' end,
      'verify_detail', left(coalesce(p_detail, ''), 300));
    update onboarding_projects set items_state = jsonb_set(items_state, array[v_idx::text], v_item) where id = p_project_id;
    return jsonb_build_object('project_id', p_project_id, 'item_key', p_key, 'changed', false, 'already_complete', true);
  end if;

  if not p_verified then
    v_item := v_item || jsonb_build_object(
      'last_check_at', now(), 'last_check_result', 'not_yet',
      'verify_detail', left(coalesce(p_detail, ''), 300));
    update onboarding_projects set items_state = jsonb_set(items_state, array[v_idx::text], v_item) where id = p_project_id;
    return jsonb_build_object('project_id', p_project_id, 'item_key', p_key, 'changed', false, 'verified', false);
  end if;

  -- Verified true: same completion shape as update_onboarding_item's
  -- done path, attributed to System rather than a human.
  v_item := v_item || jsonb_build_object(
    'status', 'done', 'done_at', now(),
    'verified_by', 'system', 'verified_at', now(),
    'last_check_at', now(), 'last_check_result', 'verified',
    'verify_detail', left(coalesce(p_detail, ''), 300));

  if v_signoff then
    insert into human_tasks (tenant_id, type, title, detail, source, related_table, related_id)
    values (v_proj.tenant_id, 'review_gate',
            format('Onboarding sign-off — %s · %s', v_def->>'label', v_proj.name),
            format('Item "%s" was CONNECTOR-VERIFIED (%s) and needs a human sign-off before the project can complete.', v_def->>'label', left(coalesce(p_detail, ''), 200)),
            'system', 'onboarding_projects', p_project_id)
    returning id into v_task_id;
    v_item := v_item || jsonb_build_object('signoff_task_id', v_task_id);
  end if;

  select name into v_acct_name from customer_accounts where id = v_proj.account_id;
  insert into activity_events (tenant_id, account_id, actor, actor_type, event_type, text)
  values (v_proj.tenant_id, v_proj.account_id, 'System', 'system', 'resolved',
          format('Onboarding — %s: connector-verified done%s (%s) — %s', v_def->>'label',
                 case when v_task_id is not null then ' · awaiting sign-off' else '' end,
                 coalesce(v_acct_name, v_proj.name), left(coalesce(p_detail, ''), 160)));

  perform append_audit_event_internal(
    v_proj.tenant_id, 'System', 'system',
    format('Onboarding item connector-verified — %s (%s): %s', v_def->>'label', v_proj.name, left(coalesce(p_detail, ''), 200)),
    'config_change',
    jsonb_build_object('kind', 'onboarding_verify', 'project_id', p_project_id, 'item_key', p_key,
                       'detail', p_detail, 'signoff_task_id', v_task_id));

  update onboarding_projects
    set items_state = jsonb_set(items_state, array[v_idx::text], v_item)
    where id = p_project_id;

  if not v_signoff then
    v_completed := onboarding_check_complete(p_project_id);
  end if;

  return jsonb_build_object('project_id', p_project_id, 'item_key', p_key, 'changed', true,
                            'verified', true, 'signoff_task_id', v_task_id, 'completed', v_completed);
end;
$function$;

CREATE OR REPLACE FUNCTION public.apply_opportunity_writeback_internal(p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r opportunity_writeback_requests; v_before text; v_act uuid;
BEGIN
  SELECT * INTO r FROM opportunity_writeback_requests WHERE id = p_request_id;
  IF r.id IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'not_found'); END IF;
  IF r.status NOT IN ('pending_approval') THEN RETURN jsonb_build_object('ok', false, 'error', 'not_pending', 'status', r.status); END IF;

  IF r.op = 'log_activity' THEN
    INSERT INTO opportunity_activities (tenant_id, opportunity_id, de_id, objective_id, kind, summary, detail)
    VALUES (r.tenant_id, r.opportunity_id, r.de_id, r.objective_id, 'activity_logged', r.composed->>'summary',
            jsonb_build_object('activity_kind', r.composed->>'activity_kind')) RETURNING id INTO v_act;
  ELSIF r.op = 'set_next_step' THEN
    INSERT INTO opportunity_activities (tenant_id, opportunity_id, de_id, objective_id, kind, summary, detail)
    VALUES (r.tenant_id, r.opportunity_id, r.de_id, r.objective_id, 'next_step_set',
            'Next step: ' || (r.composed->>'next_step'), r.composed) RETURNING id INTO v_act;
  ELSIF r.op = 'update_stage' THEN
    SELECT stage INTO v_before FROM opportunities WHERE id = r.opportunity_id AND tenant_id = r.tenant_id;
    UPDATE opportunities SET stage = r.composed->>'to_stage', updated_at = now(),
           stage_history = coalesce(stage_history,'[]'::jsonb) || jsonb_build_object('from', v_before, 'to', r.composed->>'to_stage', 'at', now())
     WHERE id = r.opportunity_id AND tenant_id = r.tenant_id;
    INSERT INTO opportunity_activities (tenant_id, opportunity_id, de_id, objective_id, kind, summary, detail)
    VALUES (r.tenant_id, r.opportunity_id, r.de_id, r.objective_id, 'stage_changed',
            'Stage ' || coalesce(v_before,'?') || ' → ' || (r.composed->>'to_stage'),
            jsonb_build_object('from', v_before, 'to', r.composed->>'to_stage')) RETURNING id INTO v_act;
  END IF;

  UPDATE opportunity_writeback_requests SET status = 'applied', applied_at = now(), result = jsonb_build_object('activity_id', v_act) WHERE id = p_request_id;
  RETURN jsonb_build_object('ok', true, 'activity_id', v_act);
END; $function$;

CREATE OR REPLACE FUNCTION public.apply_playbook_amendment(p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_am playbook_amendments; begin IF NOT coalesce(public.can_admin_tenant_internal((SELECT tenant_id FROM public.playbook_amendments WHERE id = p_id)), false) THEN RAISE EXCEPTION 'not permitted'; END IF;
  select * into v_am from playbook_amendments where id = p_id;
  if not found then raise exception 'amendment not found'; end if;
  if v_am.status = 'applied' then return jsonb_build_object('ok', true, 'already', true); end if;
  update playbook_definitions set steps = v_am.proposed_steps, status = 'draft'
    where id = v_am.definition_id and tenant_id = v_am.tenant_id;
  update playbook_amendments set status = 'applied' where id = p_id;
  begin
    perform append_audit_event(v_am.tenant_id, 'Practice Engine', 'de',
      'Playbook amendment applied to draft — ready to review & publish', 'config_change',
      jsonb_build_object('kind','playbook_amendment_applied','amendment_id',p_id,'definition_id',v_am.definition_id));
  exception when others then null;
  end;
  return jsonb_build_object('ok', true, 'definition_id', v_am.definition_id);
end; $function$;

CREATE OR REPLACE FUNCTION public.apply_role_kit_to_employee(p_de_id uuid, p_archetype_key text, p_allow_rerole boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tenant  uuid;
  v_name    text;
  v_current text;
  v_arch    role_archetypes;
  v_kit     jsonb;
  v_systems int := 0;
begin
  select d.tenant_id, coalesce(nullif(d.persona_name, ''), d.name), d.archetype_key
    into v_tenant, v_name, v_current
    from digital_employees d
   where d.id = p_de_id and d.lifecycle_status <> 'retired';
  if v_tenant is null then
    raise exception 'employee not found, or retired';
  end if;

  -- A human action, so a real signed-in person is required — never the
  -- anonymous or service path.
  if auth.uid() is null then raise exception 'not_authenticated'; end if;
  if not exists (
      select 1 from profiles p
       where p.user_id = auth.uid()
         and (p.layer = 'platform'
              or (p.tenant_id = v_tenant
                  and p.role in ('tenant_owner', 'tenant_admin', 'tenant_manager')))) then
    raise exception 'not authorized to configure this employee';
  end if;

  -- A dormant workspace does not get new work-generating configuration.
  if not public.tenant_is_operational(v_tenant) then
    raise exception 'this workspace is suspended';
  end if;

  select * into v_arch from role_archetypes
   where key = p_archetype_key and status = 'active';
  if v_arch.key is null then raise exception 'unknown role template %', p_archetype_key; end if;

  if v_current is not null and v_current <> p_archetype_key and not coalesce(p_allow_rerole, false) then
    raise exception 'already_has_role: this employee is a % — re-roling changes what it watches and what it may do, so it must be confirmed', v_current;
  end if;

  -- Watchers + SOP + role guardrails (mig 552 made every template installable).
  v_kit := public.install_role_kit(p_de_id, p_archetype_key);

  -- Connected systems are additive; a failure here never costs the kit, which
  -- is how the hire path treats it too.
  begin
    v_systems := coalesce(public.install_role_systems(p_de_id, p_archetype_key), 0);
  exception when others then
    v_systems := 0;
  end;

  -- Record the role on the employee so role-scoped features (team missions,
  -- role-scoped improvements, the right certification exam) resolve.
  update digital_employees
     set archetype_key = p_archetype_key, updated_at = now()
   where id = p_de_id and archetype_key is distinct from p_archetype_key;

  perform append_audit_event(
    v_tenant, 'You', 'human',
    format('Applied the %s role template to %s — %s watcher(s), %s role guardrail(s), %s connected system(s)%s',
      v_arch.name, v_name,
      coalesce(v_kit->>'watchers_created', '0'),
      coalesce(v_kit->>'guardrails_created', '0'), v_systems,
      case when coalesce((v_kit->>'watchers_skipped')::int, 0) > 0
           then format(', %s watcher template(s) skipped', v_kit->>'watchers_skipped') else '' end),
    'config_change',
    jsonb_build_object('kind', 'role_kit_applied', 'de_id', p_de_id,
      'archetype_key', p_archetype_key, 'previous_archetype', v_current,
      'rerole', (v_current is not null and v_current <> p_archetype_key),
      'kit', v_kit, 'systems_installed', v_systems));

  return v_kit || jsonb_build_object(
    'systems_installed', v_systems,
    'previous_archetype', v_current,
    'archetype_name', v_arch.name,
    'employee', v_name);
end $function$;

CREATE OR REPLACE FUNCTION public.apply_trust_promotion(p_task_id uuid, p_decision text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_policy    trust_policies;
  v_evidence  jsonb;
  v_new       integer;
  v_label     text;
  v_is_active boolean;
begin
  if p_decision not in ('approved', 'rejected') then
    raise exception 'decision must be approved or rejected';
  end if;

  select * into v_policy from trust_policies where pending_task_id = p_task_id;
  if not found then
    return jsonb_build_object('applied', false, 'reason', 'no_pending_policy');
  end if;

  if coalesce(auth.role(), '') <> 'service_role' then
    select coalesce(is_active, true) into v_is_active from profiles where user_id = auth.uid() and tenant_id = v_policy.tenant_id;
    if v_is_active is null or not v_is_active then
      raise exception 'not a member of this tenant';
    end if;
  end if;

  v_label := replace(v_policy.action_category, '_', ' ');

  if p_decision = 'rejected' then
    update trust_policies
    set pending_task_id = null, pending_evidence = null, requested_by = null, requested_at = null
    where id = v_policy.id;
    perform append_audit_event(
      v_policy.tenant_id, 'You', 'human',
      format('Trust promotion rejected — %s stays at level %s', v_label, v_policy.current_level),
      'config_change',
      jsonb_build_object('kind', 'trust_promotion_rejected', 'policy_id', v_policy.id,
        'action_category', v_policy.action_category, 'level', v_policy.current_level,
        'task_id', p_task_id, 'decided_by', auth.uid())
    );
    return jsonb_build_object('applied', false, 'reason', 'rejected');
  end if;

  -- Self-approval block: the requester cannot approve their own promotion.
  if v_policy.requested_by is not null and auth.uid() = v_policy.requested_by then
    perform append_audit_event(
      v_policy.tenant_id, 'Trust engine', 'system',
      format('Trust promotion blocked — requester cannot approve their own request (%s)', v_label),
      'config_change',
      jsonb_build_object('kind', 'trust_promotion_blocked_self_approval', 'policy_id', v_policy.id,
        'action_category', v_policy.action_category, 'task_id', p_task_id, 'user_id', auth.uid())
    );
    raise exception 'the requester cannot approve their own promotion — a different teammate must approve';
  end if;

  -- Stale-check: evidence could have regressed since the request.
  v_evidence := trust_evidence_for(v_policy);
  if not coalesce((v_evidence->>'eligible')::boolean, false) then
    update trust_policies
    set pending_task_id = null, pending_evidence = null, requested_by = null, requested_at = null
    where id = v_policy.id;
    perform append_audit_event(
      v_policy.tenant_id, 'Trust engine', 'system',
      format('Trust promotion rejected as stale — %s evidence regressed since the request', v_label),
      'config_change',
      jsonb_build_object('kind', 'trust_promotion_stale', 'policy_id', v_policy.id,
        'action_category', v_policy.action_category, 'task_id', p_task_id,
        'evidence_at_request', v_policy.pending_evidence, 'evidence_at_apply', v_evidence)
    );
    raise exception 'evidence regressed since the request — promotion rejected as stale';
  end if;

  v_new := least(v_policy.current_level + 1, v_policy.max_level);
  -- GI-3: scope the dial write to THIS employee (v_policy.de_id) — a NULL de_id
  -- keeps the historical tenant-wide behavior for tenant-scoped policies.
  perform trust_apply_level(v_policy.tenant_id, v_policy.action_category, v_new, auth.uid(), v_policy.source_category, v_policy.de_id);

  update trust_policies
  set current_level = v_new,
      pending_task_id = null, pending_evidence = null, requested_by = null, requested_at = null
  where id = v_policy.id;

  perform append_audit_event(
    v_policy.tenant_id, 'You', 'human',
    format('Trust promoted — %s level %s → %s (evidence re-verified at apply time; still capped by guardrails)',
      v_label, v_policy.current_level, v_new),
    'config_change',
    jsonb_build_object('kind', 'trust_promoted', 'policy_id', v_policy.id,
      'action_category', v_policy.action_category, 'de_id', v_policy.de_id,
      'from_level', v_policy.current_level,
      'to_level', v_new, 'task_id', p_task_id, 'approved_by', auth.uid(),
      'requested_by', v_policy.requested_by, 'evidence', v_evidence,
      'dial_settings', trust_ladder_settings(v_policy, v_new),
      'composition', 'autonomy_narrows_within_guardrails')
  );

  return jsonb_build_object('applied', true, 'new_level', v_new);
end;
$function$;

CREATE OR REPLACE FUNCTION public.approval_brief_on_new_task()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  b jsonb;
begin
  b := public.compute_approval_brief(new.id);
  if b is not null then
    insert into approval_briefs (task_id, tenant_id, risk, headline, evidence, computed_at, task_changed_at)
    values (new.id, new.tenant_id, b->>'risk', b->>'headline',
            coalesce(b->'evidence', '[]'::jsonb), now(), new.updated_at)
    on conflict (task_id) do update
      set risk = excluded.risk,
          headline = excluded.headline,
          evidence = excluded.evidence,
          computed_at = excluded.computed_at,
          task_changed_at = excluded.task_changed_at;
  end if;
  return null;
exception when others then
  -- The brief is an overlay. Losing it must never roll back the approval
  -- request itself.
  return null;
end $function$;

CREATE OR REPLACE FUNCTION public.approve_draft(p_draft_id uuid, p_edited_content text DEFAULT NULL::text, p_notes text DEFAULT NULL::text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id UUID;
  v_de_id UUID;
  v_before TEXT;
  v_tenant UUID;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;
  v_tenant := public.auth_tenant_id();
  IF v_tenant IS NULL THEN
    RAISE EXCEPTION 'no_workspace: this account is not attached to a workspace';
  END IF;

  -- DE scoping (mig 385/403). Resolve the row FIRST, on exactly the same
  -- terms the UPDATE below uses, then refuse. draft_responses.de_id is NOT
  -- NULL, so a null here means no such draft in this workspace.
  SELECT de_id, draft_content INTO v_de_id, v_before
    FROM draft_responses
   WHERE draft_id = p_draft_id AND tenant_id = v_tenant;

  IF v_de_id IS NULL THEN
    RAISE EXCEPTION 'draft_not_found: no such draft in this workspace';
  END IF;
  IF NOT public.can_access_de(v_de_id) THEN
    RAISE EXCEPTION 'not_responsible_for_de: this employee is not in your reporting line';
  END IF;

  UPDATE draft_responses
     SET status = 'approved',
         draft_content = COALESCE(p_edited_content, draft_content),
         edited_content = p_edited_content,
         approved_at = now(),
         approved_by = v_user_id
   WHERE draft_id = p_draft_id AND tenant_id = v_tenant;

  -- Training pair (mig 457). Only when the approver actually changed
  -- something; an unedited approval is not an edit. Written AFTER the
  -- update so a failed approval leaves no learning row claiming otherwise.
  IF p_edited_content IS NOT NULL
     AND btrim(p_edited_content) <> btrim(coalesce(v_before, '')) THEN
    INSERT INTO de_learning_edits (tenant_id, de_id, source_kind, source_id,
                                   before_text, after_text, note, edited_by)
    VALUES (v_tenant, v_de_id, 'draft_response', p_draft_id, v_before,
            p_edited_content, nullif(btrim(coalesce(p_notes, '')), ''), v_user_id);
  END IF;

  RETURN json_build_object('ok', true);
END;
$function$;

CREATE OR REPLACE FUNCTION public.approve_draft_reply(p_message_id uuid, p_edited_content text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_tenant uuid; v_conv uuid; v_de uuid; v_before text;
begin
  if auth.uid() is null then raise exception 'not authenticated'; end if;
  select tenant_id, conversation_id, content into v_tenant, v_conv, v_before
  from de_messages where id = p_message_id and delivery = 'draft_pending';
  if v_tenant is null then raise exception 'not_a_pending_draft'; end if;
  if not (is_platform_admin() or exists (select 1 from profiles p where p.user_id = auth.uid() and p.tenant_id = v_tenant)) then
    raise exception 'not authorized for this workspace';
  end if;
  -- DE scoping (mig 385/404). The employee lives on the CONVERSATION —
  -- de_messages has no de_id. Null-tolerant to match the mig-386 policy:
  -- an unattributed conversation is actionable by anyone in the workspace,
  -- exactly as it is readable by them.
  select de_id into v_de from de_conversations where id = v_conv;
  if v_de is not null and not public.can_access_de(v_de) then
    raise exception 'not_responsible_for_de: this employee is not in your reporting line';
  end if;

  update de_messages
    set delivery = 'sent', escalated = false,
        content = coalesce(nullif(trim(p_edited_content), ''), content)
  where id = p_message_id;
  update de_conversations set owner_user_id = coalesce(owner_user_id, auth.uid()), status = 'human_owned', last_message_at = now()
  where id = v_conv;

  -- Training pair (mig 457). de_messages.content IS the delivered message,
  -- so the overwrite above is correct and unavoidable — this is the only
  -- place the original survives.
  if nullif(trim(p_edited_content), '') is not null
     and btrim(p_edited_content) <> btrim(coalesce(v_before, '')) then
    insert into de_learning_edits (tenant_id, de_id, source_kind, source_id,
                                   before_text, after_text, edited_by)
    values (v_tenant, v_de, 'de_message', p_message_id,
            v_before, p_edited_content, auth.uid());
  end if;
end;
$function$;

CREATE OR REPLACE FUNCTION public.approve_learned_behavior(p_cluster_id uuid, p_final_pattern text DEFAULT NULL::text, p_final_threshold bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user          uuid := auth.uid();
  v_caller_tenant uuid;
  v_is_active     boolean;
  v_cluster       record;
  v_rule_id       uuid;
  v_pattern       text;
begin
  perform set_config('app.allow_task_decision', 'on', true);   -- mig 486: sanctioned decision path
  select * into v_cluster from de_learned_behavior_clusters where id = p_cluster_id;
  if v_cluster.id is null or v_cluster.status <> 'proposed' then
    return jsonb_build_object('ok', false, 'error', 'not_proposed');
  end if;

  select tenant_id, coalesce(is_active, true) into v_caller_tenant, v_is_active from profiles where user_id = v_user;
  if v_caller_tenant is distinct from v_cluster.tenant_id then
    return jsonb_build_object('ok', false, 'error', 'not_tenant_member');
  end if;
  if not v_is_active then
    return jsonb_build_object('ok', false, 'error', 'not_tenant_member');
  end if;

  -- DE scoping (mig 385/416). The cluster belongs to one employee and
  -- de_learned_behavior_clusters.de_id is NOT NULL, so no null case.
  -- NOTE the resulting guardrail rule is WORKSPACE-scoped by default; this
  -- guard bounds who may approve, not how far the rule reaches. See header.
  if not public.can_access_de(v_cluster.de_id) then
    return jsonb_build_object('ok', false, 'error', 'not_responsible_for_de');
  end if;
  if v_cluster.verdict_type = 'correction' then
    v_pattern := coalesce(p_final_pattern, v_cluster.proposed_rule->>'suggested_pattern');
    if coalesce(btrim(v_pattern), '') = '' then
      return jsonb_build_object('ok', false, 'error', 'pattern_required');
    end if;
    insert into guardrail_rules (tenant_id, rule, rule_type, pattern, severity, active, created_by)
    values (
      v_cluster.tenant_id,
      format('Learned behavior — %s', left(v_pattern, 60)),
      coalesce(v_cluster.proposed_rule->>'rule_type', 'blocked_phrase'),
      v_pattern, 'warning', true, v_user
    )
    returning id into v_rule_id;
  else
    v_rule_id := v_cluster.guardrail_rule_id;
    if v_rule_id is null then
      return jsonb_build_object('ok', false, 'error', 'no_target_rule');
    end if;
    if p_final_threshold is not null then
      update guardrail_rules set threshold = p_final_threshold, updated_at = now() where id = v_rule_id and tenant_id = v_cluster.tenant_id;
    elsif p_final_pattern is not null then
      update guardrail_rules set pattern = p_final_pattern, updated_at = now() where id = v_rule_id and tenant_id = v_cluster.tenant_id;
    else
      -- No override given: the evidence says this rule is too strict for
      -- this whole pattern — the honest default is to deactivate it
      -- rather than silently leave it exactly as-is (which would make
      -- "approve" a no-op).
      update guardrail_rules set active = false, updated_at = now() where id = v_rule_id and tenant_id = v_cluster.tenant_id;
    end if;
  end if;

  update de_learned_behavior_clusters
  set status = 'resolved', fix_applied_at = now(), resulting_guardrail_rule_id = v_rule_id, updated_at = now()
  where id = p_cluster_id;

  if v_cluster.human_task_id is not null then
    update human_tasks set status = 'approved', decided_by = v_user, decided_at = now() where id = v_cluster.human_task_id;
  end if;

  perform append_audit_event(
    v_cluster.tenant_id, coalesce((select full_name from profiles where user_id = v_user), 'A reviewer'), 'human',
    format('Approved a learned behavior (%s) — %s guardrail rule %s', v_cluster.verdict_type,
      case when v_cluster.verdict_type = 'correction' then 'created' else 'updated' end, v_rule_id),
    'config_change',
    jsonb_build_object('kind', 'learned_behavior_approved', 'cluster_id', p_cluster_id, 'guardrail_rule_id', v_rule_id)
  );

  return jsonb_build_object('ok', true, 'guardrail_rule_id', v_rule_id);
end;
$function$;

CREATE OR REPLACE FUNCTION public.approve_subtenant_request(p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_req      tenant_provisioning_requests;
  v_slug     text;
  v_base_slug text;
  v_suffix   int := 0;
  v_tenant   tenants;
  v_requester_tenant uuid;
begin
  if not resolve_platform_capability(auth.uid(), 'tenants.manage') then
    raise exception 'only a platform team member with tenant management access may approve a tenant provisioning request';
  end if;

  select * into v_req from tenant_provisioning_requests where id = p_request_id for update;
  if not found then
    raise exception 'provisioning request not found';
  end if;
  if v_req.status <> 'pending' then
    raise exception 'this request has already been decided (status=%)', v_req.status;
  end if;

  v_base_slug := lower(regexp_replace(btrim(v_req.proposed_name), '[^a-zA-Z0-9]+', '-', 'g'));
  v_base_slug := trim(both '-' from v_base_slug);
  if coalesce(v_base_slug, '') = '' then
    v_base_slug := 'org';
  end if;
  v_slug := v_base_slug;
  while exists (select 1 from tenants where slug = v_slug) loop
    v_suffix := v_suffix + 1;
    v_slug := v_base_slug || '-' || v_suffix::text;
  end loop;

  insert into tenants (name, slug, industry, plan, status, settings, parent_tenant_id)
  values (v_req.proposed_name, v_slug, nullif(btrim(coalesce(v_req.proposed_industry, '')), ''), 'starter', 'trial', '{}'::jsonb, v_req.proposed_parent_tenant_id)
  returning * into v_tenant;

  update tenant_provisioning_requests
  set status = 'approved', reviewed_by = auth.uid(), decided_at = now(), created_tenant_id = v_tenant.id
  where id = p_request_id;

  select tenant_id into v_requester_tenant from profiles where user_id = v_req.requested_by_user_id;
  if v_requester_tenant is null then
    update profiles
    set tenant_id = v_tenant.id, role = 'tenant_owner', updated_at = now()
    where user_id = v_req.requested_by_user_id and tenant_id is null;
  end if;

  -- Console-approved tenants previously got NO provisioning at all —
  -- no starter DEs, no playbooks, nothing. Run the same baseline
  -- contract the self-serve signup path runs.
  perform provision_tenant_baseline_internal(v_tenant.id);

  if v_req.proposed_parent_tenant_id is not null and exists (
    select 1 from profiles where user_id = auth.uid() and tenant_id = v_req.proposed_parent_tenant_id
  ) then
    perform append_audit_event(
      v_req.proposed_parent_tenant_id, 'Platform admin', 'human',
      format('Sub-tenant "%s" approved and created (request %s, new tenant id %s)', v_tenant.name, p_request_id, v_tenant.id),
      'config_change',
      jsonb_build_object('kind', 'tenant_provisioning_approved', 'request_id', p_request_id,
        'tenant_id', v_tenant.id, 'parent_tenant_id', v_req.proposed_parent_tenant_id,
        'approved_by', auth.uid(), 'requested_by', v_req.requested_by_user_id)
    );
  end if;

  return jsonb_build_object('ok', true, 'tenant_id', v_tenant.id, 'slug', v_tenant.slug);
end;
$function$;

CREATE OR REPLACE FUNCTION public.archive_knowledge_collection(p_id uuid, p_archived boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tenant uuid := auth_tenant_id(); v_docs int; v_children int;
BEGIN
  IF v_tenant IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  IF NOT EXISTS (SELECT 1 FROM knowledge_collections WHERE id = p_id AND tenant_id = v_tenant) THEN
    RAISE EXCEPTION 'not_found';
  END IF;
  IF knowledge_my_admin_level(p_id) < 5 AND NOT is_platform_admin() THEN
    RAISE EXCEPTION 'insufficient_permission: archiving requires knowledge manager';
  END IF;

  SELECT count(DISTINCT doc_id) INTO v_docs FROM knowledge_doc_access_paths WHERE collection_id = p_id;
  SELECT count(*) INTO v_children FROM knowledge_collections WHERE parent_id = p_id AND archived_at IS NULL;

  UPDATE knowledge_collections
     SET archived_at = CASE WHEN p_archived THEN now() ELSE NULL END, updated_at = now()
   WHERE id = p_id;

  -- The documents are untouched — say so, because "archive" reads as "delete"
  -- to most people and this one genuinely is not.
  RETURN jsonb_build_object('ok', true, 'archived', p_archived,
                            'documents_kept', v_docs, 'child_collections', v_children);
END $function$;

CREATE OR REPLACE FUNCTION public.archive_workforce_team(p_team_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tenant uuid;
  v_team workforce_teams;
  v_actor text;
begin
  v_tenant := auth_tenant_id();
  if v_tenant is null then raise exception 'not a member of any tenant'; end if;
  if not auth_has_tenant_role(array['tenant_owner', 'tenant_admin']) then
    raise exception 'only workspace owners/admins can manage workforce teams';
  end if;
  update workforce_teams set status = 'archived', updated_at = now()
  where id = p_team_id and tenant_id = v_tenant
  returning * into v_team;
  if v_team.id is null then raise exception 'team not found in this workspace'; end if;

  select full_name into v_actor from profiles where user_id = auth.uid();
  perform append_audit_event_internal(
    v_tenant, coalesce(v_actor, 'A workspace admin'), 'human',
    format('Workforce team "%s" archived — its fallback chain no longer applies', v_team.name),
    'config_change',
    jsonb_build_object('kind', 'workforce_team_archived', 'team_id', p_team_id)
  );
  return jsonb_build_object('ok', true);
end;
$function$;

CREATE OR REPLACE FUNCTION public.assert_kpi_metric_known()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM kpi_metric_catalog c
     WHERE c.metric_key = NEW.metric_key
       AND (c.tenant_id IS NULL OR c.tenant_id = NEW.tenant_id)
  ) THEN
    RAISE EXCEPTION 'unknown_metric_key: % — add it to your KPI catalog first', NEW.metric_key;
  END IF;
  RETURN NEW;
END$function$;

CREATE OR REPLACE FUNCTION public.assert_org_unit_same_tenant()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_unit_tenant uuid;
begin
  if new.org_unit_id is null then
    return new;
  end if;

  select u.tenant_id into v_unit_tenant from org_units u where u.id = new.org_unit_id;
  if v_unit_tenant is null then
    raise exception 'org unit % does not exist', new.org_unit_id;
  end if;

  if v_unit_tenant is distinct from new.tenant_id then
    raise exception
      'cross-tenant placement refused: % belongs to workspace %, but org unit % belongs to workspace %',
      tg_table_name, new.tenant_id, new.org_unit_id, v_unit_tenant
      using errcode = 'raise_exception';
  end if;

  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.assert_own_tenant(p_tenant_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_mine uuid := auth_tenant_id();
begin
  if v_mine is not null and p_tenant_id is distinct from v_mine then
    raise exception 'that workspace is not yours';
  end if;
  return p_tenant_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.assess_de_skills_internal(p_tenant_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_de record;
  v_updated integer := 0;
  -- signal scratch
  v_dec_total integer; v_dec_escalated integer; v_dec_conf numeric;
  v_run_total integer; v_run_blocked integer; v_run_answered integer;
  v_csat_total integer; v_csat_pos integer;
  v_act_total integer; v_act_ok integer;
  -- per-skill result
  v_prof integer; v_prev integer; v_sample integer; v_value numeric; v_detail text;
  v_weak text[];
  v_weak_names text;
begin
  for v_de in
    select id, tenant_id, name from digital_employees
    where lifecycle_status not in ('retired', 'archived')
      and (p_tenant_id is null or tenant_id = p_tenant_id)
      and tenant_is_operational(tenant_id)
  loop
    v_weak := '{}';

    -- ── raw signals, all windowed to the last 30 days ──
    -- mig 707: A CERTIFICATION EXAM IS NOT A SKILL RECORD (the 571 rule,
    -- ported to this organ's read). Exams run the live pipeline on purpose,
    -- so their decisions land here indistinguishable from customer work —
    -- counting them scored Technical Support "level 1, escalated 97.5% of 81"
    -- when 75 of the 81 were exam answers, and that score fed the development
    -- program. The origin stamp (682) is written at the boundary and
    -- backfilled; unknown origin defaults to production, so real work is
    -- never silently erased.
    select count(*), count(*) filter (where d.decision = 'needs_review'),
           round(avg(d.confidence) filter (where d.confidence is not null), 1)
      into v_dec_total, v_dec_escalated, v_dec_conf
    from evidence_run_decisions d
    join evidence_runs er on er.id = d.evidence_run_id
    where er.tenant_id = v_de.tenant_id and er.de_id = v_de.id
      and public.evidence_is_production(er.origin)
      and d.created_at > now() - interval '30 days';

    -- Domain grounding measures GENUINE answer attempts only: a run
    -- that never reached the model (llm_not_configured — no key/budget,
    -- an infrastructure state, not a knowledge signal) or was withheld
    -- by a guardrail (blocked — a policy signal, not knowledge) does not
    -- count for or against the DE's domain knowledge. Denominator =
    -- answered + error (the DE tried); numerator = answered.
    -- mig 707: and an exam attempt is the EXAM's evidence, not this organ's.
    select count(*) filter (where answer_status in ('answered', 'error')),
           count(*) filter (where answer_status = 'blocked'),
           count(*) filter (where answer_status = 'answered')
      into v_run_total, v_run_blocked, v_run_answered
    from evidence_runs
    where tenant_id = v_de.tenant_id and de_id = v_de.id
      and public.evidence_is_production(origin)
      and created_at > now() - interval '30 days';

    -- mig 707: exam-channel threads carry no customer to rate them — 0 such
    -- rows exist (verified live) — but the axis is excluded on principle so
    -- this read can never regress into the class.
    select count(*) filter (where csat_submitted_at is not null),
           count(*) filter (where csat_score = 1)
      into v_csat_total, v_csat_pos
    from de_conversations
    where tenant_id = v_de.tenant_id and de_id = v_de.id
      and channel is distinct from 'exam'
      and csat_submitted_at > now() - interval '30 days';

    select count(*) filter (where decision in ('auto_executed', 'executed_after_approval', 'failed')),
           count(*) filter (where decision in ('auto_executed', 'executed_after_approval'))
      into v_act_total, v_act_ok
    from action_executions
    where tenant_id = v_de.tenant_id and subject_kind = 'de' and subject_id = v_de.id
      and mode = 'execute' and created_at > now() - interval '30 days';

    -- ── skill 1: Case Resolution (escalation rate, lower better) ──
    v_sample := coalesce(v_dec_total, 0);
    if v_sample >= 10 then
      v_value := round(100.0 * v_dec_escalated / v_sample, 1);
      v_prof := case when v_value <= 10 then 4 when v_value <= 25 then 3 when v_value <= 50 then 2 else 1 end;
      v_detail := format('Escalated %s%% of %s decisions (last 30 days). Lower is better; level 5 is human-awarded.', v_value, v_sample);
    else
      v_prof := null; v_value := null;
      v_detail := format('Not yet assessed — %s of the 10 real decisions needed.', v_sample);
    end if;
    call upsert_de_skill(v_de.tenant_id, v_de.id, 'case_resolution', v_prof, v_sample, v_value, v_detail, v_prev);
    if v_prof is not null and v_prof <= 2 then v_weak := array_append(v_weak, 'Case Resolution'); end if;
    if v_prof is distinct from v_prev then v_updated := v_updated + 1; end if;

    -- ── skill 2: Judgment Calibration (avg confidence, higher better) ──
    v_sample := coalesce(v_dec_total, 0);
    if v_sample >= 10 and v_dec_conf is not null then
      v_value := v_dec_conf;
      v_prof := case when v_value >= 80 then 4 when v_value >= 65 then 3 when v_value >= 50 then 2 else 1 end;
      v_detail := format('Average confidence %s%% across %s decisions (last 30 days). Level 5 is human-awarded.', v_value, v_sample);
    else
      v_prof := null; v_value := null;
      v_detail := format('Not yet assessed — %s of the 10 real decisions needed.', v_sample);
    end if;
    call upsert_de_skill(v_de.tenant_id, v_de.id, 'judgment_calibration', v_prof, v_sample, v_value, v_detail, v_prev);
    if v_prof is not null and v_prof <= 2 then v_weak := array_append(v_weak, 'Judgment Calibration'); end if;
    if v_prof is distinct from v_prev then v_updated := v_updated + 1; end if;

    -- ── skill 3: Domain Grounding (answered share of non-blocked) ──
    v_sample := coalesce(v_run_total, 0);
    if v_sample >= 10 then
      v_value := round(100.0 * v_run_answered / v_sample, 1);
      v_prof := case when v_value >= 90 then 4 when v_value >= 75 then 3 when v_value >= 50 then 2 else 1 end;
      v_detail := format('Produced a real answer on %s%% of %s genuine answer attempts (last 30 days). Level 5 is human-awarded.', v_value, v_sample);
    else
      v_prof := null; v_value := null;
      v_detail := format('Not yet assessed — %s of the 10 genuine answer attempts needed.', v_sample);
    end if;
    call upsert_de_skill(v_de.tenant_id, v_de.id, 'domain_grounding', v_prof, v_sample, v_value, v_detail, v_prev);
    if v_prof is not null and v_prof <= 2 then v_weak := array_append(v_weak, 'Domain Knowledge Grounding'); end if;
    if v_prof is distinct from v_prev then v_updated := v_updated + 1; end if;

    -- ── skill 4: Communication Quality (positive CSAT) ──
    v_sample := coalesce(v_csat_total, 0);
    if v_sample >= 5 then
      v_value := round(100.0 * v_csat_pos / v_sample, 1);
      v_prof := case when v_value >= 90 then 4 when v_value >= 75 then 3 when v_value >= 50 then 2 else 1 end;
      v_detail := format('%s%% positive across %s ratings (last 30 days). Level 5 is human-awarded.', v_value, v_sample);
    else
      v_prof := null; v_value := null;
      v_detail := format('Not yet assessed — %s of the 5 customer ratings needed.', v_sample);
    end if;
    call upsert_de_skill(v_de.tenant_id, v_de.id, 'communication_quality', v_prof, v_sample, v_value, v_detail, v_prev);
    if v_prof is not null and v_prof <= 2 then v_weak := array_append(v_weak, 'Communication Quality'); end if;
    if v_prof is distinct from v_prev then v_updated := v_updated + 1; end if;

    -- ── skill 5: System Integration (action success rate) ──
    v_sample := coalesce(v_act_total, 0);
    if v_sample >= 5 then
      v_value := round(100.0 * v_act_ok / v_sample, 1);
      v_prof := case when v_value >= 95 then 4 when v_value >= 85 then 3 when v_value >= 60 then 2 else 1 end;
      v_detail := format('%s%% of %s executed actions succeeded (last 30 days). Level 5 is human-awarded.', v_value, v_sample);
    else
      v_prof := null; v_value := null;
      v_detail := format('Not yet assessed — %s of the 5 executed actions needed.', v_sample);
    end if;
    call upsert_de_skill(v_de.tenant_id, v_de.id, 'system_integration', v_prof, v_sample, v_value, v_detail, v_prev);
    if v_prof is not null and v_prof <= 2 then v_weak := array_append(v_weak, 'System Integration'); end if;
    if v_prof is distinct from v_prev then v_updated := v_updated + 1; end if;

    -- ── §4.5: skill gaps drive Development. One consolidated item per
    --    DE, refreshed; removed when no skills are weak. ──
    if array_length(v_weak, 1) is not null then
      v_weak_names := array_to_string(v_weak, ', ');
      insert into de_development_items (tenant_id, de_id, item_type, source, priority, description, target_metric, target_value, baseline_value, status)
      values (v_de.tenant_id, v_de.id, 'skill_gap', 'detected', 'medium',
        format('%s is below Proficient (level 3) on: %s. These are assessed from real 30-day evidence — target level 3+.', v_de.name, v_weak_names),
        'skill_proficiency', 3, 2, 'proposed')
      on conflict (tenant_id, de_id, item_type) where source = 'detected' and status in ('proposed', 'in_progress')
      do update set description = excluded.description, updated_at = now();
    else
      -- No weak skills → retire any still-open detected skill_gap item.
      update de_development_items set status = 'completed', updated_at = now()
      where tenant_id = v_de.tenant_id and de_id = v_de.id and item_type = 'skill_gap'
        and source = 'detected' and status in ('proposed', 'in_progress');
    end if;
  end loop;

  return jsonb_build_object('skills_changed', v_updated);
end;
$function$;

CREATE OR REPLACE FUNCTION public.assess_definition_of_done(p_tenant_id uuid, p_scope text, p_scope_id uuid, p_objective_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  -- ⚠ REACHABLE BY NOBODY AFTER THIS MIGRATION, and deliberately so — the same
  -- answer, for the same reason, as the three ingestion wrappers in section 1.
  -- `authenticated` has never held EXECUTE here (mig 678 asserted it), so this
  -- membership bar has never been able to fire; granting it now would be a
  -- widening smuggled in beside a narrowing. The body refuses instead of waving
  -- through, which makes handing this name to a UI a one-line decision later
  -- rather than a re-audit. Retirement candidate, reported not hidden.
  --
  -- ⚠ ITS ONE SQL CALLER, conclude_objective_verified, IS LEFT POINTING HERE
  -- rather than at the _internal. It has no caller anywhere in the repo today;
  -- if it is ever revived on a service-role path it will refuse loudly, which
  -- is the failure everyone sees, instead of reading another workspace quietly,
  -- which is the failure nobody does.
  if auth.uid() is null then
    raise exception 'not authenticated: assessing definition-of-done for a workspace named in a parameter is not an anonymous operation';
  end if;
  if not exists (select 1 from profiles p where p.user_id = auth.uid()
                   and (p.tenant_id = p_tenant_id or p.layer = 'platform')) then
    raise exception 'not authorized for this workspace';
  end if;
  return public.assess_definition_of_done_internal(p_tenant_id, p_scope, p_scope_id, p_objective_id);
end $function$;

CREATE OR REPLACE FUNCTION public.assess_definition_of_done_internal(p_tenant_id uuid, p_scope text, p_scope_id uuid, p_objective_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_pending int := 0;
  v_unresolved boolean := false;
  v_gated_task uuid;
begin
  -- NO USER CHECK. connector-hub:7438 and _shared/defOfDone.ts:39 assess with
  -- the service-role admin client. EXECUTE is service_role only.

  -- (a) origin-scoped gated actions: pending = a gated row whose task is still
  --     'pending', OR 'approved' but with nothing that LANDED resolving it.
  --     ⚠ migs 678 + 679. The resolving test used to be a blacklist — anything
  --     not marked as a failure — which a row satisfies the instant the
  --     approval is CLAIMED, before the external call, and which a voided
  --     tombstone satisfies forever. It is now THE shared proof-of-landing.
  select count(*) into v_pending
    from action_executions ae
    join human_tasks ht on ht.id = ae.task_id
   where ae.tenant_id = p_tenant_id and ae.origin_kind = p_scope and ae.origin_id = p_scope_id
     and ae.decision in ('human_gated_destructive','human_gated_trust')
     and ( ht.status = 'pending'
        or ( ht.status = 'approved'
             and not exists (select 1 from action_executions ex
                              where ex.resolves_task_id = ae.task_id
                                and public.action_execution_landed(ex)) ) );

  -- (b) account / opportunity write-backs on this objective.
  if p_objective_id is not null then
    v_pending := v_pending
      + (select count(*) from account_writeback_requests w where w.tenant_id = p_tenant_id and w.objective_id = p_objective_id and w.status = 'pending_approval')
      + (select count(*) from opportunity_writeback_requests w where w.tenant_id = p_tenant_id and w.objective_id = p_objective_id and w.status = 'pending_approval');
  end if;

  -- (c) outbound drafts scoped to this run/item.
  v_pending := v_pending
    + (select count(*) from outbound_drafts d where d.tenant_id = p_tenant_id and d.source_kind = p_scope and d.source_ref = p_scope_id and d.status = 'pending_approval');

  -- (d) fail-CLOSED anchor: an agentic run that flagged a gate whose task is not
  --     resolved by a LANDED execution is 'unresolved' even if origin wasn't
  --     threaded — so a missing correlation can never pass as "nothing pending".
  --     Same shared predicate as (a), and now identical BY CONSTRUCTION rather
  --     than by two copies happening to agree.
  if p_scope = 'agentic_run' then
    select last_gated_human_task_id into v_gated_task from agentic_step_runs where id = p_scope_id and tenant_id = p_tenant_id;
    if v_gated_task is not null
       and not exists (select 1 from action_executions ex
                        where ex.resolves_task_id = v_gated_task
                          and public.action_execution_landed(ex)) then
      v_unresolved := true;
    end if;
  end if;

  return jsonb_build_object(
    'verified', (coalesce(v_pending, 0) = 0) and not v_unresolved,
    'pending_count', coalesce(v_pending, 0),
    'unresolved', v_unresolved,
    'detail', jsonb_build_object('scope', p_scope, 'scope_id', p_scope_id, 'objective_id', p_objective_id)
  );
end $function$;

CREATE OR REPLACE FUNCTION public.assign_doc_collection(p_doc_id uuid, p_collection_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tenant uuid := public.auth_tenant_id();
BEGIN
  IF v_tenant IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'no_tenant'); END IF;
  IF NOT EXISTS (SELECT 1 FROM knowledge_docs WHERE id = p_doc_id AND tenant_id = v_tenant)
    THEN RETURN jsonb_build_object('ok', false, 'error', 'doc_not_found'); END IF;
  IF NOT EXISTS (SELECT 1 FROM knowledge_collections WHERE id = p_collection_id AND tenant_id = v_tenant)
    THEN RETURN jsonb_build_object('ok', false, 'error', 'collection_not_found'); END IF;

  -- 359: filing a document you cannot edit, into a space you do not administer,
  -- is how a member moves a document somewhere they CAN read it.
  IF NOT public.is_platform_admin() THEN
    IF public.knowledge_effective_level(p_doc_id) < 3 THEN
      RETURN jsonb_build_object('ok', false, 'error', 'insufficient_permission',
                                'detail', 'you need edit access to that document');
    END IF;
    IF public.knowledge_my_admin_level(p_collection_id) < 3 THEN
      RETURN jsonb_build_object('ok', false, 'error', 'insufficient_permission',
                                'detail', 'you need access to the space you are filing it into');
    END IF;
  END IF;

  INSERT INTO knowledge_doc_collections (tenant_id, doc_id, collection_id)
  VALUES (v_tenant, p_doc_id, p_collection_id)
  ON CONFLICT (doc_id, collection_id) DO NOTHING;
  RETURN jsonb_build_object('ok', true);
END $function$;

CREATE OR REPLACE FUNCTION public.assign_human_task(p_task_id uuid, p_force boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_task      human_tasks%rowtype;
  v_rule      work_assignment_rules%rowtype;
  v_unit      org_units%rowtype;
  v_pool      org_units%rowtype;   -- the unit the rotation actually draws from
  v_cands     uuid[];
  v_pick      uuid;
  v_cursor    integer;
  v_scope     text;
  v_up_id     uuid;
begin
  select * into v_task from human_tasks where id = p_task_id;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'task_not_found');
  end if;
  -- mig 664: NULL-SAFE, and deliberately the LOOSE service_role escape.
  -- trg_human_tasks_assign fires on INSERT, and inserts arrive from
  -- migrations, cron and psql where auth.role() is NULL; those must keep
  -- auto-routing. The strict coalesce() form would refuse them SILENTLY,
  -- because the trigger swallows exceptions. An authenticated caller always
  -- has a non-null role, so the comparison always runs for them, and
  -- `is distinct from` makes a NULL tenant FAIL rather than skip.
  if auth.role() is not null and auth.role() <> 'service_role'
     and v_task.tenant_id is distinct from auth_tenant_id() then
    raise exception 'that task is not in this workspace';
  end if;
  if v_task.assigned_user_id is not null and not p_force then
    return jsonb_build_object('ok', true, 'reason', 'already_assigned',
                              'user_id', v_task.assigned_user_id);
  end if;

  select * into v_rule
  from work_assignment_rules r
  where r.tenant_id = v_task.tenant_id
    and r.is_active
    and (r.match_type          is null or r.match_type          = v_task.type)
    and (r.match_source        is null or r.match_source        = v_task.source)
    and (r.match_related_table is null or r.match_related_table = v_task.related_table)
    and (r.match_de_id         is null or r.match_de_id         = v_task.de_id)
  order by
    ( (r.match_type is not null)::int + (r.match_source is not null)::int
    + (r.match_related_table is not null)::int + (r.match_de_id is not null)::int ) desc,
    r.priority asc, r.created_at asc
  limit 1;

  if not found then
    return jsonb_build_object('ok', false, 'reason', 'no_matching_rule');
  end if;

  select * into v_unit from org_units where id = v_rule.target_unit_id and is_active;
  if not found then
    return jsonb_build_object('ok', false, 'reason', 'target_unit_inactive', 'rule', v_rule.name);
  end if;
  v_pool := v_unit;

  -- 1. The unit's own people.
  select array_agg(m.user_id order by m.user_id) into v_cands
  from org_unit_members m
  where m.org_unit_id = v_unit.id and m.is_active
    and (v_rule.strategy = 'round_robin' or m.role_in_unit = 'lead');
  v_scope := 'unit';

  -- 2. Asked for a lead, found none — take anyone in the unit.
  if v_cands is null and v_rule.strategy = 'lead_then_round_robin' then
    select array_agg(m.user_id order by m.user_id) into v_cands
    from org_unit_members m where m.org_unit_id = v_unit.id and m.is_active;
    v_scope := 'unit_any';
  end if;

  -- 3. Nobody at this level — look at the teams beneath it.
  if v_cands is null then
    with recursive sub as (
      select id from org_units where id = v_unit.id
      union all
      select u.id from org_units u join sub s on u.parent_id = s.id where u.is_active
    )
    select array_agg(distinct m.user_id order by m.user_id) into v_cands
    from org_unit_members m
    where m.org_unit_id in (select id from sub) and m.is_active;
    v_scope := 'descendants';
  end if;

  -- 4. Still nobody — walk UP to the NEAREST staffed ancestor. Nearest, not
  --    "anyone above", so a team's work escalates to its own department before
  --    it reaches head office.
  if v_cands is null then
    with recursive up as (
      select id, parent_id, 0 as lvl from org_units where id = v_unit.id
      union all
      select u.id, u.parent_id, up.lvl + 1 from org_units u join up on u.id = up.parent_id
      where u.is_active
    )
    select up.id into v_up_id
    from up
    where up.lvl > 0
      and exists (select 1 from org_unit_members m where m.org_unit_id = up.id and m.is_active)
    order by up.lvl asc
    limit 1;

    if v_up_id is not null then
      select * into v_pool from org_units where id = v_up_id;
      select array_agg(m.user_id order by m.user_id) into v_cands
      from org_unit_members m where m.org_unit_id = v_up_id and m.is_active;
      v_scope := 'ancestor';
    end if;
  end if;

  if v_cands is null or array_length(v_cands, 1) = 0 then
    return jsonb_build_object('ok', false, 'reason', 'unit_has_no_members',
                              'rule', v_rule.name, 'unit', v_unit.name);
  end if;

  update org_units set rr_cursor = rr_cursor + 1
   where id = v_pool.id
  returning rr_cursor into v_cursor;

  v_pick := v_cands[ (v_cursor % array_length(v_cands, 1)) + 1 ];

  update human_tasks
     set assigned_user_id = v_pick,
         assigned_role    = v_unit.name,
         assigned_at      = now(),
         assigned_via     = jsonb_build_object(
           'rule_id',   v_rule.id,      'rule',      v_rule.name,
           'unit_id',   v_unit.id,      'unit',      v_unit.name,
           'unit_kind', v_unit.kind,    'strategy',  v_rule.strategy,
           'scope',     v_scope,        'pool_unit', v_pool.name,
           'pool_size', array_length(v_cands, 1)
         )
   where id = p_task_id;

  return jsonb_build_object('ok', true, 'user_id', v_pick, 'unit', v_unit.name,
                            'scope', v_scope, 'rule', v_rule.name,
                            'pool_size', array_length(v_cands, 1));
end;
$function$;

CREATE OR REPLACE FUNCTION public.assign_training_for_de(p_de_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_tenant uuid; v_arch text; v_n int;
begin
  select tenant_id, catalog_id into v_tenant, v_arch from digital_employees where id = p_de_id;
  if v_tenant is null then raise exception 'de not found'; end if;
  insert into de_training_progress (tenant_id, de_id, module_key, status)
  select v_tenant, p_de_id, m.module_key, 'assigned'
  from de_training_modules m
  where m.archetype_key = v_arch and m.required
    and (m.scope = 'platform' or m.tenant_id = v_tenant)
  on conflict (de_id, module_key) do nothing;
  get diagnostics v_n = row_count;
  return v_n;
end;
$function$;

CREATE OR REPLACE FUNCTION public.attach_compliance_pack(p_tenant_id uuid, p_pack_key text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_res jsonb;
begin
  -- Refused on its own line, FIRST, and in words — not folded into the role
  -- predicate as `auth.uid() is not null and ...`, which is the bug this
  -- migration exists for. The internal variant would refuse this caller too;
  -- this line exists so the person reads a sentence about identity rather than
  -- a sentence about authority.
  if auth.uid() is null then
    raise exception 'not authenticated: attaching a compliance pack switches on blocking rules for every employee in this workspace, and the record has to say who did it';
  end if;

  v_res := public.attach_compliance_pack_internal(p_tenant_id, p_pack_key, 'compliance_page');

  -- Same integer contract as before: how many guardrail rules this call put in
  -- force. A revived rule counts — it was not enforcing a second ago and is now.
  return coalesce((v_res ->> 'rules_created')::integer, 0)
       + coalesce((v_res ->> 'rules_reactivated')::integer, 0);
end;
$function$;

CREATE OR REPLACE FUNCTION public.attach_compliance_pack_internal(p_tenant_id uuid, p_pack_key text, p_via text DEFAULT 'unknown'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_inserted   integer := 0;
  v_revived    integer := 0;
  v_in_force   integer := 0;
  v_new_pack   boolean := false;
  v_pack_name  text;
  v_rules      jsonb;
  v_actor      text;
  v_actor_type text;
begin
  -- ⚠ THE WORKSPACE IS NAMED FIRST, in words. Without this line a NULL tenant
  -- reached the tenant_compliance_packs insert and came back as a raw 23502
  -- about a column nobody outside this file has heard of — and it got that far
  -- because `p_tenant = auth_tenant_id()` is NULL when p_tenant is NULL, so the
  -- authority check below evaluated to NULL and waved it through. It is now
  -- refused twice: here by name, and by the coalesce below if this line is ever
  -- deleted.
  if p_tenant_id is null then
    raise exception 'not authorized to attach a compliance pack: no workspace was named — a pack switches on blocking rules for one specific workspace, and a call that does not say which cannot be authorised or recorded';
  end if;

  -- ⚠ FAILS CLOSED, AND coalesce IS WHAT MAKES THAT TRUE. can_admin_tenant_internal is
  --     auth.role() = 'service_role'
  --  OR (p_tenant = auth_tenant_id() AND auth_has_tenant_role([owner, admin]))
  -- which returns NULL — not FALSE — whenever auth_tenant_id() is NULL, and
  -- `if not NULL then` DOES NOT FIRE. Measured live: a profile carrying
  -- role='tenant_owner' with tenant_id NULL walks straight past the bare call.
  -- See the header section on coalesce for the full measurement and for the 11
  -- live functions that already write it this way, install_role_systems — this
  -- migration's own cited precedent — among them.
  if not coalesce(public.can_admin_tenant_internal(p_tenant_id), false) then
    raise exception 'not authorized to attach a compliance pack to this workspace — attaching switches on blocking rules that apply to every employee in it';
  end if;

  select name into v_pack_name from compliance_packs where key = p_pack_key;
  if v_pack_name is null then
    raise exception 'unknown compliance pack %', p_pack_key;
  end if;

  insert into tenant_compliance_packs (tenant_id, pack_key, attached_by)
  values (p_tenant_id, p_pack_key, auth.uid())
  on conflict (tenant_id, pack_key) do nothing;
  get diagnostics v_inserted = row_count;
  v_new_pack := v_inserted > 0;

  -- (a) rules this workspace has never held. Column list byte-identical to the
  --     body this replaces: semantic_policy is deliberately NOT copied from the
  --     catalogue, because it never was, and quietly starting to would change
  --     what the meaning judge screens on.
  insert into guardrail_rules
    (tenant_id, rule, rule_type, pattern, applies_to, severity, active, compliance_pack_key)
  select p_tenant_id, r.rule, r.rule_type, r.pattern, 'all', r.severity, true, r.pack_key
  from compliance_pack_rules r
  where r.pack_key = p_pack_key
    and not exists (
      select 1 from guardrail_rules g
       where g.tenant_id = p_tenant_id
         and g.compliance_pack_key = r.pack_key
         and g.rule = r.rule);
  get diagnostics v_inserted = row_count;

  -- (b) rules a previous detach retired, or that are otherwise switched off.
  --     ⚠ The trigger does NOT block this: it refuses `NEW.active = false`, and
  --     this sets active TRUE. retired_at must be cleared in the SAME statement
  --     or guardrail_rules_retired_is_inactive rejects the row.
  update guardrail_rules g
     set retired_at = null,
         retired_by = null,
         active     = true,
         version    = g.version + 1
   where g.tenant_id          = p_tenant_id
     and g.compliance_pack_key = p_pack_key
     and (g.retired_at is not null or g.active = false);
  get diagnostics v_revived = row_count;

  select count(*) into v_in_force
    from guardrail_rules g
   where g.tenant_id = p_tenant_id
     and g.compliance_pack_key = p_pack_key
     and g.active and g.retired_at is null;

  -- The rules VERBATIM. Same reasoning retire_guardrail_rule states in its own
  -- comment: the row can be edited later and there is no version history
  -- anywhere else, so the audit detail is the only frozen copy of what the
  -- customer's workspace was actually made to enforce.
  -- ⚠ THE SAME COLUMN LIST AS retire_guardrail_rule's frozen copy, and the same
  -- one detach uses below. The first version of this file froze a shorter list
  -- in each of the two directions and a shorter one again than retire's:
  -- threshold, scope_ref and version were missing here or there. Harmless while
  -- every pack rule is blocked_topic/blocking with null threshold and null
  -- scope_ref — and silently wrong on the first pack rule that is not, which is
  -- exactly the day the frozen copy is the only record left.
  select coalesce(jsonb_agg(jsonb_build_object(
           'rule_id',  g.id,   'rule',      g.rule,
           'rule_type', g.rule_type, 'pattern', g.pattern,
           'threshold', g.threshold,
           'severity', g.severity, 'applies_to', g.applies_to,
           'scope',    g.scope, 'scope_ref', g.scope_ref,
           'version',  g.version) order by g.rule), '[]'::jsonb)
    into v_rules
    from guardrail_rules g
   where g.tenant_id = p_tenant_id
     and g.compliance_pack_key = p_pack_key
     and g.active and g.retired_at is null;

  -- ⚠ NOT 'You'/'human' unconditionally. append_audit_event only overwrites the
  -- actor for a JWT caller; under service_role it writes whatever it is handed,
  -- so a hardcoded 'You' would file the Onboarding Architect's automated hire
  -- as a human decision.
  if coalesce(auth.role(), '') = 'service_role' then
    v_actor := 'System'; v_actor_type := 'system';
  else
    v_actor := 'You';    v_actor_type := 'human';
  end if;

  -- Audited only when something actually CHANGED. Hiring three accountants
  -- attaches financial_controls once and no-ops twice; three identical
  -- config_change rows would be three claims that something happened.
  if v_new_pack or v_inserted > 0 or v_revived > 0 then
    perform public.append_audit_event(
      p_tenant_id, v_actor, v_actor_type,
      format('Compliance pack attached — %s. %s blocking rule(s) now apply to every employee in this workspace.',
             v_pack_name, v_in_force),
      'config_change',
      jsonb_build_object(
        'event',             'compliance_pack_attached',
        'pack_key',          p_pack_key,
        'pack_name',         v_pack_name,
        'via',               p_via,
        'rules_created',     v_inserted,
        'rules_reactivated', v_revived,
        'rules_in_force',    v_in_force,
        'rules',             v_rules,
        'attached_by',       auth.uid()));
  end if;

  return jsonb_build_object(
    'ok',                true,
    'pack_key',          p_pack_key,
    'pack_name',         v_pack_name,
    'newly_attached',    v_new_pack,
    'rules_created',     v_inserted,
    'rules_reactivated', v_revived,
    'rules_in_force',    v_in_force);
end;
$function$;

CREATE OR REPLACE FUNCTION public.audit_chain_head(p_tenant_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_head    text;
  v_at      timestamptz;
  v_count   bigint;
BEGIN
  IF coalesce(auth.role(), '') <> 'service_role' AND NOT EXISTS (
    SELECT 1 FROM profiles WHERE user_id = auth.uid() AND tenant_id = p_tenant_id
  ) THEN
    RAISE EXCEPTION 'not a member of this tenant';
  END IF;

  v_head := public.audit_chain_tip(p_tenant_id);          -- mig 549: the true tip
  SELECT created_at INTO v_at FROM audit_events
   WHERE tenant_id = p_tenant_id AND hash = v_head LIMIT 1;
  SELECT count(*) INTO v_count FROM audit_events WHERE tenant_id = p_tenant_id;

  RETURN jsonb_build_object(
    'head_hash', coalesce(v_head, ''),
    'head_at',   v_at,
    'count',     coalesce(v_count, 0)
  );
END;
$function$;

CREATE OR REPLACE FUNCTION public.audit_chain_tip(p_tenant_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_head text;
begin
  select head_hash into v_head from audit_chain_state where tenant_id = p_tenant_id;

  if v_head is null
     or (v_head <> '' and exists (select 1 from audit_events c
                                   where c.tenant_id = p_tenant_id and c.prev_hash = v_head)) then
    select e.hash into v_head
      from audit_events e
     where e.tenant_id = p_tenant_id
       and not exists (select 1 from audit_events c
                        where c.tenant_id = p_tenant_id and c.prev_hash = e.hash)
     order by e.created_at desc, e.id desc
     limit 1;
  end if;

  return coalesce(v_head, '');
end $function$;

CREATE OR REPLACE FUNCTION public.audit_de_config_changes()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP = 'INSERT' THEN
    INSERT INTO de_config_audit_log (tenant_id, entity_kind, entity_id, action,
                                     new_value, changed_by, details)
    VALUES (NEW.tenant_id, NEW.entity_kind, NEW.entity_id, 'create',
            NEW.data, NEW.updated_by, 'Configuration created');
  ELSIF TG_OP = 'UPDATE' THEN
    -- Only log a real change; set_de_config rewrites the row on every save.
    IF NEW.data IS DISTINCT FROM OLD.data THEN
      INSERT INTO de_config_audit_log (tenant_id, entity_kind, entity_id, action,
                                       old_value, new_value, changed_by, details)
      VALUES (NEW.tenant_id, NEW.entity_kind, NEW.entity_id, 'update',
              OLD.data, NEW.data, NEW.updated_by, 'Configuration updated');
    END IF;
  ELSIF TG_OP = 'DELETE' THEN
    INSERT INTO de_config_audit_log (tenant_id, entity_kind, entity_id, action,
                                     old_value, changed_by, details)
    VALUES (OLD.tenant_id, OLD.entity_kind, OLD.entity_id, 'delete',
            OLD.data, auth.uid(), 'Configuration deleted');
  END IF;
  RETURN COALESCE(NEW, OLD);
END;
$function$;

CREATE OR REPLACE FUNCTION public.audit_events_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if TG_OP = 'DELETE' and coalesce(current_setting('app.allow_audit_purge', true), '') = 'on' then
    return OLD;
  end if;
  raise exception 'audit_events is immutable — records can only be appended';
end;
$function$;

CREATE OR REPLACE FUNCTION public.audit_events_no_truncate()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  raise exception
    'audit_events cannot be truncated — the record is append-only. Deleting a tenant removes its own rows through delete_tenant.';
end;
$function$;

CREATE OR REPLACE FUNCTION public.audit_tenant_feature_parity()
 RETURNS TABLE(finding_kind text, subject text, detail text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  return query
  -- (a) a workspace that does not meet the baseline contract every workspace
  --     is supposed to get. Same thresholds audit_tenant_provisioning uses.
  select 'baseline_incomplete'::text, t.name::text,
         format('employees=%s playbooks=%s guardrails=%s onboarding_versions=%s',
           (select count(*) from digital_employees d where d.tenant_id=t.id and d.lifecycle_status<>'retired'),
           (select count(*) from playbook_definitions p where p.tenant_id=t.id),
           (select count(*) from guardrail_rules g where g.tenant_id=t.id and g.active),
           (select count(*) from onboarding_template_versions v where v.tenant_id=t.id))::text
    from tenants t
   where t.id <> 'a0000000-0000-0000-0000-000000000001'
     and t.name not like '[TEST DEBRIS%'
     and (  (select count(*) from digital_employees d where d.tenant_id=t.id and d.lifecycle_status<>'retired') < 2
         -- playbooks intentionally NOT asserted: provisioning no longer seeds any (723)
         or (select count(*) from guardrail_rules g where g.tenant_id=t.id and g.active) < 7
         or (select count(*) from onboarding_template_versions v where v.tenant_id=t.id) < 1)

  union all
  -- (b) a feature that ships on by default but has been switched OFF for a
  --     single workspace — the literal shape of "not available to everyone".
  select 'feature_disabled_for_one'::text, (t.name || ' / ' || o.feature_key)::text,
         'default_enabled=true but this workspace has an explicit disable'::text
    from tenant_feature_overrides o
    join tenants t on t.id = o.tenant_id
    join feature_registry f on f.key = o.feature_key
   where f.default_enabled = true and o.enabled = false

  union all
  -- (c) the drift that produced defect 2: a description that contradicts the
  --     flag. Cheap to check, and it is what customers actually read.
  select 'description_contradicts_flag'::text, f.key::text,
         'default_enabled=true but the description says it is off by default'::text
    from feature_registry f
   where f.default_enabled = true and f.description ilike '%default off%'

  union all
  -- (d) a workspace-scoped action that duplicates a platform one: that
  --     workspace's employees see two tools for the same job.
  select 'tenant_action_shadows_platform'::text, (t.name || ' / ' || a.action_key || ' [' || a.category || ']')::text,
         'a platform action with the same key and category already reaches every workspace'::text
    from action_definitions a
    join tenants t on t.id = a.tenant_id
   where a.scope = 'tenant'
     and exists (select 1 from action_definitions p
                  where p.scope = 'platform' and p.tenant_id is null
                    and p.action_key = a.action_key and p.category = a.category);
end $function$;

CREATE OR REPLACE FUNCTION public.audit_tenant_provisioning()
 RETURNS TABLE(tenant_id uuid, tenant_name text, tenant_status text, des bigint, playbooks bigint, guardrails bigint, onboarding_templates bigint, specialists bigint, trust_policies bigint, autonomy_rows bigint, connectors bigint, baseline_complete boolean)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not resolve_platform_capability(auth.uid(), 'tenants.manage') then raise exception 'only a platform team member with tenant management access may audit tenant provisioning'; end if;
  return query
  select t.id, t.name, t.status,
    (select count(*) from digital_employees d where d.tenant_id = t.id and d.lifecycle_status <> 'retired'),
    (select count(*) from playbook_definitions p where p.tenant_id = t.id),
    (select count(*) from guardrail_rules g where g.tenant_id = t.id and g.active),
    (select count(*) from onboarding_template_versions v where v.tenant_id = t.id),
    0,
    (select count(*) from trust_policies tp where tp.tenant_id = t.id),
    (select count(*) from de_autonomy da where da.tenant_id = t.id),
    (select count(*) from connectors c where c.tenant_id = t.id),
    (select count(*) from digital_employees d where d.tenant_id = t.id and d.lifecycle_status <> 'retired') >= 2
      -- playbooks intentionally NOT asserted: provisioning no longer seeds any (723)
      and (select count(*) from guardrail_rules g where g.tenant_id = t.id and g.active) >= 7
      and (select count(*) from onboarding_template_versions v where v.tenant_id = t.id) >= 1
  from tenants t
  where t.id <> 'a0000000-0000-0000-0000-000000000001' and t.name not like '[TEST DEBRIS%'
  order by t.created_at desc;
end; $function$;

CREATE OR REPLACE FUNCTION public.audit_unguarded_dormancy_writers()
 RETURNS TABLE(function_name text, writes_to text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select p.proname::text,
         (select string_agg(t, ', ' order by t)
            from unnest(array['human_tasks','de_work_items','playbook_trigger_fires',
                              'staleness_escalations','de_objectives','de_incidents',
                              'de_development_items']) t
           where p.prosrc ~* ('insert\s+into\s+' || t))
  from pg_proc p
  join pg_namespace n on n.oid = p.pronamespace
  where n.nspname = 'public'
    and p.prokind = 'f'
    -- writes something that MEANS the workforce acted
    and p.prosrc ~* 'insert\s+into\s+(human_tasks|de_work_items|playbook_trigger_fires|staleness_escalations|de_objectives|de_incidents|de_development_items)'
    -- …with neither accepted spelling of the suspension check
    and p.prosrc not ilike '%tenant_is_operational%'
    and p.prosrc !~* 'status\s+in\s*\(\s*''active''\s*,\s*''trial''\s*\)'
    -- …and is not a human-driven RPC (see KNOWN LIMITS above)
    and p.prosrc !~* 'auth\.uid\(\)|auth_tenant_id\(\)'
    -- …and has not been reviewed and accepted
    and not exists (select 1 from dormancy_writer_exemptions x where x.function_name = p.proname)
  order by 1;
$function$;

CREATE OR REPLACE FUNCTION public.auth_has_tenant_role(required_roles text[])
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select
    exists (
      select 1 from public.profiles
      where user_id = auth.uid() and coalesce(is_active, true) = true
        and role = any(required_roles)
    )
    or
    public.resolve_remote_access_tenant(auth.uid(), public.auth_tenant_id()) is not null;
$function$;

CREATE OR REPLACE FUNCTION public.auth_tenant_id()
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce(
    (
      select tenant_id from public.profiles
      where user_id = auth.uid() and coalesce(is_active, true) = true
      limit 1
    ),
    (
      select e.tenant_id
      from public.platform_access_events e
      where e.operator_user_id = auth.uid()
        and e.event = 'start'
        and e.created_at > now() - interval '12 hours'
        and exists (
          select 1 from public.profiles p
          where p.user_id = auth.uid() and coalesce(p.is_active, true) = true
        )
        and e.id = (
          select e2.id
          from public.platform_access_events e2
          where e2.operator_user_id = auth.uid()
          order by e2.created_at desc
          limit 1
        )
      limit 1
    )
  );
$function$;

CREATE OR REPLACE FUNCTION public.authority_dimension_reader_is_real()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_src text;
begin
  if new.reader_fn is null then
    return new;   -- no reader claimed; mig 770 already refuses rules on it
  end if;

  if to_regprocedure(new.reader_fn) is null then
    raise exception 'reader_fn_does_not_exist: % names no function', new.reader_fn;
  end if;

  select regexp_replace(p.prosrc, '--[^' || chr(10) || ']*', '', 'g') into v_src
    from pg_proc p where p.oid = to_regprocedure(new.reader_fn);

  -- NOT a proof that the function reports the dimension -- a proof that it
  -- could. A reader that never names the dimension anywhere in its body
  -- certainly does not report it, and that is the case this catches.
  -- Comments are stripped first: prose about a dimension is not a reader of
  -- it, and this repo has had three probes pass by matching their own
  -- comments.
  if v_src is null or v_src !~ new.dimension then
    raise exception 'reader_fn_never_mentions_dimension: % does not reference %, so it cannot be reporting it',
      new.reader_fn, new.dimension;
  end if;

  return new;
end
$function$;

CREATE OR REPLACE FUNCTION public.authority_rule_requires_a_reader()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_reader text; v_active boolean; v_value_type text;
begin
  select reader_fn, is_active, value_type into v_reader, v_active, v_value_type
    from public.authority_dimensions where dimension = new.dimension;
  if not coalesce(v_active, false) then
    raise exception 'dimension_not_active: % is not a measure this platform offers', new.dimension;
  end if;
  if v_reader is null then
    raise exception 'dimension_has_no_reader: nothing reads % yet, so a rule about it would be decoration — the reader ships before the rule becomes declarable', new.dimension;
  end if;
  -- Ask the catalog, never a stored boolean.
  if to_regprocedure(v_reader) is null then
    raise exception 'dimension_reader_missing: % names %, which does not exist', new.dimension, v_reader;
  end if;
  -- ⛔ A STORABLE RULE THAT CAN NEVER FIRE IS A CONFIGURABLE CONTROL THAT
  -- ENFORCES NOTHING — the same disease this whole registry exists to end,
  -- one column over. The composite FK above stops an illegal COMPARATOR from
  -- being stored (`reversible >= 5`); nothing stopped an illegal THRESHOLD:
  -- evaluate_authority maps a boolean measure to 1 or 0, so `reversible is 7`
  -- can never equal either, and confidence is read as a 0..100 score, so
  -- `confidence < -1` can never trip. Both are legal to insert today and dead
  -- on arrival.
  if v_value_type = 'boolean' and new.threshold not in (0, 1) then
    raise exception 'threshold_cannot_fire: % is boolean, stored as 1 or 0, so a threshold of % can never match', new.dimension, new.threshold;
  end if;
  if new.dimension = 'confidence' and (new.threshold < 0 or new.threshold > 100) then
    raise exception 'threshold_cannot_fire: % is scored 0..100, so a threshold of % can never trip a comparison', new.dimension, new.threshold;
  end if;
  return new;
end
$function$;

CREATE OR REPLACE FUNCTION public.auto_provision_new_tenant()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_de_id UUID;
BEGIN
  -- Only provision if tenant is created with status='active'
  IF NEW.status = 'active' THEN
    RAISE NOTICE 'Auto-provisioning features for new tenant: %', NEW.name;

    -- Create Workspace Assistant DE
    INSERT INTO digital_employees (
      tenant_id,
      name,
      status,
      charter,
      is_workforce_assistant,
      is_product_expert,
      created_by,
      description
    ) VALUES (
      NEW.id,
      'Workspace Assistant',
      'active',
      jsonb_build_object(
        'name', 'Workspace Assistant',
        'persona', 'You are a trusted advisor helping this organization hire, improve, and manage their digital workforce. You are an expert on the DreamTeamAI platform.',
        'responsibilities', jsonb_build_array(
          'Help hire new DEs by understanding role requirements',
          'Suggest improvements to underperforming DEs based on metrics',
          'Monitor team performance and provide insights',
          'Help retire DEs and transition knowledge',
          'Train new tenants on DreamTeamAI features'
        ),
        'guardrails', jsonb_build_array(
          'Never auto-approve DE changes without explicit user consent',
          'Always show evidence for recommendations',
          'Prioritize user success over automation',
          'Escalate ambiguous decisions to the tenant admin'
        )
      ),
      true,
      true,
      auth.uid(),
      'Conversational workforce management assistant'
    ) RETURNING id INTO v_de_id;

    -- Create initial deployment stage
    INSERT INTO de_deployment_stages (de_id, stage)
    VALUES (v_de_id, 'live');

    RAISE NOTICE 'Auto-provisioned Workspace Assistant for tenant: %', NEW.name;
  END IF;

  -- 332: every workspace gets the platform-provided Workspace Assistant.

  -- Never let this block tenant creation: a missing Assistant is

  -- recoverable, a failed workspace creation is not.

  begin perform public.provision_workforce_assistant_internal(new.id);

  exception when others then

    raise warning 'workforce assistant provisioning failed for %: %', new.id, sqlerrm;

  end;

  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.b64url(p_in text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT translate(
           replace(replace(rtrim(encode(convert_to(coalesce(p_in,''),'UTF8'),'base64'), '='), chr(10), ''), chr(13), ''),
           '+/', '-_');
$function$;

CREATE OR REPLACE FUNCTION public.begin_objective_wake(p_objective_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_count integer;
  v_tenant uuid;
  v_de uuid;
  v_kind text;
  v_ref text;
  v_fp text;
  v_open int;
  v_done int;
begin
  update de_objectives
     set wake_count = wake_count + 1,
         next_wake_at = case when cadence_minutes is not null
                             then now() + make_interval(mins => cadence_minutes)
                             else now() + interval '60 minutes' end,
         updated_at = now()
   where id = p_objective_id and status in ('open', 'in_progress', 'blocked')
     and next_wake_at is not null and next_wake_at <= now()   -- the actual claim
   returning wake_count, tenant_id, de_id, entity_kind, entity_ref
        into v_count, v_tenant, v_de, v_kind, v_ref;
  if v_count is null then raise exception 'objective not wakeable (already claimed, disarmed, or closed)'; end if;

  -- Progress fingerprint: identical across consecutive wakes == nothing moved.
  select md5(coalesce(string_agg(w.id::text || ':' || w.status, '|' order by w.id), 'none')),
         count(*) filter (where w.status in ('queued','running','waiting_human')),
         count(*) filter (where w.status = 'done')
    into v_fp, v_open, v_done
    from de_work_items w
   where w.objective_id = p_objective_id;

  insert into de_objective_wakes (
    tenant_id, de_id, objective_id, wake_no,
    open_item_count, done_item_count, progress_fingerprint,
    entity_kind, entity_ref, source_category
  )
  select v_tenant, v_de, p_objective_id, v_count,
         coalesce(v_open, 0), coalesce(v_done, 0), v_fp,
         v_kind, v_ref, de.archetype_key
    from digital_employees de
   where de.id = v_de
  on conflict (objective_id, wake_no) do nothing;

  return v_count;
end;
$function$;

CREATE OR REPLACE FUNCTION public.build_base_predicates(p jsonb)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE e jsonb; out text := ''; BEGIN
  FOR e IN SELECT jsonb_array_elements(coalesce(p,'[]'::jsonb)) LOOP
    out := out || CASE e->>'op'
      WHEN 'is_null'         THEN format(' AND %I IS NULL', e->>'col')
      WHEN 'is_not_null'     THEN format(' AND %I IS NOT NULL', e->>'col')
      WHEN 'ge_current_date' THEN format(' AND %I >= current_date', e->>'col')
      ELSE '' END;
  END LOOP; RETURN out; END $function$;

CREATE OR REPLACE FUNCTION public.bulk_add_doc_tag(p_doc_ids uuid[], p_tag text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tenant uuid := public.auth_tenant_id(); v_n int; v_tag text := btrim(coalesce(p_tag, ''));
BEGIN
  IF v_tenant IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'no_tenant'); END IF;
  IF p_doc_ids IS NULL OR array_length(p_doc_ids, 1) IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'no_docs'); END IF;
  IF array_length(p_doc_ids, 1) > 1000 THEN RETURN jsonb_build_object('ok', false, 'error', 'too_many'); END IF;
  IF v_tag = '' THEN RETURN jsonb_build_object('ok', false, 'error', 'empty_tag'); END IF;
  UPDATE knowledge_docs
     SET tags = (SELECT array_agg(DISTINCT t) FROM unnest(coalesce(tags, '{}') || ARRAY[v_tag]) t),
         updated_at = now()
   WHERE id = ANY(p_doc_ids) AND tenant_id = v_tenant AND NOT (coalesce(tags, '{}') @> ARRAY[v_tag]);
  GET DIAGNOSTICS v_n = ROW_COUNT;
  RETURN jsonb_build_object('ok', true, 'updated', v_n);
END $function$;

CREATE OR REPLACE FUNCTION public.bulk_assign_collection(p_doc_ids uuid[], p_collection_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tenant uuid := public.auth_tenant_id(); v_n int;
BEGIN
  IF v_tenant IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'no_tenant'); END IF;
  IF p_doc_ids IS NULL OR array_length(p_doc_ids, 1) IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'no_docs'); END IF;
  IF array_length(p_doc_ids, 1) > 1000 THEN RETURN jsonb_build_object('ok', false, 'error', 'too_many'); END IF;
  IF NOT EXISTS (SELECT 1 FROM knowledge_collections WHERE id = p_collection_id AND tenant_id = v_tenant) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'collection_not_found');
  END IF;
  INSERT INTO knowledge_doc_collections (tenant_id, doc_id, collection_id)
  SELECT v_tenant, d.id, p_collection_id FROM knowledge_docs d
   WHERE d.id = ANY(p_doc_ids) AND d.tenant_id = v_tenant
  ON CONFLICT (doc_id, collection_id) DO NOTHING;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  RETURN jsonb_build_object('ok', true, 'added', v_n);
END $function$;

CREATE OR REPLACE FUNCTION public.bulk_delete_docs(p_doc_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tenant uuid := public.auth_tenant_id(); v_n int;
BEGIN
  IF v_tenant IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'no_tenant'); END IF;
  IF p_doc_ids IS NULL OR array_length(p_doc_ids, 1) IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'no_docs'); END IF;
  IF array_length(p_doc_ids, 1) > 500 THEN RETURN jsonb_build_object('ok', false, 'error', 'too_many', 'cap', 500); END IF;
  DELETE FROM knowledge_docs WHERE id = ANY(p_doc_ids) AND tenant_id = v_tenant;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  RETURN jsonb_build_object('ok', true, 'deleted', v_n);
END $function$;

CREATE OR REPLACE FUNCTION public.bulk_mark_verified(p_doc_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tenant uuid := public.auth_tenant_id(); v_n int;
BEGIN
  IF v_tenant IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'no_tenant'); END IF;
  IF p_doc_ids IS NULL OR array_length(p_doc_ids, 1) IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'no_docs'); END IF;
  IF array_length(p_doc_ids, 1) > 1000 THEN RETURN jsonb_build_object('ok', false, 'error', 'too_many'); END IF;
  UPDATE knowledge_docs SET last_verified_at = now()
   WHERE id = ANY(p_doc_ids) AND tenant_id = v_tenant;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  RETURN jsonb_build_object('ok', true, 'verified', v_n);
END $function$;

CREATE OR REPLACE FUNCTION public.bulk_reembed_docs(p_doc_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tenant uuid := public.auth_tenant_id(); v_n int;
BEGIN
  IF v_tenant IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'no_tenant'); END IF;
  IF NOT public.is_feature_enabled_internal(v_tenant, 'knowledge_reembed') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'reembed_disabled'); END IF;
  IF p_doc_ids IS NULL OR array_length(p_doc_ids, 1) IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'no_docs'); END IF;
  IF array_length(p_doc_ids, 1) > 500 THEN RETURN jsonb_build_object('ok', false, 'error', 'too_many', 'cap', 500); END IF;
  UPDATE knowledge_doc_chunks SET reembed_pending = true
   WHERE doc_id = ANY(p_doc_ids) AND tenant_id = v_tenant;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  RETURN jsonb_build_object('ok', true, 'chunks_queued', v_n);
END $function$;

CREATE OR REPLACE FUNCTION public.calculate_tenant_monthly_cost(p_tenant_id uuid)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_features_cost NUMERIC(10,2) := 0;
  v_usage_cost NUMERIC(10,2) := 0;
  v_total_cost NUMERIC(10,2) := 0;
  v_month_year VARCHAR(7) := to_char(now(), 'YYYY-MM');
  v_responses INT;
  v_amendments INT;
  v_de_count INT;
BEGIN
  IF NOT is_platform_admin() THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;

  -- Get current month metrics
  SELECT
    COALESCE(total_responses_this_month, 0),
    COALESCE(total_amendments_created, 0)
  INTO v_responses, v_amendments
  FROM tenant_usage_metrics
  WHERE tenant_id = p_tenant_id AND month_year = v_month_year;

  -- Get DE count
  SELECT COUNT(*) INTO v_de_count
  FROM digital_employees
  WHERE tenant_id = p_tenant_id;

  -- Calculate feature costs (assuming all enabled)
  SELECT
    COALESCE(sophie_config_cost, 100) +
    COALESCE(amendment_journeys_cost, 50) +
    COALESCE(metrics_tracking_cost, 75) +
    COALESCE(reply_mode_cost, 150) +
    COALESCE(hosted_chat_cost, 200)
  INTO v_features_cost
  FROM tenant_billing_config
  WHERE tenant_id = p_tenant_id;

  -- Calculate usage costs
  SELECT
    (v_responses::numeric / 1000) * COALESCE(cost_per_1k_responses, 0.50) +
    (v_amendments::numeric) * COALESCE(cost_per_amendment, 5) +
    (v_de_count::numeric) * COALESCE(cost_per_de, 20)
  INTO v_usage_cost
  FROM tenant_billing_config
  WHERE tenant_id = p_tenant_id;

  v_total_cost := COALESCE(v_features_cost, 0) + COALESCE(v_usage_cost, 0);

  -- Insert or update cost tracking
  INSERT INTO tenant_cost_tracking (
    tenant_id, billing_month, status,
    sophie_config_charge, amendment_journeys_charge, metrics_tracking_charge,
    reply_mode_charge, hosted_chat_charge, response_usage_cost,
    amendment_usage_cost, de_count_cost, subtotal, total_cost
  ) VALUES (
    p_tenant_id, v_month_year, 'estimated',
    100, 50, 75, 150, 200,
    (v_responses::numeric / 1000) * 0.50,
    (v_amendments::numeric) * 5,
    (v_de_count::numeric) * 20,
    v_features_cost, v_total_cost
  )
  ON CONFLICT (tenant_id, billing_month)
  DO UPDATE SET
    total_cost = EXCLUDED.total_cost,
    response_usage_cost = EXCLUDED.response_usage_cost,
    amendment_usage_cost = EXCLUDED.amendment_usage_cost,
    de_count_cost = EXCLUDED.de_count_cost,
    updated_at = now();

  RETURN json_build_object(
    'tenant_id', p_tenant_id,
    'month', v_month_year,
    'features_cost', ROUND(v_features_cost, 2),
    'usage_cost', ROUND(v_usage_cost, 2),
    'responses', v_responses,
    'amendments', v_amendments,
    'de_count', v_de_count,
    'total_cost', ROUND(v_total_cost, 2)
  );
END;
$function$;

CREATE OR REPLACE FUNCTION public.caller_has_tenant_relationship(p_tenant_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select
    is_platform_admin()
    or exists (
      select 1 from profiles pr where pr.user_id = auth.uid() and pr.tenant_id = p_tenant_id and coalesce(pr.is_active, true) = true
    )
    or exists (
      -- caller's own tenant is an ancestor of p_tenant_id => opt-in rollup
      -- visibility for a parent looking at a descendant.
      select 1
      from profiles pr
      join tenant_ancestry ta on ta.tenant_id = p_tenant_id and ta.ancestor_id = pr.tenant_id
      where pr.user_id = auth.uid() and coalesce(pr.is_active, true) = true
    );
$function$;

CREATE OR REPLACE FUNCTION public.can_access_de(p_de_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT
    -- ⚠ SERVICE ROLE IS IDENTIFIED BY auth.role(), NEVER BY A NULL auth.uid().
    -- anon ALSO has a null uid, so "if uid is null then allow" hands the
    -- internet everything — that is precisely the fail-open migration 330 had
    -- to close across 26 functions. Name the role explicitly.
    coalesce(auth.role(), '') = 'service_role'
    -- Platform staff. This is also the branch that carries Support Remote
    -- Access: resolve_remote_access_tenant requires layer='platform', which is
    -- exactly this predicate, so remote access never needs the branch below.
    OR public.is_platform_admin()
    -- Owner, admin and manager are responsible for the whole workforce —
    -- ⚠ mig 663: OF THEIR OWN WORKSPACE. Before this, the role test stood alone
    -- and admitted 1,875 cross-tenant pairs.
    OR (
      public.auth_has_tenant_role(ARRAY['tenant_owner', 'tenant_admin', 'tenant_manager'])
      AND public.auth_tenant_id() IS NOT NULL
      AND EXISTS (
        SELECT 1 FROM public.digital_employees de
         WHERE de.id = p_de_id
           AND de.tenant_id = public.auth_tenant_id()
      )
    )
    -- Everyone else sees the digital employees they are assigned to.
    -- ⚠ mig 663: an assignment row's tenant is chosen by whoever writes it, and
    -- `authenticated` can write this table. Requiring the EMPLOYEE's tenant to
    -- match too means a self-issued ticket names a workspace it cannot claim.
    -- Defence in depth: section 2 below stops the row being written at all.
    OR EXISTS (
      SELECT 1 FROM public.de_assignments a
        JOIN public.digital_employees d ON d.id = a.de_id
       WHERE a.de_id = p_de_id
         AND a.user_id = auth.uid()
         AND a.tenant_id = public.auth_tenant_id()
         AND d.tenant_id = a.tenant_id
    )
    -- mig 591 + 592: …or that work in a unit you belong to.
    --
    -- The seed set (mig 592): a DEPARTMENT or TEAM you are in, or a
    -- LOCATION/BRANCH you LEAD. Being based at a site is not supervising it —
    -- everybody is "at" the head office, and 588 placed them all there.
    -- Without this distinction, root membership meant the whole workforce.
    --
    -- DOWNWARD ONLY from that seed. A department reaches its teams; a team
    -- never reaches back up to the department's other teams.
    -- (Already tenant-pinned on the employee itself — left as it was.)
    OR EXISTS (
      WITH RECURSIVE mine AS (
        SELECT m.org_unit_id AS id
          FROM public.org_unit_members m
          JOIN public.org_units su ON su.id = m.org_unit_id
         WHERE m.user_id = auth.uid()
           AND m.is_active
           AND m.tenant_id = public.auth_tenant_id()
           AND su.is_active
           AND (su.kind IN ('department', 'team') OR m.role_in_unit = 'lead')
        UNION
        SELECT u.id
          FROM public.org_units u
          JOIN mine ON u.parent_id = mine.id
         WHERE u.is_active
      )
      SELECT 1
        FROM public.digital_employees de
       WHERE de.id = p_de_id
         AND de.tenant_id = public.auth_tenant_id()
         AND de.org_unit_id IS NOT NULL
         AND de.org_unit_id IN (SELECT id FROM mine)
    );
$function$;

CREATE OR REPLACE FUNCTION public.can_admin_tenant_internal(p_tenant uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT coalesce(auth.role(),'') = 'service_role'
      OR (p_tenant = public.auth_tenant_id()
          AND public.auth_has_tenant_role(ARRAY['tenant_owner','tenant_admin']));
$function$;

CREATE OR REPLACE FUNCTION public.can_consult_multihop(p_tenant_id uuid, p_requester_de uuid, p_target_de uuid, p_path uuid[] DEFAULT '{}'::uuid[], p_max_depth integer DEFAULT 2)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if p_target_de = any(p_path) or p_target_de = p_requester_de then
    return jsonb_build_object('allowed', false, 'reason', 'cycle');
  end if;
  if coalesce(array_length(p_path, 1), 0) >= p_max_depth then
    return jsonb_build_object('allowed', false, 'reason', 'max_depth');
  end if;
  if not exists (
      select 1 from de_consultation_grants g
      where g.tenant_id = p_tenant_id and g.requester_de_id = p_requester_de
        and g.target_de_id = p_target_de and g.active) then
    return jsonb_build_object('allowed', false, 'reason', 'no_grant');
  end if;
  return jsonb_build_object('allowed', true, 'next_path', (p_path || p_requester_de));
end;
$function$;

CREATE OR REPLACE FUNCTION public.cancel_case_continuation(p_event_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tenant uuid; v_de uuid;
BEGIN
  SELECT tenant_id, de_id INTO v_tenant, v_de FROM de_case_events WHERE id = p_event_id AND status = 'pending';
  IF v_tenant IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'not_found_or_decided'); END IF;
  IF coalesce(auth.role(),'') <> 'service_role' AND v_tenant IS DISTINCT FROM public.auth_tenant_id() THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_tenant_member');
  END IF;
  -- DE scoping (mig 385/439). de_case_events.de_id is NOT NULL, and it comes
  -- off the same row the UPDATE below touches. Service callers bypass, as
  -- they do for the tenant check above.
  IF coalesce(auth.role(),'') <> 'service_role' AND NOT public.can_access_de(v_de) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_responsible_for_de');
  END IF;
  UPDATE de_case_events SET status = 'cancelled', decided_at = now() WHERE id = p_event_id;
  RETURN jsonb_build_object('ok', true);
END; $function$;

CREATE OR REPLACE FUNCTION public.cancel_ingestion_job(p_job_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tenant uuid := auth_tenant_id(); v_n int;
BEGIN
  IF v_tenant IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  IF NOT EXISTS (SELECT 1 FROM knowledge_ingestion_jobs WHERE id=p_job_id AND tenant_id=v_tenant) THEN
    RAISE EXCEPTION 'job_not_found';
  END IF;

  UPDATE knowledge_ingestion_jobs SET status='cancelled', finished_at=now() WHERE id=p_job_id;
  UPDATE knowledge_ingestion_items SET status='cancelled', updated_at=now()
   WHERE job_id=p_job_id AND status IN ('queued','running');
  GET DIAGNOSTICS v_n = ROW_COUNT;
  RETURN jsonb_build_object('ok', true, 'cancelled_items', v_n);
END $function$;

CREATE OR REPLACE FUNCTION public.capture_capability_demand()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_label text;
begin
  -- Coverage is rewritten every turn; only look when it actually moved.
  if tg_op = 'UPDATE' and new.coverage is not distinct from old.coverage then
    return new;
  end if;

  select coalesce(nullif(btrim(t.name), ''), nullif(btrim(t.slug), ''), new.tenant_id::text)
    into v_label
    from tenants t where t.id = new.tenant_id;
  v_label := coalesce(v_label, new.tenant_id::text);

  insert into discovery_capability_demand_log
    (tenant_id, session_id, dimension_key, tenant_label, dimension_title, capability, evidence)
  select new.tenant_id, new.id, g.dimension_key, v_label, g.title, cap.a,
         left(nullif(btrim(coalesce(new.coverage -> g.dimension_key ->> 'evidence', '')), ''), 500)
    from discovery_capability_gaps g
    cross join lateral unnest(g.planned_archetypes) cap(a)
   where (new.coverage -> g.dimension_key ->> 'state') = 'heard'
  on conflict (session_id, capability, dimension_key) do nothing;

  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.certify_de_from_eval(p_de_id uuid, p_archetype_key text, p_eval_run_id uuid, p_threshold_pct integer DEFAULT 80)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_tenant uuid;
begin
  -- The identity bar on its own line, in words about identity. The `auth.uid()
  -- is not null and` prefix that used to sit in front of the check below made
  -- it SKIP for a caller with no identity instead of refusing one.
  if auth.uid() is null then
    raise exception 'not authenticated: a certification is recorded against a workspace, so the caller has to be a member of one';
  end if;
  select tenant_id into v_tenant from digital_employees where id = p_de_id;
  if v_tenant is null then raise exception 'de not found'; end if;
  -- The authority predicate, unchanged from the live body apart from the
  -- deleted prefix.
  if not exists (
      select 1 from profiles p where p.user_id = auth.uid()
      and (p.layer = 'platform' or p.tenant_id = v_tenant)) then
    raise exception 'not authorized';
  end if;
  return public.certify_de_from_eval_internal(p_de_id, p_archetype_key, p_eval_run_id, p_threshold_pct);
end;
$function$;

CREATE OR REPLACE FUNCTION public.certify_de_from_eval_internal(p_de_id uuid, p_archetype_key text, p_eval_run_id uuid, p_threshold_pct integer DEFAULT 80)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_tenant uuid; v_total int; v_passed int; v_pct numeric; v_status text; v_threshold integer;
begin
  select tenant_id into v_tenant from digital_employees where id = p_de_id;
  if v_tenant is null then raise exception 'de not found'; end if;
  -- NO USER CHECK, ON PURPOSE. eval-run certifies with the service-role admin
  -- client and has no signed-in person to check. EXECUTE is service_role only.
  select coalesce((select pass_threshold_pct from role_archetypes where key = p_archetype_key), 80)
    into v_threshold;
  select total, passed into v_total, v_passed from eval_runs where id = p_eval_run_id and tenant_id = v_tenant;
  if v_total is null or v_total = 0 then raise exception 'eval run has no results'; end if;
  v_pct := round(100.0 * v_passed / v_total, 1);
  v_status := case when v_pct >= v_threshold then 'passed' else 'failed' end;
  insert into role_certifications (tenant_id, de_id, archetype_key, eval_run_id, score_pct, threshold_pct, status, evaluated_at, config_fingerprint)
  values (v_tenant, p_de_id, p_archetype_key, p_eval_run_id, v_pct, v_threshold, v_status, now(), public.de_config_fingerprint(p_de_id));
  return jsonb_build_object('status', v_status, 'score_pct', v_pct, 'threshold_pct', v_threshold, 'passed', v_passed, 'total', v_total);
end;
$function$;

CREATE OR REPLACE FUNCTION public.certify_de_from_sim(p_de_id uuid, p_archetype_key text, p_sim_run_id uuid, p_threshold_pct integer DEFAULT 80)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_tenant uuid; v_run sim_runs; v_pct numeric; v_status text; v_threshold integer; v_fp text;
begin
  select tenant_id into v_tenant from digital_employees where id = p_de_id;
  if v_tenant is null then raise exception 'de not found'; end if;
  -- Prefix deleted. No caller anywhere — reported as a retirement candidate
  -- rather than left as a live SECDEF writer nothing calls.
  if not exists (
      select 1 from profiles p where p.user_id = auth.uid()
      and (p.layer = 'platform' or p.tenant_id = v_tenant)) then
    raise exception 'not authorized';
  end if;

  -- The archetype's bar governs; the caller's p_threshold_pct is IGNORED
  -- (kept only for signature compatibility) — a threshold of 0 could mint
  -- a passing cert from any finished run (C2).
  select coalesce((select pass_threshold_pct from role_archetypes where key = p_archetype_key), 80)
    into v_threshold;

  select * into v_run from sim_runs
    where id = p_sim_run_id and tenant_id = v_tenant and de_id = p_de_id
      and status in ('passed', 'failed') and candidate = false;
  if v_run.id is null or v_run.total = 0 then
    raise exception 'simulation has no results (or is a candidate dry-run, which cannot certify)';
  end if;
  v_pct := round(100.0 * v_run.passed / v_run.total, 1);
  v_status := case when v_pct >= v_threshold then 'passed' else 'failed' end;
  -- The cert vouches for the config the run actually TESTED (C3).
  v_fp := coalesce(v_run.config_fingerprint, public.de_config_fingerprint(p_de_id));

  insert into role_certifications (tenant_id, de_id, archetype_key, eval_run_id, score_pct, threshold_pct, status, evaluated_at, config_fingerprint)
  values (v_tenant, p_de_id, p_archetype_key, null, v_pct, v_threshold, v_status, now(), v_fp);

  return jsonb_build_object('status', v_status, 'score_pct', v_pct, 'threshold_pct', v_threshold,
                            'passed', v_run.passed, 'total', v_run.total, 'from', 'simulation');
end;
$function$;

CREATE OR REPLACE FUNCTION public.check_action_idempotency(p_tenant_id uuid, p_action_definition_id uuid, p_dedupe_key text)
 RETURNS TABLE(execution_id uuid, receipt text, executed_at timestamp with time zone)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select e.id, e.receipt, e.created_at
  from action_executions e
  where e.tenant_id = p_tenant_id
    and e.action_definition_id = p_action_definition_id
    and e.dedupe_key = p_dedupe_key
    and e.dedupe_key is not null
    and e.mode = 'execute'
    and e.decision in ('auto_executed', 'executed_after_approval')
    and e.rolled_back_at is null
  order by e.created_at desc
  limit 1;
$function$;

CREATE OR REPLACE FUNCTION public.check_de_budget(p_de_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_ceiling bigint; v_used numeric;
begin
  select monthly_ceiling_cents into v_ceiling from de_budget_policies where de_id = p_de_id;
  if v_ceiling is null or v_ceiling = 0 then
    return jsonb_build_object('allowed', true, 'ceiling_cents', 0, 'used_cents', 0);
  end if;
  -- Cost this month = tokens x model price (ai_model_pricing is $/1M tok),
  -- converted to cents. Unknown model -> priced at 0 (no false block).
  select coalesce(sum(
           (u.input_tokens::numeric / 1000000) * coalesce(p.input_price_per_million, 0) * 100
         + (u.output_tokens::numeric / 1000000) * coalesce(p.output_price_per_million, 0) * 100
         ), 0)
    into v_used
  from de_token_usage u
  left join ai_model_pricing p on p.model_id = u.model_id
  where u.de_id = p_de_id and u.created_at >= date_trunc('month', now());
  return jsonb_build_object('allowed', v_used < v_ceiling, 'ceiling_cents', v_ceiling, 'used_cents', round(v_used));
end;
$function$;

CREATE OR REPLACE FUNCTION public.check_de_retirement_readiness(p_de_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_tenant uuid;
  v_de digital_employees;
  v_open_tasks integer;
  v_pending_actions integer;
  v_playbook_assignments integer;
  v_active_charter_bindings integer;
  v_consulted_by integer;
  v_blockers jsonb := '[]'::jsonb;
begin
  v_tenant := auth_tenant_id();
  if v_tenant is null then raise exception 'not a member of any tenant'; end if;
  if not auth_has_tenant_role(array['tenant_owner', 'tenant_admin']) then raise exception 'only workspace owners/admins can check retirement readiness'; end if;

  select * into v_de from digital_employees where id = p_de_id and tenant_id = v_tenant and public.can_access_de(id);
  if v_de.id is null then raise exception 'employee not found in this workspace'; end if;

  select count(*) into v_open_tasks
  from human_tasks
  where tenant_id = v_tenant and status = 'open' and related_table = 'de_conversations'
    and related_id in (select id from de_conversations where de_id = p_de_id);

  select count(*) into v_pending_actions
  from action_executions ae
  join human_tasks ht on ht.id = ae.task_id
  where ae.tenant_id = v_tenant and ae.subject_kind = 'de' and ae.subject_id = p_de_id
    and ae.decision in ('human_gated_destructive', 'human_gated_trust') and ht.status = 'open';

  select count(*) into v_playbook_assignments
  from de_playbook_assignments where tenant_id = v_tenant and digital_employee_id = p_de_id;

  select count(*) into v_active_charter_bindings
  from de_playbook_charter where tenant_id = v_tenant and de_id = p_de_id and active;

  select count(*) into v_consulted_by
  from de_consultation_grants where tenant_id = v_tenant and target_de_id = p_de_id and active;

  if v_open_tasks > 0 then
    v_blockers := v_blockers || jsonb_build_object('kind', 'open_conversations', 'count', v_open_tasks,
      'message', format('%s open escalation(s) from conversations this employee is party to — resolve them first.', v_open_tasks));
  end if;
  if v_pending_actions > 0 then
    v_blockers := v_blockers || jsonb_build_object('kind', 'pending_approvals', 'count', v_pending_actions,
      'message', format('%s action(s) awaiting human approval — decide them first.', v_pending_actions));
  end if;
  if v_playbook_assignments > 0 then
    v_blockers := v_blockers || jsonb_build_object('kind', 'playbook_assignments', 'count', v_playbook_assignments,
      'message', format('Assigned to %s playbook(s) — reassign or remove those assignments first.', v_playbook_assignments));
  end if;
  if v_active_charter_bindings > 0 then
    v_blockers := v_blockers || jsonb_build_object('kind', 'active_charter_bindings', 'count', v_active_charter_bindings,
      'message', format('%s active playbook charter binding(s) — deactivate them first.', v_active_charter_bindings));
  end if;
  if v_consulted_by > 0 then
    v_blockers := v_blockers || jsonb_build_object('kind', 'consulted_by_other_des', 'count', v_consulted_by,
      'message', format('%s other employee(s) are configured to consult this one — remove those consultation grants first.', v_consulted_by));
  end if;

  return jsonb_build_object(
    'de_id', p_de_id, 'ready', jsonb_array_length(v_blockers) = 0,
    'open_conversations', v_open_tasks, 'pending_approvals', v_pending_actions,
    'playbook_assignments', v_playbook_assignments, 'active_charter_bindings', v_active_charter_bindings,
    'consulted_by_other_des', v_consulted_by,
    'blockers', v_blockers
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.check_dispatch_failures()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_failed  int;
  v_total   int;
  v_sample  text;
BEGIN
  SELECT count(*) FILTER (WHERE error_msg IS NOT NULL OR status_code >= 400),
         count(*),
         max(error_msg) FILTER (WHERE error_msg IS NOT NULL)
    INTO v_failed, v_total, v_sample
    FROM net._http_response
   WHERE created > now() - interval '1 hour';

  IF v_failed = 0 THEN
    RETURN jsonb_build_object('ok', true, 'checked', v_total, 'failed', 0);
  END IF;

  -- ops_alerts, not de_incidents: a dispatcher timing out is infrastructure, and
  -- attributing it to whichever tenant happened to trigger it would be wrong.
  -- ops_alerts has no tenant_id, which is exactly right for a platform fault.
  INSERT INTO ops_alerts (kind, message, detail, created_at)
  SELECT 'dispatch_failure',
         format('%s of %s background dispatches failed in the last hour', v_failed, v_total),
         jsonb_build_object(
           'failed', v_failed, 'total', v_total, 'sample_error', v_sample,
           'by_function', coalesce((
             select jsonb_object_agg(coalesce(d.fn, '(unattributed)'), c) from (
               select d.fn, count(*) c from net._http_response r
               left join dispatch_log d on d.request_id = r.id
                where r.created > now() - interval '1 hour'
                  and (r.error_msg is not null or r.status_code >= 400)
                group by d.fn) d), '{}'::jsonb),
           'status_codes', coalesce((
             select jsonb_object_agg(coalesce(sc::text, 'timeout'), c) from (
               select status_code sc, count(*) c from net._http_response
                where created > now() - interval '1 hour'
                  and (error_msg is not null or status_code >= 400)
                group by status_code) s), '{}'::jsonb),
           'attribution', case when exists (select 1 from dispatch_log
                                   where created_at > now() - interval '1 hour')
                                then 'ok' else 'unavailable — is the net_dispatch_log trigger still installed?' end,
           'severity', CASE WHEN v_failed::numeric / greatest(v_total, 1) > 0.25
                            THEN 'high' ELSE 'medium' END),
         now()
  WHERE NOT EXISTS (
    -- One alert per hour, not one per failed call. Unresolved ones only, so a
    -- recurring fault re-alerts once it has been acknowledged and closed.
    SELECT 1 FROM ops_alerts
     WHERE kind = 'dispatch_failure'
       AND created_at > now() - interval '1 hour'
       AND resolved_at IS NULL);

  RETURN jsonb_build_object('ok', false, 'checked', v_total, 'failed', v_failed);
END $function$;

CREATE OR REPLACE FUNCTION public.check_idle_in_transaction_internal()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  v_threshold interval := interval '5 minutes';
  v_count int; v_worst interval; v_worst_pid int; v_app text; v_xmin_age bigint;
BEGIN
  -- 'idle in transaction (aborted)' counts too: an aborted transaction still
  -- holds its locks and still pins xmin until the client rolls back.
  SELECT count(*), max(now() - state_change)
    INTO v_count, v_worst
    FROM pg_stat_activity
   WHERE state IN ('idle in transaction', 'idle in transaction (aborted)')
     AND pid <> pg_backend_pid()
     AND now() - state_change > v_threshold;

  IF coalesce(v_count, 0) = 0 THEN RETURN 'ok — none idle in transaction'; END IF;

  SELECT pid, coalesce(application_name, '(unnamed)')
    INTO v_worst_pid, v_app
    FROM pg_stat_activity
   WHERE state IN ('idle in transaction', 'idle in transaction (aborted)')
     AND pid <> pg_backend_pid()
   ORDER BY state_change ASC LIMIT 1;

  -- The wider harm: how far behind the oldest pinned snapshot is. This is what
  -- stops VACUUM reclaiming, database-wide, and it is the number that makes the
  -- alert worth acting on rather than merely noting.
  SELECT max(age(backend_xmin)) INTO v_xmin_age FROM pg_stat_activity;

  -- One banner per incident. Resolving it re-arms the check.
  IF EXISTS (SELECT 1 FROM ops_alerts
              WHERE kind = 'idle_in_transaction' AND resolved_at IS NULL) THEN
    RETURN format('still stuck (%s), alert already open', v_worst);
  END IF;

  PERFORM raise_ops_alert(
    'idle_in_transaction',
    format('%s database connection(s) idle in transaction — oldest %s (pid %s, %s). '
           || 'This holds locks AND blocks VACUUM database-wide until it ends.',
           v_count, v_worst, v_worst_pid, v_app),
    jsonb_build_object(
      'count', v_count, 'oldest', v_worst::text, 'pid', v_worst_pid,
      'application_name', v_app, 'oldest_xmin_age', v_xmin_age,
      'threshold', v_threshold::text,
      'remedy', 'Investigate the client, then: select pg_terminate_backend(<pid>)'));

  RETURN format('alert raised — %s stuck, oldest %s', v_count, v_worst);
END $function$;

CREATE OR REPLACE FUNCTION public.check_ip_against_tenant_allowlist(p_tenant_id uuid, p_ip text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_enabled boolean;
  v_matched boolean;
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'check_ip_against_tenant_allowlist is service-role only';
  end if;

  select enabled into v_enabled from tenant_ip_allowlists where tenant_id = p_tenant_id;
  if v_enabled is not true then
    return jsonb_build_object('allowed', true, 'reason', 'not_enabled');
  end if;

  select exists(
    select 1 from tenant_ip_allowlist_entries e
    where e.tenant_id = p_tenant_id and p_ip::inet <<= e.ip_range
  ) into v_matched;

  return jsonb_build_object('allowed', v_matched, 'reason', case when v_matched then 'matched' else 'no_match' end);
exception when others then
  return jsonb_build_object('allowed', true, 'reason', 'error_fail_open');
end;
$function$;

CREATE OR REPLACE FUNCTION public.check_staleness(p_tenant_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_policy   record;
  v_proj     record;
  v_task     record;
  v_inv      record;
  v_open     record;
  v_warned   integer := 0;
  v_breached integer := 0;
  v_resolved integer := 0;
  v_acct     text;
begin
  for v_policy in
    select * from staleness_policies sp
    where sp.enabled
      and (p_tenant_id is null or sp.tenant_id = p_tenant_id)
      and is_feature_enabled_internal(sp.tenant_id, 'staleness_watchdog')
      -- Mig 545: a suspended workspace is dormant. Without this the watchdog
      -- kept minting "Review overdue" escalations for suspended tenants
      -- (observed on acme-telecom for three days after mig 430) because the
      -- backlog it nags about does not disappear when the tenant is suspended.
      and tenant_is_operational(sp.tenant_id)
  loop

    if v_policy.target_kind = 'onboarding_project' then
      for v_proj in
        select op.id, op.name, op.updated_at, op.account_id
        from onboarding_projects op
        where op.tenant_id = v_policy.tenant_id
          and op.status = 'active'
      loop
        select name into v_acct from customer_accounts
          where id = v_proj.account_id and tenant_id = v_policy.tenant_id;

        if now() - v_proj.updated_at >= v_policy.breach_after then
          if stale_upsert_escalation(
            v_policy.tenant_id, 'onboarding_project', v_proj.id, 'breach',
            format('Onboarding stalled — %s', v_proj.name),
            format('This onboarding project for %s hasn''t been touched in %s (breach threshold: %s).',
                   coalesce(v_acct, v_proj.name), stale_humanize_interval(now() - v_proj.updated_at),
                   stale_humanize_interval(v_policy.breach_after)),
            'onboarding_projects', v_proj.id
          ) is not null then v_breached := v_breached + 1; end if;
        elsif now() - v_proj.updated_at >= v_policy.warning_after then
          if stale_upsert_escalation(
            v_policy.tenant_id, 'onboarding_project', v_proj.id, 'warning',
            format('Onboarding going quiet — %s', v_proj.name),
            format('This onboarding project for %s hasn''t been touched in %s (warning threshold: %s).',
                   coalesce(v_acct, v_proj.name), stale_humanize_interval(now() - v_proj.updated_at),
                   stale_humanize_interval(v_policy.warning_after)),
            'onboarding_projects', v_proj.id
          ) is not null then v_warned := v_warned + 1; end if;
        end if;
      end loop;

      for v_open in
        select se.id, se.target_id
        from staleness_escalations se
        where se.tenant_id = v_policy.tenant_id
          and se.target_kind = 'onboarding_project'
          and se.resolved_at is null
      loop
        if not exists (
          select 1 from onboarding_projects op
          where op.id = v_open.target_id and op.tenant_id = v_policy.tenant_id
            and op.status = 'active'
            and now() - op.updated_at >= v_policy.warning_after
        ) then
          update staleness_escalations set resolved_at = now() where id = v_open.id;
          v_resolved := v_resolved + 1;
        end if;
      end loop;

    elsif v_policy.target_kind = 'pending_review_task' then
      for v_task in
        select ht.id, ht.title, ht.created_at, ht.type
        from human_tasks ht
        where ht.tenant_id = v_policy.tenant_id
          and ht.status = 'pending'
          and ht.type in ('inquiry_review', 'action_approval', 'checklist', 'review_gate', 'approval_gate')
      loop
        if now() - v_task.created_at >= v_policy.breach_after then
          if stale_upsert_escalation(
            v_policy.tenant_id, 'pending_review_task', v_task.id, 'breach',
            format('Review overdue — %s', v_task.title),
            format('This %s has been waiting %s for a human decision (breach threshold: %s).',
                   replace(v_task.type, '_', ' '), stale_humanize_interval(now() - v_task.created_at),
                   stale_humanize_interval(v_policy.breach_after)),
            'human_tasks', v_task.id
          ) is not null then v_breached := v_breached + 1; end if;
        elsif now() - v_task.created_at >= v_policy.warning_after then
          if stale_upsert_escalation(
            v_policy.tenant_id, 'pending_review_task', v_task.id, 'warning',
            format('Review waiting — %s', v_task.title),
            format('This %s has been waiting %s for a human decision (warning threshold: %s).',
                   replace(v_task.type, '_', ' '), stale_humanize_interval(now() - v_task.created_at),
                   stale_humanize_interval(v_policy.warning_after)),
            'human_tasks', v_task.id
          ) is not null then v_warned := v_warned + 1; end if;
        end if;
      end loop;

      for v_open in
        select se.id, se.target_id
        from staleness_escalations se
        where se.tenant_id = v_policy.tenant_id
          and se.target_kind = 'pending_review_task'
          and se.resolved_at is null
      loop
        if not exists (
          select 1 from human_tasks ht
          where ht.id = v_open.target_id and ht.tenant_id = v_policy.tenant_id
            and ht.status = 'pending'
        ) then
          update staleness_escalations set resolved_at = now() where id = v_open.id;
          v_resolved := v_resolved + 1;
        end if;
      end loop;

    elsif v_policy.target_kind = 'overdue_invoice_unattended' then
      for v_inv in
        select ri.id, ri.account_id, ri.amount_cents, ri.due_date, ca.name as account_name
        from renewal_invoices ri
        join customer_accounts ca on ca.id = ri.account_id and ca.tenant_id = v_policy.tenant_id
        where ri.tenant_id = v_policy.tenant_id
          and ri.status in ('sent', 'awaiting_approval')
          and ri.due_date is not null
      loop
        if (current_date - v_inv.due_date) * interval '1 day' >= v_policy.breach_after then
          if stale_upsert_escalation(
            v_policy.tenant_id, 'overdue_invoice_unattended', v_inv.id, 'breach',
            format('Invoice seriously overdue — %s', v_inv.account_name),
            format('Invoice for %s (%s cents) has been overdue since %s — %s past due (breach threshold: %s).',
                   v_inv.account_name, v_inv.amount_cents, v_inv.due_date,
                   stale_humanize_interval((current_date - v_inv.due_date) * interval '1 day'),
                   stale_humanize_interval(v_policy.breach_after)),
            'renewal_invoices', v_inv.id
          ) is not null then v_breached := v_breached + 1; end if;
        elsif (current_date - v_inv.due_date) * interval '1 day' >= v_policy.warning_after then
          if stale_upsert_escalation(
            v_policy.tenant_id, 'overdue_invoice_unattended', v_inv.id, 'warning',
            format('Invoice overdue — %s', v_inv.account_name),
            format('Invoice for %s (%s cents) has been overdue since %s — %s past due (warning threshold: %s).',
                   v_inv.account_name, v_inv.amount_cents, v_inv.due_date,
                   stale_humanize_interval((current_date - v_inv.due_date) * interval '1 day'),
                   stale_humanize_interval(v_policy.warning_after)),
            'renewal_invoices', v_inv.id
          ) is not null then v_warned := v_warned + 1; end if;
        end if;
      end loop;

      for v_open in
        select se.id, se.target_id
        from staleness_escalations se
        where se.tenant_id = v_policy.tenant_id
          and se.target_kind = 'overdue_invoice_unattended'
          and se.resolved_at is null
      loop
        if not exists (
          select 1 from renewal_invoices ri
          where ri.id = v_open.target_id and ri.tenant_id = v_policy.tenant_id
            and ri.status in ('sent', 'awaiting_approval')
        ) then
          update staleness_escalations set resolved_at = now() where id = v_open.id;
          v_resolved := v_resolved + 1;
        end if;
      end loop;

    end if;
  end loop;

  return jsonb_build_object('warned', v_warned, 'breached', v_breached, 'resolved', v_resolved);
end;
$function$;

CREATE OR REPLACE FUNCTION public.check_tenant_ai_budget(p_tenant_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_budget  integer;
  v_used    bigint;
  v_allowed boolean;
  v_period  text := to_char(date_trunc('month', now()), 'YYYY-MM');
  v_kind    text;
  v_name    text;
begin
  select monthly_token_budget, name into v_budget, v_name
    from tenants where id = p_tenant_id;

  -- null / <= 0 means "no ceiling" — unchanged behaviour.
  if v_budget is null or v_budget <= 0 then
    return jsonb_build_object('allowed', true, 'used', 0, 'budget', v_budget);
  end if;

  v_used   := get_tenant_token_usage_this_month(p_tenant_id);
  v_allowed := v_used < v_budget;

  if v_used >= (v_budget::numeric * 0.8) then
    v_kind := case when v_allowed then 'ai_budget_approaching' else 'ai_budget_exhausted' end;

    insert into ops_alerts (kind, message, detail)
    select
      v_kind,
      case when v_allowed
        then format('%s has used %s%% of its monthly AI budget (%s of %s tokens).',
                    coalesce(v_name, 'A tenant'),
                    round((v_used::numeric / v_budget) * 100),
                    v_used, v_budget)
        else format('%s has EXHAUSTED its monthly AI budget (%s of %s tokens). Its digital employees have stopped answering.',
                    coalesce(v_name, 'A tenant'), v_used, v_budget)
      end,
      jsonb_build_object(
        'tenant_id', p_tenant_id,
        'tenant_name', v_name,
        'period', v_period,
        'used', v_used,
        'budget', v_budget
      )
    where not exists (
      select 1 from ops_alerts a
       where a.kind = v_kind
         and a.detail->>'tenant_id' = p_tenant_id::text
         and a.detail->>'period' = v_period
         -- Budget is part of the key (mig 468): 80% of a different number
         -- is a different fact, so raising or lowering the ceiling re-arms
         -- the warning. Without this the alert goes quiet for the rest of
         -- the month exactly when the ceiling has just moved.
         and a.detail->>'budget' = v_budget::text
    );
  end if;

  return jsonb_build_object('allowed', v_allowed, 'used', v_used, 'budget', v_budget);
end;
$function$;

CREATE OR REPLACE FUNCTION public.check_unit_rest_tripwires()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_t record;
  v_u record;
  v_kind text;
  v_evaluated int := 0;
  v_tripped int := 0;
  v_written int := 0;
begin
  for v_t in select t.id, t.name from tenants t where tenant_is_operational(t.id) loop
    for v_u in
      select de.archetype_key,
             count(*) as n_emp,
             min(de.created_at) as unit_born,
             greatest(
               max(w.last_done),
               max(dl.last_deliv),
               max(c.last_convo)
             ) as last_receipt
        from digital_employees de
        left join lateral (
          select max(updated_at) as last_done from de_work_items
           where de_id = de.id and status = 'done'
        ) w on true
        left join lateral (
          select max(created_at) as last_deliv from de_deliverables
           where de_id = de.id
        ) dl on true
        left join lateral (
          select max(created_at) as last_convo from de_conversations
           where de_id = de.id and channel <> 'exam'
        ) c on true
       where de.tenant_id = v_t.id
         and de.archetype_key is not null
         and de.lifecycle_status in ('active','published','improving')
       group by de.archetype_key
    loop
      v_evaluated := v_evaluated + 1;

      -- Young units are exempt; a receipt inside 90 days clears the wire.
      if v_u.unit_born > now() - interval '90 days' then continue; end if;
      if v_u.last_receipt is not null and v_u.last_receipt > now() - interval '90 days' then continue; end if;

      v_tripped := v_tripped + 1;
      v_kind := 'unit_rest_tripwire_' || v_u.archetype_key || '_' || left(v_t.id::text, 8);
      -- One raise per quarter, decided or not: CONTINUE means "check again
      -- in another 90 days", and that is exactly what this window does.
      if exists (select 1 from ops_alerts
                  where kind = v_kind and created_at > now() - interval '90 days') then
        continue;
      end if;

      insert into ops_alerts (kind, message, detail)
      values (v_kind,
        format('Unit tripwire — %s / %s: %s employee(s), no production receipt in 90+ days (last: %s). Decide: CONTINUE (build its demand) or REST the unit. Units rest, never close.',
          v_t.name, v_u.archetype_key, v_u.n_emp,
          coalesce(to_char(v_u.last_receipt, 'YYYY-MM-DD'), 'never')),
        jsonb_build_object('tripwire', 'unit_rest_90d',
          'tenant_id', v_t.id, 'tenant_name', v_t.name,
          'unit', v_u.archetype_key, 'employees', v_u.n_emp,
          'unit_oldest_hire', v_u.unit_born,
          'last_production_receipt', v_u.last_receipt,
          'receipt_definition', 'done work item | deliverable | non-exam conversation (same as the weekly digest)',
          'options', jsonb_build_array('continue: invest in demand for this unit', 'rest: pause the unit — never close')));
      v_written := v_written + 1;
    end loop;
  end loop;

  return jsonb_build_object('units_evaluated', v_evaluated,
                            'tripped', v_tripped, 'alerts_written', v_written);
end; $function$;

CREATE OR REPLACE FUNCTION public.check_workforce_circuit_breaker()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  r          record;
  v_since    timestamptz;
  v_perf     int; v_considered int; v_blocked int; v_incidents int;
  v_inc_pct  numeric; v_blk_pct numeric;
  v_why      text;
  v_tripped  int := 0;
  v_checked  int := 0;
begin
  for r in
    -- ⚠ TENANTS FIRST, posture second. 624 had this the other way round and so
    -- guarded only workspaces that already had a row — which was none of them.
    select
      t.id                                        as tenant_id,
      coalesce(p.breaker_enabled, true)           as breaker_enabled,
      coalesce(p.autonomy_paused, false)          as autonomy_paused,
      coalesce(p.breaker_window_hours, 24)        as breaker_window_hours,
      coalesce(p.breaker_min_actions, 10)         as breaker_min_actions,
      coalesce(p.breaker_incident_pct, 20)        as breaker_incident_pct,
      coalesce(p.breaker_block_pct, 30)           as breaker_block_pct
    from tenants t
    left join workforce_trust_posture p on p.tenant_id = t.id
    where tenant_is_operational(t.id)
      and coalesce(p.breaker_enabled, true)      -- a workspace may opt OUT
      and not coalesce(p.autonomy_paused, false) -- already stopped; nothing to trip
  loop
    v_checked := v_checked + 1;
    v_since := now() - make_interval(hours => r.breaker_window_hours);

    select
      count(*) filter (where decision in ('auto_executed','executed_after_approval')),
      count(*) filter (where decision in ('auto_executed','executed_after_approval',
                                          'human_gated_destructive','human_gated_trust','guardrail_blocked')),
      count(*) filter (where decision = 'guardrail_blocked')
    into v_perf, v_considered, v_blocked
    from action_executions
    where tenant_id = r.tenant_id and created_at >= v_since;

    select count(*) into v_incidents
    from de_incidents where tenant_id = r.tenant_id and occurred_at >= v_since;

    v_why := null;

    if v_perf >= r.breaker_min_actions then
      v_inc_pct := round((v_incidents::numeric / v_perf) * 100, 1);
      if v_inc_pct >= r.breaker_incident_pct then
        v_why := format('%s incidents against %s actions in %sh (%s%% — limit %s%%)',
                        v_incidents, v_perf, r.breaker_window_hours, v_inc_pct, r.breaker_incident_pct);
      end if;
    end if;

    if v_why is null and v_considered >= r.breaker_min_actions then
      v_blk_pct := round((v_blocked::numeric / v_considered) * 100, 1);
      if v_blk_pct >= r.breaker_block_pct then
        v_why := format('%s guardrail blocks against %s decisions in %sh (%s%% — limit %s%%)',
                        v_blocked, v_considered, r.breaker_window_hours, v_blk_pct, r.breaker_block_pct);
      end if;
    end if;

    if v_why is not null then
      -- The row is created HERE if it did not exist — the trip is what makes a
      -- workspace's posture explicit, not a prerequisite for being guarded.
      insert into workforce_trust_posture (tenant_id, autonomy_paused, paused_at,
                                           paused_reason, breaker_tripped_at, breaker_tripped_why)
      values (r.tenant_id, true, now(), 'Stopped automatically: ' || v_why, now(), v_why)
      on conflict (tenant_id) do update set
        autonomy_paused = true, paused_at = now(), paused_by = null,
        paused_reason = 'Stopped automatically: ' || v_why,
        breaker_tripped_at = now(), breaker_tripped_why = v_why, updated_at = now();

      perform raise_ops_alert(r.tenant_id, 'workforce_autonomy_breaker',
        'Workforce autonomy stopped automatically', v_why);

      perform append_audit_event(r.tenant_id, 'Circuit breaker', 'system',
        format('Workforce autonomy STOPPED automatically — %s', v_why),
        'config_change',
        jsonb_build_object('kind', 'workforce_autonomy_breaker', 'why', v_why));

      v_tripped := v_tripped + 1;
    end if;
  end loop;

  return jsonb_build_object('checked', v_checked, 'tripped', v_tripped);
end;
$function$;

CREATE OR REPLACE FUNCTION public.check_workforce_heartbeat(p_stall_minutes integer DEFAULT 30)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  t record;
  v_due int; v_claimable int; v_recent int; v_awaiting_human int; v_probe_err text;
  v_checked int := 0;
  v_stalled    jsonb := '[]'::jsonb;
  v_broken     jsonb := '[]'::jsonb;
  v_deadlock   jsonb := '[]'::jsonb;
  v_on_people  jsonb := '[]'::jsonb;
BEGIN
  FOR t IN SELECT id, slug FROM tenants WHERE tenant_is_operational(id) LOOP
    v_checked := v_checked + 1;

    SELECT count(*),
           count(*) FILTER (WHERE w.depends_on IS NULL
                              OR EXISTS (SELECT 1 FROM de_work_items d
                                          WHERE d.id = w.depends_on AND d.status = 'done'))
      INTO v_due, v_claimable
      FROM de_work_items w
      JOIN digital_employees de ON de.id = w.de_id
     WHERE w.tenant_id = t.id
       AND w.status = 'queued'
       AND w.scheduled_for <= now()
       AND de.status = 'active'
       AND de.lifecycle_status NOT IN ('paused', 'retired', 'archived');

    CONTINUE WHEN v_due = 0;  -- nothing to do; silence is correct

    SELECT count(*) INTO v_recent
      FROM de_work_items w
     WHERE w.tenant_id = t.id AND w.status IN ('done', 'failed')
       AND w.updated_at > now() - make_interval(mins => greatest(5, p_stall_minutes));

    IF v_claimable = 0 THEN
      SELECT count(*) INTO v_awaiting_human
        FROM de_work_items w WHERE w.tenant_id = t.id AND w.status = 'waiting_human';

      IF v_awaiting_human > 0 THEN
        -- Blocked on people. REPORTED ALWAYS — it is a fact about the queue and
        -- costs nothing to state — but never alarmed: the escalation queue is
        -- where somebody is already looking, and the stall sweep raises anything
        -- left unanswered. Reporting does not depend on recent completions,
        -- because "did something finish in the last half hour" says nothing
        -- about whether the queue is now waiting on a human.
        v_on_people := v_on_people || jsonb_build_object(
          'tenant', t.slug, 'due', v_due, 'awaiting_human', v_awaiting_human);
      ELSIF v_recent = 0 THEN
        -- Nothing can be picked up, nobody has been asked, and nothing is
        -- finishing. Wedged. This one is the alarm.
        v_deadlock := v_deadlock || jsonb_build_object('tenant', t.slug, 'due', v_due);
      END IF;
      CONTINUE;  -- nothing to probe: the claim has nothing to hand out
    END IF;

    v_probe_err := NULL;
    BEGIN
      PERFORM * FROM claim_de_work_items(1, 'heartbeat-probe', t.id);
      RAISE EXCEPTION 'heartbeat_probe_rollback';
    EXCEPTION WHEN OTHERS THEN
      IF SQLERRM <> 'heartbeat_probe_rollback' THEN v_probe_err := SQLERRM; END IF;
    END;

    IF v_probe_err IS NOT NULL THEN
      v_broken := v_broken || jsonb_build_object('tenant', t.slug, 'claimable', v_claimable, 'error', left(v_probe_err, 300));
    ELSIF v_recent = 0 THEN
      v_stalled := v_stalled || jsonb_build_object('tenant', t.slug, 'claimable', v_claimable);
    END IF;
  END LOOP;

  IF jsonb_array_length(v_broken) > 0 THEN
    PERFORM raise_ops_alert('workforce_claim_broken',
      format('The work queue cannot be claimed in %s tenant(s) — no employee can pick up work', jsonb_array_length(v_broken)),
      jsonb_build_object('tenants', v_broken));
  END IF;

  IF jsonb_array_length(v_stalled) > 0 THEN
    PERFORM raise_ops_alert('workforce_stalled',
      format('%s tenant(s) have work ready but nothing has completed in %s minutes', jsonb_array_length(v_stalled), p_stall_minutes),
      jsonb_build_object('tenants', v_stalled, 'window_minutes', p_stall_minutes));
  END IF;

  IF jsonb_array_length(v_deadlock) > 0 THEN
    PERFORM raise_ops_alert('workforce_deadlocked',
      format('%s tenant(s) have work due that nothing can pick up, and no one has been asked to unblock it', jsonb_array_length(v_deadlock)),
      jsonb_build_object('tenants', v_deadlock, 'window_minutes', p_stall_minutes));
  END IF;

  -- Raise AND clear in one pass. An alert nobody closes buries the next real
  -- one, and the next real one here means no employee can pick up work.
  PERFORM resolve_cleared_ops_alerts(jsonb_build_object(
    'claim_broken', v_broken, 'stalled', v_stalled, 'deadlocked', v_deadlock));

  RETURN jsonb_build_object('ok', true, 'tenants_checked', v_checked,
    'claim_broken', v_broken, 'stalled', v_stalled,
    'deadlocked', v_deadlock, 'blocked_on_people', v_on_people);
END $function$;

CREATE OR REPLACE FUNCTION public.chunk_doc_text_internal(p_text text)
 RETURNS text[]
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare
  v_clean text := regexp_replace(coalesce(p_text, ''), '^\s+|\s+$', '', 'g');
  v_len   int;
  v_out   text[] := '{}';
  v_start int := 0;
  v_end   int;
  v_window text;
  v_para  int; v_sent int; v_space int; v_cut int;
  v_piece text;
begin
  if v_clean = '' then return v_out; end if;
  v_len := length(v_clean);
  if v_len <= 1500 then return array[v_clean]; end if;

  while v_start < v_len loop
    v_end := least(v_start + 1500, v_len);
    if v_end < v_len then
      v_window := substr(v_clean, v_start + 1, 1500);
      v_para := public.last_index_of_internal(v_window, chr(10) || chr(10));
      v_sent := greatest(
        public.last_index_of_internal(v_window, '. '),
        public.last_index_of_internal(v_window, '.' || chr(10)),
        public.last_index_of_internal(v_window, '! '),
        public.last_index_of_internal(v_window, '? '));
      v_space := public.last_index_of_internal(v_window, ' ');
      v_cut := case
        when v_para  > 600 then v_para
        when v_sent  > 600 then v_sent + 1
        when v_space > 600 then v_space
        else length(v_window)
      end;
      v_end := v_start + v_cut;
    end if;
    v_piece := regexp_replace(substr(v_clean, v_start + 1, v_end - v_start), '^\s+|\s+$', '', 'g');
    if v_piece <> '' then v_out := v_out || v_piece; end if;
    exit when v_end >= v_len;
    v_start := greatest(v_end - 200, v_start + 1);
  end loop;
  return v_out;
end $function$;

CREATE OR REPLACE FUNCTION public.chunk_knowledge_doc_internal(p_doc_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
AS $function$
declare
  d record;
  v_text  text;
  v_parts text[];
  v_n     int;
begin
  select id, tenant_id, account_id, title, content into d
    from knowledge_docs where id = p_doc_id;
  if d.id is null then
    raise warning 'chunk_knowledge_doc_internal: doc % not found', p_doc_id;
    return 0;
  end if;

  select count(*) into v_n from knowledge_doc_chunks where doc_id = d.id;
  if v_n > 0 then return v_n; end if;

  v_text  := coalesce(d.title, '') || chr(10) || chr(10) || coalesce(d.content, '');
  v_parts := public.chunk_doc_text_internal(v_text);
  if coalesce(array_length(v_parts, 1), 0) = 0 then return 0; end if;

  insert into knowledge_doc_chunks (tenant_id, account_id, doc_id, chunk_index, content, embedding)
  select d.tenant_id, d.account_id, d.id, i - 1, v_parts[i], null
    from generate_subscripts(v_parts, 1) as i;

  update knowledge_docs
     set content_hash = public.normalized_content_hash_internal(v_text)
   where id = d.id;

  return array_length(v_parts, 1);
end $function$;

CREATE OR REPLACE FUNCTION public.claim_amendment_for_fitness(p_tenant_id uuid, p_amendment_id uuid, p_entity_kind text, p_entity_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_id uuid;
BEGIN
  INSERT INTO amendment_metrics (tenant_id, amendment_id, entity_kind, entity_id,
      before_metrics, replay_score_before, replay_score_after, adopted_at)
  VALUES (p_tenant_id, p_amendment_id, p_entity_kind, p_entity_id,
      '{}'::jsonb, null, null, now())
  ON CONFLICT (amendment_id) DO NOTHING
  RETURNING metric_id INTO v_id;
  RETURN jsonb_build_object('claimed', v_id IS NOT NULL);
END $function$;

CREATE OR REPLACE FUNCTION public.claim_computer_use_task(p_task_id uuid, p_runtime_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_row computer_use_tasks;
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'claim_computer_use_task is service-role only';
  end if;
  -- Atomic claim; the transition trigger re-verifies approval + runtime.
  update computer_use_tasks
     set status = 'claimed', runtime_id = p_runtime_id, updated_at = now()
   where id = p_task_id and status = 'approved'
   returning * into v_row;
  if v_row.id is null then raise exception 'task not claimable (not approved, already claimed, or missing)'; end if;
  return jsonb_build_object('task_id', v_row.id, 'goal', v_row.goal,
                            'allowed_domains', v_row.allowed_domains, 'max_steps', v_row.max_steps,
                            'constraints', v_row.constraints);
end;
$function$;

CREATE OR REPLACE FUNCTION public.claim_domain_verification_slot(p_tenant uuid, p_domain_id uuid DEFAULT NULL::uuid, p_domain text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
-- v_updated is separate from v_domain on purpose: PL/pgSQL sets an INTO target
-- to NULL when the statement returns no rows, so reusing v_domain as the
-- RETURNING target would erase the value read a few lines earlier and the
-- throttle message would name a blank domain.
DECLARE v_domain text; v_status text; v_updated text; v_id uuid;
BEGIN
  IF coalesce(auth.role(), '') <> 'service_role' THEN
    RAISE EXCEPTION 'domain verification runs from the backend only'
      USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF p_tenant IS NULL OR (p_domain_id IS NULL AND p_domain IS NULL) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_found');
  END IF;

  -- p_tenant comes from the caller's JWT as resolved by the edge function, and
  -- is matched here rather than trusted there. A bug in the edge function that
  -- passes somebody else's domain id therefore fails in SQL instead of
  -- verifying another workspace's domain. Note tenant_id is in BOTH branches.
  SELECT id, status, domain INTO v_id, v_status, v_domain
    FROM tenant_domains
   WHERE tenant_id = p_tenant
     AND (( p_domain_id IS NOT NULL AND id = p_domain_id)
       OR ( p_domain_id IS NULL AND domain = public.normalize_email_domain(p_domain)));
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_found');
  END IF;
  IF v_status = 'verified' THEN
    -- Idempotent: verifying an already-verified domain is a no-op, not a DNS
    -- query and not an error.
    RETURN jsonb_build_object('ok', false, 'reason', 'already_verified',
                              'status', 'verified', 'domain', v_domain,
                              'domain_id', v_id);
  END IF;

  UPDATE tenant_domains
     SET last_checked_at = now(),
         check_count     = check_count + 1,
         checks_today    = CASE WHEN checks_today_on IS DISTINCT FROM current_date
                                THEN 1 ELSE checks_today + 1 END,
         checks_today_on = current_date
   WHERE id = v_id
     AND tenant_id = p_tenant
     AND status <> 'verified'
     AND (last_checked_at IS NULL OR last_checked_at <= now() - interval '30 seconds')
     AND (checks_today_on IS DISTINCT FROM current_date OR checks_today < 50)
  RETURNING domain INTO v_updated;

  IF NOT FOUND THEN
    -- v_domain still holds the value read above, so the caller can name the
    -- domain in the "wait 30 seconds" message instead of showing a blank.
    RETURN jsonb_build_object('ok', false, 'reason', 'throttled',
                              'status', v_status, 'domain', v_domain,
                              'domain_id', v_id,
                              'record_name', public.tenant_domain_dns_record_name(v_domain));
  END IF;

  RETURN jsonb_build_object(
    'ok', true, 'domain', v_domain, 'domain_id', v_id,
    'record_name', public.tenant_domain_dns_record_name(v_domain));
END $function$;

CREATE OR REPLACE FUNCTION public.claim_gated_action_execution(p_tenant_id uuid, p_task_id uuid, p_execution_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_task_status text;
  v_new_id uuid;
  v_existing_id uuid;
  v_existing_receipt text;
begin
  -- Authoritative resolution signal — the human_task must be APPROVED (the
  -- action_executions.decision alone can't distinguish pending/approved/rejected).
  select status into v_task_status from human_tasks where id = p_task_id and tenant_id = p_tenant_id;
  if v_task_status is distinct from 'approved' then
    return jsonb_build_object('claimed', false, 'reason', 'task_not_approved');
  end if;

  -- Already executed for this task?
  select id, receipt into v_existing_id, v_existing_receipt
    from action_executions where resolves_task_id = p_task_id and decision <> 'failed' limit 1;
  if v_existing_id is not null then
    return jsonb_build_object('claimed', false, 'existing_id', v_existing_id, 'receipt', v_existing_receipt);
  end if;

  -- Claim: copy the gated row's fields into a new executed-placeholder row,
  -- guarded by the partial unique index. Concurrent/retry attempts collide.
  begin
    insert into action_executions (
      tenant_id, action_definition_id, connector_id, subject_kind, subject_id, mode, params,
      decision, destructive, idempotent, dedupe_key, request_summary,
      origin_kind, origin_id, resolves_task_id, receipt, result, task_id
    )
    select
      tenant_id, action_definition_id, connector_id, subject_kind, subject_id, mode, params,
      'executed_after_approval', destructive, idempotent, dedupe_key, request_summary,
      origin_kind, origin_id, p_task_id, null, null, null
    from action_executions
    where id = p_execution_id and tenant_id = p_tenant_id
    returning id into v_new_id;
  exception when unique_violation then
    select id, receipt into v_existing_id, v_existing_receipt
      from action_executions where resolves_task_id = p_task_id and decision <> 'failed' limit 1;
    return jsonb_build_object('claimed', false, 'existing_id', v_existing_id, 'receipt', v_existing_receipt);
  end;

  if v_new_id is null then
    return jsonb_build_object('claimed', false, 'reason', 'gated_row_not_found');
  end if;
  return jsonb_build_object('claimed', true, 'claim_row_id', v_new_id);
end $function$;

CREATE OR REPLACE FUNCTION public.claim_support_conversation(p_conversation_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_tenant uuid; v_de uuid;
begin
  v_tenant := _assert_conv_member(p_conversation_id);
  -- DE scoping (mig 385/407). Claiming a thread SILENCES the employee that
  -- was answering it, so this is an act on that employee, not just on the
  -- conversation. Null-tolerant to match the mig-386 policy.
  select de_id into v_de from de_conversations where id = p_conversation_id;
  if v_de is not null and not public.can_access_de(v_de) then
    raise exception 'not_responsible_for_de: this employee is not in your reporting line';
  end if;

  update de_conversations set owner_user_id = auth.uid(), status = 'human_owned', last_message_at = now()
  where id = p_conversation_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.claim_tenant_domain(p_domain text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_tenant uuid := public.auth_tenant_id();
  v_domain text;
  v_row    tenant_domains;
  v_count  integer;
  v_actor  text;
  v_existed boolean := false;
BEGIN
  IF v_tenant IS NULL THEN
    RAISE EXCEPTION 'not a member of any workspace' USING ERRCODE = 'insufficient_privilege';
  END IF;
  IF NOT public.can_admin_tenant_internal(v_tenant) THEN
    RAISE EXCEPTION 'only workspace owners and admins can claim a domain'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  -- Precise refusals. "invalid domain" makes an admin guess; each branch below
  -- tells them the one thing they have to change.
  IF p_domain IS NULL OR btrim(p_domain) = '' THEN
    RAISE EXCEPTION 'enter a domain, for example acme.com';
  END IF;
  IF p_domain ~ '[^\x01-\x7F]' THEN
    RAISE EXCEPTION 'internationalised domains must be entered in punycode form (for example xn--80ak6aa92e.com) — we do not convert unicode, because two spellings of one domain would defeat the one-workspace-per-domain rule';
  END IF;

  v_domain := public.normalize_email_domain(p_domain);

  IF public.is_bare_public_suffix(v_domain) THEN
    RAISE EXCEPTION '"%" is a public suffix, not a domain anyone can own', v_domain;
  END IF;
  IF NOT public.is_valid_email_domain(v_domain) THEN
    RAISE EXCEPTION '"%" is not a valid domain — enter the part after the @, for example acme.com', v_domain;
  END IF;
  IF public.is_public_email_domain(v_domain) THEN
    RAISE EXCEPTION '"%" is a public email provider and cannot be claimed by any workspace — verifying it would hand this workspace every future account at that provider', v_domain;
  END IF;

  SELECT count(*) INTO v_count FROM tenant_domains WHERE tenant_id = v_tenant;
  IF v_count >= 25 THEN
    RAISE EXCEPTION 'this workspace already has 25 claimed domains — remove one first';
  END IF;

  -- Idempotent: re-claiming returns the SAME token. Rotating it here would
  -- break an admin who has already published the TXT record and is waiting for
  -- DNS to propagate — the single most common way this flow is used.
  SELECT * INTO v_row FROM tenant_domains
   WHERE tenant_id = v_tenant AND domain = v_domain;

  IF FOUND THEN
    v_existed := true;
  ELSE
    -- verification_token deliberately omitted: the column DEFAULT is the only
    -- token minting site in the system.
    INSERT INTO tenant_domains (tenant_id, domain, created_by)
    VALUES (v_tenant, v_domain, auth.uid())
    RETURNING * INTO v_row;

    SELECT coalesce(full_name, 'a workspace admin') INTO v_actor
      FROM profiles WHERE user_id = auth.uid();
    PERFORM public.append_audit_event_internal(
      v_tenant, coalesce(v_actor, 'a workspace admin'), 'human',
      format('Claimed the email domain %s (unverified)', v_domain),
      'config_change',
      jsonb_build_object('kind', 'tenant_domain_claimed', 'domain', v_domain,
                         'domain_id', v_row.id));
  END IF;

  -- NOTE what is NOT returned: whether some other workspace already verified
  -- this domain. Telling an anonymous-signup caller that would turn this RPC
  -- into a customer-list enumeration oracle. They find out at verification
  -- time — at which point they have proved they control the domain, so telling
  -- them is safe. See record_domain_verification_attempt.
  RETURN jsonb_build_object(
    'id', v_row.id,
    'domain', v_row.domain,
    'status', v_row.status,
    'already_claimed', v_existed,
    'record_type', 'TXT',
    'record_name', public.tenant_domain_dns_record_name(v_row.domain),
    'record_value', v_row.verification_token
  );
END $function$;

CREATE OR REPLACE FUNCTION public.classify_sentiment_text(p_text text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
DECLARE v text := lower(coalesce(p_text, ''));
BEGIN
  IF v ~ 'cancel my|switch to|competitor|leaving you|close my account|no longer want|take my business' THEN RETURN 'churn_risk'; END IF;
  IF v ~ 'unacceptable|furious|ridiculous|worst|terrible|outrageous|disgusted|so angry|fed up' THEN RETURN 'angry'; END IF;
  IF v ~ 'still not|yet again|third time|keep failing|frustrat|annoyed|why is this|not working again' THEN RETURN 'frustrated'; END IF;
  IF v ~ 'urgent|asap|deadline|worried|concerned|losing money|at risk|time-sensitive' THEN RETURN 'anxious'; END IF;
  IF v ~ 'confus|do not understand|don''t understand|not sure how|unclear|how do i|where do i' THEN RETURN 'confused'; END IF;
  IF v ~ 'thank you|thanks|great|awesome|perfect|works now|resolved|appreciate|much better' THEN RETURN 'satisfied'; END IF;
  RETURN 'neutral';
END; $function$;

CREATE OR REPLACE FUNCTION public.classify_support_text(p_tenant_id uuid, p_text text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  r        support_triage_rules;
  v_hit    support_triage_rules;
  v_low    text := lower(coalesce(p_text, ''));
  frag     text;
  v_owner  uuid;
begin
  <<rules>>
  for r in
    select * from support_triage_rules
     where tenant_id = p_tenant_id and active
     order by rule_order, created_at
  loop
    -- Catch-all rule (no pattern) applies immediately.
    if r.match_pattern is null or btrim(r.match_pattern) = '' then
      v_hit := r;
      exit rules;
    end if;
    -- First rule whose ANY literal keyword is present wins.
    foreach frag in array string_to_array(r.match_pattern, '|') loop
      frag := lower(btrim(frag));
      if frag <> '' and position(frag in v_low) > 0 then
        v_hit := r;
        exit rules;
      end if;
    end loop;
  end loop;

  -- No rule matched and no catch-all configured — safe neutral default,
  -- unchanged from migration 233 and still the answer 18 workspaces would get
  -- if their baseline were ever deleted.
  if v_hit.id is null then
    return jsonb_build_object('category', 'general', 'priority', 'normal',
                              'severity', 'sev3', 'rule', 'default',
                              'rule_id', null, 'owner_de_id', null);
  end if;

  -- ⚠ 760 — WHO ANSWERS, RESOLVED OFF THE ROW THAT MATCHED and filtered to an
  -- employee who can actually take it. Every clause here is a decision:
  --   · tenant_id = p_tenant_id — belt as well as the composite foreign key's
  --     braces. The FK makes a cross-workspace owner unwritable; this makes it
  --     unreadable even if the constraint were ever dropped.
  --   · is_workforce_assistant — the Workspace Assistant is the platform's own
  --     internal helper, not one of the customer's employees. Without this it
  --     would be the first path that puts customer support traffic in front of
  --     it. Stated as a FILTER, never as a value anything reads.
  --   · lifecycle_status — rows are RETIRED here, never deleted, so existence
  --     is not eligibility. 'designed' is in the list because widget-ask's own
  --     front-desk resolution excludes it ("never published DEs never front
  --     customer chat") and a topic owner IS fronting customer chat.
  -- A miss on any of these returns NULL, which sends the caller to its ordinary
  -- fallback — the topic keeps its label and stops choosing a person.
  if v_hit.owner_de_id is not null then
    select d.id into v_owner
      from digital_employees d
     where d.id = v_hit.owner_de_id
       and d.tenant_id = p_tenant_id
       and coalesce(d.is_workforce_assistant, false) = false
       and coalesce(d.lifecycle_status, '') not in ('paused', 'retired', 'archived', 'designed');
  end if;

  return jsonb_build_object('category', v_hit.set_category,
                            'priority',  v_hit.set_priority,
                            'severity',  v_hit.set_severity,
                            'rule',      v_hit.name,
                            'rule_id',   v_hit.id,
                            'owner_de_id', v_owner);
end;
$function$;

CREATE OR REPLACE FUNCTION public.clear_de_operate_login(p_system_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tenant uuid; v_secret uuid;
BEGIN
  SELECT tenant_id, login_secret_id INTO v_tenant, v_secret
    FROM de_connected_systems WHERE id = p_system_id;
  IF v_tenant IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'binding_not_found'); END IF;
  IF NOT public.can_admin_tenant_internal(v_tenant) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_permitted');
  END IF;
  UPDATE de_connected_systems SET login_secret_id = NULL WHERE id = p_system_id;
  IF v_secret IS NOT NULL THEN DELETE FROM vault.secrets WHERE id = v_secret; END IF;
  RETURN jsonb_build_object('ok', true);
END; $function$;

CREATE OR REPLACE FUNCTION public.clear_review_minutes(p_task_type text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_tenant uuid; v_deleted int;
begin
  v_tenant := public.auth_tenant_id();
  if v_tenant is null or not public.auth_has_tenant_role(array['tenant_owner','tenant_admin']) then
    return jsonb_build_object('ok', false, 'error', 'not_permitted');
  end if;

  delete from review_time_standards where tenant_id = v_tenant and task_type = p_task_type;
  get diagnostics v_deleted = row_count;

  return jsonb_build_object('ok', true, 'task_type', p_task_type,
                            'effective_minutes', public.resolve_review_minutes(v_tenant, p_task_type),
                            'was_overridden', v_deleted > 0);
end $function$;

CREATE OR REPLACE FUNCTION public.clear_tenant_llm_key(p_tenant_id uuid, p_provider_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_secret uuid;
BEGIN
  IF auth.role() IS NOT NULL AND auth.role() <> 'service_role' THEN
    IF auth.uid() IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
    IF NOT (is_platform_admin()
            OR (EXISTS (SELECT 1 FROM profiles p
                         WHERE p.user_id = auth.uid() AND p.tenant_id = p_tenant_id)
                AND auth_has_tenant_role(ARRAY['tenant_owner', 'tenant_admin']))) THEN
      RAISE EXCEPTION 'not authorized';
    END IF;
  END IF;
  -- Take the vault secret with the row. Deleting only the row would leave the
  -- credential decryptable in vault for ever, which is the opposite of what
  -- "remove my key" means.
  DELETE FROM tenant_llm_credentials
   WHERE tenant_id = p_tenant_id AND provider_key = p_provider_key
   RETURNING secret_id INTO v_secret;
  IF v_secret IS NOT NULL THEN
    DELETE FROM vault.secrets WHERE id = v_secret;
  END IF;
  RETURN jsonb_build_object('ok', true);
END $function$;

CREATE OR REPLACE FUNCTION public.close_escalations_for_finished_goal()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_prev text;
BEGIN
  IF NEW.status IN ('achieved', 'abandoned') AND NEW.status IS DISTINCT FROM OLD.status THEN
    -- ⚠ Capture whatever was already there. Restoring it (rather than forcing
    -- 'off') is what keeps this safe to call from inside an outer sanctioned
    -- operation — see the migration header.
    v_prev := coalesce(current_setting('app.allow_task_decision', true), '');

    PERFORM set_config('app.allow_task_decision', 'on', true);  -- mig 487 sanctioned path
    UPDATE human_tasks
       SET status = 'rejected',
           disposition = 'cancelled',
           decision_note = format(
             'Closed automatically: the goal this asked about is %s. Nobody needs to rule on it now, and no human ruling was made.',
             NEW.status),
           decided_at = now(),
           updated_at = now()
     WHERE related_table = 'de_objectives'
       AND related_id = NEW.id
       AND status = 'pending';

    -- Re-arm. An exception between the two would abort the transaction and
    -- take the setting with it, so there is no path that leaves it 'on'.
    PERFORM set_config('app.allow_task_decision', v_prev, true);
  END IF;
  RETURN NEW;
END
$function$;

CREATE OR REPLACE FUNCTION public.close_opportunity_lost(p_opp uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_opp    opportunities;
  v_tenant uuid;
  v_is_active boolean;
begin
  select coalesce(is_active, true) into v_is_active from profiles where user_id = auth.uid() limit 1;
  if v_is_active is false then raise exception 'account is deactivated'; end if;
  v_tenant := auth_tenant_id();
  if v_tenant is null then raise exception 'no tenant for caller'; end if;
  if coalesce(trim(p_reason), '') = '' then
    return jsonb_build_object('error', 'lost_reason_required');
  end if;
  select * into v_opp from opportunities where id = p_opp and tenant_id = v_tenant;
  if not found then return jsonb_build_object('error', 'opportunity_not_found'); end if;
  if v_opp.stage in ('won', 'lost') then return jsonb_build_object('error', 'already_closed'); end if;

  perform set_config('dreamteam.opp_close', 'on', true);
  update opportunities set stage = 'lost', lost_reason = trim(p_reason) where id = v_opp.id;
  perform set_config('dreamteam.opp_close', '', true);

  return jsonb_build_object('closed', true);
end;
$function$;

CREATE OR REPLACE FUNCTION public.close_opportunity_won(p_opp uuid, p_account_id uuid DEFAULT NULL::uuid, p_create_onboarding boolean DEFAULT false, p_template_version uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_opp       opportunities;
  v_tenant    uuid;
  v_is_active boolean;
  v_acct_id   uuid;
  v_acct_name text;
  v_proj      jsonb;
  v_proj_id   uuid;
begin
  select coalesce(is_active, true) into v_is_active from profiles where user_id = auth.uid() limit 1;
  if v_is_active is false then raise exception 'account is deactivated'; end if;
  v_tenant := auth_tenant_id();
  if v_tenant is null then raise exception 'no tenant for caller'; end if;

  select * into v_opp from opportunities where id = p_opp and tenant_id = v_tenant;
  if not found then return jsonb_build_object('error', 'opportunity_not_found'); end if;
  if v_opp.stage in ('won', 'lost') then return jsonb_build_object('error', 'already_closed'); end if;

  v_acct_id := coalesce(p_account_id, v_opp.account_id);
  if v_acct_id is not null then
    select name into v_acct_name from customer_accounts where id = v_acct_id and tenant_id = v_tenant;
    if v_acct_name is null then return jsonb_build_object('error', 'account_not_found'); end if;
  else
    v_acct_name := coalesce(nullif(trim(v_opp.company_name), ''), v_opp.name);
    insert into customer_accounts (tenant_id, name, arr_cents, health_score, status, notes)
    values (v_tenant, v_acct_name, coalesce(v_opp.amount_cents, 0), 70, 'active',
            format('Created from won opportunity "%s"', v_opp.name))
    returning id into v_acct_id;
    insert into activity_events (tenant_id, account_id, actor, actor_type, event_type, text)
    values (v_tenant, v_acct_id, 'You', 'human', 'config_change',
            format('Account created from won opportunity — %s', v_acct_name));
  end if;

  perform set_config('dreamteam.opp_close', 'on', true);
  update opportunities set stage = 'won', account_id = v_acct_id where id = v_opp.id;
  perform set_config('dreamteam.opp_close', '', true);

  perform append_audit_event_internal(
    v_tenant, 'You', 'human',
    format('Won → lifecycle handoff — %s: account "%s"%s', v_opp.name, v_acct_name,
           case when p_create_onboarding then ' + onboarding kickoff' else '' end),
    'config_change',
    jsonb_build_object('kind', 'opportunity_won_handoff', 'opportunity_id', v_opp.id,
                       'account_id', v_acct_id, 'created_account', v_opp.account_id is null and p_account_id is null,
                       'create_onboarding', p_create_onboarding));

  if p_create_onboarding and p_template_version is not null then
    v_proj := create_onboarding_project(v_acct_id, p_template_version, null, null);
    v_proj_id := (v_proj->>'project_id')::uuid;
    if v_proj->>'error' is not null then
      return jsonb_build_object('account_id', v_acct_id, 'onboarding_error', v_proj->>'error');
    end if;
  end if;

  return jsonb_build_object('account_id', v_acct_id, 'project_id', v_proj_id);
end;
$function$;

CREATE OR REPLACE FUNCTION public.cluster_gap_candidates(p_tenant_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_policy       record;
  v_candidate    record;
  v_nearest_id   uuid;
  v_nearest_status text;
  v_nearest_dist double precision;
  v_new_cluster_id uuid;
  v_frustration  integer;
  v_new_members  integer := 0;
  v_new_clusters integer := 0;
  v_reopened     integer := 0;
  v_promoted     integer := 0;
  v_cluster_id   uuid;
begin
  if not is_feature_enabled_internal(p_tenant_id, 'knowledge_gap_detection') then
    return jsonb_build_object('skipped', 'feature_disabled');
  end if;

  for v_policy in
    select * from knowledge_gap_policies where tenant_id = p_tenant_id and enabled = true
  loop
    for v_candidate in
      select erd.id as decision_id, erd.evidence_run_id, erd.confidence, erd.source_category,
             er.inquiry, er.inquiry_embedding, er.created_at
      from evidence_run_decisions erd
      join evidence_runs er on er.id = erd.evidence_run_id
      where erd.tenant_id = p_tenant_id
        and (v_policy.category is null or erd.source_category = v_policy.category)
        and erd.confidence < v_policy.min_confidence_floor
        and er.inquiry_embedding is not null
        and er.created_at >= now() - make_interval(days => v_policy.window_days)
        and not exists (select 1 from knowledge_gap_cluster_members m where m.evidence_run_id = er.id)
      order by er.created_at asc
    loop
      v_frustration := score_frustration_internal(p_tenant_id, v_candidate.inquiry);

      select c.id, c.status, rer.inquiry_embedding <=> v_candidate.inquiry_embedding
        into v_nearest_id, v_nearest_status, v_nearest_dist
      from knowledge_gap_clusters c
      join evidence_runs rer on rer.id = c.representative_run_id
      where c.tenant_id = p_tenant_id
        and (v_policy.category is null or c.category = v_candidate.source_category)
        and c.last_seen_at >= now() - make_interval(days => v_policy.window_days)
      order by rer.inquiry_embedding <=> v_candidate.inquiry_embedding asc
      limit 1;

      if v_nearest_id is not null and v_nearest_dist < v_policy.similarity_threshold then
        insert into knowledge_gap_cluster_members (cluster_id, evidence_run_id, similarity_to_representative, frustration_score)
        values (v_nearest_id, v_candidate.evidence_run_id, 1 - v_nearest_dist, v_frustration)
        on conflict (evidence_run_id) do nothing;

        if v_nearest_status = 'resolved' then
          update knowledge_gap_clusters
          set status = 'open', member_count = member_count + 1, last_seen_at = now(),
              recurred_after_fix = true, recurrence_count = recurrence_count + 1,
              severity_score = (select count(*) * (1 + coalesce(avg(frustration_score), 0) / 100.0)
                                from knowledge_gap_cluster_members where cluster_id = v_nearest_id) + 10,
              updated_at = now()
          where id = v_nearest_id;
          v_reopened := v_reopened + 1;
        else
          update knowledge_gap_clusters
          set member_count = member_count + 1, last_seen_at = now(),
              severity_score = (select count(*) * (1 + coalesce(avg(frustration_score), 0) / 100.0)
                                from knowledge_gap_cluster_members where cluster_id = v_nearest_id),
              updated_at = now()
          where id = v_nearest_id;
        end if;
        v_new_members := v_new_members + 1;
      else
        insert into knowledge_gap_clusters (tenant_id, category, representative_run_id, member_count, severity_score, status, first_seen_at, last_seen_at)
        values (p_tenant_id, v_candidate.source_category, v_candidate.evidence_run_id, 1, 1 + v_frustration / 100.0, 'open', now(), now())
        returning id into v_new_cluster_id;

        insert into knowledge_gap_cluster_members (cluster_id, evidence_run_id, similarity_to_representative, frustration_score)
        values (v_new_cluster_id, v_candidate.evidence_run_id, 1.0, v_frustration)
        on conflict (evidence_run_id) do nothing;

        v_new_clusters := v_new_clusters + 1;
      end if;
    end loop;

    -- promote any open cluster that just crossed this policy's bar
    -- (fixed: category-null policy now correctly matches every
    -- category's clusters, not just category-null ones)
    for v_cluster_id in
      select c.id from knowledge_gap_clusters c
      where c.tenant_id = p_tenant_id
        and c.status = 'open'
        and (v_policy.category is null or c.category = v_policy.category)
        and c.member_count >= v_policy.min_cluster_size
    loop
      perform promote_gap_cluster(v_cluster_id);
      v_promoted := v_promoted + 1;
    end loop;
  end loop;

  return jsonb_build_object(
    'new_members', v_new_members, 'new_clusters', v_new_clusters,
    'reopened_after_fix', v_reopened, 'promoted', v_promoted
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.cluster_learned_behavior_candidates(p_tenant_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_policy        record;
  v_candidate     record;
  v_verdict       text;
  v_nearest_id    uuid;
  v_nearest_status text;
  v_nearest_dist  double precision;
  v_new_cluster_id uuid;
  v_new_members   integer := 0;
  v_new_clusters  integer := 0;
  v_reopened      integer := 0;
  v_promoted      integer := 0;
  v_cluster_id    uuid;
begin
  if not is_feature_enabled_internal(p_tenant_id, 'de_learned_behavior_detection') then
    return jsonb_build_object('skipped', 'feature_disabled');
  end if;

  for v_policy in
    select * from de_learning_policies where tenant_id = p_tenant_id and enabled = true
  loop
    for v_candidate in
      select erd.id as decision_id, erd.evidence_run_id, erd.confidence, erd.source_category,
             erd.guardrail_rule_id, er.inquiry, er.inquiry_embedding, er.created_at, er.de_id,
             ht.status as task_status, ht.decision_edit
      from evidence_run_decisions erd
      join evidence_runs er on er.id = erd.evidence_run_id
      join human_tasks ht on ht.id = erd.human_task_id
      where erd.tenant_id = p_tenant_id
        and (erd.decision = 'needs_review' or ht.decision_edit is not null)
        and ht.status in ('approved', 'rejected')
        and evidence_is_production(ht.origin)
        and (v_policy.category is null or erd.source_category = v_policy.category)
        and er.inquiry_embedding is not null
        and er.de_id is not null
        and er.created_at >= now() - make_interval(days => v_policy.window_days)
        and not exists (select 1 from de_learned_behavior_cluster_members m where m.evidence_run_id = er.id)
      order by er.created_at asc
    loop
      -- reject -> the DE's proposed answer was wrong (correction evidence)
      -- edit   -> the human CHANGED the content before approving (correction)
      -- plain approve -> the DE didn't need to be this cautious (overcaution)
      v_verdict := case when v_candidate.task_status = 'rejected'
                          or v_candidate.decision_edit is not null
                        then 'correction' else 'overcaution' end;

      select c.id, c.status, rer.inquiry_embedding <=> v_candidate.inquiry_embedding
        into v_nearest_id, v_nearest_status, v_nearest_dist
      from de_learned_behavior_clusters c
      join evidence_runs rer on rer.id = c.representative_run_id
      where c.tenant_id = p_tenant_id
        and c.de_id = v_candidate.de_id
        and c.verdict_type = v_verdict
        and (v_policy.category is null or c.category = v_candidate.source_category)
        and (v_verdict = 'correction' or c.guardrail_rule_id is not distinct from v_candidate.guardrail_rule_id)
        and c.last_seen_at >= now() - make_interval(days => v_policy.window_days)
      order by rer.inquiry_embedding <=> v_candidate.inquiry_embedding asc
      limit 1;

      if v_nearest_id is not null and v_nearest_dist < v_policy.similarity_threshold then
        insert into de_learned_behavior_cluster_members (cluster_id, evidence_run_id, human_task_id, similarity_to_representative)
        values (v_nearest_id, v_candidate.evidence_run_id, erd_human_task_id(v_candidate.decision_id), 1 - v_nearest_dist)
        on conflict (evidence_run_id) do nothing;

        if v_nearest_status = 'resolved' then
          update de_learned_behavior_clusters
          set status = 'open', member_count = member_count + 1, last_seen_at = now(),
              recurred_after_fix = true, recurrence_count = recurrence_count + 1,
              severity_score = (select count(*) from de_learned_behavior_cluster_members where cluster_id = v_nearest_id) + 10,
              updated_at = now()
          where id = v_nearest_id;
          v_reopened := v_reopened + 1;
        else
          update de_learned_behavior_clusters
          set member_count = member_count + 1, last_seen_at = now(),
              severity_score = (select count(*) from de_learned_behavior_cluster_members where cluster_id = v_nearest_id),
              updated_at = now()
          where id = v_nearest_id;
        end if;
        v_new_members := v_new_members + 1;
      else
        insert into de_learned_behavior_clusters (
          tenant_id, de_id, category, verdict_type, representative_run_id, guardrail_rule_id,
          member_count, severity_score, status, first_seen_at, last_seen_at
        )
        values (
          p_tenant_id, v_candidate.de_id, v_candidate.source_category, v_verdict, v_candidate.evidence_run_id,
          case when v_verdict = 'overcaution' then v_candidate.guardrail_rule_id else null end,
          1, 1, 'open', now(), now()
        )
        returning id into v_new_cluster_id;

        insert into de_learned_behavior_cluster_members (cluster_id, evidence_run_id, human_task_id, similarity_to_representative)
        values (v_new_cluster_id, v_candidate.evidence_run_id, erd_human_task_id(v_candidate.decision_id), 1.0)
        on conflict (evidence_run_id) do nothing;

        v_new_clusters := v_new_clusters + 1;
      end if;
    end loop;

    for v_cluster_id in
      select c.id from de_learned_behavior_clusters c
      where c.tenant_id = p_tenant_id
        and c.status = 'open'
        and c.category is not distinct from v_policy.category
        and c.member_count >= v_policy.min_cluster_size
    loop
      perform propose_learned_behavior(v_cluster_id);
      v_promoted := v_promoted + 1;
    end loop;
  end loop;

  return jsonb_build_object(
    'new_members', v_new_members, 'new_clusters', v_new_clusters,
    'reopened_after_fix', v_reopened, 'promoted', v_promoted
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.complete_de_work_item(p_id uuid, p_status text, p_result jsonb DEFAULT NULL::jsonb, p_error text DEFAULT NULL::text, p_retry_delay_seconds integer DEFAULT 300)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_row de_work_items;
begin
  select * into v_row from de_work_items where id = p_id for update;
  if v_row.id is null then raise exception 'work item not found'; end if;

  if p_status = 'failed' and v_row.attempts < v_row.max_attempts then
    update de_work_items
       set status = 'queued', last_error = p_error,
           scheduled_for = now() + make_interval(secs => greatest(1, p_retry_delay_seconds)),
           locked_at = null, locked_by = null, updated_at = now()
     where id = p_id;
    return 'requeued';
  end if;

  update de_work_items
     set status = p_status, result = coalesce(p_result, result), last_error = p_error,
         locked_at = null, locked_by = null, updated_at = now()
   where id = p_id;
  return p_status;
end;
$function$;

CREATE OR REPLACE FUNCTION public.complete_ingestion_item(p_item_id uuid, p_doc_id uuid, p_duplicate boolean DEFAULT false)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not authenticated: recording an ingestion result is a platform operation, not an anonymous one';
  END IF;
  IF NOT is_platform_admin() THEN
    RAISE EXCEPTION 'not callable by tenant users';
  END IF;
  PERFORM public.complete_ingestion_item_internal(p_item_id, p_doc_id, p_duplicate);
END $function$;

CREATE OR REPLACE FUNCTION public.complete_ingestion_item_internal(p_item_id uuid, p_doc_id uuid, p_duplicate boolean DEFAULT false)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_item knowledge_ingestion_items; v_job knowledge_ingestion_jobs;
BEGIN
  -- NO USER CHECK. Called by the drain with the service-role client.
  SELECT * INTO v_item FROM knowledge_ingestion_items WHERE id = p_item_id;
  IF v_item.id IS NULL THEN RAISE EXCEPTION 'ingestion item not found'; END IF;

  UPDATE knowledge_ingestion_items
     SET status = CASE WHEN p_duplicate THEN 'skipped_duplicate' ELSE 'succeeded' END,
         doc_id = p_doc_id, last_error = NULL, error_kind = NULL, updated_at = now()
   WHERE id = p_item_id;

  -- File the result into the job's target Space, if it had one. This is what
  -- turns an import into an organised library rather than a flat pile.
  SELECT * INTO v_job FROM knowledge_ingestion_jobs WHERE id = v_item.job_id;
  IF v_job.target_collection_id IS NOT NULL AND p_doc_id IS NOT NULL AND NOT p_duplicate THEN
    INSERT INTO knowledge_doc_collections (tenant_id, doc_id, collection_id)
    VALUES (v_job.tenant_id, p_doc_id, v_job.target_collection_id)
    ON CONFLICT DO NOTHING;
  END IF;
END $function$;

CREATE OR REPLACE FUNCTION public.complete_onboarding_item_from_execution()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_now     boolean;
  v_was     boolean := false;
  v_project uuid;
  v_key     text;
begin
  -- HAS THE WORK LANDED? Evaluated on NEW, through the ONE definition.
  v_now := new.dedupe_key is not null
       and new.dedupe_key like 'onboarding:%'
       and public.action_execution_landed(new);

  -- The same question about the row BEFORE this statement. On INSERT there is
  -- no before, and OLD is unassigned there, so it must not be touched.
  if tg_op = 'UPDATE' then
    v_was := old.dedupe_key is not null
         and old.dedupe_key like 'onboarding:%'
         and public.action_execution_landed(old);
  end if;

  -- Not landed: a gate row, a claim taken before the call, a preview, a
  -- failure, a rollback. Nothing to record. (A landed -> not-landed
  -- transition also lands here: see mig 676's NAMED AND LEFT note.)
  if not v_now then return null; end if;
  -- Already landed before this statement: this UPDATE changed something else,
  -- and must not re-write an item a person has moved on from since.
  if v_was then return null; end if;

  v_project := nullif(split_part(new.dedupe_key, ':', 2), '')::uuid;
  v_key     := nullif(split_part(new.dedupe_key, ':', 3), '');
  if v_project is null or v_key is null then return null; end if;

  -- Tenant-scoped by construction: the id arrives inside a text key, and the
  -- WHERE clause below still requires it to match the execution's own
  -- tenant_id before anything is written.
  update onboarding_projects p
     set items_state = (
           select jsonb_agg(case when i->>'key' = v_key and i->>'status' <> 'signed_off'
                                 then i || jsonb_build_object(
                                        'status',  'done',
                                        'done_at', now(),
                                        'note',    coalesce(nullif(btrim(new.receipt), ''), 'applied'),
                                        'completed_by_execution', new.id)
                                 else i end)
             from jsonb_array_elements(p.items_state) i)
   where p.id = v_project
     and p.tenant_id = new.tenant_id;

  return null;
exception when others then
  -- A malformed key must not roll back an execution that already reached a
  -- customer's system.
  return null;
end;
$function$;

CREATE OR REPLACE FUNCTION public.complete_signup(p_org_name text, p_industry text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user   uuid := auth.uid();
  v_profile profiles;
  v_slug   text;
  v_base_slug text;
  v_suffix int := 0;
  v_tenant tenants;
  v_demo_tenant_id constant uuid := 'a0000000-0000-0000-0000-000000000001';
begin
  if v_user is null then
    return jsonb_build_object('ok', false, 'error', 'not_authenticated',
      'detail', 'You must be signed in to set up an organization.');
  end if;

  if coalesce(btrim(p_org_name), '') = '' then
    return jsonb_build_object('ok', false, 'error', 'org_name_required');
  end if;

  select * into v_profile from profiles where user_id = v_user;
  if v_profile.id is null then
    return jsonb_build_object('ok', false, 'error', 'no_profile',
      'detail', 'No profile found for this user. Please contact support.');
  end if;

  if v_profile.tenant_id is not null then
    return jsonb_build_object('ok', false, 'error', 'already_has_tenant',
      'tenant_id', v_profile.tenant_id,
      'detail', 'This account is already linked to an organization.');
  end if;

  v_base_slug := lower(regexp_replace(btrim(p_org_name), '[^a-zA-Z0-9]+', '-', 'g'));
  v_base_slug := trim(both '-' from v_base_slug);
  if coalesce(v_base_slug, '') = '' then
    v_base_slug := 'org';
  end if;
  v_slug := v_base_slug;
  while exists (select 1 from tenants where slug = v_slug) loop
    v_suffix := v_suffix + 1;
    v_slug := v_base_slug || '-' || v_suffix::text;
  end loop;

  insert into tenants (name, slug, industry, plan, status, settings, trial_ends_at, admin_email, admin_name)
  values (btrim(p_org_name), v_slug, nullif(btrim(coalesce(p_industry, '')), ''), 'starter', 'trial', '{}'::jsonb, now() + interval '14 days', (select email from auth.users where id = v_user), coalesce(v_profile.full_name, (select email from auth.users where id = v_user)))
  returning * into v_tenant;

  if v_tenant.id = v_demo_tenant_id then
    raise exception 'Refusing to provision the reserved demo tenant id';
  end if;

  -- role='tenant_owner' added here — this UPDATE only ever fires once
  -- per user (tenant_id is null guard), for the tenant this same user
  -- just created above, so granting real ownership at this exact
  -- point is safe and correct, not a broadened grant.
  update profiles
  set tenant_id = v_tenant.id,
      role = 'tenant_owner',
      updated_at = now()
  where user_id = v_user
    and tenant_id is null;
  perform public.grant_workspace_baseline_access(v_tenant.id, v_user);

  if not found then
    delete from tenants where id = v_tenant.id;
    return jsonb_build_object('ok', false, 'error', 'already_has_tenant',
      'detail', 'This account is already linked to an organization.');
  end if;

  -- Full baseline contract: feature reconcile (starter DEs + playbooks)
  -- PLUS starter guardrails, onboarding template, and specialist desk —
  -- previously only the reconcile ran here, so new tenants were missing
  -- every feature whose seed data had only ever been installed on the
  -- dev tenant by hand.
  perform provision_tenant_baseline_internal(v_tenant.id);

  perform append_audit_event(
    v_tenant.id,
    coalesce(v_profile.full_name, 'owner'),
    'human',
    'Organization "' || v_tenant.name || '" created at signup by ' || coalesce(v_profile.full_name, 'the account owner'),
    'config_change',
    jsonb_build_object('kind', 'tenant_provisioned', 'tenant_id', v_tenant.id,
      'tenant_name', v_tenant.name, 'slug', v_tenant.slug, 'industry', v_tenant.industry,
      'user_id', v_user)
  );

  return jsonb_build_object('ok', true, 'tenant_id', v_tenant.id, 'slug', v_tenant.slug, 'name', v_tenant.name);
end;
$function$;

CREATE OR REPLACE FUNCTION public.compose_weekly_value_digest()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_week text := to_char(now(), 'IYYY"-W"IW');
  v_t record;
  v_units jsonb;
  v_rollup jsonb;
  v_kind text;
  v_created int;
  v_decided int;
  v_pending int;
  v_pay int;
  v_overdue int;
  v_review jsonb;
  v_review_block jsonb;
  v_review_minutes numeric;
  v_written int := 0;
begin
  for v_t in
    select t.id, t.name from tenants t
     where tenant_is_operational(t.id)
  loop
    begin  -- per-tenant isolation: one bad tenant cannot kill the digest tick
      v_kind := 'value_digest_' || v_week || '_' || left(v_t.id::text, 8);
      if exists (select 1 from ops_alerts where kind = v_kind) then continue; end if;

      select coalesce(jsonb_agg(jsonb_build_object(
               'unit', u.archetype_key,
               'employees', u.n_emp,
               'work_items_done_7d', u.done,
               'deliverables_7d', u.deliv,
               'production_conversations_7d', u.convos
             ) order by u.archetype_key), '[]'::jsonb)
        into v_units
        from (
          select coalesce(de.archetype_key, '(no archetype)') as archetype_key,
                 count(distinct de.id) as n_emp,
                 count(distinct w.id)  as done,
                 count(distinct dl.id) as deliv,
                 count(distinct c.id)  as convos
            from digital_employees de
            left join de_work_items w
              on w.de_id = de.id and w.status = 'done'
             and w.updated_at > now() - interval '7 days'
            left join de_deliverables dl
              on dl.de_id = de.id and dl.created_at > now() - interval '7 days'
            left join de_conversations c
              on c.de_id = de.id and c.channel <> 'exam'
             and c.created_at > now() - interval '7 days'
           where de.tenant_id = v_t.id
             and de.lifecycle_status in ('active','published','improving')
           group by coalesce(de.archetype_key, '(no archetype)')
        ) u;

      select count(*) into v_created from human_tasks
       where tenant_id = v_t.id and created_at > now() - interval '7 days';
      select count(*) into v_decided from human_tasks
       where tenant_id = v_t.id and decided_at > now() - interval '7 days';
      select count(*) into v_pending from human_tasks
       where tenant_id = v_t.id and status = 'pending';
      select count(*) into v_pay from invoice_payments
       where tenant_id = v_t.id and created_at > now() - interval '7 days';
      select count(*) into v_overdue from renewal_invoices
       where tenant_id = v_t.id and status = 'overdue';

      -- 702: the founder's own time, modeled (mig 691), on the digest's
      -- 7-day window. Reduced to the host organ's rules: no rate field.
      v_review := public.get_review_cost_internal(v_t.id, 7);
      v_review_minutes := coalesce((v_review->'decided'->>'total_minutes')::numeric, 0);
      v_review_block := jsonb_build_object(
        'basis', v_review->>'basis',
        'total_modeled_minutes_7d', v_review_minutes,
        'by_de', v_review->'decided'->'by_de',
        'outputs_7d', v_review->'outputs',
        'hourly_rate_usd', v_review->'hourly_rate_usd',
        'modeled_cost_usd', v_review->'modeled_cost_usd',
        'note', v_review->>'note');

      v_rollup := jsonb_build_object(
        'window_days', 7,
        'human_tasks_created_7d', v_created,
        'human_tasks_decided_7d', v_decided,
        'human_tasks_pending_now', v_pending,
        'payments_recorded_7d', v_pay,
        'invoices_overdue_now_face_value', v_overdue,
        'notes', jsonb_build_array(
          'exam traffic excluded from every count',
          'overdue invoices are face value — a balance is only real after payment reconciliation',
          'counts only, no rates: the reader divides',
          'human-review minutes are MODELED (standard minutes × decided tasks), never measured — tune them in Settings'));

      insert into ops_alerts (kind, message, detail)
      values (v_kind,
        format('Week in receipts — %s: %s decided of %s new asks (%s pending now) · %s work items done · %s payments recorded · %s invoices overdue (face value) · ~%s modeled review minutes. Exams excluded.',
          v_t.name, v_decided, v_created, v_pending,
          (select coalesce(sum((u->>'work_items_done_7d')::int), 0) from jsonb_array_elements(v_units) u),
          v_pay, v_overdue, round(v_review_minutes)),
        jsonb_build_object('digest', 'weekly_value', 'week', v_week,
                           'tenant_id', v_t.id, 'tenant_name', v_t.name,
                           'units', v_units, 'rollup', v_rollup,
                           'human_review', v_review_block));
      v_written := v_written + 1;
    exception when others then
      raise warning 'value digest failed for tenant %: %', v_t.id, sqlerrm;
    end;
  end loop;

  return 'value digest: ' || v_written || ' tenant digest(s) written for ' || v_week;
end; $function$;

CREATE OR REPLACE FUNCTION public.compute_account_health(p_account uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_tenant uuid;
  v_is_active boolean;
begin
  select tenant_id into v_tenant from customer_accounts where id = p_account;
  if v_tenant is null then
    return jsonb_build_object('error', 'account_not_found');
  end if;
  if coalesce(auth.role(), '') <> 'service_role' then
    select coalesce(is_active, true) into v_is_active from profiles where user_id = auth.uid() and tenant_id = v_tenant;
    if v_is_active is null or not v_is_active then
      raise exception 'not a member of this tenant';
    end if;
  end if;
  return compute_account_health_core(p_account);
end;
$function$;

CREATE OR REPLACE FUNCTION public.compute_account_health_core(p_account uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_acct       customer_accounts;
  v_weights    jsonb;
  v_thresholds jsonb;
  w_tickets    numeric; w_escal numeric; w_overdue numeric; w_activity numeric;
  n_open       integer; n_escal integer; n_overdue integer;
  v_last_act   timestamptz;
  v_days       integer;                  -- null = no activity ever
  p_tickets    numeric; p_escal numeric; p_overdue numeric; p_activity numeric;
  v_score      integer;
  v_components jsonb;
  v_at_risk    integer; v_healthy integer;
  v_new_status text;
begin
  select * into v_acct from customer_accounts where id = p_account;
  if not found then
    return jsonb_build_object('error', 'account_not_found');
  end if;

  select weights, thresholds into v_weights, v_thresholds
  from health_score_config where tenant_id = v_acct.tenant_id;
  v_weights    := coalesce(v_weights,    '{"open_tickets":25,"escalations":25,"overdue_invoices":30,"activity_recency":20}'::jsonb);
  v_thresholds := coalesce(v_thresholds, '{"at_risk_below":50,"healthy_above":75}'::jsonb);

  w_tickets  := coalesce((v_weights->>'open_tickets')::numeric, 25);
  w_escal    := coalesce((v_weights->>'escalations')::numeric, 25);
  w_overdue  := coalesce((v_weights->>'overdue_invoices')::numeric, 30);
  w_activity := coalesce((v_weights->>'activity_recency')::numeric, 20);
  v_at_risk  := coalesce((v_thresholds->>'at_risk_below')::int, 50);
  v_healthy  := coalesce((v_thresholds->>'healthy_above')::int, 75);

  -- ── real signals ──
  select count(*) filter (where status in ('open', 'pending')),
         count(*) filter (where status = 'escalated')
    into n_open, n_escal
  from support_tickets where account_id = p_account;

  select count(*) into n_overdue
  from renewal_invoices
  where account_id = p_account and status = 'sent'
    and due_date is not null and due_date < current_date;

  select max(created_at) into v_last_act
  from activity_events where account_id = p_account;
  v_days := case when v_last_act is null then null
                 else greatest(0, extract(day from now() - v_last_act)::int) end;

  -- ── mig 510: NO EVIDENCE IS NOT A SCORE ────────────────────────────────
  -- The four signals above are the only inputs. When an account has none of
  -- them the arithmetic still produced a confident number: every penalty is
  -- zero except activity_recency, which charges its full weight because
  -- v_days is NULL — so EVERY customer with no history scored exactly the
  -- same, and anything an operator had marked at_risk flipped back to active
  -- for clearing the healthy threshold.
  --
  -- That is "this customer is brand new" being reported as "this customer is
  -- fine", and it OVERWRITES what a person entered. Observed live: ten
  -- accounts entered with a 38-91 spread were rewritten to a uniform 80 one
  -- minute after creation, while cases opened against the entered values were
  -- already running — an employee correctly reported the contradiction.
  --
  -- Same rule as migration 491: an unmeasured thing says so. Return without
  -- touching the score or the status, and record WHY so the surface can be
  -- honest rather than blank.
  if n_open = 0 and n_escal = 0 and n_overdue = 0 and v_last_act is null then
    update customer_accounts
       set health_components = jsonb_build_object(
             'score', null,
             'measured', false,
             'computed_at', now(),
             'reason', 'No tickets, invoices or activity recorded for this account yet — nothing to compute a health score from. The score shown is whatever was entered by hand.')
     where id = p_account;
    return jsonb_build_object(
      'measured', false,
      'score', null,
      'status', v_acct.status,
      'status_changed', false,
      'reason', 'no_evidence');
  end if;

  -- ── bucketed penalties ──
  p_tickets  := case when n_open = 0 then 0 when n_open <= 2 then 0.4 * w_tickets
                     when n_open <= 5 then 0.7 * w_tickets else w_tickets end;
  p_escal    := case when n_escal = 0 then 0 when n_escal = 1 then 0.6 * w_escal else w_escal end;
  p_overdue  := case when n_overdue = 0 then 0 when n_overdue = 1 then 0.7 * w_overdue else w_overdue end;
  p_activity := case when v_days is null then w_activity
                     when v_days <= 7 then 0 when v_days <= 14 then 0.3 * w_activity
                     when v_days <= 30 then 0.6 * w_activity else w_activity end;

  v_score := greatest(0, least(100, round(100 - p_tickets - p_escal - p_overdue - p_activity)::int));

  v_components := jsonb_build_object(
    'score', v_score,
    'measured', true,
    'computed_at', now(),
    'open_tickets',     jsonb_build_object('count', n_open,    'penalty', round(p_tickets, 1),  'weight', w_tickets),
    'escalations',      jsonb_build_object('count', n_escal,   'penalty', round(p_escal, 1),    'weight', w_escal),
    'overdue_invoices', jsonb_build_object('count', n_overdue, 'penalty', round(p_overdue, 1),  'weight', w_overdue),
    'activity_recency', jsonb_build_object('days_since', v_days, 'penalty', round(p_activity, 1), 'weight', w_activity)
  );

  -- ── status flip per thresholds (never touches churned) ──
  v_new_status := v_acct.status;
  if v_acct.status = 'active' and v_score < v_at_risk then
    v_new_status := 'at_risk';
  elsif v_acct.status = 'at_risk' and v_score > v_healthy then
    v_new_status := 'active';
  end if;

  update customer_accounts
    set health_score = v_score, health_components = v_components, status = v_new_status
    where id = p_account;

  -- Audit ONLY on a status change — not on every recompute.
  if v_new_status <> v_acct.status then
    perform append_audit_event_internal(
      v_acct.tenant_id, 'Success DE', 'de',
      format('Account health flip — %s: %s → %s (score %s, at-risk < %s, healthy > %s)',
             v_acct.name, v_acct.status, v_new_status, v_score, v_at_risk, v_healthy),
      'config_change',
      jsonb_build_object('kind', 'health_recompute', 'account_id', p_account,
                         'old_status', v_acct.status, 'new_status', v_new_status,
                         'score', v_score, 'components', v_components));
  end if;

  return v_components || jsonb_build_object('status', v_new_status, 'status_changed', v_new_status <> v_acct.status);
end;
$function$;

CREATE OR REPLACE FUNCTION public.compute_approval_brief(p_task_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  t          record;
  ex         record;
  v_category text;
  v_amount   bigint;
  v_appr     int := 0;
  v_rej      int := 0;
  v_last     date;
  v_exact    boolean := false;
  v_landed   int := 0;
  v_landed_at date;
  v_batch    int := 0;
  v_dials    record;
  ev         jsonb := '[]'::jsonb;
  v_attention text[] := '{}';
  v_caution   text[] := '{}';
  v_risk     text;
  v_headline text;
  v_money    text;
begin
  select ht.id, ht.tenant_id, ht.type, ht.status, ht.updated_at,
         tn.status as tenant_status
    into t
    from human_tasks ht
    left join tenants tn on tn.id = ht.tenant_id
   where ht.id = p_task_id;
  if not found or t.type not in ('action_approval', 'trust_promotion') then
    return null;
  end if;
  -- mig 710: a trust-widening proposal gets its own rail-composed brief.
  if t.type = 'trust_promotion' then
    return public.compute_trust_proposal_brief(p_task_id);
  end if;

  -- The gated execution behind the button, by EITHER linkage column —
  -- resolves_task_id was unpopulated before August (mig 642's lesson: a
  -- linkage column is not a fact, so read both).
  select ae.id, ae.action_definition_id, ae.request_summary,
         ad.action_key, ad.category, ad.label,
         coalesce((ad.risk->>'destructive')::boolean, false) as destructive
    into ex
    from action_executions ae
    join action_definitions ad on ad.id = ae.action_definition_id
   where (ae.task_id = p_task_id or ae.resolves_task_id = p_task_id)
     and ae.decision like 'human_gated%'
   order by ae.created_at desc
   limit 1;

  -- Category and amount through THE definition the authority gate itself
  -- reads (mig 593) — never a re-derivation that can drift from it.
  select f.category, f.amount_cents into v_category, v_amount
    from task_approval_facts(p_task_id) f;

  -- ── Evidence line: the executor ─────────────────────────────────────────
  if ex.id is null then
    ev := ev || to_jsonb('No executor is linked to this approval — approving would mark it approved and send nothing.'::text);
    v_attention := array_append(v_attention, 'nothing is behind the button');
  else
    ev := ev || to_jsonb(('Action: ' || coalesce(ex.label, ex.action_key)
          || ' (' || coalesce(ex.category, 'uncategorised') || ').'
          || case when ex.destructive
                  then ' Destructive — approving sends or changes something outside the platform.'
                  else '' end)::text);
  end if;

  -- ── Evidence line: identical prior decisions (same workspace, same
  --    action definition — the strictest honest meaning of "identical") ──
  if ex.id is not null then
    select count(distinct h2.id) filter (where h2.status = 'approved'),
           count(distinct h2.id) filter (where h2.status = 'rejected'),
           max(h2.decided_at)::date
      into v_appr, v_rej, v_last
      from human_tasks h2
      join action_executions ae2
        on (ae2.task_id = h2.id or ae2.resolves_task_id = h2.id)
     where h2.tenant_id = t.tenant_id
       and h2.type = 'action_approval'
       and h2.status in ('approved','rejected')
       and ae2.action_definition_id = ex.action_definition_id;

    if coalesce(v_appr,0) + coalesce(v_rej,0) = 0 then
      ev := ev || to_jsonb('No prior decision on this action in this workspace — this is the first of its kind here.'::text);
      v_caution := array_append(v_caution, 'first of its kind here');
    else
      ev := ev || to_jsonb((v_appr || ' identical prior request(s) approved in this workspace'
            || case when v_last is not null then ' (most recent ' || v_last || ')' else '' end
            || '; ' || v_rej || ' rejected.')::text);
      if v_rej > 0 and v_appr = 0 then
        v_attention := array_append(v_attention, 'every prior identical request was rejected');
      elsif v_rej > 0 then
        v_caution := array_append(v_caution, 'this action has been rejected here before');
      end if;
    end if;

    -- Exact repeat: the same request summary, already decided.
    select exists (
      select 1 from human_tasks h3
        join action_executions ae3
          on (ae3.task_id = h3.id or ae3.resolves_task_id = h3.id)
       where h3.tenant_id = t.tenant_id and h3.type = 'action_approval'
         and h3.status in ('approved','rejected')
         and ae3.action_definition_id = ex.action_definition_id
         and ae3.request_summary is not distinct from ex.request_summary
    ) into v_exact;
    if v_exact then
      ev := ev || to_jsonb('This exact request (same summary) has been decided here before.'::text);
    end if;

    -- Did the work actually LAND when it was approved? Through THE shared
    -- predicate (mig 679), never an open-coded copy.
    select count(*), max(ex2.created_at)::date into v_landed, v_landed_at
      from action_executions ex2
     where ex2.tenant_id = t.tenant_id
       and ex2.action_definition_id = ex.action_definition_id
       and public.action_execution_landed(ex2);
    if v_landed > 0 then
      ev := ev || to_jsonb(('The last execution of this action here landed ('
            || v_landed_at || '); ' || v_landed || ' landed in total.')::text);
    elsif coalesce(v_appr,0) > 0 then
      ev := ev || to_jsonb('Approved runs of this action have NEVER landed in this workspace — approval has not been producing results.'::text);
      v_caution := array_append(v_caution, 'past approvals never landed');
    else
      ev := ev || to_jsonb('This action has never executed in this workspace.'::text);
    end if;

    -- Batch context: how many of this same thing are queued right now.
    select count(*) into v_batch
      from human_tasks h4
      join action_executions ae4
        on (ae4.task_id = h4.id or ae4.resolves_task_id = h4.id)
     where h4.tenant_id = t.tenant_id and h4.type = 'action_approval'
       and h4.status = 'pending' and h4.id <> p_task_id
       and ae4.action_definition_id = ex.action_definition_id;
    if v_batch > 0 then
      ev := ev || to_jsonb(('One of ' || (v_batch + 1) || ' pending requests for this same action in this queue.')::text);
    end if;

    if ex.destructive and coalesce(v_appr,0) = 0 then
      v_attention := array_append(v_attention, 'destructive with no precedent');
    end if;
  end if;

  -- ── Evidence line: the money against the workspace's dials (migs 626/7) ─
  if v_amount is null then
    ev := ev || to_jsonb('No amount is attached to this request.'::text);
  else
    v_money := '$' || to_char(round(v_amount / 100.0, 2), 'FM999,999,999,990.00');
    select count(*) as n,
           bool_or(a.max_amount_cents is null) as unlimited,
           max(a.max_amount_cents) as ceiling,
           min(a.second_approver_above_cents) as second_above
      into v_dials
      from approval_authority a
     where a.tenant_id = t.tenant_id and a.is_active
       and (a.category is null or a.category = v_category);
    if coalesce(v_dials.n, 0) = 0 then
      ev := ev || to_jsonb((v_money || ' attached; no approval limits are declared for this kind of work, so the permissive default applies.')::text);
    elsif coalesce(v_dials.unlimited, false) or v_amount <= coalesce(v_dials.ceiling, 0) then
      ev := ev || to_jsonb((v_money || ' is within this workspace''s approval limits'
            || case when coalesce(v_dials.unlimited, false) then ' (an unlimited grant exists)'
                    else ' (top ceiling $' || to_char(round(v_dials.ceiling / 100.0, 2), 'FM999,999,999,990.00') || ')' end
            || '.')::text);
    else
      ev := ev || to_jsonb((v_money || ' is ABOVE every declared ceiling for this kind of work (max $'
            || to_char(round(coalesce(v_dials.ceiling,0) / 100.0, 2), 'FM999,999,999,990.00') || ').')::text);
      v_attention := array_append(v_attention, 'amount above every declared ceiling');
    end if;
    if v_dials.second_above is not null and v_amount > v_dials.second_above then
      -- min() across ALL matching grants, so this is the most conservative
      -- threshold — an unlimited owner may not need the second signature.
      -- "may", honestly, never "will".
      ev := ev || to_jsonb(('Crosses the lowest second-signature threshold ($'
            || to_char(round(v_dials.second_above / 100.0, 2), 'FM999,999,999,990.00')
            || ') — depending on who approves, a second approver may be required.')::text);
      v_caution := array_append(v_caution, 'may need a second signature');
    end if;
  end if;

  -- ── Evidence line: workspace standing. Only SUSPENSION is the dormancy
  --    state where deciding achieves nothing (tenant-suspension machinery);
  --    'trial' operates normally and must not cry wolf — a rank that flags
  --    every trial workspace teaches people to ignore 'attention'. ────────
  if t.tenant_status = 'suspended' or t.tenant_status is null then
    ev := ev || to_jsonb(('This workspace is ' || coalesce(t.tenant_status, 'gone')
          || ' — nothing will execute until it is reinstated.')::text);
    v_attention := array_append(v_attention, 'workspace is ' || coalesce(t.tenant_status, 'gone'));
  elsif t.tenant_status <> 'active' and t.tenant_status <> 'trial' then
    ev := ev || to_jsonb(('Workspace status: ' || t.tenant_status || '.')::text);
  end if;

  -- ── The rank and the advisory sentence — rail-composed, never a model ───
  if array_length(v_attention, 1) is not null then
    v_risk := 'attention';
    v_headline := 'Needs attention — ' || array_to_string(v_attention, '; ') || '.';
  elsif array_length(v_caution, 1) is not null then
    v_risk := 'caution';
    v_headline := 'Worth a look — ' || array_to_string(v_caution, '; ') || '.';
  else
    v_risk := 'routine';
    v_headline := 'Looks routine — ' || v_appr || ' identical prior approval(s), none rejected'
      || case when v_landed > 0 then ', and the last run landed.' else '.' end;
  end if;

  return jsonb_build_object(
    'risk', v_risk,
    'headline', v_headline,
    'evidence', ev,
    'category', v_category,
    'amount_cents', v_amount
  );
end $function$;

CREATE OR REPLACE FUNCTION public.compute_confidence_dimensions(p_base_confidence integer, p_has_sources boolean DEFAULT NULL::boolean, p_identity_verified boolean DEFAULT NULL::boolean, p_action_ready boolean DEFAULT NULL::boolean)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT jsonb_strip_nulls(jsonb_build_object(
    'knowledge', greatest(0, least(100, coalesce(p_base_confidence, 0))),
    'grounding', case when p_has_sources is null then null when p_has_sources then 90 else 30 end,
    'identity',  case when p_identity_verified is null then null when p_identity_verified then 90 else 40 end,
    'action',    case when p_action_ready is null then null when p_action_ready then 80 else null end
  ));
$function$;

CREATE OR REPLACE FUNCTION public.compute_de_lifecycle_readiness(p_de_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_de digital_employees;
  v_tenant uuid;
  v_identity boolean;
  v_grants boolean;
  v_knowledge boolean;
  v_policies boolean;
  v_embedded boolean;
  v_qa_passed boolean;
  v_certified boolean;
  v_channel boolean;
  v_grounding jsonb;
  v_executed boolean;
begin
  select * into v_de from digital_employees where id = p_de_id;
  if v_de.id is null then return jsonb_build_object('error', 'not_found'); end if;
  v_tenant := v_de.tenant_id;

  -- Humans must belong to the workspace; trusted server contexts pass.
  if auth.role() is not null and auth.role() <> 'service_role' then
    if auth_tenant_id() is distinct from v_tenant then
      raise exception 'not a member of this workspace';
    end if;
    if not public.can_access_de(p_de_id) then
      return jsonb_build_object('error', 'not_found');
    end if;
  end if;

  v_identity := coalesce(v_de.name, '') <> '' and coalesce(v_de.description, '') <> ''
    and (coalesce(v_de.department, '') <> '' or coalesce(v_de.workspace, '') <> '')
    and coalesce(array_length(v_de.responsibilities, 1), 0) >= 1;

  v_grants := exists (select 1 from data_access_grants
    where tenant_id = v_tenant and subject_kind = 'de' and subject_id = p_de_id);

  v_knowledge := exists (select 1 from knowledge_docs d
    where d.tenant_id = v_tenant
      and (d.visibility = 'tenant'
           or exists (select 1 from knowledge_doc_scopes s
                      where s.doc_id = d.id and s.subject_kind = 'de' and s.subject_id = p_de_id)));

  v_policies := exists (select 1 from guardrail_rules where tenant_id = v_tenant and active);

  v_embedded := exists (select 1 from knowledge_doc_chunks c
    join knowledge_docs d on d.id = c.doc_id
    where d.tenant_id = v_tenant and c.embedding is not null
      and (d.visibility = 'tenant'
           or exists (select 1 from knowledge_doc_scopes s
                      where s.doc_id = d.id and s.subject_kind = 'de' and s.subject_id = p_de_id)));

  v_qa_passed := coalesce((select r.status = 'passed' from eval_runs r
    where r.tenant_id = v_tenant
    order by coalesce(r.finished_at, r.started_at) desc limit 1), false);

  v_certified := exists (select 1 from de_lifecycle_events
    where tenant_id = v_tenant and de_id = p_de_id and to_stage = 'certified' and actor_id is not null);

  v_channel := exists (select 1 from data_access_grants g
      where g.tenant_id = v_tenant and g.subject_kind = 'de' and g.subject_id = p_de_id
        and access_permission_level(g.permission) >= access_permission_level('search'))
    or exists (select 1 from widget_keys where tenant_id = v_tenant and active);

  v_executed := exists (select 1 from evidence_runs where tenant_id = v_tenant and de_id = p_de_id);
  -- Mig 796: grounding. required_connector_categories was DECORATIVE — its one
  -- reader displayed it on the Record tab and nothing gated hiring or work, so
  -- an SEO employee could be hired with nothing to read and would run anyway,
  -- producing plausible generic content (measured 2026-07-28, still true
  -- 2026-08-11). A required category counts as met only when this tenant has a
  -- CONNECTED connector in it. No archetype, or no requirements ⇒ trivially
  -- grounded — a bespoke employee is not penalised for having no template.
  select coalesce(jsonb_object_agg(req.cat,
           exists (select 1 from connectors k
                    where k.tenant_id = v_tenant and k.category = req.cat
                      and k.status = 'connected')), '{}'::jsonb)
    into v_grounding
    from (select unnest(ra.required_connector_categories) as cat
            from digital_employees d
            join role_archetypes ra on ra.key = d.archetype_key
           where d.id = p_de_id) req;

  return jsonb_build_object(
    'stage', v_de.lifecycle_status,
    'status', v_de.status,
    'criteria', jsonb_build_object(
      'configured', jsonb_build_object(
        'identity_complete', v_identity,
        'detail', 'Name, description, a department or workspace, and at least one responsibility.'),
      'trained', jsonb_build_object(
        'control_fabric_grant', v_grants,
        'knowledge_in_scope', v_knowledge,
        'active_guardrails', v_policies,
        'detail', 'At least one system-access grant, knowledge this employee can see, and active workspace guardrails.'),
      'tested', jsonb_build_object(
        'knowledge_embedded', v_embedded,
        'detail', 'The knowledge in scope is actually searchable (embedded), so answers can cite it.'),
      'certified', jsonb_build_object(
        'golden_qa_passed', v_qa_passed,
        'scope', 'workspace',
        'detail', 'The latest golden Q&A run passed. (Suite is workspace-level today — per-employee suites arrive with Skills, DE-C1.)'),
      'published', jsonb_build_object(
        'certified_by_human', v_certified,
        'detail', 'A named workspace owner/admin recorded certification.'),
      'assigned', jsonb_build_object(
        'has_work_channel', v_channel,
        'grounding_connected', (select coalesce(bool_and(v::boolean), true) from jsonb_each_text(v_grounding) as e(k, v)),
        'grounding_by_category', v_grounding,
        'detail', 'A searchable system grant (inbox) or an active site widget key.'),
      'active', jsonb_build_object(
        'first_live_execution', v_executed,
        'detail', 'At least one real evidence run attributed to this employee.')
    )
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.compute_inquiry_confidence(p_inputs jsonb)
 RETURNS integer
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select greatest(0, least(97,
    40
    + least(24, 8 * coalesce((p_inputs->>'knowledge_hits')::int, 0))
    + least(24, 8 * coalesce((p_inputs->>'history_corroborations')::int, 0))
    + case when coalesce((p_inputs->>'account_context_found')::boolean, false) then 12 else 0 end
    - 15 * coalesce((p_inputs->>'systems_failed')::int, 0)
  ))::integer;
$function$;

CREATE OR REPLACE FUNCTION public.compute_tenant_health(p_force boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_tenant uuid;
  v_is_active boolean;
  v_last   timestamptz;
  v_n      integer := 0;
  v_flips  integer := 0;
  v_acct   record;
  v_res    jsonb;
begin
  select coalesce(is_active, true) into v_is_active from profiles where user_id = auth.uid() limit 1;
  if v_is_active is false then raise exception 'account is deactivated'; end if;
  v_tenant := auth_tenant_id();
  if v_tenant is null then raise exception 'no tenant for caller'; end if;

  insert into health_score_config (tenant_id) values (v_tenant)
  on conflict (tenant_id) do nothing;

  select last_computed_at into v_last from health_score_config where tenant_id = v_tenant;
  if not p_force and v_last is not null and v_last > now() - interval '1 hour' then
    return jsonb_build_object('computed', 0, 'skipped', true, 'last_computed_at', v_last);
  end if;

  for v_acct in select id from customer_accounts where tenant_id = v_tenant and status <> 'churned' loop
    v_res := compute_account_health_core(v_acct.id);
    v_n := v_n + 1;
    if coalesce((v_res->>'status_changed')::boolean, false) then v_flips := v_flips + 1; end if;
  end loop;

  update health_score_config set last_computed_at = now() where tenant_id = v_tenant;
  return jsonb_build_object('computed', v_n, 'status_flips', v_flips, 'skipped', false);
end;
$function$;

CREATE OR REPLACE FUNCTION public.compute_tenant_health_service(p_tenant_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_n     integer := 0;
  v_flips integer := 0;
  v_acct  record;
  v_res   jsonb;
begin
  for v_acct in select id from customer_accounts where tenant_id = p_tenant_id and status <> 'churned' loop
    v_res := compute_account_health_core(v_acct.id);
    v_n := v_n + 1;
    if coalesce((v_res->>'status_changed')::boolean, false) then v_flips := v_flips + 1; end if;
  end loop;
  insert into health_score_config (tenant_id, last_computed_at) values (p_tenant_id, now())
  on conflict (tenant_id) do update set last_computed_at = now();
  return jsonb_build_object('computed', v_n, 'status_flips', v_flips);
end;
$function$;

CREATE OR REPLACE FUNCTION public.compute_trust_evidence(p_de_id uuid, p_action_category text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_tenant uuid;
  v_is_active boolean;
  v_policy trust_policies;
begin
  select tenant_id, coalesce(is_active, true) into v_tenant, v_is_active from profiles where user_id = auth.uid() limit 1;
  if v_tenant is null then
    raise exception 'not a member of any tenant';
  end if;
  if not v_is_active then
    raise exception 'account is deactivated';
  end if;
  if p_de_id is not null and not public.can_access_de(p_de_id) then
    raise exception 'not_responsible_for_de';
  end if;

  -- Scope resolution (fixed here): a NULL p_de_id asks about the WORKSPACE
  -- and must never surface an employee-scoped policy; a set p_de_id prefers
  -- that employee's own policy and falls back to the workspace default.
  select * into v_policy
  from trust_policies
  where tenant_id = v_tenant
    and action_category = p_action_category
    and (de_id is null or (p_de_id is not null and de_id = p_de_id))
  order by (de_id is not null) desc
  limit 1;
  if not found then
    raise exception 'no trust policy for category %', p_action_category;
  end if;

  return trust_evidence_for(v_policy);
end;
$function$;

CREATE OR REPLACE FUNCTION public.compute_trust_proposal_brief(p_task_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  t          record;
  pol        trust_policies;
  pat        jsonb;
  n          integer;
  ev         jsonb := '[]'::jsonb;
  v_attention text[] := '{}';
  v_caution   text[] := '{}';
  v_risk     text;
  v_headline text;
begin
  select ht.id, ht.tenant_id, ht.type, ht.status, tn.status as tenant_status
    into t
    from human_tasks ht
    left join tenants tn on tn.id = ht.tenant_id
   where ht.id = p_task_id;
  if not found or t.type <> 'trust_promotion' then
    return null;
  end if;

  select p.* into pol from trust_policies p where p.pending_task_id = p_task_id;

  if pol.id is null then
    ev := ev || to_jsonb('No trust policy is linked to this proposal — approving would decide the task and change NOTHING (the apply hook would no-op).'::text);
    v_attention := array_append(v_attention, 'nothing is behind the button');
  else
    ev := ev || to_jsonb(format('Approving widens "%s" from level %s to level %s for one employee. Evidence is re-verified at apply time; automatic demotion can undo it.',
            pol.action_category, pol.current_level,
            least(pol.current_level + 1, least(3, coalesce(pol.max_level, 3))))::text);

    pat := pol.pending_evidence->'pattern';
    if pat is not null and jsonb_typeof(pat) = 'object' then
      n := coalesce((pat->>'n_approved')::integer, 0);
      ev := ev || to_jsonb(format('%s identical production approvals of "%s" in the last %s days — every one landed, zero rejections. Raised automatically by the pattern detector.',
              n, pat->>'action_key', pat->>'window_days')::text);
      if n < 3 then
        ev := ev || to_jsonb('The citation names fewer decisions than the pattern floor (3) — this proposal should not exist in this state.'::text);
        v_attention := array_append(v_attention, 'cites fewer decisions than the pattern floor');
      end if;
    else
      ev := ev || to_jsonb('Requested by a person from the employee file (no pattern citation) — the policy criteria were met at request time and are re-verified at apply.'::text);
      v_caution := array_append(v_caution, 'human-requested; review the criteria evidence');
    end if;
  end if;

  -- Workspace standing — same rule and same wording family as mig 705.
  if t.tenant_status = 'suspended' or t.tenant_status is null then
    ev := ev || to_jsonb(('This workspace is ' || coalesce(t.tenant_status, 'gone')
          || ' — nothing will execute until it is reinstated.')::text);
    v_attention := array_append(v_attention, 'workspace is ' || coalesce(t.tenant_status, 'gone'));
  elsif t.tenant_status <> 'active' and t.tenant_status <> 'trial' then
    ev := ev || to_jsonb(('Workspace status: ' || t.tenant_status || '.')::text);
  end if;

  if array_length(v_attention, 1) is not null then
    v_risk := 'attention';
    v_headline := 'Needs attention — ' || array_to_string(v_attention, '; ') || '.';
  elsif array_length(v_caution, 1) is not null then
    v_risk := 'caution';
    v_headline := 'Worth a look — ' || array_to_string(v_caution, '; ') || '.';
  else
    v_risk := 'routine';
    v_headline := format('Looks routine — %s identical landed approvals earned this; approving widens one dial, and demotion can undo it.', coalesce(n, 0));
  end if;

  return jsonb_build_object(
    'risk', v_risk,
    'headline', v_headline,
    'evidence', ev,
    'category', 'trust_promotion',
    'amount_cents', null
  );
end $function$;

CREATE OR REPLACE FUNCTION public.conclude_objective_verified(p_tenant_id uuid, p_objective_id uuid, p_assessment text, p_note text DEFAULT NULL::text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_enforce boolean := false;
  v_master boolean; v_tenant_on boolean; v_mode text;
  v_assess jsonb; v_final text := p_assessment;
begin
  begin
    select (value = 'true') into v_master from platform_config where key = 'definition_of_done.enabled';
    if coalesce(v_master, false) then
      select is_feature_enabled_internal(p_tenant_id, 'definition_of_done') into v_tenant_on;
      if v_tenant_on is true then
        select value into v_mode from platform_config where key = 'definition_of_done.mode';
        v_enforce := coalesce(v_mode, 'shadow') = 'enforce';
      end if;
    end if;
  exception when others then v_enforce := false; end;   -- flag axis fails to current behavior

  if p_assessment = 'achieved' then
    v_assess := assess_definition_of_done(p_tenant_id, 'objective', p_objective_id, p_objective_id);
    begin
      insert into definition_of_done_log (tenant_id, writer, scope, scope_id, objective_id, verdict, would_withhold, enforced)
      values (p_tenant_id, 'objective', 'objective', p_objective_id, p_objective_id, v_assess, not (v_assess->>'verified')::boolean, v_enforce);
    exception when others then null; end;
    if v_enforce and not (v_assess->>'verified')::boolean then
      v_final := 'in_progress';   -- withhold; re-reviewed once the evidence lands
    end if;
  end if;

  update de_objectives set status = v_final, updated_at = now()
    where id = p_objective_id and tenant_id = p_tenant_id;
  return v_final;
end $function$;

CREATE OR REPLACE FUNCTION public.conclude_objective_wake(p_objective_id uuid, p_assessment text, p_note text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if p_assessment = 'achieved' then
    update de_objectives set status = 'achieved', next_wake_at = null, updated_at = now()
     where id = p_objective_id and status in ('open', 'in_progress', 'blocked');
  elsif p_assessment = 'blocked' then
    -- Re-arm, do not disarm. A blocked objective must come back around so the
    -- stall can be re-assessed and re-escalated; 24h is slow enough that a
    -- genuinely blocked goal is not the hourly spin docs/38 measured.
    update de_objectives
       set status = 'blocked',
           next_wake_at = now() + interval '24 hours',
           updated_at = now()
     where id = p_objective_id and status in ('open', 'in_progress', 'blocked');
  elsif p_assessment = 'continue' then
    null;
  else
    raise exception 'assessment must be achieved | blocked | continue';
  end if;

  -- The note the platform used to throw away. Written to the most recent
  -- unconcluded wake for this objective (wake_count may have advanced if a
  -- later wake started, so anchor on the open row, not on the counter).
  update de_objective_wakes
     set concluded_at = now(),
         assessment = p_assessment,
         note = coalesce(p_note, '')
   where id = (
     select w.id from de_objective_wakes w
      where w.objective_id = p_objective_id and w.concluded_at is null
      order by w.wake_no desc
      limit 1
   );
end;
$function$;

CREATE OR REPLACE FUNCTION public.connector_circuit_open(p_failures integer, p_last_error_at timestamp with time zone)
 RETURNS boolean
 LANGUAGE sql
 STABLE
AS $function$
  -- Open (i.e. suppress dispatch) once a connector has failed repeatedly AND
  -- is still failing recently. 10 is generous enough that a transient blip or
  -- a brief provider wobble never trips it; an hour of quiet is short enough
  -- that a fixed connector recovers by itself within the hour.
  select coalesce(p_failures, 0) >= 10
     and p_last_error_at is not null
     and p_last_error_at > now() - interval '1 hour';
$function$;

CREATE OR REPLACE FUNCTION public.count_pending_knowledge_gaps(p_tenant_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_count int;
begin
  perform public._assert_caller_tenant(p_tenant_id);

  select count(*) into v_count
  from knowledge_revision_requests
  where tenant_id = p_tenant_id
    and status = 'pending_approval';

  return coalesce(v_count, 0);
end;
$function$;

CREATE OR REPLACE FUNCTION public.create_browser_operation(p_de_id uuid, p_system_key text, p_instruction text, p_max_steps integer DEFAULT 20)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  s de_connected_systems; v_tenant uuid; v_domain text; v_cred text; v_task uuid; v_ht uuid;
  v_de_name text; v_goal text; v_title text;
  v_is_service boolean := coalesce(auth.role(),'') = 'service_role';
BEGIN
  SELECT tenant_id INTO v_tenant FROM digital_employees WHERE id = p_de_id;
  IF v_tenant IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'de_not_found'); END IF;
  -- de-work (service) or a tenant admin acting for the DE.
  IF NOT v_is_service AND NOT (v_tenant = public.auth_tenant_id()
       AND public.auth_has_tenant_role(ARRAY['tenant_owner','tenant_admin','tenant_manager'])) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_permitted');
  END IF;
  -- DE scoping (mig 385/414). DEFENCE IN DEPTH, NOT A FIX: every role that
  -- passes the gate above already satisfies the check below. It bites only
  -- if browser operations are opened below manager — and a task here can
  -- carry credential_policy = vault_injected, i.e. a real stored credential
  -- for a customer system, so that is the day it must already be present.
  IF NOT public.can_access_de(p_de_id) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_responsible_for_de');
  END IF;
  IF NOT public.is_feature_enabled_internal(v_tenant, 'computer_use') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'browser_operator_disabled');
  END IF;

  SELECT * INTO s FROM de_connected_systems
    WHERE de_id = p_de_id AND system_key = p_system_key AND active AND can_operate;
  IF s.id IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'system_not_operable'); END IF;

  v_domain := public.operate_domain_of(s);
  IF v_domain IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'no_operate_domain'); END IF;
  IF nullif(btrim(coalesce(p_instruction,'')),'') IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'instruction_required'); END IF;

  SELECT coalesce(persona_name, name, 'DE') INTO v_de_name FROM digital_employees WHERE id = p_de_id;
  v_title := format('Operate %s', coalesce(s.label, p_system_key));
  v_goal  := format(E'In %s (%s): %s\n\nWork within this app only. When finished, report the outcome as JSON: what you changed/found and any IDs. Do not perform irreversible actions (payments, deletions, sending) — hand those to a human.',
                    coalesce(s.label, p_system_key), v_domain, btrim(p_instruction));

  INSERT INTO computer_use_tasks (tenant_id, de_id, goal, allowed_domains, max_steps, engine, credential_policy, title)
  VALUES (v_tenant, p_de_id, v_goal, ARRAY[v_domain], greatest(1, least(50, coalesce(p_max_steps,20))),
          'browser_dom',
          CASE WHEN s.login_secret_id IS NOT NULL THEN 'vault_injected' ELSE 'human_login' END,
          v_title)
  RETURNING id INTO v_task;

  INSERT INTO human_tasks (tenant_id, type, source, title, detail, related_table, related_id)
  VALUES (v_tenant, 'approval_gate', 'de',
    format('%s wants to operate %s', v_de_name, coalesce(s.label, p_system_key)),
    format(E'%s wants to run this in %s (%s):\n\n%s\n\nIt stays on %s, is limited to %s steps, never performs payments/deletions without you, and records every step.',
           v_de_name, coalesce(s.label, p_system_key), v_domain, btrim(p_instruction), v_domain, greatest(1, least(50, coalesce(p_max_steps,20)))),
    'computer_use_tasks', v_task)
  RETURNING id INTO v_ht;
  UPDATE computer_use_tasks SET human_task_id = v_ht, updated_at = now() WHERE id = v_task;

  BEGIN PERFORM append_audit_event_internal(v_tenant, v_de_name, 'de',
    format('%s requested a browser operation in %s', v_de_name, coalesce(s.label, p_system_key)), 'de_consultation',
    jsonb_build_object('kind','browser_operation_requested','task_id',v_task,'system_key',p_system_key,'domain',v_domain));
  EXCEPTION WHEN OTHERS THEN NULL; END;

  RETURN jsonb_build_object('ok', true, 'task_id', v_task, 'domain', v_domain,
    'credential_policy', CASE WHEN s.login_secret_id IS NOT NULL THEN 'vault_injected' ELSE 'human_login' END,
    'status', 'pending_approval');
END; $function$;

CREATE OR REPLACE FUNCTION public.create_config_schema(p_tenant_id uuid, p_entity_kind text, p_entity_id uuid DEFAULT NULL::uuid, p_name text DEFAULT NULL::text, p_fields jsonb DEFAULT '[]'::jsonb, p_tags text[] DEFAULT '{}'::text[])
 RETURNS TABLE(schema_id uuid, tenant_id uuid, entity_kind text, entity_id uuid, name text, fields jsonb, tags text[], created_at timestamp with time zone, updated_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_schema_id UUID := gen_random_uuid();
BEGIN
  PERFORM public._assert_caller_tenant(p_tenant_id);
  INSERT INTO de_config_schemas (schema_id, tenant_id, entity_kind, entity_id, name, fields, tags)
  VALUES (v_schema_id, p_tenant_id, p_entity_kind, p_entity_id, p_name, p_fields, p_tags);
  RETURN QUERY SELECT * FROM de_config_schemas s WHERE s.schema_id = v_schema_id;
END$function$;

CREATE OR REPLACE FUNCTION public.create_custom_metric(p_tenant_id uuid, p_name text, p_key text, p_type text, p_description text, p_unit text DEFAULT NULL::text, p_calculation_rule text DEFAULT NULL::text, p_query_template text DEFAULT NULL::text, p_tags text[] DEFAULT '{}'::text[], p_thresholds jsonb DEFAULT NULL::jsonb)
 RETURNS TABLE(metric_id uuid, tenant_id uuid, name text, key text, type text, description text, unit text, calculation_rule text, query_template text, tags text[], thresholds jsonb, created_at timestamp with time zone, created_by uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_metric_id UUID := gen_random_uuid();
BEGIN
  PERFORM public._assert_caller_tenant(p_tenant_id);
  INSERT INTO customer_metrics (
    metric_id, tenant_id, name, key, type, description, unit,
    calculation_rule, query_template, tags, thresholds, created_by
  ) VALUES (
    v_metric_id, p_tenant_id, p_name, p_key, p_type, p_description, p_unit,
    p_calculation_rule, p_query_template, p_tags, p_thresholds, auth.uid()
  );
  RETURN QUERY SELECT * FROM customer_metrics cm WHERE cm.metric_id = v_metric_id;
END$function$;

CREATE OR REPLACE FUNCTION public.create_de_mission(p_de_id uuid, p_directive text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tenant uuid; v_id uuid;
BEGIN
  v_tenant := public.auth_tenant_id();
  IF v_tenant IS NULL OR NOT public.auth_has_tenant_role(
       ARRAY['tenant_owner','tenant_admin','tenant_manager']) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_permitted');
  END IF;
  IF length(btrim(coalesce(p_directive,''))) < 8 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'directive_too_short');
  END IF;
  IF NOT EXISTS (SELECT 1 FROM digital_employees
                 WHERE id = p_de_id AND tenant_id = v_tenant AND status = 'active') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'unknown_or_inactive_de');
  END IF;
  -- DE scoping (mig 385/421). DEFENCE IN DEPTH: the manager+ gate above
  -- already implies this. The existence check has proven p_de_id is an
  -- active employee in this workspace, so no null case.
  IF NOT public.can_access_de(p_de_id) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_responsible_for_de');
  END IF;
  INSERT INTO de_missions (tenant_id, de_id, directive_text, created_by)
  VALUES (v_tenant, p_de_id, btrim(p_directive), auth.uid())
  RETURNING id INTO v_id;
  RETURN jsonb_build_object('ok', true, 'mission_id', v_id);
END $function$;

CREATE OR REPLACE FUNCTION public.create_de_team_mission(p_target_spec jsonb, p_directive text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tenant uuid; v_id uuid; v_kind text; v_routing text;
  v_de_ids uuid[]; v_sup uuid; v_arch text; v_bad int;
BEGIN
  v_tenant := public.auth_tenant_id();
  IF v_tenant IS NULL OR NOT public.auth_has_tenant_role(
       ARRAY['tenant_owner','tenant_admin','tenant_manager']) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_permitted');
  END IF;
  IF length(btrim(coalesce(p_directive,''))) < 8 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'directive_too_short');
  END IF;

  v_kind    := p_target_spec->>'kind';
  v_routing := coalesce(p_target_spec->>'routing', 'auto');
  IF v_kind NOT IN ('archetype','explicit','supervisor') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'bad_target_kind');
  END IF;
  IF v_routing NOT IN ('auto','owner_continuity','least_loaded','round_robin') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'bad_routing');
  END IF;

  IF v_kind = 'archetype' THEN
    v_arch := p_target_spec->>'archetype_key';
    IF v_arch IS NULL THEN
      RETURN jsonb_build_object('ok', false, 'error', 'archetype_required');
    END IF;
    IF NOT EXISTS (SELECT 1 FROM digital_employees
                   WHERE tenant_id = v_tenant AND archetype_key = v_arch AND status = 'active') THEN
      RETURN jsonb_build_object('ok', false, 'error', 'no_active_de_for_archetype');
    END IF;

  ELSIF v_kind = 'explicit' THEN
    BEGIN
      SELECT array_agg((x)::uuid) INTO v_de_ids
        FROM jsonb_array_elements_text(coalesce(p_target_spec->'de_ids', '[]'::jsonb)) x;
    EXCEPTION WHEN others THEN
      RETURN jsonb_build_object('ok', false, 'error', 'bad_de_ids');
    END;
    IF v_de_ids IS NULL OR array_length(v_de_ids, 1) IS NULL THEN
      RETURN jsonb_build_object('ok', false, 'error', 'de_ids_required');
    END IF;
    SELECT count(*) INTO v_bad FROM unnest(v_de_ids) d
     WHERE NOT EXISTS (SELECT 1 FROM digital_employees
                       WHERE id = d AND tenant_id = v_tenant AND status = 'active');
    IF v_bad > 0 THEN
      RETURN jsonb_build_object('ok', false, 'error', 'unknown_or_foreign_de');
    END IF;

  ELSE  -- supervisor
    BEGIN
      v_sup := (p_target_spec->>'supervisor_de_id')::uuid;
    EXCEPTION WHEN others THEN
      RETURN jsonb_build_object('ok', false, 'error', 'bad_supervisor_id');
    END;
    IF v_sup IS NULL OR NOT EXISTS (SELECT 1 FROM digital_employees
          WHERE id = v_sup AND tenant_id = v_tenant AND status = 'active') THEN
      RETURN jsonb_build_object('ok', false, 'error', 'unknown_or_foreign_supervisor');
    END IF;
  END IF;

  -- DE scoping (mig 385/422). DEFENCE IN DEPTH: the manager+ gate above
  -- already implies all three of these. Checked here, once, where every
  -- branch variable is resolved. ALL matching employees must be accessible,
  -- not any — a mission aimed at a set acts through the whole set.
  IF v_de_ids IS NOT NULL AND EXISTS (
       SELECT 1 FROM unnest(v_de_ids) d WHERE NOT public.can_access_de(d)) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_responsible_for_de');
  END IF;
  IF v_sup IS NOT NULL AND NOT public.can_access_de(v_sup) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_responsible_for_de');
  END IF;
  -- Archetype targets are re-resolved at dispatch; this tests the set as it
  -- stands now. An employee hired into the archetype later is not covered.
  IF v_arch IS NOT NULL AND EXISTS (
       SELECT 1 FROM digital_employees
        WHERE tenant_id = v_tenant AND archetype_key = v_arch AND status = 'active'
          AND NOT public.can_access_de(id)) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_responsible_for_de');
  END IF;
  INSERT INTO de_missions (tenant_id, de_id, target_spec, directive_text, created_by)
  VALUES (v_tenant, NULL, p_target_spec, btrim(p_directive), auth.uid())
  RETURNING id INTO v_id;
  RETURN jsonb_build_object('ok', true, 'mission_id', v_id);
END $function$;

CREATE OR REPLACE FUNCTION public.create_improvement_review(p_improvement_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare imp de_improvements; v_task uuid; v_name text; v_live_task uuid;
begin
  select * into imp from de_improvements where id = p_improvement_id;
  if imp.id is null then raise exception 'improvement not found'; end if;

  -- A review may be OPENED from a passing replay, or RE-ISSUED when the row
  -- says review_pending but its task is gone (deleted task + ON DELETE SET
  -- NULL leaves an invisible review that still holds a backpressure slot).
  if imp.status = 'review_pending' then
    select id into v_live_task from human_tasks where id = imp.human_task_id;
    if v_live_task is not null then
      raise exception 'review already open with a live task (%)', v_live_task;
    end if;
  elsif imp.status <> 'replayed' then
    raise exception 'improvement must have a PASSING replay before review (status is %)', imp.status;
  end if;

  select coalesce(persona_name, name, 'DE') into v_name from digital_employees where id = imp.de_id;
  insert into human_tasks (tenant_id, type, source, title, detail, related_table, related_id)
  values (imp.tenant_id, 'knowledge_revision', 'system',
    format('Approve knowledge fix proposed by %s — "%s"', v_name, left(imp.proposed_title, 80)),
    format(E'%s answered a question wrongly and proposes this knowledge fix.\n\nFailing question: %s\n\nWhy it failed: %s\n\nProposed article "%s":\n%s\n\nReplay proof: re-answering WITH this fix scored %s/100 (was %s/100); golden set %s/%s passed. Approving publishes the article scoped to this employee; rejecting discards it.',
      v_name, left(imp.failure_question, 300), left(imp.failure_rationale, 400),
      imp.proposed_title, left(imp.proposed_content, 1500),
      coalesce(imp.replay->'after'->>'score','?'), coalesce(imp.replay->'before'->>'score','?'),
      coalesce(imp.replay->'golden'->>'passed','?'), coalesce(imp.replay->'golden'->>'total','?')),
    'de_improvements', imp.id)
  returning id into v_task;

  update de_improvements set human_task_id = v_task, status = 'review_pending', updated_at = now()
   where id = p_improvement_id;
  return v_task;
end;
$function$;

CREATE OR REPLACE FUNCTION public.create_ingestion_job(p_label text, p_source_kind text, p_items jsonb, p_target_collection_id uuid DEFAULT NULL::uuid, p_source_ref text DEFAULT NULL::text, p_connector_id uuid DEFAULT NULL::uuid, p_publish_mode text DEFAULT 'published'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tenant uuid := auth_tenant_id(); v_job uuid; v_n int; v_lvl int;
BEGIN
  IF v_tenant IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  IF p_publish_mode NOT IN ('published','draft') THEN
    RAISE EXCEPTION 'publish mode must be published or draft';
  END IF;

  SELECT coalesce(max(knowledge_permission_rank(g.permission)), 0) INTO v_lvl
    FROM knowledge_access_grants g
   WHERE g.tenant_id = v_tenant AND g.resource_type = 'workspace'
     AND knowledge_grant_matches_caller(g);
  IF v_lvl < 2 AND NOT is_platform_admin() THEN
    RAISE EXCEPTION 'insufficient_permission: adding knowledge requires contributor';
  END IF;
  -- Publishing straight through is a publisher act. A contributor may still
  -- import — their work lands as drafts, which is exactly the review flow.
  IF p_publish_mode = 'published' AND v_lvl < 4 AND NOT is_platform_admin() THEN
    RAISE EXCEPTION 'insufficient_permission: publishing on import requires publisher — import as draft instead';
  END IF;

  IF p_target_collection_id IS NOT NULL
     AND NOT EXISTS (SELECT 1 FROM knowledge_collections c
                      WHERE c.id = p_target_collection_id AND c.tenant_id = v_tenant) THEN
    RAISE EXCEPTION 'target collection does not belong to this workspace';
  END IF;

  INSERT INTO knowledge_ingestion_jobs (tenant_id, label, source_kind, source_ref,
                                        target_collection_id, connector_id, created_by, publish_mode)
  VALUES (v_tenant, p_label, p_source_kind, p_source_ref,
          p_target_collection_id, p_connector_id, auth.uid(), p_publish_mode)
  RETURNING id INTO v_job;

  INSERT INTO knowledge_ingestion_items (job_id, tenant_id, source_ref, title, byte_size, mime_type, raw_content)
  SELECT v_job, v_tenant,
         coalesce(e->>'source_ref', e->>'url', e->>'filename', 'item'),
         e->>'title', (e->>'byte_size')::bigint, e->>'mime_type', e->>'content'
    FROM jsonb_array_elements(coalesce(p_items, '[]'::jsonb)) e;

  GET DIAGNOSTICS v_n = ROW_COUNT;
  IF v_n = 0 THEN RAISE EXCEPTION 'an ingestion job needs at least one item'; END IF;
  RETURN v_job;
END $function$;

CREATE OR REPLACE FUNCTION public.create_knowledge_collection(p_parent_id uuid, p_name text, p_description text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tenant uuid := auth_tenant_id(); v_id uuid;
BEGIN
  IF v_tenant IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  IF p_parent_id IS NULL THEN
    RAISE EXCEPTION 'a collection lives inside a space — use create_knowledge_space for a new top-level space';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM knowledge_collections WHERE id = p_parent_id AND tenant_id = v_tenant) THEN
    RAISE EXCEPTION 'that parent does not belong to this workspace';
  END IF;
  -- Administering the branch, not reading it (mig 359's distinction).
  IF knowledge_my_admin_level(p_parent_id) < 5 AND NOT is_platform_admin() THEN
    RAISE EXCEPTION 'insufficient_permission: organising knowledge requires knowledge manager';
  END IF;
  IF p_name IS NULL OR btrim(p_name) = '' THEN RAISE EXCEPTION 'a collection needs a name'; END IF;

  -- The 341 trigger enforces depth <= 3, no cycles and no cross-workspace parent.
  INSERT INTO knowledge_collections (tenant_id, parent_id, name, description, is_space)
  VALUES (v_tenant, p_parent_id, btrim(p_name), nullif(btrim(coalesce(p_description,'')),''), false)
  RETURNING id INTO v_id;
  RETURN v_id;
END $function$;

CREATE OR REPLACE FUNCTION public.create_knowledge_space(p_name text, p_description text DEFAULT NULL::text, p_icon text DEFAULT 'folder'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tenant uuid := auth_tenant_id(); v_id uuid;
BEGIN
  IF v_tenant IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  IF knowledge_my_admin_level(NULL) < 5 AND NOT is_platform_admin() THEN
    RAISE EXCEPTION 'insufficient_permission: creating a space requires knowledge manager';
  END IF;
  IF p_name IS NULL OR btrim(p_name) = '' THEN RAISE EXCEPTION 'a space needs a name'; END IF;

  INSERT INTO knowledge_collections (tenant_id, parent_id, name, description, is_space, icon)
  VALUES (v_tenant, NULL, btrim(p_name), nullif(btrim(coalesce(p_description,'')),''), true, p_icon)
  RETURNING id INTO v_id;

  PERFORM append_audit_event(v_tenant, 'Knowledge', 'human',
    format('Created the space "%s"', btrim(p_name)), 'access_control',
    jsonb_build_object('space_id', v_id));
  RETURN v_id;
EXCEPTION WHEN unique_violation THEN
  RAISE EXCEPTION 'a space called "%" already exists', btrim(p_name);
END $function$;

CREATE OR REPLACE FUNCTION public.create_onboarding_project(p_account_id uuid, p_version_id uuid, p_name text DEFAULT NULL::text, p_target date DEFAULT NULL::date, p_tenant_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_tenant  uuid;
  v_is_service boolean := coalesce(auth.role(), '') = 'service_role';
  v_is_active boolean;
  v_acct    customer_accounts;
  v_ver     onboarding_template_versions;
  v_state   jsonb;
  v_proj_id uuid;
  v_name    text;
  v_created_by uuid;
begin
  if v_is_service then
    if p_tenant_id is null then
      return jsonb_build_object('error', 'tenant_id_required_for_service_call');
    end if;
    v_tenant := p_tenant_id;
    v_created_by := null;
  else
    select coalesce(is_active, true) into v_is_active from profiles where user_id = auth.uid() limit 1;
    if v_is_active is false then raise exception 'account is deactivated'; end if;
    v_tenant := auth_tenant_id();
    if v_tenant is null then raise exception 'no tenant for caller'; end if;
    v_created_by := auth.uid();
  end if;

  select * into v_acct from customer_accounts where id = p_account_id and tenant_id = v_tenant;
  if not found then return jsonb_build_object('error', 'account_not_found'); end if;

  select * into v_ver from onboarding_template_versions where id = p_version_id and tenant_id = v_tenant;
  if not found then return jsonb_build_object('error', 'template_version_not_found'); end if;

  select jsonb_agg(jsonb_build_object(
    'key', i->>'key', 'status', 'pending', 'assignee', null, 'note', ''))
    into v_state
  from jsonb_array_elements(v_ver.items) i;

  v_name := coalesce(nullif(trim(p_name), ''), format('%s — %s', v_acct.name, v_ver.name));

  insert into onboarding_projects (tenant_id, account_id, template_version_id, name, target_golive, items_state, created_by)
  values (v_tenant, p_account_id, p_version_id, v_name, p_target, coalesce(v_state, '[]'::jsonb), v_created_by)
  returning id into v_proj_id;

  perform append_audit_event_internal(
    v_tenant, case when v_is_service then 'Playbook DE' else 'You' end, case when v_is_service then 'de' else 'human' end,
    format('Onboarding project created — %s (%s v%s, %s items)', v_name, v_ver.name, v_ver.version, jsonb_array_length(v_ver.items)),
    'config_change',
    jsonb_build_object('kind', 'onboarding_project_create', 'project_id', v_proj_id,
                       'account_id', p_account_id, 'version_id', p_version_id));

  insert into activity_events (tenant_id, account_id, actor, actor_type, event_type, text)
  values (v_tenant, p_account_id, case when v_is_service then 'Playbook DE' else 'You' end, case when v_is_service then 'de' else 'human' end, 'config_change',
          format('Onboarding started — %s', v_acct.name));

  return jsonb_build_object('project_id', v_proj_id);
end;
$function$;

CREATE OR REPLACE FUNCTION public.create_outbound_draft(p_tenant_id uuid, p_de_id uuid, p_recipient text, p_channel text, p_subject text, p_body text, p_reason text DEFAULT ''::text, p_source_kind text DEFAULT 'manual'::text, p_source_ref uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_draft uuid; v_task uuid; v_name text;
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'create_outbound_draft is service-role only';
  end if;
  -- Mig 547: a suspended workspace drafts nothing. email-inbound has no
  -- suspension gate of its own, so an inbound email to a dormant tenant
  -- would otherwise produce a draft AND an approval task.
  if not tenant_is_operational(p_tenant_id) then
    return null;
  end if;
  if p_body is null or length(trim(p_body)) < 10 then
    raise exception 'draft body required (min 10 chars)';
  end if;
  if not exists (select 1 from digital_employees where id = p_de_id and tenant_id = p_tenant_id) then
    raise exception 'de not in tenant';
  end if;

  insert into outbound_drafts (tenant_id, de_id, recipient_ref, channel, subject, body, reason, source_kind, source_ref)
  values (p_tenant_id, p_de_id, left(coalesce(p_recipient, ''), 200),
          case when p_channel in ('email','sms','chat','other') then p_channel else 'email' end,
          left(coalesce(p_subject, ''), 200), p_body, left(coalesce(p_reason, ''), 500),
          case when p_source_kind in ('work_item','objective','conversation','manual') then p_source_kind else 'manual' end,
          p_source_ref)
  returning id into v_draft;

  select coalesce(persona_name, name, 'DE') into v_name from digital_employees where id = p_de_id;
  insert into human_tasks (tenant_id, type, source, title, detail, related_table, related_id)
  values (p_tenant_id, 'approval_gate', 'de',
    format('Outbound draft from %s — to %s', v_name, left(coalesce(p_recipient, 'recipient'), 60)),
    format(E'%s drafted an outbound %s message and needs your approval. NOTHING sends automatically — approving means you deliver it via your own channel.\n\nTo: %s\nSubject: %s\n\n%s\n\nWhy: %s',
           v_name, case when p_channel in ('email','sms','chat','other') then p_channel else 'email' end,
           coalesce(p_recipient, '—'), coalesce(nullif(p_subject, ''), '—'), p_body, coalesce(nullif(p_reason, ''), '—')),
    'outbound_drafts', v_draft)
  returning id into v_task;

  update outbound_drafts set human_task_id = v_task, updated_at = now() where id = v_draft;
  return v_draft;
end;
$function$;

CREATE OR REPLACE FUNCTION public.create_principal_group(p_name text, p_description text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tenant uuid := auth_tenant_id(); v_id uuid;
BEGIN
  IF v_tenant IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  IF public.knowledge_my_admin_level(NULL) < 5 AND NOT is_platform_admin() THEN
    RAISE EXCEPTION 'insufficient_permission: managing groups requires knowledge manager';
  END IF;
  IF p_name IS NULL OR btrim(p_name) = '' THEN RAISE EXCEPTION 'a group needs a name'; END IF;

  INSERT INTO knowledge_principal_groups (tenant_id, name, description, created_by)
  VALUES (v_tenant, btrim(p_name), nullif(btrim(coalesce(p_description,'')), ''), auth.uid())
  RETURNING id INTO v_id;

  PERFORM append_audit_event(v_tenant, 'Knowledge', 'human',
    format('Created the group "%s"', btrim(p_name)), 'access_control',
    jsonb_build_object('group_id', v_id));
  RETURN v_id;
EXCEPTION WHEN unique_violation THEN
  RAISE EXCEPTION 'a group called "%" already exists', btrim(p_name);
END $function$;

CREATE OR REPLACE FUNCTION public.create_tenant_api_key(p_tenant_id uuid, p_name text, p_scopes text[] DEFAULT '{}'::text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_raw text;
  v_hash text;
  v_hint text;
  v_id uuid;
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;
  if not (
    is_platform_admin()
    or exists (
      select 1 from profiles p
      where p.user_id = auth.uid() and p.tenant_id = p_tenant_id
        and coalesce(p.is_active, true) = true
        and p.role in ('tenant_owner', 'tenant_admin')
    )
  ) then
    raise exception 'only workspace owners/admins can create an API key';
  end if;
  if p_name is null or length(trim(p_name)) = 0 then
    raise exception 'name is required';
  end if;

  v_raw := encode(gen_random_bytes(24), 'hex');
  v_hash := encode(digest(v_raw, 'sha256'), 'hex');
  v_hint := 'dt_live_' || repeat('•', 8) || right(v_raw, 4);

  insert into tenant_api_keys (tenant_id, name, display_hint, key_hash, scopes, created_by)
  values (p_tenant_id, trim(p_name), v_hint, v_hash, coalesce(p_scopes, '{}'), auth.uid())
  returning id into v_id;

  perform append_audit_event_internal(
    p_tenant_id, 'You', 'human',
    format('API key created: %s', trim(p_name)),
    'config_change',
    jsonb_build_object('kind', 'api_key_created', 'key_id', v_id, 'name', trim(p_name), 'scopes', p_scopes)
  );

  return jsonb_build_object('id', v_id, 'raw_key', 'dt_live_' || v_raw, 'display_hint', v_hint);
end;
$function$;

CREATE OR REPLACE FUNCTION public.create_workforce_assistant_de(p_tenant_id uuid, p_charter_override jsonb DEFAULT NULL::jsonb)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_de_id UUID;
  v_assistant_charter JSONB;
BEGIN
  IF NOT (p_tenant_id = auth_tenant_id() AND auth_has_tenant_role(array['tenant_owner', 'tenant_admin'])) THEN
    RAISE EXCEPTION 'Unauthorized: must be tenant admin';
  END IF;

  SELECT id INTO v_de_id FROM digital_employees WHERE tenant_id = p_tenant_id AND is_workforce_assistant = true;
  IF v_de_id IS NOT NULL THEN RETURN json_build_object('success', false, 'error', 'Workspace Assistant already exists'); END IF;

  v_assistant_charter := jsonb_build_object('name', 'Workspace Assistant', 'persona', 'You are a trusted advisor helping this organization hire, improve, and manage their digital workforce.', 'responsibilities', jsonb_build_array('Help hire new DEs', 'Suggest improvements to underperforming DEs', 'Monitor team performance', 'Help retire DEs', 'Train new tenants on DreamTeamAI features'), 'guardrails', jsonb_build_array('Never auto-approve DE changes without explicit user consent', 'Always show evidence for recommendations', 'Prioritize user success', 'Escalate ambiguous decisions'));
  v_assistant_charter := COALESCE(v_assistant_charter || p_charter_override, v_assistant_charter);

  INSERT INTO digital_employees (tenant_id, name, status, charter, is_workforce_assistant, is_product_expert, created_by) VALUES (p_tenant_id, 'Workspace Assistant', 'active', v_assistant_charter, true, true, auth.uid()) RETURNING id INTO v_de_id;
  INSERT INTO de_deployment_stages (de_id, stage) VALUES (v_de_id, 'live');

  RETURN json_build_object('success', true, 'de_id', v_de_id, 'message', 'Workspace Assistant provisioned successfully', 'charter', v_assistant_charter);
END;
$function$;

CREATE OR REPLACE FUNCTION public.de_blocker_signature(p_text text)
 RETURNS text[]
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
declare
  s   text;
  acc text[] := '{}';
  r   record;
begin
  s := lower(btrim(regexp_replace(coalesce(p_text, ''), '\s+', ' ', 'g')));
  if s = '' then
    return '{}'::text[];
  end if;

  for r in
    select * from (values
      ('blocked_input',
       '(no source( is)? connected|not connected|cannot( be)? read|can ?not be read|cannot access|inaccessible|not readable|unable to (access|read|open)|no access|access issue|permission denied|not authori[sz]ed|truncat|incomplete|partial(ly)? |cuts? off|only [0-9]+ [a-z ]{0,20}(of|entries|rows|items)|[0-9]+ of [0-9]+ (entries|rows|items)|missing|not provided|full [a-z ]{0,20}required|no data|empty)'),
      ('inconsistent',
       '(does not balance|do not balance|out of balance|imbalance|discrepan|mismatch|variance|shortfall|does not match|do not match|exceed debits|credits exceed|conflict|inconsisten|disagree)'),
      ('out_of_range',
       '(future[- ]dated|forward[- ]dated|dated in [0-9]{4}|dated [0-9]{4}|out of period|period mismatch|date anomaly|period allocation|future dates|exceeds? the [a-z ]{0,20}threshold|above the limit|over the limit|outside the)'),
      ('overdue',
       '(overdue|past due|days? past|aged[- ]receivable|final[- ]notice|collections referral|breached the sla|sla breach)'),
      ('missing_owner',
       '(no (executive )?sponsor|no day[- ]to[- ]day contact|no contact|contact[^.]{0,40}not recorded|no owner|owner is not|unassigned|nobody is)')
    ) as t(k, re)
  loop
    if s ~ r.re then
      acc := array_append(acc, r.k);
    end if;
  end loop;

  return (select coalesce(array_agg(distinct u order by u), '{}'::text[]) from unnest(acc) as u);
end;
$function$;

CREATE OR REPLACE FUNCTION public.de_certification_status(p_de_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tenant uuid;
  v_current text;
  v_fresh boolean;
  v_has_pass boolean;
  v_disp role_certifications;   -- the cert to DISPLAY (prefer a fresh one)
  v_any  role_certifications;
begin
  select tenant_id into v_tenant from digital_employees where id = p_de_id;
  if v_tenant is null then return jsonb_build_object('state', 'unknown'); end if;
  -- Prefix `auth.uid() is not null and` deleted. Browser-only caller
  -- (src/lib/deWorkbenchApi.ts:308); no service-role path exists.
  if not exists (
      select 1 from profiles p where p.user_id = auth.uid()
      and (p.layer = 'platform' or p.tenant_id = v_tenant)) then
    raise exception 'not authorized';
  end if;
  if not public.can_access_de(p_de_id) then
    return jsonb_build_object('state', 'unknown');
  end if;

  v_current := public.de_config_fingerprint(p_de_id);

  -- Freshness is decided the SAME way the go-live gate decides it: does ANY
  -- passing cert match the current config fingerprint? (Not "is the newest
  -- passing cert fresh" — two passing certs can share a timestamp.)
  v_fresh := exists (
    select 1 from role_certifications
     where de_id = p_de_id and status = 'passed'
       and config_fingerprint is not distinct from v_current);
  v_has_pass := exists (
    select 1 from role_certifications where de_id = p_de_id and status = 'passed');

  -- Display cert: the matching fresh one if present, else the newest passing.
  select * into v_disp from role_certifications
    where de_id = p_de_id and status = 'passed'
    order by (config_fingerprint is not distinct from v_current) desc,
             evaluated_at desc nulls last, created_at desc limit 1;
  select * into v_any from role_certifications
    where de_id = p_de_id
    order by evaluated_at desc nulls last, created_at desc limit 1;

  return jsonb_build_object(
    'state', case
      when not v_has_pass and v_any.id is null then 'uncertified'
      when not v_has_pass then 'failed'
      when v_fresh then 'certified'
      else 'stale'
    end,
    'fresh', v_fresh,
    'latest_passed', case when v_disp.id is null then null else jsonb_build_object(
      'id', v_disp.id, 'score_pct', v_disp.score_pct, 'threshold_pct', v_disp.threshold_pct,
      'evaluated_at', v_disp.evaluated_at, 'archetype_key', v_disp.archetype_key,
      'certified_fingerprint', v_disp.config_fingerprint) end,
    'current_fingerprint', v_current,
    'latest_status', v_any.status
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.de_config_fingerprint(p_de_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_de digital_employees;
begin
  select * into v_de from digital_employees where id = p_de_id;
  if v_de.id is null then return null; end if;
  return public.de_config_fingerprint_row(v_de);
end;
$function$;

CREATE OR REPLACE FUNCTION public.de_development_items_attempts_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.attempts is distinct from old.attempts
     and coalesce(auth.role(), '') = 'authenticated' then
    raise exception 'attempts is a machine-written log and cannot be edited from the app';
  end if;
  return new;
end $function$;

CREATE OR REPLACE FUNCTION public.de_escalation_headline(p_text text, p_limit integer DEFAULT 120)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
declare
  s    text;
  sent text;
  head text;
  cut  text;
  lim  integer := greatest(24, least(coalesce(p_limit, 120), 300));
begin
  s := btrim(regexp_replace(coalesce(p_text, ''), '\s+', ' ', 'g'));
  if s = '' then
    return null;                    -- nothing to derive from; the caller decides
  end if;

  -- (a) a COMPLETE first sentence, if one ends inside the budget.
  --     >= 3 alphanumerics before the terminator rejects "vs." / "e.g." / "No.";
  --     the trailing-whitespace requirement rejects every decimal point.
  sent := (regexp_match(s, '^(.{20,}?[[:alnum:]]{3}[])"'']?)[.!?](\s|$)'))[1];
  if sent is not null and char_length(sent) <= lim then
    return sent;
  end if;

  -- (b) otherwise cut on a SPACE. Never on punctuation — that is what put
  --     "debits PKR 322k vs" and "exceed the $10,000" in front of a human.
  if char_length(s) <= lim then
    return s;
  end if;
  head := left(s, lim);
  cut  := regexp_replace(head, '\s+\S*$', '');                 -- partial word off
  if btrim(cut) = '' then
    cut := head;                                               -- one word > lim
  end if;
  cut := regexp_replace(cut, '\s*\((\d{1,2}|[a-z])\)$', '');   -- no dangling "(2)"
  cut := regexp_replace(cut, '[[:space:],;:./&(…–—-]+$', '');  -- no dangling joiner
  if btrim(cut) = '' then
    return null;
  end if;
  return cut || '…';
end;
$function$;

CREATE OR REPLACE FUNCTION public.de_escalation_scope(p_tenant_id uuid, p_objective_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
declare
  v text;
begin
  if p_objective_id is null then
    return null;
  end if;
  select nullif(btrim(lower(regexp_replace(coalesce(o.title, ''), '\s+', ' ', 'g'))), '')
    into v
    from de_objectives o
   where o.id = p_objective_id
     and (p_tenant_id is null or o.tenant_id = p_tenant_id);
  return coalesce(left(v, 200), 'objective:' || p_objective_id::text);
end;
$function$;

CREATE OR REPLACE FUNCTION public.de_escalation_title(p_tenant_id uuid, p_title text, p_reason text, p_de_name text, p_work_item_id uuid DEFAULT NULL::uuid, p_objective_id uuid DEFAULT NULL::uuid, p_entity text DEFAULT NULL::text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
declare
  v_title  text;
  v_named  text;
  v_entity text;
begin
  -- (1) what the caller said, if it said anything.
  v_title := nullif(btrim(coalesce(p_title, '')), '');
  if v_title is not null then
    return v_title;
  end if;

  v_entity := nullif(btrim(regexp_replace(coalesce(p_entity, ''), '\s+', ' ', 'g')), '');

  -- (2) what the EMPLOYEE said. This is the rung that matters: p_reason is
  --     the employee's own account and is present on every live call. The
  --     entity, when there is one, is kept in front of it — literally, with
  --     no "the headline already mentions it, so drop the prefix" shortcut,
  --     because that shortcut is how the NAME gets lost.
  v_title := public.de_escalation_headline(p_reason, 120);
  if v_title is not null then
    return case when v_entity is null then v_title else v_entity || ' — ' || v_title end;
  end if;

  -- (3) no reason at all. Name the work it stopped on — the row points at it.
  if p_work_item_id is not null then
    select nullif(btrim(w.title), '') into v_named
      from de_work_items w
     where w.id = p_work_item_id
       and (p_tenant_id is null or w.tenant_id = p_tenant_id);
    if v_named is not null then
      return case when v_entity is null then 'Stopped on: ' || v_named
                  else v_entity || ' — stopped on: ' || v_named end;
    end if;
  end if;
  if p_objective_id is not null then
    select nullif(btrim(o.title), '') into v_named
      from de_objectives o
     where o.id = p_objective_id
       and (p_tenant_id is null or o.tenant_id = p_tenant_id);
    if v_named is not null then
      return case when v_entity is null then 'Stopped on: ' || v_named
                  else v_entity || ' — stopped on: ' || v_named end;
    end if;
  end if;

  -- (3b) nothing to say about the problem, but we do know WHO it is about.
  --      The name alone beats a sentence that is true of every row.
  if v_entity is not null then
    return v_entity;
  end if;

  -- (4) THE GENUINE LAST RESORT: it knows nothing. Say that, rather than the
  --     old sentence, which said only that a decision was wanted — true of
  --     every row in the queue and therefore information in none of them.
  return coalesce(nullif(btrim(coalesce(p_de_name, '')), ''), 'An employee')
         || ' stopped and gave no reason';
end;
$function$;

CREATE OR REPLACE FUNCTION public.de_eval_quality(p_tenant_id uuid, p_de_id uuid, p_days integer DEFAULT 7)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with prod as (
    -- mig 706: count only what is PROVABLY production — the judgment links to
    -- a message that still exists, in a conversation not filed under the exam
    -- channel. Judgments whose source rows are gone (80 live rows, hq) cannot
    -- prove what they graded and are excluded at read time; they are not
    -- deleted or rewritten — they are history.
    select j.score, j.verdict
    from eval_judgments j
    join de_messages m on m.id = j.message_id
    join de_conversations c on c.id = m.conversation_id
    where j.tenant_id = p_tenant_id and j.de_id = p_de_id
      and j.source = 'online'
      and c.channel is distinct from 'exam'
      and j.created_at >= now() - make_interval(days => greatest(1, p_days))
  )
  select jsonb_build_object(
    'n', count(*),
    'avg_score', coalesce(round(avg(score)), 0),
    'pass_rate', coalesce(round(100.0 * count(*) filter (where verdict = 'pass') / nullif(count(*), 0)), 0),
    'fail_rate', coalesce(round(100.0 * count(*) filter (where verdict = 'fail') / nullif(count(*), 0)), 0),
    'headline_basis', 'production_online_only',
    'by_source', coalesce((select jsonb_object_agg(source, c) from
       (select source, count(*) c from eval_judgments
        where tenant_id = p_tenant_id and de_id = p_de_id
          and created_at >= now() - make_interval(days => greatest(1, p_days)) group by source) s), '{}'::jsonb)
  )
  from prod;
$function$;

CREATE OR REPLACE FUNCTION public.de_governance_sweep_internal()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_cert record;
  v_pip record;
  v_inc record;
  m record;
  v_warned integer := 0;
  v_expired integer := 0;
  v_pip_completed integer := 0;
  v_pip_failed integer := 0;
  v_sla integer := 0;
  v_de_name text;
  v_prop jsonb;
  v_goals integer; v_measured integer; v_unmet integer; v_decisions bigint;
  v_pip_dismissed integer := 0;
  v_pip_unassessable integer := 0;
begin
  -- (a) Expiring within 14 days → one warning audit event per cert.
  for v_cert in
    select c.*, de.name as de_name from de_certifications c
    join digital_employees de on de.id = c.de_id
    where c.status = 'active' and c.warned_at is null
      and c.expires_at <= now() + interval '14 days' and c.expires_at > now()
      and tenant_is_operational(c.tenant_id)
  loop
    update de_certifications set warned_at = now() where id = v_cert.id;
    perform append_audit_event_internal(
      v_cert.tenant_id, 'Governance sweep', 'system',
      format('%s''s %s certification expires %s — recertify to keep it current', v_cert.de_name, v_cert.cert_type, to_char(v_cert.expires_at, 'YYYY-MM-DD')),
      'config_change',
      jsonb_build_object('kind', 'certification_expiring', 'cert_id', v_cert.id, 'de_id', v_cert.de_id)
    );
    v_warned := v_warned + 1;
  end loop;

  -- (b) Expired → status flip + incident (dedup via unique source key).
  for v_cert in
    select c.*, de.name as de_name from de_certifications c
    join digital_employees de on de.id = c.de_id
    where c.status = 'active' and c.expires_at <= now()
      and tenant_is_operational(c.tenant_id)
  loop
    update de_certifications set status = 'expired' where id = v_cert.id;
    insert into de_incidents (tenant_id, de_id, kind, severity, title, detail, source_table, source_id, occurred_at)
    values (v_cert.tenant_id, v_cert.de_id, 'certification_expired', 'warning',
      format('%s certification expired — %s', initcap(v_cert.cert_type), v_cert.de_name),
      jsonb_build_object('cert_id', v_cert.id, 'cert_type', v_cert.cert_type, 'scope', v_cert.scope,
                         'issued_by', v_cert.issued_by_name, 'expired_at', v_cert.expires_at),
      'de_certifications', v_cert.id, v_cert.expires_at)
    on conflict (tenant_id, source_table, source_id) do nothing;
    v_expired := v_expired + 1;
  end loop;

  -- (c) Overdue open PIPs → RE-MEASURE on a fresh 4-week window: now
  --     passing → completed (closed loop); still failing → 'failed' +
  --     CRITICAL incident for human trust review.
  for v_pip in
    select i.* from de_development_items i
    where i.item_type = 'pip' and i.source = 'detected'
      and i.status in ('proposed', 'in_progress') and i.due_date < current_date
      and tenant_is_operational(i.tenant_id)
  loop
    select name into v_de_name from digital_employees where id = v_pip.de_id;

    -- ⛔ ONE POLICY, TWO READERS.
    --
    -- This block used to re-measure against three constants:
    --   total_decisions >= 10 and escalation_rate <= 50
    --   and avg_confidence >= 50 and error_rate <= 15
    -- Mig 765 removed exactly those from the review as illegitimate -- "judging
    -- everyone against three invented constants" -- and replaced them with the
    -- goals the workspace actually set. They lived on HERE, so the two readers
    -- of one policy disagreed: the review would decline to judge an employee
    -- while this sweep failed it and raised a CRITICAL incident.
    --
    -- Worse, `v_passing` was initialised false and only ever set INSIDE a loop
    -- over get_de_performance_metrics. An employee that function returned no
    -- row for fell straight to the else branch: absence of evidence became
    -- FAILURE, plus a critical incident. That is the same polarity error mig
    -- 786 closed on the authority side -- "we could not tell" must never be
    -- spelled the same way as a verdict.
    --
    -- Same reader as the review now: de_kpi_status_internal, over the same
    -- fresh 4-week window this sweep has always used.
    select count(*),
           count(*) filter (where k.current is not null),
           count(*) filter (where k.current is not null and coalesce(k.met, false) = false)
      into v_goals, v_measured, v_unmet
      from de_kpi_status_internal(v_pip.tenant_id, v_pip.de_id, 4) k;

    v_decisions := 0;
    select coalesce(mm.total_decisions, 0) into v_decisions
      from get_de_performance_metrics(v_pip.tenant_id, 4) mm
     where mm.de_id = v_pip.de_id;

    if v_goals = 0 then
      -- No goals means no verdict (founder decision, 2026-08-18). A plan on an
      -- employee with nothing to be judged against can NEVER be adjudicated by
      -- either reader, so leaving it open is not caution -- it is a permanent
      -- open threat carrying a consequence clause that promises a critical
      -- incident. Withdraw it, and say so. `dismissed` rather than completed
      -- or failed: it neither passed nor failed, it was never judgeable.
      update de_development_items set status = 'dismissed', updated_at = now()
       where id = v_pip.id;
      perform append_audit_event_internal(
        v_pip.tenant_id, 'Governance sweep', 'system',
        format('%s has no goals set, so its Performance Improvement Plan could not be judged and has been withdrawn. Set goals and a future review can open one that means something.',
               coalesce(v_de_name, 'Employee')),
        'config_change',
        jsonb_build_object('kind', 'pip_dismissed', 'item_id', v_pip.id, 'de_id', v_pip.de_id,
                           'why', 'no goals set for this employee')
      );
      v_pip_dismissed := v_pip_dismissed + 1;

    elsif v_decisions < 10 or v_measured = 0 then
      -- ⚠ NOT A FAILURE. Goals exist but there is not yet enough to judge them
      -- on. The thin-evidence guard mig 765 deliberately KEPT, applied here for
      -- the first time. The plan stays open and its deadline stays where it is;
      -- next sweep may well have the evidence. What must not happen is a
      -- critical incident for the crime of being unmeasured.
      v_pip_unassessable := v_pip_unassessable + 1;

    elsif v_unmet = 0 then
      update de_development_items set status = 'completed', completed_at = now(), updated_at = now() where id = v_pip.id;
      perform append_audit_event_internal(
        v_pip.tenant_id, 'Governance sweep', 'system',
        format('%s met its Performance Improvement Plan targets — PIP closed', coalesce(v_de_name, 'Employee')),
        'config_change',
        jsonb_build_object('kind', 'pip_completed', 'item_id', v_pip.id, 'de_id', v_pip.de_id,
                           'goals_measured', v_measured)
      );
      v_pip_completed := v_pip_completed + 1;

    else
      -- Measured, and missed. This is the consequence the plan itself promises.
      update de_development_items set status = 'failed', updated_at = now() where id = v_pip.id;
      insert into de_incidents (tenant_id, de_id, kind, severity, title, detail, source_table, source_id, occurred_at)
      values (v_pip.tenant_id, v_pip.de_id, 'pip_failed', 'critical',
        format('Performance Improvement Plan failed — %s', coalesce(v_de_name, 'employee')),
        jsonb_build_object('item_id', v_pip.id, 'due_date', v_pip.due_date,
          'consequence', v_pip.consequence,
          'goals_missed', v_unmet, 'goals_measured', v_measured,
          'next_step', 'A human decides here: trust reduction, added approval gates, or pause (Pause is on the employee profile).'),
        'de_development_items', v_pip.id, now())
      on conflict (tenant_id, source_table, source_id) do nothing;
      v_pip_failed := v_pip_failed + 1;
    end if;
  end loop;

  -- (d) §10.3: critical incidents should be reviewed within 48 hours —
  --     one nudge each (detail flag dedup).
  for v_inc in
    select * from de_incidents
    where status = 'open' and severity = 'critical'
      and created_at < now() - interval '48 hours'
      and coalesce(detail->>'sla_nudged', '') = ''
      and tenant_is_operational(tenant_id)
  loop
    update de_incidents set detail = detail || '{"sla_nudged": true}'::jsonb where id = v_inc.id;
    perform append_audit_event_internal(
      v_inc.tenant_id, 'Governance sweep', 'system',
      format('Critical incident open past the 48-hour review window: %s', left(v_inc.title, 160)),
      'config_change',
      jsonb_build_object('kind', 'incident_sla_nudge', 'incident_id', v_inc.id, 'de_id', v_inc.de_id)
    );
    v_sla := v_sla + 1;
  end loop;

  -- (e) mig 710: repeated identical human approvals become a trust-widening
  --     PROPOSAL (never a decision — a human still approves it, through
  --     decide_human_task, like every other task). SECURITY DEFINER
  --     dispatch: the callee is owned by trust_pattern_proposer, so this
  --     step runs with that role's privileges, which cannot decide or move
  --     a dial. Errors are captured, not swallowed silently — they ride in
  --     the return payload; a proposer failure must not cost steps (a)-(d).
  begin
    v_prop := public.raise_trust_widening_proposals(null);
  exception when others then
    v_prop := jsonb_build_object('error', sqlerrm);
  end;

  return jsonb_build_object('cert_warnings', v_warned, 'certs_expired', v_expired,
    'pips_completed', v_pip_completed, 'pips_failed', v_pip_failed,
    'pips_dismissed', v_pip_dismissed, 'pips_unassessable', v_pip_unassessable,
    'sla_nudges', v_sla,
    'trust_proposals', coalesce(v_prop, '{}'::jsonb));
end;
$function$;

CREATE OR REPLACE FUNCTION public.de_improvements_entity_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_text text;
  v_hits int;
  v_outcome text;
  v_match_name text;
  v_match_kind text;
  r record;
begin
  begin
    -- (1) outcome_kind, from data the organ already recorded.
    v_outcome := 'wrong_answer';
    if new.gap_cluster_id is not null then
      select coalesce((er.confidence_inputs->>'knowledge_hits')::int, 0) into v_hits
      from knowledge_gap_clusters g
      join evidence_runs er on er.id = g.representative_run_id
      where g.id = new.gap_cluster_id;
      if v_hits is not null and v_hits = 0 then
        v_outcome := 'kb_missing';
      end if;
    end if;

    -- (2) entity match: live workspace entities named by the proposal text.
    v_text := coalesce(new.proposed_title, '') || ' ' || coalesce(new.proposed_content, '');
    for r in
      select * from (
        select coalesce(nullif(d.persona_name, ''), d.name) as display,
               t.term, 'digital_employee'::text as kind
        from digital_employees d
        cross join lateral (values
          (d.name),
          (nullif(d.persona_name, '')),
          (nullif(regexp_replace(d.name, '\s+(DE|Specialist)\s*$', '', 'i'), d.name))
        ) as t(term)
        where d.tenant_id = new.tenant_id and d.status = 'active'
        union all
        select coalesce(nullif(c.display_name, ''), c.provider) as display,
               t.term, 'connector'::text as kind
        from connectors c
        cross join lateral (values (nullif(c.display_name, '')), (c.provider)) as t(term)
        where c.tenant_id = new.tenant_id
      ) cand
      where cand.term is not null and length(btrim(cand.term)) >= 3
      order by length(cand.term) desc
    loop
      if v_text ~* ('\m' || regexp_replace(btrim(r.term), '([.\\+*?\[\]\^\$(){}=!<>|:#&-])', '\\\1', 'g') || '\M') then
        v_match_name := r.display;
        v_match_kind := r.kind;
        exit;
      end if;
    end loop;

    new.detail := coalesce(new.detail, '{}'::jsonb)
      || jsonb_build_object('outcome_kind', v_outcome)
      || case when v_match_name is not null
              then jsonb_build_object(
                     'entity_match', jsonb_build_object('name', v_match_name, 'kind', v_match_kind),
                     'possible_kb_gap', true)
              else '{}'::jsonb end;
  exception when others then
    -- Tagging is advisory — it must never abort proposal creation.
    raise warning 'de_improvements_entity_guard tagging skipped for %: %', new.id, sqlerrm;
  end;
  return new;
end $function$;

CREATE OR REPLACE FUNCTION public.de_is_available(p_availability jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
declare
  v_now timestamp;
  v_dow integer;
  v_hour integer;
begin
  if coalesce(p_availability->>'mode', 'always_on') <> 'business_hours' then
    return true;
  end if;
  begin
    v_now := now() at time zone coalesce(p_availability->>'timezone', 'UTC');
  exception when others then
    return true;  -- fail-open: bad timezone never stops an inbox
  end;
  v_dow := extract(isodow from v_now);
  v_hour := extract(hour from v_now);
  return exists (
      select 1 from jsonb_array_elements_text(coalesce(p_availability->'days', '[1,2,3,4,5]'::jsonb)) d
      where d::integer = v_dow)
    and v_hour >= coalesce((p_availability->>'start_hour')::integer, 9)
    and v_hour < coalesce((p_availability->>'end_hour')::integer, 17);
exception when others then
  return true;  -- fail-open on any malformed shape
end;
$function$;

CREATE OR REPLACE FUNCTION public.de_kpi_action_value(p_tenant_id uuid, p_de_id uuid, p_source text, p_source_config jsonb, p_window_weeks integer DEFAULT 13)
 RETURNS TABLE(v numeric, n bigint)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select
    -- ⚠ mig 501's guard. A non-'action' metric MUST come back NULL, never 0.
    case when coalesce(p_source, '') = 'action' then
      case when coalesce(p_source_config->>'agg', 'count') = 'auto_rate'
           then round(100.0 * count(*) filter (where ae.decision = 'auto_executed') / nullif(count(*), 0), 1)
           else count(*)::numeric end
    end                                            as v,
    count(*)                                       as n
    from action_executions ae
    left join action_definitions ad on ad.id = ae.action_definition_id
   where p_source = 'action'
     and ae.tenant_id = p_tenant_id
     and ae.subject_kind = 'de'
     and ae.subject_id = p_de_id
     and ae.rollback_of is null
     and ae.created_at >= now() - (p_window_weeks * interval '7 days')
     and (coalesce(p_source_config->>'category', '')     = '' or ad.category = p_source_config->>'category')
     and (coalesce(p_source_config->>'action_label', '') = '' or ad.label    = p_source_config->>'action_label')
$function$;

CREATE OR REPLACE FUNCTION public.de_kpi_status_internal(p_tenant_id uuid, p_de_id uuid, p_window_weeks integer DEFAULT 13)
 RETURNS TABLE(kpi_id uuid, name text, metric_key text, target numeric, direction text, current numeric, met boolean, sample bigint)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$

declare
  -- ⛔ mig 766: `p_tenant_id uuid;` WAS DECLARED HERE, shadowing the
  -- parameter of the same name. Mig 764 generated this body by replacing
  -- v_tenant -> p_tenant_id across the whole text, including the DECLARE
  -- block, so the function computed every tenant-scoped lookup against a
  -- NULL local instead of its argument. Removed.
  m record; v_csat numeric; v_csat_n bigint; v_vals jsonb; v_samples jsonb;
begin
  -- A tenant id passed as a PARAMETER is not authorisation, it is an assertion
  -- to be checked. Callers are trusted routines today; that is a property of
  -- today's callers, not of this function.
  if not exists (select 1 from digital_employees d
                  where d.id = p_de_id and d.tenant_id = p_tenant_id) then
    return;
  end if;


  select * into m from get_de_performance_metrics(p_tenant_id, p_window_weeks) where de_id = p_de_id;
  select round(100.0 * count(*) filter (where csat_score = 1) / nullif(count(*) filter (where csat_submitted_at is not null), 0), 1),
         count(*) filter (where csat_submitted_at is not null)
    into v_csat, v_csat_n
  from de_conversations where tenant_id = p_tenant_id and de_id = p_de_id
     -- ⚠ THE WINDOW THIS FUNCTION IS ASKED FOR. It had NO time filter at
     -- all, so csat_pct was an all-time figure sitting in a payload whose
     -- every other number honoured p_window_weeks, and a review calling
     -- itself "13 weeks" published it as such.
     --
     -- Restricting here also restricts the NUMERATOR, which previously
     -- counted csat_score = 1 rows whose csat_submitted_at was null while
     -- the denominator did not — a ratio that could exceed 100%. Naming it
     -- rather than leaving it: there is no way to window this read without
     -- touching that, and leaving it while editing this very expression
     -- would be the worse choice.
     and csat_submitted_at >= now() - (p_window_weeks * interval '7 days');

  v_vals := jsonb_strip_nulls(jsonb_build_object(
    'resolution_rate',        case when coalesce(m.total_decisions, 0) >= 1 then m.resolution_rate end,
    'avg_confidence',         case when coalesce(m.total_decisions, 0) >= 1 then m.avg_confidence end,
    'escalation_rate',        case when coalesce(m.total_decisions, 0) >= 1 then m.escalation_rate end,
    'error_rate',             case when coalesce(m.total_runs, 0) >= 1 then m.error_rate end,
    'csat_pct',               v_csat,
    'high_frustration_count', case when coalesce(m.total_decisions, 0) >= 1 then m.high_frustration_count::numeric end,
    'total_decisions',        coalesce(m.total_decisions, 0)::numeric
  ));
  v_samples := jsonb_build_object('csat_pct', v_csat_n);

  return query
  select k.id, k.name, k.metric_key, k.target, k.direction, cur.v,
         case when cur.v is null then null
              when k.direction = 'higher' then cur.v >= k.target
              else cur.v <= k.target end,
         cur.n
  -- ⛔ mig 766. This read `from de_kpis k` with NO restriction at all — not
  -- by employee, not by workspace — so it returned EVERY goal in the database
  -- whatever it was asked about. Scoped here at the source, as a subquery, so
  -- no later join can widen it back.
  from (select * from de_kpis
         where de_id = p_de_id and tenant_id = p_tenant_id) k
  left join kpi_metric_catalog c
    on c.metric_key = k.metric_key and (c.tenant_id is null or c.tenant_id = p_tenant_id)
  -- mig 757: the arm lives in ONE place now (mig 756). Same expression,
  -- proven identical over 1143 (metric x employee) pairs before the switch.
  left join lateral public.de_kpi_action_value(p_tenant_id, p_de_id, c.source, c.source_config, p_window_weeks) act on true
  -- Latest manual reading, for metrics the platform doesn't compute.
  left join lateral (
    select d.value, count(*) over () as rn from de_kpi_readings d
     where d.de_id = k.de_id and d.metric_key = k.metric_key
       and d.source = 'manual'                    -- GI-5: fallback = human readings only
     order by d.as_of desc, d.created_at desc limit 1
  ) r on true
  cross join lateral (
    select coalesce((v_vals->>k.metric_key)::numeric, act.v, r.value) as v,
           coalesce((v_samples->>k.metric_key)::bigint, nullif(act.n, 0), r.rn, coalesce(m.total_decisions, 0)) as n
  ) cur;
end $function$;

CREATE OR REPLACE FUNCTION public.de_may_use_action(p_tenant_id uuid, p_de_id uuid, p_action_definition_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce(
    case
      when ad.requires_role is null then true
      when ad.requires_role = 'workforce_assistant'
        then coalesce(de.is_workforce_assistant, false)
      -- mig 669: the money desk. Reaching a CUSTOMER about their unpaid
      -- invoice is a finance act, not something every employee holding the
      -- ERP connector should be able to do.
      when ad.requires_role = 'finance'
        then coalesce(de.archetype_key, '') in ('billing_ar', 'accounting', 'fpa')
      -- Mig 797: the sales desk. Quoting a price and taking an order are
      -- commercial acts — the roles that face the customer commercially,
      -- not everyone holding the ERP connector.
      when ad.requires_role = 'sales_desk'
        then coalesce(de.archetype_key, '') in ('bdr', 'sdr', 'front_desk', 'billing_ar')
      -- No permissive else. An unrecognised requirement DENIES.
      else false
    end, false)
    from action_definitions ad
    left join digital_employees de
      on de.id = p_de_id and de.tenant_id = p_tenant_id
   where ad.id = p_action_definition_id;
$function$;

CREATE OR REPLACE FUNCTION public.de_memory_search(p_tenant_id uuid, p_de_id uuid, p_query_embedding vector DEFAULT NULL::vector, p_subject_kind text DEFAULT NULL::text, p_subject_ref text DEFAULT NULL::text, p_kinds text[] DEFAULT NULL::text[], p_match_count integer DEFAULT 8)
 RETURNS TABLE(id uuid, content text, kind text, subject_kind text, subject_ref text, salience numeric, distance double precision, created_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is null then
    raise exception 'not authenticated: reading DE memory for a workspace named in a parameter is not an anonymous operation';
  end if;
  if not exists (select 1 from profiles p where p.user_id = auth.uid()
                   and (p.tenant_id = p_tenant_id or p.layer = 'platform')) then
    raise exception 'not authorized to read memory for this tenant';
  end if;
  return query select * from public.de_memory_search_internal(
    p_tenant_id, p_de_id, p_query_embedding, p_subject_kind, p_subject_ref,
    p_kinds, p_match_count);
end;
$function$;

CREATE OR REPLACE FUNCTION public.de_memory_search_internal(p_tenant_id uuid, p_de_id uuid, p_query_embedding vector DEFAULT NULL::vector, p_subject_kind text DEFAULT NULL::text, p_subject_ref text DEFAULT NULL::text, p_kinds text[] DEFAULT NULL::text[], p_match_count integer DEFAULT 8)
 RETURNS TABLE(id uuid, content text, kind text, subject_kind text, subject_ref text, salience numeric, distance double precision, created_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  -- NO USER CHECK. Four edge functions recall DE memory with the service-role
  -- admin client. EXECUTE is service_role only.
  return query
  select m.id, m.content, m.kind, m.subject_kind, m.subject_ref, m.salience,
         case when p_query_embedding is not null and m.embedding is not null
              then (m.embedding <=> p_query_embedding)::float else null end as distance,
         m.created_at
  from de_memory m
  where m.tenant_id = p_tenant_id
    and m.de_id = p_de_id
    and (m.expires_at is null or m.expires_at > now())
    and (p_subject_kind is null or m.subject_kind = p_subject_kind)
    and (p_subject_ref  is null or m.subject_ref  = p_subject_ref)
    and (p_kinds is null or m.kind = any(p_kinds))
  order by
    -- lower is better: semantic distance when available, else a recency+
    -- salience proxy (newer & more salient sort first).
    coalesce(case when p_query_embedding is not null and m.embedding is not null
                  then (m.embedding <=> p_query_embedding)::float end,
             1.0 - m.salience
               + least(0.5, extract(epoch from (now() - m.created_at)) / (86400.0 * 60)))
    asc
  limit greatest(1, least(50, p_match_count));
end;
$function$;

CREATE OR REPLACE FUNCTION public.de_memory_write(p_tenant_id uuid, p_de_id uuid, p_content text, p_embedding vector DEFAULT NULL::vector, p_subject_kind text DEFAULT 'general'::text, p_subject_ref text DEFAULT NULL::text, p_kind text DEFAULT 'episodic'::text, p_salience numeric DEFAULT 0.5, p_source text DEFAULT 'de'::text, p_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  -- The body's old comment said the identity test was deliberate — "auth.uid()
  -- is null under service_role, so the membership check is skipped for it".
  -- That is a true description of a fail-open guard, written as if it were a
  -- design. The service path now has its own function; this name refuses.
  if auth.uid() is null then
    raise exception 'not authenticated: writing DE memory for a workspace named in a parameter is not an anonymous operation';
  end if;
  if not exists (select 1 from profiles p where p.user_id = auth.uid()
                   and (p.tenant_id = p_tenant_id or p.layer = 'platform')) then
    raise exception 'not authorized to write memory for this tenant';
  end if;
  return public.de_memory_write_internal(p_tenant_id, p_de_id, p_content, p_embedding,
                                         p_subject_kind, p_subject_ref, p_kind,
                                         p_salience, p_source, p_expires_at);
end;
$function$;

CREATE OR REPLACE FUNCTION public.de_memory_write_internal(p_tenant_id uuid, p_de_id uuid, p_content text, p_embedding vector DEFAULT NULL::vector, p_subject_kind text DEFAULT 'general'::text, p_subject_ref text DEFAULT NULL::text, p_kind text DEFAULT 'episodic'::text, p_salience numeric DEFAULT 0.5, p_source text DEFAULT 'de'::text, p_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_id uuid;
begin
  -- NO USER CHECK, ON PURPOSE. Five edge functions write DE memory with the
  -- service-role admin client and have no signed-in person to check.
  -- EXECUTE is service_role only.
  if p_content is null or btrim(p_content) = '' then
    raise exception 'memory content required';
  end if;

  insert into de_memory (tenant_id, de_id, subject_kind, subject_ref, kind,
                         content, embedding, salience, source, expires_at)
  values (p_tenant_id, p_de_id, p_subject_kind, p_subject_ref, p_kind,
          p_content, p_embedding, greatest(0, least(1, coalesce(p_salience, 0.5))),
          p_source, p_expires_at)
  returning id into v_id;
  return v_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.de_records_gate(p_tenant_id uuid, p_de_id uuid)
 RETURNS TABLE(gated boolean, reasons text[])
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_reasons text[] := '{}';
  v_cert record;
  v_fp text;
  v_n bigint;       -- GI-4: this DE's 56d evidence-run volume
  v_failed bigint;  -- GI-4: this DE's 56d failed-run count
  v_req boolean;        -- GI-9: tenant opted into mandatory cert?
  v_req_since timestamptz;
  v_de_created timestamptz;
  v_arch text;
  v_has_exam boolean;
  v_has_pass boolean;
begin
  -- (a) Exam certifications (role_certifications): latest row decides.
  select rc.status, rc.config_fingerprint into v_cert
    from role_certifications rc
   where rc.tenant_id = p_tenant_id and rc.de_id = p_de_id
   order by rc.evaluated_at desc nulls last, rc.created_at desc limit 1;
  if found then
    if v_cert.status = 'failed' then
      v_reasons := array_append(v_reasons, 'failed_certification');
    elsif v_cert.status = 'passed' and v_cert.config_fingerprint is not null then
      v_fp := public.de_config_fingerprint(p_de_id);
      if v_fp is not null and v_fp <> v_cert.config_fingerprint then
        v_reasons := array_append(v_reasons, 'stale_certification');
      end if;
    end if;
  end if;

  -- (b) Governance certifications (de_certifications): an expired cert not
  --     superseded by a newer active one of the same type gates.
  if exists (
    select 1 from de_certifications c
     where c.tenant_id = p_tenant_id and c.de_id = p_de_id and c.status = 'expired'
       and not exists (
         select 1 from de_certifications c2
          where c2.tenant_id = p_tenant_id and c2.de_id = p_de_id
            and c2.cert_type = c.cert_type and c2.status = 'active'
            and c2.created_at > c.created_at)
  ) then
    v_reasons := array_append(v_reasons, 'expired_certification');
  end if;

  -- (c) GI-4: an OPEN CRITICAL incident on THIS employee gates. de_id is
  --     required so a tenant-level (null-de_id) incident never over-gates one
  --     employee. Self-clears the moment the incident moves off 'open'.
  if exists (
    select 1 from de_incidents i
     where i.tenant_id = p_tenant_id and i.de_id = p_de_id
       and i.status = 'open' and i.severity = 'critical'
  ) then
    v_reasons := array_append(v_reasons, 'open_critical_incident');
  end if;

  -- (d) GI-4: degraded performance gates on ERROR RATE ONLY (never escalation —
  --     escalation self-manufactures under gating; see header). Scoped to this
  --     employee, 56-day recoverable window, >=10-run sample floor so a DE with
  --     little/no run volume is never gated. Div-by-zero guarded. The inner
  --     block fails CLOSED with a distinct diagnosable reason so a throwing
  --     metric query can never bubble up and silently un-gate a fail-open path.
  begin
    select count(*)::bigint,
           count(*) filter (where er.status = 'failed')::bigint
      into v_n, v_failed
      from evidence_runs er
     where er.tenant_id = p_tenant_id and er.de_id = p_de_id
       and er.created_at > now() - interval '56 days'
       -- C-3: production evidence only. 75 of 287 runs carry a non-production
       -- origin, and an exam failing on a harness error must never count toward
       -- an error rate that flips external_reply_mode.
       and public.evidence_is_production(er.origin);
    if coalesce(v_n, 0) >= 10
       and (100.0 * coalesce(v_failed, 0) / nullif(v_n, 0)) > 15 then
      v_reasons := array_append(v_reasons, 'degraded_metrics');
    end if;
  exception when others then
    v_reasons := array_append(v_reasons, 'metrics_check_unavailable');
  end;

  -- (e) GI-9: MANDATORY CERTIFICATION — opt-in per tenant (default off),
  --     grandfathered by hire date, honest per CURRENT role. A DE that has never
  --     passed its current role's exam is supervised, but ONLY when (i) the tenant
  --     explicitly opted in, (ii) the DE was hired AFTER opt-in, (iii) an exam
  --     actually exists for its role. Opt-in is an EXPLICIT-true DIRECT read (never
  --     is_feature_enabled_internal, which fails OPEN). The cert/exam lookups fail
  --     CLOSED inside their own block so a throw on an opted-in tenant goes supervised.
  if p_de_id is not null then
    select tfo.enabled, tfo.updated_at
      into v_req, v_req_since
      from tenant_feature_overrides tfo
     where tfo.tenant_id = p_tenant_id
       and tfo.feature_key = 'require_certification';
    if coalesce(v_req, false) then
      begin
        select d.created_at into v_de_created
          from digital_employees d
         where d.id = p_de_id and d.tenant_id = p_tenant_id;
        -- Grandfather: only DEs hired after opt-in must certify.
        if v_de_created is not null and v_de_created > v_req_since then
          v_arch := public.resolve_de_archetype(p_de_id);
          select exists (
            select 1 from golden_qa gq
             where gq.tenant_id = p_tenant_id and gq.active = true
               and (gq.archetype_key is null or gq.archetype_key = v_arch)
          ) into v_has_exam;
          select exists (
            select 1 from role_certifications rc
             where rc.tenant_id = p_tenant_id and rc.de_id = p_de_id
               and rc.status = 'passed'
               and rc.archetype_key is not distinct from v_arch
          ) into v_has_pass;
          if coalesce(v_has_exam, false) and not coalesce(v_has_pass, false) then
            v_reasons := array_append(v_reasons, 'never_certified');
          end if;
        end if;
      exception when others then
        v_reasons := array_append(v_reasons, 'certification_check_unavailable');
      end;
    end if;
  end if;

  return query select coalesce(array_length(v_reasons, 1), 0) > 0, v_reasons;
end;
$function$;

CREATE OR REPLACE FUNCTION public.de_stall_sweep_internal(p_stall_hours integer DEFAULT 24, p_wake_budget integer DEFAULT 12)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_waited int := 0;
  v_spin int := 0;
  r record;
begin
  -- (a) WAITING TOO LONG. Raising to 'urgent' is itself the idempotency
  --     guard — a second sweep finds nothing left to raise.
  for r in
    select t.id as task_id, t.tenant_id, t.de_id, t.title, t.related_id,
           w.objective_id, t.sla_due_at
      from human_tasks t
      join de_work_items w on w.id = t.related_id
     where t.type = 'escalation'
       and t.status = 'pending'
       and t.related_table = 'de_work_items'
       and coalesce(t.priority, 'normal') <> 'urgent'
       and t.created_at < now() - make_interval(hours => greatest(1, p_stall_hours))
       and w.status = 'waiting_human'
       and tenant_is_operational(t.tenant_id)
     limit 200
  loop
    update human_tasks set priority = 'urgent', updated_at = now() where id = r.task_id;

    update de_objectives
       set attention_flag = 'waiting_too_long',
           attention_since = coalesce(attention_since, now()),
           updated_at = now()
     where id = r.objective_id and attention_flag is distinct from 'waiting_too_long';

    perform append_audit_event_internal(
      r.tenant_id, 'Workspace', 'system',
      format('Escalation unanswered for over %sh — raised to urgent: %s',
             p_stall_hours, left(coalesce(r.title, ''), 120)),
      'escalated',
      jsonb_build_object('task_id', r.task_id, 'de_id', r.de_id,
        'work_item_id', r.related_id, 'objective_id', r.objective_id,
        'sla_due_at', r.sla_due_at, 'stall_hours', p_stall_hours));

    v_waited := v_waited + 1;
  end loop;

  -- (b) WAKE SPIN: the loop runs, nothing moves. The staleness form works on
  --     objectives that predate the 482 wake store (Lakeshore has 121 wakes
  --     and work items untouched since 2026-07-22); once the store fills, an
  --     identical progress_fingerprint across consecutive wakes says the same
  --     thing more precisely.
  for r in
    select o.id, o.tenant_id, o.de_id, o.title, o.wake_count
      from de_objectives o
     where o.status in ('open','in_progress','blocked')
       and o.wake_count >= greatest(2, p_wake_budget)
       and o.attention_flag is distinct from 'wake_spin'
       and tenant_is_operational(o.tenant_id)
       and exists (select 1 from de_work_items w
                    where w.objective_id = o.id
                      and w.status in ('queued','running','waiting_human'))
       and coalesce((select max(w.updated_at) from de_work_items w where w.objective_id = o.id),
                    o.created_at) < now() - make_interval(hours => greatest(1, p_stall_hours))
     limit 200
  loop
    update de_objectives
       set attention_flag = 'wake_spin',
           attention_since = coalesce(attention_since, now()),
           updated_at = now()
     where id = r.id;

    insert into ops_alerts (kind, message, detail)
    select 'de_objective_wake_spin',
           format('%s wakes with no progress: %s', r.wake_count, left(coalesce(r.title, ''), 160)),
           jsonb_build_object('objective_id', r.id, 'tenant_id', r.tenant_id,
             'de_id', r.de_id, 'wake_count', r.wake_count, 'wake_budget', p_wake_budget)
     where not exists (
       select 1 from ops_alerts a
        where a.kind = 'de_objective_wake_spin'
          and a.resolved_at is null
          and a.detail->>'objective_id' = r.id::text);

    perform append_audit_event_internal(
      r.tenant_id, 'Workspace', 'system',
      format('Goal woke %s times with no progress: %s', r.wake_count, left(coalesce(r.title, ''), 120)),
      'escalated',
      jsonb_build_object('objective_id', r.id, 'de_id', r.de_id,
        'wake_count', r.wake_count, 'wake_budget', p_wake_budget));

    v_spin := v_spin + 1;
  end loop;

  return jsonb_build_object('ok', true, 'waited_too_long', v_waited, 'wake_spin', v_spin);
end;
$function$;

CREATE OR REPLACE FUNCTION public.de_status_allowed(p_lifecycle text, p_status text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select case
    when p_lifecycle in ('designed','configured','trained','tested','certified')
      then p_status in ('idle','disabled')
    when p_lifecycle in ('paused','retired','archived')
      then p_status = 'disabled'
    else true
  end;
$function$;

CREATE OR REPLACE FUNCTION public.de_trust_surface_candidates(p_tenant_id uuid, p_de_id uuid)
 RETURNS TABLE(capability_key text, kind text, label text, category text, dialable boolean, destructive boolean, uses_confidence boolean, uses_amount boolean)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
WITH me AS (
  SELECT d.id FROM digital_employees d
   WHERE d.id = p_de_id AND d.tenant_id = p_tenant_id
),
-- widget-ask's own eligibility filter, mirrored exactly.
eligible AS (
  SELECT d.id, d.external_reply_mode, d.created_at
    FROM digital_employees d
   WHERE d.tenant_id = p_tenant_id
     AND coalesce(d.lifecycle_status, '') NOT IN ('paused', 'retired', 'archived', 'designed')
),
front AS (  -- the front-DE heuristic: oldest auto-reply DE, else oldest eligible
  SELECT e.id FROM eligible e
   ORDER BY (CASE WHEN e.external_reply_mode = 'auto' THEN 0 ELSE 1 END), e.created_at ASC
   LIMIT 1
),
serves_widget AS (
  SELECT (
    EXISTS (SELECT 1 FROM eligible e WHERE e.id = p_de_id)
    AND (
      EXISTS (SELECT 1 FROM widget_keys wk           -- mig 323: explicit binding wins
               WHERE wk.tenant_id = p_tenant_id AND wk.active AND wk.de_id = p_de_id)
      OR (
        EXISTS (SELECT 1 FROM widget_keys wk         -- a key that falls back to the heuristic
                 WHERE wk.tenant_id = p_tenant_id AND wk.active
                   AND (wk.de_id IS NULL
                        OR NOT EXISTS (SELECT 1 FROM eligible e2 WHERE e2.id = wk.de_id)))
        AND (SELECT f.id FROM front f) = p_de_id
      )
    )
  ) AS yes
),
-- Reachable registered actions: connector-hub's resolveActionDefinition,
-- mirrored (see header for why provider match is not additionally required).
reachable AS (
  SELECT ad.category   AS category,
         ad.action_key AS action_key,
         min(ad.label) AS label,
         bool_or(coalesce((ad.risk ->> 'destructive')::boolean, true)) AS destructive
    FROM action_definitions ad
   WHERE ad.status = 'active'
     AND ad.provider <> 'internal'
     AND (ad.scope = 'platform' OR (ad.scope = 'tenant' AND ad.tenant_id = p_tenant_id))
     AND EXISTS (SELECT 1 FROM connectors c
                  WHERE c.tenant_id = p_tenant_id
                    AND c.status = 'connected'
                    AND c.category = ad.category)
   GROUP BY ad.category, ad.action_key
),
runs_invoice_playbook AS (
  SELECT EXISTS (
    SELECT 1 FROM playbook_definitions pd
     WHERE pd.tenant_id = p_tenant_id
       AND pd.de_id = p_de_id
       AND pd.status = 'published'
       AND EXISTS (SELECT 1 FROM jsonb_array_elements(pd.steps) s
                    WHERE s ->> 'key' = 'generate_invoice')
  ) AS yes
)
SELECT 'answer_dock', 'answer', 'Answers in the dock (internal chat)',
       NULL::text, true, false, true, false
 WHERE EXISTS (SELECT 1 FROM me)
UNION ALL
SELECT 'answer_widget', 'answer', 'Answers customers on the public widget & help centre',
       NULL::text, true, false, true, false
 WHERE (SELECT yes FROM serves_widget)
UNION ALL
SELECT 'invoice_auto_send', 'playbook', 'Auto-sends renewal invoices (renewal playbook)',
       NULL::text, true, false, false, true
 WHERE EXISTS (SELECT 1 FROM me) AND (SELECT yes FROM runs_invoice_playbook)
UNION ALL
-- A category is dial-able only while it holds at least one non-destructive
-- action: destructive actions gate above the dial unconditionally, so a dial
-- over an all-destructive category could never do anything — showing it
-- dial-able would oversell. The moment a non-destructive action is registered
-- in the category, this recomputes and the dial appears (measured live:
-- the self-management category is all-destructive by design).
SELECT 'action:' || rc.category, 'action_category',
       initcap(replace(rc.category, '_', ' ')) || ' actions',
       rc.category, rc.has_dialable, false, false, true
  FROM (SELECT r.category, bool_or(NOT r.destructive) AS has_dialable
          FROM reachable r GROUP BY r.category) rc
 WHERE EXISTS (SELECT 1 FROM me)
UNION ALL
SELECT r.action_key, 'action', r.label, r.category,
       NOT r.destructive, r.destructive, false, true
  FROM reachable r
 WHERE EXISTS (SELECT 1 FROM me)
UNION ALL
-- RECORD WRITE-BACKS (mig 496). These are the ops an employee uses to keep its
-- own records current — log an activity, set a next step — and they are NOT
-- registered actions: they are their own RPC family, so the reachable CTE above
-- can never produce a card for them. Before this branch the dial that actually
-- governs them (action_execute + source_category) was invisible on every screen
-- in the product and could not be switched off from anywhere.
--
-- Emitted only for an employee that actually works records: it holds a case
-- whose entity kind has a write-back family, or a system it may write to.
-- dialable = true because the non-destructive ops (log_activity, set_next_step)
-- genuinely reach the dial; the destructive ones (advance_stage, update_status,
-- update_stage) return at the destructive floor above it regardless.
SELECT 'writeback:' || wb.category, 'writeback',
       CASE wb.category WHEN 'crm' THEN 'Keeps its own records current (notes & next steps)'
                        ELSE 'Keeps billing records current (notes & next steps)' END,
       wb.category, true, false, false, false
  FROM (
    SELECT DISTINCT CASE WHEN s.write_registry = 'invoice' THEN 'billing' ELSE 'crm' END AS category
      FROM de_connected_systems s
     WHERE s.de_id = p_de_id AND coalesce(s.can_write, false)
    UNION
    SELECT 'crm' WHERE EXISTS (
      SELECT 1 FROM de_objectives o
       WHERE o.de_id = p_de_id AND o.tenant_id = p_tenant_id
         AND o.entity_kind IN ('customer_account', 'opportunity', 'commercial_agreement'))
  ) wb
 WHERE EXISTS (SELECT 1 FROM me);
$function$;

CREATE OR REPLACE FUNCTION public.decide_action_execution(p_tenant_id uuid, p_action_label text, p_category text, p_destructive boolean, p_de_id uuid DEFAULT NULL::uuid, p_amount_cents bigint DEFAULT NULL::bigint, p_action_type text DEFAULT 'action_execute'::text, p_content text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_rule      record;
  -- mig 495: the CONTENT is scanned too. Until now this text was the
  -- server-composed LABEL plus the category — both fixed constants per op —
  -- so guardrails evaluated the same string on every proposal and could never
  -- see what the employee actually wrote. A rule like "no pricing commitments
  -- in writing" was structurally incapable of firing on a write-back.
  v_text      text := lower(coalesce(p_action_label, '') || ' ' || coalesce(p_category, '') || ' ' || coalesce(p_content, ''));
  v_autonomy  record;
  v_risk jsonb;
  v_frag      text;
  v_hit       boolean;
  v_threshold bigint;
  v_period    text;
  v_spent     bigint;
begin
  -- 0) DESTRUCTIVE ALWAYS GATES.
  -- ⚠ THE STOP BUTTON, CHECKED BEFORE ANYTHING ELSE (mig 623). A pause has
  -- to stop everything, including what would otherwise have been allowed, so
  -- it sits above the destructive floor rather than beside the trust dial.
  if public.workforce_autonomy_paused(p_tenant_id) then
    return jsonb_build_object('decision', 'human_gated_paused',
      'guardrail_rule_id', null, 'guardrail_rule', null, 'trust_level', null,
      'reasoning', format('Autonomy is stopped for this whole workspace, so "%s" goes to a person. Nothing runs on its own until someone restarts the workforce.', p_action_label));
  end if;

  if coalesce(p_destructive, true) then
    return jsonb_build_object('decision', 'human_gated_destructive',
      'guardrail_rule_id', null, 'guardrail_rule', null, 'trust_level', null,
      'reasoning', format('This action is marked destructive — it always requires human approval regardless of trust level. This is a platform safety floor, not a per-department setting: "%s" will never auto-execute.', p_action_label));
  end if;

  -- 1) Guardrail check (blocked_phrase / blocked_topic — always win).
  --    WAVE-1 FIX: scope-aware via guardrail_rules_for_de (workspace + this
  --    employee's employee/department rules) instead of every tenant rule.
  for v_rule in
    select id, rule, pattern
    from guardrail_rules_for_de(p_tenant_id, p_de_id,
                                array['blocked_phrase', 'blocked_topic'])
    where severity = 'blocking'
  loop
    if v_rule.pattern is null then continue; end if;
    -- mig 328: match the WHOLE pattern as ONE case-insensitive regex. The old
    -- code split on '|' FIRST and then matched each fragment as its own regex,
    -- which shredded any grouping the rule author wrote -- turning
    --   what is your (pin|cvv|password|ssn|social security)|tell me your (...)
    -- into the bare fragments 'cvv', 'password', 'ssn', so the rule fired on ANY
    -- mention of them. POSIX ~* understands | and () as the author intended.
    begin
      v_hit := v_text ~* v_rule.pattern;
    exception when others then
      -- Not a valid regex -> the author meant literal phrases split by '|'.
      -- Literal only, never regex: a fragment that failed to compile as part of
      -- a whole is not meaningful as a regex on its own.
      v_hit := false;
      foreach v_frag in array string_to_array(v_rule.pattern, '|') loop
        v_frag := trim(both from lower(v_frag));
        if v_frag <> '' and position(v_frag in v_text) > 0 then v_hit := true; exit; end if;
      end loop;
    end;
    if v_hit then
      return jsonb_build_object('decision', 'guardrail_blocked',
        'guardrail_rule_id', v_rule.id, 'guardrail_rule', v_rule.rule, 'trust_level', null,
        'reasoning', format('Blocked: guardrail rule "%s" matched this action — routed to a human regardless of trust. Guardrails always win over the trust dial.', v_rule.rule));
    end if;
  end loop;

  -- 1.5) Amount guardrail (require_approval_over_cents).
  if p_amount_cents is not null then
    select threshold into v_threshold
    from guardrail_rules_for_de(p_tenant_id, p_de_id, array['require_approval_over_cents'])
    where active
    order by (case scope when 'employee' then 0 when 'playbook' then 1 when 'department' then 2 when 'workspace' then 3 else 4 end), updated_at desc
    limit 1;
    v_threshold := coalesce(v_threshold, 1000000);
    if p_amount_cents > v_threshold then
      return jsonb_build_object('decision', 'human_gated_trust',
        'guardrail_rule_id', null, 'guardrail_rule', 'require_approval_over_cents', 'trust_level', null,
        'reasoning', format('Needs approval: "%s" is for $%s, above this workspace''s $%s approval threshold. Amounts over the threshold always get a human, regardless of the trust dial.', p_action_label, round(p_amount_cents / 100.0), round(v_threshold / 100.0)));
    end if;
  end if;

  -- 1.6) SPEND CAPS (additive, GUARDED) — only DEs with a configured spend_cap
  --      rule are affected. Sums this period's ledger + this action's amount and
  --      gates to a human if it would breach the cap. A DE with no cap: no-op.
  if p_de_id is not null and p_amount_cents is not null then
    for v_rule in
      select rule_type, threshold from guardrail_rules
      where tenant_id = p_tenant_id and active
        and rule_type in ('spend_cap_daily_cents', 'spend_cap_monthly_cents')
        and (scope = 'workspace' or (scope = 'employee' and scope_ref = p_de_id::text))
        and threshold is not null
      order by threshold asc
    loop
      if v_rule.rule_type = 'spend_cap_daily_cents' then
        v_period := to_char(current_date, 'YYYY-MM-DD');
        select coalesce(sum(cents), 0) into v_spent from de_spend_ledger
          where tenant_id = p_tenant_id and de_id = p_de_id and period_kind = 'day' and period_key = v_period;
      else
        v_period := to_char(current_date, 'YYYY-MM');
        select coalesce(sum(cents), 0) into v_spent from de_spend_ledger
          where tenant_id = p_tenant_id and de_id = p_de_id and period_kind = 'month' and period_key = v_period;
      end if;
      if v_spent + p_amount_cents > v_rule.threshold then
        return jsonb_build_object('decision', 'human_gated_trust',
          'guardrail_rule_id', null, 'guardrail_rule', v_rule.rule_type, 'trust_level', null,
          'reasoning', format('Needs approval: this $%s spend would take %s spend to $%s, over the $%s cap. Spend over the cap always gets a human.',
            round(p_amount_cents / 100.0),
            case when v_rule.rule_type = 'spend_cap_daily_cents' then 'today''s' else 'this month''s' end,
            round((v_spent + p_amount_cents) / 100.0), round(v_rule.threshold / 100.0)));
      end if;
    end loop;
  end if;

  -- 2) Trust dial (per-employee cascade), resolved through the fallback
  --    chain: the registered action's own key first, then its whole
  --    category, then the generic gate. Every generic-gate seed sits at
  --    enabled=false, so nothing opens by itself — this makes per-action
  --    trust representable, and that is all it does. The destructive
  --    floor, guardrails, the amount threshold and spend caps all
  --    returned above before this line is ever reached.
  select * into v_autonomy from resolve_de_autonomy_chain(
    p_tenant_id,
    array[
      -- ⚠ SPECIFIC FIRST (mig 618). Reversed, the generic key matched
      -- whenever any row existed and 'action:<category>' was never reached,
      -- which is why a per-category rule had never once been consulted.
      case when nullif(p_category, '') is not null then 'action:' || p_category end,
      nullif(p_action_type, ''),
      'action_execute'
    ],
    p_de_id, p_category);
  -- ── THE SECOND QUESTION (spec §3.6), on the employee path ────────────
  -- Everything above answered "has this employee EARNED this?" — guardrails,
  -- the destructive floor, the amount threshold, the spend caps and the
  -- earned-trust chain. All of it is unchanged. This asks the other question:
  -- "does this particular action need more scrutiny?"
  --
  -- It sits immediately before the auto_executed return because that is THE
  -- ONLY return in this function that lets an action through without a human.
  -- Every other path already ends at a person.
  --
  -- ⚠ THE MAPPING IS CONSTRAINED, NOT CHOSEN. action_executions.decision
  -- carries a CHECK of ten values, so a new one would RAISE on insert inside
  -- record_action_execution. deny therefore becomes 'access_denied' — in the
  -- CHECK, semantically exact, and never once used live, so it cannot be
  -- confused with an existing meaning. 'guardrail_blocked' was rejected: five
  -- functions branch on it, and an authority denial is not a guardrail hit.
  -- Callers are safe either way — eight functions gate on = 'auto_executed',
  -- so anything else means "do not execute".
  --
  -- With authority_rules EMPTY this is exactly a no-op.
  v_risk := evaluate_authority(
    p_tenant_id,
    case when p_de_id is null then 'all' else 'de' end,
    p_de_id,
    p_category,
    case when p_amount_cents is null then '{}'::jsonb
         else jsonb_build_object('amount_cents', p_amount_cents) end);

  if v_risk->>'outcome' = 'deny' then
    return jsonb_build_object('decision', 'access_denied',
      'guardrail_rule_id', null, 'guardrail_rule', null, 'trust_level', null,
      'reasoning', format('Refused: a workspace authority rule denies this. %s',
        coalesce(v_risk->'reasons'->0->>'why', 'No reason was recorded.')));
  end if;

  if v_risk->>'outcome' in ('require_human','require_second_approver') then
    return jsonb_build_object('decision', 'human_gated_trust',
      'guardrail_rule_id', null, 'guardrail_rule', null, 'trust_level', null,
      'reasoning', format('Needs approval: a workspace authority rule asks for a person here. %s',
        coalesce(v_risk->'reasons'->0->>'why', 'No reason was recorded.')));
  end if;

  if coalesce(v_autonomy.enabled, false)
     and (p_amount_cents is null
          or (v_autonomy.max_amount_cents is not null and p_amount_cents <= v_autonomy.max_amount_cents)) then
    return jsonb_build_object('decision', 'auto_executed',
      'guardrail_rule_id', null, 'guardrail_rule', null, 'trust_level', 1,
      'reasoning', case
        when p_amount_cents is not null then
          format('Auto-executed: "%s" ($%s) is within both the workspace approval threshold and the earned trust-dial limit of $%s%s, and no guardrail blocked it.',
            p_action_label, round(p_amount_cents / 100.0), round(v_autonomy.max_amount_cents / 100.0),
            case when p_de_id is not null then ' resolved for this employee' else '' end)
        else
          format('Auto-executed: "%s" is not destructive, no guardrail blocked it, and the trust dial%s allows auto-executing non-destructive actions for %s.',
            p_action_label, case when p_de_id is not null then ' (resolved for this employee)' else '' end, p_category)
      end);
  end if;

  return jsonb_build_object('decision', 'human_gated_trust',
    'guardrail_rule_id', null, 'guardrail_rule', null, 'trust_level', null,
    'reasoning', case
      when not coalesce(v_autonomy.enabled, false) then
        format('Needs approval: "%s" is not destructive, but the trust dial has not enabled auto-execution for %s %s actions yet (Governance -> Trust & Architecture).',
          p_action_label, case when p_de_id is not null then 'this employee''s' else 'this workspace''s' end, p_category)
      else
        format('Needs approval: "%s" ($%s) exceeds the trust-dial limit of %s earned so far.',
          p_action_label, round(coalesce(p_amount_cents, 0) / 100.0),
          coalesce('$' || round(v_autonomy.max_amount_cents / 100.0)::text, 'no amount'))
    end);
end;
$function$;

CREATE OR REPLACE FUNCTION public.decide_de_escalation(p_task_id uuid, p_disposition text, p_instruction text DEFAULT NULL::text, p_assign_role text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tenant uuid := auth_tenant_id();
  v_task human_tasks;
  v_de_name text;
  v_instruction text;
  v_moved uuid;
begin
  -- mig 486: this is a sanctioned decision path (see guard_human_task_decision).
  perform set_config('app.allow_task_decision', 'on', true);

  if v_tenant is null then raise exception 'not_authenticated'; end if;
  -- mig 503: authority follows ASSIGNMENT, not job title. The per-employee
  -- can_access_de test below is the whole gate now.

  if p_disposition not in ('answered','cancelled','rerouted') then
    raise exception 'disposition must be answered | cancelled | rerouted';
  end if;

  select * into v_task from human_tasks where id = p_task_id and tenant_id = v_tenant;
  if v_task.id is null then raise exception 'task_not_found'; end if;
  if v_task.status <> 'pending' then raise exception 'already_decided: %', v_task.status; end if;
  if v_task.de_id is not null and not can_access_de(v_task.de_id) then
    raise exception 'insufficient_scope';
  end if;

  v_instruction := nullif(btrim(coalesce(p_instruction, '')), '');
  if p_disposition = 'cancelled' and v_instruction is null then
    raise exception 'cancelling a blocker requires a reason';
  end if;

  update human_tasks set
    status = case when p_disposition = 'cancelled' then 'rejected'
                  when p_disposition = 'answered' then 'approved'
                  else status end,
    disposition = p_disposition,
    decision_note = coalesce(v_instruction, decision_note),
    assigned_role = coalesce(p_assign_role, assigned_role),
    decided_by = auth.uid(),
    decided_at = now()
  where id = p_task_id;

  if p_disposition = 'rerouted' then
    v_moved := resume_de_work_from_decision(p_task_id, 'rerouted', v_instruction);
  else
    select resolved_work_item_id into v_moved from human_tasks where id = p_task_id;
  end if;

  select name into v_de_name from digital_employees where id = v_task.de_id;
  perform append_audit_event(
    v_tenant, 'Workspace', 'human',
    format('%s escalation %s — %s', coalesce(v_de_name, 'An employee'), p_disposition, left(v_task.title, 120)),
    'approval',
    jsonb_build_object('task_id', p_task_id, 'de_id', v_task.de_id,
      'disposition', p_disposition, 'instruction', v_instruction,
      'work_item_id', v_task.related_id, 'work_item_moved', v_moved is not null));

  return jsonb_build_object('ok', true, 'disposition', p_disposition,
    'work_item_id', v_task.related_id, 'work_item_moved', v_moved is not null);
end;
$function$;

CREATE OR REPLACE FUNCTION public.decide_de_exception(p_exception_id uuid, p_decision text, p_outcome text DEFAULT NULL::text, p_learned boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tenant uuid := auth_tenant_id();
  v_row de_exceptions;
  v_de_name text;
  v_status text;
  v_memory_id uuid;
  v_item_moved uuid;
  v_instruction text;
BEGIN
  IF v_tenant IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  -- mig 503: authority follows ASSIGNMENT, not job title (founder decision,
  -- block 4). The per-employee test happens below, once the row identifies
  -- which employee this is.

  IF p_decision NOT IN ('approved','rejected','denied') THEN
    RAISE EXCEPTION 'decision must be approved or rejected';
  END IF;
  v_status := CASE WHEN p_decision = 'rejected' THEN 'denied' ELSE p_decision END;
  SELECT * INTO v_row FROM de_exceptions WHERE id = p_exception_id AND tenant_id = v_tenant;
  IF v_row.id IS NULL THEN RAISE EXCEPTION 'exception_not_found'; END IF;
  IF v_row.status <> 'proposed' THEN RAISE EXCEPTION 'already_decided: %', v_row.status; END IF;
  -- Assignment (or seniority) decides. can_access_de encodes both axes:
  -- owner/admin/manager pass for the whole workforce, everyone else passes
  -- for the employees they are actually assigned to.
  IF NOT can_access_de(v_row.de_id) THEN RAISE EXCEPTION 'insufficient_scope'; END IF;
  SELECT name INTO v_de_name FROM digital_employees WHERE id = v_row.de_id;
  v_instruction := nullif(btrim(coalesce(p_outcome, '')), '');

  UPDATE de_exceptions SET
    status = v_status, outcome = p_outcome, learned = coalesce(p_learned, false),
    decided_by = auth.uid(), decided_at = now()
  WHERE id = p_exception_id;

  -- (A) "remember this" -> durable memory the employee actually recalls.
  IF coalesce(p_learned, false) THEN
    v_memory_id := de_memory_write(
      p_tenant_id    => v_tenant,
      p_de_id        => v_row.de_id,
      p_content      => left(format('Human ruling (%s): when facing "%s" the proposal was "%s".%s', v_status, v_row.situation, v_row.proposed_action, CASE WHEN v_instruction IS NOT NULL THEN ' Instruction: ' || v_instruction ELSE '' END), 2000),
      p_embedding    => NULL,             -- de_memory_search degrades to recency+salience when null
      p_subject_kind => 'general',
      p_subject_ref  => NULL,
      p_kind         => 'fact',
      p_salience     => 0.8,
      p_source       => 'human');
  END IF;

  -- (B) the paused work item moves with the decision.
  IF v_row.work_item_id IS NOT NULL THEN
    IF v_status = 'approved' THEN
      UPDATE de_work_items SET
        status = 'queued', scheduled_for = now(), attempts = 0, last_error = NULL,
        locked_at = NULL, locked_by = NULL, updated_at = now(),
        payload = payload || jsonb_build_object(
          'detail', left(coalesce(payload->>'detail','')
            || E'\n\nHUMAN RULING: your proposal for this task was APPROVED'
            || CASE WHEN v_instruction IS NOT NULL THEN '. Instruction: ' || v_instruction ELSE '' END
            || '. Approved proposal: "' || left(v_row.proposed_action, 400)
            || '". Carry it out now; do not raise this same exception again.', 4000),
          'human_ruling', jsonb_build_object('exception_id', p_exception_id,
            'decision', v_status, 'outcome', p_outcome, 'decided_at', now()))
      WHERE id = v_row.work_item_id AND tenant_id = v_tenant AND status = 'waiting_human'
      RETURNING id INTO v_item_moved;
    ELSE
      UPDATE de_work_items SET
        status = 'cancelled', locked_at = NULL, locked_by = NULL, updated_at = now(),
        result = coalesce(result, '{}'::jsonb) || jsonb_build_object(
          'summary', left('Denied by human' || CASE WHEN v_instruction IS NOT NULL THEN ': ' || v_instruction ELSE '' END, 500),
          'human_ruling', jsonb_build_object('exception_id', p_exception_id,
            'decision', v_status, 'outcome', p_outcome, 'decided_at', now()))
      WHERE id = v_row.work_item_id AND tenant_id = v_tenant AND status = 'waiting_human'
      RETURNING id INTO v_item_moved;
      -- claim_de_work_items requires depends_on to be 'done'; a cancelled
      -- predecessor strands its successors as invisible-stuck 'queued' rows.
      IF v_item_moved IS NOT NULL THEN
        WITH RECURSIVE chain AS (
          SELECT w.id FROM de_work_items w
           WHERE w.depends_on = v_row.work_item_id AND w.tenant_id = v_tenant
             AND w.status IN ('queued','waiting_human')
          UNION ALL
          SELECT w2.id FROM de_work_items w2 JOIN chain c ON w2.depends_on = c.id
           WHERE w2.status IN ('queued','waiting_human')
        )
        UPDATE de_work_items w SET status = 'cancelled',
               last_error = 'predecessor denied by human ruling', updated_at = now()
          FROM chain WHERE w.id = chain.id;
      END IF;
    END IF;
  END IF;

  PERFORM append_audit_event(
    v_tenant, 'Workspace', 'human',
    format('%s exception %s — %s', coalesce(v_de_name, 'An employee'), v_status, left(v_row.situation, 120)),
    'approval',
    jsonb_build_object('exception_id', p_exception_id, 'de_id', v_row.de_id,
      'decision', v_status, 'learned', coalesce(p_learned, false),
      'memory_id', v_memory_id, 'work_item_id', v_row.work_item_id,
      'work_item_moved', v_item_moved IS NOT NULL));
  RETURN jsonb_build_object('ok', true, 'status', v_status,
    'memory_id', v_memory_id, 'work_item_id', v_row.work_item_id,
    'work_item_moved', v_item_moved IS NOT NULL);
END$function$;

CREATE OR REPLACE FUNCTION public.decide_discovery_proposal(p_proposal_id uuid, p_decision text, p_note text DEFAULT NULL::text, p_created_object_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_p          public.discovery_proposals%rowtype;   -- the proposal, read once
  v_row        public.discovery_proposals%rowtype;   -- what the CAS claimed
  v_detail     jsonb;
  v_label      text;
  v_action     text;
  v_object_id  uuid;
  v_object_tbl text;
  v_writer     text;
  v_err        text;
  v_errstate   text;
  v_attempts   integer;

  -- ── added by 746, for the `employee` branch ──────────────────────────────
  v_arch       text;      -- the archetype key, off the payload
  v_name       text;      -- what the new employee is called, off the payload
  v_de_id      uuid;      -- what instantiate_role_archetype created
  v_kit        jsonb;     -- install_role_kit's own account of what it installed
  v_systems    integer;   -- install_role_systems' count, or 0 if it refused
  -- Everything the accept wants to be able to SAY afterwards, in one object
  -- that is merged into BOTH the return payload and the audit detail so the two
  -- can never disagree. Empty for every kind that does not fill it, so the
  -- connector branch's shape is byte-identical to what 741 returned.
  v_counters   jsonb := '{}'::jsonb;

  -- ── added by 747, for the `employee` branch ──────────────────────────────
  -- ⚠ A HIRE ATTACHES WORKSPACE-WIDE BLOCKING RULES AND SAID NOTHING. 7 of 15
  -- active archetypes carry a compliance pack; instantiate_role_archetype
  -- materialises its rules as guardrail_rules with applies_to='all',
  -- severity='blocking'. None of that reached a counter, an audit detail or a
  -- card, so a customer accepted controls they were never shown — the same
  -- §11b problem the guardrail card already solves for a single rule.
  --
  -- Measured as a BEFORE/AFTER DELTA rather than read off the archetype,
  -- because the two answer different questions: the archetype says which packs
  -- the role declares, the delta says how many rules THIS accept actually put
  -- in force. They differ whenever the workspace already had the pack, which is
  -- the common case for a second finance hire — and a card that claims two new
  -- blocking rules when it added none is the overclaim this file already
  -- refuses for guardrails and systems.
  v_pack_keys  text[];    -- what the role declares
  v_pack_before bigint;   -- active pack rules in the workspace before the hire
  v_pack_after  bigint;   -- ...and after

  -- ── added by 751, for the `guardrail` branch ─────────────────────────────
  -- The payload is exactly {rule, pattern, threshold, severity} and carries NO
  -- rule_type; these three are what the branch reads off it, and v_rule is the
  -- row the browser says it created, read back so every promise on the card can
  -- be checked against the thing that now exists rather than against the thing
  -- the caller says exists.
  v_pattern    text;      -- the literal the card showed, verbatim
  v_threshold  text;      -- the bare, unitless number — held, never written
  v_pattern_ok boolean;   -- ...is that literal one the matcher can actually use
  v_rule       public.guardrail_rules%rowtype;

  -- ── added by 752, for the `procedure` branch ─────────────────────────────
  -- The payload is {name, trigger, steps, evidence, note} — FILL_WHITELIST
  -- .procedure is ['name','trigger','steps'], so those three are the model's
  -- and the rest is the emitter's. These four are what the branch reads off it.
  --
  -- v_sop is the SOP TEXT COMPOSED FROM THEM: byte for byte the string the
  -- browser sent the drafter, and the thing the `playbook_studies` check
  -- compares against. It is this kind's consented literal, the way `pattern` is
  -- the guardrail's — §11b's "you cannot consent to what you cannot predict"
  -- applied to a procedure is the name, the trigger and the steps the card
  -- showed.
  --
  -- v_pb_key is DERIVED FROM THE PROPOSAL ID, and that is the whole
  -- anti-duplication mechanism: one proposal, one key, UNIQUE (tenant_id, key).
  -- v_def is the draft the caller says came back, read WHOLE, because a promise
  -- nobody re-reads is a promise nobody keeps.
  -- ⚠ v_proc_name IS THE COMPARED VALUE AND v_proc_label IS THE PRINTED ONE,
  -- and they are two variables on purpose. `last_error` is written as
  -- `left(v_err, 500)`, the bound 741 chose and every kind shares; the
  -- provenance refusal below is 326 characters before the name goes in, so a
  -- name over 174 characters cut the closing sentence off the card — the one
  -- that tells the customer the draft exists, runs nothing, and can be archived.
  -- Nothing caps the name: not `validatePayload` at emission, not
  -- `procedureAcceptability` in the browser, and not the column (both `name`
  -- and `last_error` are unbounded `text`).
  --
  -- Of the three fixes, capping the name is the only one that BOUNDS the
  -- message. Raising 500 moves the cliff without removing it — a 4,000-character
  -- name truncates at any bound — and it changes a field all six kinds write for
  -- the sake of one. Shortening the sentence removes the thing the sentence is
  -- for. Capping the name makes every refusal in this branch fit whatever the
  -- customer typed, and the name is the one part already on the card in front of
  -- them. 140 + an ellipsis is the widest cap the tightest message admits: the
  -- name-mismatch refusal prints TWO names against a 216-character base, so
  -- 216 + 2 x 141 = 498.
  --
  -- ⚠ v_proc_label MUST NEVER REACH `v_sop` OR THE `v_def.name` COMPARISON. The
  -- SOP text is compared BYTE FOR BYTE against what the drafter recorded, and
  -- the name is compared byte for byte against the row; a truncated value in
  -- either would refuse a perfectly correct draft, permanently.
  v_proc_name  text;      -- what the procedure is called, off the payload
  v_proc_label text;      -- ...the same name, capped, for MESSAGES ONLY
  v_def_label  text;      -- ...and the row's own name, capped the same way
  v_proc_trig  text;      -- when it runs, in the customer's own words
  v_proc_steps text[];    -- the prose steps, trimmed, blanks dropped
  v_sop        text;      -- the composed SOP text — the consented literal
  v_pb_key     text;      -- 'discovery_' || the proposal id, dashes removed
  v_def        public.playbook_definitions%rowtype;
  v_study_ok   boolean;   -- ...was this draft compiled from THAT sop text

  -- ── added by 753, for the `trust_rule` branch ────────────────────────────
  -- The payload is {de_ref, action_category, cap, above_cap, evidence} —
  -- FILL_WHITELIST.trust_rule is ['de_ref','action_category','cap','above_cap'],
  -- so those four are the model's and `evidence` is the emitter's.
  --
  -- ⚠ THERE IS NO v_ladder VARIABLE HERE AND THAT IS THE WHOLE DESIGN. This
  -- branch NEVER writes `trust_policies.ladder`, never calls set_trust_ladder
  -- and never calls trust_apply_level. See the header's three measured reasons;
  -- the shortest is that `cap` carries no unit and `max_amount_cents` is CENTS,
  -- so writing it would be the same factor-of-a-hundred guess the founder
  -- already refused for guardrail thresholds on 2026-08-15.
  v_tr_ref     text;      -- "archetype:<key>", off the payload
  v_tr_arch    text;      -- ...the key on its own
  v_tr_cat     text;      -- the action category, off the payload
  v_tr_cap_raw text;      -- the cap exactly as the payload carries it
  v_tr_cap_n   text;      -- ...normalised the way isNumericLiteral normalises
  v_tr_above   text;      -- "what happens above it", the customer's words
  v_tr_unit    text;      -- 'confidence' or 'amount' — set_trust_ladder's split
  v_tr_de      uuid;      -- the employee, resolved from an ACCEPTED sibling
  v_tr_emp     text;      -- ...its name, for the messages
  v_tr_pol     public.trust_policies%rowtype;
  v_tr_seeded  boolean := false;  -- did THIS accept open the setting
  v_tr_dials   bigint;    -- de_autonomy rows for this exact scope, counted

  -- ── added by 754, for the `conversation_type` branch ────────────────────
  -- The payload is {label, set_category, match_pattern, examples, evidence} —
  -- FILL_WHITELIST.conversation_type is ['label','set_category','match_pattern'],
  -- so those three are the model's and the rest is the emitter's. All three are
  -- COMPARED byte for byte against the row the browser created, which is why
  -- they are trimmed with 751's explicit set rather than one-argument btrim.
  --
  -- v_ct_ties and v_ct_ahead are COUNTED, never claimed. classify_support_text
  -- walks the rules `ORDER BY rule_order, created_at` and returns on the FIRST
  -- match, so where a rule sits IS the routing decision — and a tie is broken by
  -- a timestamp no screen shows.
  v_ct_label   text;      -- what the topic is called, off the payload
  v_ct_cat     text;      -- the token written into de_conversations.category
  v_ct_pattern text;      -- the pipe-separated literal phrases, verbatim
  v_ct_ties    bigint;    -- other active rules sharing its position
  v_ct_ahead   bigint;    -- active rules consulted BEFORE it
  v_ct_rule    public.support_triage_rules%rowtype;
  -- ⚠ 760. THE OWNER, and it is resolved the way 753 resolves a trust rule's
  -- de_ref rather than the way every other Path B kind resolves an object id:
  -- `owner_ref` is "archetype:<key>", never an employee id, because at the
  -- moment the interview writes the card that employee DOES NOT EXIST YET. The
  -- id it means is the one an ACCEPTED employee proposal IN THIS SAME SESSION
  -- created, so "you cannot own a topic until you have been hired" is enforced
  -- here in SQL and not only by the browser.
  v_ct_own_ref  text;     -- "archetype:<key>", off the payload, or NULL
  v_ct_own_arch text;     -- ...the key on its own
  v_ct_owner    uuid;     -- the employee it resolves to, or NULL for "nobody"
  v_ct_own_name text;     -- ...their name, for the card and the audit line
begin
  --------------------------------------------------------------------------
  -- ZONE 1 — refuse before touching anything. Every branch here RAISES, and
  -- nothing has been written when it does.
  --------------------------------------------------------------------------

  -- A null uid is refused on its own line and FIRST, for all three decisions.
  -- Folding this into the role predicate as `auth.uid() is not null and ...`
  -- is the exact bug in install_role_kit: it makes the authority check SKIP
  -- instead of FAIL. It applies to decline and park too, because a terminal
  -- state with a null decided_by is a decision nobody made.
  if auth.uid() is null then
    raise exception 'not authenticated: a discovery proposal is decided by a person, and the decision records which person';
  end if;

  select * into v_p from public.discovery_proposals where id = p_proposal_id;
  if v_p.id is null then
    raise exception 'unknown discovery proposal %', p_proposal_id;
  end if;

  if p_decision is null or p_decision not in ('accepted', 'declined', 'parked') then
    raise exception 'decide_discovery_proposal: % is not a decision — must be ''accepted'', ''declined'' or ''parked''',
      coalesce(p_decision, 'NULL');
  end if;

  -- The role bar. The tenant comes off the ROW (v_p.tenant_id), never from a
  -- parameter. Accept only: saying no is not gated.
  --
  -- ⚠ NO `p.layer = 'platform' or` DISJUNCT. A platform profile has
  -- tenant_id NULL and `profiles` is UNIQUE (user_id), so its holder can never
  -- satisfy append_audit_event's membership check. Admitting them here means
  -- passing the authority check and then aborting at the audit call OUTSIDE
  -- every sub-block — with the browser's connector already committed. Refuse
  -- in Zone 1, in words, before anything is claimed. See the header.
  if p_decision = 'accepted' then
    if not exists (
      select 1 from public.profiles p
       where p.user_id = auth.uid()
         and coalesce(p.is_active, true)
         and p.tenant_id = v_p.tenant_id
         and p.role in ('tenant_owner', 'tenant_admin')
    ) then
      raise exception 'only workspace owners and admins can accept a discovery proposal — declining and parking are open to anyone in the workspace';
    end if;
  end if;

  --------------------------------------------------------------------------
  -- ZONE 2 — THE CLAIM. This compare-and-swap is the double-click guard.
  -- It is OUTSIDE any sub-block on purpose: a writer's rollback in Zone 3
  -- must not be able to undo it.
  --
  -- 'parked' is in the admitted set because park is a pause. 'accepted' and
  -- 'declined' are not, so a second decision on either matches zero rows,
  -- leaves v_row NULL, and returns already_decided having written nothing.
  --
  -- ⚠ `and not (state = 'parked' and p_decision = 'parked')` is what makes PARK
  -- ITSELF IDEMPOTENT. Without it a double-clicked Park matches on 'parked',
  -- re-dates decided_at, writes a SECOND config_change audit row and returns
  -- ok=true twice — the same class of defect that logged one human's approval
  -- three times in 37 seconds. Parked → accepted and parked → declined are
  -- untouched by this clause; only parked → parked is refused.
  --------------------------------------------------------------------------
  update public.discovery_proposals
     set state      = p_decision,
         decided_by = auth.uid(),
         decided_at = now()
   where id        = p_proposal_id
     and tenant_id = v_p.tenant_id
     and state in ('pending', 'parked')
     and not (state = 'parked' and p_decision = 'parked')
  returning * into v_row;

  if v_row.id is null then
    return jsonb_build_object(
      'ok',          false,
      'error',       'already_decided',
      'proposal_id', p_proposal_id,
      'state',       (select state from public.discovery_proposals
                       where id = p_proposal_id and tenant_id = v_p.tenant_id));
  end if;

  --------------------------------------------------------------------------
  -- THE AUDIT DETAIL, BUILT ONCE, BEFORE THE BRANCH.
  --
  -- Built here rather than per-arm so that a decline cannot be dropped by
  -- someone editing a separate code path. The accept arm ADDS to it; no arm
  -- rebuilds it.
  --
  -- `payload` goes in WHOLE AND VERBATIM. It is the only copy of the literal
  -- the customer consented to, and the row it came from can be edited or
  -- deleted with no version history anywhere else — the same reasoning
  -- retire_guardrail_rule states in its own comment.
  --
  -- `decided_by` goes INSIDE detail. append_audit_event's hash covers
  -- prev_hash || tenant_id || action || detail::text || created_at. The
  -- `actor` COLUMN is not in the digest; `detail` is. The tamper-evident
  -- chain does not protect the identity column, so the identity is put where
  -- the chain reaches.
  --
  -- ⚠ append_audit_event, not _internal, and UNGUARDED: it raises on failure,
  -- so no audit row means no decision. Swallowing it is the deprecated
  -- resolve_account_writeback shape. Category MUST be 'config_change' — an
  -- invented category violates audit_events_category_check and aborts the
  -- decision, which is the mig-429 lesson.
  --------------------------------------------------------------------------
  v_label := coalesce(
    nullif(btrim(v_p.payload ->> 'name'), ''),
    nullif(btrim(v_p.payload ->> 'label'), ''),
    nullif(btrim(v_p.payload ->> 'rule'), ''),
    nullif(btrim(v_p.payload ->> 'archetype_key'), ''),
    nullif(btrim(v_p.payload ->> 'provider_key'), ''),
    'unnamed');

  v_detail := jsonb_build_object(
    'kind',             'discovery_proposal_decision',
    'decision',         p_decision,
    'proposal_id',      v_p.id,
    'session_id',       v_p.session_id,
    'proposal_kind',    v_p.kind,
    'source_dimension', v_p.source_dimension,
    'payload',          v_p.payload,
    'rationale',        v_p.rationale,
    'note',             nullif(btrim(p_note), ''),
    'decided_by',       auth.uid());

  v_action := format('Discovery proposal %s — %s (%s).', p_decision, v_label, v_p.kind);

  -- Decline and park end here. Both audited, for three reasons: there is no
  -- note column on the table, so an unaudited decline destroys the only
  -- sentence explaining why a customer refused; absence must be
  -- distinguishable from never-shown; and an unaudited park re-creates the
  -- invisible pile.
  if p_decision <> 'accepted' then
    perform public.append_audit_event(
      v_p.tenant_id, 'You', 'human', v_action, 'config_change', v_detail);

    return jsonb_build_object(
      'ok',                true,
      'state',             p_decision,
      'proposal_id',       v_p.id,
      'created_object_id', null);
  end if;

  --------------------------------------------------------------------------
  -- ZONE 3 — ACCEPT ONLY. Exactly ONE sub-block, for the whole accept.
  --
  -- ADDING A KIND IS ONE `when` BRANCH HERE AND NOTHING ELSE. A branch must
  -- set v_writer and v_object_tbl (they are what the audit line and the
  -- refusal record report) and end with v_object_id set to the thing that now
  -- exists, or raise with a sentence a person can read.
  --------------------------------------------------------------------------
  begin
    case v_p.kind

      -- ---- connector — Path B -------------------------------------------
      -- The browser already inserted the row as the signed-in human under
      -- RLS. This stamps it. It does NOT insert: an `insert into connectors`
      -- here runs as postgres, bypasses RLS entirely, and is the second
      -- creation engine the plan forbids.
      --
      -- ⚠ NO `data_access_grants` ROW IS WRITTEN, and that is load-bearing
      -- rather than an oversight. `poll_de_work_sources_targets` filters
      -- `c.status <> 'disconnected'`, which ADMITS 'pending_credentials', and
      -- joins to data_access_grants. The grant is what arms the poller.
      -- Withholding it is what makes the card's promise — "you still enter
      -- the credential yourself" — true on every traced path.
      when 'connector' then
        v_writer     := 'connectProvider -> connectors (client, under RLS), stamped here';
        v_object_tbl := 'connectors';

        if p_created_object_id is null then
          raise exception 'a connector proposal is accepted by creating the connector first: insert it as the signed-in person, then pass its id here (Path B)';
        end if;

        -- The id a caller hands us is NOT its own authorisation. It must be a
        -- connector already belonging to THIS proposal's tenant, or
        -- created_object_id would point at another workspace's row — or at
        -- nothing at all, which would satisfy the Task 5 certify assertion
        -- with garbage.
        if not exists (
          select 1 from public.connectors c
           where c.id = p_created_object_id
             and c.tenant_id = v_p.tenant_id
        ) then
          raise exception 'no connector % in this workspace — a created-object id is not its own authorisation', p_created_object_id;
        end if;

        v_object_id := p_created_object_id;

      -- ---- employee — Path A, ONE transaction ----------------------------
      -- THE FIRST KIND THIS FUNCTION CREATES ITSELF, and it can only because
      -- all three of its ordinary writers are SQL. `p_created_object_id` is
      -- IGNORED here: there is nothing for the browser to have made first, and
      -- `authenticated` holds only SELECT on digital_employees, which is
      -- exactly why this kind cannot be Path B.
      --
      -- The human hire is three RPCs in three transactions
      -- (src/lib/hireApi.ts:104-149) and has already stranded half-hired
      -- employees. This is one.
      when 'employee' then
        v_writer     := 'instantiate_role_archetype + install_role_kit + install_role_systems, inside decide_discovery_proposal';
        v_object_tbl := 'digital_employees';

        -- Both literals are read BEFORE anything is created, and refused in
        -- words. digital_employees.name is NOT NULL with no default (read live
        -- from pg_attribute), so a payload without one would otherwise reach
        -- the customer as `23502 null value in column "name"` — a sentence
        -- about a column nobody outside this file has heard of, written onto
        -- the card by migration 740's last_error and still there tomorrow.
        v_arch := nullif(btrim(v_p.payload ->> 'archetype_key'), '');
        v_name := nullif(btrim(v_p.payload ->> 'name'), '');
        if v_arch is null then
          raise exception 'this recommendation does not say which role to hire, so there is nothing to create — it carries no archetype_key';
        end if;
        if v_name is null then
          raise exception 'this recommendation does not say what to call the new employee, and an employee has to have a name';
        end if;

        -- 1. THE HIRE. Creates the digital_employees row at
        --    designed/supervised, attaches the archetype's mandatory compliance
        --    packs and materialises its PER-EMPLOYEE autonomy dials, so a hire
        --    never widens the workspace.
        --
        --    ⚠ It does NOT set is_workforce_assistant (live body, read via
        --    pg_get_functiondef), so the column takes its default of false: a
        --    discovery accept can never stamp the workspace's own admin desk,
        --    which is what scripts/discovery-proposal-check.mjs's `excluded`
        --    resolver arm refuses on every certify.
        --    ⚠ THE PACK COUNT IS TAKEN EITHER SIDE OF THIS CALL, because
        --    instantiate_role_archetype returns only a uuid and the pack attach
        --    happens inside it. Counting `active and retired_at is null` on
        --    both sides means a pack the workspace already held contributes 0,
        --    and a pack whose rules were previously RETIRED by a detach and are
        --    revived here contributes them — which is exactly what a person
        --    needs to be told, since revived rules start blocking again.
        select count(*) into v_pack_before
          from public.guardrail_rules g
         where g.tenant_id = v_p.tenant_id
           and g.compliance_pack_key is not null
           and g.active and g.retired_at is null;
        select coalesce(a.compliance_pack_keys, '{}'::text[]) into v_pack_keys
          from public.role_archetypes a where a.key = v_arch;

        v_de_id := public.instantiate_role_archetype(
                     v_p.tenant_id, v_arch, v_name, null);
        if v_de_id is null then
          raise exception 'the hire returned no employee';
        end if;

        select count(*) into v_pack_after
          from public.guardrail_rules g
         where g.tenant_id = v_p.tenant_id
           and g.compliance_pack_key is not null
           and g.active and g.retired_at is null;

        -- 2. THE KIT — its Book of Work watchers, its published SOP and its
        --    role guardrails. DELIBERATELY UNGUARDED. This is what makes the
        --    new employee an employee rather than a row, so a failure here must
        --    take the whole accept down: the sub-block below rolls the employee
        --    back and the card returns to the deck with the reason on it.
        --    Probe 13 forces exactly that and asserts no employee is left
        --    behind — the asymmetry with step 3 is a claim, so it is driven.
        v_kit := public.install_role_kit(v_de_id, v_arch);

        -- 3. THE SYSTEMS — additive, and therefore in their OWN nested block.
        --
        --    ⚠⚠ THIS NESTING IS LOAD-BEARING, and it is not a style choice.
        --    install_role_systems opens with
        --        IF NOT coalesce(can_admin_tenant_internal(<the DE's tenant>),
        --                        false) THEN RAISE EXCEPTION 'not permitted';
        --    and can_admin_tenant_internal admits service_role or
        --    tenant_owner/tenant_admin only. Un-nested, that refusal — and
        --    every other way this step can fail — would abort the hire and undo
        --    the kit as well, for a step the product has always treated as
        --    additive. apply_role_kit_to_employee wraps it exactly this way;
        --    hireApi.ts means to and cannot, because .rpc() resolves on a
        --    Postgres error and its catch is dead code.
        --
        --    ⚠ coalesce, because a SQL function returning NULL would otherwise
        --    put a null into a counter the screen prints as a number.
        begin
          v_systems := coalesce(public.install_role_systems(v_de_id, v_arch), 0);
        exception when others then
          v_systems := 0;
        end;

        -- WHAT THE SCREEN IS ALLOWED TO SAY. A SILENT ZERO IS THE DEFECT: the
        -- existing hire wizard prints "0 connected systems" identically for
        -- "this archetype has none" and "the systems step refused", and there
        -- is no way from the outside to tell which happened. These travel in
        -- the return payload AND the audit detail, from ONE object, so the two
        -- accounts cannot drift.
        --
        -- sop_snapshot_published is here because install_role_kit already
        -- reports it honestly (false for every SOP archetype — an SOP is
        -- compiled by de-work, never run by playbook-execute) while the card
        -- asserts comes_with_published_sop unconditionally. The accept should
        -- be able to contradict the card.
        v_counters := jsonb_build_object(
          'archetype_key',          v_arch,
          -- ⚠ THREE numbers, not one, for the reason systems_installed has a
          -- sentence of its own above: "0 new blocking rules" and "this
          -- workspace has no compliance rules at all" are opposite facts and
          -- read identically as a bare zero. in_force is what tells them apart,
          -- and packs_attached names WHICH controls, since a rule the customer
          -- cannot name is a rule they cannot consent to.
          'compliance_packs_attached', to_jsonb(coalesce(v_pack_keys, '{}'::text[])),
          'compliance_rules_created',  greatest(coalesce(v_pack_after, 0) - coalesce(v_pack_before, 0), 0),
          'compliance_rules_in_force', coalesce(v_pack_after, 0),
          'systems_installed',      v_systems,
          'watchers_created',       coalesce((v_kit ->> 'watchers_created')::integer, 0),
          'watchers_skipped',       coalesce((v_kit ->> 'watchers_skipped')::integer, 0),
          'guardrails_created',     coalesce((v_kit ->> 'guardrails_created')::integer, 0),
          'sop_playbook_id',        v_kit ->> 'sop_playbook_id',
          'sop_snapshot_published', coalesce((v_kit ->> 'sop_snapshot_published')::boolean, false));

        v_object_id := v_de_id;

      -- ---- guardrail — Path B, PATTERN-BEARING ONLY ----------------------
      -- The browser already added the rule through addGuardrailRule
      -- (src/lib/guardrailApi.ts) as the signed-in human under RLS. This
      -- stamps it. It does NOT insert: `authenticated` holds INSERT on
      -- guardrail_rules and guardrail_rules_tenant_write is the policy the
      -- human path depends on — an insert here runs as postgres, bypasses that
      -- policy entirely, and is the second creation engine the plan forbids.
      --
      -- THE FOUNDER'S RULING, 2026-08-15: patterns now, thresholds held. See
      -- this migration's header for the two measured reasons; the refusals
      -- below are written in words a business owner can read, because
      -- migration 740 puts them straight onto the card and leaves them there.
      when 'guardrail' then
        v_writer     := 'addGuardrailRule -> guardrail_rules (client, under RLS), stamped here';
        v_object_tbl := 'guardrail_rules';

        -- ⚠ btrim IS NOT .trim(), AND THE DIFFERENCE LEAVES A LIVE BLOCKING
        -- RULE THAT CAN NEVER BE STAMPED. One-argument `btrim` strips SPACES
        -- and nothing else — measured: length(btrim(E'\treturn|refund')) = 14
        -- against length('return|refund') = 13, and
        -- btrim(E'refund|chargeback\n') <> 'refund|chargeback'. The client gate
        -- (discoveryProposalPresentation.ts's `str`, and guardrailAcceptability
        -- through it) uses JS `.trim()`, which strips ALL whitespace. So on a
        -- payload the model filled as "refund|chargeback\n" — applyModelFill
        -- writes the model's bytes verbatim and `pattern` is on
        -- FILL_WHITELIST.guardrail — the browser creates the rule with the
        -- TRIMMED literal, this function compares it against the UNTRIMMED one,
        -- and the verbatim check below raises 'the rule that was created blocks
        -- X, but this recommendation showed X' about two identical-looking
        -- strings. The proposal reverts to pending, attempts increments, THE
        -- RULE STAYS LIVE AND BLOCKING, and every retry re-finds it and refuses
        -- again: a permanent stuck state plus an orphan workspace-wide rule.
        -- A lone "\t" was worse still — btrim left it, so it was length 1, one
        -- whitespace-split word, no trailing punctuation, and v_pattern_ok came
        -- back TRUE: the readable refusal was skipped and a business owner was
        -- shown "…add it as the signed-in person, then pass its id here
        -- (Path B)" permanently, through migration 740's last_error.
        --
        -- The character set is EXPLICIT rather than `\s`, so it cannot move
        -- with the database's ctype, and it is the set JS `.trim()` strips:
        -- ASCII whitespace plus the Unicode space separators, the two line
        -- separators and the BOM. Verified against `.trim()` on the same
        -- battery; kept in step by the vitest drift guard, which now pins the
        -- trim as well as the four predicate clauses behind it.
        v_pattern   := nullif(btrim(v_p.payload ->> 'pattern', E' \t\n\r\f\v\u00a0\u1680\u2000\u2001\u2002\u2003\u2004\u2005\u2006\u2007\u2008\u2009\u200a\u2028\u2029\u202f\u205f\u3000\ufeff'), '');
        v_threshold := nullif(btrim(coalesce(v_p.payload ->> 'threshold', ''), E' \t\n\r\f\v\u00a0\u1680\u2000\u2001\u2002\u2003\u2004\u2005\u2006\u2007\u2008\u2009\u200a\u2028\u2029\u202f\u205f\u3000\ufeff'), '');

        -- ⚠ THE THIRD COPY of looksLikeEnforceablePattern, and the header says
        -- why it has to be here rather than only in the two TypeScript copies:
        -- validatePayload lets a PROSE pattern sit beside a valid threshold and
        -- never nulls it out, the card correctly renders that payload as
        -- "threshold: N", and this function is the only thing that can write
        -- the reason onto the row. `pattern is not null` would have called that
        -- payload pattern-bearing and created a rule blocking on a sentence.
        --
        -- Mirrors the TS predicate line for line: non-empty, at most 120
        -- characters, does not end in sentence punctuation, at most five
        -- whitespace-separated words, and contains none of the prose words.
        -- `\y` is Postgres's word boundary — JS's `\b`.
        v_pattern_ok := v_pattern is not null
          and length(v_pattern) <= 120
          and v_pattern !~ '[.!?]$'
          and coalesce(array_length(regexp_split_to_array(v_pattern, '\s+'), 1), 0) <= 5
          and v_pattern !~* '\y(the|and|might|could|should|would|whatever|anything|something|appropriate|reasonable|seems|find|please|kindly|customer|customers)\y';

        if not v_pattern_ok then
          if v_threshold is not null then
            -- The number, said back to them, because the card showed exactly
            -- this and nothing about it says which unit it is in.
            raise exception 'this one is a bare number with no unit, so we have not switched it on: % could mean % dollars or % per cent, and those are two different rules in this workspace — one holds payments for approval, the other caps a discount. We would rather ask than guess by a factor of a hundred. Nothing was created, and it is still here waiting for you.',
              v_threshold, v_threshold, v_threshold;
          else
            raise exception 'this one has no phrase we can match on: "%" reads as a sentence rather than a literal, and a blocking rule only stops the exact words it is given. Nothing was created, and it is still here waiting for you.',
              coalesce(v_pattern, 'nothing');
          end if;
        end if;

        -- ⚠ THE CONSENTED LITERAL IS COMPILED AS A REGULAR EXPRESSION, AND
        -- NOTHING ON THE CARD SAYS SO. matchPattern
        -- (supabase/functions/_shared/guardrailMatch.ts:65-79) does
        -- `text.match(new RegExp(pattern, 'i'))` and only falls back to literal
        -- fragments when that compilation THROWS. Its own header rests the
        -- safety argument on an audit of 85 HAND-AUTHORED patterns, and money
        -- amounts and parentheticals are exactly what a "never say X" rule
        -- contains.
        --
        -- ⚠ CORRECTED. This paragraph, guardrailAcceptability's header in
        -- src/lib/discoveryProposalPresentation.ts and probe 15(e3)'s own
        -- finding all said this migration was "the FIRST path that lets a
        -- MODEL-authored literal reach that compiler". FALSE about the code,
        -- true only about the data: `approveProposal`
        -- (src/lib/governanceAiApi.ts) passes `governance_proposals.pattern` —
        -- a column the Workspace Assistant writes — straight into
        -- addGuardrailRule, and did so with NO screen of any kind: not this
        -- one, not the empty-alternative one, not even
        -- looksLikeEnforceablePattern. A human clicks Approve; the bytes are
        -- the model's. "refund|" through that door mutes every outbound message
        -- on all four enforcement paths exactly as it would through this one.
        -- `governance_proposals` holds 0 rows (measured 2026-08-17), so the
        -- door has never been used — which is why the sentence read as true.
        -- The client half of this migration therefore moves both screens onto
        -- `addGuardrailRule` itself, so a door added later gets them without
        -- anybody remembering to ask.
        --
        -- Replicated in node against the real matcher, all four passing
        -- looksLikeEnforceablePattern:
        --
        --   "$500 off"     on "we can do $500 off for you"  -> null, BLOCKS NOTHING
        --   "(free) month" on "have a (free) month"         -> null, BLOCKS NOTHING
        --   "3.5% fee"     on "our 3x5% fee applies"        -> matches, BLOCKS WIDER
        --   "refund|"      on "we will ship it tomorrow"    -> "", BLOCKS EVERYTHING
        --
        -- The last one is the worst and was not in the report: an empty
        -- alternative compiles to a regex that matches the empty string,
        -- matchPattern returns '' and findBlockingMatch tests `!== null`, so a
        -- single trailing "|" withholds EVERY outbound message on all four
        -- enforcement paths until someone finds the rule.
        --
        -- THE CHOICE, and it is a choice: SCREEN AT THE ACCEPTANCE GATE, do not
        -- touch the matcher. Changing matchPattern would change enforcement for
        -- the 85 live hand-authored rules — including the one that legitimately
        -- uses grouping — which is a different migration with a different
        -- argument. Screening here narrows only what a customer can be asked to
        -- consent to, and it narrows it to the shape where the compiled regex
        -- and a plain reading of the words agree: literal characters, with `|`
        -- between alternatives and something on both sides of every one. The
        -- card is then true as written; the alternative — leaving the gate open
        -- and rewriting the card to explain regex to a business owner — fails
        -- §11b, which is about predicting the block, not about disclosing that
        -- it is unpredictable. The same screen is in guardrailAcceptability
        -- (src/lib/discoveryProposalPresentation.ts), which is the gate the card
        -- copy and the accept writer both read, and the two are pinned against
        -- each other in tests/discovery-proposal-batching.test.ts.
        if v_pattern ~ '[\\^$.?*+(){}\[\]]' then
          raise exception 'we cannot switch this one on as written: "%" contains % — and a blocking rule is read as a search expression, so those characters mean something other than themselves and it would block something other than the words on the card. A phrase of plain words, with "|" between alternatives, is one we can promise. Nothing was created, and it is still here waiting for you.',
            v_pattern, regexp_replace(v_pattern, '[^\\^$.?*+(){}\[\]]', '', 'g');
        end if;
        if v_pattern ~ '(^\||\|\||\|$)' then
          raise exception 'we cannot switch this one on as written: "%" has a "|" with nothing beside it, and a rule written that way matches every message rather than these words — every answer this workspace sends would be withheld. Nothing was created, and it is still here waiting for you.',
            v_pattern;
        end if;

        if p_created_object_id is null then
          raise exception 'a guardrail proposal is accepted by creating the rule first: add it as the signed-in person, then pass its id here (Path B)';
        end if;

        -- The id a caller hands us is NOT its own authorisation. Read the WHOLE
        -- row back — every check below is a sentence printed on the card, and a
        -- promise nobody re-reads is a promise nobody keeps.
        select * into v_rule
          from public.guardrail_rules g
         where g.id = p_created_object_id
           and g.tenant_id = v_p.tenant_id;
        if v_rule.id is null then
          raise exception 'no guardrail rule % in this workspace — a created-object id is not its own authorisation', p_created_object_id;
        end if;

        -- blocked_phrase, of the NINE values guardrail_rules_rule_type_check
        -- admits (read live: blocked_topic, blocked_phrase,
        -- require_approval_over_cents, max_discount_pct, frustration_signal,
        -- require_computed_number, require_citation, spend_cap_daily_cents,
        -- spend_cap_monthly_cents). It is the one whose card promise is true
        -- end to end: loadBlockingRules asks guardrail_rules_for_de for
        -- ['blocked_phrase','blocked_topic'] and findBlockingMatch compiles
        -- `pattern`, so the string on the card is the string that blocks.
        if v_rule.rule_type is distinct from 'blocked_phrase' then
          raise exception 'the rule that was created is a % rule, not a blocked phrase — this recommendation was shown as words to block, and nothing else was agreed to', v_rule.rule_type;
        end if;

        -- ⚠ THE LITERAL, BYTE FOR BYTE. §11b: "the rule sentence AND its
        -- literal pattern, verbatim — you cannot consent to a block you cannot
        -- predict." The card rendered `matches: <payload.pattern>`; if the row
        -- carries anything else, the customer agreed to one block and got
        -- another, and no later reader could tell.
        if v_rule.pattern is distinct from v_pattern then
          raise exception 'the rule that was created blocks "%", but this recommendation showed "%" — a guardrail has to be the one that was agreed to, exactly', coalesce(v_rule.pattern, 'nothing'), v_pattern;
        end if;

        -- ⚠ AND IT HAS TO BE REMOVABLE. retire_guardrail_rule refuses a pack
        -- rule by name ("it belongs to a pack — detach the pack instead"), and
        -- trg_guard_compliance_guardrails blocks deactivating one. A discovery
        -- guardrail carrying a pack key would be a rule the customer accepted
        -- and then could not take off — the defect migration 747 has just
        -- finished fixing on the other side of this same table.
        if v_rule.compliance_pack_key is not null then
          raise exception 'the rule that was created belongs to the % compliance pack, and a pack rule cannot be taken off on its own — a guardrail you agreed to here has to be one you can remove here', v_rule.compliance_pack_key;
        end if;

        -- One arm, five conditions, because they are one promise: "anything
        -- matching this is blocked before it reaches a customer, FOR EVERY
        -- EMPLOYEE IN THIS WORKSPACE" (the card at
        -- discoveryProposalPresentation.ts:518 and :706, and the flash at
        -- DiscoveryProposalsPage.tsx:365, all say the second half out loud).
        --
        -- loadBlockingRules filters severity='blocking' and every reader filters
        -- `active`. ⚠ AND `scope` IS WHAT DECIDES WHO IT REACHES — NOT
        -- `applies_to`, which this arm used to test on its own. Measured live:
        -- `guardrail_rules_for_de`, the sole resolver behind loadBlockingRules
        -- and loadBlockingRulesForJudge and therefore behind all four
        -- enforcement paths, does not contain the string `applies_to` at all.
        --
        -- ⚠ CORRECTED 2026-08-17, AND THIS IS THE THIRD SITE IN THIS ONE FILE.
        -- These two lines said the resolver "admits `g.scope = 'workspace'`, or
        -- `g.scope = 'employee'` matched against the asking employee's id" — a
        -- TWO-ARM description of a FOUR-ARM predicate. The round before fixed
        -- the two other places that said the same thing and did not enumerate
        -- this one, which is the same class of error one level out. Read live
        -- from pg_get_functiondef, the scope predicate is:
        --         g.scope = 'workspace'
        --      or g.scope = 'employee'   and p_de_id is not null
        --                                and g.scope_ref = p_de_id::text
        --      or g.scope = 'department' and p_de_id is not null
        --                                and g.scope_ref = (that employee's department)
        --      or g.scope = 'playbook'   and p_playbook_def_id is not null
        --                                and g.scope_ref = p_playbook_def_id::text
        -- — so each of the three non-workspace arms ALSO needs its parameter to
        -- be non-null, which is why a department- or playbook-scoped rule can be
        -- enforced for a strictly narrower audience still.
        --
        -- Both columns default (workspace/all) so the ordinary create path lands
        -- right — but nothing here was reading the one that matters, and the
        -- client's crash-window reuse-find could hand this function an
        -- employee-scoped row on a pattern collision. In outsourcetel-hq there
        -- are 12 rows matching every filter that find applies except the
        -- pattern, all of them scope='employee'.
        if v_rule.severity is distinct from 'blocking'
           or v_rule.scope is distinct from 'workspace'
           or v_rule.applies_to is distinct from 'all'
           or not coalesce(v_rule.active, false)
           or v_rule.retired_at is not null then
          raise exception 'the rule that was created would not actually stop anything, or would not stop it for everyone — it is severity=%, scope=%, applies_to=%, active=%, retired=%. The card said this blocks the phrase for every employee in this workspace, so that is what has to exist; a rule scoped to one employee is enforced for that employee alone.',
            coalesce(v_rule.severity, 'null'), coalesce(v_rule.scope, 'null'),
            coalesce(v_rule.applies_to, 'null'),
            coalesce(v_rule.active::text, 'null'), coalesce(v_rule.retired_at::text, 'no');
        end if;

        -- What the screen and the audit line are allowed to say, from ONE
        -- object so they cannot drift. The PATTERN is in here deliberately: the
        -- row can be edited or retired afterwards and there is no version
        -- history anywhere else, so the literal the customer consented to has
        -- to outlive it — the same reasoning retire_guardrail_rule states in
        -- its own comment.
        v_counters := jsonb_build_object(
          'rule_type',           v_rule.rule_type,
          'pattern',             v_rule.pattern,
          'severity',            v_rule.severity,
          'applies_to',          v_rule.applies_to,
          'scope',               v_rule.scope,
          'compliance_pack_key', v_rule.compliance_pack_key,
          'threshold_held',      v_threshold);

        v_object_id := v_rule.id;

      -- ---- procedure — Path B, AND THE WRITER IS AN EDGE FUNCTION ---------
      -- The browser already drafted it through `draftPlaybookFromSop`
      -- (src/lib/playbookBuilderApi.ts) over the `playbook-draft` edge
      -- function, and then stamped the deterministic key and the agreed name
      -- onto the row it got back. This verifies and links it.
      --
      -- It does NOT draft: `net.http_post` returns a request id, the request is
      -- not dispatched until COMMIT and the reply arrives later in
      -- `net._http_response`, so a SQL function cannot call the drafter and read
      -- what it made. See this migration's header — that is a mechanical
      -- impossibility, not a preference, and it is a stronger reason for Path B
      -- than connector's or guardrail's.
      when 'procedure' then
        v_writer     := 'draftPlaybookFromSop -> playbook-draft edge function (service-role inside), key+name stamped by the browser under RLS, verified here';
        v_object_tbl := 'playbook_definitions';

        -- ⚠ THE SAME EXPLICIT WHITESPACE SET AS 751'S PATTERN TRIM, and for the
        -- same measured reason: one-argument `btrim` strips SPACES ONLY, while
        -- the client composes with JS `.trim()`, which strips all of it. Here
        -- the consequence is sharper than a mismatched literal — every one of
        -- these three fields goes into `v_sop`, and `v_sop` is compared BYTE FOR
        -- BYTE against what the drafter was given. A single stray tab on either
        -- side and the provenance check refuses a draft that is perfectly
        -- correct, permanently, while the draft sits in the workspace.
        v_proc_name := nullif(btrim(v_p.payload ->> 'name',    E' \t\n\r\f\v\u00a0\u1680\u2000\u2001\u2002\u2003\u2004\u2005\u2006\u2007\u2008\u2009\u200a\u2028\u2029\u202f\u205f\u3000\ufeff'), '');
        v_proc_trig := nullif(btrim(v_p.payload ->> 'trigger', E' \t\n\r\f\v\u00a0\u1680\u2000\u2001\u2002\u2003\u2004\u2005\u2006\u2007\u2008\u2009\u200a\u2028\u2029\u202f\u205f\u3000\ufeff'), '');
        -- `jsonb_typeof` first: `jsonb_array_elements_text` RAISES on a non-array,
        -- and a payload whose `steps` is a bare string would then reach the
        -- customer as `22023 cannot extract elements from a scalar` — a sentence
        -- about a jsonb function, written onto the card by 740's last_error and
        -- still there tomorrow. Empty and whitespace-only entries are dropped
        -- rather than kept, exactly as the client's composer drops them.
        v_proc_steps := case when jsonb_typeof(v_p.payload -> 'steps') = 'array' then
            array(select btrim(s, E' \t\n\r\f\v\u00a0\u1680\u2000\u2001\u2002\u2003\u2004\u2005\u2006\u2007\u2008\u2009\u200a\u2028\u2029\u202f\u205f\u3000\ufeff')
                    from jsonb_array_elements_text(v_p.payload -> 'steps') s
                   where nullif(btrim(s, E' \t\n\r\f\v\u00a0\u1680\u2000\u2001\u2002\u2003\u2004\u2005\u2006\u2007\u2008\u2009\u200a\u2028\u2029\u202f\u205f\u3000\ufeff'), '') is not null)
          else '{}'::text[] end;

        -- The three literals validatePayload already requires at emission, read
        -- again HERE because this function is the only thing that can write a
        -- reason onto the row — and because a row can reach this line from
        -- before that validator existed, or from an operator insert.
        if v_proc_name is null then
          raise exception 'this recommendation does not say what the procedure is called, so there is nothing to draft it as. Nothing was created, and it is still here waiting for you.';
        end if;
        -- THE PRINTED FORM, computed once, used by every message below and by
        -- nothing else. See its declaration for why the compared value stays
        -- whole and why the cap is 140.
        v_proc_label := case when length(v_proc_name) > 140
                             then left(v_proc_name, 140) || '…' else v_proc_name end;
        if v_proc_trig is null then
          raise exception 'this recommendation does not say when "%" should run, and a procedure nobody can say the starting point for is not one anybody can review. Nothing was created, and it is still here waiting for you.', v_proc_label;
        end if;
        if coalesce(array_length(v_proc_steps, 1), 0) = 0 then
          raise exception 'this recommendation has no steps written down for "%", so there is nothing to draft from. Nothing was created, and it is still here waiting for you.', v_proc_label;
        end if;

        -- ⚠ THE CONSENTED LITERAL, COMPOSED. This is the exact string the
        -- browser sends to the drafter, and the `playbook_studies` check at the
        -- bottom of this branch compares it byte for byte against what the
        -- drafter recorded it was given. It is the procedure's answer to §11b:
        -- the guardrail's consented literal is its pattern, and this one's is
        -- the name, the trigger and the steps the card showed.
        --
        -- Kept deliberately dull — three fixed labels, one bullet per step, no
        -- conditional shape — because it exists twice (here and
        -- `sopTextForProcedure` in src/lib/discoveryProposalPresentation.ts) and
        -- every branch in it is a way for the two to disagree. The vitest drift
        -- guard pins this composer's shape and its trim set against the
        -- TypeScript one.
        v_sop := v_proc_name || E'\n\n'
              || 'Runs when: ' || v_proc_trig || E'\n\n'
              || 'Steps:' || E'\n'
              || array_to_string(array(select '- ' || x from unnest(v_proc_steps) x), E'\n');

        -- The drafter's own floor, restated so the refusal is a sentence rather
        -- than an HTTP 400 the browser has to translate:
        --   playbook-draft/index.ts:364
        --   if (!recompileDefId && sopText.length < 40) return json({ error: 'sop_text required …' }, 400)
        -- The client checks it first and drafts nothing, so reaching this line
        -- means the client's copy drifted looser — the SAFE direction, and this
        -- is what catches it.
        if length(v_sop) < 40 then
          raise exception 'there is not enough written down here to draft from — what was recorded for "%" comes to % characters, and the drafter needs at least 40 before it can turn a description into steps. A sentence or two more about what happens, and when, is enough. Nothing was created, and it is still here waiting for you.',
            v_proc_label, length(v_sop);
        end if;

        -- ⚠ THE DETERMINISTIC KEY. One proposal, one procedure. The browser
        -- stamps this onto the row the drafter made, UNIQUE (tenant_id, key)
        -- makes a second one impossible, and refusing any other key below is
        -- what makes a retry re-use the first draft rather than mint a twin.
        -- The dashes come out so the key stays inside the [a-z0-9_] shape every
        -- other key in this table uses.
        v_pb_key := 'discovery_' || replace(v_p.id::text, '-', '');

        if p_created_object_id is null then
          raise exception 'a procedure is drafted first and linked second: nothing was drafted for "%", so there is nothing to link here. Nothing was created, and it is still here waiting for you.', v_proc_label;
        end if;

        -- The id a caller hands us is NOT its own authorisation. Read the WHOLE
        -- row back — every check below is a sentence printed on the card.
        select * into v_def
          from public.playbook_definitions d
         where d.id = p_created_object_id
           and d.tenant_id = v_p.tenant_id;
        if v_def.id is null then
          raise exception 'no draft procedure % in this workspace — a created-object id is not its own authorisation', p_created_object_id;
        end if;
        -- The row's own name is capped for printing too, and for the same
        -- reason: the browser writes it and nothing bounds what it writes.
        v_def_label := case when length(v_def.name) > 140
                            then left(v_def.name, 140) || '…' else v_def.name end;

        -- ⚠ THE ANTI-DUPLICATION PIN. Everything else in this branch is about
        -- whether the draft is the right SHAPE; this one is about whether it is
        -- THE one this recommendation drafted. A draft under any other key is
        -- either somebody else's procedure or a second copy of this one, and
        -- stamping it would make "accept twice, get one procedure" false.
        if v_def.key is distinct from v_pb_key then
          raise exception 'the draft that came back is filed as "%", and the draft for this recommendation is filed as "%" — accepting this would have left you with two copies of the same procedure instead of re-using the first, so nothing was linked. It is still here waiting for you.',
            coalesce(v_def.key, 'nothing'), v_pb_key;
        end if;

        -- ⚠ THE NAME, BYTE FOR BYTE, AND THE DRAFTER DOES NOT DO THIS ON ITS
        -- OWN. playbook-draft:622 takes `compiled.name` — the COMPILING model's
        -- own title — and only falls back to what it was asked for. The card
        -- read `Draft the "<name>" procedure`; a draft that came out called
        -- something else is a procedure the customer did not agree to by the one
        -- handle they were given for it. The browser re-stamps the name in the
        -- same update as the key; this refuses a row where it did not take.
        if v_def.name is distinct from v_proc_name then
          raise exception 'the draft that came back is called "%", but this recommendation was for "%" — a procedure has to be the one that was agreed to, by the name it was agreed under. Nothing was linked, and it is still here waiting for you.',
            coalesce(v_def_label, 'nothing'), v_proc_label;
        end if;

        -- ⚠ THE CARD'S CENTRAL PROMISE: "This becomes a draft — nothing runs
        -- until you publish it." Every path that RUNS a definition filters on
        -- `published` — eight gates across five callers, enumerated in this
        -- migration's header (playbook-execute:2428, :655 and :2952,
        -- de-work:215, de-mission:108, dispatch_due_triggers twice, and
        -- emit_tenant_event) — so
        -- `draft` is not a detail of this row — it is the entire reason this
        -- kind can be accepted at all before the customer has read a single
        -- step. An archived row is refused by the same arm, which is what makes
        -- probe 16's removal drive mean something.
        if v_def.status is distinct from 'draft' then
          raise exception 'the draft that came back is %, not a draft. The card said this becomes a draft and runs nothing until you publish it, so a draft is what has to exist. Nothing was linked, and it is still here waiting for you.',
            coalesce(v_def.status, 'null');
        end if;

        -- ⚠ TWO ENGINES, ONE TABLE. `kind` is DERIVED from the steps by trigger
        -- (playbook_definitions_set_kind -> playbook_definition_kind, which
        -- answers 'sop' iff any step carries kind='use_tool'), so it cannot
        -- drift from what the row holds. An 'sop' row is compiled into work
        -- items by de-work, not run by playbook-execute; the card describes the
        -- one you publish and run.
        if v_def.kind is distinct from 'procedure' then
          raise exception 'the draft that came back is a standing instruction rather than a procedure that runs — a different part of the workforce reads that kind, and it is not what this card described. Nothing was linked, and it is still here waiting for you.';
        end if;

        -- ⚠ AND IT IS NOBODY'S WORK YET. de-work and de-mission both select on
        -- `de_id`, so a draft already assigned to an employee is one publish away
        -- from becoming that employee's queue. The card offered a draft for the
        -- customer to read, not work handed to somebody.
        if v_def.de_id is not null then
          raise exception 'the draft that came back is already assigned to one of your digital employees. This card offered you a draft to read over first, not work handed to somebody, so that is not what was agreed to. Nothing was linked, and it is still here waiting for you.';
        end if;

        -- An empty draft is nothing a person can review, approve or decline —
        -- validatePayload's own words for refusing an empty `steps` at emission.
        if coalesce(case when jsonb_typeof(v_def.steps) = 'array'
                         then jsonb_array_length(v_def.steps) else 0 end, 0) = 0 then
          raise exception 'the draft for "%" came back with no steps in it, so there is nothing for you to read over or publish. Nothing was linked, and it is still here waiting for you.', v_proc_label;
        end if;

        -- ⚠ PROVENANCE, AND WITHOUT IT THE TWO CHECKS ABOVE ARE WORTHLESS.
        -- `key` and `name` are both written by the BROWSER. A function that
        -- verified only those would be verifying the caller's own claims — "a
        -- created-object id is not its own authorisation" turned into "an id
        -- plus two strings the caller chose is". `playbook_studies.sop_text` is
        -- written by the drafter's own service-role client from the text it was
        -- handed (playbook-draft:632, upserted on `definition_id`, which carries
        -- a UNIQUE index), and `authenticated` holds SELECT and nothing else on
        -- that table — so it is the one field on this path the browser cannot
        -- choose. Byte-identical to the composed text, or this draft was not
        -- made from what the customer described.
        --
        -- ⚠ AND THE HONEST LIMIT: playbook-draft does not check that upsert's
        -- error (`await admin.from('playbook_studies').upsert(…)`, result
        -- discarded), so a draft CAN come back from a 200 with no study row.
        -- That would make this arm unsatisfiable and the proposal permanently
        -- stuck — the milder version of 751's stuck guardrail, with an inert
        -- draft instead of a live blocking rule. It is stated rather than fixed,
        -- and the evidence that it is rare is a DATE, not a key shape: six live
        -- rows carry the `<slug>_<random6>` shape and only three carry a study,
        -- but the other three predate playbook-draft's existence entirely —
        -- connector-hub's `dt_draft_playbook` mints the same shape and writes no
        -- study. Of the rows created since the study writer shipped, 3 of 3
        -- carry one, and the unique index the upsert needs exists. The header
        -- has the measurement. The refusal below says what to do about the draft
        -- either way, because a customer should never have to infer that from
        -- silence.
        select exists (
          select 1 from public.playbook_studies s
           where s.definition_id = v_def.id
             and s.tenant_id     = v_p.tenant_id
             and s.sop_text      = v_sop
        ) into v_study_ok;
        if not coalesce(v_study_ok, false) then
          raise exception 'we could not confirm that this draft was written from what you described for "%", so we have not linked it to this recommendation. The draft is on your Playbooks screen — it is a draft, so it runs nothing — and you can read it there and archive it if it is not what you meant. This recommendation is still here waiting for you.', v_proc_label;
        end if;

        -- What the screen and the audit line are allowed to say, from ONE object
        -- so they cannot drift. The composed SOP TEXT is deliberately NOT in
        -- here — it is already in `payload`, which the audit detail carries
        -- whole and verbatim — but its length is, because "we drafted from 40
        -- characters" and "we drafted from 4,000" are different facts about the
        -- same accept. `steps_drafted` is the drafter's count, not the payload's:
        -- the customer described N things and the compiler emitted M, and a card
        -- that showed only N would hide the compile.
        v_counters := jsonb_build_object(
          'playbook_key',      v_def.key,
          'playbook_name',     v_def.name,
          'playbook_status',   v_def.status,
          'playbook_kind',     v_def.kind,
          'assigned_to_de',    v_def.de_id,
          'steps_described',   coalesce(array_length(v_proc_steps, 1), 0),
          'steps_drafted',     case when jsonb_typeof(v_def.steps) = 'array'
                                    then jsonb_array_length(v_def.steps) else 0 end,
          'sop_chars',         length(v_sop),
          'trigger_described', v_proc_trig);

        v_object_id := v_def.id;

      -- ---- trust_rule — PATH A, AND IT DELIBERATELY WRITES NO LIMIT --------
      -- THE ONLY PROPOSAL THAT REMOVES A HUMAN FROM A LOOP (§11b), and the one
      -- this function is allowed to make the LEAST of. Everything the other
      -- four kinds accept ADDS a capability; this one subtracts oversight. So
      -- the accept does the smallest true thing: it opens the trust setting the
      -- customer's sentence was about, at level 0, where it already effectively
      -- sat — and records the limit they stated as CONSENT DATA rather than as
      -- configuration.
      --
      -- PATH A, and the argument is NOT "SQL can reach the writer". Path B
      -- exists in 741/751/752 because those kinds' ordinary writers are a
      -- PostgREST insert under RLS (connector, guardrail) or an edge function
      -- (procedure): duplicating them inside a SECURITY DEFINER body would
      -- bypass an RLS policy the human path depends on, which is contract
      -- §8.3's second creation engine. HERE THERE IS NO SUCH POLICY TO BYPASS.
      -- Measured live: `authenticated` holds SELECT on public.trust_policies
      -- and nothing else — no INSERT, no UPDATE, no DELETE — so there is no
      -- PostgREST write path at all and no browser half to preserve. The
      -- ordinary writer IS a SECURITY DEFINER RPC (`seed_de_trust_policy`),
      -- calling it from here is calling THE engine from one more place, and it
      -- re-checks the caller itself: auth.uid() and auth_tenant_id() read the
      -- request GUC, which SECURITY DEFINER does not change, so its own bar
      -- (owner/admin/manager plus can_access_de) fires against the real human
      -- exactly as it does from the browser. 746's employee branch already
      -- rests on the same fact.
      --
      -- ⚠ AND PATH A REMOVES THIS KIND'S VERSION OF THE 751/752 TRAP. Those two
      -- have an asymmetric drift invariant — the client must be at least as
      -- strict as this function, always — because the browser has already
      -- created a live blocking rule (751) or an inert draft (752) by the time
      -- the refusal lands. Here the browser writes NOTHING before calling, so
      -- BOTH drift directions are safe: a stricter SQL copy refuses a card and
      -- leaves the workspace exactly as it was. That is why the THREE checks
      -- below that the client does not have (a negative cap; a confidence cap
      -- above 100; a capability that is not on this employee's surface) can be
      -- added without the stuck-state risk 752's header spends four paragraphs
      -- on.
      when 'trust_rule' then
        v_writer     := 'seed_de_trust_policy, inside decide_discovery_proposal — NO ladder is written and no dial is applied, so the stated limit is recorded and nothing this employee does changes';
        v_object_tbl := 'trust_policies';

        -- ⚠ THE SAME EXPLICIT WHITESPACE SET 751 ESTABLISHED. One-argument
        -- `btrim` strips SPACES ONLY; the client's `str()` uses JS `.trim()`,
        -- which strips all of it. `de_ref` and `action_category` are both
        -- COMPARED against other stored values below, and `cap` is normalised
        -- by a regex whose anchors a stray tab would defeat.
        v_tr_ref     := nullif(btrim(v_p.payload ->> 'de_ref',          E' \t\n\r\f\v\u00a0\u1680\u2000\u2001\u2002\u2003\u2004\u2005\u2006\u2007\u2008\u2009\u200a\u2028\u2029\u202f\u205f\u3000\ufeff'), '');
        v_tr_cat     := nullif(btrim(v_p.payload ->> 'action_category', E' \t\n\r\f\v\u00a0\u1680\u2000\u2001\u2002\u2003\u2004\u2005\u2006\u2007\u2008\u2009\u200a\u2028\u2029\u202f\u205f\u3000\ufeff'), '');
        v_tr_cap_raw := nullif(btrim(coalesce(v_p.payload ->> 'cap', ''), E' \t\n\r\f\v\u00a0\u1680\u2000\u2001\u2002\u2003\u2004\u2005\u2006\u2007\u2008\u2009\u200a\u2028\u2029\u202f\u205f\u3000\ufeff'), '');
        v_tr_above   := nullif(btrim(coalesce(v_p.payload ->> 'above_cap', ''), E' \t\n\r\f\v\u00a0\u1680\u2000\u2001\u2002\u2003\u2004\u2005\u2006\u2007\u2008\u2009\u200a\u2028\u2029\u202f\u205f\u3000\ufeff'), '');

        if v_tr_ref is null then
          raise exception 'this recommendation does not say which of your digital employees it is about, and a limit that names nobody is not something anyone can agree to. Nothing was changed, and it is still here waiting for you.';
        end if;
        if v_tr_cat is null then
          raise exception 'this recommendation does not say what kind of work the limit is for, so there is nothing to record it against. Nothing was changed, and it is still here waiting for you.';
        end if;

        -- ⚠ THE CAP, AND `isNumericLiteral` MIRRORED CHARACTER FOR CHARACTER.
        -- supabase/functions/_shared/discoveryProposals.ts:485 strips a LEADING
        -- '$', ALL commas and a TRAILING '%' and then tests
        -- /^-?\d+(\.\d+)?$/. Restated here because a payload can reach this
        -- line from before that validator existed, or from an operator insert,
        -- and because this function is the only thing that can write a reason
        -- onto the row (migration 740).
        --
        -- ⚠ 0 IS A VALID CAP and this is deliberately not a truthiness test —
        -- that module's own comment says so. A NEGATIVE cap is refused, and
        -- that check is STRICTER THAN THE CLIENT'S: validatePayload admits
        -- "-500". On Path A a stricter server is safe (see the branch header),
        -- and "act on its own up to minus five hundred dollars" is not a
        -- sentence a person can consent to.
        v_tr_cap_n := regexp_replace(
                        regexp_replace(
                          regexp_replace(coalesce(v_tr_cap_raw, ''), '^\$', ''),
                          ',', '', 'g'),
                        '%$', '');
        if v_tr_cap_raw is null or v_tr_cap_n !~ '^-?\d+(\.\d+)?$' then
          raise exception 'this recommendation does not carry a limit we can read — what was recorded was "%". This is the one recommendation that would let an employee act without asking you, so a number is the whole of the decision and we will not guess one. Nothing was changed, and it is still here waiting for you.',
            coalesce(v_tr_cap_raw, 'nothing');
        end if;
        if v_tr_cap_n::numeric < 0 then
          raise exception 'the limit on this recommendation is %, and a limit below zero is not something we can write down as an agreement. Nothing was changed, and it is still here waiting for you.',
            v_tr_cap_n;
        end if;

        -- WHICH UNIT THE NUMBER IS IN, taken from the SAME split
        -- set_trust_ladder uses (`v_uses_conf := action_category in
        -- ('answer_dock','answer_widget')`, read live) and from the client's
        -- own formatCap, which reads that split too. It is recorded beside the
        -- number rather than folded into it: a bare cap with no unit is exactly
        -- what the founder refused for guardrail thresholds, and a later reader
        -- of this audit row must not have to re-derive it.
        v_tr_unit := case when v_tr_cat in ('answer_dock', 'answer_widget')
                          then 'confidence' else 'amount' end;

        -- ⚠ AND A CONFIDENCE CAP IS RANGE-CHECKED. AN AMOUNT IS NOT, AND THE
        -- ASYMMETRY IS THE POINT. For 'amount' there is no bound to check
        -- against — the payload carries no currency and no scale, which is the
        -- whole reason no ladder is written — so any non-negative number is a
        -- number a person could have meant. For 'confidence' there IS a bound,
        -- and it is not invented here: `validate_trust_ladder`, the one
        -- validator every ladder in this database passes through, requires
        -- min_confidence to be between 0 and 100 (read live). Restating it here
        -- is the same move this branch already makes for `isNumericLiteral` and
        -- for set_trust_ladder's unit split.
        --
        -- Without it, the accept would record stated_cap "500" beside
        -- stated_cap_unit "confidence": consent to 500% confidence. INERT TODAY,
        -- and that is exactly the reason it matters — `stated_cap` is written
        -- nowhere else, and the header's whole provenance argument is that a
        -- FUTURE enforcement layer is meant to find it and read it. "Act on its
        -- own above 500% confidence" is not a sentence a person can agree to,
        -- which is the argument the negative-amount refusal above already makes.
        --
        -- ⚠ STRICTER THAN THE CLIENT, a third time, and safe for the same Path A
        -- reason: formatCap renders "500% confidence" without complaint and
        -- validatePayload has no range at all, but nothing is written before
        -- this line, so a refusal leaves the workspace exactly as it was.
        --
        -- ⚠ ONLY THE RANGE, NOT THE WHOLE-NUMBER RULE. validate_trust_ladder
        -- also demands an integer; this deliberately does not, because "60.5%
        -- confidence" is a thing a person can mean and consent to, and refusing
        -- it would be refusing a coherent answer to protect a field this accept
        -- does not write. The range is checked because only the range makes the
        -- recorded sentence impossible.
        -- ⚠ Upper bound only: a cap below zero was already refused above, in ANY
        -- unit, so a `< 0` arm here could never fire and would be one more
        -- comparison that cannot fail.
        if v_tr_unit = 'confidence' and v_tr_cap_n::numeric > 100 then
          raise exception 'this recommendation records a confidence limit of %, and confidence runs from 0 to 100 — so there is no setting this could ever mean, and we will not write it down as something you agreed to. Nothing was changed, and it is still here waiting for you.',
            v_tr_cap_n;
        end if;

        -- ⚠ THE EMPLOYEE IS RESOLVED FROM THE SESSION, NEVER FROM THE CALLER.
        -- Every other Path B kind has to answer "an id is not its own
        -- authorisation" by reading the row back. This branch answers it by
        -- construction: there is no id to hand us. `de_ref` is
        -- "archetype:<key>", and the employee it means is the one an ACCEPTED
        -- employee proposal IN THIS SAME SESSION created. §11b requirement 4 —
        -- "a trust rule cannot exist without the employee it governs" — is
        -- therefore enforced here in SQL, not only by the browser's
        -- trustRuleBlockReason.
        if v_tr_ref !~ '^archetype:[a-z0-9_]+$' then
          raise exception 'this recommendation points at "%" rather than at one of the employees it recommended, so there is nobody to record a limit for. Nothing was changed, and it is still here waiting for you.',
            v_tr_ref;
        end if;
        v_tr_arch := substring(v_tr_ref from 11);

        select s.created_object_id into v_tr_de
          from public.discovery_proposals s
         where s.session_id = v_p.session_id
           and s.tenant_id  = v_p.tenant_id
           and s.kind       = 'employee'
           and s.state      = 'accepted'
           and s.created_object_id is not null
           and nullif(btrim(s.payload ->> 'archetype_key', E' \t\n\r\f\v\u00a0\u1680\u2000\u2001\u2002\u2003\u2004\u2005\u2006\u2007\u2008\u2009\u200a\u2028\u2029\u202f\u205f\u3000\ufeff'), '') = v_tr_arch
         order by s.decided_at desc nulls last
         limit 1;
        if v_tr_de is null then
          raise exception 'we have not set up the employee this limit is for yet. Say yes to that recommendation first and this one will be ready straight after — a limit on somebody who does not exist is not something we can record. Nothing was changed, and it is still here waiting for you.';
        end if;

        -- ...and that id, which came off a SIBLING ROW rather than off this
        -- decision, still has to be a real employee in THIS workspace. The
        -- sibling's `created_object_id` is written by this same function, but a
        -- row can be edited by anything holding UPDATE, so it is re-read here.
        -- ⚠ The Workspace Assistant exclusion is a FILTER, never a value read:
        -- this select cannot return an assistant row, which is the standing
        -- instruction stated as a predicate rather than as a promise.
        select d.name into v_tr_emp
          from public.digital_employees d
         where d.id = v_tr_de
           and d.tenant_id = v_p.tenant_id
           and coalesce(d.is_workforce_assistant, false) = false;
        if v_tr_emp is null then
          raise exception 'the employee this limit was for is not one of yours any more, so there is nothing to record it against. Nothing was changed, and it is still here waiting for you.';
        end if;

        -- PATH A'S OWN SHAPE, said the way 752 says Path B's. There is nothing
        -- for a browser to have created first — it holds SELECT on this table
        -- and nothing else — so being handed an object id means something
        -- upstream believes this kind works the other way round.
        if p_created_object_id is not null then
          raise exception 'a trust limit is recorded by this workspace itself, not created first and linked after, so there was nothing to link. Nothing was changed, and it is still here waiting for you.';
        end if;

        -- ⚠⚠ THE INERTNESS PIN, AND IT IS ASKED OF THIS ROW RATHER THAN OF THE
        -- PLATFORM. The card says nothing changes today. That sentence is true
        -- because this employee is at level 0 for this capability, where
        -- `trust_ladder_settings` returns {enabled:false} before it even looks
        -- at a ladder — NOT because "no policy anywhere is above level 0",
        -- which is a fact about the 90 rows that exist today and would stop
        -- being true the first time anybody approves a promotion.
        --
        -- So the row is read FIRST, and an already-promoted policy is REFUSED.
        -- Accepting one would mean re-opening a setting on an employee that has
        -- already earned autonomy here, which is a different decision with a
        -- different blast radius from the one the card described.
        select * into v_tr_pol
          from public.trust_policies t
         where t.tenant_id       = v_p.tenant_id
           and t.de_id           = v_tr_de
           and t.action_category = v_tr_cat
           and t.source_category is null;

        if v_tr_pol.id is not null and coalesce(v_tr_pol.current_level, 0) > 0 then
          raise exception '% has already earned some independence on this kind of work — it is at level % of %. This recommendation was written as "nothing changes today", and on an employee that is already acting on its own it would not be, so we have not touched it. You can see and change what % is allowed to do on its own under its Trust settings. Nothing was changed, and this is still here waiting for you.',
            v_tr_emp, v_tr_pol.current_level, coalesce(v_tr_pol.max_level, 3), v_tr_emp;
        end if;

        -- ...and the same question about the OTHER half of the pair. A policy
        -- that already carries a ladder has had somebody set what each level
        -- means, deliberately, through set_trust_ladder — the one door. Opening
        -- this card on top of that would put a number in the audit trail beside
        -- a configuration nobody here wrote, and a later reader could not tell
        -- which of the two the customer agreed to.
        if v_tr_pol.id is not null and v_tr_pol.ladder is not null then
          raise exception 'somebody has already set out what each level of trust means for % on this kind of work, and this recommendation would sit beside that without changing it — which would leave two different limits recorded and no way to tell which one you meant. Have a look under %''s Trust settings and set the limit there instead. Nothing was changed, and this is still here waiting for you.',
            v_tr_emp, v_tr_emp;
        end if;

        -- OPEN THE SETTING, THROUGH THE ORDINARY WRITER. seed_de_trust_policy
        -- creates the row at level 0 and is idempotent on
        -- (tenant, action_category, coalesce(source_category,''),
        -- coalesce(de_id::text,'')) — the live unique index — so a re-run finds
        -- the row rather than making a second one.
        --
        -- ⚠ ITS OWN BAR REFUSES A CAPABILITY THAT IS NOT REAL FOR THIS
        -- EMPLOYEE: `de_trust_surface_candidates` decides what an employee can
        -- even be dialled on, and an `action:<category>` needs a CONNECTED
        -- connector behind it. That refusal is checked here first so the
        -- customer reads a sentence instead of a function's internal message —
        -- the same reason 752 restates playbook-draft's 40-character floor.
        -- ⚠ STRICTER THAN THE CLIENT AGAIN, and safe for the same Path A
        -- reason: validatePayload only checks the category against the live
        -- NAMESPACE (the distinct values in trust_policies), which is a
        -- workspace-wide fact and says nothing about THIS employee.
        if v_tr_pol.id is null then
          if not exists (
            select 1 from public.de_trust_surface_candidates(v_p.tenant_id, v_tr_de) c
             where c.capability_key = v_tr_cat
               and coalesce(c.dialable, false)
          ) then
            raise exception 'this workspace cannot yet let % work on its own on this — "%" either is not something % does, or it needs a system connected before it can be dialled at all. Connect that system, or set the limit under %''s Trust settings once it appears there. Nothing was changed, and this is still here waiting for you.',
              v_tr_emp, v_tr_cat, v_tr_emp, v_tr_emp;
          end if;

          -- ⚠ p_display_name IS DELIBERATELY NULL. A marker written into a
          -- customer-facing label would be a SECOND, WEAKER copy of provenance
          -- — editable by anyone with the ladder editor, and silent about who
          -- agreed or when. The record that this limit came from an interview
          -- is the ACCEPTED PROPOSAL POINTING AT THIS ROW (created_object_id)
          -- plus its audit event, which carry the whole payload, the session,
          -- the source dimension and the person. See the header.
          perform public.seed_de_trust_policy(v_tr_de, v_tr_cat, null);
          v_tr_seeded := true;

          select * into v_tr_pol
            from public.trust_policies t
           where t.tenant_id       = v_p.tenant_id
             and t.de_id           = v_tr_de
             and t.action_category = v_tr_cat
             and t.source_category is null;
        end if;

        -- READ BACK AND RE-CHECK EVERY PROMISE, exactly as the Path B kinds do
        -- with the row the browser made. A writer nobody re-reads is a writer
        -- nobody keeps.
        if v_tr_pol.id is null then
          raise exception 'we could not open a trust setting for % on this kind of work, so nothing was recorded. Nothing was changed, and this is still here waiting for you.',
            v_tr_emp;
        end if;
        if v_tr_pol.tenant_id is distinct from v_p.tenant_id
           or v_tr_pol.de_id is distinct from v_tr_de
           or v_tr_pol.action_category is distinct from v_tr_cat
           or v_tr_pol.source_category is not null then
          raise exception 'the trust setting that came back is not the one this recommendation was about (it is for a different employee, a different kind of work, or a different workspace), so nothing was recorded. Nothing was changed, and this is still here waiting for you.';
        end if;

        -- ⚠ THE CARD'S CENTRAL PROMISE, RE-ASSERTED AGAINST THE ROW THAT NOW
        -- EXISTS. Level 0 and no ladder together are the whole of "nothing
        -- changes today":
        --   · trust_ladder_settings(policy, 0) returns {enabled:false} before
        --     it reads the ladder at all, so level 0 enforces nothing;
        --   · a NULL ladder means a future promotion falls back to
        --     trust_level_settings — the built-in defaults — so this accept
        --     cannot change what level 1 will mean either. THE INTERVIEW
        --     CANNOT MOVE A DIAL IT DID NOT SET.
        -- Probe 17 drives both, and inverts both.
        if coalesce(v_tr_pol.current_level, 0) <> 0
           or coalesce(v_tr_pol.baseline_level, 0) <> 0
           or v_tr_pol.ladder is not null then
          raise exception 'the trust setting for % came back at level % with %, and this recommendation was recorded on the promise that nothing changes today. Nothing was recorded, and this is still here waiting for you.',
            v_tr_emp, coalesce(v_tr_pol.current_level, 0),
            case when v_tr_pol.ladder is null then 'no limits set' else 'limits already set on it' end;
        end if;
        if coalesce(v_tr_pol.status, '') is distinct from 'active' then
          raise exception 'the trust setting for % is %, not active, so a limit recorded against it would not be looked at even when you do decide to use it. Nothing was recorded, and this is still here waiting for you.',
            v_tr_emp, coalesce(v_tr_pol.status, 'in an unknown state');
        end if;

        -- WHAT IS ENFORCED FOR THIS EXACT SCOPE RIGHT NOW, counted rather than
        -- claimed. `de_autonomy` is the table the four enforcement paths read
        -- through resolve_de_autonomy, and `trust_apply_level` is the only
        -- thing that writes it from a ladder. This number travels into the
        -- return payload and the audit detail so "nothing changes today" is
        -- checkable against the ledger rather than believed.
        select count(*) into v_tr_dials
          from public.de_autonomy a
         where a.tenant_id      = v_p.tenant_id
           and a.de_id          = v_tr_de
           and a.action_type    = v_tr_cat
           and a.source_category is null;

        -- What the screen and the audit line are allowed to say, from ONE
        -- object so the two cannot drift. The STATED CAP IS IN HERE, with its
        -- unit beside it, because it is the thing the customer agreed to and it
        -- is written nowhere else that a future enforcement layer could find:
        -- the policy row deliberately does not carry it. `ladder_written` and
        -- `enforces_today` are stated as facts rather than left to be inferred
        -- from an absence.
        v_counters := jsonb_build_object(
          'policy_id',           v_tr_pol.id,
          'action_category',     v_tr_pol.action_category,
          'de_id',               v_tr_de,
          'employee_name',       v_tr_emp,
          'current_level',       coalesce(v_tr_pol.current_level, 0),
          'max_level',           coalesce(v_tr_pol.max_level, 3),
          'policy_opened_here',  v_tr_seeded,
          'stated_cap',          v_tr_cap_n,
          'stated_cap_unit',     v_tr_unit,
          'above_cap',           v_tr_above,
          'ladder_written',      false,
          'enforced_dials_for_this_scope', coalesce(v_tr_dials, 0),
          'enforces_today',      false);

        v_object_id := v_tr_pol.id;

      -- ---- conversation_type — Path B, and the LAST kind ------------------
      -- The browser already inserted the triage rule as the signed-in human
      -- under RLS (`authenticated` holds INSERT/UPDATE/DELETE/SELECT on
      -- support_triage_rules, and support_triage_rules_admin_write is a
      -- FOR ALL policy over tenant_owner/tenant_admin/tenant_manager). This
      -- verifies and stamps it. It does NOT insert: an `insert into
      -- support_triage_rules` here runs as postgres and bypasses RLS, which is
      -- the second creation engine the plan forbids — the same argument the
      -- connector arm makes, and it applies with full force here because the
      -- ORDINARY writer for this table is PostgREST (upsertTriageRule,
      -- src/lib/supportInboxApi.ts:333) behind a full CRUD editor the customer
      -- already uses.
      --
      -- ⚠ WHY THIS KIND IS NOT PATH A, stated against the two that are.
      -- `employee` is Path A because `authenticated` holds SELECT and nothing
      -- else on digital_employees; `trust_rule` is Path A for the same reason on
      -- trust_policies. Neither is true here. There IS a PostgREST write path,
      -- customers use it, and routing the interview around it would mean two
      -- writers for one table with only one of them under RLS.
      when 'conversation_type' then
        v_writer     := 'createTriageRuleFromProposal -> support_triage_rules (client, under RLS), verified and stamped here';
        v_object_tbl := 'support_triage_rules';

        -- ⚠ THE SAME EXPLICIT WHITESPACE SET 751 ESTABLISHED, for the same
        -- measured reason: one-argument `btrim` strips SPACES ONLY, while the
        -- client composes with JS `.trim()`. All three of these are COMPARED
        -- byte for byte against what the browser wrote, so a lone tab surviving
        -- here and not there is a permanent stuck proposal beside a live rule.
        v_ct_label   := nullif(btrim(v_p.payload ->> 'label',         E' \t\n\r\f\v\u00a0\u1680\u2000\u2001\u2002\u2003\u2004\u2005\u2006\u2007\u2008\u2009\u200a\u2028\u2029\u202f\u205f\u3000\ufeff'), '');
        v_ct_cat     := nullif(btrim(v_p.payload ->> 'set_category',  E' \t\n\r\f\v\u00a0\u1680\u2000\u2001\u2002\u2003\u2004\u2005\u2006\u2007\u2008\u2009\u200a\u2028\u2029\u202f\u205f\u3000\ufeff'), '');
        v_ct_pattern := nullif(btrim(v_p.payload ->> 'match_pattern', E' \t\n\r\f\v\u00a0\u1680\u2000\u2001\u2002\u2003\u2004\u2005\u2006\u2007\u2008\u2009\u200a\u2028\u2029\u202f\u205f\u3000\ufeff'), '');
        -- ⚠ 760: the FOURTH literal, trimmed with the same explicit whitespace
        -- set for the same reason — one-argument btrim strips SPACES ONLY and
        -- the browser composes with JS .trim(). This one is OPTIONAL: a topic
        -- nobody owns is a topic the workspace answers the way it does today,
        -- which is the whole of the founder's "no match keeps today's behaviour".
        v_ct_own_ref := nullif(btrim(v_p.payload ->> 'owner_ref',     E' \t\n\r\f\v\u00a0\u1680\u2000\u2001\u2002\u2003\u2004\u2005\u2006\u2007\u2008\u2009\u200a\u2028\u2029\u202f\u205f\u3000\ufeff'), '');

        if v_ct_label is null then
          raise exception 'this recommendation has no name for the topic, and a topic nobody can read on a screen is not something anyone can agree to. Nothing was created, and it is still here waiting for you.';
        end if;
        if v_ct_cat is null then
          raise exception 'this recommendation does not say which topic to file these conversations under, so there is nothing to write down. Nothing was created, and it is still here waiting for you.';
        end if;

        -- ⚠ THE CATEGORY TOKEN IS WRITTEN INTO de_conversations.category AND
        -- READ BACK BY THE INBOX FILTER AS AN EXACT STRING (supportInboxApi.ts's
        -- CONV_COLS and SupportInboxPage's `c.category !== topic`), and
        -- SupportHistoryReport renders `category.replace(/_/g, ' ')`. So the
        -- shape is fixed here rather than left to whatever a model wrote: lower
        -- case, a-z 0-9 and underscore, at most 40 characters. The eleven live
        -- categories all satisfy it (safety, security, legal, outage, data,
        -- billing, access, complaint, feature_request, how_to, general —
        -- measured 2026-08-17 across 18 tenants).
        if v_ct_cat !~ '^[a-z0-9]+(_[a-z0-9]+)*$' or length(v_ct_cat) > 40 then
          raise exception 'we cannot file conversations under "%" — a topic name we can sort and count by has to be plain lower-case words joined by underscores, like "delivery_delay". Nothing was created, and it is still here waiting for you.',
            v_ct_cat;
        end if;

        -- ⚠ THE PATTERN IS NOT A REGULAR EXPRESSION HERE, AND THAT IS THE
        -- OPPOSITE OF THE GUARDRAIL CASE — measured from the matcher itself
        -- rather than assumed from the field name. `classify_support_text`
        -- (read live 2026-08-17) does:
        --     FOREACH frag IN ARRAY string_to_array(r.match_pattern, '|')
        --       IF position(lower(btrim(frag)) IN lower(text)) > 0 THEN ...
        -- `position`, not `~` and not `new RegExp`. So every character in a
        -- triage pattern means itself, and 751's whole regex-metacharacter
        -- screen would be refusing safe input if it were copied here. What DOES
        -- carry over is the empty-alternative hazard, and it lands differently:
        -- an empty fragment is skipped by `frag <> ''`, so "billing|" matches
        -- exactly what "billing" does rather than matching everything. It is
        -- refused anyway, because a card showing a trailing bar promises a
        -- second phrase that will never be looked at.
        --
        -- A NULL pattern is refused OUTRIGHT and this is the sharpest edge on
        -- this kind: a rule with no pattern is a CATCH-ALL that returns
        -- IMMEDIATELY for every message reaching it, which would silently swallow
        -- every conversation the rules below it were written for. All 18 live
        -- tenants carry exactly one such rule, at rule_order 9999, called
        -- "Default". An interview must never mint a second one.
        if v_ct_pattern is null then
          raise exception 'this recommendation has no words to look for, and a topic rule with no words catches EVERY conversation rather than the ones about "%" — every other topic below it would stop being used. Nothing was created, and it is still here waiting for you.',
            v_ct_label;
        end if;
        if v_ct_pattern ~ '(^\||\|\||\|$)' then
          raise exception 'the words to look for on this one — "%" — have a "|" with nothing beside it. The blank between the bars is skipped rather than matched, so the card would be showing you a phrase that is never looked at. Nothing was created, and it is still here waiting for you.',
            v_ct_pattern;
        end if;

        -- ⚠⚠ 760 — WHO ANSWERS, RESOLVED FROM THE SESSION AND NEVER FROM THE
        -- CALLER. This is 753's de_ref shape, and it is that shape for the same
        -- reason: there is no employee id to hand us at the moment the card is
        -- written, so the reference is to an ARCHETYPE the same interview
        -- proposed, and the employee it means is the one an ACCEPTED employee
        -- proposal in THIS session created.
        --
        -- ⚠ AN UNRESOLVABLE OWNER REFUSES; IT DOES NOT DEGRADE TO "nobody". The
        -- card named a person. Writing the rule without them would be a card
        -- that said one thing and a workspace that does another, with no later
        -- reader able to tell — and this repo has paid for silent degradation
        -- before. The refusal says which card to say yes to first.
        if v_ct_own_ref is not null then
          if v_ct_own_ref !~ '^archetype:[a-z0-9_]+$' then
            raise exception 'this recommendation says these conversations should go to "%" rather than to one of the people it recommended, so there is nobody to send them to. Nothing was created, and it is still here waiting for you.',
              v_ct_own_ref;
          end if;
          v_ct_own_arch := substring(v_ct_own_ref from 11);

          select s.created_object_id into v_ct_owner
            from public.discovery_proposals s
           where s.session_id = v_p.session_id
             and s.tenant_id  = v_p.tenant_id
             and s.kind       = 'employee'
             and s.state      = 'accepted'
             and s.created_object_id is not null
             and nullif(btrim(s.payload ->> 'archetype_key', E' \t\n\r\f\v\u00a0\u1680\u2000\u2001\u2002\u2003\u2004\u2005\u2006\u2007\u2008\u2009\u200a\u2028\u2029\u202f\u205f\u3000\ufeff'), '') = v_ct_own_arch
           order by s.decided_at desc nulls last
           limit 1;
          if v_ct_owner is null then
            raise exception 'we have not set up the person who would answer these yet. Say yes to that recommendation first and this one will be ready straight after — a topic that goes to somebody who does not exist would just sit there. Nothing was created, and it is still here waiting for you.';
          end if;

          -- ...and that id, which came off a SIBLING ROW rather than off this
          -- decision, still has to be an employee in THIS workspace.
          -- ⚠ THE WORKSPACE ASSISTANT IS A FILTER, NEVER A VALUE READ — the
          -- standing instruction stated as a predicate. It is the workspace's
          -- own internal helper, not one of the customer's employees, and this
          -- would otherwise be the first path on the platform that puts
          -- customer support traffic in front of it.
          --
          -- ⚠⚠ AND LIFECYCLE IS DELIBERATELY *NOT* A BAR HERE, WHICH IS THE
          -- OPPOSITE OF WHAT THE FIRST VERSION OF THIS BRANCH DID — measured,
          -- not reasoned. The employee an owner_ref resolves to is ALWAYS one
          -- an accepted employee proposal in this same session just created,
          -- and the ordinary discovery hire lands at
          -- `lifecycle_status = 'designed', status = 'idle'` (driven live
          -- 2026-08-18 through this very function). So a lifecycle bar here
          -- would refuse EVERY owner the interview can ever propose, and the
          -- feature would be dead on arrival with a message blaming the
          -- customer.
          --
          -- THE SPLIT IS THE POINT: this function records CONSENT — the
          -- customer said this person answers this topic — and
          -- classify_support_text decides ELIGIBILITY at answer time, where a
          -- 'designed', paused, retired or archived owner returns NULL and the
          -- workspace's ordinary choice answers instead. One place, one rule,
          -- re-evaluated on every message rather than frozen at accept time.
          --
          -- ⚠ AND IT IS ALSO THE SECOND GATE THIS KIND WAS SAID NOT TO HAVE.
          -- Because the owner is always a just-hired 'designed' employee,
          -- accepting a topic with an owner CHANGES NOTHING ABOUT WHO ANSWERS
          -- until that employee is published. The card and the drawer both say
          -- so; the sentence a customer reads before pressing a button has to
          -- be the sentence that turns out to be true.
          select d.name into v_ct_own_name
            from public.digital_employees d
           where d.id = v_ct_owner
             and d.tenant_id = v_p.tenant_id
             and coalesce(d.is_workforce_assistant, false) = false;
          if v_ct_own_name is null then
            raise exception 'the person this topic would go to is not one of yours, so these conversations would have nowhere to land. Nothing was created, and it is still here waiting for you.';
          end if;
        end if;

        if p_created_object_id is null then
          raise exception 'a conversation topic is accepted by creating the rule first: add it as the signed-in person, then pass its id here (Path B)';
        end if;

        -- The id a caller hands us is NOT its own authorisation. Read the WHOLE
        -- row back — every sentence on the card is checked against it below.
        select * into v_ct_rule
          from public.support_triage_rules t
         where t.id = p_created_object_id
           and t.tenant_id = v_p.tenant_id;
        if v_ct_rule.id is null then
          raise exception 'no topic rule % in this workspace — a created-object id is not its own authorisation', p_created_object_id;
        end if;

        -- ⚠⚠ THE PROVENANCE COLUMN IS THE IDEMPOTENCY, AND IT IS THE ONLY
        -- THING THAT COULD BE. support_triage_rules carried exactly three
        -- constraints before this migration — the primary key, the
        -- set_priority CHECK and the tenant FK (read live 2026-08-17) — and NO
        -- unique index of any kind. So a browser that died between the insert
        -- and the stamp left an orphan rule, and a retry minted a second one
        -- with nothing in the database to stop it. 752 solved the same problem
        -- with a deterministic key over an index that already existed; there was
        -- no key column here to be deterministic about.
        -- This file adds `source_proposal_id` plus a UNIQUE index over it, so
        -- one proposal can own at most ONE rule, enforced by the database rather
        -- than by the browser not clicking twice. The client's find-first is a
        -- COURTESY that turns a 23505 into a re-use; this is the guarantee.
        if v_ct_rule.source_proposal_id is distinct from v_p.id then
          raise exception 'the topic rule that was created is not linked to this recommendation (it points at %), so accepting this would leave two rules where you agreed to one. Nothing was recorded, and this is still here waiting for you.',
            coalesce(v_ct_rule.source_proposal_id::text, 'nothing');
        end if;

        -- ⚠ THE CONSENTED LITERALS, BYTE FOR BYTE — §11b's "you cannot consent
        -- to what you cannot predict" applied to a topic rule. The card rendered
        -- the topic name, the words to look for and the file-under token; if the
        -- row carries anything else the customer agreed to one rule and got
        -- another, and no later reader could tell.
        if v_ct_rule.set_category is distinct from v_ct_cat then
          raise exception 'the rule that was created files conversations under "%", but this recommendation showed "%" — a topic has to be the one that was agreed to, exactly', coalesce(v_ct_rule.set_category, 'nothing'), v_ct_cat;
        end if;
        if v_ct_rule.match_pattern is distinct from v_ct_pattern then
          raise exception 'the rule that was created looks for "%", but this recommendation showed "%" — the words on the card are the whole of what you agreed to', coalesce(v_ct_rule.match_pattern, 'nothing'), v_ct_pattern;
        end if;
        if v_ct_rule.name is distinct from v_ct_label then
          raise exception 'the rule that was created is called "%", but this recommendation showed "%" — the name is what you will see in your triage rules, so it has to be the one on the card', coalesce(v_ct_rule.name, 'nothing'), v_ct_label;
        end if;
        -- ⚠⚠ 760 — AND WHO ANSWERS, WHICH IS NOW THE LARGEST FACT ON THE CARD.
        -- `is distinct from` compares BOTH DIRECTIONS with one operator and
        -- that is deliberate: a card naming nobody must not create a rule that
        -- sends traffic to somebody, and a card naming somebody must not create
        -- a rule that sends it nowhere. Either way the customer agreed to one
        -- thing and got another, and a triage rule is editable with no version
        -- history anywhere else, so the literal has to be checked here or never.
        if v_ct_rule.owner_de_id is distinct from v_ct_owner then
          raise exception 'the rule that was created sends these conversations to %, but this recommendation said %. Who answers is the biggest thing on that card, so it has to be the one that was agreed to. Nothing was recorded, and it is still here waiting for you.',
            coalesce((select d.name from public.digital_employees d
                       where d.id = v_ct_rule.owner_de_id and d.tenant_id = v_p.tenant_id
                         and coalesce(d.is_workforce_assistant, false) = false), 'nobody in particular'),
            coalesce(v_ct_own_name, 'nobody in particular');
        end if;

        -- ...and it has to actually be consulted. `classify_support_text`
        -- filters `WHERE tenant_id = p_tenant_id AND active`, so an inactive rule
        -- is a card that says a topic is being tracked while nothing looks at it.
        if not coalesce(v_ct_rule.active, false) then
          raise exception 'the rule that was created is switched off, and a topic nothing looks for is not the thing this recommendation described. Nothing was recorded, and this is still here waiting for you.';
        end if;

        -- ⚠⚠ THE ORDER IS THE ROUTING DECISION, AND IT IS CHECKED RATHER THAN
        -- DEFAULTED. `classify_support_text` walks the rules
        -- `ORDER BY rule_order, created_at` and RETURNS ON THE FIRST MATCH. The
        -- column defaults to 100 — and every one of the 18 live tenants already
        -- carries a baseline rule AT 100 ("How-to"), seeded before today, so a
        -- rule taking the default would tie with it and lose the tie on
        -- created_at, silently and forever. That is an ordering nobody chose.
        --
        -- The live baseline, measured 2026-08-17, is identical in all 18
        -- tenants: 10 Safety, 20 Security, 30 Legal/Regulatory, 40 Outage,
        -- 50 Data loss, 60 Billing, 70 Access, 80 Complaint, 90 Feature request,
        -- 100 How-to, 9999 Default (the catch-all).
        --
        -- So this kind is confined to the band 200..9998, and the accept
        -- REFUSES a row outside it. That band is a decision with two halves,
        -- and both are on the card:
        --   · ABOVE 100 — a topic from an interview NEVER outranks Safety or
        --     Security. "Someone is hurt" must not be re-filed as "delivery
        --     delay" because a customer described their inbox that way.
        --   · BELOW 9999 — it is still consulted before the catch-all, so it
        --     does change what a conversation is filed as. A rule that only ran
        --     after "Default" could never fire at all.
        if coalesce(v_ct_rule.rule_order, 100) < 200 or coalesce(v_ct_rule.rule_order, 100) > 9998 then
          raise exception 'the rule that was created sits at position % in your triage list, and a topic from this conversation belongs between 200 and 9998 — after the built-in urgent categories like Safety and Security, and before the catch-all. Nothing was recorded, and this is still here waiting for you.',
            coalesce(v_ct_rule.rule_order::text, 'the default');
        end if;

        -- WHAT ELSE IS AT THAT POSITION, COUNTED RATHER THAN ASSUMED. Ties are
        -- broken by created_at, which nothing on any screen shows, so a tie is a
        -- routing decision made invisibly. This does NOT refuse — two of the
        -- customer's own topics sharing a position is a display question between
        -- rules they both wrote, not a safety question, and refusing would make
        -- a second interview session unable to accept anything. It is COUNTED,
        -- and the number travels into the audit detail and the return payload so
        -- the screen can say it out loud.
        select count(*) into v_ct_ties
          from public.support_triage_rules t
         where t.tenant_id = v_p.tenant_id
           and t.active
           and t.rule_order = v_ct_rule.rule_order
           and t.id <> v_ct_rule.id;

        -- ...and how many active rules sit AHEAD of it, which is the honest
        -- answer to "will this actually catch anything". A rule behind ten
        -- broader patterns fires for whatever they leave.
        select count(*) into v_ct_ahead
          from public.support_triage_rules t
         where t.tenant_id = v_p.tenant_id
           and t.active
           and t.rule_order < v_ct_rule.rule_order;

        -- What the screen and the audit line are allowed to say, from ONE
        -- object so the two cannot drift. The PATTERN and the CATEGORY are in
        -- here deliberately: the row is editable and deletable from the triage
        -- rules editor with no version history anywhere else, so the literals
        -- the customer consented to have to outlive it — the same reasoning
        -- 751 states for a guardrail's pattern.
        -- ⚠⚠ 760 REPLACED THE PARAGRAPH THAT USED TO STAND HERE, AND THE OLD ONE
        -- WAS TRUE WHEN IT WAS WRITTEN. It said `routes_to_employee` is FALSE
        -- because "nothing on this platform reads de_conversations.category to
        -- choose a digital employee". That is no longer the shape: the three
        -- functions that CREATE a conversation now classify the question BEFORE
        -- the row exists, look the topic's owner up from that one classification,
        -- and stamp de_id from it (widget-ask, email-inbound, de-answer).
        --
        -- ⚠ SO THE COUNTER IS AN EXPRESSION, NOT A LITERAL, and that is the
        -- whole point of it. A topic with no owner still routes nothing, and
        -- `routes_to_employee` says so for that card; a topic with an owner says
        -- so for that one. A hardcoded `true` would be the same defect the
        -- hardcoded `false` became — a sentence the customer is shown that
        -- nothing can be checked against — and both arms are driven in probe 19.
        v_counters := jsonb_build_object(
          'rule_id',            v_ct_rule.id,
          'topic_name',         v_ct_rule.name,
          'set_category',       v_ct_rule.set_category,
          'match_pattern',      v_ct_rule.match_pattern,
          'set_priority',       v_ct_rule.set_priority,
          'set_severity',       v_ct_rule.set_severity,
          'rule_order',         v_ct_rule.rule_order,
          'rules_ahead_of_it',  coalesce(v_ct_ahead, 0),
          'rules_sharing_its_position', coalesce(v_ct_ties, 0),
          'owner_de_id',        v_ct_owner,
          'owner_name',         v_ct_own_name,
          'routes_to_employee', (v_ct_owner is not null),
          'labels_conversations', true);

        v_object_id := v_ct_rule.id;

      -- ---- every other kind ---------------------------------------------
      -- ⚠ NO PRODUCT KIND REACHES THIS ARM ANY MORE. All six kinds
      -- discovery_proposals_kind_check admitted before today now have a `when`
      -- branch above. What reaches it is `__unrouted_probe__`, a SENTINEL this
      -- migration adds to the CHECK precisely so this arm stays drivable — see
      -- the header. Nothing emits it, `authenticated` holds SELECT and nothing
      -- else on discovery_proposals, and it is absent from ProposalKind, from
      -- KIND_LABELS and from SECTION_ORDER, so no card can ever carry it.
      --
      -- ⚠⚠ AND THE PROBES THAT DRIVE IT NO LONGER NAME IT. 751 repointed probe
      -- 7 off `guardrail`, 752 repointed probe 14 off `procedure`, and each
      -- repoint was a rename that happened to still have a spare kind. There is
      -- no spare left. So 753 rebuilt both probes to DERIVE their subject: they
      -- read discovery_proposals_kind_check for the admitted kinds, strip the
      -- comments out of THIS function's body, subtract every `when '<kind>'
      -- then` arm that is really there, and drive whatever survives. The day
      -- `conversation_type` gains a branch that set is EMPTY, and the fixture
      -- guard turns that into a FINDING naming what has to be rebuilt — instead
      -- of two probes that keep running and compare nothing. Whoever ships it
      -- should expect red here and read the message rather than move a number.
      else
        raise exception 'kind not yet routable: %', v_p.kind;


    end case;

    -- Belt and braces for a future branch that forgets: never leave Zone 3
    -- with the state claimed and nothing created.
    if v_object_id is null then
      raise exception 'writer_returned_no_object';
    end if;

  exception when others then
    -- ⚠ ONLY variable capture. Everything the failed writer wrote is already
    -- rolled back by the time this line runs, and anything written HERE would
    -- roll back too. The record of the failure is made below, outside.
    -- ⚠ `sqlstate`, NOT `returned_sqlstate`. RETURNED_SQLSTATE is a GET STACKED
    -- DIAGNOSTICS ITEM NAME, not an identifier: only SQLSTATE and SQLERRM exist
    -- in a handler's namespace. plpgsql defers expression parsing to first
    -- execution, so `returned_sqlstate` here compiled fine and then raised
    -- 42703 `column "returned_sqlstate" does not exist` INSIDE the handler on
    -- the first refusal — escaping this block and killing the entire
    -- revert-to-pending / last_error / attempts / refusal-audit arm below.
    -- The shipped precedent is migration 738's `v_null_sqlstate := sqlstate;`.
    v_err      := sqlerrm;
    v_errstate := sqlstate;
  end;

  --------------------------------------------------------------------------
  -- OUTSIDE the sub-block. These writes commit with the rest of the
  -- transaction — migration 525's pattern.
  --------------------------------------------------------------------------
  if v_err is not null then
    update public.discovery_proposals
       set state         = 'pending',
           decided_by    = null,
           decided_at    = null,
           last_error    = left(v_err, 500),
           last_error_at = now(),
           attempts      = attempts + 1
     where id = p_proposal_id and tenant_id = v_p.tenant_id
    returning attempts into v_attempts;

    v_detail := v_detail || jsonb_build_object(
      'outcome',                'refused',
      'error',                  left(v_err, 500),
      'sqlstate',               v_errstate,
      'attempts',               v_attempts,
      'writer',                 v_writer,
      'attempted_object_table', v_object_tbl);

    perform public.append_audit_event(
      v_p.tenant_id, 'You', 'human',
      format('Discovery proposal could not be accepted — %s (%s): %s', v_label, v_p.kind, left(v_err, 200)),
      'config_change', v_detail);

    return jsonb_build_object(
      'ok',          false,
      'state',       'pending',
      'proposal_id', v_p.id,
      'error',       v_err,
      'sqlstate',    v_errstate,
      'attempts',    v_attempts);
  end if;

  -- The accept succeeded. state='accepted' (Zone 2) and created_object_id
  -- (here) commit together; neither can be observed without the other.
  update public.discovery_proposals
     set created_object_id = v_object_id,
         last_error        = null,
         last_error_at     = null
   where id = p_proposal_id and tenant_id = v_p.tenant_id;

  -- ⚠ `|| v_counters` on BOTH, from the SAME variable. The audit line and the
  -- answer the screen prints are then the same sentence read twice — a card
  -- saying "0 connected systems" can be checked against the audit trail rather
  -- than believed. For every kind that does not fill it, v_counters is '{}' and
  -- both shapes are byte-identical to what migration 741 returned.
  v_detail := v_detail || jsonb_build_object(
    'outcome',              'created',
    'writer',               v_writer,
    'created_object_table', v_object_tbl,   -- a bare uuid with no table name
    'created_object_id',    v_object_id)    -- is not reconstructable later
    || v_counters;

  perform public.append_audit_event(
    v_p.tenant_id, 'You', 'human', v_action, 'config_change', v_detail);

  return jsonb_build_object(
    'ok',                   true,
    'state',                'accepted',
    'proposal_id',          v_p.id,
    'created_object_table', v_object_tbl,
    'created_object_id',    v_object_id)
    || v_counters;
end;
$function$;

CREATE OR REPLACE FUNCTION public.decide_human_tasks(p_task_ids uuid[], p_decision text, p_reason_code text DEFAULT NULL::text, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_id     uuid;
  v_ok     int := 0;
  v_failed jsonb := '[]'::jsonb;
  v_row    human_tasks;
  v_title  text;
begin
  if p_task_ids is null or array_length(p_task_ids, 1) is null then
    return jsonb_build_object('decided', 0, 'failed', v_failed);
  end if;
  -- Same 500 cap as withdraw_human_tasks, for the same reason: a UI bug must
  -- not be able to clear a whole workspace's queue in one call.
  if array_length(p_task_ids, 1) > 500 then
    raise exception 'too_many: decide at most 500 tasks at a time (got %)', array_length(p_task_ids, 1);
  end if;

  foreach v_id in array p_task_ids loop
    select title into v_title from human_tasks where id = v_id;
    begin
      v_row := public.decide_human_task(v_id, p_decision, p_reason_code, p_note);
      -- NULL is not failure here. decide_human_task returns NULL on the
      -- first-approver path: the approval was RECORDED and the task stays
      -- pending until a different person signs. Reporting that as an error
      -- would teach people to press it twice.
      if v_row.id is null then
        v_failed := v_failed || jsonb_build_object(
          'id', v_id, 'title', coalesce(v_title, '(untitled)'),
          'error', 'first_approval_recorded: a second approver is required');
      else
        v_ok := v_ok + 1;
      end if;
    exception when others then
      v_failed := v_failed || jsonb_build_object(
        'id', v_id, 'title', coalesce(v_title, '(untitled)'), 'error', sqlerrm);
    end;
  end loop;

  return jsonb_build_object('decided', v_ok, 'failed', v_failed);
end
$function$;

CREATE OR REPLACE FUNCTION public.decide_ingest_candidates(p_connector_id uuid, p_refs text[], p_decision text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_tenant uuid; v_count int;
begin
  if p_decision not in ('approved','rejected','pending') then
    raise exception 'decision must be approved, rejected, or pending';
  end if;
  select tenant_id into v_tenant from connectors where id = p_connector_id;
  if v_tenant is null or v_tenant <> auth_tenant_id()
     or not auth_has_tenant_role(array['tenant_owner','tenant_admin']) then
    raise exception 'only workspace owners/admins can review connector documents';
  end if;
  update connector_ingest_candidates
     set status = p_decision, decided_by = auth.uid(), decided_at = now()
   where connector_id = p_connector_id
     and status <> 'ingested'
     and (p_refs is null or external_ref = any (p_refs));
  get diagnostics v_count = row_count;
  return v_count;
end $function$;

CREATE OR REPLACE FUNCTION public.decide_inquiry_triage(p_tenant_id uuid, p_inquiry text, p_confidence integer, p_de_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_rule       record;
  v_text       text := lower(coalesce(p_inquiry, ''));
  v_autonomy   record;
  v_min_conf   integer;
  v_enabled    boolean;
  v_frag       text;
  v_hit        boolean;
  v_frustration integer;
  v_esc        record;
begin
  -- 1) Guardrail check — blocking blocked_topic/blocked_phrase rules,
  --    now scoped to this employee (workspace ∪ department ∪ employee).
  for v_rule in
    select g.id, g.rule, g.pattern
    from guardrail_rules_for_de(p_tenant_id, p_de_id, array['blocked_phrase','blocked_topic']) g
    where g.severity = 'blocking'
  loop
    if v_rule.pattern is null then continue; end if;
    foreach v_frag in array string_to_array(v_rule.pattern, '|') loop
      v_frag := trim(both from lower(v_frag));
      if v_frag = '' then continue; end if;
      begin
        v_hit := v_text ~ v_frag;
      exception when others then
        v_hit := position(v_frag in v_text) > 0;
      end;
      if v_hit then
        return jsonb_build_object(
          'decision', 'blocked_guardrail',
          'confidence', p_confidence,
          'guardrail_rule_id', v_rule.id,
          'guardrail_rule', v_rule.rule,
          'trust_level', null,
          'frustration_score', null,
          'reasoning', format('Blocked: guardrail rule "%s" matched this inquiry — routed to a human regardless of confidence (%s%%). Guardrails always win over the trust dial.', v_rule.rule, p_confidence)
        );
      end if;
    end loop;
  end loop;

  select * into v_esc from resolve_de_escalation(p_tenant_id, p_de_id);

  -- 1.25) Always-escalate topics (DE-B2): per-employee (or workspace-
  --       default) topic patterns that always get a human, regardless
  --       of confidence — below guardrails, above everything else.
  if array_length(v_esc.always_escalate_topics, 1) is not null then
    foreach v_frag in array v_esc.always_escalate_topics loop
      v_frag := trim(both from lower(v_frag));
      if v_frag = '' then continue; end if;
      begin
        v_hit := v_text ~ v_frag;
      exception when others then
        v_hit := position(v_frag in v_text) > 0;
      end;
      if v_hit then
        return jsonb_build_object(
          'decision', 'needs_review',
          'confidence', p_confidence,
          'guardrail_rule_id', null,
          'guardrail_rule', null,
          'trust_level', null,
          'frustration_score', null,
          'reasoning', format('Needs review: this inquiry matches the always-escalate topic "%s" configured for this employee — routed to a human regardless of confidence (%s%%).', v_frag, p_confidence)
        );
      end if;
    end loop;
  end if;

  -- 1.5) Frustration check — threshold resolved per-employee with
  --      workspace fallback (was hardcoded 50).
  v_frustration := score_frustration_internal(p_tenant_id, p_inquiry);
  if v_frustration >= v_esc.frustration_threshold then
    return jsonb_build_object(
      'decision', 'needs_review',
      'confidence', p_confidence,
      'guardrail_rule_id', null,
      'guardrail_rule', null,
      'trust_level', null,
      'frustration_score', v_frustration,
      'reasoning', format('Needs review: this inquiry scored %s%% on frustration signals (threshold %s%%) — routed to a human regardless of confidence (%s%%). A frustrated customer always gets a human.', v_frustration, v_esc.frustration_threshold, p_confidence)
    );
  end if;

  -- 2) Trust dial — resolved per-employee first now (no category
  --    dimension for this sibling, matching its existing scope).
  select * into v_autonomy from resolve_de_autonomy(p_tenant_id, 'answer_widget', p_de_id, null);
  v_enabled := coalesce(v_autonomy.enabled, false);
  v_min_conf := v_autonomy.min_confidence;

  if v_enabled and v_min_conf is not null and p_confidence >= v_min_conf then
    return jsonb_build_object(
      'decision', 'would_auto_send',
      'confidence', p_confidence,
      'guardrail_rule_id', null,
      'guardrail_rule', null,
      'trust_level', v_min_conf,
      'frustration_score', v_frustration,
      'reasoning', format('Would auto-send: confidence %s%% clears the trust-dial floor of %s%% for auto-answering customers, and no guardrail blocked it. Recorded as intent only — no outbound reply channel exists yet, so nothing was actually sent.', p_confidence, v_min_conf)
    );
  end if;

  return jsonb_build_object(
    'decision', 'needs_review',
    'confidence', p_confidence,
    'guardrail_rule_id', null,
    'guardrail_rule', null,
    'trust_level', v_min_conf,
    'frustration_score', v_frustration,
    'reasoning', case
      when not v_enabled then format('Needs review: confidence %s%%, but auto-answering customers is not yet enabled on the trust dial (Governance -> Trust & Architecture).', p_confidence)
      else format('Needs review: confidence %s%% is below the trust-dial floor of %s%% required to auto-answer customers.', p_confidence, coalesce(v_min_conf, 0))
    end
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.decide_work_item_triage(p_tenant_id uuid, p_category text, p_inquiry text, p_confidence integer, p_de_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_rule       record;
  v_text       text := lower(coalesce(p_inquiry, ''));
  v_autonomy   record;
  v_min_conf   integer;
  v_enabled    boolean;
  v_frag       text;
  v_hit        boolean;
  v_frustration integer;
  v_esc        record;
begin
  -- 1) Guardrail check — now scoped to this employee (workspace ∪
  --    department ∪ employee), identical matching to the sibling.
  for v_rule in
    select g.id, g.rule, g.pattern
    from guardrail_rules_for_de(p_tenant_id, p_de_id, array['blocked_phrase','blocked_topic']) g
    where g.severity = 'blocking'
  loop
    if v_rule.pattern is null then continue; end if;
    foreach v_frag in array string_to_array(v_rule.pattern, '|') loop
      v_frag := trim(both from lower(v_frag));
      if v_frag = '' then continue; end if;
      begin
        v_hit := v_text ~ v_frag;
      exception when others then
        v_hit := position(v_frag in v_text) > 0;
      end;
      if v_hit then
        return jsonb_build_object(
          'decision', 'blocked_guardrail',
          'confidence', p_confidence,
          'guardrail_rule_id', v_rule.id,
          'guardrail_rule', v_rule.rule,
          'trust_level', null,
          'frustration_score', null,
          'reasoning', format('Blocked: guardrail rule "%s" matched this %s item — routed to a human regardless of confidence (%s%%). Guardrails always win over the trust dial.', v_rule.rule, p_category, p_confidence)
        );
      end if;
    end loop;
  end loop;

  select * into v_esc from resolve_de_escalation(p_tenant_id, p_de_id);

  -- 1.25) Always-escalate topics (DE-B2) — same tier as the sibling.
  if array_length(v_esc.always_escalate_topics, 1) is not null then
    foreach v_frag in array v_esc.always_escalate_topics loop
      v_frag := trim(both from lower(v_frag));
      if v_frag = '' then continue; end if;
      begin
        v_hit := v_text ~ v_frag;
      exception when others then
        v_hit := position(v_frag in v_text) > 0;
      end;
      if v_hit then
        return jsonb_build_object(
          'decision', 'needs_review',
          'confidence', p_confidence,
          'guardrail_rule_id', null,
          'guardrail_rule', null,
          'trust_level', null,
          'frustration_score', null,
          'reasoning', format('Needs review: this %s item matches the always-escalate topic "%s" configured for this employee — routed to a human regardless of confidence (%s%%).', p_category, v_frag, p_confidence)
        );
      end if;
    end loop;
  end if;

  -- 1.5) Frustration check — threshold resolved per-employee with
  --      workspace fallback (was hardcoded 50).
  v_frustration := score_frustration_internal(p_tenant_id, p_inquiry);
  if v_frustration >= v_esc.frustration_threshold then
    return jsonb_build_object(
      'decision', 'needs_review',
      'confidence', p_confidence,
      'guardrail_rule_id', null,
      'guardrail_rule', null,
      'trust_level', null,
      'frustration_score', v_frustration,
      'reasoning', format('Needs review: this %s item scored %s%% on frustration signals (threshold %s%%) — routed to a human regardless of confidence (%s%%). A frustrated customer always gets a human.', p_category, v_frustration, v_esc.frustration_threshold, p_confidence)
    );
  end if;

  -- 2) Trust dial — resolved per-employee first now, via the shared
  --    cascade (exact de+category -> de-wide -> category-wide -> tenant-wide).
  select * into v_autonomy from resolve_de_autonomy(p_tenant_id, 'answer_widget', p_de_id, p_category);
  v_enabled := coalesce(v_autonomy.enabled, false);
  v_min_conf := v_autonomy.min_confidence;

  if v_enabled and v_min_conf is not null and p_confidence >= v_min_conf then
    return jsonb_build_object(
      'decision', 'would_auto_send',
      'confidence', p_confidence,
      'guardrail_rule_id', null,
      'guardrail_rule', null,
      'trust_level', v_min_conf,
      'frustration_score', v_frustration,
      'reasoning', format('Would auto-send: confidence %s%% clears the trust-dial floor of %s%% for auto-answering on %s, and no guardrail blocked it. Recorded as intent only unless a registered action can act on this item.', p_confidence, v_min_conf, p_category)
    );
  end if;

  return jsonb_build_object(
    'decision', 'needs_review',
    'confidence', p_confidence,
    'guardrail_rule_id', null,
    'guardrail_rule', null,
    'trust_level', v_min_conf,
    'frustration_score', v_frustration,
    'reasoning', case
      when not v_enabled then format('Needs review: confidence %s%%, but auto-answering on %s is not yet enabled on the trust dial (Governance -> Trust & Architecture).', p_confidence, p_category)
      else format('Needs review: confidence %s%% is below the trust-dial floor of %s%% required to auto-answer on %s.', p_confidence, coalesce(v_min_conf, 0), p_category)
    end
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.decision_unblock_impact(p_task_ids uuid[] DEFAULT NULL::uuid[])
 RETURNS TABLE(task_id uuid, work_item_id uuid, direct_blocked integer, total_blocked integer, deepest_chain integer)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  with recursive roots as (
    select t.id as task_id, t.related_id as work_item_id
      from human_tasks t
     where t.tenant_id = auth_tenant_id()
       and t.status = 'pending'
       and t.related_table = 'de_work_items'
       and t.related_id is not null
       and (p_task_ids is null or t.id = any(p_task_ids))
       and (t.de_id is null or public.can_access_de(t.de_id))
  ),
  chain as (
    -- depth 1: the items whose predecessor IS the stranded item
    select r.task_id, w.id, 1 as depth
      from roots r
      join de_work_items w on w.depends_on = r.work_item_id
     where w.status in ('queued', 'waiting_human')
    union all
    -- ...and everything behind those, transitively
    select c.task_id, w.id, c.depth + 1
      from chain c
      join de_work_items w on w.depends_on = c.id
     where w.status in ('queued', 'waiting_human')
       -- ⚠ A CYCLE GUARD, NOT A DISPLAY LIMIT. depends_on has no constraint
       -- preventing A->B->A, and a recursive CTE that meets one does not
       -- return a wrong answer, it never returns. The deepest real chain
       -- measured on this data is 7.
       and c.depth < 50
  )
  select
    r.task_id,
    r.work_item_id,
    coalesce(count(*) filter (where c.depth = 1), 0)::int as direct_blocked,
    coalesce(count(c.id), 0)::int                         as total_blocked,
    coalesce(max(c.depth), 0)::int                        as deepest_chain
  from roots r
  left join chain c on c.task_id = r.task_id
  group by r.task_id, r.work_item_id;
$function$;

CREATE OR REPLACE FUNCTION public.delete_account_contact(p_contact_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_tenant uuid := auth_tenant_id(); v_n int;
begin
  if v_tenant is null then raise exception 'not_authenticated'; end if;
  if not auth_has_tenant_role(array['tenant_owner','tenant_admin','tenant_manager']) then
    raise exception 'not_allowed';
  end if;
  delete from customer_account_contacts where id = p_contact_id and tenant_id = v_tenant;
  get diagnostics v_n = row_count;
  return jsonb_build_object('ok', v_n > 0);
end;
$function$;

CREATE OR REPLACE FUNCTION public.delete_custom_metric(p_metric_id uuid)
 RETURNS TABLE(success boolean, message text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_owner UUID;
BEGIN
  SELECT cm.tenant_id INTO v_owner FROM customer_metrics cm WHERE cm.metric_id = p_metric_id;
  IF v_owner IS NULL THEN RAISE EXCEPTION 'metric_not_found'; END IF;
  PERFORM public._assert_caller_tenant(v_owner);

  DELETE FROM customer_metrics cm WHERE cm.metric_id = p_metric_id;
  RETURN QUERY SELECT TRUE::BOOLEAN, 'Metric deleted'::TEXT;
END$function$;

CREATE OR REPLACE FUNCTION public.delete_de_operate_binding(p_system_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tenant uuid; v_secret uuid; v_operate_only boolean;
BEGIN
  SELECT tenant_id, login_secret_id, (binding_kind = 'connector' AND source_table IS NULL)
    INTO v_tenant, v_secret, v_operate_only
    FROM de_connected_systems WHERE id = p_system_id;
  IF v_tenant IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'binding_not_found'); END IF;
  IF NOT public.can_admin_tenant_internal(v_tenant) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_permitted');
  END IF;
  IF NOT v_operate_only THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_operate_only');
  END IF;
  DELETE FROM de_connected_systems WHERE id = p_system_id;
  IF v_secret IS NOT NULL THEN DELETE FROM vault.secrets WHERE id = v_secret; END IF;
  RETURN jsonb_build_object('ok', true);
END; $function$;

CREATE OR REPLACE FUNCTION public.delete_principal_group(p_group_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tenant uuid := auth_tenant_id(); v_name text; v_grants int; v_members int; v_my int;
BEGIN
  IF v_tenant IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  SELECT name INTO v_name FROM knowledge_principal_groups WHERE id = p_group_id AND tenant_id = v_tenant;
  IF v_name IS NULL THEN RAISE EXCEPTION 'group_not_found'; END IF;

  v_my := public.knowledge_my_admin_level(NULL);
  IF v_my < 5 AND NOT is_platform_admin() THEN
    RAISE EXCEPTION 'insufficient_permission: managing groups requires knowledge manager';
  END IF;
  -- Symmetric with 356's revoke guard: deleting a group revokes its grants, so
  -- you may not delete one holding more access than you could have removed.
  IF public.knowledge_group_max_level(p_group_id) > v_my AND NOT is_platform_admin() THEN
    RAISE EXCEPTION 'insufficient_permission: that group holds access above your level';
  END IF;

  SELECT count(*) INTO v_grants FROM knowledge_access_grants
   WHERE principal_type = 'group' AND principal_group_id = p_group_id;
  SELECT count(*) INTO v_members FROM knowledge_principal_group_members WHERE group_id = p_group_id;

  DELETE FROM knowledge_principal_groups WHERE id = p_group_id;   -- cascades the grants

  PERFORM append_audit_event(v_tenant, 'Knowledge', 'human',
    format('Deleted the group "%s" — %s grant(s) removed, %s member(s) affected', v_name, v_grants, v_members),
    'access_control',
    jsonb_build_object('group_id', p_group_id, 'grants_removed', v_grants, 'members', v_members));

  RETURN jsonb_build_object('ok', true, 'grants_removed', v_grants, 'members_affected', v_members);
END $function$;

CREATE OR REPLACE FUNCTION public.delete_tenant(p_tenant_id uuid, p_confirm_slug text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_demo_tenant_id constant uuid := 'a0000000-0000-0000-0000-000000000001';
  v_t tenants;
  v_self uuid;
  v_children int;
  v_actor text;
  v_before jsonb;
  v_rows_before bigint;
  v_tables int;
  v_after jsonb;
  v_rows_after bigint;
  v_profiles int := 0;
  -- Captured before the cascade blanks profiles.tenant_id (SET NULL) — see step 5.
  v_members uuid[] := '{}';
  v_receipt uuid;
BEGIN
  -- ── rails (verbatim from migration 194) ──────────────────────────────────
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not authenticated';
  END IF;
  IF NOT resolve_platform_capability(auth.uid(), 'tenants.manage') THEN
    RAISE EXCEPTION 'only a platform team member with tenant-management access may delete a tenant';
  END IF;

  SELECT * INTO v_t FROM tenants WHERE id = p_tenant_id;
  IF NOT found THEN
    RAISE EXCEPTION 'tenant not found';
  END IF;

  IF p_tenant_id = v_demo_tenant_id THEN
    RAISE EXCEPTION 'the demo tenant cannot be deleted';
  END IF;

  SELECT tenant_id INTO v_self FROM profiles WHERE user_id = auth.uid();
  IF v_self IS NOT DISTINCT FROM p_tenant_id THEN
    RAISE EXCEPTION 'you cannot delete the tenant you belong to';
  END IF;

  IF v_t.status <> 'suspended' THEN
    RAISE EXCEPTION 'suspend the tenant before deleting it — deletion is permanent and irreversible';
  END IF;

  IF coalesce(p_confirm_slug, '') <> v_t.slug THEN
    RAISE EXCEPTION 'confirmation text must exactly match the tenant slug (%)', v_t.slug;
  END IF;

  SELECT count(*) INTO v_children FROM tenants WHERE parent_tenant_id = p_tenant_id;
  IF v_children > 0 THEN
    RAISE EXCEPTION 'this tenant still has % sub-tenant(s) — delete or reassign them first', v_children;
  END IF;

  -- ── step 1: who is doing this, captured before anything is removed ───────
  SELECT full_name INTO v_actor FROM profiles WHERE user_id = auth.uid();

  -- ── step 2: pre-sweep — what is about to be destroyed ────────────────────
  -- Counted before, not after, because "rows removed" on a receipt has to be
  -- a measurement, not an inference from a post-delete count of zero.
  SELECT coalesce(jsonb_object_agg(table_name, remaining_rows)
                    FILTER (WHERE remaining_rows > 0 AND counts_as_residue), '{}'::jsonb),
         -- sum(bigint) returns numeric; cast so the receipt column and the
         -- comparison below are unambiguously integral.
         coalesce(sum(remaining_rows) FILTER (WHERE counts_as_residue), 0)::bigint,
         count(*)::int
    INTO v_before, v_rows_before, v_tables
    FROM tenant_rows_remaining(p_tenant_id);

  -- ── step 3: sanction the guarded purges, for THIS transaction only ───────
  -- set_config(..., true) is transaction-local, so the append-only posture is
  -- intact for every other statement in the database.
  PERFORM set_config('app.allow_audit_purge', 'on', true);       -- audit_events (mig 194)
  PERFORM set_config('app.allow_compliance_change', 'on', true); -- guardrail_rules w/ compliance_pack_key
  PERFORM set_config('app.allow_tenant_purge', 'on', true);      -- guardrail_adjudications (§2)

  -- ── step 4: the NO ACTION children the cascade will not take ─────────────
  DELETE FROM tenant_provisioning_requests
    WHERE proposed_parent_tenant_id = p_tenant_id OR created_tenant_id = p_tenant_id;
  DELETE FROM platform_access_events WHERE tenant_id = p_tenant_id;

  -- ── step 5: REMEMBER the members — do not delete them yet ────────────────
  -- ⚠ ORDERING IS LOAD-BEARING. An earlier version deleted profiles HERE,
  -- before the cascade, and that makes a workspace permanently undeletable the
  -- moment anyone uses it properly. Eleven FKs point at profiles with
  -- ON DELETE NO ACTION, and five of those sit on TENANT-scoped tables:
  --   tenant_api_keys.created_by            tenant_feature_overrides.set_by
  --   tenant_ip_allowlist_entries.created_by  tenant_ip_allowlists.updated_by
  --   tenant_session_policies.updated_by
  -- Those rows still exist at this point; only step 6 removes them. So the
  -- profile delete raised, and the whole transaction rolled back, for any
  -- tenant whose admin had ever created an API key or an IP allowlist entry.
  -- It does not fire on today's data purely by luck: all 8 existing
  -- tenant_feature_overrides rows were set by a PLATFORM profile, which the
  -- layer filter below excludes. The first tenant admin to use the Security
  -- page would have locked their own workspace into existence forever.
  --
  -- tenant_id is captured into an array because step 6's cascade is what
  -- BLANKS it (the FK is ON DELETE SET NULL) — after the cascade there is no
  -- longer any way to ask "who belonged to this tenant?".
  SELECT coalesce(array_agg(user_id), '{}')
    INTO v_members
    FROM profiles
   WHERE tenant_id = p_tenant_id AND layer IS DISTINCT FROM 'platform';

  -- ── step 6: the cascade ──────────────────────────────────────────────────
  DELETE FROM tenants WHERE id = p_tenant_id;

  -- ── step 6b: NOW the profiles ────────────────────────────────────────────
  -- SET NULL would otherwise blank tenant_id and leave full_name sitting in the
  -- table while a residue check keyed on tenant_id reported zero — the exact
  -- laundering described in (C) at the top of this file.
  -- `layer IS DISTINCT FROM 'platform'` was applied when the members were
  -- captured, so a platform operator can never be removed by a tenant deletion
  -- even if someone later attaches one to a tenant.
  BEGIN
    DELETE FROM profiles WHERE user_id = ANY(v_members);
    GET DIAGNOSTICS v_profiles = ROW_COUNT;
  EXCEPTION WHEN foreign_key_violation THEN
    -- Name the actual relation from sqlerrm rather than guessing: after the
    -- cascade, anything still referencing a member is PLATFORM-side, and the
    -- operator needs to know which one.
    RAISE EXCEPTION 'cannot delete tenant "%": a platform-side record still references one of its members after the cascade. Reassign or remove it first. [%]', v_t.slug, sqlerrm;
  END;

  -- ── step 7: sweep the two tables the cascade REFILLED ────────────────────
  -- Not a belt-and-braces duplicate of the cascade: these rows did not exist
  -- when step 6 began. log_remote_access_write() fires AFTER DELETE on 77
  -- tenant tables and, because the caller is platform staff with no tenant of
  -- their own, writes old_data = to_jsonb(OLD) for every row the cascade just
  -- removed. This is where the 153 orphan rows measured in production came
  -- from. Must run after step 6, and these two tables have no DELETE trigger
  -- of their own, so this does not recurse.
  DELETE FROM remote_access_write_log WHERE tenant_id = p_tenant_id;
  DELETE FROM tenant_activity_log     WHERE tenant_id = p_tenant_id;

  -- ── step 8: verify, or undo everything ───────────────────────────────────
  SELECT coalesce(jsonb_object_agg(table_name, remaining_rows)
                    FILTER (WHERE remaining_rows > 0 AND counts_as_residue), '{}'::jsonb),
         coalesce(sum(remaining_rows) FILTER (WHERE counts_as_residue), 0)::bigint
    INTO v_after, v_rows_after
    FROM tenant_rows_remaining(p_tenant_id);

  -- profiles cannot be checked by the tenant_id-keyed sweep above, because the
  -- cascade SET NULL blanks tenant_id — a surviving member reads as zero residue
  -- while still holding their full_name. That is exactly the laundering
  -- described in (C) at the top of this file, so it gets its own check keyed on
  -- the identities captured in step 5.
  IF EXISTS (SELECT 1 FROM profiles WHERE user_id = ANY(v_members)) THEN
    RAISE EXCEPTION 'deletion of "%" is INCOMPLETE — % of % member profile(s) survived. Nothing was deleted; the transaction has been rolled back.',
      v_t.slug,
      (SELECT count(*) FROM profiles WHERE user_id = ANY(v_members)),
      coalesce(array_length(v_members, 1), 0);
  END IF;

  IF v_rows_after > 0 THEN
    -- All-or-nothing on purpose. A partial deletion that returned ok:true is
    -- the exact failure this migration exists to remove, and rolling back
    -- leaves a suspended tenant that can be retried once the gap is fixed.
    RAISE EXCEPTION 'deletion of "%" is INCOMPLETE — % row(s) survived in %. Nothing was deleted; the transaction has been rolled back. Add coverage for those tables and retry.',
      v_t.slug, v_rows_after, v_after;
  END IF;

  -- ── step 9: the receipt (inserted after the sweep, so it is never counted)─
  INSERT INTO tenant_deletion_receipts (
    tenant_id, tenant_slug, tenant_name, deleted_by, deleted_by_name,
    tables_swept, rows_removed, per_table_removed, residual_after, verified, notes)
  VALUES (
    p_tenant_id, v_t.slug, v_t.name, auth.uid(), coalesce(v_actor, 'platform operator'),
    v_tables, v_rows_before, v_before, '{}'::jsonb, true,
    'Verified by tenant_rows_remaining() after deletion: 0 residual rows across '
      || v_tables || ' tenant-scoped tables. NOT covered by this receipt: auth.users '
      || 'login rows (auth schema, outside this database''s public FK graph), Supabase '
      || 'Storage objects, and any off-database backups, logs or third-party systems.')
  RETURNING id INTO v_receipt;

  RETURN jsonb_build_object(
    'ok', true,
    'deleted_tenant', p_tenant_id,
    'name', v_t.name,
    'slug', v_t.slug,
    'receipt_id', v_receipt,
    'tables_swept', v_tables,
    'rows_removed', v_rows_before,
    'profiles_removed', v_profiles,
    'residual_rows', 0,
    'not_covered', jsonb_build_array(
      'auth.users login rows (auth schema)',
      'Supabase Storage objects',
      'off-database backups, logs and third-party systems')
  );
END $function$;

CREATE OR REPLACE FUNCTION public.deprovision_starter_de_internal(p_tenant_id uuid, p_feature_key text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_catalog_id text;
  v_source_cat text;
  v_de_id      uuid;
begin
  v_catalog_id := case p_feature_key when 'account_de' then 'starter_account_de' when 'finance_de' then 'starter_finance_de' else null end;
  v_source_cat := case p_feature_key when 'account_de' then 'crm' when 'finance_de' then 'erp_financials' else null end;
  if v_catalog_id is null then
    return; -- not a DE-provisioning feature — nothing to do
  end if;

  select id into v_de_id from digital_employees where tenant_id = p_tenant_id and catalog_id = v_catalog_id;
  if v_de_id is null then
    return; -- never provisioned — honest no-op
  end if;

  update digital_employees set status = 'disabled', lifecycle_status = 'paused' where id = v_de_id;

  update de_playbook_charter set active = false
  where tenant_id = p_tenant_id and de_id = v_de_id;

  update playbook_event_rules set active = false
  where tenant_id = p_tenant_id
    and definition_id in (select playbook_id from de_playbook_charter where de_id = v_de_id);

  update de_autonomy set enabled = false
  where tenant_id = p_tenant_id and action_type = 'action_execute' and source_category = v_source_cat;

  perform append_audit_event_internal(
    p_tenant_id, 'DreamTeam', 'system',
    format('Starter Digital Employee paused (feature "%s" turned off) — its playbook and autonomy were disabled; access grants and history were kept, not deleted.', p_feature_key),
    'config_change',
    jsonb_build_object('kind', 'feature_de_deprovisioned', 'feature_key', p_feature_key, 'de_id', v_de_id)
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.derive_de_autonomy_dials(p_de_id uuid)
 RETURNS TABLE(action_type text, source_category text, label text, description text, configured boolean, enabled boolean, max_amount_cents bigint, min_confidence integer)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with de as (
    select d.id, d.tenant_id from digital_employees d
    where d.id = p_de_id and d.tenant_id = auth_tenant_id()
  ),
  cats as (
    select distinct g.resource_category as cat
    from data_access_grants g join de on g.subject_id = de.id
    where g.subject_kind = 'de' and g.resource_category is not null
  )
  select
    ('action:' || c.cat)::text                         as action_type,
    c.cat::text                                        as source_category,
    (coalesce(sc.label, c.cat) || ' actions')::text    as label,
    sc.description                                     as description,
    (a.id is not null)                                 as configured,
    coalesce(a.enabled, false)                         as enabled,
    a.max_amount_cents,
    a.min_confidence
  from cats c
  cross join de
  left join system_categories sc on sc.key = c.cat
  left join de_autonomy a
    on a.tenant_id = de.tenant_id and a.de_id = de.id
   and a.action_type = 'action:' || c.cat
   and a.playbook_id is null
  order by coalesce(sc.label, c.cat);
$function$;

CREATE OR REPLACE FUNCTION public.detach_compliance_pack(p_tenant_id uuid, p_pack_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_pack_name    text;
  v_rules        jsonb;
  v_retired      integer := 0;
  v_already      integer := 0;
  v_was_attached boolean := false;
begin
  if auth.uid() is null then
    raise exception 'not authenticated: taking a compliance pack off removes blocking rules from every employee in this workspace, and the record has to say who did it';
  end if;

  -- The tenant comes off the caller's OWN profile row matched against the
  -- parameter — a tenant id supplied by the caller is not authorisation
  -- (migrations 662-664). No `p.layer = 'platform'` disjunct, and no
  -- service_role arm: see the header for both.
  if not exists (
    select 1 from profiles p
     where p.user_id = auth.uid()
       and coalesce(p.is_active, true)
       and p.tenant_id = p_tenant_id
       and p.role in ('tenant_owner', 'tenant_admin')
  ) then
    raise exception 'only this workspace''s owners and admins can take a compliance pack off';
  end if;

  select name into v_pack_name from compliance_packs where key = p_pack_key;
  if v_pack_name is null then
    raise exception 'unknown compliance pack %', p_pack_key;
  end if;

  -- Frozen BEFORE anything changes. After the update these rows still exist but
  -- read as retired; the point of the copy is what they SAID while they applied.
  select coalesce(jsonb_agg(jsonb_build_object(
           'rule_id',  g.id,   'rule',      g.rule,
           'rule_type', g.rule_type, 'pattern', g.pattern,
           'threshold', g.threshold,
           'severity', g.severity, 'applies_to', g.applies_to,
           'scope',    g.scope, 'scope_ref', g.scope_ref,
           'version',  g.version) order by g.rule), '[]'::jsonb)
    into v_rules
    from guardrail_rules g
   where g.tenant_id = p_tenant_id
     and g.compliance_pack_key = p_pack_key
     and g.retired_at is null;

  select count(*) into v_already
    from guardrail_rules g
   where g.tenant_id = p_tenant_id
     and g.compliance_pack_key = p_pack_key
     and g.retired_at is not null;

  -- Transaction-local sanction for trg_guard_compliance_guardrails.
  perform set_config('app.allow_compliance_change', 'on', true);

  -- ⚠ RETIRE, NOT DELETE (migration 726). active = false is what stops
  -- enforcement — every reader filters on it, and guardrail_rules_for_de filters
  -- on retired_at too. retired_at is the filing decision, and it is what lets a
  -- guardrail_block recorded months ago still point at something.
  update guardrail_rules
     set retired_at = now(),
         retired_by = auth.uid(),
         active     = false,
         version    = version + 1
   where tenant_id = p_tenant_id
     and compliance_pack_key = p_pack_key
     and retired_at is null;
  get diagnostics v_retired = row_count;

  with d as (
    delete from tenant_compliance_packs
     where tenant_id = p_tenant_id and pack_key = p_pack_key
    returning 1)
  select count(*) > 0 into v_was_attached from d;

  -- ⚠ SHUT THE GATE. set_config(..., true) lasts the whole TRANSACTION, not the
  -- statement — leaving it open would let anything later in the same transaction
  -- delete or deactivate a pack rule with no gate at all. Probe 9 fires a bare
  -- DELETE right after this returns and requires it to be refused.
  perform set_config('app.allow_compliance_change', 'off', true);

  if v_retired > 0 or v_was_attached then
    perform public.append_audit_event(
      p_tenant_id, 'You', 'human',
      format('Compliance pack removed — %s. %s blocking rule(s) stopped applying to every employee in this workspace.',
             v_pack_name, v_retired),
      'config_change',
      jsonb_build_object(
        'event',                 'compliance_pack_detached',
        'pack_key',              p_pack_key,
        'pack_name',             v_pack_name,
        'rules_retired',         v_retired,
        'rules_already_retired', v_already,
        'was_attached',          v_was_attached,
        'rules',                 v_rules,
        'detached_by',           auth.uid()));
  end if;

  return jsonb_build_object(
    'ok',                    true,
    'pack_key',              p_pack_key,
    'pack_name',             v_pack_name,
    'rules_retired',         v_retired,
    'rules_already_retired', v_already,
    'was_attached',          v_was_attached);
end;
$function$;

CREATE OR REPLACE FUNCTION public.detect_de_incidents_internal(p_tenant_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_inserted integer := 0;
  v_count integer;
begin
  -- 1. Guardrail blocks from the triage pipeline (best attribution:
  --    evidence_runs.de_id).
  insert into de_incidents (tenant_id, de_id, kind, severity, title, detail, source_table, source_id, occurred_at)
  select d.tenant_id, er.de_id, 'guardrail_block', 'warning',
    'Guardrail blocked an automatic action',
    jsonb_build_object('reasoning', left(d.reasoning, 400), 'guardrail_rule_id', d.guardrail_rule_id,
                       'external_ref', d.external_ref, 'source_category', d.source_category,
                       'evidence_run_id', d.evidence_run_id),
    'evidence_run_decisions', d.id, d.created_at
  from evidence_run_decisions d
  join evidence_runs er on er.id = d.evidence_run_id
  where d.decision = 'blocked_guardrail'
    and d.created_at > now() - interval '30 days'
    and (p_tenant_id is null or d.tenant_id = p_tenant_id)
    and tenant_is_operational(d.tenant_id)
  on conflict (tenant_id, source_table, source_id) do nothing;
  get diagnostics v_count = row_count; v_inserted := v_inserted + v_count;

  -- 2. Guardrail blocks recorded straight to the audit trail (widget/
  --    chat answers withheld). Attribution by actor name — the same
  --    semantics the old profile tab used, now persisted once.
  insert into de_incidents (tenant_id, de_id, kind, severity, title, detail, source_table, source_id, occurred_at)
  select a.tenant_id,
    (select de.id from digital_employees de
     where de.tenant_id = a.tenant_id and (de.name = a.actor or de.persona_name = a.actor)
     limit 1),
    'guardrail_block', 'warning',
    'Guardrail withheld an answer',
    jsonb_build_object('action', left(a.action, 400), 'rule', a.detail->>'rule', 'channel', a.detail->>'channel'),
    'audit_events', a.id, a.created_at
  from audit_events a
  where a.category = 'guardrail_block'
    and a.created_at > now() - interval '30 days'
    and (p_tenant_id is null or a.tenant_id = p_tenant_id)
    and tenant_is_operational(a.tenant_id)
  on conflict (tenant_id, source_table, source_id) do nothing;
  get diagnostics v_count = row_count; v_inserted := v_inserted + v_count;

  -- 3. Automatic trust demotions (migration 025's "demote fast" path).
  insert into de_incidents (tenant_id, de_id, kind, severity, title, detail, source_table, source_id, occurred_at)
  select a.tenant_id,
    nullif(a.detail->>'de_id', '')::uuid,
    'trust_demotion', 'critical',
    'Trust level automatically demoted',
    jsonb_build_object('action', left(a.action, 400), 'action_category', a.detail->>'action_category',
                       'policy_id', a.detail->>'policy_id'),
    'audit_events', a.id, a.created_at
  from audit_events a
  where a.detail->>'kind' = 'trust_demoted'
    and a.created_at > now() - interval '30 days'
    and (p_tenant_id is null or a.tenant_id = p_tenant_id)
    and tenant_is_operational(a.tenant_id)
  on conflict (tenant_id, source_table, source_id) do nothing;
  get diagnostics v_count = row_count; v_inserted := v_inserted + v_count;

  -- 4. Failed eval runs (tenant-level: no single attributable DE).
  insert into de_incidents (tenant_id, de_id, kind, severity, title, detail, source_table, source_id, occurred_at)
  select r.tenant_id, null,
    'eval_regression', 'warning',
    format('Golden QA run failed — %s of %s passed', r.passed, r.total),
    jsonb_build_object('run_id', r.id, 'passed', r.passed, 'failed', r.failed, 'trigger', r.trigger),
    'eval_runs', r.id, coalesce(r.finished_at, r.started_at)
  from eval_runs r
  where r.status = 'failed'
    and coalesce(r.finished_at, r.started_at) > now() - interval '30 days'
    and (p_tenant_id is null or r.tenant_id = p_tenant_id)
    and tenant_is_operational(r.tenant_id)
  on conflict (tenant_id, source_table, source_id) do nothing;
  get diagnostics v_count = row_count; v_inserted := v_inserted + v_count;

  -- 5. Humans rejecting a proposed action (a draft the DE got wrong).
  insert into de_incidents (tenant_id, de_id, kind, severity, title, detail, source_table, source_id, occurred_at)
  select t.tenant_id,
    case when ae.subject_kind = 'de' then ae.subject_id else null end,
    'action_rejected', 'info',
    format('Proposed action rejected by a human — %s', left(t.title, 120)),
    jsonb_build_object('task_id', t.id, 'request_summary', left(ae.request_summary, 300), 'decided_at', t.decided_at),
    'human_tasks', t.id, coalesce(t.decided_at, t.created_at)
  from human_tasks t
  join action_executions ae on ae.task_id = t.id
  where t.type = 'action_approval' and t.status = 'rejected'
    and coalesce(t.decided_at, t.created_at) > now() - interval '30 days'
    and (p_tenant_id is null or t.tenant_id = p_tenant_id)
    and tenant_is_operational(t.tenant_id)
  on conflict (tenant_id, source_table, source_id) do nothing;
  get diagnostics v_count = row_count; v_inserted := v_inserted + v_count;

  return jsonb_build_object('inserted', v_inserted);
end;
$function$;

CREATE OR REPLACE FUNCTION public.detect_exceptions(p_tenant_id uuid, p_workspace_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_caller uuid;
  v_period_end date;
  v_count int := 0;
begin
  v_caller := auth_tenant_id();
  if v_caller is distinct from p_tenant_id and not is_platform_admin() then
    raise exception 'tenant mismatch';
  end if;

  select period_end into v_period_end from public.close_workspaces where id = p_workspace_id and tenant_id = p_tenant_id;

  delete from public.exceptions where tenant_id = p_tenant_id and workspace_id = p_workspace_id and status = 'open';

  -- 1) UNMATCHED BANK TRANSACTIONS
  insert into public.exceptions(tenant_id, workspace_id, exception_type, severity, title, detail, amount, account_id, ref_table, ref_id, ai_reasoning, confidence, proposed_action, is_risky, status)
  select p_tenant_id, p_workspace_id, 'unmatched_bank_txn',
    case when abs(bt.amount) >= 10000 then 'high' when abs(bt.amount) >= 1000 then 'medium' else 'low' end,
    'Unmatched bank transaction: '||left(bt.description,40),
    'Bank line of '||bt.amount||' on '||bt.txn_date||' has no matching payment record.',
    bt.amount, bt.account_id, 'bank_transactions', bt.id,
    'No payment row links to this bank line; it is uncleared in the ledger.',
    0.82, 'Investigate and match to a payment, or create an adjusting entry.', false, 'open'
  from public.bank_transactions bt
  where bt.tenant_id = p_tenant_id and bt.workspace_id = p_workspace_id and bt.is_matched = false and bt.matched_payment_id is null;

  -- 2) DUPLICATE BILLS (same vendor + amount; flag the later one only)
  insert into public.exceptions(tenant_id, workspace_id, exception_type, severity, title, detail, amount, account_id, ref_table, ref_id, ai_reasoning, confidence, proposed_action, is_risky, status)
  select p_tenant_id, p_workspace_id, 'duplicate_invoice', 'high',
    'Possible duplicate bill: '||b.bill_number,
    'Another bill with the same vendor and amount ('||b.amount||') exists in this period.',
    b.amount, b.account_id, 'bills', b.id,
    'Two bills share vendor_id and amount within the same close window, a strong duplicate signal.',
    0.88, 'Confirm whether this is a true duplicate before payment; void if confirmed.', true, 'open'
  from public.bills b
  where b.tenant_id = p_tenant_id and b.workspace_id = p_workspace_id
    and exists (
      select 1 from public.bills b2 where b2.tenant_id = b.tenant_id and b2.workspace_id = b.workspace_id
        and b2.id <> b.id and b2.vendor_id = b.vendor_id and b2.amount = b.amount
        and b2.id::text < b.id::text
    );

  -- 3) MISSING RECEIPTS
  insert into public.exceptions(tenant_id, workspace_id, exception_type, severity, title, detail, amount, account_id, ref_table, ref_id, ai_reasoning, confidence, proposed_action, is_risky, status)
  select p_tenant_id, p_workspace_id, 'missing_receipt',
    case when b.amount >= 5000 then 'high' else 'medium' end,
    'Missing receipt: '||b.bill_number,
    'Bill of '||b.amount||' has no supporting receipt attached.',
    b.amount, b.account_id, 'bills', b.id,
    'has_receipt is false; audit evidence is incomplete for this expense.',
    0.79, 'Request and attach the receipt before close.', false, 'open'
  from public.bills b
  where b.tenant_id = p_tenant_id and b.workspace_id = p_workspace_id and b.has_receipt = false;

  -- 4) UNUSUAL SPEND
  insert into public.exceptions(tenant_id, workspace_id, exception_type, severity, title, detail, amount, account_id, ref_table, ref_id, ai_reasoning, confidence, proposed_action, is_risky, status)
  select p_tenant_id, p_workspace_id, 'unusual_spend', 'high',
    'Unusual spend: '||left(bt.description,40),
    'Large outbound transfer of '||bt.amount||' on '||bt.txn_date||
      case when extract(dow from bt.txn_date) in (0,6) then ' (weekend)' else '' end||
      case when (abs(bt.amount)::numeric % 1000) = 0 then ' (round-number)' else '' end||'.',
    bt.amount, bt.account_id, 'bank_transactions', bt.id,
    'Outbound amount far exceeds typical spend'||
      case when extract(dow from bt.txn_date) in (0,6) then '; posted on a weekend' else '' end||
      case when (abs(bt.amount)::numeric % 1000) = 0 then '; exact round number' else '' end||
      ', elevating fraud/error risk.',
    case when extract(dow from bt.txn_date) in (0,6) or (abs(bt.amount)::numeric % 1000)=0 then 0.86 else 0.74 end,
    'Verify authorization and supporting documentation; do not auto-clear.', true, 'open'
  from public.bank_transactions bt
  where bt.tenant_id = p_tenant_id and bt.workspace_id = p_workspace_id
    and bt.amount <= -10000;

  -- 5) LATE CUSTOMER PAYMENTS
  insert into public.exceptions(tenant_id, workspace_id, exception_type, severity, title, detail, amount, account_id, ref_table, ref_id, ai_reasoning, confidence, proposed_action, is_risky, status)
  select p_tenant_id, p_workspace_id, 'late_customer_payment',
    case when (coalesce(v_period_end, current_date) - i.due_date) >= 60 then 'high'
         when (coalesce(v_period_end, current_date) - i.due_date) >= 30 then 'medium' else 'low' end,
    'Overdue receivable: '||i.invoice_number,
    'Invoice '||i.invoice_number||' of '||(i.amount - i.amount_paid)||' is '||
      (coalesce(v_period_end, current_date) - i.due_date)||' days past due.',
    (i.amount - i.amount_paid), null, 'invoices', i.id,
    'Due date passed with outstanding balance; aging increases collection risk.',
    0.9, 'Send dunning reminder / escalate to collections.', false, 'open'
  from public.invoices i
  where i.tenant_id = p_tenant_id and i.workspace_id = p_workspace_id
    and i.status in ('open','partial','overdue')
    and i.amount_paid < i.amount
    and i.due_date < coalesce(v_period_end, current_date);

  -- 6) UNCATEGORIZED
  insert into public.exceptions(tenant_id, workspace_id, exception_type, severity, title, detail, amount, account_id, ref_table, ref_id, ai_reasoning, confidence, proposed_action, is_risky, status)
  select p_tenant_id, p_workspace_id, 'uncategorized_txn', 'low',
    'Uncategorized transaction: '||left(bt.description,40),
    'Bank line of '||bt.amount||' on '||bt.txn_date||' has no category assigned.',
    bt.amount, bt.account_id, 'bank_transactions', bt.id,
    'category is null; cannot be posted to the correct GL account without coding.',
    0.7, 'Assign a GL category for proper classification.', false, 'open'
  from public.bank_transactions bt
  where bt.tenant_id = p_tenant_id and bt.workspace_id = p_workspace_id and bt.category is null;

  -- 7) REVENUE / PAYMENT MISMATCH
  insert into public.exceptions(tenant_id, workspace_id, exception_type, severity, title, detail, amount, account_id, ref_table, ref_id, ai_reasoning, confidence, proposed_action, is_risky, status)
  select p_tenant_id, p_workspace_id, 'revenue_payment_mismatch', 'medium',
    'Revenue/payment mismatch: '||i.invoice_number,
    'Invoice '||i.invoice_number||' status is '''||i.status||''' but amount_paid ('||i.amount_paid||') does not reconcile to amount ('||i.amount||').',
    (i.amount - i.amount_paid), null, 'invoices', i.id,
    'Status/paid amount inconsistency indicates a posting drift between AR and cash.',
    0.81, 'Reconcile the applied payments against the invoice balance.', false, 'open'
  from public.invoices i
  where i.tenant_id = p_tenant_id and i.workspace_id = p_workspace_id
    and ((i.status = 'paid' and i.amount_paid <> i.amount) or (i.amount_paid > i.amount));

  select count(*) into v_count from public.exceptions
    where tenant_id = p_tenant_id and workspace_id = p_workspace_id and status = 'open';
  return v_count;
end;
$function$;

CREATE OR REPLACE FUNCTION public.detect_trust_widening_patterns(p_tenant_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(tenant_id uuid, de_id uuid, de_name text, action_definition_id uuid, action_key text, action_label text, policy_id uuid, policy_category text, current_level integer, proposed_level integer, window_days integer, n_approved bigint, first_decided timestamp with time zone, last_decided timestamp with time zone, evidence jsonb)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
with decided as (
  -- (1)(2)(3): every decided approval with its gate execution and action,
  -- once per task; production evidence only; operational tenants only.
  select ht.id as task_id, ht.tenant_id as t_id, ht.de_id as d_id,
         ht.status as t_status, ht.decided_at, ht.decided_by,
         g.ad_id, g.g_action_key, g.g_label, g.g_category, g.g_destructive
    from human_tasks ht
    join lateral (
      select ae.action_definition_id as ad_id, ad.action_key as g_action_key,
             ad.label as g_label, ad.category as g_category,
             coalesce((ad.risk->>'destructive')::boolean, false) as g_destructive
        from action_executions ae
        join action_definitions ad on ad.id = ae.action_definition_id
       where (ae.task_id = ht.id or ae.resolves_task_id = ht.id)
         and ae.decision like 'human_gated%'
       order by ae.created_at desc
       limit 1
    ) g on true
   where ht.type = 'action_approval'
     and ht.status in ('approved', 'rejected')
     and ht.decided_at is not null
     and ht.de_id is not null
     and public.evidence_is_production(ht.origin)
     and public.tenant_is_operational(ht.tenant_id)
     and (p_tenant_id is null or ht.tenant_id = p_tenant_id)
),
clean as (
  -- (5): carried out AND landed, through THE shared predicate; nothing
  -- rolled back, failed, or contradicted. Both linkage columns, always —
  -- resolves_task_id was unpopulated before August (mig 642).
  select d.*,
         (d.t_status = 'approved'
          and exists (select 1 from action_executions ex
                       where (ex.task_id = d.task_id or ex.resolves_task_id = d.task_id)
                         and public.action_execution_landed(ex))
          and not exists (select 1 from action_executions ex
                           where (ex.task_id = d.task_id or ex.resolves_task_id = d.task_id)
                             and (ex.rolled_back_at is not null
                               or ex.decision = 'failed'
                               or coalesce(ex.result #>> array['ok'], 'true') = 'false'))
         ) as is_clean,
         (select max(ex.rolled_back_at) from action_executions ex
           where (ex.task_id = d.task_id or ex.resolves_task_id = d.task_id)) as rb_at
    from decided d
),
grp as (
  -- (4): destructive actions never reach a proposal — the destructive gate
  -- sits above the dial and a widened dial would open nothing.
  select c.t_id, c.d_id, c.ad_id,
         max(c.g_action_key) as g_action_key, max(c.g_label) as g_label,
         max(c.g_category) as g_category,
         greatest(
           coalesce(max(c.decided_at) filter (where c.t_status = 'rejected'), '-infinity'::timestamptz),
           coalesce(max(c.rb_at), '-infinity'::timestamptz)
         ) as base_reset
    from clean c
   group by c.t_id, c.d_id, c.ad_id
  having not bool_or(c.g_destructive)
),
pol as (
  -- (9), mig 711: the governing policy — employee-scoped, active,
  -- SPECIFIC-FIRST AMONG ELIGIBLE CANDIDATES. 710 stopped at the most
  -- specific candidate even when its evidence model is approval-blind
  -- (trust_evidence_for's else-branch), which starved the seam; the ladder
  -- proposed must be the ladder the evidence actually climbs. Eligibility
  -- (mig 692's form) already folds in status, ceiling and every criterion,
  -- and apply_trust_promotion re-verifies the SAME test at apply time.
  select g.*, p.id as pol_id, p.action_category as pol_cat,
         p.current_level as cur_level, least(3, coalesce(p.max_level, 3)) as ceiling,
         coalesce((p.criteria->>'window_days')::integer, 30) as win
    from grp g
    join lateral (
      select tp.* from trust_policies tp
       where tp.tenant_id = g.t_id and tp.de_id = g.d_id and tp.status = 'active'
         and (tp.action_category = g.g_action_key
           or tp.action_category = 'action:' || coalesce(g.g_category, '')
           or (tp.action_category = 'action_execute'
               and (tp.source_category is null or tp.source_category = g.g_category)))
         and coalesce((trust_evidence_for(tp)->>'eligible')::boolean, false)
       order by case
           when tp.action_category = g.g_action_key then 0
           when tp.action_category = 'action:' || coalesce(g.g_category, '') then 1
           when tp.source_category = g.g_category then 2
           else 3 end
       limit 1
    ) p on true
   -- ONE open proposal per group across the WHOLE candidate chain: an open
   -- proposal on ANY candidate (even an approval-blind one a human
   -- requested) blocks — first-eligible must never manufacture a second
   -- proposal about the same repeated action.
   where not exists (
     select 1 from trust_policies tpx
      join human_tasks hx on hx.id = tpx.pending_task_id and hx.status = 'pending'
     where tpx.tenant_id = g.t_id and tpx.de_id = g.d_id and tpx.status = 'active'
       and (tpx.action_category = g.g_action_key
         or tpx.action_category = 'action:' || coalesce(g.g_category, '')
         or (tpx.action_category = 'action_execute'
             and (tpx.source_category is null or tpx.source_category = g.g_category))))
),
reset_full as (
  -- (6): the void-reset moment — a decline of a prior proposal on ANY
  -- candidate policy in the chain restarts the pattern, alongside
  -- rejections and rollbacks. The founder's recent "no" about widening
  -- this employee on this work holds whichever rung carried it.
  select p.*, greatest(p.base_reset,
    coalesce((select max(h.decided_at)
                from human_tasks h
                join trust_policies tpr on tpr.id = h.related_id
               where h.type = 'trust_promotion' and h.related_table = 'trust_policies'
                 and h.status = 'rejected'
                 and tpr.tenant_id = p.t_id and tpr.de_id = p.d_id
                 and (tpr.action_category = p.g_action_key
                   or tpr.action_category = 'action:' || coalesce(p.g_category, '')
                   or (tpr.action_category = 'action_execute'
                       and (tpr.source_category is null or tpr.source_category = p.g_category)))),
             '-infinity'::timestamptz)
  ) as reset_ts
    from pol p
),
counted as (
  -- (7): count clean approvals after the reset, inside the policy's window,
  -- and carry the full citation — task, decider, timestamp, landed receipt.
  select r.*, w.n_ok, w.first_ok, w.last_ok, w.decisions
    from reset_full r
    cross join lateral (
      select count(*) as n_ok,
             min(c.decided_at) as first_ok,
             max(c.decided_at) as last_ok,
             jsonb_agg(jsonb_build_object(
               'task_id', c.task_id,
               'decided_at', c.decided_at,
               'decided_by', c.decided_by,
               'decided_by_name', coalesce(
                 (select pr.full_name from profiles pr where pr.user_id = c.decided_by),
                 'a teammate'),
               'receipt', (select left(coalesce(nullif(btrim(ex.receipt), ''), '(result recorded)'), 160)
                             from action_executions ex
                            where (ex.task_id = c.task_id or ex.resolves_task_id = c.task_id)
                              and public.action_execution_landed(ex)
                            order by ex.created_at desc limit 1)
             ) order by c.decided_at) as decisions
        from clean c
       where c.t_id = r.t_id and c.d_id = r.d_id and c.ad_id = r.ad_id
         and c.is_clean
         and c.decided_at > r.reset_ts
         and c.decided_at >= now() - make_interval(days => r.win)
    ) w
)
-- (8) the N, and (10) the chosen ladder's evidence bar re-checked whole.
-- `k.n_ok >= 3` IS the pattern floor — the Ring-0 probe pins this exact
-- token; changing N means changing it here AND there, out loud.
select k.t_id, k.d_id,
       coalesce(de.persona_name, de.name),
       k.ad_id, k.g_action_key, k.g_label,
       k.pol_id, k.pol_cat, k.cur_level,
       least(k.cur_level + 1, k.ceiling),
       k.win, k.n_ok, k.first_ok, k.last_ok,
       jsonb_build_object(
         'pattern', jsonb_build_object(
           'action_key', k.g_action_key,
           'action_definition_id', k.ad_id,
           'n_approved', k.n_ok,
           'window_days', k.win,
           'reset_at', case when k.reset_ts > '-infinity'::timestamptz
                            then to_jsonb(k.reset_ts) else 'null'::jsonb end,
           'decisions', k.decisions),
         'dial', jsonb_build_object(
           'current_level', k.cur_level,
           'proposed_level', least(k.cur_level + 1, k.ceiling),
           'current_settings', (select trust_ladder_settings(tp, k.cur_level)
                                  from trust_policies tp where tp.id = k.pol_id),
           'proposed_settings', (select trust_ladder_settings(tp, least(k.cur_level + 1, k.ceiling))
                                   from trust_policies tp where tp.id = k.pol_id)),
         'policy_evidence', (select trust_evidence_for(tp)
                               from trust_policies tp where tp.id = k.pol_id))
  from counted k
  join digital_employees de on de.id = k.d_id
 where k.n_ok >= 3
   and k.cur_level < k.ceiling
   and coalesce(((select trust_evidence_for(tp) from trust_policies tp
                   where tp.id = k.pol_id)->>'eligible')::boolean, false)
$function$;

CREATE OR REPLACE FUNCTION public.discovery_coverage_states_valid(p_coverage jsonb)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select not jsonb_path_exists(p_coverage,
    '$.*.state ? (@.type() != "string" || (@ != "heard" && @ != "parked" && @ != "skipped" && @ != "not_heard"))');
$function$;

CREATE OR REPLACE FUNCTION public.dismiss_platform_kb_change(p_change_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  -- Prefix deleted. Same reachability note as publish_platform_shelf_doc.
  IF NOT public.is_platform_admin() THEN
    RAISE EXCEPTION 'only platform administrators can manage the shelf review queue';
  END IF;
  IF p_reason IS NULL OR length(btrim(p_reason)) < 10 THEN
    RAISE EXCEPTION 'say why this change needs no documentation update';
  END IF;
  UPDATE platform_kb_changes
     SET status = 'dismissed', dismiss_reason = btrim(p_reason),
         reviewed_at = now(), reviewed_by = auth.uid()
   WHERE id = p_change_id;
END $function$;

CREATE OR REPLACE FUNCTION public.dismiss_playbook_gap(p_gap_id uuid, p_note text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_gap    playbook_gaps;
  v_tenant uuid := public.auth_tenant_id();
  v_uid    uuid := auth.uid();
  v_actor  text;
begin
  if v_tenant is null or v_uid is null then
    raise exception 'not_authenticated';
  end if;
  if not public.auth_has_tenant_role(array['tenant_owner','tenant_admin']) then
    raise exception 'dismissing_requires_owner_or_admin';
  end if;
  select * into v_gap from playbook_gaps
   where id = p_gap_id and tenant_id = v_tenant
   for update;
  if v_gap.id is null then
    raise exception 'gap_not_found';
  end if;
  if v_gap.status in ('resolved', 'dismissed') then
    raise exception 'gap_already_closed: %', v_gap.status;
  end if;

  update playbook_gaps
     set status = 'dismissed', dismissed_by = v_uid, dismissed_at = now()
   where id = v_gap.id;

  select coalesce(nullif(full_name, ''), 'A workspace member') into v_actor
    from profiles where user_id = v_uid limit 1;
  perform append_audit_event(
    v_tenant, coalesce(v_actor, 'A workspace member'), 'human',
    format('Playbook gap dismissed — %s "%s" (%s)%s', v_gap.kind, v_gap.title, v_gap.gap_key,
      case when coalesce(p_note, '') <> '' then ': ' || left(p_note, 300) else '' end),
    'config_change',
    jsonb_build_object('kind', 'playbook_gap_dismissed', 'gap_id', v_gap.id,
      'definition_id', v_gap.definition_id, 'gap_kind', v_gap.kind,
      'gap_key', v_gap.gap_key, 'note', coalesce(p_note, ''))
  );
  return jsonb_build_object('ok', true, 'gap_id', v_gap.id, 'status', 'dismissed');
end $function$;

CREATE OR REPLACE FUNCTION public.dispatch_de_fitness_measure_internal()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_secret text;
  v_anon   text := coalesce((select value from platform_runtime_config where key = 'supabase_anon_key'), 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6InJmc3ZtaGNxZWl5cnhpdmJtcGVsIiwicm9sZSI6ImFub24iLCJpYXQiOjE3ODIxMzIwMDgsImV4cCI6MjA5NzcwODAwOH0.RKCWute2ypkx9X-ByumIQWw8MS5uQPco-i-asNa-ESg');
begin
  -- Gate: no work + no wasted post while the feature is off.
  if coalesce((select value from platform_config where key = 'amendment_fitness.enabled'), 'false') <> 'true' then
    return 'amendment_fitness disabled';
  end if;
  select decrypted_secret into v_secret from vault.decrypted_secrets where name = 'playbook_dispatch_secret';
  if v_secret is null then return 'no dispatch secret'; end if;

  -- One amendment per tick (the fn picks the oldest unmeasured applied 'de').
  perform net.http_post(
    url     := public.platform_fn_url('/functions/v1/de-fitness-measure'),
    body    := '{}'::jsonb,
    headers := jsonb_build_object(
                 'Content-Type', 'application/json',
                 'Authorization', 'Bearer ' || v_anon,
                 'x-dispatch-secret', v_secret
               )
  , timeout_milliseconds := 60000);
  return 'de-fitness-measure dispatched (async)';
end;
$function$;

CREATE OR REPLACE FUNCTION public.dispatch_de_improve_internal()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_secret text;
  v_anon   text := coalesce((select value from platform_runtime_config where key = 'supabase_anon_key'), 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6InJmc3ZtaGNxZWl5cnhpdmJtcGVsIiwicm9sZSI6ImFub24iLCJpYXQiOjE3ODIxMzIwMDgsImV4cCI6MjA5NzcwODAwOH0.RKCWute2ypkx9X-ByumIQWw8MS5uQPco-i-asNa-ESg');
  v_row    record;
  v_count  int := 0;
begin
  select decrypted_secret into v_secret from vault.decrypted_secrets where name = 'playbook_dispatch_secret';
  if v_secret is null then return 'no dispatch secret'; end if;

  -- Retryability: an infra-caused mid-replay failure (fail_closed) must not
  -- permanently burn a judgment. Clear such proposals older than 3 days so the
  -- candidate query re-picks their judgment for another pass. A genuine
  -- "answer could not be improved" that did NOT fail closed stays deduped.
  delete from de_improvements
   where status = 'failed_replay'
     and (replay->'golden'->>'failed_closed') = 'true'
     and updated_at < now() - interval '3 days';

  -- One oldest-unhandled below-standard judgment per tenant (FIFO fairness +
  -- sidesteps the edge fn's recency-window picker), skipping tenants that
  -- already have >= 3 open reviews (backpressure on the human queue), and only
  -- for active employees. Passing judgment_id makes each tick idempotent.
  for v_row in
    with pending as (
      select tenant_id, count(*) n from de_improvements
       where status = 'review_pending' group by tenant_id
    )
    select distinct on (j.tenant_id) j.tenant_id, j.id as judgment_id
      from eval_judgments j
      join digital_employees de on de.id = j.de_id
       and de.status = 'active'
       and de.lifecycle_status not in ('retired','archived')
      left join pending p on p.tenant_id = j.tenant_id
     where j.verdict in ('fail','partial')
       and j.score < 70
       and j.de_id is not null
       and coalesce(p.n, 0) < 3
       and tenant_is_operational(j.tenant_id)
       and not exists (select 1 from de_improvements di
                        where di.tenant_id = j.tenant_id and di.judgment_id = j.id)
     order by j.tenant_id, j.created_at asc
     limit 25
  loop
    -- per-iteration isolation: a bad row can never abort the global tick.
    begin
      perform net.http_post(
        url     := public.platform_fn_url('/functions/v1/de-improve'),
        body    := jsonb_build_object('tenant_id', v_row.tenant_id, 'judgment_id', v_row.judgment_id),
        headers := jsonb_build_object(
                     'Content-Type', 'application/json',
                     'Authorization', 'Bearer ' || v_anon,
                     'x-dispatch-secret', v_secret
                   )
      , timeout_milliseconds := 60000);
      v_count := v_count + 1;
    exception when others then
      raise warning 'de-improve dispatch failed for tenant % judgment %: %', v_row.tenant_id, v_row.judgment_id, sqlerrm;
    end;
  end loop;

  -- Honest: the posts are async; this counts dispatches, not improvements.
  return 'de-improve dispatched ' || v_count || ' http_post(s) (async)';
end;
$function$;

CREATE OR REPLACE FUNCTION public.dispatch_de_work_internal()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_secret text;
  v_anon   text := platform_anon_key();
  v_req_id bigint;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM de_work_items WHERE status = 'queued' AND scheduled_for <= now() AND tenant_is_operational(tenant_id))
     AND NOT EXISTS (SELECT 1 FROM de_objectives WHERE status IN ('open','in_progress','blocked') AND tenant_is_operational(tenant_id)
                       AND ( (next_wake_at IS NOT NULL AND next_wake_at <= now())
                             OR NOT EXISTS (SELECT 1 FROM de_work_items w WHERE w.objective_id = de_objectives.id) ))
  THEN
    RETURN 'idle — nothing due';
  END IF;

  SELECT decrypted_secret INTO v_secret FROM vault.decrypted_secrets WHERE name = 'playbook_dispatch_secret';
  IF v_secret IS NULL THEN
    PERFORM raise_ops_alert('dispatch_secret_missing',
      'playbook_dispatch_secret is missing from Vault — de-work items are queued but the work engine cron cannot run them.',
      jsonb_build_object('cron', 'dispatch_de_work_internal'));
    RETURN 'no dispatch secret';
  END IF;
  SELECT net.http_post(
    url := platform_fn_url('/functions/v1/de-work'),
    body := '{"action":"run","max_items":3}'::jsonb,
    headers := jsonb_build_object('Content-Type','application/json','Authorization','Bearer '||v_anon,'x-dispatch-secret',v_secret)
  , timeout_milliseconds := 60000) INTO v_req_id;
  RETURN 'de-work dispatched, req ' || v_req_id;
END;
$function$;

CREATE OR REPLACE FUNCTION public.dispatch_due_triggers(p_tenant_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_sched      record;
  v_rule       record;
  v_acct       record;
  v_inv        record;
  v_ticket     record;
  v_opp        record;
  v_pending    integer := 0;
  v_skipped    integer := 0;
  v_days       integer;
  v_priority   text;
  v_within     integer;
  v_recent     record;
  v_min_arr    bigint;
  v_min_amount bigint;
begin
  -- ── (a) due schedules — lowest DE-assigned priority first ──
  for v_sched in
    select s.*, d.status as def_status,
      coalesce((select min(a.priority) from de_playbook_charter a
                where a.playbook_id = s.definition_id and a.active), 1000) as charter_priority
    from playbook_schedules s
    join playbook_definitions d on d.id = s.definition_id
    where s.active
      and s.next_fire_at is not null
      and s.next_fire_at <= now()
      and (p_tenant_id is null or s.tenant_id = p_tenant_id)
      and tenant_is_operational(s.tenant_id)
    order by charter_priority asc, s.next_fire_at asc
    for update of s skip locked
  loop
    if v_sched.def_status <> 'published' then
      insert into playbook_trigger_fires (tenant_id, source, schedule_id, definition_id, status, detail)
      values (v_sched.tenant_id, 'schedule', v_sched.id, v_sched.definition_id, 'error',
              'definition is not published — schedule fired into the void');
      v_skipped := v_skipped + 1;
    elsif v_sched.account_selector->>'mode' = 'single' then
      insert into playbook_trigger_fires (tenant_id, source, schedule_id, definition_id, target_account_id, status, detail)
      values (v_sched.tenant_id, 'schedule', v_sched.id, v_sched.definition_id,
              (v_sched.account_selector->>'account_id')::uuid, 'pending_start',
              format('schedule due at %s (single account, charter priority %s)', v_sched.next_fire_at, v_sched.charter_priority));
      v_pending := v_pending + 1;
    else
      v_within := coalesce((v_sched.account_selector->>'renewal_within_days')::int, 60);
      for v_acct in
        select id from customer_accounts
        where tenant_id = v_sched.tenant_id
          and renewal_date is not null
          and renewal_date <= (current_date + v_within)
      loop
        insert into playbook_trigger_fires (tenant_id, source, schedule_id, definition_id, target_account_id, status, detail)
        values (v_sched.tenant_id, 'schedule', v_sched.id, v_sched.definition_id, v_acct.id, 'pending_start',
                format('schedule due at %s (renewal within %s days, charter priority %s)', v_sched.next_fire_at, v_within, v_sched.charter_priority));
        v_pending := v_pending + 1;
      end loop;
    end if;

    update playbook_schedules set last_fired_at = now() where id = v_sched.id;
  end loop;

  -- ── (b) event rules — lowest DE-assigned priority first ────
  for v_rule in
    select r.*, d.status as def_status,
      coalesce((select min(a.priority) from de_playbook_charter a
                where a.playbook_id = r.definition_id and a.active), 1000) as charter_priority
    from playbook_event_rules r
    join playbook_definitions d on d.id = r.definition_id
    where r.active
      and d.status = 'published'
      and (p_tenant_id is null or r.tenant_id = p_tenant_id)
      and tenant_is_operational(r.tenant_id)
    order by charter_priority asc
  loop
    if v_rule.event_key = 'invoice_overdue' then
      v_days := coalesce((v_rule.params->>'overdue_days')::int, 7);
      for v_inv in
        select id, account_id from renewal_invoices
        where tenant_id = v_rule.tenant_id
          and status = 'sent'
          and due_date is not null
          and due_date < (current_date - v_days)
      loop
        select * into v_recent from playbook_trigger_fires
          where event_rule_id = v_rule.id and target_ref = v_inv.id::text
            and status in ('pending_start', 'started')
            and fired_at > now() - make_interval(hours => v_rule.cooldown_hours)
          order by fired_at desc limit 1;
        if found then
          if not exists (
            select 1 from playbook_trigger_fires
            where event_rule_id = v_rule.id and target_ref = v_inv.id::text
              and status = 'skipped_dedup' and fired_at > v_recent.fired_at
          ) then
            insert into playbook_trigger_fires (tenant_id, source, event_rule_id, definition_id, target_account_id, target_ref, status, detail)
            values (v_rule.tenant_id, 'event', v_rule.id, v_rule.definition_id, v_inv.account_id, v_inv.id::text, 'skipped_dedup',
                    format('invoice already fired within the %sh cooldown', v_rule.cooldown_hours));
            v_skipped := v_skipped + 1;
          end if;
        else
          insert into playbook_trigger_fires (tenant_id, source, event_rule_id, definition_id, target_account_id, target_ref, status, detail)
          values (v_rule.tenant_id, 'event', v_rule.id, v_rule.definition_id, v_inv.account_id, v_inv.id::text, 'pending_start',
                  format('invoice overdue > %s days (charter priority %s)', v_days, v_rule.charter_priority));
          update playbook_event_rules set last_fired_at = now() where id = v_rule.id;
          v_pending := v_pending + 1;
        end if;
      end loop;

    elsif v_rule.event_key = 'ticket_synced_high_priority' then
      v_priority := coalesce(v_rule.params->>'priority', 'p1');
      for v_ticket in
        select id, account_id from support_tickets
        where tenant_id = v_rule.tenant_id
          and source = 'zendesk'
          and priority = v_priority
          and created_at > now() - interval '7 days'
      loop
        select * into v_recent from playbook_trigger_fires
          where event_rule_id = v_rule.id and target_ref = v_ticket.id::text
            and status in ('pending_start', 'started')
            and fired_at > now() - make_interval(hours => v_rule.cooldown_hours)
          order by fired_at desc limit 1;
        if found then
          if not exists (
            select 1 from playbook_trigger_fires
            where event_rule_id = v_rule.id and target_ref = v_ticket.id::text
              and status = 'skipped_dedup' and fired_at > v_recent.fired_at
          ) then
            insert into playbook_trigger_fires (tenant_id, source, event_rule_id, definition_id, target_account_id, target_ref, status, detail)
            values (v_rule.tenant_id, 'event', v_rule.id, v_rule.definition_id, v_ticket.account_id, v_ticket.id::text, 'skipped_dedup',
                    format('ticket already fired within the %sh cooldown', v_rule.cooldown_hours));
            v_skipped := v_skipped + 1;
          end if;
        else
          insert into playbook_trigger_fires (tenant_id, source, event_rule_id, definition_id, target_account_id, target_ref, status, detail)
          values (v_rule.tenant_id, 'event', v_rule.id, v_rule.definition_id, v_ticket.account_id, v_ticket.id::text, 'pending_start',
                  format('%s ticket synced from Zendesk (charter priority %s)', v_priority, v_rule.charter_priority));
          update playbook_event_rules set last_fired_at = now() where id = v_rule.id;
          v_pending := v_pending + 1;
        end if;
      end loop;

    elsif v_rule.event_key = 'account_at_risk' then
      v_min_arr := coalesce((v_rule.params->>'min_arr_cents')::bigint, 0);
      for v_acct in
        select id, arr_cents from customer_accounts
        where tenant_id = v_rule.tenant_id
          and status = 'at_risk'
          and arr_cents >= v_min_arr
      loop
        select * into v_recent from playbook_trigger_fires
          where event_rule_id = v_rule.id and target_ref = v_acct.id::text
            and status in ('pending_start', 'started')
            and fired_at > now() - make_interval(hours => v_rule.cooldown_hours)
          order by fired_at desc limit 1;
        if found then
          if not exists (
            select 1 from playbook_trigger_fires
            where event_rule_id = v_rule.id and target_ref = v_acct.id::text
              and status = 'skipped_dedup' and fired_at > v_recent.fired_at
          ) then
            insert into playbook_trigger_fires (tenant_id, source, event_rule_id, definition_id, target_account_id, target_ref, status, detail)
            values (v_rule.tenant_id, 'event', v_rule.id, v_rule.definition_id, v_acct.id, v_acct.id::text, 'skipped_dedup',
                    format('account already fired within the %sh cooldown', v_rule.cooldown_hours));
            v_skipped := v_skipped + 1;
          end if;
        else
          insert into playbook_trigger_fires (tenant_id, source, event_rule_id, definition_id, target_account_id, target_ref, status, detail)
          values (v_rule.tenant_id, 'event', v_rule.id, v_rule.definition_id, v_acct.id, v_acct.id::text, 'pending_start',
                  format('account at risk (computed health below threshold, charter priority %s)', v_rule.charter_priority));
          update playbook_event_rules set last_fired_at = now() where id = v_rule.id;
          v_pending := v_pending + 1;
        end if;
      end loop;

    elsif v_rule.event_key = 'opportunity_won' then
      -- RESTORED (originally 023, never actually applied live because
      -- 023's own version predated charter_priority — see this
      -- migration's header). Byte-faithful to 023's query/dedup/
      -- cooldown logic, with charter_priority ordering applied on top
      -- exactly like the other three branches already get.
      v_min_amount := coalesce((v_rule.params->>'min_amount_cents')::bigint, 0);
      for v_opp in
        select id, account_id, amount_cents from opportunities
        where tenant_id = v_rule.tenant_id
          and stage = 'won'
          and account_id is not null
          and closed_at > now() - interval '7 days'
          and coalesce(amount_cents, 0) >= v_min_amount
      loop
        select * into v_recent from playbook_trigger_fires
          where event_rule_id = v_rule.id and target_ref = v_opp.id::text
            and status in ('pending_start', 'started')
            and fired_at > now() - make_interval(hours => v_rule.cooldown_hours)
          order by fired_at desc limit 1;
        if found then
          if not exists (
            select 1 from playbook_trigger_fires
            where event_rule_id = v_rule.id and target_ref = v_opp.id::text
              and status = 'skipped_dedup' and fired_at > v_recent.fired_at
          ) then
            insert into playbook_trigger_fires (tenant_id, source, event_rule_id, definition_id, target_account_id, target_ref, status, detail)
            values (v_rule.tenant_id, 'event', v_rule.id, v_rule.definition_id, v_opp.account_id, v_opp.id::text, 'skipped_dedup',
                    format('opportunity already fired within the %sh cooldown', v_rule.cooldown_hours));
            v_skipped := v_skipped + 1;
          end if;
        else
          insert into playbook_trigger_fires (tenant_id, source, event_rule_id, definition_id, target_account_id, target_ref, status, detail)
          values (v_rule.tenant_id, 'event', v_rule.id, v_rule.definition_id, v_opp.account_id, v_opp.id::text, 'pending_start',
                  format('opportunity won — welcome/kickoff play (charter priority %s)', v_rule.charter_priority));
          update playbook_event_rules set last_fired_at = now() where id = v_rule.id;
          v_pending := v_pending + 1;
        end if;
      end loop;
    end if;
  end loop;

  return jsonb_build_object('pending', v_pending, 'skipped_dedup', v_skipped);
end;
$function$;

CREATE OR REPLACE FUNCTION public.dispatch_erp_reconcile_internal()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_secret text;
  v_anon   text := platform_anon_key();
  v_c      record;
  v_n      int := 0;
begin
  select decrypted_secret into v_secret from vault.decrypted_secrets where name = 'playbook_dispatch_secret';
  if v_secret is null then return 'no dispatch secret'; end if;

  for v_c in
    select id, tenant_id from connectors
    where category = 'erp_financials' and status = 'connected' and provider <> 'template'
      and tenant_is_operational(tenant_id)
  loop
    begin
      perform net.http_post(
        url     := platform_fn_url('/functions/v1/connector-hub'),
        body    := jsonb_build_object('action', 'reconcile_financials', 'connector_id', v_c.id, 'tenant_id', v_c.tenant_id),
        headers := jsonb_build_object('Content-Type', 'application/json', 'Authorization', 'Bearer ' || v_anon,
                                      'apikey', v_anon, 'x-dispatch-secret', v_secret),
        timeout_milliseconds := 60000);
      v_n := v_n + 1;
    exception when others then
      raise warning 'erp reconcile dispatch failed for connector %: %', v_c.id, sqlerrm;
    end;
  end loop;
  return 'erp-reconcile dispatched ' || v_n || ' connector(s)';
end;
$function$;

CREATE OR REPLACE FUNCTION public.dispatch_eval_driver_internal()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_secret text;
  v_anon   text := coalesce((select value from platform_runtime_config where key = 'supabase_anon_key'), 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6InJmc3ZtaGNxZWl5cnhpdmJtcGVsIiwicm9sZSI6ImFub24iLCJpYXQiOjE3ODIxMzIwMDgsImV4cCI6MjA5NzcwODAwOH0.RKCWute2ypkx9X-ByumIQWw8MS5uQPco-i-asNa-ESg');
  v_run    record;
  v_count  int := 0;
begin
  select decrypted_secret into v_secret from vault.decrypted_secrets where name = 'playbook_dispatch_secret';
  if v_secret is null then return 'no dispatch secret'; end if;

  for v_run in
    select id, tenant_id, de_id, archetype_key
      from eval_runs
     where status = 'running'
       and de_id is not null
       and finished_at is null
       and coalesce(jsonb_array_length(results), 0) < total
       and tenant_is_operational(tenant_id)
  loop
    perform net.http_post(
      url     := public.platform_fn_url('/functions/v1/eval-run'),
      body    := jsonb_build_object(
                   'run_id',        v_run.id,
                   'tenant_id',     v_run.tenant_id,
                   'de_id',         v_run.de_id,
                   'archetype_key', v_run.archetype_key
                 ),
      headers := jsonb_build_object(
                   'Content-Type', 'application/json',
                   'Authorization', 'Bearer ' || v_anon,
                   'x-dispatch-secret', v_secret
                 )
    , timeout_milliseconds := 60000);
    v_count := v_count + 1;
  end loop;

  return 'eval-driver dispatched ' || v_count || ' run(s)';
end;
$function$;

CREATE OR REPLACE FUNCTION public.dispatch_financial_sync_internal()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_secret text;
  v_anon   text := platform_anon_key();
  c        record;
  v_req    bigint;
  n_sent   int := 0;
BEGIN
  -- Nothing due? Say so and spend nothing.
  IF NOT EXISTS (
    SELECT 1 FROM connectors k
     WHERE k.category = 'erp_financials'
       AND k.status = 'connected'
       AND NOT public.connector_circuit_open(k.consecutive_failures, k.last_error_at)
       AND k.scheduled_sync_enabled
       AND tenant_is_operational(k.tenant_id)
       AND (k.last_scheduled_sync_at IS NULL
            OR k.last_scheduled_sync_at < now() - make_interval(mins => greatest(15, coalesce(k.sync_interval_mins, 1440)))))
  THEN
    RETURN 'idle — no financial connector due';
  END IF;

  SELECT decrypted_secret INTO v_secret FROM vault.decrypted_secrets
   WHERE name = 'playbook_dispatch_secret';
  IF v_secret IS NULL THEN
    PERFORM raise_ops_alert('dispatch_secret_missing',
      'playbook_dispatch_secret is missing from Vault — receivables cannot refresh, so collections would work from stale invoices.',
      jsonb_build_object('cron', 'dispatch_financial_sync_internal'));
    RETURN 'no dispatch secret';
  END IF;

  FOR c IN
    SELECT k.id, k.tenant_id, k.provider FROM connectors k
     WHERE k.category = 'erp_financials'
       AND k.status = 'connected'
       AND NOT public.connector_circuit_open(k.consecutive_failures, k.last_error_at)
       AND k.scheduled_sync_enabled
       AND tenant_is_operational(k.tenant_id)
       AND (k.last_scheduled_sync_at IS NULL
            OR k.last_scheduled_sync_at < now() - make_interval(mins => greatest(15, coalesce(k.sync_interval_mins, 1440))))
     ORDER BY k.last_scheduled_sync_at NULLS FIRST
     LIMIT 25
  LOOP
    SELECT net.http_post(
      url := platform_fn_url('/functions/v1/connector-hub'),
      body := jsonb_build_object('action','sync_financials','connector_id',c.id,'tenant_id',c.tenant_id),
      headers := jsonb_build_object('Content-Type','application/json',
                                    'Authorization','Bearer '||v_anon,
                                    'x-dispatch-secret', v_secret),
      timeout_milliseconds := 60000) INTO v_req;

    -- Stamp on DISPATCH, not on success. If the call fails the connector's own
    -- health fields and the drift sentinel report it; stamping here only stops
    -- the same connector being hammered every tick while one call is in flight.
    UPDATE connectors SET last_scheduled_sync_at = now() WHERE id = c.id;
    n_sent := n_sent + 1;
  END LOOP;

  RETURN format('financial sync dispatched for %s connector(s)', n_sent);
END $function$;

CREATE OR REPLACE FUNCTION public.dispatch_gap_improve_internal()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_secret text;
  v_anon   text := coalesce((select value from platform_runtime_config where key = 'supabase_anon_key'), 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6InJmc3ZtaGNxZWl5cnhpdmJtcGVsIiwicm9sZSI6ImFub24iLCJpYXQiOjE3ODIxMzIwMDgsImV4cCI6MjA5NzcwODAwOH0.RKCWute2ypkx9X-ByumIQWw8MS5uQPco-i-asNa-ESg');
  v_row    record;
  v_count  int := 0;
BEGIN
  SELECT decrypted_secret INTO v_secret FROM vault.decrypted_secrets WHERE name = 'playbook_dispatch_secret';
  IF v_secret IS NULL THEN RETURN 'no dispatch secret'; END IF;

  FOR v_row IN
    WITH pending AS (
      SELECT tenant_id, count(*) n FROM de_improvements
       WHERE status = 'review_pending' GROUP BY tenant_id
    )
    SELECT DISTINCT ON (g.tenant_id) g.tenant_id, g.id AS cluster_id
      FROM knowledge_gap_clusters g
      LEFT JOIN pending p ON p.tenant_id = g.tenant_id
     WHERE g.status = 'open'
       AND g.de_improvement_id IS NULL
       AND g.representative_run_id IS NOT NULL
       AND coalesce(p.n, 0) < 3
       AND tenant_is_operational(g.tenant_id)
       AND NOT EXISTS (SELECT 1 FROM de_improvements di WHERE di.gap_cluster_id = g.id)
       -- draftable only: de-improve needs a DE + question from the rep run;
       -- a rep run with no de_id would 422 forever, so never dispatch it.
       AND EXISTS (SELECT 1 FROM evidence_runs r
                    WHERE r.id = g.representative_run_id
                      AND r.de_id IS NOT NULL AND r.inquiry IS NOT NULL)
     ORDER BY g.tenant_id, g.severity_score DESC NULLS LAST, g.member_count DESC
     LIMIT 25
  LOOP
    BEGIN
      PERFORM net.http_post(
        url     := public.platform_fn_url('/functions/v1/de-improve'),
        body    := jsonb_build_object('tenant_id', v_row.tenant_id, 'gap_cluster_id', v_row.cluster_id),
        headers := jsonb_build_object(
                     'Content-Type', 'application/json',
                     'Authorization', 'Bearer ' || v_anon,
                     'x-dispatch-secret', v_secret)
      , timeout_milliseconds := 60000);
      v_count := v_count + 1;
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING 'gap-improve dispatch failed for tenant % cluster %: %', v_row.tenant_id, v_row.cluster_id, sqlerrm;
    END;
  END LOOP;

  RETURN 'gap-improve dispatched ' || v_count || ' http_post(s) (async)';
END;
$function$;

CREATE OR REPLACE FUNCTION public.dispatch_knowledge_sync_internal()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_secret text;
  v_anon   text := coalesce((select value from platform_runtime_config where key = 'supabase_anon_key'), 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6InJmc3ZtaGNxZWl5cnhpdmJtcGVsIiwicm9sZSI6ImFub24iLCJpYXQiOjE3ODIxMzIwMDgsImV4cCI6MjA5NzcwODAwOH0.RKCWute2ypkx9X-ByumIQWw8MS5uQPco-i-asNa-ESg');
  v_row    record;
  v_count  int := 0;
BEGIN
  SELECT decrypted_secret INTO v_secret FROM vault.decrypted_secrets WHERE name = 'playbook_dispatch_secret';
  IF v_secret IS NULL THEN RETURN 'no dispatch secret'; END IF;

  FOR v_row IN
    SELECT c.id AS connector_id, c.tenant_id
      FROM connectors c
     WHERE c.scheduled_sync_enabled = true
       AND coalesce(c.access_mode, '') <> 'fetch_only'
       -- default-OFF flag => no tenant is touched until it explicitly opts in
       AND public.is_feature_enabled_internal(c.tenant_id, 'knowledge_scheduled_sync') = true
       AND tenant_is_operational(c.tenant_id)
       AND (c.last_scheduled_sync_at IS NULL
            OR c.last_scheduled_sync_at < now() - make_interval(mins => greatest(60, c.sync_interval_mins)))
     ORDER BY c.last_scheduled_sync_at ASC NULLS FIRST
     LIMIT 25
  LOOP
    BEGIN
      -- Claim first (advance the clock) so a slow/duplicate tick can't double-fire.
      UPDATE connectors SET last_scheduled_sync_at = now() WHERE id = v_row.connector_id;
      PERFORM net.http_post(
        url     := public.platform_fn_url('/functions/v1/connector-hub'),
        body    := jsonb_build_object('action', 'sync', 'connector_id', v_row.connector_id,
                                      'tenant_id', v_row.tenant_id, 'scheduled', true),
        headers := jsonb_build_object(
                     'Content-Type', 'application/json',
                     'Authorization', 'Bearer ' || v_anon,
                     'x-dispatch-secret', v_secret)
      , timeout_milliseconds := 60000);
      v_count := v_count + 1;
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING 'knowledge-sync dispatch failed for connector %: %', v_row.connector_id, sqlerrm;
    END;
  END LOOP;

  RETURN 'knowledge-sync dispatched ' || v_count || ' connector(s) (async)';
END;
$function$;

CREATE OR REPLACE FUNCTION public.dispatch_ledger_sync_internal()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_secret text;
  v_anon   text := platform_anon_key();
  c        record;
  v_req    bigint;
  n_sent   int := 0;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM connectors k
     WHERE k.category = 'erp_financials'
       AND k.status = 'connected'
       AND NOT public.connector_circuit_open(k.consecutive_failures, k.last_error_at)
       AND k.scheduled_sync_enabled
       AND tenant_is_operational(k.tenant_id))
  THEN
    RETURN 'idle — no financial connector';
  END IF;

  SELECT decrypted_secret INTO v_secret FROM vault.decrypted_secrets
   WHERE name = 'playbook_dispatch_secret';
  IF v_secret IS NULL THEN
    PERFORM raise_ops_alert('dispatch_secret_missing',
      'playbook_dispatch_secret is missing from Vault — the general ledger cannot refresh, so reconciliation would work from stale books.',
      jsonb_build_object('cron', 'dispatch_ledger_sync_internal'));
    RETURN 'no dispatch secret';
  END IF;

  FOR c IN
    SELECT k.id, k.tenant_id FROM connectors k
     WHERE k.category = 'erp_financials'
       AND k.status = 'connected'
       AND NOT public.connector_circuit_open(k.consecutive_failures, k.last_error_at)
       AND k.scheduled_sync_enabled
       AND tenant_is_operational(k.tenant_id)
     ORDER BY k.last_sync_at NULLS FIRST
     LIMIT 25
  LOOP
    SELECT net.http_post(
      url := platform_fn_url('/functions/v1/connector-hub'),
      body := jsonb_build_object('action', 'sync_ledger', 'connector_id', c.id, 'tenant_id', c.tenant_id),
      headers := jsonb_build_object('Content-Type', 'application/json',
                                    'Authorization', 'Bearer ' || v_anon,
                                    'x-dispatch-secret', v_secret),
      timeout_milliseconds := 60000) INTO v_req;
    n_sent := n_sent + 1;
  END LOOP;

  RETURN format('dispatched ledger sync for %s connector(s)', n_sent);
END;
$function$;

CREATE OR REPLACE FUNCTION public.dispatch_online_eval_internal()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_secret text;
  v_anon   text := platform_anon_key();
  v_req_id bigint;
BEGIN
  SELECT decrypted_secret INTO v_secret FROM vault.decrypted_secrets WHERE name = 'playbook_dispatch_secret';
  IF v_secret IS NULL THEN
    PERFORM raise_ops_alert('dispatch_secret_missing',
      'playbook_dispatch_secret is missing from Vault — online eval cron is doing nothing.',
      jsonb_build_object('cron', 'dispatch_online_eval_internal'));
    RETURN 'no dispatch secret';
  END IF;
  SELECT net.http_post(
    url := platform_fn_url('/functions/v1/de-eval-online'),
