  , timeout_milliseconds := 60000) INTO v_req_id;
  RETURN 'online-eval dispatched, req ' || v_req_id;
END;
$function$;

CREATE OR REPLACE FUNCTION public.due_approved_actions(p_limit integer DEFAULT 25)
 RETURNS TABLE(tenant_id uuid, tenant_slug text, task_id uuid, execution_id uuid, connector_id uuid, action_definition_id uuid, action_key text, action_label text, params jsonb, decided_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_enabled_at timestamptz;
  v_allow      text[];
begin
  -- Empty or unparseable ⇒ disabled. Never "assume on".
  select nullif(btrim(value), '')::timestamptz into v_enabled_at
    from platform_config where key = 'approved_action_driver.enabled_at';
  if v_enabled_at is null then
    return;                                     -- disabled: zero rows
  end if;

  select coalesce(
           array(select btrim(s) from unnest(string_to_array(coalesce(value, ''), ',')) s
                  where btrim(s) <> ''), '{}')
    into v_allow
    from platform_config where key = 'approved_action_driver.tenant_allowlist';
  if coalesce(array_length(v_allow, 1), 0) = 0 then
    return;                                     -- nobody opted in: zero rows
  end if;

  return query
  select t.id, t.slug, ht.id, ae.id, ae.connector_id, ae.action_definition_id,
         ad.action_key, ad.label, ae.params, ht.decided_at
    from human_tasks ht
    join tenants t             on t.id = ht.tenant_id
    join action_executions ae  on ae.task_id = ht.id
    join action_definitions ad on ad.id = ae.action_definition_id
   where ht.type = 'action_approval'
     and ht.status = 'approved'                 -- 'expired' (mig 642) excluded
     and t.status = 'active'                    -- never act in a suspended workspace
     and t.slug = any(v_allow)
     and ht.decided_at >= v_enabled_at          -- THE WATERMARK
     and ae.decision like 'human_gated%'
     and ae.connector_id is not null
     -- Not already carried out. From mig 642 onward the linkage is reliable:
     -- claim_gated_action_execution sets resolves_task_id on every claim.
     and not exists (
       select 1 from action_executions x
        where x.resolves_task_id = ht.id
          and x.decision <> 'failed')
   order by ht.decided_at
   limit greatest(1, least(coalesce(p_limit, 25), 100));
end;
$function$;

CREATE OR REPLACE FUNCTION public.dunning_action_for(p_tenant_id uuid, p_action_key text, p_execution_key text)
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select ad.id
  from action_definitions ad
  where ad.action_key = p_action_key
    and ad.status = 'active'
    and (ad.tenant_id = p_tenant_id or ad.tenant_id is null)
    -- An empty `execution` means nothing happens when a human approves it.
    and coalesce(ad.execution->>'execution_key', '') = coalesce(p_execution_key, '')
    and coalesce(p_execution_key, '') <> ''
  order by (ad.tenant_id is not null) desc, ad.created_at asc
  limit 1;
$function$;

CREATE OR REPLACE FUNCTION public.dunning_connector_for(p_tenant_id uuid, p_action_definition_id uuid)
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  -- The connector that carries out THIS definition for THIS tenant: same
  -- category, same provider, connected. Exactly one, or nothing — a second
  -- candidate collapses the whole thing to null rather than choosing a
  -- company's ERP by row order. (`array_agg(…)[1]` rather than `min()`:
  -- there is no `min(uuid)` in Postgres, and under `count(*) = 1` the array
  -- holds exactly one element, so the subscript is not a choice.)
  select case when count(*) = 1 then (array_agg(c.id))[1] end
  from connectors c
  join action_definitions ad on ad.id = p_action_definition_id
  where c.tenant_id = p_tenant_id
    and c.status    = 'connected'
    and c.category  = ad.category
    and c.provider  = ad.provider;
$function$;

CREATE OR REPLACE FUNCTION public.dunning_de_for(p_tenant_id uuid)
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select de.id
  from digital_employees de
  where de.tenant_id = p_tenant_id
    and de.status = 'active'
    and (
      coalesce(de.category, '')   ~* '(financ|billing|account|revenue)'
      or coalesce(de.department,'') ~* '(financ|billing|account|revenue)'
      or de.name                  ~* '(financ|billing|account|receivab|collection)'
    )
  -- Deterministic: the same employee every day, so the audit trail reads as
  -- one desk doing the work rather than a rota nobody chose.
  order by
    (de.name ~* 'financ') desc,
    (de.name ~* '(account|receivab)') desc,
    de.created_at asc
  limit 1;
$function$;

CREATE OR REPLACE FUNCTION public.dunning_email(p_stage integer, p_customer text, p_invoice_ref text, p_days_overdue integer, p_outstanding_cents bigint, p_currency text, p_due_date date, p_from_org text)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select case coalesce(p_stage, 1)
    when 1 then jsonb_build_object(
      'subject', format('Invoice %s — payment reminder', p_invoice_ref),
      'body', format(E'Dear %s,\n\nThis is a reminder that invoice %s for %s was due on %s and is showing as unpaid on our records.\n\nIf payment is already on its way, please ignore this message. If not, we would be grateful if you could let us know when we can expect it — or tell us if something about the invoice needs resolving.\n\nThank you,\n%s',
        p_customer, p_invoice_ref, money_text(p_outstanding_cents, p_currency),
        to_char(p_due_date, 'FMDD FMMonth YYYY'), p_from_org))
    when 2 then jsonb_build_object(
      'subject', format('Invoice %s — now %s days overdue', p_invoice_ref, p_days_overdue),
      'body', format(E'Dear %s,\n\nWe are following up on invoice %s, which was due on %s and is now %s days past due. %s remains outstanding.\n\nCould you confirm the date on which payment will be made? If there is a problem with the invoice, please tell us so that we can put it right.\n\nThank you,\n%s',
        p_customer, p_invoice_ref, to_char(p_due_date, 'FMDD FMMonth YYYY'), p_days_overdue,
        money_text(p_outstanding_cents, p_currency), p_from_org))
    when 3 then jsonb_build_object(
      'subject', format('Final notice — invoice %s', p_invoice_ref),
      'body', format(E'Dear %s,\n\nInvoice %s was due on %s and is now %s days past due. %s remains outstanding, and our earlier reminders have not been answered.\n\nPlease arrange payment within 7 days of this message. If payment is not received we will place the account on hold while the matter is resolved.\n\nIf you believe this notice is in error, please contact us straight away and we will look into it.\n\nRegards,\n%s',
        p_customer, p_invoice_ref, to_char(p_due_date, 'FMDD FMMonth YYYY'), p_days_overdue,
        money_text(p_outstanding_cents, p_currency), p_from_org))
    -- Stage 4 is a credit-hold recommendation put to a human. There is no
    -- customer-facing message for it, and returning null here is what makes
    -- accidentally emailing it impossible rather than merely unlikely.
    else null
  end;
$function$;

CREATE OR REPLACE FUNCTION public.dunning_execution_key(p_provider text, p_action_key text, p_has_recipient boolean)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select case
    -- Chosen by RUNG, not by whether an address happens to exist. The
    -- credit-hold rung's own tone says "Do not contact the customer", and that
    -- must not become negotiable the day a contact_email turns up.
    when p_action_key = 'flag_for_collections' then p_provider || '_invoice_comment'
    when p_provider = 'erpnext' and coalesce(p_has_recipient, false) then 'erpnext_send_invoice_email'
    when p_provider = 'erpnext' then 'erpnext_invoice_comment'
    -- Stripe, Xero and QuickBooks already email on their reminder endpoint.
    when p_action_key = 'send_payment_reminder' then p_provider || '_send_invoice_reminder'
    -- Anything else has no executor for this provider. Returning null makes
    -- the sweep report `no_executor` rather than raise an approval nothing can
    -- carry out.
    else null
  end;
$function$;

CREATE OR REPLACE FUNCTION public.dunning_note_text(p_stage integer, p_customer text, p_invoice_ref text, p_days_overdue integer, p_outstanding_cents bigint, p_currency text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select case coalesce(p_stage, 1)
    when 1 then format(
      'Payment reminder — invoice %s for %s is %s day(s) past due, with %s still outstanding. Likely an oversight. Ask when payment can be expected and whether anything is blocking it. No consequences to be mentioned at this stage.',
      p_invoice_ref, p_customer, p_days_overdue, money_text(p_outstanding_cents, p_currency))
    when 2 then format(
      'Second approach — invoice %s for %s is now %s day(s) past due, with %s still outstanding. Restate the amount and the age, ask for a specific payment date, and copy the account owner. Warm but direct.',
      p_invoice_ref, p_customer, p_days_overdue, money_text(p_outstanding_cents, p_currency))
    when 3 then format(
      'FINAL NOTICE — invoice %s for %s is %s day(s) past due, with %s still outstanding. State the amount, the age, what happens next and by when. No threats and no apology; this is the last message before commercial consequences.',
      p_invoice_ref, p_customer, p_days_overdue, money_text(p_outstanding_cents, p_currency))
    else format(
      'CREDIT HOLD RECOMMENDED — do not contact the customer. %s has %s outstanding on invoice %s, %s day(s) past due, and earlier approaches have not produced payment. Putting the recommendation to a human with the full history.',
      p_customer, money_text(p_outstanding_cents, p_currency), p_invoice_ref, p_days_overdue)
  end;
$function$;

CREATE OR REPLACE FUNCTION public.dunning_position(p_tenant_id uuid)
 RETURNS TABLE(invoice_id uuid, invoice_ref text, customer text, days_overdue integer, outstanding_cents bigint, current_stage integer, due_stage integer, rung_label text, tone text, action_key text, requires_approval boolean, actionable boolean, why text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_ladder uuid; v_first_rung int; v_floor bigint;
BEGIN
  SELECT id INTO v_ladder FROM dunning_ladders
   WHERE active AND (tenant_id = p_tenant_id OR tenant_id IS NULL)
   ORDER BY tenant_id NULLS LAST LIMIT 1;

  -- The first rung's terms, so an invoice that has not reached it can say
  -- exactly what it is waiting for rather than listing possibilities.
  SELECT d.after_days_overdue, d.min_outstanding_cents INTO v_first_rung, v_floor
    FROM dunning_rungs d WHERE d.ladder_id = v_ladder ORDER BY d.stage LIMIT 1;

  RETURN QUERY
  SELECT r.id, coalesce(r.source_external_ref, r.id::text),
         coalesce(a.name, '(unknown customer)'),
         (current_date - r.due_date)::int,
         r.outstanding_cents,
         coalesce(r.cadence_stage, 0),
         g.stage, g.label, g.tone, g.action_key, g.requires_approval,
         (pr.id IS NULL                       -- an open promise stops the ladder
          AND r.outstanding_cents IS NOT NULL
          AND r.outstanding_cents > 0
          AND g.stage IS NOT NULL
          AND g.stage > coalesce(r.cadence_stage, 0))::boolean,
         CASE
           WHEN pr.id IS NOT NULL THEN
             format('Not chasing: %s promised %s by %s. Holding until %s.',
                    coalesce(a.name,'the customer'), money_text(pr.promised_cents, r.source_currency),
                    to_char(pr.promised_on,'FMDD Mon'), to_char(pr.promised_on + pr.grace_days,'FMDD Mon'))
           WHEN br.id IS NOT NULL AND r.outstanding_cents IS NOT NULL AND r.outstanding_cents > 0 THEN
             format('%s day(s) overdue and %s still owed. A promise to pay by %s was not kept — escalate rather than wait for the next rung.',
                    (current_date - r.due_date)::int, money_text(r.outstanding_cents, r.source_currency),
                    to_char(br.promised_on,'FMDD Mon'))
           WHEN r.outstanding_cents IS NULL THEN
             'Cannot be chased: no payment has ever been reconciled against this invoice, so the amount still owed is unverified. Its face value is not a balance owed.'
           WHEN r.outstanding_cents = 0 THEN 'Nothing owed — settled.'
           WHEN v_ladder IS NULL THEN 'No dunning ladder is declared for this workspace, so nothing is chased.'
           -- Not yet due. Say when it IS due, not a negative overdue count.
           WHEN r.due_date > current_date THEN
             format('Not due yet — payable %s, in %s day(s).',
                    to_char(r.due_date, 'FMDD Mon YYYY'), (r.due_date - current_date)::int)
           -- Overdue, but the ladder has not reached it.
           WHEN g.stage IS NULL AND (current_date - r.due_date) < coalesce(v_first_rung, 0) THEN
             format('%s day(s) overdue. The first approach is due at %s day(s).',
                    (current_date - r.due_date)::int, coalesce(v_first_rung, 0))
           WHEN g.stage IS NULL THEN
             format('%s day(s) overdue, but %s owed is below the %s this workspace bothers to chase.',
                    (current_date - r.due_date)::int, money_text(r.outstanding_cents, r.source_currency),
                    money_text(coalesce(v_floor,0), r.source_currency))
           WHEN g.stage <= coalesce(r.cadence_stage, 0) THEN
             format('Already at stage %s; the next rung is not due yet.', coalesce(r.cadence_stage, 0))
           ELSE format('%s day(s) overdue and %s still owed — %s is due.',
                    (current_date - r.due_date)::int, money_text(r.outstanding_cents, r.source_currency), g.label)
         END
    FROM renewal_invoices r
    LEFT JOIN customer_accounts a ON a.id = r.account_id
    -- An OPEN promise whose day has not passed suppresses chasing entirely.
    LEFT JOIN LATERAL (
      SELECT p.* FROM payment_promises p
       WHERE p.invoice_id = r.id AND p.status = 'open'
         AND current_date <= p.promised_on + p.grace_days
       ORDER BY p.created_at DESC LIMIT 1) pr ON true
    -- The most recent BROKEN promise, which makes the case stronger, not weaker.
    LEFT JOIN LATERAL (
      SELECT p.* FROM payment_promises p
       WHERE p.invoice_id = r.id AND p.status = 'broken'
       ORDER BY p.promised_on DESC LIMIT 1) br ON true
    LEFT JOIN LATERAL (
      SELECT d.* FROM dunning_rungs d
       WHERE d.ladder_id = v_ladder
         AND (current_date - r.due_date) >= d.after_days_overdue
         AND coalesce(r.outstanding_cents, 0) >= d.min_outstanding_cents
       ORDER BY d.stage DESC LIMIT 1
    ) g ON true
   WHERE r.tenant_id = p_tenant_id
     AND coalesce(r.status, '') NOT IN ('paid', 'void', 'cancelled')
     AND r.due_date IS NOT NULL
   ORDER BY (current_date - r.due_date) DESC;
END $function$;

CREATE OR REPLACE FUNCTION public.dunning_rung_order_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE v_bad int;
BEGIN
  SELECT count(*) INTO v_bad FROM dunning_rungs a JOIN dunning_rungs b
    ON a.ladder_id = b.ladder_id AND a.stage < b.stage
   WHERE a.ladder_id = NEW.ladder_id AND a.after_days_overdue >= b.after_days_overdue;
  IF v_bad > 0 THEN
    RAISE EXCEPTION 'Each rung must come later than the one before it. Stage % would fire no later than an earlier stage.', NEW.stage;
  END IF;
  RETURN NEW;
END $function$;

CREATE OR REPLACE FUNCTION public.edit_outbound_draft(p_draft_id uuid, p_body text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_tenant uuid; v_de uuid;
begin
  if auth.uid() is null then raise exception 'not authenticated'; end if;
  if coalesce(btrim(p_body), '') = '' or length(btrim(p_body)) < 10 then raise exception 'draft body required (min 10 chars)'; end if;
  select tenant_id, de_id into v_tenant, v_de from outbound_drafts where id = p_draft_id and status = 'pending_approval';
  if v_tenant is null then raise exception 'not_a_pending_draft'; end if;
  if not (is_platform_admin() or exists (select 1 from profiles p where p.user_id = auth.uid() and p.tenant_id = v_tenant)) then
    raise exception 'not authorized for this workspace';
  end if;
  -- DE scoping (mig 385/405). outbound_drafts.de_id is NOT NULL and comes
  -- off the very row the UPDATE below will touch, so no null case and no
  -- chance of guarding a different row than the one being changed.
  if not public.can_access_de(v_de) then
    raise exception 'not_responsible_for_de: this employee is not in your reporting line';
  end if;

  update outbound_drafts set body = btrim(p_body), updated_at = now() where id = p_draft_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.emit_tenant_event(p_tenant_id uuid, p_event_key text, p_target_ref text DEFAULT NULL::text, p_target_account_id uuid DEFAULT NULL::uuid, p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_user uuid := auth.uid();
  v_role text;
  v_is_active boolean;
  v_tenant_check uuid;
  v_evt event_definitions;
  v_rule record;
  v_recent record;
  v_ref text;
  v_pending integer := 0;
  v_skipped integer := 0;
begin
  -- Trusted-server gate (same as upsert_event_definition above).
  if auth.role() is not null and auth.role() <> 'service_role' then
    select tenant_id, role, coalesce(is_active, true) into v_tenant_check, v_role, v_is_active
      from profiles where user_id = v_user;
    if v_tenant_check is distinct from p_tenant_id then
      raise exception 'not a member of this tenant';
    end if;
    if not v_is_active then
      raise exception 'account is deactivated';
    end if;
    if v_role not in ('tenant_owner', 'tenant_admin') then
      raise exception 'only workspace owners/admins can fire events';
    end if;
  end if;

  -- The event must exist for this tenant (own event preferred, else platform)
  -- and be active.
  select * into v_evt from event_definitions
   where event_key = p_event_key and active
     and (scope = 'platform' or tenant_id = p_tenant_id)
   order by (scope = 'tenant') desc
   limit 1;
  if v_evt.id is null then
    return jsonb_build_object('ok', false, 'error', 'event_not_found', 'event_key', p_event_key);
  end if;

  v_ref := coalesce(nullif(p_target_ref, ''), p_target_account_id::text, '');

  for v_rule in
    select r.*, d.status as def_status
    from playbook_event_rules r
    join playbook_definitions d on d.id = r.definition_id
    where r.active and r.tenant_id = p_tenant_id and r.event_key = p_event_key
  loop
    if v_rule.def_status <> 'published' then
      continue;  -- unpublished definition: nothing runnable
    end if;

    -- Cooldown / dedup — identical shape to dispatch_due_triggers.
    select * into v_recent from playbook_trigger_fires
      where event_rule_id = v_rule.id and target_ref = v_ref
        and status in ('pending_start', 'started')
        and fired_at > now() - make_interval(hours => v_rule.cooldown_hours)
      order by fired_at desc limit 1;
    if found then
      if not exists (
        select 1 from playbook_trigger_fires
        where event_rule_id = v_rule.id and target_ref = v_ref
          and status = 'skipped_dedup' and fired_at > v_recent.fired_at
      ) then
        insert into playbook_trigger_fires (tenant_id, source, event_rule_id, definition_id, target_account_id, target_ref, status, detail)
        values (p_tenant_id, 'event', v_rule.id, v_rule.definition_id, p_target_account_id, v_ref, 'skipped_dedup',
                format('event "%s" already fired within the %sh cooldown', p_event_key, v_rule.cooldown_hours));
        v_skipped := v_skipped + 1;
      end if;
    else
      insert into playbook_trigger_fires (tenant_id, source, event_rule_id, definition_id, target_account_id, target_ref, status, detail)
      values (p_tenant_id, 'event', v_rule.id, v_rule.definition_id, p_target_account_id, v_ref, 'pending_start',
              format('emitted event "%s"%s', p_event_key,
                     case when p_payload ? 'source' then ' from '||(p_payload->>'source') else '' end));
      update playbook_event_rules set last_fired_at = now() where id = v_rule.id;
      v_pending := v_pending + 1;
    end if;
  end loop;

  return jsonb_build_object('ok', true, 'event_key', p_event_key, 'fires_created', v_pending, 'skipped', v_skipped);
end;
$function$;

CREATE OR REPLACE FUNCTION public.end_discovery_session(p_session_id uuid, p_tenant_id uuid, p_status text, p_resume_hint text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_status    text;
  v_tenant    uuid;
begin
  if p_status is null or p_status not in ('parked', 'abandoned') then
    raise exception 'end_discovery_session: % is not an end state — must be ''parked'' (the customer means to come back) or ''abandoned'' (they do not)', coalesce(p_status, 'NULL');
  end if;
  if p_session_id is null or p_tenant_id is null then
    raise exception 'end_discovery_session: both a session and a tenant are required';
  end if;

  select status, tenant_id into v_status, v_tenant
    from public.discovery_sessions
   where id = p_session_id;

  if v_status is null then
    raise exception 'end_discovery_session: unknown discovery session %', p_session_id;
  end if;
  if v_tenant is distinct from p_tenant_id then
    raise exception 'end_discovery_session: session % does not belong to tenant % — a session id is not its own authorisation', p_session_id, p_tenant_id;
  end if;
  if v_status <> 'running' and v_status <> p_status then
    raise exception 'end_discovery_session: session % is already ''%'' — only a running interview can be ended, and a finished one is not reclassified by a retry', p_session_id, v_status;
  end if;

  -- STATUS, HINT, CLOCK. Not coverage. Not transcript. A session that ends
  -- keeps every word of what it heard, and every gap it never closed.
  update public.discovery_sessions
     set status      = p_status,
         resume_hint = coalesce(p_resume_hint, resume_hint),
         updated_at  = now()
   where id = p_session_id;

  return jsonb_build_object(
    'session_id',      p_session_id,
    'status',          p_status,
    'previous_status', v_status,
    'resume_hint',     (select resume_hint from public.discovery_sessions where id = p_session_id)
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.end_platform_remote_access(p_session_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_start platform_access_events;
begin
  if not resolve_platform_capability(auth.uid(), 'remote_access.use') then
    raise exception 'only a platform team member with remote access may end a remote access session';
  end if;

  select * into v_start from platform_access_events
  where session_key = p_session_key and event = 'start' and operator_user_id = auth.uid()
  order by created_at desc limit 1;

  if not found then
    raise exception 'no matching remote access session found to end';
  end if;

  if exists (select 1 from platform_access_events where session_key = p_session_key and event = 'end') then
    raise exception 'this remote access session has already been ended';
  end if;

  insert into platform_access_events (tenant_id, operator_user_id, operator_name, event, session_key, detail)
  values (v_start.tenant_id, auth.uid(), v_start.operator_name, 'end', p_session_key,
    jsonb_build_object('duration_seconds', extract(epoch from (now() - v_start.created_at))));

  return jsonb_build_object('ok', true, 'session_key', p_session_key);
end;
$function$;

CREATE OR REPLACE FUNCTION public.enqueue_conflict_backlog(p_tenant_id uuid, p_limit integer DEFAULT 500, p_after_chunk_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_n int; v_last uuid;
BEGIN
  IF NOT (p_tenant_id = auth_tenant_id()
          AND auth_has_tenant_role(ARRAY['tenant_owner', 'tenant_admin'])) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'forbidden');
  END IF;
  IF NOT is_feature_enabled_internal(p_tenant_id, 'knowledge_conflict_detection') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'detection_disabled');
  END IF;
  WITH batch AS (
    SELECT c.id, c.doc_id, c.tenant_id, c.content_hash
    FROM knowledge_doc_chunks c
    WHERE c.tenant_id = p_tenant_id AND c.embedding IS NOT NULL
      AND (p_after_chunk_id IS NULL OR c.id > p_after_chunk_id)
    ORDER BY c.id
    LIMIT least(greatest(coalesce(p_limit, 500), 1), 2000)
  ), ins AS (
    INSERT INTO knowledge_conflict_probe_queue (tenant_id, chunk_id, doc_id, content_hash)
    SELECT b.tenant_id, b.id, b.doc_id, b.content_hash FROM batch b
    ON CONFLICT (tenant_id, chunk_id) DO NOTHING
    RETURNING 1
  )
  SELECT (SELECT count(*) FROM ins),
         (SELECT b.id FROM batch b ORDER BY b.id DESC LIMIT 1)   -- keyset watermark (no max(uuid))
    INTO v_n, v_last;
  RETURN jsonb_build_object('ok', true, 'seeded', coalesce(v_n, 0), 'last_chunk_id', v_last);
END $function$;

CREATE OR REPLACE FUNCTION public.enqueue_conflict_probe()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  -- Fire only for an embedded chunk whose content/embedding meaningfully changed,
  -- and only for tenants that opted in (default-OFF flag → inert for everyone else).
  IF NEW.embedding IS NOT NULL
     AND (TG_OP = 'INSERT' OR OLD.embedding IS NULL OR NEW.content_hash IS DISTINCT FROM OLD.content_hash)
     AND is_feature_enabled_internal(NEW.tenant_id, 'knowledge_conflict_detection') THEN
    INSERT INTO knowledge_conflict_probe_queue (tenant_id, chunk_id, doc_id, content_hash)
    VALUES (NEW.tenant_id, NEW.id, NEW.doc_id, NEW.content_hash)
    ON CONFLICT (tenant_id, chunk_id) DO UPDATE
      SET content_hash = EXCLUDED.content_hash, enqueued_at = now(), probed_at = NULL, attempts = 0;
    -- A changed chunk invalidates its prior open findings.
    UPDATE knowledge_conflicts SET status = 'superseded'
     WHERE tenant_id = NEW.tenant_id AND status = 'open' AND NEW.id IN (chunk_a_id, chunk_b_id);
  END IF;
  RETURN NEW;
END $function$;

CREATE OR REPLACE FUNCTION public.enqueue_de_work_item(p_tenant_id uuid, p_de_id uuid, p_title text, p_kind text DEFAULT 'act'::text, p_scheduled_for timestamp with time zone DEFAULT now(), p_objective_id uuid DEFAULT NULL::uuid, p_seq integer DEFAULT 0, p_depends_on uuid DEFAULT NULL::uuid, p_payload jsonb DEFAULT '{}'::jsonb, p_idempotency_key text DEFAULT NULL::text, p_max_attempts integer DEFAULT 3)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is null then
    raise exception 'not authenticated: queueing work puts a task in front of an employee in a named workspace, so the caller has to be a member of it';
  end if;

  -- ⚠ THE TENANT ID IS A PARAMETER, SO IT IS NOT AUTHORISATION (migs 662-664).
  -- Matched against the caller's OWN profile row. Predicate otherwise verbatim
  -- from the live body, prefix deleted.
  if not exists (select 1 from profiles p where p.user_id = auth.uid()
                   and (p.tenant_id = p_tenant_id or p.layer = 'platform')) then
    raise exception 'not authorized to enqueue work for this tenant';
  end if;

  -- DE scoping (mig 385/420). The `auth.uid() is not null and` prefix that
  -- used to sit in front of this one is gone too: with the bar above, a null
  -- identity never reaches this line.
  if not public.can_access_de(p_de_id) then
    raise exception 'not_responsible_for_de: this employee is not in your reporting line';
  end if;

  return public.enqueue_de_work_item_internal(
           p_tenant_id, p_de_id, p_title, p_kind, p_scheduled_for, p_objective_id,
           p_seq, p_depends_on, p_payload, p_idempotency_key, p_max_attempts);
end;
$function$;

CREATE OR REPLACE FUNCTION public.enqueue_de_work_item_internal(p_tenant_id uuid, p_de_id uuid, p_title text, p_kind text DEFAULT 'act'::text, p_scheduled_for timestamp with time zone DEFAULT now(), p_objective_id uuid DEFAULT NULL::uuid, p_seq integer DEFAULT 0, p_depends_on uuid DEFAULT NULL::uuid, p_payload jsonb DEFAULT '{}'::jsonb, p_idempotency_key text DEFAULT NULL::text, p_max_attempts integer DEFAULT 3)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_id uuid;
begin
  -- NO MEMBERSHIP CHECK. de-work drives the autonomy loop with the
  -- service-role client and has no signed-in person.
  --
  -- ⚠ THE DE-SCOPING TEST IS KEPT, AND THAT IS THE ONE PLACE THIS MIGRATION
  -- TIGHTENS THE SERVICE PATH RATHER THAN LEAVING IT ALONE. In the live body
  -- this line also carried the prefix, so under service_role it was SKIPPED;
  -- here it runs. It is kept rather than dropped because can_access_de names
  -- service_role EXPLICITLY (`coalesce(auth.role(),'') = 'service_role'`,
  -- with its own comment saying a null uid must never stand in for the role),
  -- so a real service-role caller still passes — probe 3 fires it with the
  -- PostgREST service-role JWT shape rather than assuming. What it would now
  -- refuse is a caller with no identity AND no service_role claim, which is
  -- exactly the class this migration exists to refuse. If some future caller
  -- reaches this with neither, it gets `not_responsible_for_de` — a refusal
  -- with a misleading noun, and that is the honest cost of keeping the line.
  if not public.can_access_de(p_de_id) then
    raise exception 'not_responsible_for_de: this employee is not in your reporting line';
  end if;

  insert into de_work_items (tenant_id, de_id, objective_id, title, kind,
                             scheduled_for, seq, depends_on, payload,
                             idempotency_key, max_attempts)
  values (p_tenant_id, p_de_id, p_objective_id, p_title, p_kind,
          coalesce(p_scheduled_for, now()), p_seq, p_depends_on, coalesce(p_payload, '{}'::jsonb),
          p_idempotency_key, greatest(1, p_max_attempts))
  on conflict (tenant_id, idempotency_key) where idempotency_key is not null
    do nothing
  returning id into v_id;

  -- ON CONFLICT DO NOTHING returns no row; fetch the existing one so the
  -- caller always gets a stable id for the same idempotency key.
  if v_id is null and p_idempotency_key is not null then
    select id into v_id from de_work_items
     where tenant_id = p_tenant_id and idempotency_key = p_idempotency_key;
  end if;
  return v_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.erd_human_task_id(p_decision_id uuid)
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select human_task_id from evidence_run_decisions where id = p_decision_id;
$function$;

CREATE OR REPLACE FUNCTION public.erp_ar_mirror_totals(p_tenant_id uuid, p_provider text)
 RETURNS TABLE(cnt bigint, cents bigint)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select count(*)::bigint, coalesce(sum(amount_cents), 0)::bigint
  from renewal_invoices
  where tenant_id = p_tenant_id and source_provider = p_provider;
$function$;

CREATE OR REPLACE FUNCTION public.evaluate_authority(p_tenant_id uuid, p_actor_kind text, p_actor_id uuid, p_category text, p_measures jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  r            record;
  v_rank       int;
  v_worst      int := 0;                  -- 0 allow, 1 human, 2 second, 3 deny
  v_reasons    jsonb := '[]'::jsonb;
  v_measures   jsonb := coalesce(p_measures, '{}'::jsonb);
  v_val        numeric;
  v_present    boolean;
  v_trips      boolean;
  v_unreadable boolean;
begin
  if p_tenant_id is null then
    return jsonb_build_object('outcome','require_human',
      'reasons', jsonb_build_array(jsonb_build_object('why','no workspace in context')));
  end if;

  -- ⛔ FAIL CLOSED ON THE ACTOR, not only on the measures. Left unguarded, an
  -- unrecognised or absent p_actor_kind, or a scoped kind with no
  -- p_actor_id, would just match nothing in the loop below and fall out
  -- through v_worst's default of 0 — permission by omission, one parameter
  -- over from the bug this function exists to end.
  --
  -- ⚠ 'role' and 'org_unit' are RULE-scoping vocabulary, not actor kinds — a
  -- rule scopes to a role or a unit, but no caller ever IS one. authority_
  -- rules_actor_shape (mig 770) already forces actor_id null for a 'role'
  -- rule, so a caller that passed ('role', <uuid>) as ITS OWN kind would
  -- match nothing in the loop below (ar.actor_kind = p_actor_kind never
  -- holds, since no rule's actor_kind is ever 'role' paired with a live
  -- actor_id) and silently fall out through v_worst's default of 0 — allow.
  -- Only the two kinds a caller can actually BE, plus 'all', are accepted.
  if p_actor_kind is null or p_actor_kind not in ('all','user','de') then
    return jsonb_build_object('outcome','require_human',
      'reasons', jsonb_build_array(jsonb_build_object(
        'why', format('unknown actor kind: %s is not a kind this evaluator recognizes', coalesce(p_actor_kind, '<null>')))));
  end if;

  if p_actor_kind <> 'all' and p_actor_id is null then
    return jsonb_build_object('outcome','require_human',
      'reasons', jsonb_build_array(jsonb_build_object(
        'why', format('unidentified actor: actor_kind %s was given with no actor_id', p_actor_kind))));
  end if;

  -- ⛔ THE ACTOR MUST RESOLVE, NOT MERELY BE WELL-SHAPED. A stale, cross-
  -- tenant, or edge-function-relayed id that names nobody in p_tenant_id
  -- would otherwise pass the shape check above and then silently lose every
  -- role- and unit-derived rule below — their EXISTS joins simply find no
  -- row — and fall out through v_worst's default of 0, returning the most
  -- permissive answer available. Do NOT silently narrow to whatever rules
  -- happen to still match; escalate instead.
  -- ⛔ AND IT MUST BE ACTIVE. Without `coalesce(is_active, true)` this guard
  -- escalates for a profile that does not EXIST but waves through one that has
  -- been DEACTIVATED — and the role arm below filters on exactly that flag, so
  -- an offboarded user resolves here, matches no role-scoped rule there, and
  -- receives the most permissive answer available. That is the likelier real
  -- case of the two: people are offboarded far more often than user ids are
  -- fabricated. It is also the same polarity trap the org-unit comment sixty
  -- lines below warns about — a filter that means "fewer grants" in
  -- has_approval_authority means "fewer restrictions" here.
  if p_actor_kind = 'user' and not exists (
       select 1 from profiles
        where user_id = p_actor_id and tenant_id = p_tenant_id
          and coalesce(is_active, true)) then
    return jsonb_build_object('outcome','require_human',
      'reasons', jsonb_build_array(jsonb_build_object(
        'why', format('unidentified actor: no active profile for user %s in this workspace', p_actor_id))));
  end if;

  if p_actor_kind = 'de' and not exists (
       select 1 from digital_employees where id = p_actor_id and tenant_id = p_tenant_id) then
    return jsonb_build_object('outcome','require_human',
      'reasons', jsonb_build_array(jsonb_build_object(
        'why', format('unidentified actor: no digital employee %s in this workspace', p_actor_id))));
  end if;

  for r in
    select ar.dimension, ar.comparator, ar.threshold, ar.outcome, ad.value_type
      from authority_rules ar
      join authority_dimensions ad on ad.dimension = ar.dimension
     where ar.tenant_id = p_tenant_id
       and ar.is_active
       -- ⛔ p_category IS NULL must NOT narrow to global-only rules.
       -- task_approval_facts can genuinely return a null category, and the
       -- strictest reading of "I don't know the category" is "every
       -- category-scoped rule applies", not "no category-scoped rule does".
       and (p_category is null or ar.category is null or ar.category = p_category)
       and (
         ar.actor_kind = 'all'
         or (ar.actor_kind = p_actor_kind and ar.actor_id = p_actor_id)
         -- ⚠ A PERSON IS ALSO REACHED BY THEIR ROLE AND THEIR ORG UNIT, and
         -- by any unit ABOVE the one they belong to. The walk direction
         -- mirrors has_approval_authority (mig 593) — an evaluator that only
         -- matched exact actor ids would fail step 2's differential against
         -- it on every role-scoped and unit-scoped row, which is 151 rows
         -- today. It does NOT mirror 593's is_active pruning: see the note
         -- at the recursive CTE below for why that pruning would fail open
         -- here.
         or (p_actor_kind = 'user' and ar.actor_kind = 'role' and exists (
               select 1 from profiles pr
                where pr.user_id = p_actor_id and pr.tenant_id = p_tenant_id
                  and coalesce(pr.is_active, true)
                  and pr.role = ar.actor_role))
         or (p_actor_kind = 'user' and ar.actor_kind = 'org_unit' and exists (
               -- ⚠ THIS WALK MUST NOT PRUNE ON is_active. mig 593 prunes an
               -- inactive intermediate unit out of a walk that computes
               -- GRANTS — losing a branch there loses authority, which
               -- fails closed. Here the walk computes a RESTRICTION's
               -- reach: losing a branch would let one inactive intermediate
               -- unit silently exempt its whole live subtree from a rule
               -- above it, which fails OPEN. Do not "restore" an is_active
               -- filter here to make this match 593 again — the polarity
               -- difference is the point, not an oversight.
               with recursive below as (
                 select ar.actor_id as id
                 union
                 select u.id from org_units u join below b on u.parent_id = b.id
               )
               select 1 from org_unit_members m
                where m.user_id = p_actor_id and m.is_active
                  and m.org_unit_id in (select id from below)))
       )
     order by ar.dimension, ar.comparator, ar.threshold, ar.id
  loop
    v_rank := 0;  -- local to this rule; only "if v_rank > v_worst" below promotes it

    -- ⛔ `?` TESTS KEY PRESENCE, NOT MEASUREMENT. {"amount_cents": null} has
    -- the key, and 74% of pending approvals carry no amount exactly that
    -- way — a JSON null must be treated like an absent key, not like zero
    -- or false.
    v_present := (v_measures ? r.dimension) and jsonb_typeof(v_measures -> r.dimension) <> 'null';

    if not v_present then
      -- ⛔ absence escalates. Never `or` past it.
      v_rank := 1;
      v_reasons := v_reasons || jsonb_build_object(
        'dimension', r.dimension, 'comparator', r.comparator, 'threshold', r.threshold,
        'outcome', 'require_human', 'rule_outcome', r.outcome, 'unverified', true,
        'why', format('unmeasured: this action did not report %s, and a rule depends on it', r.dimension));
    else
      -- ⛔ A MALFORMED MEASURE FAILS CLOSED, NOT RAISES. This function IS the
      -- fail-closed guarantee; it cannot delegate that guarantee back to a
      -- caller by letting a bad cast abort the transaction — this repo has
      -- a standing trap where `.rpc()` resolves on a Postgres error, so an
      -- unhandled exception here can read as silence, not as a refusal.
      v_unreadable := false;
      begin
        if r.value_type = 'boolean' then
          v_val := case when coalesce((v_measures->>r.dimension)::boolean, false) then 1 else 0 end;
        else
          v_val := (v_measures->>r.dimension)::numeric;
        end if;
      exception when others then
        v_unreadable := true;
      end;

      if v_unreadable then
        v_rank := 1;
        v_reasons := v_reasons || jsonb_build_object(
          'dimension', r.dimension, 'comparator', r.comparator, 'threshold', r.threshold,
          'outcome', 'require_human', 'rule_outcome', r.outcome, 'unverified', true,
          'why', format('unreadable measure: %s could not be read as %s', r.dimension, r.value_type));
      else
        v_trips := case r.comparator
          when '>'  then v_val >  r.threshold
          when '>=' then v_val >= r.threshold
          when '<'  then v_val <  r.threshold
          when '<=' then v_val <= r.threshold
          when 'is' then v_val =  r.threshold
          else null
        end;

        if v_trips is null then
          -- Unknown comparator — only reachable if the registry ever grows
          -- one this function was not updated to evaluate. Escalate, do not
          -- raise: raising is exactly what the branch above exists to stop
          -- doing, and silently not-firing is exactly the bug this whole
          -- function exists to end.
          v_rank := 1;
          v_reasons := v_reasons || jsonb_build_object(
            'dimension', r.dimension, 'comparator', r.comparator, 'threshold', r.threshold,
            'outcome', 'require_human', 'rule_outcome', r.outcome, 'unverified', true,
            'why', format('unknown comparator: %s is not understood by this evaluator', r.comparator));
        elsif not v_trips then
          continue;
        else
          v_rank := case r.outcome
            when 'deny' then 3 when 'require_second_approver' then 2 else 1 end;
          v_reasons := v_reasons || jsonb_build_object(
            'dimension', r.dimension, 'comparator', r.comparator, 'threshold', r.threshold,
            'outcome', r.outcome,
            'why', format('%s %s %s', r.dimension, r.comparator, r.threshold));
        end if;
      end if;
    end if;

    if v_rank > v_worst then v_worst := v_rank; end if;
  end loop;

  return jsonb_build_object(
    'outcome', case v_worst when 3 then 'deny' when 2 then 'require_second_approver'
                            when 1 then 'require_human' else 'allow' end,
    'reasons', v_reasons);
end
$function$;

CREATE OR REPLACE FUNCTION public.evidence_is_production(p_origin text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
AS $function$ select coalesce(p_origin, 'production') <> 'exercise' $function$;

CREATE OR REPLACE FUNCTION public.expire_trials()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_demo_tenant_id constant uuid := 'a0000000-0000-0000-0000-000000000001';
  v_count int;
begin
  with expired as (
    update tenants
    set status = 'suspended', updated_at = now()
    where status = 'trial'
      and trial_ends_at is not null
      and trial_ends_at < now()
      and id <> v_demo_tenant_id
    returning id, name
  )
  select count(*) into v_count from expired;

  return coalesce(v_count, 0);
end;
$function$;

CREATE OR REPLACE FUNCTION public.export_tenant_config(p_tenant_id uuid)
 RETURNS TABLE(metrics jsonb, schemas jsonb, configs jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  PERFORM public._assert_caller_tenant(p_tenant_id);
  RETURN QUERY
  SELECT
    (SELECT jsonb_agg(row_to_json(t)) FROM customer_metrics t WHERE t.tenant_id = p_tenant_id),
    (SELECT jsonb_agg(row_to_json(t)) FROM de_config_schemas t WHERE t.tenant_id = p_tenant_id),
    (SELECT jsonb_agg(row_to_json(t)) FROM de_config t WHERE t.tenant_id = p_tenant_id);
END$function$;

CREATE OR REPLACE FUNCTION public.export_tenant_manifest(p_tenant uuid, p_include_counts boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  s             record;
  v_sql         text;
  v_where       text;
  -- Named v_count, not n: the queries below alias pg_namespace as `n`, and a
  -- plpgsql scalar sharing a name with a table alias is a resolution conflict,
  -- not a style nit.
  v_count       bigint;
  v_tables      jsonb  := '[]'::jsonb;
  v_blocked     jsonb  := '[]'::jsonb;
  v_total       bigint := 0;
  v_nonempty    int    := 0;
  v_exportable  int    := 0;
  v_surface     text[] := '{}';
  v_public_rel  int;
  v_views       int;
  v_tenant      record;
begin
  if not public.can_admin_tenant_internal(p_tenant) then
    raise exception 'not authorized to export tenant %', p_tenant using errcode = '42501';
  end if;

  select id, slug, name, status, created_at into v_tenant
    from tenants where id = p_tenant;
  if not found then
    raise exception 'tenant % not found', p_tenant using errcode = '22023';
  end if;

  for s in select * from public.export_tenant_surface() loop
    v_surface := v_surface || s.table_name;

    -- Reasons a table cannot be exported are REPORTED, never swallowed. Both
    -- conditions are empty in production today; they exist so that the day one
    -- of them stops being empty, the customer is told instead of shortchanged.
    if s.pk_columns is null then
      v_blocked := v_blocked || jsonb_build_object(
        'table', s.table_name,
        'reason', 'no primary key — rows cannot be paginated deterministically');
      continue;
    end if;
    if s.pk_columns && s.redacted_columns then
      -- The pager derives the next cursor from the last row's primary key. A
      -- redacted PK would make that cursor a marker string and paging would stop
      -- after one page: a partial export presented as a whole one.
      v_blocked := v_blocked || jsonb_build_object(
        'table', s.table_name,
        'reason', 'primary key is credential material and is redacted, so pages cannot be chained');
      continue;
    end if;

    v_exportable := v_exportable + 1;
    v_count := null;
    if p_include_counts then
      v_where := public.export_tenant_scope_sql(s.scope, s.parent_links);
      v_sql := format('select count(*) from public.%I t where %s', s.table_name, v_where);
      execute v_sql into v_count using p_tenant;
      v_total := v_total + v_count;
      if v_count > 0 then v_nonempty := v_nonempty + 1; end if;
    end if;

    v_tables := v_tables || jsonb_build_object(
      'table', s.table_name,
      'rows', v_count,
      'scope', case when s.scope = 'tenant_id'
                    then 'rows where tenant_id = your tenant'
                    else 'rows whose parent record belongs to your tenant' end,
      'primary_key', to_jsonb(s.pk_columns),
      'columns_omitted', to_jsonb(s.omitted_columns),
      'columns_redacted', to_jsonb(s.redacted_columns),
      'parent_links', s.parent_links);
  end loop;

  select count(*) filter (where c.relkind = 'r'),
         count(*) filter (where c.relkind in ('v', 'm'))
    into v_public_rel, v_views
    from pg_class c
    join pg_namespace n on n.oid = c.relnamespace
   where n.nspname = 'public' and c.relkind in ('r', 'v', 'm');

  -- A bulk read of every row a tenant owns is exactly the event an auditor asks
  -- about. One row per export, on the same hash-chained trail as everything else.
  perform public.append_audit_event_internal(
    p_tenant,
    coalesce(auth.uid()::text, 'service_role'),
    case when auth.uid() is null then 'system' else 'human' end,
    'tenant_data_export_started',
    'access_control',
    jsonb_build_object(
      'tables', v_exportable,
      'rows', case when p_include_counts then v_total end,
      'counts_included', p_include_counts));

  return jsonb_build_object(
    'format_version', 1,
    'generated_at', now(),
    'tenant', jsonb_build_object(
      'id', v_tenant.id, 'slug', v_tenant.slug, 'name', v_tenant.name,
      'status', v_tenant.status, 'created_at', v_tenant.created_at),
    'counts', jsonb_build_object(
      'tables_exportable', v_exportable,
      'tables_with_rows', case when p_include_counts then v_nonempty end,
      'total_rows',       case when p_include_counts then v_total end,
      'counts_included',  p_include_counts),
    'tables', v_tables,
    'not_exportable', v_blocked,

    -- ────────────────────────────────────────────────────────────────────────
    -- Read this before treating the archive as a backup. Every list below is
    -- COMPUTED from the catalog, not typed out, so none of it can go stale.
    -- ────────────────────────────────────────────────────────────────────────
    'not_included', jsonb_build_object(
      'summary',
        'This is a data extract, not a system backup. It contains your rows. '
        || 'It cannot by itself restore a working DreamTeam workspace.',
      'user_accounts',
        'Login accounts, password hashes and SSO identities are not included. '
        || 'Your team members appear in the profiles table as records, but those '
        || 'records cannot be used to sign in anywhere.',
      'files',
        'Uploaded files held in object storage are not included. Their database '
        || 'records — paths, names, extracted text — are.',
      'credentials',
        'Connector credentials, widget signing keys and API tokens are either '
        || 'excluded outright or shown as a redaction marker. They are secrets, '
        || 'and an export carrying them would be a breach waiting for a shared drive.',
      'derived_data',
        'Search embeddings are excluded — they are computed from your own text '
        || 'and are regenerated automatically.',
      'system',
        'Application source, edge functions, scheduled jobs, database schema and '
        || 'access-control policies are not included.',
      'tables_excluded_by_name', (
        select coalesce(jsonb_agg(jsonb_build_object(
                 'table', c.relname, 'reason', 'whole-table credential store')
                 order by c.relname), '[]'::jsonb)
          from pg_class c join pg_namespace n on n.oid = c.relnamespace
         where n.nspname = 'public' and c.relkind = 'r'
           and c.relname like '%\_secrets'),
      'tables_not_tenant_scoped', (
        -- Platform-wide catalogs and our own operational tables. They hold no
        -- rows attributable to a single tenant, which is precisely why they are
        -- out — but the customer gets to see the list and judge for themselves.
        select coalesce(jsonb_agg(c.relname order by c.relname), '[]'::jsonb)
          from pg_class c join pg_namespace n on n.oid = c.relnamespace
         where n.nspname = 'public' and c.relkind = 'r'
           and not (c.relname = any(v_surface))
           and c.relname not like '%\_secrets'),
      'views_excluded', (
        select coalesce(jsonb_agg(c.relname order by c.relname), '[]'::jsonb)
          from pg_class c join pg_namespace n on n.oid = c.relnamespace
         where n.nspname = 'public' and c.relkind in ('v', 'm')),
      'coverage', format(
        '%s of the %s tables in this database are exported for your tenant. '
        || 'The remaining %s hold no rows attributable to a single tenant or are '
        || 'listed above; a further %s database views are omitted because they '
        || 'only restate rows already included.',
        coalesce(array_length(v_surface, 1), 0),
        v_public_rel,
        v_public_rel - coalesce(array_length(v_surface, 1), 0),
        v_views)
    ));
end;
$function$;

CREATE OR REPLACE FUNCTION public.export_tenant_scope_sql(p_scope text, p_parent_links jsonb)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
declare
  l        jsonb;
  v_mine   text;
  v_any    text := '';
  v_notyours text := '';
begin
  if p_scope = 'tenant_id' then
    return 't.tenant_id = $1';
  end if;

  -- via_parent. The rule is: at least one tenant-scoped parent is MINE, and NO
  -- tenant-scoped parent belongs to a DIFFERENT tenant. The second half is what
  -- makes this safe for the multi-parent tables — de_role_assignments points at
  -- both digital_employees and playbook_definitions, and a row whose playbook
  -- belongs to someone else is withheld from both sides rather than leaked to
  -- either.
  --
  -- "is not null and <> $1" rather than "= $1" is load-bearing, and it was a
  -- live production row that proved it: tenant_provisioning_requests has one row
  -- whose requester belongs to acme-telecom and whose reviewer is a platform
  -- admin, and a platform admin's profile has tenant_id NULL by design. A
  -- stricter "every parent must be mine" test let that NULL veto the row, so the
  -- customer's own provisioning request was withheld from the customer. A parent
  -- owned by nobody is not evidence that a row belongs to someone else.
  for l in select value from jsonb_array_elements(p_parent_links) loop
    v_mine := format(
      'exists (select 1 from public.%I p where p.%I = t.%I and p.tenant_id = $1)',
      l->>'parent_table', l->>'parent_column', l->>'fk_column');
    v_any := case when v_any = '' then v_mine else v_any || ' or ' || v_mine end;
    -- A NULL fk needs no special case: the NOT EXISTS is trivially true for it.
    v_notyours := v_notyours || format(
      ' and not exists (select 1 from public.%I p where p.%I = t.%I'
      || ' and p.tenant_id is not null and p.tenant_id <> $1)',
      l->>'parent_table', l->>'parent_column', l->>'fk_column');
  end loop;

  if v_any = '' then
    raise exception 'no tenant-scoped parent link for a via_parent table'
      using errcode = '22023';
  end if;
  return '(' || v_any || ')' || v_notyours;
end;
$function$;

CREATE OR REPLACE FUNCTION public.export_tenant_surface()
 RETURNS TABLE(table_name text, scope text, pk_columns text[], pk_types text[], data_columns text[], omitted_columns text[], redacted_columns text[], parent_links jsonb)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  with rels as (
    select c.oid, c.relname
      from pg_class c
      join pg_namespace n on n.oid = c.relnamespace
     -- relkind 'r' only. eval_gate and pipeline_summary are VIEWS (confirmed in
     -- pg_class, relkind='v'), so they hold no rows of their own and exporting
     -- them would only restate rows the base tables already ship.
     where n.nspname = 'public'
       and c.relkind = 'r'
       -- connector_secrets, specialist_source_secrets, widget_key_secrets.
       -- Whole-table credential stores with no useful non-secret residue.
       and c.relname not like '%\_secrets'
       -- ⚠ PLATFORM-OPERATIONS DATA WEARING A tenant_id.
       -- tenant_deletion_receipts (migration 371) carries a tenant_id so that a
       -- receipt survives the tenant it records — which is exactly what makes a
       -- catalog-driven surface pick it up. Its own COMMENT says "Platform-
       -- operations data, not tenant data", and its only protection is
       -- RLS-with-no-policy, which the SECURITY DEFINER pager below bypasses by
       -- design. Neither migration is wrong alone; the defect only exists once
       -- both are applied, which is why it needs naming here.
       -- Excluding it also keeps the customer-facing table count stable at 226
       -- rather than silently becoming 227 the day 371 lands.
       and c.relname <> 'tenant_deletion_receipts'
  ),
  direct as (
    select r.oid, r.relname
      from rels r
     where exists (select 1 from pg_attribute a
                    where a.attrelid = r.oid and a.attname = 'tenant_id'
                      and not a.attisdropped)
  ),
  links as (
    -- Single-column FKs from a non-tenant_id table into a tenant_id table.
    -- Multi-column FKs are skipped: none exist today, and half a join key cannot
    -- be shown to be tenant-scoped.
    select k.conrelid as oid,
           (select a.attname from pg_attribute a
             where a.attrelid = k.conrelid and a.attnum = k.conkey[1]) as fk_column,
           p.relname as parent_table,
           (select a.attname from pg_attribute a
             where a.attrelid = k.confrelid and a.attnum = k.confkey[1]) as parent_column
      from pg_constraint k
      join pg_class p on p.oid = k.confrelid
     where k.contype = 'f'
       and array_length(k.conkey, 1) = 1
       and k.confrelid in (select oid from direct)
       and k.conrelid  in (select oid from rels)
       and k.conrelid not in (select oid from direct)
  ),
  child as (
    select r.oid, r.relname
      from rels r
     where r.oid in (select oid from links)
       -- platform_capability_grants and platform_invites reach a tenant only
       -- through profiles. They are OUR records about platform operators, not
       -- the customer's business data, and belong in no customer's archive.
       and r.relname not like 'platform\_%'
  ),
  src as (
    select oid, relname, 'tenant_id'::text  as scope from direct
    union all
    select oid, relname, 'via_parent'::text as scope from child
  ),
  pk as (
    select i.indrelid as oid,
           array_agg(a.attname                           order by k.ord) as cols,
           array_agg(format_type(a.atttypid, a.atttypmod) order by k.ord) as types
      from pg_index i
      cross join lateral unnest(i.indkey::int[]) with ordinality as k(attnum, ord)
      join pg_attribute a on a.attrelid = i.indrelid and a.attnum = k.attnum
     where i.indisprimary
     group by i.indrelid
  ),
  cols as (
    select a.attrelid as oid, a.attname, a.attnum,
           -- pgvector registers vector/halfvec in public and format_type()
           -- renders them as 'vector(384)', so match typname, not the rendered
           -- text — the reason a first pass at this found zero embedding columns.
           (t.typname in ('vector', 'halfvec')) as is_embedding,
           (a.attname ~ '^(secret|password|token_hash|api_key|private_key|client_secret|access_token|refresh_token)$'
            or a.attname ~ '_(secret|password|token_hash|api_key|private_key)$'
            or a.attname like 'encrypted\_%') as is_credential
      from pg_attribute a
      join pg_type t on t.oid = a.atttypid
     where a.attnum > 0 and not a.attisdropped
       and a.attrelid in (select oid from src)
  )
  select s.relname,
         s.scope,
         pk.cols,
         pk.types,
         (select array_agg(c.attname order by c.attnum) from cols c
           where c.oid = s.oid and not c.is_embedding),
         (select coalesce(array_agg(c.attname order by c.attnum), '{}') from cols c
           where c.oid = s.oid and c.is_embedding),
         (select coalesce(array_agg(c.attname order by c.attnum), '{}') from cols c
           where c.oid = s.oid and c.is_credential),
         (select coalesce(jsonb_agg(jsonb_build_object(
                    'fk_column',     l.fk_column,
                    'parent_table',  l.parent_table,
                    'parent_column', l.parent_column) order by l.fk_column), '[]'::jsonb)
            from links l where l.oid = s.oid)
    from src s
    -- LEFT, not INNER: a PK-less table must surface as unexportable, not vanish.
    -- All 226 have a primary key today (215 single-column, 11 composite) and this
    -- must not depend on that staying true.
    left join pk on pk.oid = s.oid
   order by s.relname;
$function$;

CREATE OR REPLACE FUNCTION public.export_tenant_table_page(p_tenant uuid, p_table text, p_cursor jsonb DEFAULT NULL::jsonb, p_limit integer DEFAULT 500, p_session uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  s        record;
  v_where  text;
  v_select text;
  v_order  text;
  v_after  text := '';
  v_limit  int;
  v_sql    text;
  v_rows   jsonb;
  v_n      int;
  v_cursor jsonb := null;
  -- Not named `c`: the unnest aliases below expose a column called col, and a
  -- scalar variable colliding with a query alias is a plpgsql resolution hazard.
  v_cur_val text;
begin
  if not public.can_admin_tenant_internal(p_tenant) then
    raise exception 'not authorized to export tenant %', p_tenant using errcode = '42501';
  end if;

  -- Catalog lookup BEFORE any SQL is composed. This is the validation that makes
  -- the format('%I') calls below a second line of defence rather than the only one.
  select * into s from public.export_tenant_surface() where table_name = p_table;
  if not found then
    raise exception 'table % is not part of the tenant export surface', p_table
      using errcode = '22023';
  end if;
  if s.pk_columns is null then
    raise exception 'table % has no primary key and cannot be paginated', p_table
      using errcode = '22023';
  end if;
  if s.pk_columns && s.redacted_columns then
    raise exception 'table % has a redacted primary key and cannot be paginated', p_table
      using errcode = '22023';
  end if;

  v_where := public.export_tenant_scope_sql(s.scope, s.parent_links);

  -- ── Per-document ACL (mig 377, preserved here) ────────────────────────────
  -- This function is SECURITY DEFINER, so RLS does not apply and
  -- knowledge_docs_acl_select (migs 343/344, hardened by 357) is bypassed. That
  -- policy exempts is_platform_admin() ONLY — deliberately not tenant_admin,
  -- because 357 exists so that "admin" does not mean "reads every restricted
  -- Space". Delegates to the same helpers the policy uses rather than restating
  -- the rule, so the two cannot drift apart.
  -- Latent today: 0 docs have restricted_space_id set. It closes the day one does.
  if p_table = 'knowledge_docs'
     and coalesce(auth.role(), '') <> 'service_role'
     and not public.is_platform_admin() then
    v_where := v_where || ' and (t.restricted_space_id is null and t.inherits_access'
            || ' or exists (select 1 from knowledge_access_grants g'
            || '             where g.tenant_id = t.tenant_id'
            || '               and knowledge_permission_rank(g.permission) >= 1'
            || '               and knowledge_grant_matches_caller(g.*)'
            || '               and (g.resource_type = ''workspace'''
            || '                 or (g.resource_type = ''space'' and g.resource_id = t.restricted_space_id)'
            || '                 or (g.resource_type = ''document'' and g.resource_id = t.id))))';
  end if;

  -- 2000 caps ONE page's memory here and in the caller. It is not a cap on the
  -- export: the caller keeps paging until complete.
  v_limit := least(greatest(coalesce(p_limit, 500), 1), 2000);

  select string_agg(
           case when u.col = any(s.redacted_columns)
                then format('%L::text as %I',
                            '[redacted: credential material — not exported]', u.col)
                else format('t.%I', u.col) end,
           ', ' order by u.ord)
    into v_select
    from unnest(s.data_columns) with ordinality as u(col, ord);

  select string_agg(format('t.%I', u.col), ', ' order by u.ord)
    into v_order
    from unnest(s.pk_columns) with ordinality as u(col, ord);

  if p_cursor is not null then
    if jsonb_typeof(p_cursor) <> 'array'
       or jsonb_array_length(p_cursor) <> array_length(s.pk_columns, 1) then
      raise exception 'cursor must be an array of % primary key value(s) for %',
        array_length(s.pk_columns, 1), p_table using errcode = '22023';
    end if;
    for v_cur_val in select jsonb_array_elements_text(p_cursor) loop
      if v_cur_val is null then
        -- A NULL anywhere in a row comparison makes the whole predicate NULL,
        -- which returns zero rows and reads to the caller as "export finished".
        raise exception 'cursor values may not be null' using errcode = '22023';
      end if;
    end loop;
    -- (a,b,c) > (x,y,z) is row-wise comparison in Postgres and it matches
    -- ORDER BY a,b,c exactly, so this means "strictly after the last row of the
    -- previous page" for composite keys as well as single ones. Verified against
    -- production on knowledge_doc_usage_daily (tenant_id, doc_id, usage_date):
    -- 97 rows, 3 returned, 94 remaining after the cursor — no gap, no overlap.
    -- The cast target comes from format_type() in the catalog, never the caller.
    select format(' and (%s) > (%s)',
             v_order,
             string_agg(format('%L::%s', p_cursor->>(u.ord - 1)::int, u.ty),
                        ', ' order by u.ord))
      into v_after
      from unnest(s.pk_columns, s.pk_types) with ordinality as u(col, ty, ord);
  end if;

  v_sql := format(
    'select coalesce(jsonb_agg(to_jsonb(x)), ''[]''::jsonb) from ('
    || 'select %s from public.%I t where %s%s order by %s limit %s) x',
    v_select, p_table, v_where, v_after, v_order, v_limit);
  execute v_sql into v_rows using p_tenant;

  v_n := jsonb_array_length(v_rows);
  if v_n > 0 then
    -- Rows come back in primary-key order, so the last element carries the next
    -- cursor. Safe to read back out of the JSON because a redacted primary key
    -- was rejected above.
    select jsonb_agg(v_rows -> (v_n - 1) ->> u.col order by u.ord)
      into v_cursor
      from unnest(s.pk_columns) with ordinality as u(col, ord);
  end if;

  -- ── Audit (mig 377, preserved) ────────────────────────────────────────────
  -- 372 audited the MANIFEST only, while this pager is separately granted to
  -- authenticated — so a tenant_admin could page every row of all 226 tables
  -- over PostgREST and leave no trace. Deduped per (session, table).
  if p_session is not null then
    insert into audit_events (tenant_id, actor, actor_type, action, category, detail, created_at)
    select p_tenant,
           coalesce((select full_name from profiles where user_id = auth.uid()), 'unknown'),
           'user', format('Exported table %s', p_table), 'data_export',
           jsonb_build_object('table', p_table, 'export_session', p_session),
           now()
     where not exists (
       select 1 from audit_events a
        where a.tenant_id = p_tenant and a.category = 'data_export'
          and a.detail->>'export_session' = p_session::text
          and a.detail->>'table' = p_table);
  end if;

  return jsonb_build_object(
    'table', p_table,
    'rows', v_rows,
    'returned', v_n,
    -- A short page means the table is drained. A full page is ambiguous, so we
    -- report not-complete and let the caller make one more call that returns
    -- zero rows. Guessing here is how an export loses its tail.
    'complete', v_n < v_limit,
    'next_cursor', v_cursor);
end;
$function$;

CREATE OR REPLACE FUNCTION public.fail_dependents_of_failed_steps()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE n int; v_total int := 0; v_rounds int := 0;
BEGIN
  -- Loop because failing a child creates a new failed parent for ITS children.
  -- Bounded: each round strictly shortens the longest live chain.
  LOOP
    v_rounds := v_rounds + 1;
    UPDATE de_work_items w
       SET status = 'failed', updated_at = now(),
           last_error = format('Cannot run: the step it depends on failed — "%s"', left(coalesce(p.title, 'earlier step'), 120))
      FROM de_work_items p
     WHERE w.depends_on = p.id
       AND w.status = 'queued'
       AND p.status = 'failed'
       AND tenant_is_operational(w.tenant_id);
    GET DIAGNOSTICS n = ROW_COUNT;
    v_total := v_total + n;
    EXIT WHEN n = 0 OR v_rounds >= 20;
  END LOOP;

  -- Tell somebody. A goal with a broken chain needs a person to decide whether
  -- to retry it, change the approach, or drop it — it must not look abandoned.
  UPDATE de_objectives o
     SET attention_flag = 'steps_failed',
         attention_since = coalesce(o.attention_since, now()),
         updated_at = now()
   WHERE o.status IN ('open', 'in_progress', 'blocked')
     AND o.attention_flag IS DISTINCT FROM 'steps_failed'
     AND EXISTS (SELECT 1 FROM de_work_items w WHERE w.objective_id = o.id AND w.status = 'failed');

  RETURN jsonb_build_object('ok', true, 'failed_dependents', v_total, 'rounds', v_rounds);
END $function$;

CREATE OR REPLACE FUNCTION public.fail_ingestion_item(p_item_id uuid, p_error text, p_kind text DEFAULT 'retryable'::text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not authenticated: recording an ingestion failure is a platform operation, not an anonymous one';
  END IF;
  IF NOT is_platform_admin() THEN
    RAISE EXCEPTION 'not callable by tenant users';
  END IF;
  RETURN public.fail_ingestion_item_internal(p_item_id, p_error, p_kind);
END $function$;

CREATE OR REPLACE FUNCTION public.fail_ingestion_item_internal(p_item_id uuid, p_error text, p_kind text DEFAULT 'retryable'::text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_item knowledge_ingestion_items; v_final boolean; v_backoff interval;
BEGIN
  -- NO USER CHECK. Called by the drain with the service-role client.
  IF p_kind NOT IN ('retryable','terminal') THEN
    RAISE EXCEPTION 'error kind must be retryable or terminal, got %', p_kind;
  END IF;

  SELECT * INTO v_item FROM knowledge_ingestion_items WHERE id = p_item_id;
  IF v_item.id IS NULL THEN RAISE EXCEPTION 'ingestion item not found'; END IF;

  -- Terminal failures do not get their remaining attempts. Retrying an
  -- unreadable file three times just delays telling the human it is unreadable.
  v_final := (p_kind = 'terminal') OR (v_item.attempts >= v_item.max_attempts);

  IF v_final THEN
    UPDATE knowledge_ingestion_items
       SET status='failed', last_error=left(p_error, 2000), error_kind=p_kind, updated_at=now()
     WHERE id = p_item_id;
    RETURN 'failed';
  END IF;

  -- Exponential backoff, capped: 1m, 4m, 9m... never more than an hour.
  v_backoff := make_interval(secs => least(3600, 60 * power(greatest(v_item.attempts,1), 2)::int));
  UPDATE knowledge_ingestion_items
     SET status='queued', last_error=left(p_error, 2000), error_kind=p_kind,
         next_attempt_at = now() + v_backoff, updated_at=now()
   WHERE id = p_item_id;
  RETURN 'retry_scheduled';
END $function$;

CREATE OR REPLACE FUNCTION public.find_duplicate_knowledge_doc(p_tenant_id uuid, p_title text, p_content text)
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT d.id FROM knowledge_docs d
   WHERE d.tenant_id = p_tenant_id
     AND d.is_current
     AND d.content_hash = public.knowledge_content_hash(p_title, p_content)
   LIMIT 1;
$function$;

CREATE OR REPLACE FUNCTION public.finish_browser_task(p_task_id uuid, p_status text, p_result text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF coalesce(auth.role(),'') <> 'service_role' THEN RAISE EXCEPTION 'service-role only'; END IF;
  IF p_status NOT IN ('done','failed') THEN RAISE EXCEPTION 'status must be done or failed'; END IF;
  UPDATE computer_use_tasks
     SET status = p_status, result = left(coalesce(p_result, ''), 8000), updated_at = now()
   WHERE id = p_task_id AND status IN ('claimed','running');
END; $function$;

CREATE OR REPLACE FUNCTION public.forget_de_memory(p_memory_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tenant uuid := auth_tenant_id(); v_row de_memory;
BEGIN
  IF v_tenant IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  IF NOT auth_has_tenant_role(ARRAY['tenant_owner','tenant_admin']) THEN
    RAISE EXCEPTION 'insufficient_role';
  END IF;
  SELECT * INTO v_row FROM de_memory WHERE id = p_memory_id AND tenant_id = v_tenant;
  IF v_row.id IS NULL THEN RAISE EXCEPTION 'memory_not_found'; END IF;

  DELETE FROM de_memory WHERE id = p_memory_id;

  PERFORM append_audit_event(
    v_tenant, 'Workspace', 'human',
    format('Memory removed — %s', left(v_row.content, 120)), 'config_change',
    jsonb_build_object('de_id', v_row.de_id, 'kind', v_row.kind, 'subject_ref', v_row.subject_ref)
  );
  RETURN jsonb_build_object('ok', true);
END$function$;

CREATE OR REPLACE FUNCTION public.forget_end_user(p_tenant_id uuid, p_end_user_ref text, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_actor    text;
  v_convs    int := 0;
  v_msgs     int := 0;
  v_sessions int := 0;
  v_contacts int := 0;
  v_conv_ids uuid[];
begin
  -- ── rails ────────────────────────────────────────────────────────────────
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;
  if coalesce(btrim(p_end_user_ref), '') = '' then
    raise exception 'an end-user reference is required — refusing to erase on a blank subject';
  end if;
  if not (
    public.is_platform_admin()
    or (public.auth_tenant_id() = p_tenant_id
        and public.auth_has_tenant_role(array['tenant_owner', 'tenant_admin']))
  ) then
    raise exception 'only an owner or admin of this workspace may erase a person''s data';
  end if;

  select coalesce(full_name, 'unknown') into v_actor from profiles where user_id = auth.uid();

  -- ── the subject's conversations, resolved once and reused ────────────────
  select coalesce(array_agg(id), '{}') into v_conv_ids
    from de_conversations
   where tenant_id = p_tenant_id and end_user_ref = p_end_user_ref;

  -- ── measure BEFORE writing (see header) ──────────────────────────────────
  v_convs := coalesce(array_length(v_conv_ids, 1), 0);

  select count(*) into v_msgs from de_messages
   where tenant_id = p_tenant_id and conversation_id = any(v_conv_ids);

  select count(*) into v_sessions from end_user_sessions
   where tenant_id = p_tenant_id and end_user_ref = p_end_user_ref;

  select count(*) into v_contacts from customer_account_contacts
   where tenant_id = p_tenant_id and end_user_ref = p_end_user_ref;

  -- ── erase ────────────────────────────────────────────────────────────────
  -- The person's own words go; the employee's replies stay, because they are
  -- the workspace's record of what it told a customer and they do not identify
  -- the customer once the identifiers above are gone.
  update de_messages
     set content = '[erased at the data subject''s request]'
   where tenant_id = p_tenant_id and conversation_id = any(v_conv_ids);

  update de_conversations
     set end_user_ref = null,
         end_user_name = '[erased]',
         handoff_summary = case when handoff_summary is null then null
                                else '[erased at the data subject''s request]' end
   where id = any(v_conv_ids);

  delete from end_user_sessions
   where tenant_id = p_tenant_id and end_user_ref = p_end_user_ref;

  delete from customer_account_contacts
   where tenant_id = p_tenant_id and end_user_ref = p_end_user_ref;

  -- ── receipt ──────────────────────────────────────────────────────────────
  -- Audited under its own category so an erasure is findable later WITHOUT
  -- storing the reference that was erased. The subject key is deliberately not
  -- written into the audit detail: recording who was forgotten, in the log, in
  -- order to prove they were forgotten, defeats the point.
  perform public.append_audit_event(
    p_tenant_id, v_actor, 'human',
    format('Erased an end user''s personal data on request — %s conversation(s), %s message(s), %s session(s), %s contact(s)',
           v_convs, v_msgs, v_sessions, v_contacts),
    'access_control',
    jsonb_build_object(
      'conversations_pseudonymised', v_convs,
      'user_messages_erased',        v_msgs,
      'sessions_deleted',            v_sessions,
      'contacts_deleted',            v_contacts,
      'reason',                      coalesce(p_reason, 'data subject request')
    )
  );

  return jsonb_build_object(
    'ok', true,
    'conversations_pseudonymised', v_convs,
    'user_messages_erased',        v_msgs,
    'sessions_deleted',            v_sessions,
    'contacts_deleted',            v_contacts,
    'nothing_found', (v_convs + v_sessions + v_contacts) = 0
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.gate_de_certification()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare v_gated text[] := array['certified','published','assigned','active']; v_fp text;
begin
  if NEW.lifecycle_status = any(v_gated) and OLD.lifecycle_status is distinct from NEW.lifecycle_status
     and OLD.lifecycle_status <> all(v_gated) then
    -- Fingerprint NEW, not a re-SELECT of the pre-update row: a single
    -- statement changing config AND lifecycle is judged on the config
    -- that will actually go live (C1).
    v_fp := public.de_config_fingerprint_row(NEW);
    if not exists (
      select 1 from role_certifications c
       where c.de_id = NEW.id and c.status = 'passed'
         and c.config_fingerprint is not distinct from v_fp
    ) then
      if exists (select 1 from role_certifications c where c.de_id = NEW.id and c.status = 'passed') then
        raise exception 'DE % cannot advance to "%": its passing certification is STALE — the configuration (including changes in this statement) was not certified. Re-run its eval/simulation and re-certify first.', NEW.id, NEW.lifecycle_status;
      else
        raise exception 'DE % cannot advance to "%": it has not passed role certification. Run its eval/simulation and certify it first.', NEW.id, NEW.lifecycle_status;
      end if;
    end if;
  end if;
  return NEW;
end;
$function$;

CREATE OR REPLACE FUNCTION public.gate_knowledge_publish()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_gate record;
BEGIN
  -- Humans only: service-role pipelines and unauthenticated internals pass.
  IF coalesce(auth.role(), '') <> 'authenticated' THEN RETURN NEW; END IF;
  -- Revisions are the FIX path — never gate them.
  IF NEW.previous_version_id IS NOT NULL THEN RETURN NEW; END IF;
  -- The audited override tag from the client dialog passes.
  IF NEW.tags IS NOT NULL AND 'eval-gate-override' = ANY(NEW.tags) THEN RETURN NEW; END IF;

  SELECT status, passed, failed INTO v_gate
  FROM eval_gate WHERE tenant_id = NEW.tenant_id;
  IF v_gate.status = 'failed' THEN
    RAISE EXCEPTION 'eval_gate_failed: your latest evaluation run failed (% passed, % failed). Fix the failing answers in the Proving Ground, or use the override in the Library editor — overrides are recorded on the audit trail.',
      coalesce(v_gate.passed, 0), coalesce(v_gate.failed, 0)
      USING ERRCODE = 'P0001';
  END IF;
  RETURN NEW;
END $function$;

CREATE OR REPLACE FUNCTION public.get_agentic_run_messages(p_run_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_tenant uuid; v_out jsonb;
begin
  v_tenant := public.auth_tenant_id();
  if v_tenant is null then return jsonb_build_object('ok', false, 'error', 'not_permitted'); end if;
  -- The run must belong to the caller's tenant and to an employee the caller
  -- is responsible for, or no turns are returned.
  if not exists (select 1 from agentic_step_runs r where r.id = p_run_id and r.tenant_id = v_tenant and public.can_access_de(r.de_id)) then
    return jsonb_build_object('ok', false, 'error', 'run_not_found');
  end if;
  select coalesce(jsonb_agg(row_to_json(x) order by x.turn_index), '[]'::jsonb) into v_out from (
    select m.id, m.turn_index, m.role, m.content, m.created_at
      from agentic_step_messages m
     where m.agentic_step_run_id = p_run_id
     order by m.turn_index
  ) x;
  return jsonb_build_object('ok', true, 'messages', v_out);
end $function$;

CREATE OR REPLACE FUNCTION public.get_agentic_tools_for_de(p_tenant_id uuid, p_de_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tools jsonb := '[]'::jsonb;
  v_conn record;
  v_def record;
  v_verdict jsonb;
  v_properties jsonb;
  v_required jsonb;
  v_param record;
  v_type text;
  v_name text;     -- sanitized, connector-unique tool name
  v_suffix text;   -- per-connector discriminator
begin
  for v_conn in
    select id, category, display_name, provider
    from connectors
    where tenant_id = p_tenant_id and status = 'connected'
  loop
    for v_def in
      select *
      from action_definitions
      where status = 'active'
        and provider <> 'internal'
        and category = v_conn.category
        -- Matching on category ALONE offered an ERPNext-connected employee
        -- the Stripe/QuickBooks/Xero tools in the same category. Those could
        -- only ever fail: there is no such connector to run them against.
        and (provider is null or provider = v_conn.provider or provider = 'template')
        and (scope = 'platform' or (scope = 'tenant' and tenant_id = p_tenant_id))
    loop
      select resolve_access(p_tenant_id, 'de', p_de_id, v_conn.id, 'write_back') into v_verdict;
      -- mig 643: connector access says WHERE this employee may write; the role
      -- requirement says WHAT it may do there. Both must hold. Without the
      -- second, connecting the DreamTeam self-connector handed every employee
      -- in the workspace the verbs that create and hire other employees.
      if coalesce((v_verdict->>'allowed')::boolean, false)
         and public.de_may_use_action(p_tenant_id, p_de_id, v_def.id) then
        v_properties := '{}'::jsonb;
        v_required := '[]'::jsonb;

        for v_param in
          select * from jsonb_to_recordset(v_def.param_schema)
            as x(name text, type text, required boolean, help text)
        loop
          v_type := case v_param.type when 'number' then 'number' when 'boolean' then 'boolean' else 'string' end;
          v_properties := v_properties || jsonb_build_object(
            v_param.name, jsonb_build_object('type', v_type, 'description', coalesce(v_param.help, ''))
          );
          if coalesce(v_param.required, false) then
            v_required := v_required || to_jsonb(v_param.name);
          end if;
        end loop;

        -- Connector-unique + charset-safe + length-bounded (Anthropic: ^[a-zA-Z0-9_-]{1,64}$).
        v_suffix := '__' || left(replace(v_conn.id::text, '-', ''), 6) || left(md5(v_def.id::text), 4);
        -- Per-DEFINITION, not just per-connector. One action_key can have
        -- several executors (ERPNext comment vs ERPNext email), and the
        -- model rejects the ENTIRE call if any two tools share a name.
        v_name := regexp_replace(v_conn.category || '__' || v_def.action_key, '[^a-zA-Z0-9_-]', '_', 'g');
        v_name := left(v_name, 64 - length(v_suffix)) || v_suffix;

        v_tools := v_tools || jsonb_build_array(jsonb_build_object(
          'name', v_name,
          'description', v_def.label || '. ' || v_def.description
                         || ' (system: ' || coalesce(nullif(v_conn.display_name, ''), v_conn.provider) || ')',
          'input_schema', jsonb_build_object(
            'type', 'object', 'properties', v_properties, 'required', v_required
          ),
          'connector_id', v_conn.id,
          -- The EXACT definition this tool stands for. The name above already
          -- encodes it (mig 605 suffixes with md5(v_def.id)), but the caller was
          -- left to re-derive the action from (connector, action_key) — which is
          -- ambiguous whenever one key has several executors.
          'action_definition_id', v_def.id,
          'action_key', v_def.action_key,
          'destructive', coalesce((v_def.risk->>'destructive')::boolean, true)
        ));
      end if;
    end loop;
  end loop;

  return v_tools;
end;
$function$;

CREATE OR REPLACE FUNCTION public.get_all_tenants_with_summary()
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
  IF NOT is_platform_admin() THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;

  RETURN json_agg(
    json_build_object(
      'tenant_id', t.id,
      'name', t.name,
      'slug', t.slug,
      'status', t.status,
      'plan', t.plan,
      'industry', t.industry,
      'admin_email', t.admin_email,
      'adoption_score', COALESCE(t.adoption_score, 0),
      'de_count', de_cnt.count,
      'active_features', active_features.count,
      'monthly_cost', COALESCE(ROUND(tct.total_cost, 2), 0),
      'cost_vs_budget', CASE
        WHEN tft.monthly_cost_limit IS NOT NULL
        THEN ROUND(100 * tct.total_cost / tft.monthly_cost_limit, 1)
        ELSE NULL
      END,
      'created_at', t.created_at::text
    )
  )
  FROM tenants t
  LEFT JOIN tenant_feature_toggles tft ON tft.tenant_id = t.id
  LEFT JOIN tenant_cost_tracking tct ON tct.tenant_id = t.id
    AND tct.billing_month = to_char(now(), 'YYYY-MM')
  LEFT JOIN LATERAL (
    SELECT COUNT(*) as count FROM digital_employees
    WHERE tenant_id = t.id
  ) de_cnt ON true
  LEFT JOIN LATERAL (
    SELECT COUNT(*) as count FROM tenant_feature_toggles
    WHERE tenant_id = t.id
    AND (sophie_config_enabled OR amendment_journeys_enabled OR metrics_tracking_enabled
      OR reply_mode_enabled OR hosted_chat_enabled)
  ) active_features ON true
  ORDER BY t.created_at DESC;
END;
$function$;

CREATE OR REPLACE FUNCTION public.get_amendment_effectiveness(p_entity_kind text, p_entity_id uuid)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tenant_id UUID := public.auth_tenant_id();
  v_total INT; v_adopted INT;
  v_conf NUMERIC; v_esc NUMERIC; v_replay NUMERIC;
BEGIN
  IF v_tenant_id IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;

  SELECT COUNT(*), COUNT(*) FILTER (WHERE adopted_at IS NOT NULL)
  INTO v_total, v_adopted
  FROM amendment_metrics
  WHERE entity_kind = p_entity_kind AND entity_id = p_entity_id AND tenant_id = v_tenant_id;

  SELECT AVG(confidence_delta), AVG(escalation_rate_delta),
         AVG(COALESCE(replay_score_after - replay_score_before, 0))
  INTO v_conf, v_esc, v_replay
  FROM amendment_metrics
  WHERE entity_kind = p_entity_kind AND entity_id = p_entity_id
    AND tenant_id = v_tenant_id AND adopted_at IS NOT NULL;

  RETURN json_build_object(
    'entity_kind', p_entity_kind,
    'entity_id', p_entity_id,
    'total_amendments', v_total,
    'adopted_count', v_adopted,
    'adoption_rate_pct', CASE WHEN v_total > 0 THEN ROUND((v_adopted::NUMERIC / v_total) * 100, 1) ELSE 0 END,
    'avg_confidence_delta', ROUND(COALESCE(v_conf, 0)::NUMERIC, 2),
    'avg_escalation_rate_delta', ROUND(COALESCE(v_esc, 0)::NUMERIC, 2),
    'avg_replay_score_gain', ROUND(COALESCE(v_replay, 0)::NUMERIC, 2)
  );
END$function$;

CREATE OR REPLACE FUNCTION public.get_amendment_impact_history(p_entity_kind text, p_entity_id uuid, p_limit integer DEFAULT 10)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tenant_id UUID := public.auth_tenant_id();
BEGIN
  IF v_tenant_id IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  RETURN (
    SELECT json_agg(row_to_json(t))
    FROM (
      SELECT metric_id, amendment_id, confidence_delta, escalation_rate_delta,
             COALESCE(replay_score_after - replay_score_before, 0) AS replay_score_delta,
             adopted_at::text AS adopted_at,
             CASE WHEN adopted_at IS NOT NULL THEN 'adopted' ELSE 'pending' END AS status
      FROM amendment_metrics
      WHERE entity_kind = p_entity_kind AND entity_id = p_entity_id AND tenant_id = v_tenant_id
      ORDER BY created_at DESC
      LIMIT p_limit
    ) t
  );
END$function$;

CREATE OR REPLACE FUNCTION public.get_benchmark_report(p_tenant_id uuid, p_de_id uuid DEFAULT NULL::uuid, p_days integer DEFAULT 30)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_from timestamptz := now() - make_interval(days => greatest(1, least(365, p_days)));
  v_outcomes jsonb; v_quality jsonb; v_csat jsonb; v_cost jsonb; v_sim jsonb; v_review jsonb;
  v_res bigint; v_esc bigint; v_cost_cents numeric;
begin
  -- ⚠ p_tenant_id IS A PARAMETER, SO IT IS NOT AUTHORISATION. The
  -- `auth.uid() is not null and` prefix is deleted: with it, a caller with no
  -- identity read ANY workspace's outcome, quality, CSAT and cost numbers.
  if not exists (
      select 1 from profiles p where p.user_id = auth.uid()
      and (p.layer = 'platform' or p.tenant_id = p_tenant_id)) then
    raise exception 'not authorized';
  end if;

  -- Billable resolutions only (a human-handled conversation is not an AI
  -- resolution); escalations and blocks all stay in the denominator.
  select count(*) filter (where kind = 'resolution' and billable),
         count(*) filter (where kind = 'escalation')
    into v_res, v_esc
    from billable_outcomes
   where tenant_id = p_tenant_id and occurred_at >= v_from
     and evidence_is_production(origin)   -- 682
     and (p_de_id is null or de_id = p_de_id);
  v_outcomes := jsonb_build_object(
    'resolutions', v_res, 'escalations', v_esc,
    'resolution_rate_pct', case when v_res + v_esc > 0 then round(100.0 * v_res / (v_res + v_esc), 1) end);

  -- mig 706: judged_quality counts PROVABLY-production online judgments only.
  -- 682 excluded golden/simulation at this reader; the remaining leak was
  -- upstream — the online sampler graded exam answers and they arrived here
  -- labeled 'online'. The proof standard is now positive: the judgment's
  -- message still exists and its conversation is not on the exam channel.
  select jsonb_build_object(
      'graded', count(*),
      'pass_rate_pct', case when count(*) > 0 then round(100.0 * count(*) filter (where j.verdict = 'pass') / count(*), 1) end,
      'avg_score', case when count(*) > 0 then round(avg(j.score), 1) end)
    into v_quality
    from eval_judgments j
    join de_messages m on m.id = j.message_id
    join de_conversations c on c.id = m.conversation_id
   where j.tenant_id = p_tenant_id and j.created_at >= v_from
     and j.source = 'online'
     and c.channel is distinct from 'exam'
     and (p_de_id is null or j.de_id = p_de_id);

  -- CSAT is a ±1 thumbs field: % positive is the honest statistic (an
  -- "average of 0.33" is meaningless to a reader).
  select jsonb_build_object(
      'ratings', count(*),
      'positive_pct', case when count(*) > 0 then round(100.0 * count(*) filter (where csat_score = 1) / count(*), 1) end)
    into v_csat
    from de_conversations
   where tenant_id = p_tenant_id and csat_submitted_at is not null and csat_submitted_at >= v_from
     and channel is distinct from 'exam'   -- 682
     and (p_de_id is null or de_id = p_de_id);

  select coalesce(sum(
      u.input_tokens  / 1000000.0 * coalesce(pr.input_price_per_million, 0) * 100
    + u.output_tokens / 1000000.0 * coalesce(pr.output_price_per_million, 0) * 100), 0)
    into v_cost_cents
    from de_token_usage u
    left join ai_model_pricing pr on pr.model_id = u.model_id
   where u.tenant_id = p_tenant_id and u.created_at >= v_from
     and evidence_is_production(u.origin)   -- 682
     and (p_de_id is null or u.de_id = p_de_id);
  v_cost := jsonb_build_object(
    'ai_spend_cents', round(v_cost_cents),
    'cost_per_resolution_cents', case when v_res > 0 then round(v_cost_cents / v_res) end);

  select jsonb_build_object('mode', mode, 'passed', passed, 'total', total,
                            'avg_score', avg_score, 'status', status, 'ran_at', started_at)
    into v_sim
    from sim_runs
   where tenant_id = p_tenant_id and candidate = false and status in ('passed', 'failed')
     and (p_de_id is null or de_id = p_de_id)
   order by started_at desc limit 1;

  -- 691 (G-D): the human side of the COGS, beside the AI side. Tenant-wide
  -- (the modeled minutes attribute per-DE inside the block itself).
  v_review := public.get_review_cost_internal(p_tenant_id, greatest(1, least(365, p_days)));

  return jsonb_build_object(
    'window_days', greatest(1, least(365, p_days)),
    'de_id', p_de_id,
    'generated_at', now(),
    'outcomes', v_outcomes,
    'judged_quality', v_quality,
    'csat', v_csat,
    'cost', v_cost,
    'human_review', v_review,
    'capability', coalesce(v_sim, jsonb_build_object('status', 'no_simulation_yet')),
    'definitions', jsonb_build_object(
      'resolution_rate_pct', 'Auto-sent, guardrail-clean answers that were NOT later handed to a human, as a share of ALL metered outcomes in the window — every escalation, hand-off, and guardrail block counts in the denominator. Certification-exam traffic is excluded from numerator and denominator alike (mig 682).',
      'judged_quality', 'Share of graded LIVE answers an independent LLM judge scored as passing on grounding, correctness, guardrail adherence, and tone. Counts only judgments provably tied to a delivered production message; certification, simulation, and exam-channel grades are excluded — they measure the exam, not the work (migs 682/706).',
      'csat', 'Percent of customer-submitted thumbs ratings that were positive. Never inferred or imputed.',
      'cost_per_resolution_cents', 'Real model spend on production traffic in the window divided by billable resolutions delivered.',
      'human_review', 'MODELED, not measured: decided review tasks × founder-editable standard minutes per decision type (exam-origin decisions excluded), divided by landed outputs. Dollars appear only when the workspace baseline (G-A) is on file.',
      'capability', 'Latest certification-grade simulation result. Dry-run (candidate) simulations are excluded, exactly as they are excluded from certification.'));
end;
$function$;

CREATE OR REPLACE FUNCTION public.get_browser_login(p_tenant_id uuid, p_domain text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE s de_connected_systems; v_secret text; v_dom text;
BEGIN
  IF coalesce(auth.role(),'') <> 'service_role' THEN RAISE EXCEPTION 'service-role only'; END IF;
  v_dom := lower(regexp_replace(regexp_replace(coalesce(p_domain,''), '^https?://', ''), '/.*$', ''));
  FOR s IN SELECT * FROM de_connected_systems WHERE tenant_id = p_tenant_id AND can_operate AND login_secret_id IS NOT NULL LOOP
    IF public.operate_domain_of(s) = v_dom THEN
      SELECT decrypted_secret INTO v_secret FROM vault.decrypted_secrets WHERE id = s.login_secret_id LIMIT 1;
      IF v_secret IS NOT NULL THEN
        -- Secret convention: JSON {"username":"…","password":"…"} or a bare password.
        RETURN jsonb_build_object('ok', true, 'secret', v_secret);
      END IF;
    END IF;
  END LOOP;
  RETURN jsonb_build_object('ok', false, 'error', 'no_login_secret');
END; $function$;

CREATE OR REPLACE FUNCTION public.get_browser_task(p_task_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v jsonb;
BEGIN
  SELECT to_jsonb(c) - 'constraints' INTO v FROM computer_use_tasks c WHERE c.id = p_task_id
    AND (c.tenant_id = public.auth_tenant_id() OR EXISTS (SELECT 1 FROM profiles WHERE user_id = auth.uid() AND layer = 'platform'));
  IF v IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'not_found'); END IF;
  RETURN jsonb_build_object('ok', true, 'task', v);
END; $function$;

CREATE OR REPLACE FUNCTION public.get_config_audit_log(p_tenant_id uuid, p_entity_kind text, p_entity_id uuid, p_limit integer DEFAULT 50)
 RETURNS TABLE(audit_id uuid, "timestamp" timestamp with time zone, changed_by uuid, action text, field_name text, old_value jsonb, new_value jsonb, details text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  PERFORM public._assert_caller_tenant(p_tenant_id);
  RETURN QUERY
  SELECT dal.audit_id, dal.changed_at, dal.changed_by, dal.action,
         dal.field_name, dal.old_value, dal.new_value, dal.details
  FROM de_config_audit_log dal
  WHERE dal.tenant_id = p_tenant_id AND dal.entity_kind = p_entity_kind AND dal.entity_id = p_entity_id
  ORDER BY dal.changed_at DESC
  LIMIT p_limit;
END$function$;

CREATE OR REPLACE FUNCTION public.get_config_schema(p_tenant_id uuid, p_entity_kind text, p_entity_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(schema_id uuid, tenant_id uuid, entity_kind text, entity_id uuid, name text, fields jsonb, tags text[], created_at timestamp with time zone, updated_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  PERFORM public._assert_caller_tenant(p_tenant_id);
  RETURN QUERY
  SELECT * FROM de_config_schemas s
  WHERE s.tenant_id = p_tenant_id AND s.entity_kind = p_entity_kind
    AND (s.entity_id = p_entity_id OR s.entity_id IS NULL)
  ORDER BY s.entity_id DESC NULLS LAST
  LIMIT 1;
END$function$;

CREATE OR REPLACE FUNCTION public.get_config_template_with_overrides(p_de_id uuid, p_template_key text DEFAULT 'support-de-template'::text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tenant_id UUID := public.auth_tenant_id();
  v_template JSONB;
  v_field JSONB;
  v_overrides JSONB;
  v_merged JSONB := '{}'::jsonb;
BEGIN
  IF v_tenant_id IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;

  SELECT fields INTO v_template FROM config_schema_templates WHERE template_key = p_template_key;
  IF v_template IS NULL THEN RAISE EXCEPTION 'Template not found: %', p_template_key; END IF;

  SELECT values INTO v_overrides
  FROM config_schema_instances
  WHERE de_id = p_de_id AND tenant_id = v_tenant_id AND template_key = p_template_key;
  v_overrides := COALESCE(v_overrides, '{}'::jsonb);

  FOR v_field IN SELECT * FROM jsonb_array_elements(v_template)
  LOOP
    v_merged := v_merged || jsonb_build_object(
      v_field->>'key',
      COALESCE(v_overrides->(v_field->>'key'), v_field->'defaultValue')
    );
  END LOOP;

  RETURN v_merged;
END$function$;

CREATE OR REPLACE FUNCTION public.get_conversation_facts(p_tenant_id uuid, p_conversation_id uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
  select coalesce(jsonb_object_agg(fact_key, fact_value), '{}'::jsonb)
  from conversation_facts
  where tenant_id = p_tenant_id and conversation_id = p_conversation_id;
$function$;

CREATE OR REPLACE FUNCTION public.get_de_action_metrics(p_tenant_id uuid, p_days integer DEFAULT NULL::integer)
 RETURNS TABLE(de_id uuid, total_events bigint, executed bigint, auto_executed bigint, approved_after_gate bigint, sent_to_human bigint, blocked bigint, rejected bigint, failed bigint, autonomy_rate numeric)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is null then raise exception 'not authenticated'; end if;
  if not (is_platform_admin() or exists (select 1 from profiles p where p.user_id = auth.uid() and p.tenant_id = p_tenant_id)) then
    raise exception 'not authorized to view this workspace''s performance data';
  end if;
  return query
    with ax as (
      select ae.subject_id as d_de_id, ae.decision as dec
      from action_executions ae
      where ae.tenant_id = p_tenant_id
        and ae.subject_kind = 'de'
        and ae.subject_id is not null
        -- DE scoping (wave2 grpB): rows narrow to the employees this caller
        -- is responsible for; owner/admin/manager see the whole workspace.
        and public.can_access_de(ae.subject_id)
        and ae.decision <> 'previewed'
        and (p_days is null or ae.created_at >= now() - make_interval(days => p_days))
    )
    select
      ax.d_de_id as de_id,
      count(*)::bigint,
      count(*) filter (where dec in ('auto_executed', 'executed_after_approval'))::bigint,
      count(*) filter (where dec = 'auto_executed')::bigint,
      count(*) filter (where dec = 'executed_after_approval')::bigint,
      count(*) filter (where dec in ('human_gated_destructive', 'human_gated_trust'))::bigint,
      count(*) filter (where dec in ('guardrail_blocked', 'access_denied'))::bigint,
      count(*) filter (where dec = 'rejected')::bigint,
      count(*) filter (where dec = 'failed')::bigint,
      round(100.0 * count(*) filter (where dec = 'auto_executed')
        / nullif(count(*) filter (where dec in ('auto_executed', 'executed_after_approval')), 0), 1)
    from ax
    group by ax.d_de_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.get_de_agentic_runs(p_de_id uuid, p_limit integer DEFAULT 15)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_tenant uuid; v_out jsonb;
begin
  v_tenant := public.auth_tenant_id();
  if v_tenant is null then return jsonb_build_object('ok', false, 'error', 'not_permitted'); end if;
  -- The employee must exist in the caller's tenant AND the caller must be
  -- responsible for it (owner/admin/manager pass; else needs an assignment).
  if not exists (select 1 from digital_employees where id = p_de_id and tenant_id = v_tenant and public.can_access_de(p_de_id)) then
    return jsonb_build_object('ok', false, 'error', 'de_not_found');
  end if;
  p_limit := greatest(1, least(50, coalesce(p_limit, 15)));
  select coalesce(jsonb_agg(row_to_json(x)), '[]'::jsonb) into v_out from (
    select r.id, r.goal, r.status, r.iteration_count,
           coalesce(r.cost_used_cents, 0) as cost_used_cents,
           r.tokens_used, r.created_at, r.completed_at
      from agentic_step_runs r
     where r.tenant_id = v_tenant and r.de_id = p_de_id
     order by r.created_at desc
     limit p_limit
  ) x;
  return jsonb_build_object('ok', true, 'runs', v_out);
end $function$;

CREATE OR REPLACE FUNCTION public.get_de_briefing(p_de_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tenant uuid;
  v_sop text;
  v_guard text;
begin
  select tenant_id into v_tenant from digital_employees where id = p_de_id;
  if v_tenant is null then return jsonb_build_object('sop','','guardrails',''); end if;

  -- ALL attached, published SOPs (titled; newest first; capped at 4).
  select string_agg(sop_text, E'\n\n' order by upd desc)
  into v_sop
  from (
    select pd.updated_at as upd,
           '## ' || pd.name || E'\n' || render_playbook_structure(pd.steps) as sop_text
    from playbook_definitions pd
    where pd.de_id = p_de_id and pd.status = 'published'
    order by pd.updated_at desc
    limit 4
  ) sops;

  -- The DE's active guardrails, rendered as rules it must honour.
  select string_agg('- ' ||
    case r.rule_type
      when 'blocked_phrase' then 'Never commit to / say: ' || coalesce(r.pattern,'')
      when 'blocked_topic'  then 'Do not act on topic: ' || coalesce(r.pattern,'')
      when 'max_discount_pct' then 'Any discount above ' || coalesce(r.threshold::text,'0') || '% must be proposed for human approval'
      when 'require_approval_over_cents' then 'Any amount over $' || to_char(coalesce(r.threshold,0)/100.0,'FM999,999,990.00') || ' must be proposed for human approval'
      when 'frustration_signal' then 'Escalate to a human on: ' || coalesce(r.pattern,'')
      else coalesce(r.rule,'')
    end, E'\n')
  into v_guard
  from guardrail_rules_for_de(v_tenant, p_de_id,
       ARRAY['blocked_phrase','blocked_topic','max_discount_pct','require_approval_over_cents','frustration_signal'],
       null) r
  where r.active;

  return jsonb_build_object('sop', coalesce(v_sop,''), 'guardrails', coalesce(v_guard,''));
end;
$function$;

CREATE OR REPLACE FUNCTION public.get_de_briefing_for_objective(p_de_id uuid, p_objective text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tenant uuid; v_sop text; v_guard text; v_pid uuid; v_name text; v_by_rel boolean := false;
begin
  select tenant_id into v_tenant from digital_employees where id = p_de_id;
  if v_tenant is null then
    return jsonb_build_object('sop','','guardrails','','matched_playbook_id',null,'matched_by_relevance',false);
  end if;

  -- Best-matching published SOP by full-text rank vs the objective; fallback to
  -- most-recent (empty/nonsense objective → all ranks 0 → most-recent wins).
  select pd.id, pd.name, render_playbook_structure(pd.steps),
         (ts_rank(to_tsvector('english', coalesce(pd.name,'') || ' ' || coalesce(pd.description,'')),
                  plainto_tsquery('english', coalesce(p_objective,''))) > 0)
    into v_pid, v_name, v_sop, v_by_rel
  from playbook_definitions pd
  where pd.de_id = p_de_id and pd.status = 'published'
  order by ts_rank(to_tsvector('english', coalesce(pd.name,'') || ' ' || coalesce(pd.description,'')),
                   plainto_tsquery('english', coalesce(p_objective,''))) desc nulls last,
           pd.updated_at desc
  limit 1;

  -- Guardrail block — byte-identical to get_de_briefing (mig 250:48-62).
  select string_agg('- ' ||
    case r.rule_type
      when 'blocked_phrase' then 'Never commit to / say: ' || coalesce(r.pattern,'')
      when 'blocked_topic'  then 'Do not act on topic: ' || coalesce(r.pattern,'')
      when 'max_discount_pct' then 'Any discount above ' || coalesce(r.threshold::text,'0') || '% must be proposed for human approval'
      when 'require_approval_over_cents' then 'Any amount over $' || to_char(coalesce(r.threshold,0)/100.0,'FM999,999,990.00') || ' must be proposed for human approval'
      when 'frustration_signal' then 'Escalate to a human on: ' || coalesce(r.pattern,'')
      else coalesce(r.rule,'')
    end, E'\n')
  into v_guard
  from guardrail_rules_for_de(v_tenant, p_de_id,
       ARRAY['blocked_phrase','blocked_topic','max_discount_pct','require_approval_over_cents','frustration_signal'],
       null) r
  where r.active;

  return jsonb_build_object(
    'sop', case when v_sop is not null and v_name is not null then '## ' || v_name || E'\n' || v_sop else '' end,
    'guardrails', coalesce(v_guard,''),
    'matched_playbook_id', v_pid,
    'matched_by_relevance', coalesce(v_by_rel,false)
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.get_de_config(p_tenant_id uuid, p_entity_kind text, p_entity_id uuid)
 RETURNS TABLE(config_id uuid, tenant_id uuid, entity_kind text, entity_id uuid, schema_id uuid, data jsonb, created_at timestamp with time zone, updated_at timestamp with time zone, updated_by uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  PERFORM public._assert_caller_tenant(p_tenant_id);
  RETURN QUERY
  SELECT * FROM de_config dc
  WHERE dc.tenant_id = p_tenant_id AND dc.entity_kind = p_entity_kind AND dc.entity_id = p_entity_id;
END$function$;

CREATE OR REPLACE FUNCTION public.get_de_config(p_de_id uuid)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tenant_id UUID := public.auth_tenant_id();
BEGIN
  IF v_tenant_id IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  RETURN (
    SELECT json_build_object(
      'instance_id', instance_id,
      'de_id', de_id,
      'template_key', template_key,
      'values', values,
      'updated_at', updated_at::text
    )
    FROM config_schema_instances
    WHERE de_id = p_de_id AND tenant_id = v_tenant_id
    LIMIT 1
  );
END$function$;

CREATE OR REPLACE FUNCTION public.get_de_contract_metrics(p_tenant_id uuid, p_de_id uuid)
 RETURNS TABLE(metric_key text, tier text, label text, unit text, value numeric, target numeric, measurable boolean, unmeasurable_because text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_arch text;
  v_contract jsonb;
  c jsonb;
  -- denominators, resolved once
  v_cases int;            -- continuity cases owned by this employee
  v_closed int;           -- ...that reached a terminal stage
  v_deadlines_passed int; -- agreements whose notice deadline has elapsed
begin
  if auth.role() is not null and auth.role() <> 'service_role' then
    if auth.uid() is null then raise exception 'not authenticated'; end if;
    if not (is_platform_admin()
            or exists (select 1 from profiles p where p.user_id = auth.uid() and p.tenant_id = p_tenant_id)) then
      raise exception 'not authorized to view this workspace''s performance data';
    end if;
  end if;
  if not (auth.role() is null or auth.role() = 'service_role' or public.can_access_de(p_de_id)) then
    raise exception 'not authorized to view this employee';
  end if;

  select d.archetype_key into v_arch from digital_employees d
   where d.id = p_de_id and d.tenant_id = p_tenant_id;
  if v_arch is null then
    -- No archetype, no contract. Honest silence beats a generic scorecard:
    -- 94 of 116 employees platform-wide have no archetype at all.
    return;
  end if;

  select a.performance_contract into v_contract from role_archetypes a where a.key = v_arch;
  if v_contract is null or v_contract = '[]'::jsonb then
    return;
  end if;

  select count(*),
         count(*) filter (where cc.outcome is not null)
    into v_cases, v_closed
    from continuity_cases cc
   where cc.tenant_id = p_tenant_id and cc.de_id = p_de_id;

  select count(*) into v_deadlines_passed
    from commercial_agreements ag
    join continuity_cases cc on cc.agreement_id = ag.id and cc.de_id = p_de_id
   where ag.tenant_id = p_tenant_id and ag.notice_deadline is not null and ag.notice_deadline < current_date;

  for c in select * from jsonb_array_elements(v_contract) loop
    metric_key := c->>'metric_key';
    tier       := c->>'tier';
    target     := nullif(c->>'target', '')::numeric;
    value      := null;
    measurable := true;
    unmeasurable_because := null;

    case metric_key

      when 'revenue_retained_cents' then
        label := 'Revenue retained'; unit := 'cents';
        if v_closed = 0 then
          measurable := false;
          unmeasurable_because := 'No renewal has been closed yet, so there is nothing retained to count. The closing path exists and has never been used.';
        else
          select coalesce(sum(cc.baseline_cents), 0) into value
            from continuity_cases cc
            left join continuity_stage_config sc
              on sc.tenant_id = cc.tenant_id and sc.stage_key = cc.stage_key
           where cc.tenant_id = p_tenant_id and cc.de_id = p_de_id
             and cc.outcome is not null and coalesce(sc.category, '') = 'won';
        end if;

      when 'renewals_closed_on_time' then
        label := 'Renewals closed on time'; unit := 'percent';
        if v_closed = 0 then
          measurable := false;
          unmeasurable_because := 'No renewal has been closed yet — the percentage has no denominator. Reporting 0% would say the employee missed every renewal, which is not what happened.';
        else
          -- A close TIME can only come from the event ledger: continuity_cases
          -- has no closed_at, and updated_at is bumped by set_next_step too.
          select round(100.0 * count(*) filter (
                   where ev.created_at::date <= ag.notice_deadline) / nullif(count(*), 0), 1)
            into value
            from continuity_cases cc
            join commercial_agreements ag on ag.id = cc.agreement_id
            join lateral (
              select min(e.created_at) as created_at from continuity_case_events e
               where e.objective_id = cc.objective_id and e.to_stage is distinct from 'discovered'
            ) ev on true
           where cc.tenant_id = p_tenant_id and cc.de_id = p_de_id
             and cc.outcome is not null and ag.notice_deadline is not null;
        end if;

      when 'notice_deadlines_missed' then
        label := 'Notice deadlines missed'; unit := 'count';
        -- A true measurement even at zero: the deadlines simply have not
        -- arrived yet. Distinct from "not measured".
        select count(*) into value
          from commercial_agreements ag
          join continuity_cases cc on cc.agreement_id = ag.id and cc.de_id = p_de_id
         where ag.tenant_id = p_tenant_id
           and ag.notice_deadline is not null and ag.notice_deadline < current_date
           and cc.outcome is null;

      when 'deadlines_approaching_30d' then
        label := 'Deadlines inside 30 days'; unit := 'count';
        select count(*) into value
          from commercial_agreements ag
          join continuity_cases cc on cc.agreement_id = ag.id and cc.de_id = p_de_id
         where ag.tenant_id = p_tenant_id
           and ag.notice_deadline is not null
           and ag.notice_deadline >= current_date
           and ag.notice_deadline < current_date + 30
           and cc.outcome is null;

      when 'uplift_entitled_cents' then
        label := 'Contractual uplift entitled'; unit := 'cents';
        -- ENTITLED, not captured. expected_uplift_cents has no writer anywhere
        -- in the schema, so captured is unmeasurable and calling this "captured"
        -- would be a fabrication.
        select coalesce(sum(round(ag.baseline_value_cents
                 * (ag.attributes->>'contractual_increase_pct')::numeric / 100.0)), 0)
          into value
          from commercial_agreements ag
          join continuity_cases cc on cc.agreement_id = ag.id and cc.de_id = p_de_id
         where ag.tenant_id = p_tenant_id
           and ag.baseline_value_cents is not null
           and (ag.attributes->>'contractual_increase_pct') is not null;

      when 'cases_recorded_at_close' then
        label := 'Cases recorded at close'; unit := 'percent';
        if v_closed = 0 then
          measurable := false;
          unmeasurable_because := 'No case has closed yet, so there is nothing to have recorded.';
        else
          value := round(100.0 * v_closed / nullif(v_cases, 0), 1);
        end if;

      else
        label := metric_key; unit := 'unknown';
        measurable := false;
        unmeasurable_because := 'This role''s contract names a metric the library does not implement.';
    end case;

    return next;
  end loop;
end;
$function$;

CREATE OR REPLACE FUNCTION public.get_de_cost_metrics(p_tenant_id uuid)
 RETURNS TABLE(de_id uuid, total_calls bigint, total_input_tokens bigint, total_output_tokens bigint, total_cost_usd numeric)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;
  if not (
    is_platform_admin()
    or exists (select 1 from profiles p where p.user_id = auth.uid() and p.tenant_id = p_tenant_id)
  ) then
    raise exception 'not authorized to view this workspace''s cost data';
  end if;

  return query
    select
      u.de_id,
      count(*) as total_calls,
      sum(u.input_tokens) as total_input_tokens,
      sum(u.output_tokens) as total_output_tokens,
      round(sum(
        (u.input_tokens::numeric / 1000000) * coalesce(pr.input_price_per_million, 3.00)
        + (u.output_tokens::numeric / 1000000) * coalesce(pr.output_price_per_million, 15.00)
      ), 4) as total_cost_usd
    from de_token_usage u
    left join ai_model_pricing pr on pr.model_id = u.model_id
    where u.tenant_id = p_tenant_id and u.de_id is not null
      and evidence_is_production(u.origin)
      -- A-4: and only the employees this caller actually holds. can_access_de
      -- keeps owner/admin/manager on the WHOLE workforce of their own
      -- workspace and platform staff on everything, so no role that could see
      -- this before loses it; it is the narrower roles that stop seeing spend
      -- for employees they are not responsible for.
      and public.can_access_de(u.de_id)   -- 682: exam spend is not a business cost metric
    group by u.de_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.get_de_cost_metrics_ranged(p_tenant_id uuid, p_days integer DEFAULT NULL::integer)
 RETURNS TABLE(de_id uuid, total_calls bigint, total_input_tokens bigint, total_output_tokens bigint, total_cost_usd numeric)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is null then raise exception 'not authenticated'; end if;
  if not (is_platform_admin() or exists (select 1 from profiles p where p.user_id = auth.uid() and p.tenant_id = p_tenant_id)) then
    raise exception 'not authorized to view this workspace''s cost data';
  end if;
  return query
    select
      u.de_id,
      count(*)::bigint as total_calls,
      sum(u.input_tokens)::bigint as total_input_tokens,
      sum(u.output_tokens)::bigint as total_output_tokens,
      round(sum(
        (u.input_tokens::numeric / 1000000) * coalesce(pr.input_price_per_million, 3.00)
        + (u.output_tokens::numeric / 1000000) * coalesce(pr.output_price_per_million, 15.00)
      ), 4) as total_cost_usd
    from de_token_usage u
    left join ai_model_pricing pr on pr.model_id = u.model_id
    where u.tenant_id = p_tenant_id and u.de_id is not null
      and evidence_is_production(u.origin)   -- 682
      and (p_days is null or u.created_at >= now() - make_interval(days => p_days))
    group by u.de_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.get_de_csat_metrics(p_tenant_id uuid)
 RETURNS TABLE(de_id uuid, total_ratings bigint, positive_ratings bigint, csat_pct numeric)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;
  if not (
    is_platform_admin()
    or exists (select 1 from profiles p where p.user_id = auth.uid() and p.tenant_id = p_tenant_id)
  ) then
    raise exception 'not authorized to view this workspace''s CSAT data';
  end if;

  return query
    select
      c.de_id,
      count(*) as total_ratings,
      count(*) filter (where c.csat_score = 1) as positive_ratings,
      round(100.0 * count(*) filter (where c.csat_score = 1) / nullif(count(*), 0), 1) as csat_pct
    from de_conversations c
    where c.tenant_id = p_tenant_id and c.csat_submitted_at is not null and c.de_id is not null
      and c.channel is distinct from 'exam'   -- 682: an exam thread is not a customer rating
    group by c.de_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.get_de_economics(p_tenant_id uuid, p_de_id uuid DEFAULT NULL::uuid, p_days integer DEFAULT 30)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  b workforce_baselines;
  v_inquiries bigint;
  v_actions bigint;
  v_conversations bigint;
  v_de_cost numeric;
  v_human_minutes numeric := 0;
  v_counted boolean := false;
  v_missing text[] := '{}';
  v_fte numeric;
  v_human_cost numeric;
  v_roi numeric;
  v_savings numeric;
  v_std_minutes numeric;
begin
  if p_days < 1 or p_days > 365 then raise exception 'window must be 1-365 days'; end if;
  -- Same trusted-server/human gate as get_de_performance_metrics.
  if auth.role() is not null and auth.role() <> 'service_role' then
    if auth.uid() is null then raise exception 'not authenticated'; end if;
    if not (is_platform_admin()
            or exists (select 1 from profiles p where p.user_id = auth.uid() and p.tenant_id = p_tenant_id)) then
      raise exception 'not authorized to view this workspace''s economics';
    end if;
  end if;

  select * into b from workforce_baselines where tenant_id = p_tenant_id;

  -- Real work counts, windowed. mig 709: BENEFIT counts are production-only —
  -- these numbers get multiplied by tenant-typed minutes into the founder's
  -- "Hours saved" headline, and before this filter hq's window was 158-of-160
  -- conversations and 75-of-91 decisions certification-exam traffic. An exam
  -- is the control being tested, never work a human was saved from doing.
  select count(*) into v_inquiries
  from evidence_run_decisions d join evidence_runs er on er.id = d.evidence_run_id
  where er.tenant_id = p_tenant_id and er.de_id is not null
    and public.evidence_is_production(er.origin)
    and (p_de_id is null or er.de_id = p_de_id) and (er.de_id is null or public.can_access_de(er.de_id))
    and d.created_at > now() - make_interval(days => p_days);

  select count(*) into v_actions
  from action_executions
  where tenant_id = p_tenant_id and subject_kind = 'de' and mode = 'execute'
    and decision in ('auto_executed', 'executed_after_approval')
    and (p_de_id is null or subject_id = p_de_id) and (subject_id is null or public.can_access_de(subject_id))
    and created_at > now() - make_interval(days => p_days);

  select count(*) into v_conversations
  from de_conversations
  where tenant_id = p_tenant_id and de_id is not null
    and channel is distinct from 'exam'   -- mig 709, the 671 axis
    and (p_de_id is null or de_id = p_de_id) and (de_id is null or public.can_access_de(de_id))
    and created_at > now() - make_interval(days => p_days);

  -- Real AI cost, windowed (same pricing join as get_de_cost_metrics).
  -- mig 709: DELIBERATELY not exam-filtered. Exam tokens are real spend under
  -- the same budget cap; excluding them would flatter the economics. Filtering
  -- benefits and not costs is the conservative direction, on purpose.
  select coalesce(round(sum(
      (u.input_tokens::numeric / 1000000) * coalesce(pr.input_price_per_million, 3.00)
      + (u.output_tokens::numeric / 1000000) * coalesce(pr.output_price_per_million, 15.00)
    ), 4), 0) into v_de_cost
  from de_token_usage u
  left join ai_model_pricing pr on pr.model_id = u.model_id
  where u.tenant_id = p_tenant_id
    and (p_de_id is null or u.de_id = p_de_id) and (u.de_id is null or public.can_access_de(u.de_id))
    and u.created_at > now() - make_interval(days => p_days);

  -- Human-minutes over CONFIGURED task types only.
  if b.inquiry_minutes is not null then
    v_human_minutes := v_human_minutes + v_inquiries * b.inquiry_minutes; v_counted := true;
  elsif v_inquiries > 0 then v_missing := array_append(v_missing, 'inquiry_minutes'); end if;

  if b.action_minutes is not null then
    v_human_minutes := v_human_minutes + v_actions * b.action_minutes; v_counted := true;
  elsif v_actions > 0 then v_missing := array_append(v_missing, 'action_minutes'); end if;

  if b.conversation_minutes is not null then
    v_human_minutes := v_human_minutes + v_conversations * b.conversation_minutes; v_counted := true;
  elsif v_conversations > 0 then v_missing := array_append(v_missing, 'conversation_minutes'); end if;

  -- §12.3: 9,600 standard working minutes per month, prorated.
  v_std_minutes := 9600.0 * p_days / 30.0;
  if v_counted then
    v_fte := round(v_human_minutes / v_std_minutes, 3);
    if b.avg_fte_cost_monthly_usd is not null then
      v_human_cost := round(v_fte * b.avg_fte_cost_monthly_usd * p_days / 30.0, 2);
      v_savings := round(v_human_cost - v_de_cost, 2);
      if v_de_cost > 0 then
        v_roi := round((v_human_cost - v_de_cost) / v_de_cost, 1);
      end if;
    else
      v_missing := array_append(v_missing, 'avg_fte_cost_monthly_usd');
    end if;
  end if;

  return jsonb_build_object(
    'window_days', p_days,
    'counts', jsonb_build_object(
      'inquiries_handled', v_inquiries, 'actions_executed', v_actions, 'conversations_answered', v_conversations),
    'baselines', jsonb_build_object(
      'inquiry_minutes', b.inquiry_minutes, 'action_minutes', b.action_minutes,
      'conversation_minutes', b.conversation_minutes, 'avg_fte_cost_monthly_usd', b.avg_fte_cost_monthly_usd),
    'hours_saved', case when v_counted then round(v_human_minutes / 60.0, 1) end,
    'fte_equivalent', v_fte,
    'de_cost_usd', v_de_cost,
    'human_cost_equivalent_usd', v_human_cost,
    'monthly_saving_usd', case when v_savings is not null then round(v_savings * 30.0 / p_days, 2) end,
    'roi_ratio', v_roi,
    'unconfigured', to_jsonb(v_missing),
    'configured', v_counted and b.avg_fte_cost_monthly_usd is not null and array_length(v_missing, 1) is null
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.get_de_escalation_rules(p_de_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_tenant uuid; v_de_rules jsonb; v_tenant_rules jsonb; v_frust int; v_topics text[];
begin
  v_tenant := public.auth_tenant_id();
  if v_tenant is null then return jsonb_build_object('ok', false, 'error', 'not_permitted'); end if;
  if not exists (select 1 from digital_employees where id = p_de_id and tenant_id = v_tenant) then
    return jsonb_build_object('ok', false, 'error', 'de_not_found');
  end if;

  select coalesce(custom_rules, '[]'::jsonb) into v_de_rules
    from de_escalation_rules where tenant_id = v_tenant and de_id = p_de_id;
  select coalesce(custom_rules, '[]'::jsonb) into v_tenant_rules
    from de_escalation_rules where tenant_id = v_tenant and de_id is null;

  select frustration_threshold, always_escalate_topics into v_frust, v_topics
    from resolve_de_escalation(v_tenant, p_de_id);

  return jsonb_build_object(
    'ok', true,
    'frustration_threshold', v_frust,
    'always_escalate_topics', to_jsonb(coalesce(v_topics, '{}')),
    'de_rules', coalesce(v_de_rules, '[]'::jsonb),
    'tenant_rules', coalesce(v_tenant_rules, '[]'::jsonb)
  );
end $function$;

CREATE OR REPLACE FUNCTION public.get_de_execution_log(p_de_id uuid, p_limit integer DEFAULT 25)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_tenant uuid; v_out jsonb;
begin
  v_tenant := public.auth_tenant_id();
  if v_tenant is null then return jsonb_build_object('ok', false, 'error', 'not_permitted'); end if;
  -- The employee must exist in the caller's tenant AND the caller must be
  -- responsible for it (owner/admin/manager pass; else needs an assignment).
  if not exists (select 1 from digital_employees where id = p_de_id and tenant_id = v_tenant and public.can_access_de(p_de_id)) then
    return jsonb_build_object('ok', false, 'error', 'de_not_found');
  end if;
  p_limit := greatest(1, least(100, coalesce(p_limit, 25)));
  select coalesce(jsonb_agg(row_to_json(x)), '[]'::jsonb) into v_out from (
    select s.name,
           round(extract(epoch from (s.ended_at - s.started_at)) * 1000)::int as duration_ms,
           s.started_at,
           s.attributes->>'gen_ai.request.model' as model,
           s.attributes->>'gen_ai.system' as provider,
           (s.attributes->>'gen_ai.usage.input_tokens')::int as input_tokens,
           (s.attributes->>'gen_ai.usage.output_tokens')::int as output_tokens,
           (s.attributes->>'dreamteam.confidence')::int as confidence,
           (s.attributes->>'dreamteam.escalated')::boolean as escalated,
           s.attributes->>'dreamteam.status' as work_status,
           (s.attributes->>'dreamteam.turns')::int as turns
      from otel_spans s
     where s.tenant_id = v_tenant
       and s.attributes->>'dreamteam.de_id' = p_de_id::text
       and s.parent_span_id is null   -- root span = one row per run
     order by s.started_at desc
     limit p_limit
  ) x;
  return jsonb_build_object('ok', true, 'runs', v_out);
end $function$;

CREATE OR REPLACE FUNCTION public.get_de_experience(p_de_id uuid, p_limit integer DEFAULT 40)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_tenant uuid; v_out jsonb;
begin
  v_tenant := public.auth_tenant_id();
  if v_tenant is null then return jsonb_build_object('ok', false, 'error', 'not_permitted'); end if;
  -- The employee must exist in the caller's tenant AND the caller must be
  -- responsible for it (owner/admin/manager pass; else needs an assignment).
  if not exists (select 1 from digital_employees where id = p_de_id and tenant_id = v_tenant and public.can_access_de(p_de_id)) then
    return jsonb_build_object('ok', false, 'error', 'de_not_found');
  end if;
  p_limit := greatest(1, least(200, coalesce(p_limit, 40)));
  select coalesce(jsonb_agg(row_to_json(x)), '[]'::jsonb) into v_out from (
    select e.id, e.category, e.fact_summary, e.external_ref, e.created_at,
           (e.source_action_execution_id is not null) as from_action,
           (e.source_evidence_run_id is not null) as from_evidence
      from de_experience e
     where e.tenant_id = v_tenant
       and e.subject_kind in ('de', 'specialist')
       and e.subject_id = p_de_id
     order by e.created_at desc
     limit p_limit
  ) x;
  return jsonb_build_object('ok', true, 'experience', v_out);
end $function$;

CREATE OR REPLACE FUNCTION public.get_de_gate_status(p_de_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_tenant uuid;
  v_g record;
begin
  v_tenant := public.auth_tenant_id();
  if v_tenant is null then return jsonb_build_object('ok', false, 'error', 'not_permitted'); end if;
  if not exists (select 1 from digital_employees where id = p_de_id and tenant_id = v_tenant) then
    return jsonb_build_object('ok', false, 'error', 'de_not_found');
  end if;
  if not public.can_access_de(p_de_id) then
    return jsonb_build_object('ok', false, 'error', 'de_not_found');
  end if;
  select * into v_g from public.de_records_gate(v_tenant, p_de_id);
  return jsonb_build_object('ok', true, 'gated', v_g.gated, 'reasons', to_jsonb(v_g.reasons));
end;
$function$;

CREATE OR REPLACE FUNCTION public.get_de_guardrail_activity(p_tenant_id uuid, p_days integer DEFAULT 30)
 RETURNS TABLE(de_id uuid, de_name text, gated_count bigint, blocked_count bigint, tenant_total_events bigint, tenant_attributed_events bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tenant_total bigint;
  v_tenant_attributed bigint;
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;
  if not (
    is_platform_admin()
    or exists (select 1 from profiles p where p.user_id = auth.uid() and p.tenant_id = p_tenant_id)
  ) then
    raise exception 'not authorized to view this workspace''s guardrail activity';
  end if;

  -- Raw tenant-wide total, independent of name-attribution success --
  -- audit_events.actor is a free-text DE name (no de_id FK exists), so a
  -- historical DE rename can leave real events un-attributable to any
  -- CURRENT digital_employees row. Surfacing the raw total alongside the
  -- attributed rows keeps this honest instead of silently reading as
  -- "no guardrail activity" when there genuinely was some.
  select count(*) into v_tenant_total
    from audit_events a
    where a.tenant_id = p_tenant_id
      and (a.category = 'guardrail_block' or (a.category = 'guardrail_check' and a.detail->>'result' = 'gated'))
      and a.created_at > now() - (p_days || ' days')::interval;

  select count(*) into v_tenant_attributed
    from audit_events a
    join digital_employees de on de.tenant_id = p_tenant_id and de.name = a.actor
    where a.tenant_id = p_tenant_id
      and (a.category = 'guardrail_block' or (a.category = 'guardrail_check' and a.detail->>'result' = 'gated'))
      and a.created_at > now() - (p_days || ' days')::interval;

  return query
    select
      de.id, de.name,
      count(*) filter (where a.category = 'guardrail_check' and a.detail->>'result' = 'gated') as gated_count,
      count(*) filter (where a.category = 'guardrail_block') as blocked_count,
      v_tenant_total, v_tenant_attributed
    from digital_employees de
    join audit_events a on a.tenant_id = p_tenant_id and a.actor = de.name
      and a.category in ('guardrail_check', 'guardrail_block')
      and a.created_at > now() - (p_days || ' days')::interval
    where de.tenant_id = p_tenant_id
    group by de.id, de.name
    having count(*) filter (where a.category = 'guardrail_block' or a.detail->>'result' = 'gated') > 0;

  -- If real events exist tenant-wide but none could be attributed to a
  -- current DE name, still surface the totals via one summary-only row
  -- rather than silently returning nothing.
  if v_tenant_total > 0 and v_tenant_attributed = 0 and not found then
    return query select null::uuid, null::text, 0::bigint, 0::bigint, v_tenant_total, v_tenant_attributed;
  end if;
end;
$function$;

CREATE OR REPLACE FUNCTION public.get_de_inquiry_metrics(p_tenant_id uuid, p_days integer DEFAULT NULL::integer)
 RETURNS TABLE(de_id uuid, total_decisions bigint, resolution_rate numeric, avg_confidence numeric, escalation_rate numeric)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is null then raise exception 'not authenticated'; end if;
  if not (is_platform_admin() or exists (select 1 from profiles p where p.user_id = auth.uid() and p.tenant_id = p_tenant_id)) then
    raise exception 'not authorized to view this workspace''s performance data';
  end if;
  return query
    with dec as (
      select er.de_id as d_de_id, d.confidence as conf, d.decision as decision
      from evidence_run_decisions d
      join evidence_runs er on er.id = d.evidence_run_id
      where er.tenant_id = p_tenant_id and er.de_id is not null
        -- mig 709: A CERTIFICATION EXAM IS NOT PRODUCTION WORK (the 571 rule,
        -- via the 682 origin stamp). This organ fed the founder's
        -- OutcomeStatement per-DE decision counts with exam traffic — the
        -- same defect 571 fixed in get_de_performance_metrics.
        and public.evidence_is_production(er.origin)
        -- DE scoping (wave2 grpB): decisions narrow to the employees
        -- this caller is responsible for.
        and public.can_access_de(er.de_id)
        and (p_days is null or d.created_at >= now() - make_interval(days => p_days))
    )
    select
      dec.d_de_id as de_id,
      count(*)::bigint,
      round(100.0 * count(*) filter (where dec.decision <> 'needs_review') / nullif(count(*), 0), 1),
      round(avg(dec.conf) filter (where dec.conf is not null), 1),
      round(100.0 * count(*) filter (where dec.decision = 'needs_review') / nullif(count(*), 0), 1)
    from dec
    group by dec.d_de_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.get_de_kpi_status(p_de_id uuid)
 RETURNS TABLE(kpi_id uuid, name text, metric_key text, target numeric, direction text, current numeric, met boolean, sample bigint)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tenant uuid;
begin
  select tenant_id into v_tenant from digital_employees where id = p_de_id and public.can_access_de(id);
  if v_tenant is null then return; end if;
  if auth.role() is not null and auth.role() <> 'service_role' then
    if auth_tenant_id() is distinct from v_tenant then raise exception 'not a member of this workspace'; end if;
  end if;

  -- 13: the window this function has always used. Unchanged on purpose.
  return query select * from public.de_kpi_status_internal(v_tenant, p_de_id, 13);
end
$function$;

CREATE OR REPLACE FUNCTION public.get_de_metrics_batch(p_tenant_id uuid, p_de_id uuid, p_metric_keys text[] DEFAULT NULL::text[], p_date_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_date_to timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS TABLE(metric_key text, metric_name text, value numeric, unit text, trend text, comparison jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  PERFORM public._assert_caller_tenant(p_tenant_id);
  RETURN QUERY SELECT NULL::TEXT, NULL::TEXT, NULL::NUMERIC, NULL::TEXT, NULL::TEXT, NULL::JSONB WHERE FALSE;
END$function$;

CREATE OR REPLACE FUNCTION public.get_de_operating_model(p_de_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tenant uuid; v_de record; v_out jsonb; v_board jsonb;
BEGIN
  v_tenant := public.auth_tenant_id();
  IF v_tenant IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_permitted');
  END IF;
  SELECT * INTO v_de FROM digital_employees
   WHERE id = p_de_id AND tenant_id = v_tenant
     -- DE scoping (mig 385/392): one gate on the single lookup every read below
     -- is keyed to. Fail it and the function returns not_found before touching
     -- work sources, playbooks, objectives or deliverables.
     AND public.can_access_de(id);
  IF v_de.id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_found');
  END IF;

  -- The board row for this DE — next_up/listens_live come from the exact
  -- same read the whole-workforce board renders.
  v_board := (public.get_workforce_board(p_de_id)->'board')->0;

  v_out := jsonb_build_object(
    'ok', true,
    'identity', jsonb_build_object(
      'de_id', v_de.id, 'name', v_de.name, 'persona_name', v_de.persona_name,
      'department', v_de.department, 'category', v_de.category,
      'trust_level', v_de.trust_level, 'status', v_de.status),
    'work_sources', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
               'label', w.label, 'description', w.description, 'kind', w.kind,
               'active', w.active, 'next_fire_at', w.next_fire_at,
               'last_run_at', w.last_run_at, 'last_match_count', w.last_match_count)
             ORDER BY w.active DESC, w.label)
        FROM work_watchers w
       WHERE w.tenant_id = v_tenant AND w.de_id = p_de_id), '[]'::jsonb),
    'playbooks', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
               'key', p.key, 'name', p.name, 'status', p.status,
               'version', p.version, 'steps', jsonb_array_length(p.steps),
               'trigger_type', p.trigger_type)
             ORDER BY p.name)
        FROM playbook_definitions p
       WHERE p.tenant_id = v_tenant AND p.de_id = p_de_id
         AND p.status = 'published'), '[]'::jsonb),
    'open_objectives', COALESCE((
      SELECT count(*) FROM de_objectives o
       WHERE o.tenant_id = v_tenant AND o.de_id = p_de_id
         AND o.status IN ('open','in_progress','blocked')), 0),
    'waiting_on_human', COALESCE((
      SELECT count(*) FROM human_tasks h
       WHERE h.tenant_id = v_tenant AND h.de_id = p_de_id
         AND h.status = 'pending'), 0),

    -- v2 additions ---------------------------------------------------------
    'current_focus', (
      SELECT jsonb_build_object(
               'title', o.title, 'status', o.status,
               'next_wake_at', o.next_wake_at, 'wake_count', o.wake_count,
               'mission_id', o.mission_id, 'due_at', o.due_at)
        FROM de_objectives o
       WHERE o.tenant_id = v_tenant AND o.de_id = p_de_id
         AND o.status = 'in_progress'
       ORDER BY o.updated_at DESC LIMIT 1),
    'next_up', COALESCE(v_board->'next_up', '[]'::jsonb),
    'listens_live', COALESCE(v_board->'listens_live', 'false'::jsonb),
    'rhythm', jsonb_build_object(
      'done_7d', COALESCE((
        SELECT count(*) FROM de_work_items t
         WHERE t.tenant_id = v_tenant AND t.de_id = p_de_id
           AND t.status = 'done'
           AND t.updated_at >= now() - interval '7 days'), 0),
      'deliverables_7d', COALESCE((
        SELECT count(*) FROM de_deliverables d
         WHERE d.tenant_id = v_tenant AND d.de_id = p_de_id
           AND d.created_at >= now() - interval '7 days'), 0),
      'last_deliverable', (
        SELECT jsonb_build_object('title', d.title, 'at', d.created_at)
          FROM de_deliverables d
         WHERE d.tenant_id = v_tenant AND d.de_id = p_de_id
         ORDER BY d.created_at DESC LIMIT 1))
  );
  RETURN v_out;
END $function$;

CREATE OR REPLACE FUNCTION public.get_de_performance_metrics(p_tenant_id uuid, p_weeks integer DEFAULT 26)
 RETURNS TABLE(de_id uuid, de_name text, total_decisions bigint, resolution_rate numeric, avg_confidence numeric, escalation_rate numeric, blocked_guardrail_count bigint, total_runs bigint, error_rate numeric, avg_frustration_score numeric, high_frustration_count bigint, trend jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.role() is not null and auth.role() <> 'service_role' then
    if auth.uid() is null then
      raise exception 'not authenticated';
    end if;
    if not (
      is_platform_admin()
      or exists (select 1 from profiles p where p.user_id = auth.uid() and p.tenant_id = p_tenant_id)
    ) then
      raise exception 'not authorized to view this workspace''s performance data';
    end if;
  end if;

  return query
    with decisions as (
      select er.de_id as d_de_id, d.confidence as d_confidence, d.decision as d_decision,
        d.human_task_id as d_human_task_id, d.created_at as d_created_at,
        d.frustration_score as d_frustration_score
      from evidence_run_decisions d
      join evidence_runs er on er.id = d.evidence_run_id
      -- CASE, not a bare cast: external_ref is free text, and Postgres does not
      -- promise to evaluate a regex guard before a cast in the same predicate.
      left join de_conversations conv
        on conv.id = (case when d.external_ref ~ '^conversation:[0-9a-fA-F-]{36}$'
                           then substring(d.external_ref from 14)::uuid end)
      where er.tenant_id = p_tenant_id and er.de_id is not null
        -- p_weeks now means what it says. Without this the "fresh 4-week
        -- re-measure" behind every PIP verdict read the employee's whole life.
        and d.created_at > now() - (greatest(1, p_weeks) || ' weeks')::interval
        -- A CERTIFICATION EXAM IS NOT PRODUCTION WORK (mig 571). Exams run the
        -- real pipeline on purpose, so their decisions land here as
        -- source='live_channel', indistinguishable from customer work. Counting
        -- them made the employee's own exams its performance record — measured
        -- live: 54 of 57 decisions were exam answers, giving a 98% escalation
        -- rate that the reply-mode gate then used to DEMOTE it minutes after
        -- auto-send was granted. Exams also escalate by construction while the
        -- employee is gated, so the evidence of unworthiness was manufactured by
        -- the very state it justified. Threads filed under channel 'exam'
        -- (mig 570) are excluded; a decision with no traceable thread is KEPT,
        -- because unknown provenance must not silently erase real work.
        and conv.channel is distinct from 'exam'
    ),
    runs as (
      select er.de_id as r_de_id, er.status as r_status
      from evidence_runs er
      where er.tenant_id = p_tenant_id and er.de_id is not null
        and er.created_at > now() - (greatest(1, p_weeks) || ' weeks')::interval
        -- error_rate feeds the SAME demotion gate, so exam runs come out here
        -- too. An exam run is judged by the exam's own pass/fail, not twice.
        and not exists (
          select 1 from evidence_run_decisions d2
          join de_conversations c2
            on c2.id = (case when d2.external_ref ~ '^conversation:[0-9a-fA-F-]{36}$'
                             then substring(d2.external_ref from 14)::uuid end)
          where d2.evidence_run_id = er.id and c2.channel = 'exam')
    ),
    summary as (
      select
        dec.d_de_id as s_de_id,
        count(*) as total_decisions,
        round(100.0 * count(*) filter (where dec.d_decision <> 'needs_review') / nullif(count(*), 0), 1) as resolution_rate,
        round(avg(dec.d_confidence) filter (where dec.d_confidence is not null), 1) as avg_confidence,
        round(100.0 * count(*) filter (where dec.d_decision = 'needs_review') / nullif(count(*), 0), 1) as escalation_rate,
        count(*) filter (where dec.d_decision = 'blocked_guardrail') as blocked_guardrail_count,
        round(avg(dec.d_frustration_score) filter (where dec.d_frustration_score is not null), 1) as avg_frustration_score,
        count(*) filter (where dec.d_frustration_score >= 50) as high_frustration_count
      from decisions dec
      group by dec.d_de_id
    ),
    run_summary as (
      select r.r_de_id as rs_de_id, count(*) as total_runs,
        round(100.0 * count(*) filter (where r.r_status = 'failed') / nullif(count(*), 0), 1) as error_rate
      from runs r
      group by r.r_de_id
    ),
    weekly as (
      select
        dec.d_de_id as w_de_id,
        date_trunc('week', dec.d_created_at) as week_start,
        count(*) as decisions_count,
        round(100.0 * count(*) filter (where dec.d_decision <> 'needs_review') / nullif(count(*), 0), 1) as week_resolution_rate,
        round(avg(dec.d_confidence) filter (where dec.d_confidence is not null), 1) as week_avg_confidence
      from decisions dec
      where dec.d_created_at > now() - (p_weeks || ' weeks')::interval
      group by dec.d_de_id, date_trunc('week', dec.d_created_at)
    ),
    trend_agg as (
      select w.w_de_id as t_de_id, jsonb_agg(
        jsonb_build_object(
          'week', to_char(w.week_start, 'YYYY-MM-DD'),
          'decisions', w.decisions_count,
          'resolution_rate', w.week_resolution_rate,
          'avg_confidence', w.week_avg_confidence
        ) order by w.week_start
      ) as trend
      from weekly w
      group by w.w_de_id
    )
    select
      de.id, de.name,
      -- COUNTS stay coalesced: an employee that made no decisions genuinely
      -- made zero, and "no data" would be the lie in the other direction.
      coalesce(s.total_decisions, 0),
      -- RATES are no longer invented. NULL means "not measured", which is the
      -- truth for every employee whose work never produced this evidence.
      s.resolution_rate,
      s.avg_confidence,
      s.escalation_rate,
      coalesce(s.blocked_guardrail_count, 0),
      coalesce(rs.total_runs, 0),
      -- NULL only when there were no runs at all; a computed 0.0 over real
      -- runs is a true zero and survives.
      rs.error_rate,
      s.avg_frustration_score,
      coalesce(s.high_frustration_count, 0),
      coalesce(t.trend, '[]'::jsonb)
    from digital_employees de
    left join summary s on s.s_de_id = de.id
    left join run_summary rs on rs.rs_de_id = de.id
    left join trend_agg t on t.t_de_id = de.id
    where de.tenant_id = p_tenant_id
      -- DE scoping (mig 385/435), REPAIRED by mig 454. The trusted-server test
      -- MIRRORS this function's own membership gate at the top of the body;
      -- 435 omitted it, so pg_cron — direct connection, no JWT, auth.role()
      -- NULL — failed the guard for every employee and four jobs read nothing.
      and (auth.role() is null
           or auth.role() = 'service_role'
           or public.can_access_de(de.id))
    order by de.name;
end;
$function$;

CREATE OR REPLACE FUNCTION public.get_de_performance_summary(p_de_id uuid, p_time_window_days integer DEFAULT 30)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tenant_id UUID;
  v_de_name TEXT;
  v_de_status TEXT;
  v_current_stage TEXT;
  v_cost_this_month NUMERIC;
  v_responses_this_month INT;
  v_amendments_count INT;
  v_training_sessions INT;
BEGIN
  SELECT tenant_id, name, status INTO v_tenant_id, v_de_name, v_de_status
  FROM digital_employees WHERE id = p_de_id;

  IF v_tenant_id IS NULL THEN RAISE EXCEPTION 'DE not found'; END IF;
  -- Trusted-server gate, same shape as get_de_performance_metrics (571/454):
  -- pg_cron and server scripts carry no JWT; humans need a management role in
  -- the employee's own workspace.
  IF auth.role() IS NOT NULL AND auth.role() <> 'service_role' THEN
    IF NOT (v_tenant_id = auth_tenant_id() AND auth_has_tenant_role(ARRAY['tenant_owner', 'tenant_admin', 'tenant_manager'])) THEN
      RAISE EXCEPTION 'Unauthorized';
    END IF;
  END IF;

  SELECT stage INTO v_current_stage FROM de_deployment_stages WHERE de_id = p_de_id;
  IF v_current_stage IS NULL THEN v_current_stage := 'unknown'; END IF;

  -- Real AI spend this calendar month (de_token_usage × published pricing —
  -- the platform's actual cost source). The old read named
  -- tenant_cost_tracking.entity_id, a column that does not exist (42703), so
  -- this function has never returned since the rebuild — the panel was blank.
  SELECT coalesce(round(sum(
      (u.input_tokens::numeric / 1000000) * coalesce(pr.input_price_per_million, 3.00)
      + (u.output_tokens::numeric / 1000000) * coalesce(pr.output_price_per_million, 15.00)
    ), 2), 0) INTO v_cost_this_month
  FROM de_token_usage u
  LEFT JOIN ai_model_pricing pr ON pr.model_id = u.model_id
  WHERE u.de_id = p_de_id AND u.created_at >= date_trunc('month', now());

  -- A real count of real rows (subject_kind/subject_id are the actual
  -- columns; the old read named action_executions.de_id, which never existed
  -- here). A genuine zero is a true measurement and stays 0.
  SELECT COALESCE(COUNT(*), 0) INTO v_responses_this_month
  FROM de_messages m JOIN de_conversations c ON c.id = m.conversation_id
  WHERE c.de_id = p_de_id AND m.role = 'assistant'
    AND m.created_at > now() - (p_time_window_days || ' days')::interval;

  SELECT COALESCE(COUNT(*), 0) INTO v_amendments_count FROM workforce_actions
  WHERE entity_id = p_de_id AND action_type IN ('de_amend', 'de_train') AND applied_at IS NOT NULL AND created_at > now() - (p_time_window_days || ' days')::interval;

  SELECT COALESCE(COUNT(*), 0) INTO v_training_sessions FROM de_training_feedback
  WHERE de_id = p_de_id AND created_at > now() - (p_time_window_days || ' days')::interval;

  RETURN json_build_object(
    'de_id', p_de_id, 'de_name', v_de_name, 'de_status', v_de_status,
    'current_stage', v_current_stage, 'time_window_days', p_time_window_days,
    'cost_this_month', v_cost_this_month,
    'responses_this_month', v_responses_this_month,
    -- mig 492: satisfaction has no survey source in this platform; the honest
    -- value is NULL, and the client renders "Not measured".
    'avg_csat', NULL,
    -- mig 708: these two used to read action_executions.status, a column that
    -- has never existed here. Answering escalation/resolution rates live in
    -- get_de_performance_metrics (exam-filtered, 571); this action panel has
    -- no measured source for them, and an unmeasured rate is NULL, not 0.
    'escalation_rate', NULL,
    'resolution_rate', NULL,
    'amendments_applied', v_amendments_count,
    'training_sessions', v_training_sessions,
    -- Real spend averaged per day of the month — the client labels it as AI
    -- spend, not as an FTE claim. (Key name kept for interface compatibility.)
    'fte_equivalent_cost', ROUND((v_cost_this_month / 30)::numeric, 2),
    -- mig 708 (§12.3): the old value was count × 0.5h — a platform-invented
    -- half-hour booked for every row, including human-gated rows that never
    -- executed and the second row of every approved action. Hours saved
    -- appear ONLY from a tenant-typed baseline (get_de_economics does that
    -- job); this panel has none, so the honest value is unknown.
    'roi_hours_saved', NULL,
    'timestamp', now());
END;
$function$;

CREATE OR REPLACE FUNCTION public.get_de_role_context(p_de_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_tenant uuid; v_de record; v_arch record; v_domains jsonb;
begin
  v_tenant := public.auth_tenant_id();
  if v_tenant is null then return jsonb_build_object('ok', false, 'error', 'not_permitted'); end if;
  select id, category, department
    into v_de from digital_employees where id = p_de_id and tenant_id = v_tenant;
  if not found then return jsonb_build_object('ok', false, 'error', 'de_not_found'); end if;
  if not public.can_access_de(p_de_id) then
    return jsonb_build_object('ok', false, 'error', 'de_not_found');
  end if;

  -- Domains it operates = the system categories it's actually granted.
  select coalesce(jsonb_agg(distinct g.resource_category), '[]'::jsonb) into v_domains
    from data_access_grants g
   where g.tenant_id = v_tenant and g.subject_kind = 'de' and g.subject_id = p_de_id
     and g.resource_category is not null;

  -- Certified archetype (if any) supplies the canonical role name + domain.
  select ra.key, ra.name, ra.domain, ra.required_connector_categories
    into v_arch
    from role_certifications rc
    join role_archetypes ra on ra.key = rc.archetype_key
   where rc.tenant_id = v_tenant and rc.de_id = p_de_id and rc.archetype_key is not null
   order by rc.evaluated_at desc nulls last limit 1;

  return jsonb_build_object(
    'ok', true,
    'department', v_de.department,
    'category', v_de.category,
    
    'domains', v_domains,
    'archetype_key', v_arch.key,
    'archetype_name', v_arch.name,
    'archetype_domain', v_arch.domain,
    'archetype_categories', coalesce(to_jsonb(v_arch.required_connector_categories), '[]'::jsonb)
  );
end $function$;

CREATE OR REPLACE FUNCTION public.get_de_systems(p_de_id uuid)
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT coalesce(jsonb_agg(jsonb_build_object(
    'system_key', t.system_key, 'label', t.label, 'source_table', t.source_table,
    'read_fields', t.read_fields, 'can_read', t.can_read, 'can_write', t.can_write,
    'can_verify', t.can_verify, 'can_operate', t.can_operate,
    'operate_domain', public.operate_domain_of(t),
    'write_registry', t.write_registry) ORDER BY t.system_key), '[]'::jsonb)
  FROM de_connected_systems t WHERE t.de_id = p_de_id AND t.active
    -- Guard (mig 432). The service_role branch is NOT optional: de-work
    -- calls this with an admin client whose JWT has no sub, so
    -- auth_tenant_id() is NULL there. Without it the worker would silently
    -- see every employee as having no connected systems and stop doing
    -- integration work, with no error and no alert.
    AND EXISTS (
          SELECT 1 FROM digital_employees d
           WHERE d.id = p_de_id
             AND (coalesce(auth.role(), '') = 'service_role'
                  OR d.tenant_id = public.auth_tenant_id())
             AND public.can_access_de(d.id));
$function$;

CREATE OR REPLACE FUNCTION public.get_de_work_metrics(p_tenant_id uuid, p_weeks integer DEFAULT 26)
 RETURNS TABLE(de_id uuid, de_name text, archetype_key text, items_completed bigint, items_cancelled bigint, items_waiting_human bigint, escalations_raised bigint, escalations_answered bigint, escalations_unanswered bigint, escalation_rate numeric, oldest_unanswered_hours numeric, goals_open bigint, goals_blocked bigint, goals_needing_attention bigint, attention_oldest_since timestamp with time zone, wakes_recorded bigint, wakes_concluded_blocked bigint)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_since timestamptz := now() - (greatest(1, p_weeks) || ' weeks')::interval;
begin
  if auth.role() is not null and auth.role() <> 'service_role' then
    if auth.uid() is null then
      raise exception 'not authenticated';
    end if;
    if not (
      is_platform_admin()
      or exists (select 1 from profiles p where p.user_id = auth.uid() and p.tenant_id = p_tenant_id)
    ) then
      raise exception 'not authorized to view this workspace''s work data';
    end if;
  end if;

  return query
  with items as (
    select w.de_id as i_de,
           count(*) filter (where w.status = 'done') as done,
           count(*) filter (where w.status = 'cancelled') as cancelled,
           count(*) filter (where w.status = 'waiting_human') as waiting
      from de_work_items w
     where w.tenant_id = p_tenant_id and w.updated_at >= v_since
     group by w.de_id
  ),
  esc as (
    -- WORK-ENGINE escalations only. A chat escalation is answer-path evidence
    -- and belongs to the answer-shaped metrics; counting it here made an
    -- answer-only employee report a 100% work escalation rate (mig 499 defect).
    select h.de_id as e_de,
           count(*) as raised,
           count(*) filter (where h.status <> 'pending') as answered,
           count(*) filter (where h.status = 'pending') as unanswered,
           max(extract(epoch from (now() - h.created_at)) / 3600.0)
             filter (where h.status = 'pending') as oldest_hours
      from human_tasks h
     where h.tenant_id = p_tenant_id
       and h.type = 'escalation'
       and h.source = 'de'
       and h.de_id is not null
       and h.related_table in ('de_work_items', 'de_objectives')
       and h.created_at >= v_since
     group by h.de_id
  ),
  goals as (
    select o.de_id as g_de,
           count(*) filter (where o.status in ('open', 'in_progress')) as open_goals,
           count(*) filter (where o.status = 'blocked') as blocked_goals,
           count(*) filter (where o.attention_flag is not null
                              and o.status in ('open', 'in_progress', 'blocked')) as flagged,
           min(o.attention_since) filter (where o.attention_flag is not null) as oldest_flag
      from de_objectives o
     where o.tenant_id = p_tenant_id
     group by o.de_id
  ),
  wakes as (
    select k.de_id as w_de,
           count(*) as recorded,
           count(*) filter (where k.assessment = 'blocked') as blocked_conclusions
      from de_objective_wakes k
     where k.tenant_id = p_tenant_id and k.started_at >= v_since
     group by k.de_id
  )
  select
    d.id, d.name, d.archetype_key,
    coalesce(i.done, 0), coalesce(i.cancelled, 0), coalesce(i.waiting, 0),
    coalesce(e.raised, 0), coalesce(e.answered, 0), coalesce(e.unanswered, 0),
    round(100.0 * coalesce(e.raised, 0)
          / nullif(coalesce(i.done, 0) + coalesce(i.cancelled, 0) + coalesce(e.raised, 0), 0), 1),
    round(e.oldest_hours, 1),
    coalesce(g.open_goals, 0), coalesce(g.blocked_goals, 0), coalesce(g.flagged, 0),
    g.oldest_flag,
    coalesce(k.recorded, 0), coalesce(k.blocked_conclusions, 0)
  from digital_employees d
  left join items i on i.i_de = d.id
  left join esc   e on e.e_de = d.id
  left join goals g on g.g_de = d.id
  left join wakes k on k.w_de = d.id
  where d.tenant_id = p_tenant_id
    and (auth.role() is null
         or auth.role() = 'service_role'
         or public.can_access_de(d.id))
  order by d.name;
end;
$function$;

CREATE OR REPLACE FUNCTION public.get_de_work_product(p_de_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_tenant uuid; v_conv jsonb; v_actions jsonb;
begin
  v_tenant := public.auth_tenant_id();
  if v_tenant is null then return jsonb_build_object('ok', false, 'error', 'not_permitted'); end if;
  if not exists (select 1 from digital_employees where id = p_de_id and tenant_id = v_tenant and public.can_access_de(id)) then
    return jsonb_build_object('ok', false, 'error', 'de_not_found');
  end if;

  -- Conversational work-product (support/CRM/product domains).
  select jsonb_build_object(
      'total', count(*),
      'resolved', count(*) filter (where status = 'resolved'),
      'open', count(*) filter (where status in ('needs_human', 'human_owned', 'ai_handling')),
      'by_channel', coalesce((select jsonb_object_agg(ch, n) from (
          select channel ch, count(*) n from de_conversations
           where tenant_id = v_tenant and de_id = p_de_id group by channel) c), '{}'::jsonb)
    ) into v_conv
    from de_conversations where tenant_id = v_tenant and de_id = p_de_id;

  -- System-action work-product, grouped by category + human label. Each row
  -- already carries its domain category — this is the generic bit.
  select coalesce(jsonb_agg(row_to_json(x) order by x.n desc), '[]'::jsonb) into v_actions from (
    select ad.category, ad.label,
           count(*) as n,
           count(*) filter (where ae.decision = 'auto_executed') as auto_n,
           count(*) filter (where ae.decision like 'human_gated%') as gated_n,
           max(ae.created_at) as last_at
      from action_executions ae
      join action_definitions ad on ad.id = ae.action_definition_id
     where ae.tenant_id = v_tenant and ae.subject_kind = 'de' and ae.subject_id = p_de_id
       and ae.rollback_of is null
     group by ad.category, ad.label
  ) x;

  return jsonb_build_object('ok', true, 'conversations', v_conv, 'actions', v_actions);
end $function$;

CREATE OR REPLACE FUNCTION public.get_de_worklists(p_tenant_id uuid, p_de_id uuid)
 RETURNS TABLE(worklist_key text, label text, row_count bigint, sample jsonb, book_is_empty boolean, source_table text, source_has_any_rows boolean)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_arch text;
  v_src_any boolean;
  v_templates jsonb;
  t jsonb;
begin
  if auth.role() is not null and auth.role() <> 'service_role' then
    if auth.uid() is null then raise exception 'not authenticated'; end if;
    if not (is_platform_admin()
            or exists (select 1 from profiles p where p.user_id = auth.uid() and p.tenant_id = p_tenant_id)) then
      raise exception 'not authorized to view this workspace';
    end if;
  end if;
  if not (auth.role() is null or auth.role() = 'service_role' or public.can_access_de(p_de_id)) then
    raise exception 'not authorized to view this employee';
  end if;

  select d.archetype_key into v_arch from digital_employees d
   where d.id = p_de_id and d.tenant_id = p_tenant_id;
  if v_arch is null then return; end if;

  select a.worklist_templates into v_templates from role_archetypes a where a.key = v_arch;
  if v_templates is null or v_templates = '[]'::jsonb then return; end if;

  for t in select * from jsonb_array_elements(v_templates) loop
    worklist_key := t->>'key';
    label        := t->>'label';
    row_count    := 0;
    sample       := '[]'::jsonb;
    source_table := null;
    source_has_any_rows := null;

    -- CLOSED LIBRARY. Every predicate is written here; nothing comes from data.
    case worklist_key

      when 'overdue_invoices' then
        source_table := 'renewal_invoices + invoices';
        select count(*), coalesce(jsonb_agg(x order by x->>'due_date') filter (where x is not null), '[]'::jsonb)
          into row_count, sample
          from (
            select jsonb_build_object('invoice', i.invoice_number, 'due', i.due_date,
                                      'amount', i.amount, 'status', i.status, 'source', 'invoices') as x,
                   i.due_date as ord
              from invoices i
             where i.tenant_id = p_tenant_id
               and i.due_date < current_date
               and coalesce(i.status, '') not in ('paid', 'void', 'cancelled')
            union all
            -- The ERP ingest (mig 517) lands real invoices in renewal_invoices,
            -- which this book did not read: 8 invoices worth $478k, two of them
            -- overdue, were invisible while the sweep reported "all accounts
            -- current". Same book, both sources.
            select jsonb_build_object('invoice', coalesce(r.source_external_ref, r.id::text), 'due', r.due_date,
                                      'amount', (r.amount_cents / 100.0), 'status', r.status,
                                      'still_owed', case when r.outstanding_cents is not null
                                                         then (r.outstanding_cents / 100.0)::text
                                                         else 'UNVERIFIED - no payment has ever been reconciled against this invoice; the amount shown is the face value, not a confirmed balance' end,
                                      'source', coalesce(r.source_provider, 'renewal_invoices')) as x,
                   r.due_date as ord
              from renewal_invoices r
             where r.tenant_id = p_tenant_id
               and r.due_date < current_date
               and coalesce(r.status, '') not in ('paid', 'void', 'cancelled')
             order by ord limit 25
          ) s;

      when 'unpaid_invoices' then
        source_table := 'renewal_invoices + invoices';
        select count(*), coalesce(jsonb_agg(x) filter (where x is not null), '[]'::jsonb)
          into row_count, sample
          from (
            select jsonb_build_object('invoice', i.invoice_number, 'due', i.due_date,
                                      'amount', i.amount, 'paid', i.amount_paid, 'status', i.status,
                                      'source', 'invoices') as x,
                   i.due_date as ord
              from invoices i
             where i.tenant_id = p_tenant_id
               and coalesce(i.status, '') not in ('paid', 'void', 'cancelled')
            union all
            select jsonb_build_object('invoice', coalesce(r.source_external_ref, r.id::text), 'due', r.due_date,
                                      'amount', (r.amount_cents / 100.0), 'status', r.status,
                                      'still_owed', case when r.outstanding_cents is not null
                                                         then (r.outstanding_cents / 100.0)::text
                                                         else 'UNVERIFIED - no payment has ever been reconciled against this invoice; the amount shown is the face value, not a confirmed balance' end,
                                      'source', coalesce(r.source_provider, 'renewal_invoices')) as x,
                   r.due_date as ord
              from renewal_invoices r
             where r.tenant_id = p_tenant_id
               and coalesce(r.status, '') not in ('paid', 'void', 'cancelled')
             order by ord nulls last limit 25
          ) s;

      when 'unreconciled_entries' then
        source_table := 'journal_entries';
        select count(*), coalesce(jsonb_agg(x) filter (where x is not null), '[]'::jsonb)
          into row_count, sample
          from (
            select jsonb_build_object('date', j.entry_date, 'memo', left(coalesce(j.memo, ''), 120),
                                      'debit', j.debit, 'credit', j.credit, 'source', j.source) as x
              from journal_entries j
             where j.tenant_id = p_tenant_id
               and j.entry_date >= date_trunc('month', current_date)
             order by j.entry_date desc limit 25
          ) s;

      when 'stalled_onboarding' then
        source_table := 'onboarding_projects';
        select count(*), coalesce(jsonb_agg(x) filter (where x is not null), '[]'::jsonb)
          into row_count, sample
          from (
            select jsonb_build_object('project', o.name, 'status', o.status,
                                      'progress_pct', o.progress_pct, 'target_golive', o.target_golive,
                                      'days_since_update', (current_date - o.updated_at::date)) as x
              from onboarding_projects o
             where o.tenant_id = p_tenant_id
               and o.completed_at is null
             order by o.updated_at limit 25
          ) s;

      when 'at_risk_accounts' then
        source_table := 'customer_accounts';
        select count(*), coalesce(jsonb_agg(x) filter (where x is not null), '[]'::jsonb)
          into row_count, sample
          from (
            select jsonb_build_object('account', c.name, 'health', c.health_score,
                                      'status', c.status, 'renews', c.renewal_date) as x
              from customer_accounts c
             where c.tenant_id = p_tenant_id
               and (coalesce(c.status, '') = 'at_risk' or coalesce(c.health_score, 100) < 50)
             order by c.health_score nulls last limit 25
          ) s;

      when 'payable_invoices' then
        -- Mig 803: the AP book. Same sample-of-25 semantics as the AR books,
        -- same UNVERIFIED honesty when the source never stated a balance.
        source_table := 'purchase_invoices';
        select count(*), coalesce(jsonb_agg(x) filter (where x is not null), '[]'::jsonb)
          into row_count, sample
          from (
            select jsonb_build_object('invoice', pi.source_external_ref, 'supplier', pi.supplier_name,
                                      'due', pi.due_date, 'amount', (pi.amount_cents / 100.0),
                                      'still_owed', case when pi.outstanding_cents is not null
                                                         then (pi.outstanding_cents / 100.0)::text
                                                         else 'UNVERIFIED - the source did not state a balance; the amount shown is the face value' end,
                                      'status', pi.status, 'source', pi.source_provider) as x,
                   pi.due_date as ord
              from purchase_invoices pi
             where pi.tenant_id = p_tenant_id
               and coalesce(pi.outstanding_cents, pi.amount_cents) > 0
               and lower(coalesce(pi.status, '')) not in ('paid', 'cancelled', 'return')
             order by ord nulls last limit 25
          ) s;

      when 'accounts_book' then
        source_table := 'customer_accounts';
        select count(*), coalesce(jsonb_agg(x) filter (where x is not null), '[]'::jsonb)
          into row_count, sample
          from (
            select jsonb_build_object('account', c.name, 'health', c.health_score,
                                      'status', c.status, 'renews', c.renewal_date) as x
              from customer_accounts c
             where c.tenant_id = p_tenant_id
               and coalesce(c.status, '') <> 'churned'
             order by c.name limit 25
          ) s;

      else
        -- A template naming a book the library does not implement. Say so
        -- rather than returning an empty list that reads as "nothing to do".
        label := coalesce(label, worklist_key) || ' (not available)';
        source_table := null;
    end case;

    -- THE DISTINCTION THIS WHOLE DESK RESTS ON.
    -- "0 invoices past due" finishes an AR sweep honestly. "I am pointed at a
    -- source that holds nothing for this tenant" does NOT — but until now both
    -- returned book_is_empty = true, and the SOP's "if the book is empty you are
    -- finished" rule turned the second into a confident all-clear. That is how a
    -- polished Daily AR Sweep Summary came to say "All accounts current, total
    -- invoices reviewed: 0" over $431k of live receivables.
    --
    -- NULL is the third answer, exactly as mig 491 made a rate with no
    -- denominator NULL rather than 0: not empty, not populated — unknown.
    if coalesce(row_count, 0) > 0 then
      book_is_empty := false;
    else
      v_src_any := case source_table
        -- Closed library, same as the predicates above: nothing here comes from data.
        -- FIX 1: migration 603 renamed this assignment to 'renewal_invoices + invoices'
        -- (both tables are unioned in the predicate now) but never added the matching
        -- arm, so every invoice book fell to `else null` the moment it had no rows.
        -- Latent while the books had work; it would have turned "no overdue invoices"
        -- into "this book cannot be read" the first quiet day. The old literal stays
        -- for any caller or template still naming it.
        when 'renewal_invoices + invoices'
                                   then (exists (select 1 from invoices            where tenant_id = p_tenant_id)
                                      or exists (select 1 from renewal_invoices    where tenant_id = p_tenant_id))
        when 'invoices'            then (exists (select 1 from invoices            where tenant_id = p_tenant_id)
                                      or exists (select 1 from renewal_invoices    where tenant_id = p_tenant_id))
        when 'journal_entries'     then  exists (select 1 from journal_entries     where tenant_id = p_tenant_id)
        when 'onboarding_projects' then  exists (select 1 from onboarding_projects where tenant_id = p_tenant_id)
        when 'customer_accounts'   then  exists (select 1 from customer_accounts   where tenant_id = p_tenant_id)
        when 'purchase_invoices'   then  exists (select 1 from purchase_invoices   where tenant_id = p_tenant_id)
        else null
      end;

      source_has_any_rows := v_src_any;

      -- FIX 2: SPLIT THE TWO MEANINGS OF NULL.
      --
      -- Until now NULL meant both "this source holds nothing for you" (common,
      -- benign, permanent for a young tenant) and "this book resolves to no
      -- source at all" (a real configuration gap). de-work renders NULL as
      -- "CANNOT BE READ — no source is connected for it" and then ORDERS an
      -- escalation, so the benign case produced a nightly false alarm: the
      -- Onboarding DE escalated 13 times in 3 days because onboarding_projects
      -- was simply empty.
      --
      -- Now:
      --   false -> rows matched the filter
      --   true  -> the source resolved and holds nothing matching. GENUINELY
      --            EMPTY, and a legitimate "nothing to work today". Whether the
      --            source is entirely unpopulated is reported separately in
      --            source_has_any_rows, so the runtime can say so WITHOUT
      --            claiming a connection failure it never measured.
      --   NULL  -> we could not resolve a source for this book at all: either
      --            the worklist key is not implemented (source_table is null)
      --            or its source_table literal matches no arm above. Both are
      --            real config gaps and both deserve a human.
      --
      -- The mig-528 property survives: a book pointed at the WRONG table is
      -- caught by the arm-coverage probe in `npm run certify`, not by
      -- pretending every empty table is a connection failure.
      book_is_empty := case
        when source_table is null then null
        when v_src_any is null    then null
        else true
      end;
    end if;
    return next;
  end loop;
end;
$function$;

CREATE OR REPLACE FUNCTION public.get_dispatch_health(p_hours integer DEFAULT 24)
 RETURNS TABLE(window_hours integer, http_total bigint, http_failed bigint, http_timed_out bigint, cron_runs bigint, cron_failed bigint, worst_error text, last_failure_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT public.is_platform_admin() THEN
    RAISE EXCEPTION 'get_dispatch_health: platform admin only';
  END IF;

  RETURN QUERY
  WITH h AS (
    SELECT * FROM net._http_response
     WHERE created > now() - make_interval(hours => p_hours)
  ), c AS (
    SELECT * FROM cron.job_run_details
     WHERE start_time > now() - make_interval(hours => p_hours)
  )
  SELECT p_hours,
         (SELECT count(*) FROM h),
         (SELECT count(*) FROM h WHERE error_msg IS NOT NULL OR status_code >= 400),
         (SELECT count(*) FROM h WHERE error_msg ILIKE '%timeout%'),
         (SELECT count(*) FROM c),
         (SELECT count(*) FROM c WHERE status = 'failed'),
         (SELECT error_msg FROM h WHERE error_msg IS NOT NULL
           ORDER BY created DESC LIMIT 1),
         (SELECT max(created) FROM h WHERE error_msg IS NOT NULL);
END $function$;

CREATE OR REPLACE FUNCTION public.get_embedding_coverage(p_tenant_id uuid)
 RETURNS TABLE(total_chunks bigint, embedded_chunks bigint, coverage_pct numeric)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select count(c.*) as total_chunks,
         count(c.*) filter (where c.embedding is not null) as embedded_chunks,
         case when count(c.*) = 0 then 100
              else round(100.0 * count(c.*) filter (where c.embedding is not null) / count(c.*), 1)
         end as coverage_pct
  from knowledge_doc_chunks c
  join knowledge_docs kd on kd.id = c.doc_id
  where kd.tenant_id = p_tenant_id
    and (auth.uid() is null or exists (
      select 1 from profiles p where p.user_id = auth.uid()
        and (p.layer = 'platform' or p.tenant_id = p_tenant_id)));
$function$;

CREATE OR REPLACE FUNCTION public.get_employee_record(p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tenant  uuid := auth_tenant_id();
  v_self    boolean := (p_user_id = auth.uid());
  v_admin   boolean := auth_has_tenant_role(array['tenant_owner','tenant_admin']);
  v_profile jsonb;
  v_private jsonb;
  v_comp    jsonb;
begin
  if v_tenant is null then raise exception 'not_authenticated'; end if;

  select to_jsonb(p) - 'id' into v_profile
  from profiles p where p.user_id = p_user_id and p.tenant_id = v_tenant;
  if v_profile is null then raise exception 'no_such_employee_in_this_workspace'; end if;

  if v_self or v_admin then
    select to_jsonb(pp) into v_private from profile_private pp
     where pp.user_id = p_user_id and pp.tenant_id = v_tenant;
    select coalesce(jsonb_agg(to_jsonb(c) order by c.effective_from desc), '[]'::jsonb) into v_comp
      from profile_compensation c where c.user_id = p_user_id and c.tenant_id = v_tenant;
  end if;

  return jsonb_build_object(
    'profile', v_profile,
    'private', v_private,
    'compensation', v_comp,
    -- Say what is missing and why. A blank section that might mean "no data"
    -- or might mean "not for you" is worse than either answer.
    'withheld', case when v_self or v_admin then '[]'::jsonb
                     else jsonb_build_array('private', 'compensation') end,
    'can_edit_job', auth_has_tenant_role(array['tenant_owner','tenant_admin','tenant_manager']),
    'can_edit_private', (v_self or v_admin),
    'can_edit_pay', v_admin
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.get_identity_inventory(p_tenant_id uuid)
 RETURNS TABLE(subject_kind text, subject_id uuid, subject_name text, subject_label text, subject_role text, subject_status text, connector_id uuid, connector_name text, connector_provider text, connector_category text, connector_status text, connector_last_ok_at timestamp with time zone, connector_last_error_at timestamp with time zone, connector_consecutive_failures integer, has_stored_credential boolean, permission text, permission_via text, trust_current_level integer, trust_target_level integer, autonomy_enabled boolean, possible_actions jsonb)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_caller_tenant uuid; v_is_service boolean := coalesce(auth.role(), '') = 'service_role'; v_is_active boolean;
begin
  if not v_is_service then
    select coalesce(is_active, true) into v_is_active from profiles where user_id = auth.uid();
    if v_is_active is false then raise exception 'account is deactivated'; end if;
    v_caller_tenant := auth_tenant_id();
    if v_caller_tenant is null then raise exception 'not authenticated or no tenant membership'; end if;
    if v_caller_tenant is distinct from p_tenant_id then raise exception 'not a member of this tenant'; end if;
  end if;
  if not is_feature_enabled_internal(p_tenant_id, 'identity_credential_inventory') then return; end if;

  return query
  with subjects as (
    select 'de'::text as subject_kind, d.id as subject_id, d.name as subject_name,
           coalesce(d.persona_name, d.name) as subject_label,
           coalesce(nullif(d.department, ''), d.category) as subject_role,
           d.status as subject_status
    from digital_employees d where d.tenant_id = p_tenant_id
  ),
  grants_resolved as (
    select g.subject_kind, g.subject_id, c.id as connector_id, g.permission, 'category'::text as via, g.resource_category as eff_category
    from data_access_grants g join connectors c on c.tenant_id = g.tenant_id and c.category = g.resource_category
    where g.tenant_id = p_tenant_id and g.resource_kind = 'category'
    union all
    select g.subject_kind, g.subject_id, g.resource_id as connector_id, g.permission, 'connector'::text as via, c.category as eff_category
    from data_access_grants g join connectors c on c.id = g.resource_id and c.tenant_id = p_tenant_id
    where g.tenant_id = p_tenant_id and g.resource_kind = 'connector'
  ),
  grants_final as (
    select distinct on (gr.subject_kind, gr.subject_id, gr.connector_id) gr.subject_kind, gr.subject_id, gr.connector_id, gr.permission, gr.via, gr.eff_category
    from grants_resolved gr order by gr.subject_kind, gr.subject_id, gr.connector_id, (gr.via = 'connector') desc
  ),
  secrets as (select cs.connector_id as secret_connector_id, true as has_secret from connector_secrets cs),
  trust as (select tp.de_id, tp.source_category, tp.current_level, tp.target_level from trust_policies tp where tp.tenant_id = p_tenant_id and tp.action_category = 'action_execute'),
  autonomy as (select da.source_category, da.enabled from de_autonomy da where da.tenant_id = p_tenant_id and da.action_type = 'action_execute'),
  actions_by_category as (
    select ad.category, jsonb_agg(jsonb_build_object('action_key', ad.action_key, 'label', ad.label, 'destructive', coalesce((ad.risk->>'destructive')::boolean, true)) order by ad.label) as actions
    from action_definitions ad where ad.status = 'active' and (ad.scope = 'platform' or ad.tenant_id = p_tenant_id) group by ad.category
  )
  select s.subject_kind, s.subject_id, s.subject_name, s.subject_label, s.subject_role, s.subject_status,
    c.id, c.display_name, c.provider, c.category, c.status, c.last_ok_at, c.last_error_at, c.consecutive_failures,
    coalesce(sec.has_secret, false), gf.permission, gf.via,
    coalesce((select tr.current_level from trust tr where tr.de_id = s.subject_id and tr.source_category = c.category),
             (select tr.current_level from trust tr where tr.de_id = s.subject_id and tr.source_category is null)),
    coalesce((select tr.target_level from trust tr where tr.de_id = s.subject_id and tr.source_category = c.category),
             (select tr.target_level from trust tr where tr.de_id = s.subject_id and tr.source_category is null)),
    coalesce((select au.enabled from autonomy au where au.source_category = c.category), (select au.enabled from autonomy au where au.source_category is null)),
    coalesce(abc.actions, '[]'::jsonb)
  from subjects s
  left join grants_final gf on gf.subject_kind = s.subject_kind and gf.subject_id = s.subject_id
  left join connectors c on c.id = gf.connector_id
  left join secrets sec on sec.secret_connector_id = c.id
  left join actions_by_category abc on abc.category = c.category
  order by s.subject_kind, s.subject_name, c.category, c.display_name;
end; $function$;

CREATE OR REPLACE FUNCTION public.get_knowledge_conflict_status()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT jsonb_build_object(
    'ok', true,
    'enabled', is_feature_enabled_internal(auth_tenant_id(), 'knowledge_conflict_detection'),
    'open_count', (SELECT count(*) FROM knowledge_conflicts
                    WHERE tenant_id = auth_tenant_id() AND status = 'open'));
$function$;

CREATE OR REPLACE FUNCTION public.get_knowledge_conflicts(p_status text DEFAULT 'open'::text, p_relation text DEFAULT NULL::text, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0)
 RETURNS TABLE(id uuid, relation text, status text, cosine_distance real, confidence real, signal jsonb, doc_a_id uuid, doc_a_title text, doc_b_id uuid, doc_b_title text, authoritative_doc_id uuid, detected_at timestamp with time zone)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT kc.id, kc.relation, kc.status, kc.cosine_distance, kc.confidence, kc.signal,
         kc.doc_a_id, da.title, kc.doc_b_id, db.title,
         kc.authoritative_doc_id, kc.detected_at
  FROM knowledge_conflicts kc
  JOIN knowledge_docs da ON da.id = kc.doc_a_id
  JOIN knowledge_docs db ON db.id = kc.doc_b_id
  WHERE kc.tenant_id IN (SELECT tenant_id FROM profiles WHERE user_id = auth.uid())
    AND kc.status = p_status
    AND (p_relation IS NULL OR kc.relation = p_relation)
  ORDER BY kc.detected_at DESC
  LIMIT least(greatest(coalesce(p_limit, 50), 1), 100) OFFSET greatest(coalesce(p_offset, 0), 0);
$function$;

CREATE OR REPLACE FUNCTION public.get_knowledge_coverage_demand(p_days integer DEFAULT 30, p_gap_limit integer DEFAULT 20, p_list_limit integer DEFAULT 10)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tenant uuid := auth_tenant_id();
  v_probe_on boolean := false;
  v_cfg text;
  v_gap_limit int := least(greatest(coalesce(p_gap_limit, 20), 1), 50);
  v_list_limit int := least(greatest(coalesce(p_list_limit, 10), 1), 50);
  v_days int := least(greatest(coalesce(p_days, 30), 1), 365);
  v_top_gaps jsonb; v_never jsonb; v_most jsonb; v_trend jsonb;
BEGIN
  IF v_tenant IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'no_tenant'); END IF;

  -- Probe gate: feature flag ON and not paused.
  IF is_feature_enabled_internal(v_tenant, 'knowledge_coverage_probe') THEN
    SELECT (value #>> '{}') INTO v_cfg FROM platform_config WHERE key = 'knowledge.coverage_probe_paused';
    v_probe_on := coalesce(v_cfg, '') NOT IN ('true', '1', 't');
  END IF;

  -- (a) TOP-DEMAND GAPS. When the probe is on, reuse hybrid_match_knowledge per
  -- gap (its inquiry + embedding) and derive coverage_state from whether a CITED
  -- doc chunk sits near. When off, coverage_state='unknown' (no probe cost).
  IF v_probe_on THEN
    SELECT jsonb_agg(row_to_json(x)) INTO v_top_gaps FROM (
      SELECT g.id, g.category, g.severity_score, g.member_count, g.reviewer_summary, g.status,
             cov.nearest_cited_dist,
             CASE
               WHEN NOT coalesce(cov.has_cited, false) THEN 'none'
               WHEN cov.nearest_cited_dist IS NULL THEN 'weak'            -- cited doc matched lexically only
               WHEN cov.nearest_cited_dist <= 0.25 THEN 'covered'
               WHEN cov.nearest_cited_dist <= 0.35 THEN 'weak'
               ELSE 'none'
             END AS coverage_state
      FROM knowledge_gap_clusters g
      JOIN evidence_runs er ON er.id = g.representative_run_id AND er.tenant_id = v_tenant
      LEFT JOIN LATERAL (
        SELECT bool_or(coalesce(d.citation_count, 0) > 0) AS has_cited,
               min(h.distance) FILTER (WHERE coalesce(d.citation_count, 0) > 0) AS nearest_cited_dist
        FROM hybrid_match_knowledge(v_tenant, er.inquiry, NULL, er.inquiry_embedding, 20, NULL, NULL, 0.35) h
        JOIN knowledge_docs d ON d.id = h.doc_id
      ) cov ON true
      WHERE g.tenant_id = v_tenant AND g.status = 'open' AND er.inquiry_embedding IS NOT NULL
      ORDER BY g.severity_score DESC NULLS LAST, g.member_count DESC
      LIMIT v_gap_limit
    ) x;
  ELSE
    SELECT jsonb_agg(row_to_json(x)) INTO v_top_gaps FROM (
      SELECT g.id, g.category, g.severity_score, g.member_count, g.reviewer_summary, g.status,
             NULL::float AS nearest_cited_dist, 'unknown'::text AS coverage_state
      FROM knowledge_gap_clusters g
      WHERE g.tenant_id = v_tenant AND g.status = 'open'
      ORDER BY g.severity_score DESC NULLS LAST, g.member_count DESC
      LIMIT v_gap_limit
    ) x;
  END IF;

  -- (b) NEVER-CITED LIST (oldest-uncited first; 14-day grace so a fresh import
  -- isn't labeled dead weight). Total count comes from get_knowledge_overview
  -- client-side (never_cited is the common case → don't O(corpus)-count here).
  SELECT jsonb_agg(row_to_json(x)) INTO v_never FROM (
    SELECT d.id, d.title, d.updated_at, d.last_verified_at
    FROM knowledge_docs d
    WHERE d.tenant_id = v_tenant AND d.is_current AND coalesce(d.citation_count, 0) = 0
      AND d.created_at < now() - interval '14 days'
    ORDER BY d.updated_at ASC
    LIMIT v_list_limit
  ) x;

  -- (c) COVERAGE LEADERS (most-cited).
  SELECT jsonb_agg(row_to_json(x)) INTO v_most FROM (
    SELECT d.id, d.title, d.citation_count, d.last_cited_at
    FROM knowledge_docs d
    WHERE d.tenant_id = v_tenant AND d.is_current AND coalesce(d.citation_count, 0) > 0
    ORDER BY d.citation_count DESC
    LIMIT v_list_limit
  ) x;

  -- (d) CITATION TREND from the usage rollup.
  SELECT jsonb_agg(row_to_json(x)) INTO v_trend FROM (
    SELECT u.usage_date, sum(u.cited_count)::int AS citations, count(DISTINCT u.doc_id)::int AS docs_cited
    FROM knowledge_doc_usage_daily u
    WHERE u.tenant_id = v_tenant AND u.usage_date >= (now()::date - v_days)
    GROUP BY u.usage_date ORDER BY u.usage_date
  ) x;

  RETURN jsonb_build_object('ok', true, 'probe_enabled', v_probe_on,
    'top_gaps', coalesce(v_top_gaps, '[]'::jsonb),
    'never_cited', coalesce(v_never, '[]'::jsonb),
    'most_cited', coalesce(v_most, '[]'::jsonb),
    'trend', coalesce(v_trend, '[]'::jsonb));
END $function$;

CREATE OR REPLACE FUNCTION public.get_knowledge_doc_citation_stats(p_tenant_id uuid)
 RETURNS TABLE(doc_id uuid, citation_count bigint, avg_confidence numeric, accurate_count bigint, needs_improvement_count bigint)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_caller_tenant uuid;
  v_is_active     boolean;
  v_is_platform   boolean := is_platform_admin();
begin
  if not v_is_platform then
    select tenant_id, coalesce(is_active, true) into v_caller_tenant, v_is_active
    from profiles where user_id = auth.uid();
    if v_caller_tenant is distinct from p_tenant_id or not v_is_active then
      raise exception 'not a member of this tenant';
    end if;
  end if;

  return query
  with cited as (
    select
      (cit->>'ref')::uuid as c_doc_id,
      er.id as c_run_id
    from evidence_runs er,
      jsonb_array_elements(coalesce(er.steps, '[]'::jsonb)) as step,
      jsonb_array_elements(coalesce(step->'citations', '[]'::jsonb)) as cit
    where er.tenant_id = p_tenant_id
      and cit->>'system' = 'DreamTeam knowledge'
      and (cit->>'ref') ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
  ),
  conf as (
    select c.c_doc_id, avg(erd.confidence) as a_avg_confidence
    from cited c
    join evidence_run_decisions erd on erd.evidence_run_id = c.c_run_id and erd.tenant_id = p_tenant_id
    group by c.c_doc_id
  ),
  fb as (
    select c.c_doc_id,
      count(*) filter (where ef.verdict = 'accurate') as f_accurate_count,
      count(*) filter (where ef.verdict in ('needs_improvement', 'inaccurate')) as f_needs_improvement_count
    from cited c
    join evidence_feedback ef on ef.evidence_run_id = c.c_run_id and ef.tenant_id = p_tenant_id
    group by c.c_doc_id
  )
  select
    d.id,
    coalesce(ca.cnt, 0),
    conf.a_avg_confidence,
    coalesce(fb.f_accurate_count, 0),
    coalesce(fb.f_needs_improvement_count, 0)
  from knowledge_docs d
  left join (select c_doc_id, count(*) as cnt from cited group by c_doc_id) ca on ca.c_doc_id = d.id
  left join conf on conf.c_doc_id = d.id
  left join fb on fb.c_doc_id = d.id
  where d.tenant_id = p_tenant_id and d.is_current = true;
end;
$function$;

CREATE OR REPLACE FUNCTION public.get_knowledge_overview()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tenant uuid := public.auth_tenant_id(); v_out jsonb;
BEGIN
  IF v_tenant IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'no_tenant'); END IF;

  WITH d AS (
    SELECT * FROM knowledge_docs WHERE tenant_id = v_tenant AND is_current
  )
  SELECT jsonb_build_object(
    'ok', true,
    'total_docs',       (SELECT count(*) FROM d),
    'indexed_docs',     (SELECT count(*) FROM d WHERE embedded_count > 0),
    'keyword_only',     (SELECT count(*) FROM d WHERE embedded_count = 0),
    'stale_docs',       (SELECT count(*) FROM d WHERE last_verified_at IS NULL OR last_verified_at < now() - interval '90 days'),
    'role_shared',      (SELECT count(*) FROM d WHERE visibility = 'role'),
    'scoped',           (SELECT count(*) FROM d WHERE visibility = 'scoped'),
    'total_citations',  (SELECT coalesce(sum(citation_count), 0) FROM d),
    'cited_docs',       (SELECT count(*) FROM d WHERE citation_count > 0),
    'never_cited',      (SELECT count(*) FROM d WHERE citation_count = 0),
    'last_updated_at',  (SELECT max(updated_at) FROM d),
    'open_gaps',        (SELECT count(*) FROM knowledge_gap_clusters WHERE tenant_id = v_tenant AND status = 'open'),
    'pending_reviews',  (SELECT count(*) FROM de_improvements WHERE tenant_id = v_tenant AND status = 'review_pending')
                        + (SELECT count(*) FROM knowledge_revision_requests WHERE tenant_id = v_tenant AND status = 'pending_approval'),
    'top_cited', COALESCE((SELECT jsonb_agg(x) FROM (
        SELECT id, title, citation_count FROM d WHERE citation_count > 0
         ORDER BY citation_count DESC, updated_at DESC LIMIT 5) x), '[]'::jsonb),
    'recent', COALESCE((SELECT jsonb_agg(x) FROM (
        SELECT id, title, updated_at, embedded_count > 0 AS indexed FROM d
         ORDER BY updated_at DESC LIMIT 5) x), '[]'::jsonb)
  ) INTO v_out;
  RETURN v_out;
END $function$;

CREATE OR REPLACE FUNCTION public.get_kpi_metrics_for_de(p_de_id uuid)
 RETURNS json
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_tenant uuid; v_cats text[];
begin
  v_tenant := public.auth_tenant_id();
  if v_tenant is null then return '[]'::json; end if;
  if not exists (select 1 from digital_employees where id = p_de_id and tenant_id = v_tenant) then return '[]'::json; end if;
  if not public.can_access_de(p_de_id) then return '[]'::json; end if;
  select coalesce(array_agg(distinct resource_category), '{}') into v_cats
    from data_access_grants where tenant_id = v_tenant and subject_kind = 'de' and subject_id = p_de_id and resource_category is not null;
  return (
    select coalesce(json_agg(row_to_json(x) order by x.applicable desc, x.sort_order, x.label), '[]'::json) from (
      select metric_key, label, description, direction, unit, source, source_config, domains, sort_order,
             (tenant_id is not null) as is_custom,
             (domains is null or domains && v_cats) as applicable
        from kpi_metric_catalog
       where tenant_id is null or tenant_id = v_tenant
    ) x
  );
end $function$;

