CREATE OR REPLACE FUNCTION public.get_platform_tenant_overview()
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT is_platform_admin() THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;

  RETURN (
    SELECT coalesce(json_agg(row_to_json(x)), '[]'::json)
    FROM (
      SELECT
        t.id::text AS tenant_id,
        adm.full_name AS admin_name,
        adm.email AS admin_email,
        coalesce(de_cnt.n, 0) AS de_count,
        coalesce(usr_cnt.n, 0) AS user_count,
        act.last_activity::text AS last_activity
      FROM tenants t
      LEFT JOIN LATERAL (
        -- Most senior member: owner > admin > manager > anyone. Tenants
        -- operated purely via platform Remote Access have no members at
        -- all — those honestly show "no admin user".
        SELECT p.full_name, u.email::text AS email
        FROM profiles p
        JOIN auth.users u ON u.id = p.user_id
        WHERE p.tenant_id = t.id
        ORDER BY CASE p.role
          WHEN 'tenant_owner' THEN 0
          WHEN 'tenant_admin' THEN 1
          WHEN 'tenant_manager' THEN 2
          ELSE 3 END
        LIMIT 1
      ) adm ON true
      LEFT JOIN LATERAL (
        SELECT count(*) AS n FROM digital_employees d WHERE d.tenant_id = t.id
      ) de_cnt ON true
      LEFT JOIN LATERAL (
        SELECT count(*) AS n FROM profiles p WHERE p.tenant_id = t.id
      ) usr_cnt ON true
      LEFT JOIN LATERAL (
        SELECT max(m.created_at) AS last_activity FROM de_messages m WHERE m.tenant_id = t.id
      ) act ON true
    ) x
  );
END$function$;

CREATE OR REPLACE FUNCTION public.get_playbook_economics(p_definition_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tenant uuid; v_runs int; v_completed int; v_failed int;
  v_cost numeric; v_minutes numeric; v_value numeric;
  v_bl workforce_baselines;
begin
  select tenant_id into v_tenant from playbook_definitions where id = p_definition_id;
  if v_tenant is null then return jsonb_build_object('error', 'not_found'); end if;
  -- Prefix deleted.
  if not exists (
    select 1 from profiles p where p.user_id = auth.uid()
      and (p.layer = 'platform' or p.tenant_id = v_tenant)) then
    raise exception 'not authorized';
  end if;

  select count(*), count(*) filter (where status = 'completed'), count(*) filter (where status = 'failed')
    into v_runs, v_completed, v_failed
  from playbook_runs where definition_id = p_definition_id;

  select coalesce(sum(a.cost_used_cents), 0) into v_cost
  from agentic_step_runs a
  join playbook_runs r on r.id = a.playbook_run_id
  where r.definition_id = p_definition_id;

  select * into v_bl from workforce_baselines where tenant_id = v_tenant;
  -- mig 708 (§12.3): same rule as get_workforce_economics — the header of the
  -- 191 original called the dollars honest while the minutes on screen came
  -- from coalesce(action_minutes, 15), a number no tenant ever typed. Minutes
  -- now exist only when the tenant's own baseline does.
  v_minutes := case when v_bl.action_minutes is not null then v_completed * v_bl.action_minutes end;
  -- hourly rate implied by the tenant's own monthly FTE cost (160 h/month)
  v_value := case when v_minutes is not null and v_bl.avg_fte_cost_monthly_usd is not null and v_bl.avg_fte_cost_monthly_usd > 0
    then round((v_minutes / 60.0) * (v_bl.avg_fte_cost_monthly_usd / 160.0), 2) else null end;

  return jsonb_build_object(
    'runs', v_runs, 'completed', v_completed, 'failed', v_failed,
    'completion_pct', case when v_runs > 0 then round(100.0 * v_completed / v_runs, 1) else null end,
    'ai_cost_cents', round(v_cost, 1),
    'human_minutes_saved', case when v_minutes is not null then round(v_minutes, 0) end,
    'est_value_usd', v_value,
    'baseline_configured', v_bl.tenant_id is not null,
    'action_minutes_configured', v_bl.action_minutes is not null
  );
end; $function$;

CREATE OR REPLACE FUNCTION public.get_posting_draft(p_draft_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE d posting_drafts; v_lines jsonb; v_dr bigint; v_cr bigint;
BEGIN
  SELECT * INTO d FROM posting_drafts WHERE id = p_draft_id;
  IF d.id IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'not_found'); END IF;

  IF auth.role() IS NOT NULL AND auth.role() <> 'service_role' THEN
    IF NOT EXISTS (SELECT 1 FROM profiles p WHERE p.user_id = auth.uid() AND p.tenant_id = d.tenant_id) THEN
      RETURN jsonb_build_object('ok', false, 'error', 'not_found');
    END IF;
  END IF;

  SELECT coalesce(jsonb_agg(jsonb_build_object(
           'line', l.line_no, 'account', l.account, 'description', l.description,
           'debit',  CASE WHEN l.debit_cents  > 0 THEN (l.debit_cents /100.0) END,
           'credit', CASE WHEN l.credit_cents > 0 THEN (l.credit_cents/100.0) END,
           'from', l.evidence_table || ':' || l.evidence_id,
           'why', l.evidence_note) ORDER BY l.line_no), '[]'::jsonb),
         coalesce(sum(l.debit_cents),0), coalesce(sum(l.credit_cents),0)
    INTO v_lines, v_dr, v_cr
    FROM posting_draft_lines l WHERE l.draft_id = d.id;

  RETURN jsonb_build_object(
    'ok', true, 'id', d.id, 'kind', d.kind, 'title', d.title, 'rationale', d.rationale,
    'posting_date', d.posting_date, 'currency', d.currency, 'status', d.status,
    'lines', v_lines,
    'total_debit', (v_dr/100.0), 'total_credit', (v_cr/100.0),
    'balances', (v_dr = v_cr),
    'posted_ref', d.posted_ref, 'posted_at', d.posted_at,
    'payload', d.payload);
END $function$;

