CREATE OR REPLACE FUNCTION public.publish_adapter_template(p_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if coalesce(auth.role(), '') <> 'service_role' and not exists (
    select 1 from adapter_templates t
    join profiles p on p.tenant_id = t.tenant_id
    where t.id = p_id and t.scope = 'tenant' and p.user_id = auth.uid() and coalesce(p.is_active, true) = true
  ) then
    raise exception 'not a member of this template''s workspace';
  end if;
  update adapter_templates set status = 'published' where id = p_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.publish_onboarding_template(p_template_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_tpl     onboarding_templates;
  v_errors  text[];
  v_version integer;
  v_vid     uuid;
begin
  select * into v_tpl from onboarding_templates where id = p_template_id;
  if not found then
    return jsonb_build_object('error', 'template_not_found');
  end if;
  if not (v_tpl.tenant_id = auth_tenant_id() and auth_has_tenant_role(array['tenant_owner', 'tenant_admin'])) then
    raise exception 'only workspace owners/admins can publish an onboarding template';
  end if;

  v_errors := validate_onboarding_items(v_tpl.items, v_tpl.tenant_id);
  if array_length(v_errors, 1) is not null then
    return jsonb_build_object('errors', to_jsonb(v_errors));
  end if;

  v_version := v_tpl.version + 1;
  insert into onboarding_template_versions (template_id, tenant_id, version, name, description, items, published_by)
  values (v_tpl.id, v_tpl.tenant_id, v_version, v_tpl.name, v_tpl.description, v_tpl.items, auth.uid())
  returning id into v_vid;

  update onboarding_templates
    set version = v_version, status = 'published'
    where id = v_tpl.id;

  perform append_audit_event_internal(
    v_tpl.tenant_id, 'You', 'human',
    format('Onboarding template published — %s v%s (%s items)', v_tpl.name, v_version, jsonb_array_length(v_tpl.items)),
    'config_change',
    jsonb_build_object('kind', 'onboarding_template_publish', 'template_id', v_tpl.id,
                       'version_id', v_vid, 'version', v_version,
                       'item_count', jsonb_array_length(v_tpl.items)));

  return jsonb_build_object('version_id', v_vid, 'version', v_version);
end;
$function$;

CREATE OR REPLACE FUNCTION public.publish_platform_shelf_doc(p_doc_id uuid, p_title text, p_content text, p_source_change_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_old platform_knowledge_docs; v_new uuid; v_mig text;
BEGIN
  -- 342: the shelf is global. A tenant user editing it would rewrite the
  -- product guide that every OTHER tenant is answered from. Prefix deleted.
  IF NOT public.is_platform_admin() THEN
    RAISE EXCEPTION 'only platform administrators can publish to the shared shelf';
  END IF;
  SELECT * INTO v_old FROM platform_knowledge_docs WHERE id = p_doc_id AND is_current;
  IF v_old.id IS NULL THEN RAISE EXCEPTION 'shelf document not found or not current'; END IF;
  IF p_content IS NULL OR length(btrim(p_content)) = 0 THEN
    RAISE EXCEPTION 'refusing to publish an empty article';
  END IF;

  SELECT source_ref INTO v_mig FROM platform_kb_changes WHERE id = p_source_change_id;

  UPDATE platform_knowledge_docs SET is_current = false, updated_at = now() WHERE id = p_doc_id;

  INSERT INTO platform_knowledge_docs (
    title, content, topic, tags, authority, is_current, version, previous_version_id,
    source_doc_path, source_migration, last_verified_at, published_at)
  VALUES (
    coalesce(nullif(btrim(p_title), ''), v_old.title), p_content, v_old.topic, v_old.tags,
    v_old.authority, true, v_old.version + 1, v_old.id,
    v_old.source_doc_path, coalesce(v_mig, v_old.source_migration), now(), now())
  RETURNING id INTO v_new;

  -- Carry the chunks forward, flagged for re-embedding. Retrieval keeps working
  -- on the old vectors until the drain catches up rather than going blind.
  INSERT INTO platform_knowledge_chunks (doc_id, chunk_index, content, embedding, reembed_pending)
  SELECT v_new, c.chunk_index, c.content, c.embedding, true
    FROM platform_knowledge_chunks c WHERE c.doc_id = p_doc_id;

  IF p_source_change_id IS NOT NULL THEN
    UPDATE platform_kb_changes
       SET status = 'reviewed', reviewed_at = now(), reviewed_by = auth.uid()
     WHERE id = p_source_change_id;
  END IF;

  RETURN v_new;
END $function$;

CREATE OR REPLACE FUNCTION public.purge_connector_secret(p_connector_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tenant uuid;
begin
  select tenant_id into v_tenant from connectors where id = p_connector_id;
  if v_tenant is null then
    raise exception 'connector not found';
  end if;

  if coalesce(auth.role(), '') <> 'service_role'
     and not (v_tenant = auth_tenant_id() and auth_has_tenant_role(array['tenant_owner', 'tenant_admin', 'tenant_manager']))
  then
    raise exception 'only workspace owners/admins can remove a connector''s credential';
  end if;

  delete from connector_secrets where connector_id = p_connector_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.raise_ops_alert(p_kind text, p_message text, p_detail jsonb DEFAULT '{}'::jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  -- Dedup: one open alert per kind per hour keeps a 5-minute cron from
  -- flooding the table while the condition persists.
  IF EXISTS (
    SELECT 1 FROM ops_alerts
    WHERE kind = p_kind AND resolved_at IS NULL AND created_at > now() - interval '1 hour'
  ) THEN RETURN; END IF;
  INSERT INTO ops_alerts (kind, message, detail) VALUES (p_kind, p_message, coalesce(p_detail, '{}'::jsonb));
END$function$;

CREATE OR REPLACE FUNCTION public.raise_trust_widening_proposals(p_tenant_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  r         record;
  v_task    uuid;
  v_title   text;
  v_detail  text;
  v_lines   text;
  v_examined integer := 0;
  v_raised   integer := 0;
  v_tasks    uuid[] := '{}';
  v_done     uuid[] := '{}';
begin
  for r in select * from public.detect_trust_widening_patterns(p_tenant_id) loop
    v_examined := v_examined + 1;
    -- One open proposal per policy, even when two action groups map to the
    -- same ladder in a single sweep.
    if r.policy_id = any(v_done) then continue; end if;
    v_done := v_done || r.policy_id;
    v_task := gen_random_uuid();

    select string_agg(format('- %s, approved by %s. Receipt: %s',
             to_char((d->>'decided_at')::timestamptz, 'YYYY-MM-DD'),
             d->>'decided_by_name',
             coalesce(d->>'receipt', '(none)')), e'\n' order by d->>'decided_at')
      into v_lines
      from jsonb_array_elements(r.evidence->'pattern'->'decisions') d;

    v_title := left(format('Trust proposal — %s: "%s" approved and landed %s times; widen to level %s',
                 r.de_name, coalesce(r.action_label, r.action_key), r.n_approved, r.proposed_level), 300);

    v_detail :=
      format('A human said yes to the same thing %s times. %s asked to run "%s" and a person approved it '
             || 'on every occasion between %s and %s — each run was carried out and LANDED (receipts below), '
             || 'zero rejections, nothing rolled back, production work only (exam activity never counts).',
             r.n_approved, r.de_name, coalesce(r.action_label, r.action_key),
             to_char(r.first_decided, 'YYYY-MM-DD'), to_char(r.last_decided, 'YYYY-MM-DD'))
      || e'\n\n' || v_lines
      || e'\n\n'
      || format('Approving widens ONE dial through the existing trust machinery: "%s" moves from level %s to level %s '
             || '(proposed settings: %s). The evidence is re-verified at the moment of approval and the request is '
             || 'refused if it has gone stale; automatic demotion (a guardrail block or an evaluation regression) '
             || 'can take the widened level away at any time. Rejecting keeps everything gated exactly as today, '
             || 'and this proposal will NOT be re-raised until the full pattern re-accumulates from scratch after '
             || 'this decline. Raised automatically by the trust pattern detector — no human requested it.',
             r.policy_category, r.current_level, r.proposed_level,
             coalesce((r.evidence->'dial'->'proposed_settings')::text, '(defaults)'));

    insert into human_tasks (id, tenant_id, type, title, detail, source, related_table, related_id, status)
    values (v_task, r.tenant_id, 'trust_promotion', v_title, v_detail,
            'system', 'trust_policies', r.policy_id, 'pending');

    -- The linkage apply_trust_promotion resolves the task through. NULL
    -- requested_by = system-raised (no requester to self-approve; the
    -- probe's marker for holding it to the evidence bar).
    update trust_policies
       set pending_task_id = v_task,
           pending_evidence = r.evidence,
           requested_by = null,
           requested_at = now()
     where id = r.policy_id;

    perform public.append_audit_event_internal(
      r.tenant_id, 'Trust pattern detector', 'system',
      format('Trust-widening proposal raised — %s identical landed approvals of "%s" by %s; "%s" level %s -> %s awaits a human decision',
             r.n_approved, coalesce(r.action_label, r.action_key), r.de_name,
             r.policy_category, r.current_level, r.proposed_level),
      'config_change',
      jsonb_build_object('kind', 'trust_widening_proposed',
        'policy_id', r.policy_id, 'task_id', v_task, 'de_id', r.de_id,
        'action_key', r.action_key, 'n_approved', r.n_approved,
        'from_level', r.current_level, 'to_level', r.proposed_level,
        'evidence', r.evidence));

    -- The brief: mig 705's AFTER INSERT trigger wrote a provisional one
    -- BEFORE the policy linkage existed (same statement, earlier moment);
    -- refresh it now so the stored brief is right from birth. Advisory
    -- overlay — its failure must never cost the proposal.
    begin
      perform public.refresh_approval_briefs_internal(r.tenant_id);
    exception when others then
      null;
    end;

    v_raised := v_raised + 1;
    v_tasks := v_tasks || v_task;
  end loop;

  return jsonb_build_object('examined', v_examined, 'raised', v_raised,
                            'task_ids', to_jsonb(v_tasks));
end $function$;

CREATE OR REPLACE FUNCTION public.rate_limit_hit(p_bucket_key text, p_window_seconds integer, p_max_hits integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_window TIMESTAMPTZ := to_timestamp(floor(extract(epoch FROM now()) / p_window_seconds) * p_window_seconds);
  v_hits INTEGER;
BEGIN
  INSERT INTO rate_limit_counters (bucket_key, window_start, hits)
  VALUES (p_bucket_key, v_window, 1)
  ON CONFLICT (bucket_key, window_start)
  DO UPDATE SET hits = rate_limit_counters.hits + 1
  RETURNING hits INTO v_hits;

  -- Opportunistic GC: ~1% of calls sweep buckets older than an hour.
  IF random() < 0.01 THEN
    DELETE FROM rate_limit_counters WHERE window_start < now() - interval '1 hour';
  END IF;

  RETURN jsonb_build_object('allowed', v_hits <= p_max_hits, 'hits', v_hits);
END$function$;

CREATE OR REPLACE FUNCTION public.read_de_system(p_de_id uuid, p_system_key text, p_entity_ref text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  s de_connected_systems; v_tenant uuid; v_sql text; v_row jsonb;
  v_is_service boolean := coalesce(auth.role(),'') = 'service_role';
BEGIN
  SELECT tenant_id INTO v_tenant FROM digital_employees WHERE id = p_de_id;
  IF v_tenant IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'de_not_found'); END IF;
  IF NOT v_is_service AND v_tenant IS DISTINCT FROM public.auth_tenant_id() THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_tenant_member');
  END IF;

  SELECT * INTO s FROM de_connected_systems WHERE de_id = p_de_id AND system_key = p_system_key AND active;
  IF s.id IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'system_not_configured'); END IF;
  IF NOT s.can_read THEN RETURN jsonb_build_object('ok', false, 'error', 'read_not_allowed'); END IF;
  IF s.binding_kind <> 'internal_table' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'connector_read_pending_creds', 'system_key', p_system_key);
  END IF;
  IF NOT (s.source_table = ANY (ARRAY['customer_accounts','opportunities','account_activities','opportunity_activities','invoices','bills','payments','journal_entries'])) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'unsupported_source_table');
  END IF;

  v_sql := format(
    'SELECT to_jsonb(t) - (SELECT coalesce(array_agg(k),ARRAY[]::text[]) FROM (SELECT key AS k FROM jsonb_each(to_jsonb(t)) WHERE key <> ALL (SELECT jsonb_array_elements_text($3))) x) FROM %I t WHERE t.%I = $1::uuid AND t.tenant_id = $2',
    s.source_table, s.id_column);
  EXECUTE v_sql INTO v_row USING p_entity_ref, v_tenant, s.read_fields;
  IF v_row IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'record_not_found'); END IF;
  RETURN jsonb_build_object('ok', true, 'system_key', p_system_key, 'record', v_row);
END; $function$;

CREATE OR REPLACE FUNCTION public.reap_stale_computer_use_runtimes()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_n integer;
BEGIN
  UPDATE computer_use_runtimes SET active = false
    WHERE active AND (last_seen IS NULL OR last_seen < now() - interval '5 minutes');
  GET DIAGNOSTICS v_n = ROW_COUNT;
  RETURN v_n;
END; $function$;

CREATE OR REPLACE FUNCTION public.reap_stale_ingestion_items()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_n int;
BEGIN
  UPDATE knowledge_ingestion_items
     SET status = CASE WHEN attempts >= max_attempts THEN 'failed' ELSE 'queued' END,
         last_error = 'the worker stopped responding part-way through this item',
         error_kind = 'retryable', next_attempt_at = now(), updated_at = now()
   WHERE status = 'running' AND updated_at < now() - interval '30 minutes';
  GET DIAGNOSTICS v_n = ROW_COUNT;
  RETURN v_n;
END $function$;

CREATE OR REPLACE FUNCTION public.reap_stale_running_work(p_grace_minutes integer DEFAULT 45)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE n int;
BEGIN
  UPDATE de_work_items w
     SET status = 'queued', locked_at = NULL, locked_by = NULL,
         scheduled_for = now(), updated_at = now(),
         last_error = format('Released after %s minutes locked with no result — the run that claimed it never finished.',
                             p_grace_minutes)
   WHERE w.status = 'running'
     AND w.locked_at IS NOT NULL
     AND w.locked_at < now() - make_interval(mins => greatest(5, p_grace_minutes))
     AND tenant_is_operational(w.tenant_id);
  GET DIAGNOSTICS n = ROW_COUNT;
  RETURN jsonb_build_object('ok', true, 'released', n);
END $function$;

CREATE OR REPLACE FUNCTION public.recompute_de_trust_badge(p_tenant_id uuid, p_de_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_gated boolean := false;
  v_max   integer;
  v_badge text;
begin
  if p_tenant_id is null or p_de_id is null then
    return;
  end if;

  -- Records gate wins: any gating record pins the badge to the floor.
  select g.gated into v_gated from public.de_records_gate(p_tenant_id, p_de_id) g;

  if coalesce(v_gated, false) then
    v_badge := 'supervised';
  else
    -- The employee's earned ladder: MAX current level across ITS policies
    -- (workspace-wide policies have no owning employee and never move a badge).
    select max(tp.current_level) into v_max
      from trust_policies tp
     where tp.tenant_id = p_tenant_id and tp.de_id = p_de_id;
    v_badge := case coalesce(v_max, 0)
                 when 0 then 'supervised'
                 when 1 then 'established'
                 when 2 then 'trusted'
                 else 'autonomous'
               end;
  end if;

  update digital_employees
     set trust_level = v_badge
   where id = p_de_id and tenant_id = p_tenant_id
     and trust_level is distinct from v_badge;
exception when others then
  -- Read-model only: never abort the governance write that fired us.
  raise warning 'recompute_de_trust_badge(%, %) failed: %', p_tenant_id, p_de_id, sqlerrm;
end;
$function$;

CREATE OR REPLACE FUNCTION public.recompute_tenant_ancestry(p_tenant_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_current uuid := p_tenant_id;
  v_depth   integer := 0;
  v_parent  uuid;
  v_max_depth constant integer := 10;
begin
  delete from tenant_ancestry where tenant_id = p_tenant_id;

  loop
    insert into tenant_ancestry (tenant_id, ancestor_id, depth)
    values (p_tenant_id, v_current, v_depth)
    on conflict (tenant_id, ancestor_id) do nothing;

    select parent_tenant_id into v_parent from tenants where id = v_current;
    exit when v_parent is null;

    v_depth := v_depth + 1;
    if v_depth > v_max_depth then
      raise exception 'tenant hierarchy exceeds max depth (%) while walking ancestry for % -- a cycle likely slipped past the self-parent guard',
        v_max_depth, p_tenant_id;
    end if;

    v_current := v_parent;
  end loop;
end;
$function$;

CREATE OR REPLACE FUNCTION public.reconcile_blocked_goals(p_tenant_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  g record;
  v_resumed int := 0; v_finished int := 0; v_dropped int := 0; v_left int := 0; v_broken int := 0;
  v_orphaned int := 0; v_aged int := 0;
  -- How long a real, asked question may go unanswered before it is worth
  -- flagging. Deliberately generous: this is a nudge, never an override.
  c_aged_days constant int := 7;
BEGIN
  PERFORM set_config('app.allow_task_decision', 'on', true);  -- mig 487 sanctioned path

  FOR g IN
    SELECT o.id, o.tenant_id,
           count(w.id)                                             AS n_items,
           count(*) FILTER (WHERE w.status = 'waiting_human')       AS n_waiting,
           count(*) FILTER (WHERE w.status IN ('queued','running')) AS n_live,
           count(*) FILTER (WHERE w.status = 'done')                AS n_done,
           count(*) FILTER (WHERE w.status = 'failed')              AS n_failed,
           -- Of the waiting steps, how many have a REAL open question attached?
           count(*) FILTER (
             WHERE w.status = 'waiting_human'
               AND EXISTS (SELECT 1 FROM human_tasks ht
                            WHERE ht.status = 'pending'
                              AND ((ht.related_table = 'de_work_items' AND ht.related_id = w.id)
                                OR (ht.related_table = 'de_objectives'  AND ht.related_id = o.id)))
           ) AS n_waiting_asked,
           max(w.updated_at) FILTER (WHERE w.status = 'waiting_human') AS newest_wait
      FROM de_objectives o
      LEFT JOIN de_work_items w ON w.objective_id = o.id
     WHERE o.status = 'blocked'
       AND (p_tenant_id IS NULL OR o.tenant_id = p_tenant_id)
       AND tenant_is_operational(o.tenant_id)
     GROUP BY o.id, o.tenant_id
  LOOP
    -- ── ORPHANED WAIT: parked on a question that does not exist. ──────────
    IF g.n_waiting > 0 AND g.n_waiting_asked = 0 THEN
      UPDATE de_work_items
         SET status = 'queued', scheduled_for = now(), attempts = 0,
             last_error = null, updated_at = now()
       WHERE objective_id = g.id AND status = 'waiting_human';
      UPDATE de_objectives
         SET status = 'in_progress', next_wake_at = least(coalesce(next_wake_at, now()), now()),
             attention_flag = null, updated_at = now()
       WHERE id = g.id;
      v_orphaned := v_orphaned + 1;
      CONTINUE;
    END IF;

    -- ── AGED WAIT: a real question, unanswered too long. Flag, never resolve. ──
    IF g.n_waiting > 0 AND g.newest_wait < now() - make_interval(days => c_aged_days) THEN
      UPDATE de_objectives
         SET attention_flag = 'waiting_too_long',
             attention_since = coalesce(attention_since, g.newest_wait), updated_at = now()
       WHERE id = g.id;
      v_aged := v_aged + 1;
      v_left := v_left + 1;
      CONTINUE;
    END IF;

    IF g.n_waiting > 0 OR g.n_items = 0 THEN
      v_left := v_left + 1;
      CONTINUE;
    END IF;

    IF g.n_live > 0 THEN
      UPDATE de_objectives SET status = 'in_progress', updated_at = now() WHERE id = g.id;
      UPDATE human_tasks
         SET status = 'rejected', disposition = 'cancelled',
             decision_note = 'Closed automatically: nothing is blocking this goal any more — its remaining steps are queued and will run. No human ruling was made.',
             decided_at = now(), updated_at = now()
       WHERE related_table = 'de_objectives' AND related_id = g.id AND status = 'pending';
      v_resumed := v_resumed + 1;

    ELSIF g.n_failed > 0 THEN
      UPDATE de_objectives
         SET attention_flag = 'steps_failed',
             attention_since = coalesce(attention_since, now()), updated_at = now()
       WHERE id = g.id;
      v_broken := v_broken + 1;

    ELSIF g.n_done > 0 THEN
      UPDATE de_objectives SET status = 'achieved', updated_at = now() WHERE id = g.id;
      v_finished := v_finished + 1;

    ELSE
      UPDATE de_objectives SET status = 'abandoned', updated_at = now() WHERE id = g.id;
      v_dropped := v_dropped + 1;
    END IF;
  END LOOP;

  RETURN jsonb_build_object('ok', true, 'resumed', v_resumed, 'finished', v_finished,
    'dropped', v_dropped, 'broken', v_broken, 'genuinely_blocked', v_left,
    'orphaned_waits_requeued', v_orphaned, 'aged_waits_flagged', v_aged);
END;
$function$;

CREATE OR REPLACE FUNCTION public.reconcile_invoice_payments(p_tenant_id uuid, p_payments jsonb, p_window_days integer DEFAULT 7)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  pay jsonb; v_src text; v_ref text; v_amt bigint; v_on date;
  v_inv uuid; v_n int; v_how text;
  n_applied int := 0; n_dup int := 0; v_ambiguous jsonb := '[]'::jsonb; v_unmatched jsonb := '[]'::jsonb;
BEGIN
  IF jsonb_typeof(p_payments) <> 'array' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'payments must be an array');
  END IF;

  FOR pay IN SELECT * FROM jsonb_array_elements(p_payments) LOOP
    v_src := coalesce(pay->>'source', 'manual');
    v_ref := nullif(pay->>'external_ref', '');
    v_amt := (pay->>'amount_cents')::bigint;
    v_on  := (pay->>'paid_on')::date;
    v_inv := NULL; v_how := NULL;

    -- 1. The payment names its invoice. Certain: no guessing involved.
    IF nullif(pay->>'invoice_ref', '') IS NOT NULL THEN
      SELECT r.id INTO v_inv FROM renewal_invoices r
       WHERE r.tenant_id = p_tenant_id AND r.source_external_ref = pay->>'invoice_ref';
      IF v_inv IS NOT NULL THEN v_how := 'external_ref'; END IF;
    END IF;

    -- 2. Otherwise: exactly ONE open invoice of that amount, due near that date.
    --    "Exactly one" is the whole safety property — see the ambiguous branch.
    IF v_inv IS NULL THEN
      SELECT count(*), (array_agg(r.id))[1] INTO v_n, v_inv
        FROM renewal_invoices r
       WHERE r.tenant_id = p_tenant_id
         AND coalesce(r.status, '') NOT IN ('paid', 'void', 'cancelled')
         AND r.amount_cents = v_amt
         AND r.due_date BETWEEN v_on - make_interval(days => p_window_days)
                            AND v_on + make_interval(days => p_window_days);
      IF v_n = 1 THEN
        v_how := 'amount_and_date';
      ELSE
        -- More than one candidate, or none. Applying either would be a guess,
        -- and a guessed payment allocation is a wrong ledger that looks right.
        IF v_n > 1 THEN
          v_ambiguous := v_ambiguous || jsonb_build_object(
            'external_ref', v_ref, 'amount_cents', v_amt, 'paid_on', v_on, 'candidates', v_n);
        ELSE
          v_unmatched := v_unmatched || jsonb_build_object(
            'external_ref', v_ref, 'amount_cents', v_amt, 'paid_on', v_on);
        END IF;
        v_inv := NULL;
      END IF;
    END IF;

    CONTINUE WHEN v_inv IS NULL;

    INSERT INTO invoice_payments (tenant_id, invoice_id, amount_cents, paid_on, source, external_ref, matched_by)
    VALUES (p_tenant_id, v_inv, v_amt, v_on, v_src, v_ref, v_how)
    ON CONFLICT (tenant_id, source, external_ref) WHERE external_ref IS NOT NULL DO NOTHING;

    IF FOUND THEN n_applied := n_applied + 1; ELSE n_dup := n_dup + 1; END IF;
  END LOOP;

  -- Recompute the balance for every invoice that now has payments. Only these:
  -- an invoice nobody has reconciled must KEEP outstanding_cents NULL rather
  -- than acquire a number that merely restates its face value.
  UPDATE renewal_invoices r
     SET outstanding_cents = greatest(0, r.amount_cents - p.paid),
         payments_reconciled_at = now(),
         updated_at = now()
    FROM (SELECT invoice_id, sum(amount_cents) AS paid
            FROM invoice_payments WHERE tenant_id = p_tenant_id GROUP BY invoice_id) p
   WHERE r.id = p.invoice_id AND r.tenant_id = p_tenant_id;

  RETURN jsonb_build_object('ok', true, 'applied', n_applied, 'already_known', n_dup,
    'ambiguous', v_ambiguous, 'unmatched', v_unmatched);
END $function$;

CREATE OR REPLACE FUNCTION public.reconcile_tenant_feature(p_tenant_id uuid, p_feature_key text, p_enabled boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if p_feature_key in ('account_de', 'finance_de') then
    if p_enabled then
      perform provision_starter_de_internal(p_tenant_id, p_feature_key);
    else
      perform deprovision_starter_de_internal(p_tenant_id, p_feature_key);
    end if;
  elsif p_feature_key = 'knowledge_gap_detection' then
    if p_enabled then
      insert into knowledge_gap_policies (tenant_id, category, enabled)
      select p_tenant_id, null, true
      where not exists (select 1 from knowledge_gap_policies where tenant_id = p_tenant_id);
    end if;
  elsif p_feature_key = 'agentic_playbook_steps' then
    if p_enabled then
      -- Tenant-default budget envelope (column defaults: 15 iterations,
      -- 100k tokens, $5, 3 no-progress strikes) — soft-disable via
      -- policy.enabled or the flag gate, never destroy tenant config.
      insert into agentic_step_policies (tenant_id)
      select p_tenant_id
      where not exists (select 1 from agentic_step_policies where tenant_id = p_tenant_id);
    end if;
  end if;
end;
$function$;

CREATE OR REPLACE FUNCTION public.record_action_execution(p_tenant_id uuid, p_action_definition_id uuid, p_connector_id uuid, p_subject_kind text, p_subject_id uuid, p_mode text, p_params jsonb, p_decision text, p_destructive boolean, p_idempotent boolean, p_dedupe_key text, p_request_summary text, p_receipt text, p_result jsonb, p_task_title text, p_task_detail text, p_create_task boolean DEFAULT true, p_origin_kind text DEFAULT NULL::text, p_origin_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_task_id uuid;
  v_row_id  uuid;
  v_category text;
  v_label    text;
  v_ref      text;
begin
  if p_create_task and p_decision in ('human_gated_destructive', 'human_gated_trust') then
    insert into human_tasks (tenant_id, de_id, type, title, detail, source, related_table, related_id, status)
    values (
      p_tenant_id,
      -- The employee this approval is ABOUT. It was already in scope and was
      -- being thrown away: 0 of 105 action_approval tasks carried it, so the
      -- trust ladder could never attribute a single approval to anyone.
      case when p_subject_kind = 'de' then p_subject_id end,
      'action_approval',
      coalesce(p_task_title, 'Action awaiting approval'),
      coalesce(p_task_detail, ''), 'de', 'action_executions', null, 'pending'
    )
    returning id into v_task_id;
  end if;

  insert into action_executions (
    tenant_id, action_definition_id, connector_id, subject_kind, subject_id,
    mode, params, decision, destructive, idempotent, dedupe_key,
    request_summary, receipt, result, task_id, origin_kind, origin_id
  ) values (
    p_tenant_id, p_action_definition_id, p_connector_id, p_subject_kind, p_subject_id,
    p_mode, coalesce(p_params, '{}'::jsonb), p_decision, coalesce(p_destructive, true), coalesce(p_idempotent, false), p_dedupe_key,
    coalesce(p_request_summary, ''), p_receipt, p_result, v_task_id, p_origin_kind, p_origin_id
  )
  returning id into v_row_id;

  if v_task_id is not null then
    update human_tasks set related_id = v_row_id where id = v_task_id;
  end if;

  if p_mode = 'execute' and p_subject_id is not null then
    select category into v_category from action_definitions where id = p_action_definition_id;
    select label into v_label from action_definitions where id = p_action_definition_id;
    v_ref := coalesce(
      nullif(p_params->>'external_ref', ''),
      nullif(p_params->>'account_name', ''),
      nullif(p_params->>'account_ref', '')
    );
    if v_category is not null and v_ref is not null then
      perform record_de_experience(
        p_tenant_id, p_subject_kind, p_subject_id, v_category, v_ref,
        format('Considered action "%s" (%s)', coalesce(v_label, 'action'), coalesce(p_request_summary, '')),
        format('Decision: %s', p_decision),
        coalesce(p_receipt, case
          when p_decision in ('human_gated_destructive', 'human_gated_trust') then 'Awaiting human approval — not yet executed.'
          when p_decision = 'failed' then 'Attempted but failed — see result for detail.'
          else 'No receipt recorded.'
        end),
        null, v_row_id
      );
    end if;
  end if;

  return jsonb_build_object('id', v_row_id, 'task_id', v_task_id);
end;
$function$;

CREATE OR REPLACE FUNCTION public.record_action_rollback(p_original_execution_id uuid, p_receipt text, p_result jsonb DEFAULT NULL::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_orig action_executions;
  v_new  uuid;
begin
  select * into v_orig from action_executions where id = p_original_execution_id;
  if v_orig.id is null then raise exception 'original execution not found'; end if;

  insert into action_executions (
    tenant_id, action_definition_id, connector_id, subject_kind, subject_id,
    mode, params, decision, destructive, idempotent, dedupe_key,
    request_summary, receipt, result, rollback_of
  ) values (
    v_orig.tenant_id, v_orig.action_definition_id, v_orig.connector_id, v_orig.subject_kind, v_orig.subject_id,
    'execute', v_orig.params, 'executed_after_approval', v_orig.destructive, v_orig.idempotent, null,
    'Rollback of execution ' || p_original_execution_id::text, p_receipt, p_result, p_original_execution_id
  ) returning id into v_new;

  update action_executions
     set rolled_back_at = now(), rollback_receipt = p_receipt
   where id = p_original_execution_id;
  return v_new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.record_amendment_after_metrics(p_amendment_id uuid, p_after_metrics jsonb, p_replay_score_before numeric DEFAULT NULL::numeric, p_replay_score_after numeric DEFAULT NULL::numeric, p_confidence_delta numeric DEFAULT NULL::numeric, p_escalation_rate_delta numeric DEFAULT NULL::numeric)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tenant_id UUID := public.auth_tenant_id();
BEGIN
  IF v_tenant_id IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  UPDATE amendment_metrics
  SET after_metrics = p_after_metrics,
      replay_score_before = p_replay_score_before,
      replay_score_after = p_replay_score_after,
      confidence_delta = p_confidence_delta,
      escalation_rate_delta = p_escalation_rate_delta,
      adopted_at = now(),
      updated_at = now()
  WHERE amendment_id = p_amendment_id AND tenant_id = v_tenant_id;
  RETURN json_build_object('ok', true, 'adopted_at', now()::text);
END$function$;

CREATE OR REPLACE FUNCTION public.record_amendment_before_metrics(p_amendment_id uuid, p_entity_kind text, p_entity_id uuid, p_before_metrics jsonb)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tenant_id UUID := public.auth_tenant_id();
  v_metric_id UUID;
BEGIN
  IF v_tenant_id IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  INSERT INTO amendment_metrics (tenant_id, amendment_id, entity_kind, entity_id, before_metrics)
  VALUES (v_tenant_id, p_amendment_id, p_entity_kind, p_entity_id, p_before_metrics)
  ON CONFLICT DO NOTHING
  RETURNING metric_id INTO v_metric_id;
  RETURN json_build_object('ok', true, 'metric_id', v_metric_id);
END$function$;

CREATE OR REPLACE FUNCTION public.record_amendment_fitness(p_tenant_id uuid, p_amendment_id uuid, p_entity_kind text, p_entity_id uuid, p_before_metrics jsonb, p_after_metrics jsonb, p_score_before numeric, p_score_after numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  INSERT INTO amendment_metrics (
    tenant_id, amendment_id, entity_kind, entity_id,
    before_metrics, after_metrics, replay_score_before, replay_score_after, adopted_at
  )
  VALUES (
    p_tenant_id, p_amendment_id, p_entity_kind, p_entity_id,
    coalesce(p_before_metrics, '{}'::jsonb), p_after_metrics, p_score_before, p_score_after, now()
  )
  ON CONFLICT (amendment_id) DO UPDATE SET
    before_metrics      = coalesce(excluded.before_metrics, amendment_metrics.before_metrics),
    after_metrics       = excluded.after_metrics,
    replay_score_before = excluded.replay_score_before,
    replay_score_after  = excluded.replay_score_after,
    adopted_at          = now(),
    updated_at          = now();
  RETURN jsonb_build_object('ok', true);
END;
$function$;

CREATE OR REPLACE FUNCTION public.record_billable_outcome(p_tenant_id uuid, p_de_id uuid, p_conversation_id uuid, p_kind text, p_source text DEFAULT 'chat'::text, p_origin text DEFAULT 'production'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_price integer := 0; v_billable boolean := false; v_id uuid;
  v_status text := 'free'; v_settle_after timestamptz := null;
  v_origin text := case when p_origin = 'exercise' then 'exercise' else 'production' end;
  v_deferred boolean := (select value = 'true' from platform_config where key = 'metering_deferred_settlement_enabled');
  v_window numeric := coalesce((select value from platform_config where key = 'metering_settle_window_hours')::numeric, 72);
begin
  if p_kind not in ('resolution', 'escalation') then raise exception 'kind must be resolution|escalation'; end if;
  if p_conversation_id is null then return jsonb_build_object('recorded', false, 'reason', 'no_conversation'); end if;
  v_deferred := coalesce(v_deferred, false);

  if v_origin = 'exercise' then
    -- An exam outcome never bills, never pends, never settles — whatever kind.
    v_billable := false; v_price := 0; v_status := 'unbilled';
  elsif p_kind = 'resolution' then
    select coalesce((select price_per_resolution_cents from tenant_outcome_pricing where tenant_id = p_tenant_id), 99)
      into v_price;
    if exists (select 1 from billable_outcomes where conversation_id = p_conversation_id and kind = 'escalation') then
      v_billable := false; v_price := 0; v_status := 'unbilled';           -- escalated first: never bills
    elsif v_deferred then
      v_billable := false; v_status := 'pending'; v_settle_after := now() + make_interval(hours => v_window);
    else
      v_billable := true;  v_status := 'confirmed';                        -- LEGACY bill-on-answer (flag OFF)
    end if;
  else
    -- Escalation after a resolution: reverse it. MUST catch PENDING too, so the
    -- settle cron can never later confirm a conversation the human took over.
    update billable_outcomes set billable = false, unit_price_cents = 0, status = 'unbilled', settled_at = now()
     where conversation_id = p_conversation_id and kind = 'resolution' and status in ('pending','confirmed');
    v_billable := false; v_status := 'free';
  end if;

  insert into billable_outcomes (tenant_id, de_id, conversation_id, kind, source, billable, unit_price_cents, status, settle_after, settled_at, origin)
  values (p_tenant_id, p_de_id, p_conversation_id, p_kind,
          case when p_source in ('chat','widget','a2a','orchestrate') then p_source else 'chat' end,
          v_billable, v_price, v_status, v_settle_after,
          case when v_status in ('confirmed','free','unbilled') then now() else null end,
          v_origin)
  on conflict do nothing
  returning id into v_id;

  return jsonb_build_object('recorded', v_id is not null, 'billable', v_billable, 'unit_price_cents', v_price, 'status', v_status, 'origin', v_origin);
end;
$function$;

CREATE OR REPLACE FUNCTION public.record_de_experience(p_tenant_id uuid, p_subject_kind text, p_subject_id uuid, p_category text, p_external_ref text, p_what_happened text, p_decision_made text, p_outcome text, p_source_evidence_run_id uuid, p_source_action_execution_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_id uuid;
begin
  if not is_feature_enabled_internal(p_tenant_id, 'de_memory') then
    return null;
  end if;

  if p_subject_kind is null or p_subject_id is null or p_category is null or p_external_ref is null or p_external_ref = '' then
    return null; -- honest no-op: an experience fact needs a resolvable subject + category + external_ref
  end if;
  insert into de_experience (
    tenant_id, subject_kind, subject_id, category, external_ref,
    fact_summary, source_evidence_run_id, source_action_execution_id
  ) values (
    p_tenant_id, p_subject_kind, p_subject_id, p_category, p_external_ref,
    jsonb_build_object(
      'what_happened', p_what_happened,
      'decision_made', p_decision_made,
      'outcome', p_outcome
    ),
    p_source_evidence_run_id, p_source_action_execution_id
  )
  returning id into v_id;
  return v_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.record_de_spend(p_tenant_id uuid, p_de_id uuid, p_cents bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF coalesce(p_cents, 0) <= 0 THEN RETURN; END IF;
  INSERT INTO de_spend_ledger (tenant_id, de_id, period_kind, period_key, cents)
    VALUES (p_tenant_id, p_de_id, 'day', to_char(current_date, 'YYYY-MM-DD'), p_cents)
    ON CONFLICT (tenant_id, de_id, period_kind, period_key)
      DO UPDATE SET cents = de_spend_ledger.cents + excluded.cents, updated_at = now();
  INSERT INTO de_spend_ledger (tenant_id, de_id, period_kind, period_key, cents)
    VALUES (p_tenant_id, p_de_id, 'month', to_char(current_date, 'YYYY-MM'), p_cents)
    ON CONFLICT (tenant_id, de_id, period_kind, period_key)
      DO UPDATE SET cents = de_spend_ledger.cents + excluded.cents, updated_at = now();
END; $function$;

CREATE OR REPLACE FUNCTION public.record_de_token_usage(p_tenant_id uuid, p_de_id uuid, p_model_id text, p_input_tokens integer, p_output_tokens integer, p_origin text DEFAULT 'production'::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'record_de_token_usage is service-role only';
  end if;
  insert into de_token_usage (tenant_id, de_id, model_id, input_tokens, output_tokens, origin)
  values (p_tenant_id, p_de_id, p_model_id, coalesce(p_input_tokens, 0), coalesce(p_output_tokens, 0),
          case when p_origin = 'exercise' then 'exercise' else 'production' end);
end;
$function$;

CREATE OR REPLACE FUNCTION public.record_deliverable(p_de_id uuid, p_objective_id uuid, p_title text, p_kind text, p_content text, p_format text DEFAULT 'markdown'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tenant uuid; v_de_name text; v_id uuid; v_is_service boolean := coalesce(auth.role(),'') = 'service_role';
BEGIN
  SELECT tenant_id, coalesce(persona_name, name) INTO v_tenant, v_de_name FROM digital_employees WHERE id = p_de_id;
  IF v_tenant IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'de_not_found'); END IF;
  IF NOT v_is_service AND v_tenant IS DISTINCT FROM public.auth_tenant_id() THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_tenant_member');
  END IF;
  IF coalesce(p_title,'') = '' OR coalesce(p_content,'') = '' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'title_and_content_required');
  END IF;
  INSERT INTO de_deliverables (tenant_id, de_id, objective_id, title, kind, content, format)
  VALUES (v_tenant, p_de_id, p_objective_id, left(p_title,200),
          CASE WHEN p_kind IN ('report','summary','memo','analysis','review') THEN p_kind ELSE 'report' END,
          p_content, coalesce(nullif(p_format,''),'markdown'))
  RETURNING id INTO v_id;
  BEGIN PERFORM append_audit_event_internal(v_tenant, v_de_name, 'de',
    v_de_name || ' produced a ' || p_kind || ' for review — "' || left(p_title,120) || '"', 'playbook_step',
    jsonb_build_object('kind','deliverable_produced','deliverable_id',v_id,'objective_id',p_objective_id,'title',p_title));
  EXCEPTION WHEN OTHERS THEN NULL; END;
  RETURN jsonb_build_object('ok', true, 'deliverable_id', v_id);
END; $function$;

CREATE OR REPLACE FUNCTION public.record_dimension_state(p_session_id uuid, p_dimension text, p_state text, p_evidence text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  -- Separate from, and before, the membership check below: `NULL not in
  -- (...)` is NULL, not TRUE, so `if p_state not in (...)` silently never
  -- fires for a NULL state and it would otherwise reach the UPDATE, caught
  -- only by luck when the table CHECK rejects the resulting JSON null —
  -- with a raw check_violation instead of this function's own message.
  if p_state is null then
    raise exception 'record_dimension_state: state is required, got NULL';
  end if;

  if p_state not in ('heard', 'parked', 'skipped', 'not_heard') then
    raise exception 'record_dimension_state: unknown state % — must be one of heard, parked, skipped, not_heard', p_state;
  end if;

  if not exists (select 1 from public.discovery_dimensions where key = p_dimension and active) then
    raise exception 'record_dimension_state: unknown or inactive dimension %', p_dimension;
  end if;

  if not exists (select 1 from public.discovery_sessions where id = p_session_id) then
    raise exception 'record_dimension_state: unknown discovery session %', p_session_id;
  end if;

  -- 'parked' (ask again later, still owed a question) and 'skipped' (not
  -- relevant to this business, not owed one) are two different real
  -- conversations. Whatever state was asked for is the state stored — never
  -- normalised toward the other.
  update public.discovery_sessions
     set coverage = jsonb_set(
           coalesce(coverage, '{}'::jsonb),
           array[p_dimension],
           jsonb_build_object('state', p_state, 'evidence', p_evidence, 'recorded_at', now()),
           true
         ),
         updated_at = now()
   where id = p_session_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.record_domain_verification_attempt(p_tenant uuid, p_domain_id uuid, p_txt_records text[], p_dns_error text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_row     tenant_domains;
  v_matched boolean;
  v_seen    integer := coalesce(array_length(p_txt_records, 1), 0);
  v_reason  text;
BEGIN
  IF coalesce(auth.role(), '') <> 'service_role' THEN
    RAISE EXCEPTION 'domain verification runs from the backend only'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  SELECT * INTO v_row FROM tenant_domains
   WHERE id = p_domain_id AND tenant_id = p_tenant FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('status', 'unknown', 'reason', 'not_found');
  END IF;
  IF v_row.status = 'verified' THEN
    RETURN jsonb_build_object('status', 'verified', 'reason', 'already_verified',
                              'verified_at', v_row.verified_at);
  END IF;

  IF p_dns_error IS NOT NULL THEN
    v_reason := p_dns_error;                       -- nxdomain / dns_timeout / ...
  ELSE
    -- Resolvers hand back TXT values quoted, and a long value arrives as several
    -- character-strings the client must concatenate; the edge function joins
    -- them, we strip quotes and whitespace here. Comparison is on the full
    -- 256-bit token, so there is nothing to shorten and no prefix match.
    SELECT EXISTS (
      SELECT 1 FROM unnest(p_txt_records) AS r
       WHERE btrim(btrim(r), '"') = v_row.verification_token
    ) INTO v_matched;

    IF NOT v_matched THEN
      v_reason := CASE WHEN v_seen = 0 THEN 'no_txt_record' ELSE 'token_mismatch' END;
    END IF;
  END IF;

  IF v_reason IS NOT NULL THEN
    UPDATE tenant_domains
       SET last_error    = v_reason,
           failure_count = failure_count + 1,
           -- 'failed' is a UI signal ("this claim has been failing for a while,
           -- look at it"), NOT a lock: the next successful check clears it and
           -- claim_domain_verification_slot still accepts attempts. A status
           -- that traps a customer needing support to escape is a worse bug
           -- than a status that nags.
           status        = CASE WHEN failure_count + 1 >= 10 THEN 'failed' ELSE status END
     WHERE id = p_domain_id
    RETURNING * INTO v_row;

    RETURN jsonb_build_object('status', v_row.status, 'reason', v_reason,
                              'records_seen', v_seen);
  END IF;

  BEGIN
    UPDATE tenant_domains
       SET status = 'verified', verified_at = now(),
           last_error = NULL, failure_count = 0
     WHERE id = p_domain_id
    RETURNING * INTO v_row;
  EXCEPTION WHEN unique_violation THEN
    -- RULE 1 firing. The caller has just PROVED control of this domain, so
    -- naming the situation is safe and is the only way they can act on it
    -- (get the other workspace to release it, or contact support). We still do
    -- not name the other workspace.
    UPDATE tenant_domains
       SET last_error = 'domain_verified_by_another_workspace',
           failure_count = failure_count + 1
     WHERE id = p_domain_id;
    RETURN jsonb_build_object('status', 'pending',
                              'reason', 'domain_verified_by_another_workspace');
  END;

  PERFORM public.append_audit_event_internal(
    v_row.tenant_id, 'domain verification', 'system',
    format('Verified control of the email domain %s by DNS TXT record', v_row.domain),
    'config_change',
    jsonb_build_object('kind', 'tenant_domain_verified', 'domain', v_row.domain,
                       'domain_id', v_row.id, 'method', 'dns_txt'));

  RETURN jsonb_build_object('status', 'verified', 'reason', 'token_matched',
                            'verified_at', v_row.verified_at);
END $function$;

CREATE OR REPLACE FUNCTION public.record_improvement_replay(p_improvement_id uuid, p_replay jsonb, p_passed boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  update de_improvements
     set replay = p_replay,
         status = case when p_passed then 'replayed' else 'failed_replay' end,
         updated_at = now()
   where id = p_improvement_id and status in ('proposed','replayed','failed_replay');
  if not found then raise exception 'improvement not found or already in review/applied'; end if;
end;
$function$;

CREATE OR REPLACE FUNCTION public.record_inquiry_decision(p_tenant_id uuid, p_evidence_run_id uuid, p_connector_id uuid, p_external_ref text, p_source text, p_decision text, p_confidence integer, p_guardrail_rule_id uuid, p_trust_level integer, p_reasoning text, p_inquiry_title text, p_source_category text DEFAULT NULL::text, p_frustration_score integer DEFAULT NULL::integer, p_existing_human_task_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_task_id uuid; v_row_id uuid; v_run record;
  v_subject_kind text; v_subject_id uuid; v_ref text;
begin
  if p_decision = 'needs_review' then
    if p_existing_human_task_id is not null then
      v_task_id := p_existing_human_task_id;
    else
      insert into human_tasks (tenant_id, type, title, detail, source, related_table, related_id, status)
      values (p_tenant_id, 'inquiry_review',
        format('Review inquiry — %s', left(coalesce(p_inquiry_title, '(no subject)'), 120)),
        p_reasoning, 'de', 'evidence_runs', p_evidence_run_id, 'pending')
      returning id into v_task_id;
    end if;
  end if;

  insert into evidence_run_decisions (
    tenant_id, evidence_run_id, connector_id, external_ref, source, decision,
    confidence, guardrail_rule_id, trust_level, reasoning, human_task_id,
    source_category, frustration_score
  ) values (
    p_tenant_id, p_evidence_run_id, p_connector_id, p_external_ref, p_source, p_decision,
    p_confidence, p_guardrail_rule_id, p_trust_level, p_reasoning, v_task_id,
    p_source_category, p_frustration_score
  )
  on conflict (evidence_run_id) do update set
    decision = excluded.decision, confidence = excluded.confidence,
    guardrail_rule_id = excluded.guardrail_rule_id, trust_level = excluded.trust_level,
    reasoning = excluded.reasoning,
    human_task_id = coalesce(evidence_run_decisions.human_task_id, excluded.human_task_id),
    source_category = coalesce(excluded.source_category, evidence_run_decisions.source_category),
    frustration_score = coalesce(excluded.frustration_score, evidence_run_decisions.frustration_score)
  returning id into v_row_id;

  -- Experience door (migs 044/045). The specialist arm went with the role;
  -- a run is the work of a digital employee, full stop.
  select de_id, account_ref into v_run from evidence_runs where id = p_evidence_run_id;
  if v_run.de_id is not null then
    v_subject_kind := 'de'; v_subject_id := v_run.de_id;
  end if;
  v_ref := coalesce(nullif(p_external_ref, ''), nullif(v_run.account_ref, ''));

  if v_subject_id is not null and p_source_category is not null and v_ref is not null then
    perform record_de_experience(
      p_tenant_id, v_subject_kind, v_subject_id, p_source_category, v_ref,
      format('%s inquiry via %s (source: %s)', initcap(replace(p_source_category, '_', ' ')), coalesce(p_inquiry_title, '(untitled)'), p_source),
      format('Decision: %s%s', p_decision, case when p_confidence is not null then format(' (confidence %s%%)', p_confidence) else '' end),
      p_reasoning, p_evidence_run_id, null);
  end if;

  return jsonb_build_object('id', v_row_id, 'human_task_id', v_task_id);
end; $function$;

CREATE OR REPLACE FUNCTION public.record_knowledge_citations(p_tenant_id uuid, p_doc_ids uuid[])
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF p_tenant_id IS NULL OR p_doc_ids IS NULL OR array_length(p_doc_ids, 1) IS NULL THEN RETURN; END IF;

  INSERT INTO knowledge_doc_usage_daily (tenant_id, doc_id, usage_date, cited_count)
  SELECT d.tenant_id, d.id, current_date, 1
    FROM knowledge_docs d
   WHERE d.id = ANY (p_doc_ids) AND d.tenant_id = p_tenant_id
  ON CONFLICT (tenant_id, doc_id, usage_date)
  DO UPDATE SET cited_count = knowledge_doc_usage_daily.cited_count + 1;

  UPDATE knowledge_docs
     SET citation_count = coalesce(citation_count, 0) + 1, last_cited_at = now()
   WHERE id = ANY (p_doc_ids) AND tenant_id = p_tenant_id;
END $function$;

CREATE OR REPLACE FUNCTION public.record_knowledge_conflict(p_tenant_id uuid, p_chunk_a uuid, p_doc_a uuid, p_chunk_b uuid, p_doc_b uuid, p_relation text, p_distance real, p_signal jsonb DEFAULT '{}'::jsonb, p_confidence real DEFAULT NULL::real)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_lo_chunk uuid; v_lo_doc uuid; v_hi_chunk uuid; v_hi_doc uuid; v_id uuid;
BEGIN
  IF auth.uid() IS NOT NULL THEN RAISE EXCEPTION 'record_knowledge_conflict: service role only'; END IF;
  IF p_relation NOT IN ('near_duplicate', 'potential_conflict') THEN RAISE EXCEPTION 'bad relation'; END IF;
  -- Canonical ordering so a pair is stored once regardless of probe direction.
  IF p_chunk_a <= p_chunk_b THEN
    v_lo_chunk := p_chunk_a; v_lo_doc := p_doc_a; v_hi_chunk := p_chunk_b; v_hi_doc := p_doc_b;
  ELSE
    v_lo_chunk := p_chunk_b; v_lo_doc := p_doc_b; v_hi_chunk := p_chunk_a; v_hi_doc := p_doc_a;
  END IF;
  INSERT INTO knowledge_conflicts (tenant_id, chunk_a_id, doc_a_id, chunk_b_id, doc_b_id,
                                   relation, cosine_distance, signal, confidence)
  VALUES (p_tenant_id, v_lo_chunk, v_lo_doc, v_hi_chunk, v_hi_doc,
          p_relation, p_distance, coalesce(p_signal, '{}'), p_confidence)
  ON CONFLICT (tenant_id, chunk_a_id, chunk_b_id, relation) DO UPDATE
    SET cosine_distance = excluded.cosine_distance, signal = excluded.signal,
        confidence = excluded.confidence, updated_at = now()
    WHERE knowledge_conflicts.status = 'open'   -- never resurrect a resolved/dismissed pair
  RETURNING id INTO v_id;
  RETURN v_id;
END $function$;

CREATE OR REPLACE FUNCTION public.record_kpi_reading(p_de_id uuid, p_metric_key text, p_value numeric, p_as_of date DEFAULT CURRENT_DATE, p_note text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tenant uuid := auth_tenant_id(); v_id uuid;
BEGIN
  IF v_tenant IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  IF NOT EXISTS (SELECT 1 FROM digital_employees WHERE id = p_de_id AND tenant_id = v_tenant) THEN
    RAISE EXCEPTION 'de_not_found';
  END IF;
  -- DE scoping (mig 385/436). A manual reading is the fallback source for
  -- get_de_kpi_status, so an unscoped write here becomes another employee''s
  -- reported KPI. The de_not_found check above proves p_de_id is in this
  -- workspace, so no null case.
  IF NOT public.can_access_de(p_de_id) THEN
    RAISE EXCEPTION 'not_responsible_for_de: this employee is not in your reporting line';
  END IF;

  INSERT INTO de_kpi_readings (tenant_id, de_id, metric_key, value, as_of, recorded_by, note)
  VALUES (v_tenant, p_de_id, p_metric_key, p_value, coalesce(p_as_of, current_date), auth.uid(), p_note)
  RETURNING id INTO v_id;
  RETURN v_id;
END$function$;

CREATE OR REPLACE FUNCTION public.record_migration_applied(p_filename text, p_checksum text, p_applied_by text DEFAULT 'db-query.mjs'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_prev text; v_was text;
BEGIN
  IF p_filename IS NULL OR btrim(p_filename) = '' THEN RAISE EXCEPTION 'filename required'; END IF;
  IF p_checksum IS NULL OR btrim(p_checksum) = '' THEN RAISE EXCEPTION 'checksum required'; END IF;

  SELECT checksum, provenance INTO v_prev, v_was
    FROM schema_migrations WHERE filename = p_filename;

  INSERT INTO schema_migrations (filename, checksum, applied_at, applied_by, provenance)
  VALUES (p_filename, p_checksum, now(), p_applied_by, 'applied_by_runner')
  ON CONFLICT (filename) DO UPDATE
    SET checksum = excluded.checksum, applied_at = now(),
        applied_by = excluded.applied_by, provenance = 'applied_by_runner';

  RETURN jsonb_build_object(
    'ok', true,
    'filename', p_filename,
    -- Re-applying a file whose content changed is the dangerous case; say so.
    'reapplied', v_prev IS NOT NULL,
    'content_changed_since_last_apply', v_prev IS NOT NULL AND v_prev <> p_checksum,
    'previous_provenance', v_was);
END $function$;

CREATE OR REPLACE FUNCTION public.record_payment_promise(p_invoice_id uuid, p_promised_cents bigint, p_promised_on date, p_source text, p_evidence_note text, p_evidence_ref text DEFAULT NULL::text, p_grace_days integer DEFAULT 2, p_de_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_inv renewal_invoices; v_id uuid;
BEGIN
  SELECT * INTO v_inv FROM renewal_invoices WHERE id = p_invoice_id;
  IF v_inv.id IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'invoice_not_found'); END IF;

  IF coalesce(trim(p_evidence_note), '') = '' THEN
    RETURN jsonb_build_object('ok', false, 'error',
      'A promise needs to say where it came from. Record what the customer actually said and where.');
  END IF;

  -- You cannot take a promise against a balance you have never verified: the
  -- amount promised would be measured against a face value nobody checked.
  IF v_inv.outstanding_cents IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error',
      'This invoice has no verified balance yet, so a promise against it cannot be checked later. Reconcile payments first.');
  END IF;

  IF p_promised_on < current_date THEN
    RETURN jsonb_build_object('ok', false, 'error', 'A promise to pay in the past is not a promise.');
  END IF;
  IF p_promised_cents > v_inv.outstanding_cents THEN
    RETURN jsonb_build_object('ok', false, 'error',
      format('Promised %s but only %s is owed.',
             money_text(p_promised_cents, v_inv.source_currency),
             money_text(v_inv.outstanding_cents, v_inv.source_currency)));
  END IF;

  -- A new promise on the same invoice replaces the old one; a customer who
  -- re-promises has not made two commitments.
  UPDATE payment_promises SET status = 'superseded', settled_at = now(),
         settled_note = 'Replaced by a later promise on the same invoice.'
   WHERE invoice_id = p_invoice_id AND status = 'open';

  INSERT INTO payment_promises (tenant_id, invoice_id, promised_cents, promised_on, grace_days,
                                source, evidence_ref, evidence_note,
                                balance_at_promise_cents, recorded_by_de)
  VALUES (v_inv.tenant_id, p_invoice_id, p_promised_cents, p_promised_on, greatest(0, coalesce(p_grace_days,2)),
          p_source, p_evidence_ref, p_evidence_note, v_inv.outstanding_cents, p_de_id)
  RETURNING id INTO v_id;

  RETURN jsonb_build_object('ok', true, 'promise_id', v_id,
    'suppresses_chasing_until', p_promised_on + greatest(0, coalesce(p_grace_days,2)));
END $function$;

CREATE OR REPLACE FUNCTION public.record_platform_kb_change(p_source_kind text, p_source_ref text, p_title text, p_body text DEFAULT ''::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_id uuid; v_clean text; v_query tsquery;
BEGIN
  INSERT INTO platform_kb_changes (source_kind, source_ref, title, body)
  VALUES (coalesce(p_source_kind,'migration'), p_source_ref, p_title, coalesce(p_body,''))
  ON CONFLICT (source_kind, source_ref) DO UPDATE
    SET title = excluded.title, body = excluded.body
  RETURNING id INTO v_id;

  DELETE FROM platform_kb_change_impacts WHERE change_id = v_id;

  v_clean := regexp_replace(coalesce(p_title,'') || ' ' || left(coalesce(p_body,''), 3000), '[^a-zA-Z ]', ' ', 'g');
  v_clean := trim(regexp_replace(v_clean, '\s+', ' ', 'g'));
  IF v_clean = '' THEN RETURN v_id; END IF;

  -- Distinct stemmed lexemes, stopwords already removed by to_tsvector, OR'd.
  SELECT to_tsquery('english', string_agg(quote_literal(lexeme), ' | '))
    INTO v_query
    FROM (SELECT DISTINCT lexeme FROM unnest(to_tsvector('english', v_clean))
           WHERE length(lexeme) > 3 LIMIT 120) z;
  IF v_query IS NULL THEN RETURN v_id; END IF;

  INSERT INTO platform_kb_change_impacts (change_id, doc_id, rank)
  SELECT v_id, d.id, ts_rank(d.search_tsv, v_query)
    FROM platform_knowledge_docs d
   WHERE d.is_current AND d.published_at IS NOT NULL
     AND d.search_tsv @@ v_query
   ORDER BY 3 DESC
   LIMIT 5;

  RETURN v_id;
END $function$;

CREATE OR REPLACE FUNCTION public.record_platform_knowledge_citations(p_doc_ids uuid[])
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF p_doc_ids IS NULL OR array_length(p_doc_ids, 1) IS NULL THEN RETURN; END IF;
  INSERT INTO platform_knowledge_usage_daily (doc_id, usage_date, cited_count)
  SELECT d.id, current_date, 1
    FROM platform_knowledge_docs d
   WHERE d.id = ANY(p_doc_ids)
  ON CONFLICT (doc_id, usage_date)
  DO UPDATE SET cited_count = platform_knowledge_usage_daily.cited_count + 1;
END $function$;

CREATE OR REPLACE FUNCTION public.record_voice_message(p_tenant_id uuid, p_de_id uuid, p_call_id text, p_caller_name text, p_caller_phone text, p_message text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_msg_id  uuid;
  v_task_id uuid;
  v_who     text;
  v_actor   text;
begin
  -- Service role (or a migration context, where auth.role() is NULL) only.
  -- Written against auth.ROLE: anon shares a NULL uid with service_role
  -- (mig 330), so only the role string keeps anon out.
  if auth.role() is not null and auth.role() <> 'service_role' then
    raise exception 'not authorized';
  end if;

  if coalesce(btrim(p_message), '') = '' then
    raise exception 'a voice message needs message text';
  end if;

  insert into voice_messages (tenant_id, de_id, call_id, caller_name, caller_phone, message)
  values (p_tenant_id, p_de_id, nullif(btrim(coalesce(p_call_id, '')), ''),
          nullif(btrim(coalesce(p_caller_name, '')), ''),
          nullif(btrim(coalesce(p_caller_phone, '')), ''),
          btrim(p_message))
  returning id into v_msg_id;

  -- Name the caller honestly. "a caller" beats inventing one, and the phone
  -- number is the thing the human actually needs to act.
  v_who := coalesce(nullif(btrim(coalesce(p_caller_name, '')), ''), 'a caller');

  insert into human_tasks (
    tenant_id, de_id, type, source, status, title, detail,
    related_table, related_id
  ) values (
    p_tenant_id, p_de_id, 'escalation', 'de', 'pending',
    format('Call back %s%s', v_who,
           case when coalesce(btrim(coalesce(p_caller_phone, '')), '') <> ''
                then ' on ' || btrim(p_caller_phone) else '' end),
    format('Left on a phone call%s.%s%s',
           case when coalesce(btrim(coalesce(p_call_id, '')), '') <> ''
                then ' (call ' || btrim(p_call_id) || ')' else '' end,
           E'\n\n', btrim(p_message)),
    'voice_messages', v_msg_id
  ) returning id into v_task_id;

  -- The audit chain is where "we told a caller we would ring back" becomes a
  -- commitment on the record rather than a row in a table nobody reads.
  select coalesce(persona_name, name, 'Digital Employee') into v_actor
    from digital_employees where id = p_de_id and tenant_id = p_tenant_id;

  perform public.append_audit_event_internal(
    p_tenant_id,
    coalesce(v_actor, 'Digital Employee'), 'de',
    format('Took a message on a phone call and raised a callback task for %s', v_who),
    'escalated',
    jsonb_build_object(
      'kind', 'voice_message_taken', 'de_id', p_de_id, 'channel', 'voice',
      'voice_message_id', v_msg_id, 'human_task_id', v_task_id,
      'call_id', nullif(btrim(coalesce(p_call_id, '')), ''),
      'caller_phone_given', coalesce(btrim(coalesce(p_caller_phone, '')), '') <> ''
    )
  );

  return jsonb_build_object('ok', true, 'message_id', v_msg_id, 'task_id', v_task_id);
end $function$;

CREATE OR REPLACE FUNCTION public.redact_old_adjudications()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE v_n int;
BEGIN
  PERFORM set_config('app.allow_adjudication_redact', 'on', true);
  WITH upd AS (
    UPDATE guardrail_adjudications
       SET content_preview = NULL, question_preview = NULL, matched_text = NULL, rationale = NULL
     WHERE created_at < now() - interval '90 days'
       AND (content_preview IS NOT NULL OR question_preview IS NOT NULL
            OR matched_text IS NOT NULL OR rationale IS NOT NULL)
    RETURNING 1)
  SELECT count(*) INTO v_n FROM upd;
  DELETE FROM guardrail_adjudication_cache WHERE expires_at < now();
  RETURN v_n;
END $function$;

CREATE OR REPLACE FUNCTION public.redeem_platform_invite(p_invite_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_code text := btrim(coalesce(p_invite_code, ''));
  v_invite platform_invites;
  v_user uuid := auth.uid();
begin
  if v_user is null then
    raise exception 'not authenticated';
  end if;

  if v_code = '' then
    raise exception 'an invite code is required';
  end if;

  select * into v_invite from platform_invites where invite_code = v_code for update;
  if not found then
    raise exception 'invite code not recognized';
  end if;

  if v_invite.status = 'redeemed' then
    raise exception 'this invite has already been redeemed';
  end if;
  if v_invite.status = 'revoked' then
    raise exception 'this invite has been revoked';
  end if;

  if not exists (select 1 from profiles where user_id = v_user) then
    raise exception 'no profile found for this account -- sign up normally first, confirm your email, then redeem this invite';
  end if;

  update profiles
  set layer = 'platform', role = v_invite.role, tenant_id = null, updated_at = now()
  where user_id = v_user;

  update platform_invites
  set status = 'redeemed', redeemed_at = now(), redeemed_by = v_user
  where id = v_invite.id;

  return jsonb_build_object('ok', true, 'role', v_invite.role, 'layer', 'platform');
end;
$function$;

CREATE OR REPLACE FUNCTION public.refresh_approval_briefs_internal(p_tenant_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  r record;
  b jsonb;
  n int := 0;
begin
  for r in select * from public.pending_approval_briefables(p_tenant_id) loop
    b := public.compute_approval_brief(r.task_id);
    if b is null then continue; end if;
    insert into approval_briefs (task_id, tenant_id, risk, headline, evidence, computed_at, task_changed_at)
    values (r.task_id, p_tenant_id, b->>'risk', b->>'headline',
            coalesce(b->'evidence', '[]'::jsonb), now(), r.task_updated_at)
    on conflict (task_id) do update
      set risk = excluded.risk,
          headline = excluded.headline,
          evidence = excluded.evidence,
          computed_at = excluded.computed_at,
          task_changed_at = excluded.task_changed_at;
    n := n + 1;
  end loop;
  return n;
end $function$;

CREATE OR REPLACE FUNCTION public.register_computer_use_runtime(p_name text, p_endpoint text, p_kind text DEFAULT 'browser'::text, p_engine text DEFAULT 'browser_dom'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_id uuid;
BEGIN
  IF coalesce(auth.role(),'') <> 'service_role' THEN RAISE EXCEPTION 'register_computer_use_runtime is service-role only'; END IF;
  -- Upsert by name so a restarting worker keeps its identity.
  SELECT id INTO v_id FROM computer_use_runtimes WHERE name = p_name LIMIT 1;
  IF v_id IS NULL THEN
    INSERT INTO computer_use_runtimes (name, endpoint, kind, engine, active, last_seen)
      VALUES (p_name, p_endpoint, coalesce(p_kind,'browser'), coalesce(p_engine,'browser_dom'), true, now())
      RETURNING id INTO v_id;
  ELSE
    UPDATE computer_use_runtimes SET endpoint = p_endpoint, kind = coalesce(p_kind,'browser'),
      engine = coalesce(p_engine,'browser_dom'), active = true, last_seen = now() WHERE id = v_id;
  END IF;
  RETURN v_id;
END; $function$;

CREATE OR REPLACE FUNCTION public.reject_draft(p_draft_id uuid, p_reason text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id UUID;
  v_tenant UUID;
  v_rows INT;
BEGIN
  v_user_id := auth.uid();
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;
  v_tenant := public.auth_tenant_id();
  IF v_tenant IS NULL THEN
    RAISE EXCEPTION 'no_workspace: this account is not attached to a workspace';
  END IF;

  UPDATE draft_responses
     SET status = 'rejected', rejected_at = now(), rejected_by = v_user_id
   WHERE draft_id = p_draft_id AND tenant_id = v_tenant;
  GET DIAGNOSTICS v_rows = ROW_COUNT;
  IF v_rows = 0 THEN
    RAISE EXCEPTION 'draft_not_found: no such draft in this workspace';
  END IF;

  RETURN json_build_object('ok', true);
END;
$function$;

CREATE OR REPLACE FUNCTION public.reject_entity_amendment(p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin update workforce_entity_amendments set status = 'rejected' where id = p_id and status <> 'applied';
  return jsonb_build_object('ok', true); end; $function$;

CREATE OR REPLACE FUNCTION public.reject_improvement(p_improvement_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_tenant uuid;
begin
  select tenant_id into v_tenant from de_improvements where id = p_improvement_id;
  if v_tenant is null then raise exception 'improvement not found'; end if;
  -- Prefix deleted. Same trigger caller as apply_improvement.
  if not exists (
      select 1 from profiles p where p.user_id = auth.uid()
      and (p.layer = 'platform' or p.tenant_id = v_tenant)) then
    raise exception 'not authorized';
  end if;
  update de_improvements set status = 'rejected', updated_at = now()
   where id = p_improvement_id and status in ('review_pending','replayed');
  if not found then raise exception 'improvement not in a rejectable state'; end if;
end;
$function$;

CREATE OR REPLACE FUNCTION public.reject_knowledge_revision(p_request_id uuid, p_reason text DEFAULT ''::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user          uuid := auth.uid();
  v_caller_tenant uuid;
  v_is_active     boolean;
  v_req           record;
  v_actor_name    text;
begin
  select * into v_req from knowledge_revision_requests where id = p_request_id;
  if v_req.id is null then
    return jsonb_build_object('ok', false, 'error', 'request_not_found');
  end if;
  if v_req.status <> 'pending_approval' then
    return jsonb_build_object('ok', false, 'error', 'not_pending', 'status', v_req.status);
  end if;

  if v_user is not null then
    select tenant_id, coalesce(is_active, true) into v_caller_tenant, v_is_active from profiles where user_id = v_user;
    if v_caller_tenant is null or v_caller_tenant <> v_req.tenant_id then
      return jsonb_build_object('ok', false, 'error', 'not_tenant_member');
    end if;
    if not v_is_active then
      return jsonb_build_object('ok', false, 'error', 'not_tenant_member');
    end if;
  elsif coalesce(auth.role(), '') <> 'service_role' then
    return jsonb_build_object('ok', false, 'error', 'not_tenant_member');
  end if;

  select coalesce(full_name, 'A reviewer') into v_actor_name from profiles where user_id = v_user;
  v_actor_name := coalesce(v_actor_name, 'A reviewer');

  update knowledge_revision_requests
    set status = 'rejected', decided_by = v_user, decided_at = now()
    where id = p_request_id;

  perform append_audit_event(
    v_req.tenant_id, v_actor_name, case when v_user is null then 'system' else 'human' end,
    v_actor_name || ' rejected a proposed knowledge revision — "' || v_req.proposed_title || '"'
      || case when coalesce(p_reason, '') <> '' then ' (' || p_reason || ')' else '' end,
    'knowledge_revision',
    jsonb_build_object('kind', 'knowledge_revision_rejected', 'revision_request_id', p_request_id, 'reason', coalesce(p_reason, ''))
  );

  -- Additive: a rejected gap-triggered proposal reopens its cluster
  -- rather than dead-ending it — the underlying pattern may still be
  -- real even if this particular draft wasn't the right fix.
  update knowledge_gap_clusters
  set status = 'open', revision_request_id = null, updated_at = now()
  where revision_request_id = p_request_id and status = 'revision_requested';

  return jsonb_build_object('ok', true);
end;
$function$;

CREATE OR REPLACE FUNCTION public.reject_learned_behavior(p_cluster_id uuid, p_reason text DEFAULT ''::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user          uuid := auth.uid();
  v_caller_tenant uuid;
  v_is_active     boolean;
  v_cluster       record;
begin
  perform set_config('app.allow_task_decision', 'on', true);   -- mig 486: sanctioned decision path
  select * into v_cluster from de_learned_behavior_clusters where id = p_cluster_id;
  if v_cluster.id is null or v_cluster.status <> 'proposed' then
    return jsonb_build_object('ok', false, 'error', 'not_proposed');
  end if;

  select tenant_id, coalesce(is_active, true) into v_caller_tenant, v_is_active from profiles where user_id = v_user;
  if v_caller_tenant is distinct from v_cluster.tenant_id then
    return jsonb_build_object('ok', false, 'error', 'not_tenant_member');
  end if;
  if not v_is_active then
    return jsonb_build_object('ok', false, 'error', 'not_tenant_member');
  end if;

  -- DE scoping (mig 385/417). Rejecting suppresses a correction derived
  -- from this employee''s own failures and records the caller as the
  -- reviewer who decided it. de_id is NOT NULL here, so no null case.
  if not public.can_access_de(v_cluster.de_id) then
    return jsonb_build_object('ok', false, 'error', 'not_responsible_for_de');
  end if;
  if v_cluster.human_task_id is not null then
    update human_tasks set status = 'rejected', decided_by = v_user, decided_at = now() where id = v_cluster.human_task_id;
  end if;

  update de_learned_behavior_clusters
  set status = 'open', human_task_id = null, updated_at = now()
  where id = p_cluster_id;

  perform append_audit_event(
    v_cluster.tenant_id, coalesce((select full_name from profiles where user_id = v_user), 'A reviewer'), 'human',
    format('Rejected a proposed learned behavior (%s)%s', v_cluster.verdict_type,
      case when coalesce(p_reason, '') <> '' then ' (' || p_reason || ')' else '' end),
    'config_change',
    jsonb_build_object('kind', 'learned_behavior_rejected', 'cluster_id', p_cluster_id, 'reason', coalesce(p_reason, ''))
  );

  return jsonb_build_object('ok', true);
end;
$function$;

CREATE OR REPLACE FUNCTION public.reject_playbook_amendment(p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin IF NOT coalesce(public.can_admin_tenant_internal((SELECT tenant_id FROM public.playbook_amendments WHERE id = p_id)), false) THEN RAISE EXCEPTION 'not permitted'; END IF;
  update playbook_amendments set status = 'rejected' where id = p_id and status <> 'applied';
  return jsonb_build_object('ok', true);
end; $function$;

CREATE OR REPLACE FUNCTION public.reject_subtenant_request(p_request_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_req tenant_provisioning_requests;
begin
  if not resolve_platform_capability(auth.uid(), 'tenants.manage') then
    raise exception 'only a platform team member with tenant management access may reject a tenant provisioning request';
  end if;

  if coalesce(btrim(p_reason), '') = '' then
    raise exception 'a rejection reason is required';
  end if;

  select * into v_req from tenant_provisioning_requests where id = p_request_id for update;
  if not found then
    raise exception 'provisioning request not found';
  end if;
  if v_req.status <> 'pending' then
    raise exception 'this request has already been decided (status=%)', v_req.status;
  end if;

  update tenant_provisioning_requests
  set status = 'rejected', reviewed_by = auth.uid(), decided_at = now(), rejection_reason = btrim(p_reason)
  where id = p_request_id;

  if v_req.proposed_parent_tenant_id is not null and exists (
    select 1 from profiles where user_id = auth.uid() and tenant_id = v_req.proposed_parent_tenant_id
  ) then
    perform append_audit_event(
      v_req.proposed_parent_tenant_id, 'Platform admin', 'human',
      format('Sub-tenant request "%s" rejected — %s', v_req.proposed_name, btrim(p_reason)),
      'config_change',
      jsonb_build_object('kind', 'tenant_provisioning_rejected', 'request_id', p_request_id,
        'proposed_name', v_req.proposed_name, 'reason', btrim(p_reason), 'rejected_by', auth.uid(),
        'requested_by', v_req.requested_by_user_id)
    );
  end if;

  return jsonb_build_object('ok', true, 'rejected', true, 'reason', btrim(p_reason));
end;
$function$;

CREATE OR REPLACE FUNCTION public.remove_de_assignment(p_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tenant uuid := auth_tenant_id(); v_n int; v_de uuid; v_user uuid; v_rel text;
BEGIN
  IF v_tenant IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  IF NOT auth_has_tenant_role(ARRAY['tenant_owner', 'tenant_admin', 'tenant_manager']) THEN
    RAISE EXCEPTION 'insufficient_permission: assigning responsibility requires manager';
  END IF;
  DELETE FROM de_assignments WHERE id = p_id AND tenant_id = v_tenant
    RETURNING de_id, user_id, relation INTO v_de, v_user, v_rel;
  GET DIAGNOSTICS v_n = ROW_COUNT;

  -- Only audit a real removal (mig 429). A no-op delete is not an event;
  -- recording one would fill the trail with things that never happened.
  IF v_n > 0 THEN
    PERFORM append_audit_event(
      v_tenant,
      coalesce((SELECT full_name FROM profiles WHERE user_id = auth.uid()), 'A manager'),
      'human',
      format('Removed %s as %s for a digital employee',
             coalesce((SELECT full_name FROM profiles WHERE user_id = v_user), 'a teammate'),
             v_rel),
      'access_control',
      jsonb_build_object('kind', 'de_assignment_removed', 'de_id', v_de,
                         'user_id', v_user, 'relation', v_rel,
                         'assignment_id', p_id, 'removed_by', auth.uid()));
  END IF;

  RETURN v_n > 0;
END $function$;

CREATE OR REPLACE FUNCTION public.remove_group_member(p_group_id uuid, p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tenant uuid := auth_tenant_id(); v_my int; v_group int; v_name text; v_who text;
BEGIN
  IF v_tenant IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  SELECT name INTO v_name FROM knowledge_principal_groups WHERE id = p_group_id AND tenant_id = v_tenant;
  IF v_name IS NULL THEN RAISE EXCEPTION 'group_not_found'; END IF;

  v_my := public.knowledge_my_admin_level(NULL);
  IF v_my < 5 AND NOT is_platform_admin() THEN
    RAISE EXCEPTION 'insufficient_permission: managing groups requires knowledge manager';
  END IF;
  -- Removing is revoking, so the same ceiling applies in reverse: you cannot
  -- strip access you could not have granted.
  v_group := public.knowledge_group_max_level(p_group_id);
  IF v_group > v_my AND NOT is_platform_admin() THEN
    RAISE EXCEPTION 'insufficient_permission: "%" carries access above your level', v_name;
  END IF;

  SELECT coalesce(full_name, 'a teammate') INTO v_who FROM profiles WHERE user_id = p_user_id;
  DELETE FROM knowledge_principal_group_members WHERE group_id = p_group_id AND user_id = p_user_id;

  PERFORM append_audit_event(v_tenant, 'Knowledge', 'human',
    format('Removed %s from the group "%s"', coalesce(v_who,'someone'), v_name), 'access_control',
    jsonb_build_object('group_id', p_group_id, 'user_id', p_user_id));
  RETURN jsonb_build_object('ok', true);
END $function$;

CREATE OR REPLACE FUNCTION public.remove_team_member(p_target_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_caller_tenant uuid;
  v_caller_role text;
  v_target_tenant uuid;
  v_target_role text;
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;
  if auth.uid() = p_target_user_id then
    raise exception 'you cannot remove yourself here';
  end if;

  select tenant_id, role into v_caller_tenant, v_caller_role
  from profiles where user_id = auth.uid() and coalesce(is_active, true) = true;
  if v_caller_tenant is null or v_caller_role not in ('tenant_owner', 'tenant_admin') then
    raise exception 'only workspace owners/admins can remove a teammate';
  end if;

  select tenant_id, role into v_target_tenant, v_target_role
  from profiles where user_id = p_target_user_id;
  if v_target_tenant is null or v_target_tenant is distinct from v_caller_tenant then
    raise exception 'that person is not a member of this workspace';
  end if;
  if v_target_role = 'tenant_owner' then
    raise exception 'the workspace owner cannot be removed -- transfer ownership first';
  end if;

  update profiles set is_active = false, tenant_id = null where user_id = p_target_user_id;

  perform append_audit_event_internal(
    v_caller_tenant, 'You', 'human',
    'Team member removed',
    'config_change',
    jsonb_build_object('kind', 'team_member_removed', 'target_user_id', p_target_user_id)
  );

  return jsonb_build_object('ok', true);
end;
$function$;

CREATE OR REPLACE FUNCTION public.remove_tenant_domain(p_domain_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tenant uuid := public.auth_tenant_id();
  v_row    tenant_domains;
  v_actor  text;
BEGIN
  IF v_tenant IS NULL OR NOT public.can_admin_tenant_internal(v_tenant) THEN
    RAISE EXCEPTION 'only workspace owners and admins can remove a domain'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  -- Scoped by tenant_id in the DELETE itself, so an id belonging to another
  -- workspace deletes nothing and is reported as not found. The same wording
  -- for "wrong id" and "someone else's id" is intentional: it leaks nothing.
  DELETE FROM tenant_domains
   WHERE id = p_domain_id AND tenant_id = v_tenant
  RETURNING * INTO v_row;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'domain not found in this workspace';
  END IF;

  SELECT coalesce(full_name, 'a workspace admin') INTO v_actor
    FROM profiles WHERE user_id = auth.uid();
  PERFORM public.append_audit_event_internal(
    v_tenant, coalesce(v_actor, 'a workspace admin'), 'human',
    format('Removed the email domain %s (%s)', v_row.domain, v_row.status),
    'config_change',
    jsonb_build_object('kind', 'tenant_domain_removed', 'domain', v_row.domain,
                       'was_verified', v_row.status = 'verified'));

  RETURN jsonb_build_object('removed', true, 'domain', v_row.domain,
                            'was_verified', v_row.status = 'verified');
END $function$;

CREATE OR REPLACE FUNCTION public.remove_tenant_ip_allowlist_entry(p_entry_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tenant uuid;
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;

  select tenant_id into v_tenant from tenant_ip_allowlist_entries where id = p_entry_id;
  if v_tenant is null then
    raise exception 'IP range not found';
  end if;
  if not (
    is_platform_admin()
    or exists (
      select 1 from profiles p
      where p.user_id = auth.uid() and p.tenant_id = v_tenant
        and coalesce(p.is_active, true) = true
        and p.role in ('tenant_owner', 'tenant_admin')
    )
  ) then
    raise exception 'only workspace owners/admins can remove an IP range';
  end if;

  delete from tenant_ip_allowlist_entries where id = p_entry_id;

  perform append_audit_event_internal(
    v_tenant, 'You', 'human',
    'IP range removed from allowlist',
    'config_change',
    jsonb_build_object('kind', 'ip_allowlist_entry_removed', 'entry_id', p_entry_id)
  );

  return jsonb_build_object('ok', true);
end;
$function$;

CREATE OR REPLACE FUNCTION public.rename_knowledge_collection(p_id uuid, p_name text, p_description text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tenant uuid := auth_tenant_id();
BEGIN
  IF v_tenant IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  IF NOT EXISTS (SELECT 1 FROM knowledge_collections WHERE id = p_id AND tenant_id = v_tenant) THEN
    RAISE EXCEPTION 'not_found';
  END IF;
  IF knowledge_my_admin_level(p_id) < 5 AND NOT is_platform_admin() THEN
    RAISE EXCEPTION 'insufficient_permission: organising knowledge requires knowledge manager';
  END IF;
  UPDATE knowledge_collections
     SET name = coalesce(nullif(btrim(p_name),''), name),
         description = nullif(btrim(coalesce(p_description,'')),''),
         updated_at = now()
   WHERE id = p_id;
  RETURN jsonb_build_object('ok', true);
END $function$;

CREATE OR REPLACE FUNCTION public.rename_principal_group(p_group_id uuid, p_name text, p_description text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tenant uuid := auth_tenant_id();
BEGIN
  IF v_tenant IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  IF public.knowledge_my_admin_level(NULL) < 5 AND NOT is_platform_admin() THEN
    RAISE EXCEPTION 'insufficient_permission: managing groups requires knowledge manager';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM knowledge_principal_groups WHERE id = p_group_id AND tenant_id = v_tenant) THEN
    RAISE EXCEPTION 'group_not_found';
  END IF;

  UPDATE knowledge_principal_groups
     SET name = coalesce(nullif(btrim(p_name), ''), name),
         description = nullif(btrim(coalesce(p_description,'')), ''),
         updated_at = now()
   WHERE id = p_group_id;
  RETURN jsonb_build_object('ok', true);
END $function$;

CREATE OR REPLACE FUNCTION public.render_playbook_structure(p_steps jsonb)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select string_agg(
    s.ord || '. ' || coalesce(s.elem->>'label', s.elem->>'title', s.elem->>'key', 'step') ||
    case
      when s.elem->>'kind' = 'use_tool' then
        coalesce(' — ' || (s.elem->>'detail'), '')
        || coalesce(' [tool: ' || nullif(s.elem->>'tool', 'none') || ']', '')
      else case s.elem->>'key'
        when 'instruction'     then coalesce(' — ' || (s.elem->'params'->>'body_md'), '')
        when 'checklist'       then ' — checklist: ' || coalesce((select string_agg(i.value #>> '{}', '; ')
                                                                  from jsonb_array_elements(s.elem->'params'->'items') i), '')
        when 'decision'        then ' — DECISION: if ' || coalesce(s.elem->'params'->>'on','(prior step)') || ' '
                                      || coalesce(s.elem->'params'->>'operator','') || ' ' || coalesce(s.elem->'params'->>'value','')
                                      || ' then ' || coalesce(jsonb_array_length(s.elem->'then_steps')::text,'0') || ' step(s), else '
                                      || coalesce(jsonb_array_length(s.elem->'else_steps')::text,'0')
        when 'human_approval'  then ' — GATE: pause here for human approval before continuing'
        when 'guardrail_check' then ' — GUARDRAIL CHECK: ' || coalesce(s.elem->'params'->>'check','')
        when 'consult_specialist' then ' — CONSULT a specialist: ' || coalesce(s.elem->'params'->>'question_template','')
        when 'check_knowledge' then ' — CHECK KNOWLEDGE for: ' || coalesce(s.elem->'params'->>'query_template','')
        when 'agentic_step'    then ' — JUDGMENT STEP (use tools to): ' || coalesce(s.elem->'params'->>'instructions', s.elem->'params'->>'goal_template','')
        when 'custom_step'     then ' — JUDGMENT STEP (use tools to): ' || coalesce(s.elem->'params'->>'instructions', s.elem->'params'->>'goal_template','')
        when 'connector_action' then ' — ACTION: ' || coalesce(
                                        s.elem->'params'->>'action_key',
                                        nullif((s.elem->'params'->>'provider') || '.' || (s.elem->'params'->>'op'), '.'),
                                        nullif((s.elem->'params'->>'category') || '.' || (s.elem->'params'->>'op'), '.'),
                                        'connector action') || ' (routed through the approval/guardrail gates)'
        when 'generate_invoice' then ' — ACTION: generate an invoice (gated for approval)'
        when 'update_record'   then ' — ACTION: update a record (gated)'
        when 'wait'            then ' — WAIT ' || coalesce(s.elem->'params'->>'duration_minutes','?') || ' minutes, then resume'
        when 'complete'        then ' — (procedure ends here)'
        else ''
      end
    end, E'\n' order by s.ord)
  from jsonb_array_elements(p_steps) with ordinality as s(elem, ord);
$function$;

CREATE OR REPLACE FUNCTION public.report_edge_error(p_function text, p_message text, p_detail jsonb DEFAULT '{}'::jsonb, p_tenant uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_key text;
BEGIN
  IF p_function IS NULL OR btrim(p_function) = '' THEN RETURN; END IF;

  -- One alert per function per distinct message per hour. A crash loop should
  -- produce one row you can act on, not ten thousand you cannot.
  v_key := p_function || ':' || left(coalesce(p_message, ''), 200);

  INSERT INTO ops_alerts (kind, message, detail, created_at)
  SELECT 'edge_function_error',
         format('%s failed: %s', p_function, left(coalesce(p_message, 'unknown'), 300)),
         coalesce(p_detail, '{}'::jsonb)
           || jsonb_build_object('function', p_function, 'tenant_id', p_tenant, 'dedupe_key', v_key),
         now()
   WHERE NOT EXISTS (
     SELECT 1 FROM ops_alerts
      WHERE kind = 'edge_function_error'
        AND detail->>'dedupe_key' = v_key
        AND created_at > now() - interval '1 hour'
        AND resolved_at IS NULL);
END $function$;

CREATE OR REPLACE FUNCTION public.request_de_task(p_from_de_id uuid, p_to_de_id uuid, p_title text, p_context text DEFAULT NULL::text, p_expected_output text DEFAULT NULL::text, p_urgency text DEFAULT 'normal'::text, p_due_date date DEFAULT NULL::date, p_related_table text DEFAULT NULL::text, p_related_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tenant uuid; v_to_tenant uuid; v_from_name text; v_to_name text;
  v_existing uuid; v_open_pair int; v_req uuid; v_obj uuid; v_title text;
  v_is_service boolean := coalesce(auth.role(),'') = 'service_role';
BEGIN
  v_title := left(btrim(coalesce(p_title,'')), 200);
  IF v_title = '' THEN RETURN jsonb_build_object('ok', false, 'error', 'title_required'); END IF;
  IF p_to_de_id IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'to_de_required'); END IF;
  IF p_from_de_id IS NOT NULL AND p_from_de_id = p_to_de_id THEN
    RETURN jsonb_build_object('ok', false, 'error', 'no_self_assignment');
  END IF;

  SELECT tenant_id, coalesce(persona_name, name) INTO v_to_tenant, v_to_name FROM digital_employees WHERE id = p_to_de_id;
  IF v_to_tenant IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'target_not_found'); END IF;
  v_tenant := v_to_tenant;
  IF NOT v_is_service AND v_tenant IS DISTINCT FROM public.auth_tenant_id() THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_tenant_member');
  END IF;

  -- (B) HUMAN path is admin-only.
  IF p_from_de_id IS NULL AND NOT v_is_service
     AND NOT public.auth_has_tenant_role(array['tenant_owner','tenant_admin']) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_permitted',
      'detail', 'Only workspace owners/admins can assign tasks to an employee.');
  END IF;

  -- (C) SINGLE-HOP backstop: a task opened FROM a de_task case cannot re-delegate.
  IF p_from_de_id IS NOT NULL AND p_related_table = 'de_objectives' AND p_related_id IS NOT NULL
     AND EXISTS (SELECT 1 FROM de_objectives o WHERE o.id = p_related_id AND o.entity_kind = 'de_task') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'chain_too_deep',
      'detail', 'A delegated task cannot itself be delegated onward.');
  END IF;

  -- (D — docs/31 decision #2 scope containment, fix-pass 2026-07-28) consult
  -- is the specialist interface; delegation is DE-to-DE work handoff. The
  -- specialist auto-grant (this migration) must not make specialists
  -- task-assignment targets, so a DE-requested task refuses them here even
  -- though a grant row exists. Mirrors the de-work delegate-tool exclusion.
  IF p_from_de_id IS NOT NULL AND EXISTS (
    SELECT 1 FROM digital_employees s WHERE s.id = p_to_de_id AND FALSE) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_permitted',
      'detail', 'Specialists are consulted, not delegated to - use a consultation instead.');
  END IF;

  IF p_from_de_id IS NOT NULL THEN
    SELECT coalesce(persona_name, name) INTO v_from_name FROM digital_employees WHERE id = p_from_de_id AND tenant_id = v_tenant;
    IF v_from_name IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'requester_not_in_tenant'); END IF;
    IF NOT EXISTS (SELECT 1 FROM de_consultation_grants g
      WHERE g.tenant_id = v_tenant AND g.requester_de_id = p_from_de_id AND g.target_de_id = p_to_de_id AND g.active) THEN
      RETURN jsonb_build_object('ok', false, 'error', 'not_permitted',
        'detail', 'No active collaboration grant from the requesting employee to the target. A tenant admin configures these.');
    END IF;
    IF EXISTS (SELECT 1 FROM de_task_requests r
      WHERE r.tenant_id = v_tenant AND r.from_de_id = p_to_de_id AND r.to_de_id = p_from_de_id
        AND lower(r.title) = lower(v_title) AND r.status IN ('requested','accepted','in_progress')) THEN
      RETURN jsonb_build_object('ok', false, 'error', 'circular', 'detail', 'A reverse task on the same subject is already open.');
    END IF;
    SELECT count(*) INTO v_open_pair FROM de_task_requests r
      WHERE r.tenant_id = v_tenant AND r.from_de_id = p_from_de_id AND r.to_de_id = p_to_de_id
        AND r.status IN ('requested','accepted','in_progress');
    IF v_open_pair >= 20 THEN
      RETURN jsonb_build_object('ok', false, 'error', 'too_many_open', 'detail', 'Too many open tasks to this employee already.');
    END IF;
  ELSE
    v_from_name := 'You';
  END IF;

  SELECT id INTO v_existing FROM de_task_requests r
    WHERE r.tenant_id = v_tenant AND r.to_de_id = p_to_de_id
      AND coalesce(r.from_de_id::text,'human') = coalesce(p_from_de_id::text,'human')
      AND lower(r.title) = lower(v_title) AND r.status IN ('requested','accepted','in_progress')
    ORDER BY r.created_at DESC LIMIT 1;
  IF v_existing IS NOT NULL THEN
    RETURN jsonb_build_object('ok', true, 'deduped', true, 'request_id', v_existing);
  END IF;

  INSERT INTO de_task_requests (tenant_id, from_de_id, to_de_id, title, context, expected_output, urgency, due_date, related_table, related_id, created_by)
  VALUES (v_tenant, p_from_de_id, p_to_de_id, v_title, left(p_context, 4000), left(p_expected_output, 2000),
          CASE WHEN p_urgency IN ('low','normal','high','urgent') THEN p_urgency ELSE 'normal' END,
          p_due_date, p_related_table, p_related_id, auth.uid())
  RETURNING id INTO v_req;

  INSERT INTO de_objectives (tenant_id, de_id, title, description, entity_kind, entity_ref, status, priority, due_at, plan)
  VALUES (v_tenant, p_to_de_id, left('Task from ' || coalesce(v_from_name,'a colleague') || ': ' || v_title, 200),
          'Assigned by ' || coalesce(v_from_name,'a colleague') || '. ' || coalesce(left(p_context,1000),'')
            || coalesce(E'\nExpected: ' || left(p_expected_output,500), ''),
          'de_task', v_req::text, 'open',
          CASE p_urgency WHEN 'urgent' THEN 5 WHEN 'high' THEN 30 ELSE 60 END,
          p_due_date::timestamptz,
          jsonb_build_object('source','cross_de_task','request_id',v_req,'from_de_id',p_from_de_id,'urgency',p_urgency))
  RETURNING id INTO v_obj;
  UPDATE de_task_requests SET objective_id = v_obj WHERE id = v_req;

  BEGIN PERFORM append_audit_event_internal(v_tenant, coalesce(v_from_name,'You'), CASE WHEN p_from_de_id IS NULL THEN 'human' ELSE 'de' END,
    coalesce(v_from_name,'You') || ' assigned a task to ' || v_to_name || ' — "' || v_title || '"', 'de_consultation',
    jsonb_build_object('kind','de_task_assigned','request_id',v_req,'from_de_id',p_from_de_id,'to_de_id',p_to_de_id,'objective_id',v_obj));
  EXCEPTION WHEN OTHERS THEN NULL; END;

  RETURN jsonb_build_object('ok', true, 'request_id', v_req, 'objective_id', v_obj);
END; $function$;

CREATE OR REPLACE FUNCTION public.request_subtenant(p_parent_tenant_id uuid, p_name text, p_industry text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user       uuid := auth.uid();
  v_role       text;
  v_caller_tenant uuid;
  v_is_active  boolean;
  v_parent     tenants;
  v_is_platform boolean := resolve_platform_capability(auth.uid(), 'tenants.provision');
  v_slug       text;
  v_base_slug  text;
  v_suffix     int := 0;
  v_tenant     tenants;
  v_request_id uuid;
  v_demo_tenant_id constant uuid := 'a0000000-0000-0000-0000-000000000001';
begin
  if v_user is null then
    raise exception 'not authenticated';
  end if;

  if coalesce(btrim(p_name), '') = '' then
    raise exception 'proposed tenant name is required';
  end if;

  if p_parent_tenant_id is null then
    if not v_is_platform then
      raise exception 'only a platform admin with tenant-provisioning access may create a new top-level tenant';
    end if;
  else
    if p_parent_tenant_id = v_demo_tenant_id then
      raise exception 'the demo tenant cannot be used as a parent tenant';
    end if;

    select * into v_parent from tenants where id = p_parent_tenant_id;
    if not found then
      raise exception 'parent tenant not found';
    end if;

    select role, tenant_id, coalesce(is_active, true) into v_role, v_caller_tenant, v_is_active from profiles where user_id = v_user;

    if not v_is_platform then
      if v_caller_tenant is distinct from p_parent_tenant_id or v_role not in ('tenant_owner', 'tenant_admin') then
        raise exception 'only an owner or admin of the parent tenant may request a sub-tenant';
      end if;
      if not v_is_active then
        raise exception 'account is deactivated';
      end if;
    end if;
  end if;

  if v_is_platform or (p_parent_tenant_id is not null and v_parent.allow_self_serve_subtenants) then
    v_base_slug := lower(regexp_replace(btrim(p_name), '[^a-zA-Z0-9]+', '-', 'g'));
    v_base_slug := trim(both '-' from v_base_slug);
    if coalesce(v_base_slug, '') = '' then
      v_base_slug := 'org';
    end if;
    v_slug := v_base_slug;
    while exists (select 1 from tenants where slug = v_slug) loop
      v_suffix := v_suffix + 1;
      v_slug := v_base_slug || '-' || v_suffix::text;
    end loop;

    insert into tenants (name, slug, industry, plan, status, settings, parent_tenant_id, trial_ends_at)
    values (btrim(p_name), v_slug, nullif(btrim(coalesce(p_industry, '')), ''), 'starter', 'trial', '{}'::jsonb, p_parent_tenant_id, now() + interval '14 days')
    returning * into v_tenant;

    -- mig 732: this branch is the third tenant-creation path and the only one
    -- that never reaches provision_tenant_baseline_internal. Until now the
    -- platform_admin connector arrived here purely as a side effect of the
    -- AFTER INSERT trigger that hires the Onboarding Architect (mig 730 moved
    -- the row into a shared helper but the trigger is still what calls it on
    -- this path). Retiring that employee — a one-row feature_registry update —
    -- would otherwise leave a console-provisioned workspace with a Workspace
    -- Assistant and no way to administer it. Idempotent, and a no-op while the
    -- trigger is still doing it: the AFTER INSERT triggers have already fired
    -- by the time this statement runs, so the helper finds the existing row.
    perform provision_platform_admin_connector_internal(v_tenant.id);

    insert into tenant_provisioning_requests
      (requested_by_user_id, proposed_parent_tenant_id, proposed_name, proposed_industry, status, reviewed_by, decided_at, created_tenant_id)
    values
      (v_user, p_parent_tenant_id, btrim(p_name), p_industry, 'approved', v_user, now(), v_tenant.id)
    returning id into v_request_id;

    return jsonb_build_object('ok', true, 'path', 'self_serve', 'tenant_id', v_tenant.id, 'slug', v_tenant.slug, 'request_id', v_request_id);
  end if;

  insert into tenant_provisioning_requests
    (requested_by_user_id, proposed_parent_tenant_id, proposed_name, proposed_industry, status)
  values
    (v_user, p_parent_tenant_id, btrim(p_name), p_industry, 'pending')
  returning id into v_request_id;

  return jsonb_build_object('ok', true, 'path', 'pending_platform_approval', 'request_id', v_request_id);
end;
$function$;

CREATE OR REPLACE FUNCTION public.request_tenant_deletion(p_tenant_id uuid, p_confirm_slug text, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tenant uuid;
  v_t      tenants;
  v_name   text;
  v_id     uuid;
BEGIN
  -- ⚠ p_tenant_id is a HINT TO CHECK, never a selector. The caller's tenant is
  -- resolved server-side; a supplied id that disagrees is rejected outright
  -- rather than quietly ignored, so a confused client cannot file a request
  -- against a workspace it merely named.
  v_tenant := public.auth_tenant_id();
  IF v_tenant IS NULL THEN
    RAISE EXCEPTION 'not a member of any workspace';
  END IF;
  IF p_tenant_id IS NOT NULL AND p_tenant_id <> v_tenant THEN
    RAISE EXCEPTION 'you can only request deletion of the workspace you belong to';
  END IF;

  -- Owner/admin only. Erasing a company's workspace is not a member action.
  IF NOT public.can_admin_tenant_internal(v_tenant) THEN
    RAISE EXCEPTION 'only a workspace owner or admin may request deletion';
  END IF;

  SELECT * INTO v_t FROM tenants WHERE id = v_tenant;
  IF NOT FOUND THEN RAISE EXCEPTION 'workspace not found'; END IF;

  -- Same confirmation delete_tenant demands, asked at the same moment the human
  -- is actually deciding — not later, by an operator who did not make the choice.
  IF coalesce(p_confirm_slug, '') <> v_t.slug THEN
    RAISE EXCEPTION 'confirmation text must exactly match the workspace id (%)', v_t.slug;
  END IF;

  SELECT full_name INTO v_name FROM profiles WHERE user_id = auth.uid();

  INSERT INTO tenant_deletion_requests (tenant_id, requested_by, requested_by_name, reason)
  VALUES (v_tenant, auth.uid(), v_name, nullif(btrim(coalesce(p_reason, '')), ''))
  ON CONFLICT (tenant_id) WHERE status = 'pending' DO NOTHING
  RETURNING id, eligible_at INTO v_id, v_t.trial_ends_at;

  IF v_id IS NULL THEN
    -- Already pending. Idempotent and honest rather than a duplicate-key error.
    SELECT id INTO v_id FROM tenant_deletion_requests
     WHERE tenant_id = v_tenant AND status = 'pending';
    RETURN jsonb_build_object('ok', true, 'already_pending', true, 'request_id', v_id);
  END IF;

  RETURN jsonb_build_object(
    'ok', true, 'already_pending', false, 'request_id', v_id,
    'eligible_at', (SELECT eligible_at FROM tenant_deletion_requests WHERE id = v_id),
    'note', 'Filed. Nothing is deleted yet — you can withdraw this during the grace window.');
END $function$;

CREATE OR REPLACE FUNCTION public.request_trust_promotion(p_policy_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_policy   trust_policies;
  v_evidence jsonb;
  v_task_id  uuid;
  v_label    text;
begin
  select * into v_policy from trust_policies where id = p_policy_id;
  if not found then
    raise exception 'trust policy not found';
  end if;
  if not exists (select 1 from profiles where user_id = auth.uid() and tenant_id = v_policy.tenant_id) then
    raise exception 'not a member of this tenant';
  end if;
  -- DE scoping (mig 385/419). NULL-TOLERANT: trust_policies.de_id is
  -- nullable and 8 of 38 live policies are workspace-level, so the plain
  -- form would refuse those for a scoped user while the reader still shows
  -- them. Exact negation of the mig-386 predicate.
  if v_policy.de_id is not null and not public.can_access_de(v_policy.de_id) then
    raise exception 'not_responsible_for_de: this employee is not in your reporting line';
  end if;
  if v_policy.status <> 'active' then
    raise exception 'trust policy is paused';
  end if;
  if v_policy.current_level >= 3 then
    raise exception 'already at the highest trust level';
  end if;
  if v_policy.pending_task_id is not null
     and exists (select 1 from human_tasks where id = v_policy.pending_task_id and status = 'pending') then
    raise exception 'a promotion request is already awaiting approval';
  end if;

  v_evidence := trust_evidence_for(v_policy);
  if not coalesce((v_evidence->>'eligible')::boolean, false) then
    raise exception 'not eligible for promotion — evidence does not yet meet the policy criteria';
  end if;

  v_label := replace(v_policy.action_category, '_', ' ');
  insert into human_tasks (tenant_id, type, title, detail, source, related_table, related_id)
  values (
    v_policy.tenant_id, 'trust_promotion',
    format('Trust promotion — %s to level %s', v_label, v_policy.current_level + 1),
    format('Evidence met all criteria: %s. Approving widens autonomy one step — still capped by guardrails.',
      (select string_agg(x->>'detail', ' · ') from jsonb_array_elements(v_evidence->'criteria') x)),
    'system', 'trust_policies', v_policy.id
  )
  returning id into v_task_id;

  update trust_policies
  set pending_task_id = v_task_id,
      pending_evidence = v_evidence,
      requested_by = auth.uid(),
      requested_at = now()
  where id = v_policy.id;

  perform append_audit_event(
    v_policy.tenant_id, 'Trust engine', 'system',
    format('Trust promotion requested — %s level %s → %s (evidence eligible)',
      v_label, v_policy.current_level, v_policy.current_level + 1),
    'config_change',
    jsonb_build_object('kind', 'trust_promotion_requested', 'policy_id', v_policy.id,
      'action_category', v_policy.action_category, 'from_level', v_policy.current_level,
      'to_level', v_policy.current_level + 1, 'task_id', v_task_id,
      'requested_by', auth.uid(), 'evidence', v_evidence)
  );

  return jsonb_build_object('ok', true, 'task_id', v_task_id, 'evidence', v_evidence);
end;
$function$;

CREATE OR REPLACE FUNCTION public.reroute_de_escalation(p_task_id uuid, p_to_de_id uuid, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tenant uuid := auth_tenant_id();
  v_task human_tasks;
  v_item de_work_items;
  v_note text;
  v_to_name text;
  v_from_name text;
  v_req jsonb;
  n_freed int := 0;
begin
  -- mig 487: this is a sanctioned decision path.
  perform set_config('app.allow_task_decision', 'on', true);

  if v_tenant is null then raise exception 'not_authenticated'; end if;
  v_note := nullif(btrim(coalesce(p_note, '')), '');
  if v_note is null then
    raise exception 'rerouting a blocker requires a reason — say why it belongs elsewhere';
  end if;

  select * into v_task from human_tasks where id = p_task_id and tenant_id = v_tenant;
  if v_task.id is null then raise exception 'task_not_found'; end if;
  if v_task.status <> 'pending' then raise exception 'already_decided: %', v_task.status; end if;
  if v_task.de_id is not null and not can_access_de(v_task.de_id) then
    raise exception 'insufficient_scope';
  end if;
  -- You may not move work to an employee you cannot see.
  if not can_access_de(p_to_de_id) then
    raise exception 'insufficient_scope_target';
  end if;
  if v_task.de_id is not distinct from p_to_de_id then
    raise exception 'already_owned_by_that_employee';
  end if;

  select coalesce(persona_name, name) into v_to_name from digital_employees
   where id = p_to_de_id and tenant_id = v_tenant;
  if v_to_name is null then raise exception 'target_not_found'; end if;
  select coalesce(persona_name, name) into v_from_name from digital_employees where id = v_task.de_id;

  if v_task.related_table = 'de_work_items' and v_task.related_id is not null then
    select * into v_item from de_work_items where id = v_task.related_id and tenant_id = v_tenant;
  end if;

  -- Hand the work over. The HUMAN path of request_de_task (from_de NULL) — a
  -- person reassigning does not need a DE-to-DE delegation grant.
  v_req := request_de_task(
    null, p_to_de_id,
    left(coalesce(v_item.title, v_task.title, 'Rerouted work'), 200),
    left(format('Rerouted from %s by a person. Reason: %s%s',
      coalesce(v_from_name, 'another employee'), v_note,
      case when coalesce(v_task.detail, '') <> ''
           then E'\n\nWhat the employee reported:\n' || left(v_task.detail, 2000) else '' end), 4000),
    null, 'normal', null,
    'de_work_items', v_item.id);

  if coalesce((v_req->>'ok')::boolean, false) is not true then
    raise exception 'reroute_failed: %', coalesce(v_req->>'error', 'unknown');
  end if;

  -- Close the original step, and free whatever was queued behind it.
  if v_item.id is not null then
    update de_work_items set
      status = 'cancelled', locked_at = null, locked_by = null, updated_at = now(),
      result = coalesce(result, '{}'::jsonb) || jsonb_build_object(
        'summary', left(format('Rerouted to %s: %s', v_to_name, v_note), 500),
        'rerouted', jsonb_build_object('task_id', p_task_id, 'to_de_id', p_to_de_id,
          'to_name', v_to_name, 'note', v_note, 'at', now()))
    where id = v_item.id and status in ('waiting_human', 'queued');

    -- NOT a cascade-cancel. The work moved; its dependants must stay runnable
    -- once the new owner delivers (mig 493's stranding lesson).
    with freed as (
      update de_work_items c set depends_on = null, updated_at = now()
       where c.depends_on = v_item.id and c.status in ('queued', 'waiting_human')
      returning c.id
    )
    select count(*) into n_freed from freed;
  end if;

  update human_tasks set
    status = 'rejected',
    disposition = 'rerouted',
    decision_note = v_note,
    decided_by = auth.uid(),
    decided_at = now()
  where id = p_task_id;

  update de_exceptions set
    status = 'denied', outcome = format('Rerouted to %s: %s', v_to_name, v_note), decided_at = now()
  where human_task_id = p_task_id and status = 'proposed';

  perform append_audit_event(
    v_tenant, 'Workspace', 'human',
    format('Blocker rerouted from %s to %s — %s',
      coalesce(v_from_name, 'an employee'), v_to_name, left(v_task.title, 100)),
    'approval',
    jsonb_build_object('task_id', p_task_id, 'from_de_id', v_task.de_id, 'to_de_id', p_to_de_id,
      'work_item_id', v_item.id, 'dependants_freed', n_freed, 'note', v_note,
      'delegation_request', v_req));

  return jsonb_build_object('ok', true, 'disposition', 'rerouted',
    'to_de_id', p_to_de_id, 'to_name', v_to_name,
    'work_item_id', v_item.id, 'dependants_freed', n_freed);
end;
$function$;

CREATE OR REPLACE FUNCTION public.reset_de_config_to_template(p_de_id uuid, p_template_key text DEFAULT 'support-de-template'::text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tenant_id UUID := public.auth_tenant_id();
BEGIN
  IF v_tenant_id IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  DELETE FROM config_schema_instances
  WHERE de_id = p_de_id AND tenant_id = v_tenant_id AND template_key = p_template_key;
  RETURN json_build_object('ok', true, 'reset', true);
END$function$;

CREATE OR REPLACE FUNCTION public.resolve_access(p_tenant_id uuid, p_subject_kind text, p_subject_id uuid, p_connector_id uuid, p_needed text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_category text;
  v_has      text;
  v_via      text;
begin
  select category into v_category from connectors
   where id = p_connector_id and tenant_id = p_tenant_id;
  if v_category is null then
    return jsonb_build_object('allowed', false, 'reason', 'connector_not_found', 'needed', p_needed, 'has', null, 'via', null);
  end if;

  -- 1. connector-specific grant wins
  select permission into v_has from data_access_grants
   where tenant_id = p_tenant_id and subject_kind = p_subject_kind and subject_id = p_subject_id
     and resource_kind = 'connector' and resource_id = p_connector_id;
  if v_has is not null then
    v_via := 'connector';
  else
    -- 2. category-level grant
    select permission into v_has from data_access_grants
     where tenant_id = p_tenant_id and subject_kind = p_subject_kind and subject_id = p_subject_id
       and resource_kind = 'category' and resource_category = v_category;
    if v_has is not null then v_via := 'category'; end if;
  end if;

  -- 3. default deny
  if v_has is null then
    return jsonb_build_object('allowed', false, 'reason', 'no_grant', 'needed', p_needed, 'has', null, 'via', null);
  end if;

  if access_permission_level(v_has) >= access_permission_level(p_needed) then
    return jsonb_build_object('allowed', true, 'reason', 'granted', 'needed', p_needed, 'has', v_has, 'via', v_via);
  end if;
  return jsonb_build_object('allowed', false, 'reason', 'insufficient_permission', 'needed', p_needed, 'has', v_has, 'via', v_via);
end;
$function$;

CREATE OR REPLACE FUNCTION public.resolve_account_writeback(p_task_id uuid, p_decision text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r account_writeback_requests; v_res jsonb;
BEGIN IF NOT coalesce(public.can_admin_tenant_internal((SELECT tenant_id FROM public.account_writeback_requests WHERE task_id = p_task_id)), false) THEN RAISE EXCEPTION 'not permitted'; END IF;
  SELECT * INTO r FROM account_writeback_requests WHERE task_id = p_task_id;
  IF r.id IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'no_request_for_task'); END IF;
  IF r.status <> 'pending_approval' THEN RETURN jsonb_build_object('ok', true, 'already', r.status); END IF;

  IF p_decision = 'approved' THEN
    v_res := public.apply_account_writeback_internal(r.id);
    UPDATE account_writeback_requests SET decided_at = now() WHERE id = r.id;
    BEGIN PERFORM append_audit_event_internal(r.tenant_id, 'You', 'human',
      'Write-back APPROVED + applied — ' || r.request_summary, 'connector_action',
      jsonb_build_object('kind','account_writeback','op',r.op,'request_id',r.id,'approved',true));
    EXCEPTION WHEN OTHERS THEN NULL; END;
    RETURN jsonb_build_object('ok', true, 'applied', true);
  ELSE
    UPDATE account_writeback_requests SET status = 'rejected', decided_at = now() WHERE id = r.id;
    RETURN jsonb_build_object('ok', true, 'applied', false);
  END IF;
END; $function$;

CREATE OR REPLACE FUNCTION public.resolve_case_await(p_tenant_id uuid, p_objective_id uuid, p_awaiting_ref text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_n integer := 0;
BEGIN
  UPDATE de_case_events
     SET status = 'resolved', decided_at = now()
   WHERE tenant_id = p_tenant_id AND objective_id = p_objective_id
     AND status = 'pending' AND awaiting_ref IS NOT NULL AND awaiting_ref = p_awaiting_ref;
  GET DIAGNOSTICS v_n = ROW_COUNT;

  IF v_n > 0 THEN
    -- The reply came — wake the case now so the DE processes it.
    UPDATE de_objectives SET status = 'open', next_wake_at = now(), updated_at = now()
     WHERE id = p_objective_id AND tenant_id = p_tenant_id AND status NOT IN ('achieved','abandoned');
  END IF;
  RETURN jsonb_build_object('ok', true, 'resolved', v_n);
END; $function$;

CREATE OR REPLACE FUNCTION public.resolve_category_access(p_tenant_id uuid, p_subject_kind text, p_subject_id uuid, p_category text, p_needed text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_has jsonb := '[]'::jsonb;
  v_via text;
  v_lvl integer := -1;
  v_row record;
begin
  -- 1. Any connector-specific grant on a connector OF this category —
  --    take the HIGHEST permission level found (mirrors "specific beats
  --    general" from resolve_access, generalized across all connectors
  --    of the category rather than just one).
  for v_row in
    select g.permission from data_access_grants g
    join connectors c on c.id = g.resource_id and c.tenant_id = p_tenant_id and c.category = p_category
    where g.tenant_id = p_tenant_id and g.subject_kind = p_subject_kind and g.subject_id = p_subject_id
      and g.resource_kind = 'connector'
  loop
    if access_permission_level(v_row.permission) > v_lvl then
      v_lvl := access_permission_level(v_row.permission);
      v_via := 'connector';
    end if;
  end loop;

  -- 2. Category-level grant, only if no connector-specific grant beat it.
  if v_lvl < 0 then
    select permission into v_row from data_access_grants
     where tenant_id = p_tenant_id and subject_kind = p_subject_kind and subject_id = p_subject_id
       and resource_kind = 'category' and resource_category = p_category;
    if found then
      v_lvl := access_permission_level(v_row.permission);
      v_via := 'category';
    end if;
  end if;

  if v_lvl < 0 then
    return jsonb_build_object('allowed', false, 'reason', 'no_grant', 'needed', p_needed, 'has', null, 'via', null);
  end if;
  if v_lvl >= access_permission_level(p_needed) then
    return jsonb_build_object('allowed', true, 'reason', 'granted', 'needed', p_needed, 'via', v_via);
  end if;
  return jsonb_build_object('allowed', false, 'reason', 'insufficient_permission', 'needed', p_needed, 'via', v_via);
end;
$function$;

CREATE OR REPLACE FUNCTION public.resolve_cleared_ops_alerts(p_heartbeat jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE n_dispatch int := 0; n_spin int := 0; n_workforce int := 0; n int := 0; k text;
BEGIN
  -- ── dispatch_failure: older than the re-check interval is history ────────
  UPDATE ops_alerts SET resolved_at = now()
   WHERE kind = 'dispatch_failure' AND resolved_at IS NULL
     AND created_at < now() - interval '2 hours';
  GET DIAGNOSTICS n_dispatch = ROW_COUNT;

  -- ── wake_spin: the goal stopped spinning, one way or another ─────────────
  UPDATE ops_alerts a SET resolved_at = now()
   WHERE a.kind = 'de_objective_wake_spin' AND a.resolved_at IS NULL
     AND EXISTS (
       SELECT 1 FROM de_objectives o
        WHERE o.id = (a.detail->>'objective_id')::uuid
          AND (o.status NOT IN ('open', 'in_progress', 'blocked')
            OR o.attention_flag IS DISTINCT FROM 'wake_spin'
            OR EXISTS (SELECT 1 FROM de_work_items w
                        WHERE w.objective_id = o.id AND w.updated_at > a.created_at)));
  GET DIAGNOSTICS n_spin = ROW_COUNT;

  -- ── workforce_*: cleared when the heartbeat says the bucket is empty ─────
  IF p_heartbeat IS NOT NULL THEN
    FOREACH k IN ARRAY ARRAY['claim_broken', 'stalled', 'deadlocked'] LOOP
      IF jsonb_array_length(coalesce(p_heartbeat->k, '[]'::jsonb)) = 0 THEN
        UPDATE ops_alerts SET resolved_at = now()
         WHERE resolved_at IS NULL
           AND kind = CASE k WHEN 'claim_broken' THEN 'workforce_claim_broken'
                             WHEN 'stalled'      THEN 'workforce_stalled'
                             ELSE                     'workforce_deadlocked' END;
        GET DIAGNOSTICS n = ROW_COUNT;
        n_workforce := n_workforce + n;
      END IF;
    END LOOP;
  END IF;

  RETURN jsonb_build_object('ok', true, 'dispatch_failure', n_dispatch,
    'wake_spin', n_spin, 'workforce', n_workforce);
END $function$;

CREATE OR REPLACE FUNCTION public.resolve_continuity_writeback(p_task_id uuid, p_decision text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r continuity_writeback_requests; v_res jsonb;
BEGIN IF NOT coalesce(public.can_admin_tenant_internal((SELECT tenant_id FROM public.continuity_writeback_requests WHERE task_id = p_task_id)), false) THEN RAISE EXCEPTION 'not permitted'; END IF;
  SELECT * INTO r FROM continuity_writeback_requests WHERE task_id = p_task_id;
  IF r.id IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'no_request_for_task'); END IF;
  IF r.status <> 'pending_approval' THEN RETURN jsonb_build_object('ok', true, 'already', r.status); END IF;
  IF p_decision = 'approved' THEN
    v_res := public.apply_continuity_writeback_internal(r.id);
    UPDATE continuity_writeback_requests SET decided_at = now() WHERE id = r.id;
    BEGIN PERFORM append_audit_event_internal(r.tenant_id, 'You', 'human', 'Continuity write-back APPROVED + applied — ' || r.request_summary, 'connector_action',
      jsonb_build_object('kind','continuity_writeback','op',r.op,'request_id',r.id,'approved',true));
    EXCEPTION WHEN OTHERS THEN NULL; END;
    RETURN jsonb_build_object('ok', true, 'applied', true);
  ELSE
    UPDATE continuity_writeback_requests SET status = 'rejected', decided_at = now() WHERE id = r.id;
    RETURN jsonb_build_object('ok', true, 'applied', false);
  END IF;
END; $function$;

CREATE OR REPLACE FUNCTION public.resolve_de_archetype(p_de_id uuid)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce(
    (select archetype_key from digital_employees where id = p_de_id),
    (select catalog_id from digital_employees where id = p_de_id),
    (select archetype_key from role_certifications
      where de_id = p_de_id and archetype_key is not null
      order by created_at desc limit 1)
  );
$function$;

CREATE OR REPLACE FUNCTION public.resolve_de_autonomy(p_tenant_id uuid, p_action_type text, p_de_id uuid DEFAULT NULL::uuid, p_source_category text DEFAULT NULL::text, p_playbook_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(enabled boolean, max_amount_cents bigint, min_confidence integer)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_row   de_autonomy;
  v_gated boolean := false;
begin
  -- Records gate (mig 258): a gated employee is supervised whatever the dial
  -- says. Checked first so every branch below inherits it.
  if p_de_id is not null then
    select g.gated into v_gated from public.de_records_gate(p_tenant_id, p_de_id) g;
  end if;

  -- playbook + employee + category
  if p_playbook_id is not null and p_de_id is not null and p_source_category is not null then
    select * into v_row from de_autonomy
    where tenant_id = p_tenant_id and action_type = p_action_type
      and de_id = p_de_id and playbook_id = p_playbook_id and source_category = p_source_category
    limit 1;
    if found then return query select (v_row.enabled and not v_gated), v_row.max_amount_cents, v_row.min_confidence; return; end if;
  end if;

  -- playbook + employee
  if p_playbook_id is not null and p_de_id is not null then
    select * into v_row from de_autonomy
    where tenant_id = p_tenant_id and action_type = p_action_type
      and de_id = p_de_id and playbook_id = p_playbook_id and source_category is null
    limit 1;
    if found then return query select (v_row.enabled and not v_gated), v_row.max_amount_cents, v_row.min_confidence; return; end if;
  end if;

  -- employee + category
  if p_de_id is not null and p_source_category is not null then
    select * into v_row from de_autonomy
    where tenant_id = p_tenant_id and action_type = p_action_type
      and de_id = p_de_id and playbook_id is null and source_category = p_source_category
    limit 1;
    if found then return query select (v_row.enabled and not v_gated), v_row.max_amount_cents, v_row.min_confidence; return; end if;
  end if;

  -- employee
  if p_de_id is not null then
    select * into v_row from de_autonomy
    where tenant_id = p_tenant_id and action_type = p_action_type
      and de_id = p_de_id and playbook_id is null and source_category is null
    limit 1;
    if found then return query select (v_row.enabled and not v_gated), v_row.max_amount_cents, v_row.min_confidence; return; end if;
  end if;

  -- ⚠ NO WORKSPACE TIER. The two branches that used to read de_id IS NULL rows
  -- are gone on purpose: a default that applies to every employee is exactly
  -- what the founder ruled out. Reaching here means this employee has no rule
  -- for this action, and the answer to that is no.
  return query select false, null::bigint, null::integer;
end;
$function$;

CREATE OR REPLACE FUNCTION public.resolve_de_autonomy_chain(p_tenant_id uuid, p_keys text[], p_de_id uuid DEFAULT NULL::uuid, p_source_category text DEFAULT NULL::text, p_playbook_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(enabled boolean, max_amount_cents bigint, min_confidence integer)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare v_key text;
begin
  foreach v_key in array coalesce(p_keys, array[]::text[]) loop
    if v_key is null or v_key = '' then continue; end if;
    if exists (
      select 1 from de_autonomy a
      where a.tenant_id = p_tenant_id
        and a.action_type = v_key
        and a.de_id is not distinct from p_de_id
        and (p_playbook_id is null or a.playbook_id is not distinct from p_playbook_id
             or a.playbook_id is null)
    ) then
      return query select * from resolve_de_autonomy(p_tenant_id, v_key, p_de_id, p_source_category, p_playbook_id);
      return;
    end if;
  end loop;
  -- No key has a rule for this employee: deny, one explicit row — never empty.
  return query select false, null::bigint, null::integer;
end;
$function$;

CREATE OR REPLACE FUNCTION public.resolve_de_escalation(p_tenant_id uuid, p_de_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(frustration_threshold integer, always_escalate_topics text[])
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select
    coalesce(
      (select r.frustration_threshold from de_escalation_rules r
       where r.tenant_id = p_tenant_id and r.de_id = p_de_id and p_de_id is not null and r.frustration_threshold is not null),
      (select r.frustration_threshold from de_escalation_rules r
       where r.tenant_id = p_tenant_id and r.de_id is null and r.frustration_threshold is not null),
      80
    ) as frustration_threshold,
    coalesce(
      (select nullif(r.always_escalate_topics, '{}') from de_escalation_rules r
       where r.tenant_id = p_tenant_id and r.de_id = p_de_id and p_de_id is not null),
      (select nullif(r.always_escalate_topics, '{}') from de_escalation_rules r
       where r.tenant_id = p_tenant_id and r.de_id is null),
      '{}'::text[]
    ) as always_escalate_topics;
$function$;

CREATE OR REPLACE FUNCTION public.resolve_de_exception(p_id uuid, p_status text, p_outcome text DEFAULT NULL::text, p_learned boolean DEFAULT false)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  -- Prefix deleted. No caller anywhere; retirement candidate.
  if not exists (
      select 1 from de_exceptions e join profiles p on p.user_id = auth.uid()
      where e.id = p_id and (p.tenant_id = e.tenant_id or p.layer = 'platform')) then
    raise exception 'not authorized';
  end if;
  update de_exceptions
     set status = p_status, outcome = p_outcome, learned = coalesce(p_learned, false),
         decided_by = auth.uid(), decided_at = now()
   where id = p_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.resolve_de_model_for_task(p_de_id uuid, p_task_class text DEFAULT 'standard'::text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_arch text; v_model text;
begin
  select catalog_id into v_arch from digital_employees where id = p_de_id;
  select model_id into v_model from de_model_routes
    where scope = 'de' and de_id = p_de_id and task_class = p_task_class limit 1;
  if v_model is not null then return v_model; end if;
  select model_id into v_model from de_model_routes
    where scope = 'archetype' and archetype_key = v_arch and task_class = p_task_class limit 1;
  if v_model is not null then return v_model; end if;
  select coalesce(model_id, 'claude-sonnet-5') into v_model from digital_employees where id = p_de_id;
  return coalesce(v_model, 'claude-sonnet-5');
end;
$function$;

CREATE OR REPLACE FUNCTION public.resolve_exception(p_exception_id uuid, p_decision text, p_final_treatment text, p_approver uuid, p_approver_name text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_ex      public.exceptions%rowtype;
  v_caller_tenant uuid;
  v_evidence_id uuid;
  v_source  text;
  v_new_status text;
begin
  if p_decision not in ('approved','rejected') then
    raise exception 'invalid decision %', p_decision;
  end if;

  select * into v_ex from public.exceptions where id = p_exception_id;
  if not found then raise exception 'exception not found'; end if;

  -- Tenant guard: caller must belong to the exception's tenant (or be platform admin).
  v_caller_tenant := public.auth_tenant_id();
  if v_caller_tenant is distinct from v_ex.tenant_id and not public.is_platform_admin() then
    raise exception 'cross-tenant access denied';
  end if;

  if v_ex.status <> 'open' then
    raise exception 'exception already %', v_ex.status;
  end if;

  -- Build source-evidence pointer string from the offending object
  v_source := coalesce(v_ex.ref_table,'n/a')||':'||coalesce(v_ex.ref_id::text,'n/a')
              ||' | type='||v_ex.exception_type||' | amount='||coalesce(v_ex.amount::text,'n/a');

  v_new_status := case when p_decision='approved' then 'approved' else 'rejected' end;

  update public.exceptions
     set status = v_new_status,
         resolved_by = p_approver,
         resolved_at = now(),
         final_treatment = p_final_treatment
   where id = p_exception_id;

  insert into public.audit_evidence
    (tenant_id, workspace_id, exception_id, action, source_evidence, ai_reasoning, confidence, approver, approver_name, final_treatment)
  values
    (v_ex.tenant_id, v_ex.workspace_id, v_ex.id, p_decision, v_source, v_ex.ai_reasoning, v_ex.confidence, p_approver, p_approver_name, p_final_treatment)
  returning id into v_evidence_id;

  return v_evidence_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.resolve_experience(p_tenant_id uuid, p_subject_kind text, p_subject_id uuid, p_category text, p_external_ref text, p_limit integer DEFAULT 3)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_verdict jsonb;
  v_rows    jsonb;
begin
  if p_external_ref is null or p_external_ref = '' then
    return jsonb_build_object('allowed', true, 'rows', '[]'::jsonb);
  end if;

  v_verdict := resolve_category_access(p_tenant_id, p_subject_kind, p_subject_id, p_category, 'search');
  if not coalesce((v_verdict->>'allowed')::boolean, false) then
    return jsonb_build_object('allowed', false, 'reason', v_verdict->>'reason', 'rows', '[]'::jsonb);
  end if;

  select coalesce(jsonb_agg(row_to_json(e)), '[]'::jsonb) into v_rows
  from (
    select id, fact_summary, source_evidence_run_id, source_action_execution_id, created_at
    from de_experience
    where tenant_id = p_tenant_id and subject_kind = p_subject_kind and subject_id = p_subject_id
      and category = p_category and external_ref = p_external_ref
    order by created_at desc
    limit greatest(1, least(p_limit, 10))
  ) e;

  return jsonb_build_object('allowed', true, 'rows', v_rows);
end;
$function$;

CREATE OR REPLACE FUNCTION public.resolve_external_account(p_tenant_id uuid, p_provider text, p_customer_external_ref text, p_customer_name text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_id uuid;
begin
  if coalesce(btrim(p_customer_external_ref), '') = '' then
    return null;
  end if;

  insert into customer_accounts (tenant_id, name, external_ref, source_provider, source_external_ref)
  values (p_tenant_id,
          coalesce(nullif(btrim(p_customer_name), ''), p_customer_external_ref),
          p_customer_external_ref, p_provider, p_customer_external_ref)
  on conflict (tenant_id, source_provider, source_external_ref) where source_external_ref is not null
  do update set name = excluded.name, updated_at = now()
  returning id into v_id;

  return v_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.resolve_invoice_writeback(p_task_id uuid, p_decision text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r invoice_writeback_requests;
BEGIN
  SELECT * INTO r FROM invoice_writeback_requests WHERE task_id = p_task_id;
  IF r.id IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'no_request_for_task'); END IF;
  IF r.status <> 'pending_approval' THEN RETURN jsonb_build_object('ok', true, 'already', r.status); END IF;
  IF p_decision = 'approved' THEN
    PERFORM public.apply_invoice_writeback_internal(r.id);
    UPDATE invoice_writeback_requests SET decided_at = now() WHERE id = r.id;
    RETURN jsonb_build_object('ok', true, 'applied', true);
  ELSE
    UPDATE invoice_writeback_requests SET status = 'rejected', decided_at = now() WHERE id = r.id;
    RETURN jsonb_build_object('ok', true, 'applied', false);
  END IF;
END; $function$;

CREATE OR REPLACE FUNCTION public.resolve_jit_membership(p_user_id uuid DEFAULT NULL::uuid, p_attributes jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_is_service   boolean;
  v_caller       uuid;
  v_target       uuid;
  v_trust        boolean;
  v_email        text;
  v_confirmed    timestamptz;
  v_is_sso       boolean;
  v_deleted      timestamptz;
  v_banned       timestamptz;
  v_found        boolean := false;
  v_p_exists     boolean := false;
  v_p_id         uuid;
  v_p_layer      text;
  v_p_role       text;
  v_p_tenant     uuid;
  v_decision     jsonb;
  v_rows         integer;
BEGIN
  -- The service role is named explicitly. It is NOT inferred from a null
  -- auth.uid(), because anon also has a null uid — that inference is the exact
  -- bug migrations 330 and 369 had to go back and fix.
  v_is_service := COALESCE(auth.role(), '') = 'service_role';
  v_caller     := auth.uid();
  v_target     := COALESCE(p_user_id, v_caller);

  IF NOT v_is_service THEN
    -- A logged-in user may resolve ONLY themselves. Resolving someone else
    -- would let any account force-provision another account, and would turn
    -- this function into an oracle for "which domains are verified".
    IF v_caller IS NULL OR v_target IS DISTINCT FROM v_caller THEN
      RAISE EXCEPTION 'not authorized';
    END IF;
  END IF;

  IF v_target IS NULL THEN
    RAISE EXCEPTION 'not authorized';
  END IF;

  -- Attributes are only believed when they arrive from the backend, which got
  -- them from a signed IdP assertion. From a browser they are user-controlled
  -- text; honouring them would let anyone self-assert into tenant_admin.
  v_trust := v_is_service;

  SELECT u.email, u.email_confirmed_at, COALESCE(u.is_sso_user, false),
         u.deleted_at, u.banned_until, true
    INTO v_email, v_confirmed, v_is_sso, v_deleted, v_banned, v_found
    FROM auth.users u
   WHERE u.id = v_target;

  IF NOT COALESCE(v_found, false) THEN
    v_decision := jsonb_build_object('granted', false, 'reason', 'user_not_found');
  ELSIF v_deleted IS NOT NULL OR (v_banned IS NOT NULL AND v_banned > now()) THEN
    v_decision := jsonb_build_object('granted', false, 'reason', 'user_disabled');
  ELSE
    SELECT pr.id, true, pr.layer, pr.role, pr.tenant_id
      INTO v_p_id, v_p_exists, v_p_layer, v_p_role, v_p_tenant
      FROM public.profiles pr
     WHERE pr.user_id = v_target;

    v_decision := public.jit_decide_internal(
      v_email, v_confirmed IS NOT NULL, v_is_sso,
      COALESCE(v_p_exists, false), v_p_layer, v_p_role, v_p_tenant,
      p_attributes, v_trust);
  END IF;

  IF (v_decision->>'granted')::boolean THEN
    -- Every precondition is restated in the WHERE clause, so two concurrent
    -- calls cannot both win and the row cannot have changed underneath the
    -- decision. Zero rows updated means someone else got there first.
    UPDATE public.profiles
       SET tenant_id  = (v_decision->>'tenant_id')::uuid,
           role       = v_decision->>'role',
           layer      = 'tenant',
           updated_at = now()
     WHERE user_id   = v_target
       AND tenant_id IS NULL
       AND layer      = 'tenant'
       AND role       = 'agent';

    GET DIAGNOSTICS v_rows = ROW_COUNT;
    IF v_rows = 0 THEN
      v_decision := jsonb_set(
        jsonb_set(v_decision, '{granted}', 'false'::jsonb),
        '{reason}', '"race_lost"'::jsonb);
    END IF;
  END IF;

  -- Record the refusal, not just the grant. log_tenant_activity() on profiles
  -- returns early for an actor with no tenant_id, which is every JIT candidate,
  -- so without this insert a JIT decision leaves no trace anywhere. Refusals
  -- are the interesting half: "why did our new hire not get in" and "who keeps
  -- trying" are both answered here.
  BEGIN
    INSERT INTO public.audit_logs (
      tenant_id, actor_user_id, action, entity_type, entity_id, entity_name,
      after_data, metadata)
    VALUES (
      NULLIF(v_decision->>'tenant_id', '')::uuid,
      v_target,
      CASE WHEN (v_decision->>'granted')::boolean THEN 'sso.jit_provisioned'
           ELSE 'sso.jit_refused' END,
      'profile', v_p_id, v_email,
      v_decision,
      jsonb_build_object(
        'source', CASE WHEN v_is_service THEN 'service_role' ELSE 'self_service' END,
        'attributes_trusted', v_trust,
        'attribute_keys', CASE WHEN jsonb_typeof(COALESCE(p_attributes,'{}'::jsonb)) = 'object'
                               -- keys only: attribute VALUES can carry HR data
                               -- (department, cost centre) and this table is
                               -- readable by every member of the tenant.
                               THEN (SELECT COALESCE(jsonb_agg(k), '[]'::jsonb)
                                       FROM jsonb_object_keys(p_attributes) k)
                               ELSE '[]'::jsonb END));
  EXCEPTION WHEN others THEN
    -- Audit failure must not deny a legitimate member their workspace, but it
    -- must be visible in the Postgres log rather than swallowed silently.
    RAISE WARNING 'resolve_jit_membership: audit insert failed: %', SQLERRM;
  END;

  RETURN v_decision;
END $function$;

CREATE OR REPLACE FUNCTION public.resolve_knowledge_conflict(p_conflict_id uuid, p_resolution text, p_authoritative_doc_id uuid DEFAULT NULL::uuid, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_c knowledge_conflicts%ROWTYPE; v_winner uuid; v_loser uuid;
BEGIN
  -- FOR UPDATE serializes concurrent resolves so the nudge applies exactly once
  -- (the second caller re-reads the committed status and returns already_resolved).
  SELECT * INTO v_c FROM knowledge_conflicts WHERE id = p_conflict_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'error', 'not_found'); END IF;
  -- Must be an admin/owner of the conflict's OWN tenant. Canonical NULL-safe idiom
  -- (mig 105): positive equality fails CLOSED on a NULL tenant, and ties the role
  -- check to this conflict's tenant (closes the remote-access NOT-IN-NULL path).
  IF NOT (v_c.tenant_id = auth_tenant_id()
          AND auth_has_tenant_role(ARRAY['tenant_owner', 'tenant_admin', 'knowledge_manager'])) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'forbidden');
  END IF;
  IF v_c.status <> 'open' THEN RETURN jsonb_build_object('ok', false, 'error', 'already_resolved'); END IF;
  IF p_resolution NOT IN ('resolved_pick_a', 'resolved_pick_b', 'merged', 'dismissed') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'bad_resolution'); END IF;
  -- Authoritative doc, if given, MUST be one of the two in the pair.
  IF p_authoritative_doc_id IS NOT NULL AND p_authoritative_doc_id NOT IN (v_c.doc_a_id, v_c.doc_b_id) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'authoritative_not_in_pair'); END IF;

  UPDATE knowledge_conflicts
     SET status = p_resolution, authoritative_doc_id = p_authoritative_doc_id,
         decided_by = auth.uid(), decided_at = now(),
         signal = signal || jsonb_build_object('note', p_note)
   WHERE id = p_conflict_id;

  -- One-tier, clamped authority nudge — winner up, loser down — scoped to exactly
  -- the two docs in this pair AND the tenant. Only when a side is picked.
  IF p_resolution IN ('resolved_pick_a', 'resolved_pick_b') THEN
    v_winner := CASE p_resolution WHEN 'resolved_pick_a' THEN v_c.doc_a_id ELSE v_c.doc_b_id END;
    v_loser  := CASE p_resolution WHEN 'resolved_pick_a' THEN v_c.doc_b_id ELSE v_c.doc_a_id END;
    UPDATE knowledge_docs SET authority = least(100, authority + 1)
      WHERE id = v_winner AND tenant_id = v_c.tenant_id;
    UPDATE knowledge_docs SET authority = greatest(0, authority - 1)
      WHERE id = v_loser AND tenant_id = v_c.tenant_id;
  END IF;
  RETURN jsonb_build_object('ok', true, 'status', p_resolution);
END $function$;

CREATE OR REPLACE FUNCTION public.resolve_llm_key(p_tenant_id uuid, p_provider_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_secret uuid; v_val text; v_mode text;
BEGIN
  -- Service role (or a superuser/migration context, where auth.role() is NULL)
  -- ONLY. Written against auth.ROLE, never "auth.uid() is null" — anon shares a
  -- NULL uid with service role (mig 330) but its role is the string 'anon', so
  -- checking the role is what actually keeps anon out of a live credential.
  IF auth.role() IS NOT NULL AND auth.role() <> 'service_role' THEN
    RAISE EXCEPTION 'not authorized';
  END IF;

  SELECT c.secret_id INTO v_secret FROM tenant_llm_credentials c
   WHERE c.tenant_id = p_tenant_id AND c.provider_key = p_provider_key;

  IF v_secret IS NOT NULL THEN
    SELECT decrypted_secret INTO v_val FROM vault.decrypted_secrets WHERE id = v_secret;
    IF coalesce(v_val, '') <> '' THEN
      RETURN jsonb_build_object('ok', true, 'key', v_val, 'source', 'tenant');
    END IF;
  END IF;

  SELECT llm_key_mode INTO v_mode FROM tenants WHERE id = p_tenant_id;

  IF coalesce(v_mode, 'platform') = 'byo' THEN
    -- No silent fallback. This workspace said it brings its own key.
    -- mig 575: distinct source, so the caller can tell refusal from absence.
    RETURN jsonb_build_object('ok', false, 'source', 'byo_refused', 'reason',
      format('This workspace is set to use its own %s and none is configured. Add it in Settings > AI Engine, or switch the workspace to the platform key.', p_provider_key));
  END IF;

  -- Read the platform secret directly rather than through platform_config_get:
  -- that function carries its own service-role guard, which this already
  -- satisfies above, and nesting it makes this fail in any context where the
  -- outer guard passes but the inner one does not.
  v_val := NULL;
  SELECT decrypted_secret INTO v_val
    FROM vault.decrypted_secrets s
    JOIN platform_config pc ON pc.secret_id = s.id
   WHERE pc.key = p_provider_key;

  IF coalesce(v_val, '') <> '' THEN
    RETURN jsonb_build_object('ok', true, 'key', v_val, 'source', 'platform');
  END IF;

  RETURN jsonb_build_object('ok', false, 'source', 'none', 'reason',
    format('No %s is configured for this workspace or for the platform.', p_provider_key));
END $function$;

CREATE OR REPLACE FUNCTION public.resolve_llm_keys(p_tenant_id uuid, p_keys text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_key    text;
  v_secret uuid;
  v_val    text;
  v_mode   text;
  v_out    jsonb := '{}'::jsonb;
begin
  -- Same guard as resolve_llm_key, written against auth.ROLE: anon shares a
  -- NULL uid with service_role (mig 330), so only the role string keeps anon
  -- away from a live credential.
  if auth.role() is not null and auth.role() <> 'service_role' then
    raise exception 'not authorized';
  end if;

  if p_keys is null or array_length(p_keys, 1) is null then
    return v_out;
  end if;

  -- One lookup of the workspace's mode, not one per key.
  if p_tenant_id is not null then
    select llm_key_mode into v_mode from tenants where id = p_tenant_id;
  end if;

  foreach v_key in array p_keys loop
    v_secret := null;
    v_val    := null;

    if p_tenant_id is not null then
      select c.secret_id into v_secret
        from tenant_llm_credentials c
       where c.tenant_id = p_tenant_id and c.provider_key = v_key;

      if v_secret is not null then
        select decrypted_secret into v_val from vault.decrypted_secrets where id = v_secret;
        if coalesce(v_val, '') <> '' then
          v_out := v_out || jsonb_build_object(v_key,
            jsonb_build_object('ok', true, 'key', v_val, 'source', 'tenant'));
          continue;
        end if;
      end if;

      if coalesce(v_mode, 'platform') = 'byo' then
        v_out := v_out || jsonb_build_object(v_key, jsonb_build_object(
          'ok', false, 'source', 'byo_refused', 'reason',
          format('This workspace is set to use its own %s and none is configured. Add it in Settings > AI Engine, or switch the workspace to the platform key.', v_key)));
        continue;
      end if;
    end if;

    -- Platform secret, read straight from the vault for the same reason
    -- resolve_llm_key does: nesting platform_config_get would re-run a guard
    -- this function has already satisfied.
    v_val := null;
    select s.decrypted_secret into v_val
      from vault.decrypted_secrets s
      join platform_config pc on pc.secret_id = s.id
     where pc.key = v_key;

    if coalesce(v_val, '') <> '' then
      v_out := v_out || jsonb_build_object(v_key,
        jsonb_build_object('ok', true, 'key', v_val, 'source', 'platform'));
    else
      -- Absence, NOT refusal. The caller falls through to its env secret,
      -- which is the only reason env-only Bedrock stays in the chain.
      v_out := v_out || jsonb_build_object(v_key, jsonb_build_object(
        'ok', false, 'source', 'none', 'reason',
        format('No %s is configured for this workspace or for the platform.', v_key)));
    end if;
  end loop;

  return v_out;
end $function$;

CREATE OR REPLACE FUNCTION public.resolve_my_de_autonomy(p_action_type text, p_de_id uuid DEFAULT NULL::uuid, p_source_category text DEFAULT NULL::text)
 RETURNS TABLE(enabled boolean, max_amount_cents bigint, min_confidence integer)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_tenant uuid;
begin
  v_tenant := auth_tenant_id();
  if v_tenant is null then
    raise exception 'not a member of any tenant';
  end if;
  if p_de_id is not null and not public.can_access_de(p_de_id) then
    raise exception 'not_responsible_for_de';
  end if;
  return query select * from resolve_de_autonomy(v_tenant, p_action_type, p_de_id, p_source_category);
end;
$function$;

CREATE OR REPLACE FUNCTION public.resolve_onboarding_signoff(p_task_id uuid, p_decision text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_task      human_tasks;
  v_proj      onboarding_projects;
  v_ver       onboarding_template_versions;
  v_def       jsonb;
  v_item      jsonb;
  v_idx       integer := -1;
  v_i         integer := 0;
  v_key       text;
  v_completed boolean := false;
begin
  if p_decision not in ('approved', 'rejected') then
    return jsonb_build_object('error', 'invalid_decision');
  end if;

  select * into v_task from human_tasks where id = p_task_id;
  if not found or v_task.related_table <> 'onboarding_projects' or v_task.related_id is null then
    return jsonb_build_object('error', 'not_an_onboarding_task');
  end if;
  if not exists (
    select 1 from profiles where user_id = auth.uid() and tenant_id = v_task.tenant_id and coalesce(is_active, true) = true
  ) then
    raise exception 'not a member of this tenant';
  end if;

  select * into v_proj from onboarding_projects where id = v_task.related_id::uuid;
  if not found then return jsonb_build_object('error', 'project_not_found'); end if;

  for v_item in select * from jsonb_array_elements(v_proj.items_state) loop
    if v_item->>'signoff_task_id' = p_task_id::text then v_idx := v_i; exit; end if;
    v_i := v_i + 1;
  end loop;
  if v_idx < 0 then return jsonb_build_object('error', 'item_for_task_not_found'); end if;
  v_key := v_item->>'key';

  if v_item->>'status' = 'signed_off' then
    return jsonb_build_object('error', 'already_signed_off');
  end if;

  select * into v_ver from onboarding_template_versions where id = v_proj.template_version_id;
  select d into v_def from jsonb_array_elements(v_ver.items) d where d->>'key' = v_key limit 1;

  if p_decision = 'approved' then
    v_item := v_item || jsonb_build_object('status', 'signed_off', 'signed_off_by', auth.uid(), 'signed_off_at', now());
  else
    v_item := v_item || jsonb_build_object('status', 'in_progress',
      'note', trim(coalesce(v_item->>'note', '') || ' · Sign-off rejected — rework needed.', ' ·'),
      'signoff_task_id', null);
  end if;

  update onboarding_projects
    set items_state = jsonb_set(items_state, array[v_idx::text], v_item)
    where id = v_proj.id;

  perform append_audit_event_internal(
    v_task.tenant_id, 'You', 'human',
    format('Onboarding sign-off %s — %s (%s)', p_decision, coalesce(v_def->>'label', v_key), v_proj.name),
    'approval',
    jsonb_build_object('kind', 'onboarding_signoff', 'project_id', v_proj.id,
                       'item_key', v_key, 'task_id', p_task_id, 'decision', p_decision));

  if p_decision = 'approved' then
    v_completed := onboarding_check_complete(v_proj.id);
  end if;

  return jsonb_build_object('project_id', v_proj.id, 'item_key', v_key,
                            'decision', p_decision, 'completed', v_completed);
end;
$function$;

CREATE OR REPLACE FUNCTION public.resolve_opportunity_writeback(p_task_id uuid, p_decision text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r opportunity_writeback_requests; v_res jsonb;
BEGIN IF NOT coalesce(public.can_admin_tenant_internal((SELECT tenant_id FROM public.opportunity_writeback_requests WHERE task_id = p_task_id)), false) THEN RAISE EXCEPTION 'not permitted'; END IF;
  SELECT * INTO r FROM opportunity_writeback_requests WHERE task_id = p_task_id;
  IF r.id IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'no_request_for_task'); END IF;
  IF r.status <> 'pending_approval' THEN RETURN jsonb_build_object('ok', true, 'already', r.status); END IF;
  IF p_decision = 'approved' THEN
    v_res := public.apply_opportunity_writeback_internal(r.id);
    UPDATE opportunity_writeback_requests SET decided_at = now() WHERE id = r.id;
    BEGIN PERFORM append_audit_event_internal(r.tenant_id, 'You', 'human', 'Pipeline write-back APPROVED + applied — ' || r.request_summary, 'connector_action',
      jsonb_build_object('kind','opportunity_writeback','op',r.op,'request_id',r.id,'approved',true));
    EXCEPTION WHEN OTHERS THEN NULL; END;
    RETURN jsonb_build_object('ok', true, 'applied', true);
  ELSE
    UPDATE opportunity_writeback_requests SET status = 'rejected', decided_at = now() WHERE id = r.id;
    RETURN jsonb_build_object('ok', true, 'applied', false);
  END IF;
END; $function$;

CREATE OR REPLACE FUNCTION public.resolve_ops_alert(p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT public.is_platform_admin() THEN
    RAISE EXCEPTION 'resolve_ops_alert: platform admin only';
  END IF;
  UPDATE ops_alerts SET resolved_at = now() WHERE id = p_id AND resolved_at IS NULL;
  RETURN jsonb_build_object('ok', FOUND);
END $function$;

CREATE OR REPLACE FUNCTION public.resolve_platform_capability(p_user_id uuid, p_capability text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_layer  text;
  v_role   text;
  v_active boolean;
  v_override text;
  v_role_default boolean;
begin
  select layer, role, coalesce(is_active, true) into v_layer, v_role, v_active
  from profiles where user_id = p_user_id;

  if v_layer is distinct from 'platform' or not coalesce(v_active, false) then
    return false;
  end if;

  select effect into v_override
  from platform_capability_grants
  where user_id = p_user_id and capability = p_capability;

  if v_override = 'grant' then return true; end if;
  if v_override = 'deny' then return false; end if;

  -- Role defaults — the fallback when no explicit override exists.
  -- platform_super_admin: everything (matches today's real behavior
  -- exactly, since is_platform_admin() has never differentiated).
  -- platform_support: what a support function actually needs —
  -- remote access to help a customer, cross-tenant task visibility,
  -- tenant/audit visibility — not tenant/team/billing control.
  -- platform_billing: visibility + LLM-provider-key control — not
  -- remote access or team power.
  v_role_default := case v_role
    when 'platform_super_admin' then true
    when 'platform_support' then p_capability in
      ('tenants.view', 'remote_access.use', 'remote_access.audit', 'support.cross_tenant')
    when 'platform_billing' then p_capability in
      ('tenants.view', 'remote_access.audit', 'billing.manage')
    else false
  end;

  return coalesce(v_role_default, false);
end;
$function$;

CREATE OR REPLACE FUNCTION public.resolve_remote_access_tenant(p_operator_user_id uuid, p_asserted_tenant_id uuid)
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select e.tenant_id
  from platform_access_events e
  where e.operator_user_id = p_operator_user_id
    and e.event = 'start'
    and e.tenant_id = p_asserted_tenant_id
    and e.created_at > now() - interval '12 hours'
    and exists (
      select 1 from profiles p
      where p.user_id = p_operator_user_id and p.layer = 'platform' and coalesce(p.is_active, true) = true
    )
    and e.id = (
      select e2.id from platform_access_events e2
      where e2.operator_user_id = p_operator_user_id
      order by e2.created_at desc
      limit 1
    )
  limit 1;
$function$;

CREATE OR REPLACE FUNCTION public.resolve_review_minutes(p_tenant_id uuid, p_task_type text)
 RETURNS numeric
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce(
    (select minutes from review_time_standards
      where tenant_id = p_tenant_id and task_type = p_task_type),
    (select minutes from review_time_standards
      where tenant_id is null and task_type = p_task_type),
    3)
$function$;

CREATE OR REPLACE FUNCTION public.resolve_review_narrative_settings(p_tenant_id uuid, p_de_id uuid)
 RETURNS TABLE(enabled boolean, instructions text, scope text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select s.enabled, s.instructions,
         case when s.de_id is null then 'workspace' else 'employee' end
    from public.de_review_narrative_settings s
   where s.tenant_id = p_tenant_id
     and (s.de_id = p_de_id or s.de_id is null)
   -- Specific first. Same shape as the autonomy chain (mig 618): the more
   -- specific row wins, and there is at most one of each.
   order by (s.de_id is not null) desc
   limit 1;
$function$;

CREATE OR REPLACE FUNCTION public.resolve_work_item_framing(p_tenant_id uuid, p_category text)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce(
    (select template from work_item_framing where scope = 'tenant' and tenant_id = p_tenant_id and category = p_category),
    (select template from work_item_framing where scope = 'platform' and category = p_category),
    'New {category} item needs review: {title} — {snippet}'
  );
$function$;

CREATE OR REPLACE FUNCTION public.respond_de_task(p_request_id uuid, p_status text, p_result text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r de_task_requests; v_to_name text; v_is_service boolean := coalesce(auth.role(),'') = 'service_role';
BEGIN
  IF p_status NOT IN ('accepted','in_progress','completed','declined','failed') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'bad_status');
  END IF;
  SELECT * INTO r FROM de_task_requests WHERE id = p_request_id;
  IF r.id IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'not_found'); END IF;
  IF NOT v_is_service AND r.tenant_id IS DISTINCT FROM public.auth_tenant_id() THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_tenant_member');
  END IF;
  -- DE scoping (mig 385/438). Guarded on the RECEIVER (to_de_id, NOT NULL):
  -- it is the receiver that acts, and a terminal status concludes or blocks
  -- its objective. Same non-service condition as the tenant check above, so
  -- the two can never disagree about who is a trusted caller.
  IF NOT v_is_service AND NOT public.can_access_de(r.to_de_id) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_responsible_for_de');
  END IF;
  IF r.status IN ('completed','declined','failed') THEN
    RETURN jsonb_build_object('ok', true, 'already', r.status);
  END IF;

  SELECT coalesce(persona_name, name) INTO v_to_name FROM digital_employees WHERE id = r.to_de_id;
  UPDATE de_task_requests
     SET status = p_status,
         result = coalesce(left(p_result, 4000), result),
         responded_at = coalesce(responded_at, now()),
         completed_at = CASE WHEN p_status IN ('completed','declined','failed') THEN now() ELSE completed_at END
   WHERE id = p_request_id;

  -- Reflect terminal states onto the receiver's case so the work engine closes it.
  -- §3 W4: 'completed' → 'achieved' now routes through conclude_objective_verified
  -- (assess + log + withhold-on-enforce); 'declined'/'failed' → 'blocked' unchanged.
  IF p_status IN ('completed','declined','failed') AND r.objective_id IS NOT NULL THEN
    IF p_status = 'completed' THEN
      PERFORM public.conclude_objective_verified(r.tenant_id, r.objective_id, 'achieved', 'cross-DE task completed');
    ELSE
      UPDATE de_objectives SET status = 'blocked' WHERE id = r.objective_id;
    END IF;
  END IF;

  BEGIN PERFORM append_audit_event_internal(r.tenant_id, coalesce(v_to_name,'DE'), 'de',
    coalesce(v_to_name,'DE') || ' marked task "' || r.title || '" as ' || p_status, 'de_consultation',
    jsonb_build_object('kind','de_task_response','request_id',r.id,'status',p_status));
  EXCEPTION WHEN OTHERS THEN NULL; END;

  RETURN jsonb_build_object('ok', true, 'status', p_status);
END; $function$;

CREATE OR REPLACE FUNCTION public.response_window_due_at(p_config jsonb, p_from timestamp with time zone)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
DECLARE w jsonb; u text; a text;
BEGIN
  w := p_config -> 'response_window';
  IF w IS NOT NULL AND jsonb_typeof(w) = 'object' THEN
    u := w->>'unit'; a := w->>'amount';

    -- A specific calendar instant: absolute, identical for every case this
    -- watcher opens. If it has already passed, the case opens overdue — which
    -- is the honest reading, because by the declared standard it IS late.
    IF u = 'date' THEN
      BEGIN
        RETURN (w->>'at')::timestamptz;
      EXCEPTION WHEN OTHERS THEN
        RETURN NULL;
      END;

    -- A duration, measured from the moment the case opened.
    ELSIF u IN ('minutes','hours','days') AND a ~ '^[0-9]{1,9}$' AND a::int > 0 THEN
      RETURN CASE u
        WHEN 'minutes' THEN p_from + make_interval(mins  => least(a::int, 5256000))
        WHEN 'hours'   THEN p_from + make_interval(hours => least(a::int, 87600))
        ELSE                p_from + make_interval(days  => least(a::int, 3650))
      END;
    END IF;
    RETURN NULL;
  END IF;

  -- Legacy shape from mig 515. Nothing outside migrations ever read it, and the
  -- rewrite below clears it, but a tenant restored from an older dump must not
  -- silently lose its declared standard.
  IF (p_config->>'response_days') ~ '^[0-9]{1,9}$' AND (p_config->>'response_days')::int > 0 THEN
    RETURN p_from + make_interval(days => least((p_config->>'response_days')::int, 3650));
  END IF;

  RETURN NULL;
END $function$;

CREATE OR REPLACE FUNCTION public.restore_guardrail_rule(p_rule_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_rule guardrail_rules;
  v_next guardrail_rules;
begin
  select * into v_rule from guardrail_rules where id = p_rule_id;
  if v_rule.id is null then
    raise exception 'guardrail rule not found';
  end if;

  if not exists (
    select 1 from profiles p
     where p.user_id = auth.uid()
       and (p.layer = 'platform'
            or (p.tenant_id = v_rule.tenant_id and p.role in ('tenant_owner', 'tenant_admin')))
  ) then
    raise exception 'only workspace owners and admins can restore a guardrail';
  end if;

  -- ⚠ ADDED BY 747. A pack rule cannot come back one at a time, in either
  -- direction: retire refuses it going out, and the trigger refuses the
  -- `active = false` this function writes coming back in. Said in words here
  -- rather than surfaced as the trigger's raw text, and it names the door that
  -- is actually open — the pack, whole.
  if v_rule.compliance_pack_key is not null then
    raise exception 'compliance guardrail (%): it belongs to a pack, so it cannot be restored on its own — put the pack back instead, under Compliance & Guardrails or by hiring a role that needs it, and all of its rules come back together', v_rule.compliance_pack_key;
  end if;

  if v_rule.retired_at is null then
    return jsonb_build_object('ok', true, 'already_live', true,
      'rule_id', v_rule.id, 'active', v_rule.active, 'version', v_rule.version);
  end if;

  update guardrail_rules
     set retired_at = null,
         retired_by = null,
         -- ⚠ STAYS OFF. Un-retiring restores the row to the list; deciding to
         -- enforce it again is a separate, visible act on the Active toggle.
         active     = false,
         version    = version + 1
   where id = p_rule_id
  returning * into v_next;

  perform append_audit_event(
    v_rule.tenant_id, 'You', 'human',
    format('Guardrail restored — "%s" (%s). It is back in the list, still switched off.',
           v_rule.rule, v_rule.rule_type),
    'config_change',
    jsonb_build_object(
      'event', 'guardrail_restored',
      'rule_id', v_rule.id, 'rule', v_rule.rule, 'rule_type', v_rule.rule_type,
      'retired_at_was', v_rule.retired_at, 'version', v_next.version));

  return jsonb_build_object('ok', true, 'rule_id', v_next.id, 'active', false,
    'version', v_next.version);
end;
$function$;

CREATE OR REPLACE FUNCTION public.resume_de_work_from_decision(p_task_id uuid, p_disposition text, p_instruction text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_task human_tasks;
  v_item de_work_items;
  v_moved uuid;
  v_instruction text;
begin
  select * into v_task from human_tasks where id = p_task_id;
  if v_task.id is null then return null; end if;
  if v_task.related_table is distinct from 'de_work_items' or v_task.related_id is null then
    return null;
  end if;

  select * into v_item from de_work_items where id = v_task.related_id and tenant_id = v_task.tenant_id;
  if v_item.id is null then return null; end if;

  v_instruction := nullif(btrim(coalesce(p_instruction, '')), '');

  if p_disposition = 'answered' then
    update de_work_items set
      status = 'queued', scheduled_for = now(), attempts = 0, last_error = null,
      locked_at = null, locked_by = null, updated_at = now(),
      payload = payload || jsonb_build_object(
        'detail', left(coalesce(payload->>'detail','')
          || E'\n\nHUMAN RULING: this task was answered by a person.'
          || case when v_instruction is not null then ' Instruction: ' || v_instruction else '' end
          || ' Act on it now; do not raise this same escalation again.', 4000),
        'human_ruling', jsonb_build_object('task_id', p_task_id,
          'disposition', p_disposition, 'instruction', v_instruction, 'decided_at', now()))
    where id = v_item.id and status = 'waiting_human'
    returning id into v_moved;

  elsif p_disposition = 'cancelled' then
    update de_work_items set
      status = 'cancelled', locked_at = null, locked_by = null, updated_at = now(),
      result = coalesce(result, '{}'::jsonb) || jsonb_build_object(
        'summary', left('Cancelled by a person'
          || case when v_instruction is not null then ': ' || v_instruction
                  else ' without a stated reason.' end, 500),
        'human_ruling', jsonb_build_object('task_id', p_task_id,
          'disposition', p_disposition, 'instruction', v_instruction, 'decided_at', now()))
    where id = v_item.id and status = 'waiting_human'
    returning id into v_moved;

    if v_moved is not null then
      with recursive chain as (
        select w.id from de_work_items w
         where w.depends_on = v_item.id and w.tenant_id = v_task.tenant_id
           and w.status in ('queued','waiting_human')
        union all
        select w2.id from de_work_items w2 join chain c on w2.depends_on = c.id
         where w2.status in ('queued','waiting_human')
      )
      update de_work_items w set status = 'cancelled',
             last_error = 'predecessor cancelled by human decision', updated_at = now()
        from chain where w.id = chain.id;
    end if;

  elsif p_disposition = 'rerouted' then
    update de_work_items set
      updated_at = now(),
      payload = payload || jsonb_build_object('rerouted', jsonb_build_object(
        'task_id', p_task_id, 'note', v_instruction, 'at', now()))
    where id = v_item.id and status = 'waiting_human'
    returning id into v_moved;
  end if;

  update de_exceptions set
    status = case when p_disposition = 'answered' then 'approved'
                  when p_disposition = 'cancelled' then 'denied'
                  else status end,
    outcome = coalesce(v_instruction, outcome),
    decided_at = case when p_disposition in ('answered','cancelled') then now() else decided_at end
  where human_task_id = p_task_id and status = 'proposed';

  -- Record WHAT was decided, not merely that something was.
  update human_tasks
     set resolved_work_item_id = v_moved,
         disposition = coalesce(disposition, p_disposition)
   where id = p_task_id;

  update de_objectives o set
    next_wake_at = least(coalesce(o.next_wake_at, now()), now()),
    attention_flag = null, attention_since = null, updated_at = now()
  where o.id = v_item.objective_id and o.status in ('open','in_progress','blocked');

  return v_moved;
end;
$function$;

CREATE OR REPLACE FUNCTION public.resume_digital_employee(p_de_id uuid, p_note text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tenant uuid;
  v_de digital_employees;
  v_actor_name text;
  v_back_to text;
begin
  if p_note is null or trim(p_note) = '' then
    raise exception 'resuming requires a note on what was investigated/remediated';
  end if;
  v_tenant := auth_tenant_id();
  if v_tenant is null then raise exception 'not a member of any tenant'; end if;
  if not auth_has_tenant_role(array['tenant_owner', 'tenant_admin']) then
    raise exception 'only workspace owners/admins can resume a Digital Employee';
  end if;
  select * into v_de from digital_employees where id = p_de_id and tenant_id = v_tenant;
  if v_de.id is null then raise exception 'employee not found in this workspace'; end if;
  if v_de.lifecycle_status <> 'paused' then raise exception 'this employee is not paused'; end if;

  -- Return to the stage the employee paused FROM (the last pause
  -- event's from_stage) — falling back to 'assigned' if history is
  -- missing. Open development items pull it to 'improving' on the next
  -- sync, matching §8's "returns to Active or Improving".
  select from_stage into v_back_to from de_lifecycle_events
  where tenant_id = v_tenant and de_id = p_de_id and to_stage = 'paused'
  order by created_at desc limit 1;
  v_back_to := coalesce(v_back_to, 'assigned');

  select full_name into v_actor_name from profiles where user_id = auth.uid();

  update digital_employees set lifecycle_status = v_back_to, status = case when v_back_to in ('designed','configured','trained','tested','certified') then 'idle' else 'active' end, updated_at = now()
  where id = p_de_id;

  insert into de_lifecycle_events (tenant_id, de_id, from_stage, to_stage, actor_id, actor_label, note)
  values (v_tenant, p_de_id, 'paused', v_back_to, auth.uid(), coalesce(v_actor_name, 'A workspace admin'), p_note);

  perform append_audit_event_internal(
    v_tenant, coalesce(v_actor_name, 'A workspace admin'), 'human',
    format('%s resumed to %s — "%s"', v_de.name, v_back_to, left(p_note, 200)),
    'config_change',
    jsonb_build_object('kind', 'de_resumed', 'de_id', p_de_id, 'to', v_back_to, 'note', p_note)
  );

  return jsonb_build_object('ok', true, 'stage', v_back_to);
end;
$function$;

CREATE OR REPLACE FUNCTION public.resume_playbook_on_task(p_task_id uuid, p_decision text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_run     playbook_runs;
  v_steps   jsonb;
  v_acct    text;
  v_inv     record;
  v_now     text := to_char(now() at time zone 'utc', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"');
  i         integer;
  v_step    jsonb;
  v_key     text;
  v_params  jsonb;
  v_ctx     jsonb;
  v_text    text;
  v_tbl     text;
  v_set     text;
  v_detail  text;
  v_gate_key text;
  v_waiver  text;
begin
  if p_decision not in ('approved', 'rejected') then
    raise exception 'decision must be approved or rejected';
  end if;

  select * into v_run
  from playbook_runs
  where waiting_task_id = p_task_id
    and status = 'waiting_approval'
  limit 1;

  if not found then
    return jsonb_build_object('resumed', false, 'reason', 'no_waiting_run');
  end if;

  if coalesce(auth.role(), '') <> 'service_role' and not exists (
    select 1 from profiles where user_id = auth.uid() and tenant_id = v_run.tenant_id and coalesce(is_active, true) = true
  ) then
    raise exception 'not a member of this tenant';
  end if;

  v_steps := v_run.steps;
  v_ctx   := coalesce(v_run.context, '{}'::jsonb);
  v_acct  := coalesce(nullif(v_ctx->>'account_name', ''),
             coalesce(nullif(split_part(v_steps->0->>'detail', ' · ', 1), ''), 'account'));

  -- ══════════════════════════════════════════════════════════
  -- LEGACY PATH: renewal_v1 (no definition) — unchanged behavior
  -- ══════════════════════════════════════════════════════════
  if v_run.definition_id is null then
    if p_decision = 'rejected' then
      v_steps := jsonb_set(v_steps, '{3,status}', '"cancelled"');
      v_steps := jsonb_set(v_steps, '{3,at}', to_jsonb(v_now));
      v_steps := jsonb_set(v_steps, '{3,detail}', '"Rejected by human reviewer"');
      for i in 4 .. jsonb_array_length(v_steps) - 1 loop
        if v_steps->i->>'status' = 'pending' then
          v_steps := jsonb_set(v_steps, array[i::text, 'status'], '"cancelled"');
        end if;
      end loop;
      update playbook_runs
        set status = 'cancelled', current_step = 3, steps = v_steps, waiting_task_id = null
        where id = v_run.id;
      perform append_audit_event(
        v_run.tenant_id, 'Renewal DE', 'de',
        format('Renewal playbook [%s] — run cancelled (approval rejected)', v_acct),
        'playbook_step',
        jsonb_build_object('run_id', v_run.id, 'task_id', p_task_id, 'resumed_by', 'resume_playbook_on_task')
      );
      return jsonb_build_object('resumed', true, 'run_id', v_run.id, 'status', 'cancelled');
    end if;

    v_steps := jsonb_set(v_steps, '{3,status}', '"done"');
    v_steps := jsonb_set(v_steps, '{3,at}', to_jsonb(v_now));
    v_steps := jsonb_set(v_steps, '{3,detail}', '"Approved by human reviewer"');
    perform append_audit_event(
      v_run.tenant_id, 'Renewal DE', 'de',
      format('Renewal playbook [%s] — step "Human approval" done: Approved by human reviewer', v_acct),
      'playbook_step',
      jsonb_build_object('run_id', v_run.id, 'step_key', 'human_approval', 'step_status', 'done', 'task_id', p_task_id)
    );

    select id, amount_cents into v_inv
    from renewal_invoices
    where tenant_id = v_run.tenant_id and account_id = v_run.account_id
    order by created_at desc
    limit 1;

    if v_inv.id is not null then
      update renewal_invoices set status = 'sent', cadence_stage = 1 where id = v_inv.id;
      v_steps := jsonb_set(v_steps, '{4,status}', '"done"');
      v_steps := jsonb_set(v_steps, '{4,at}', to_jsonb(v_now));
      v_steps := jsonb_set(v_steps, '{4,detail}',
        to_jsonb(format('Invoice $%s sent · cadence Day-0 started', to_char(round(v_inv.amount_cents / 100.0), 'FM999,999,999'))));
      perform append_audit_event(
        v_run.tenant_id, 'Renewal DE', 'de',
        format('Renewal playbook [%s] — step "Send invoice" done: %s', v_acct, v_steps->4->>'detail'),
        'playbook_step',
        jsonb_build_object('run_id', v_run.id, 'step_key', 'mark_sent', 'step_status', 'done', 'invoice_id', v_inv.id)
      );
      insert into activity_events (tenant_id, actor, actor_type, event_type, text)
      values (v_run.tenant_id, 'Renewal DE', 'de', 'resolved',
        format('Renewal playbook sent invoice — %s ($%s), dunning cadence started',
          v_acct, to_char(round(v_inv.amount_cents / 100.0), 'FM999,999,999')));
    else
      v_steps := jsonb_set(v_steps, '{4,status}', '"skipped"');
      v_steps := jsonb_set(v_steps, '{4,at}', to_jsonb(v_now));
      v_steps := jsonb_set(v_steps, '{4,detail}', '"Invoice not found for cadence update"');
    end if;

    v_steps := jsonb_set(v_steps, '{5,status}', '"done"');
    v_steps := jsonb_set(v_steps, '{5,at}', to_jsonb(v_now));
    v_steps := jsonb_set(v_steps, '{5,detail}', '"Run completed"');

    update playbook_runs
      set status = 'completed', current_step = 5, steps = v_steps, waiting_task_id = null
      where id = v_run.id;

    perform append_audit_event(
      v_run.tenant_id, 'Renewal DE', 'de',
      format('Renewal playbook [%s] — run completed end-to-end', v_acct),
      'playbook_step',
      jsonb_build_object('run_id', v_run.id, 'invoice_id', v_inv.id, 'amount_cents', v_inv.amount_cents, 'resumed_by', 'resume_playbook_on_task')
    );

    return jsonb_build_object('resumed', true, 'run_id', v_run.id, 'status', 'completed');
  end if;

  -- ══════════════════════════════════════════════════════════
  -- DEFINITION PATH: SQL advances guardrail_check / update_record /
  -- log_activity / complete natively. ANY other step (connector_action,
  -- instruction, decision, checklist, wait, sub_playbook, consult) parks
  -- the run in 'resume_pending' — the HTTP executor finishes it.
  -- ══════════════════════════════════════════════════════════
  i := v_run.current_step;  -- index of the gate step (human_approval, checklist or gap_gate)
  v_gate_key := coalesce(v_steps->i->>'key', 'human_approval');

  if p_decision = 'rejected' then
    v_steps := jsonb_set(v_steps, array[i::text, 'status'], '"cancelled"');
    v_steps := jsonb_set(v_steps, array[i::text, 'at'], to_jsonb(v_now));
    v_steps := jsonb_set(v_steps, array[i::text, 'detail'],
      (case when v_gate_key = 'checklist' then '"Checklist rejected by human reviewer"'
            when v_gate_key = 'gap_gate' then '"Run cancelled at the gap gate — the gap is unanswered and the human chose not to continue"'
            else '"Rejected by human reviewer"' end)::jsonb);
    for i in v_run.current_step + 1 .. jsonb_array_length(v_steps) - 1 loop
      if v_steps->i->>'status' = 'pending' then
        v_steps := jsonb_set(v_steps, array[i::text, 'status'], '"cancelled"');
      end if;
    end loop;
    update playbook_runs
      set status = 'cancelled', steps = v_steps, waiting_task_id = null
      where id = v_run.id;
    perform append_audit_event(
      v_run.tenant_id, 'Playbook DE', 'de',
      format('Playbook [%s] — run cancelled (%s rejected)', v_acct,
        case when v_gate_key = 'checklist' then 'checklist'
             when v_gate_key = 'gap_gate' then 'gap gate'
             else 'approval' end),
      'playbook_step',
      jsonb_build_object('run_id', v_run.id, 'task_id', p_task_id, 'definition_id', v_run.definition_id, 'resumed_by', 'resume_playbook_on_task')
    );
    return jsonb_build_object('resumed', true, 'run_id', v_run.id, 'status', 'cancelled');
  end if;

  -- Approved. A gap_gate NEVER becomes "done": approval means "skip this
  -- step for THIS run, gap still open" — recorded as the waiver it is.
  if v_gate_key = 'gap_gate' then
    v_waiver := format('skipped — gap unanswered, step waived for this run by human decision (task %s)', p_task_id);
    v_steps := jsonb_set(v_steps, array[i::text, 'status'], '"skipped"');
    v_steps := jsonb_set(v_steps, array[i::text, 'at'], to_jsonb(v_now));
    v_steps := jsonb_set(v_steps, array[i::text, 'detail'], to_jsonb(v_waiver));
    perform append_audit_event(
      v_run.tenant_id, 'Playbook DE', 'de',
      format('Playbook [%s] — gap gate "%s" skipped for this run (gap stays open; answering it unblocks the next published version)',
        v_acct, coalesce(v_steps->i->>'label', 'gap gate')),
      'playbook_step',
      jsonb_build_object('run_id', v_run.id, 'step_key', 'gap_gate', 'step_status', 'skipped',
        'task_id', p_task_id, 'definition_id', v_run.definition_id,
        'gap_id', v_steps->i->'params'->>'gap_id')
    );
  else
    -- Gate step done. If the gate approved an invoice, send it.
    v_steps := jsonb_set(v_steps, array[i::text, 'status'], '"done"');
    v_steps := jsonb_set(v_steps, array[i::text, 'at'], to_jsonb(v_now));
    v_steps := jsonb_set(v_steps, array[i::text, 'detail'],
      (case when v_gate_key = 'checklist' then '"Checklist completed — all items confirmed by a human"' else '"Approved by human reviewer"' end)::jsonb);
    perform append_audit_event(
      v_run.tenant_id, 'Playbook DE', 'de',
      format('Playbook [%s] — step "%s" done: %s', v_acct,
        case when v_gate_key = 'checklist' then 'Checklist' else 'Human approval' end,
        case when v_gate_key = 'checklist' then 'all items confirmed' else 'approved' end),
      'playbook_step',
      jsonb_build_object('run_id', v_run.id, 'step_key', v_gate_key, 'step_status', 'done', 'task_id', p_task_id, 'definition_id', v_run.definition_id)
    );
    if v_gate_key = 'human_approval' and (v_ctx->>'invoice_id') is not null then
      update renewal_invoices set status = 'sent', cadence_stage = 1
        where id = (v_ctx->>'invoice_id')::uuid and status = 'awaiting_approval';
    end if;
  end if;

  -- Walk the remaining steps.
  i := v_run.current_step + 1;
  while i <= jsonb_array_length(v_steps) - 1 loop
    v_step   := v_steps->i;
    v_key    := v_step->>'key';
    v_params := coalesce(v_step->'params', '{}'::jsonb);

    if v_key = 'guardrail_check' then
      v_detail := format('Re-checked invoice threshold post-approval — amount $%s (approved by human)',
        to_char(round(coalesce((v_ctx->>'invoice_amount_cents')::bigint, 0) / 100.0), 'FM999,999,999'));
      v_steps := jsonb_set(v_steps, array[i::text, 'status'], '"done"');
      v_steps := jsonb_set(v_steps, array[i::text, 'at'], to_jsonb(v_now));
      v_steps := jsonb_set(v_steps, array[i::text, 'detail'], to_jsonb(v_detail));
      perform append_audit_event(
        v_run.tenant_id, 'Playbook DE', 'de',
        format('Playbook [%s] — step "Guardrail check" done: %s', v_acct, v_detail),
        'guardrail_check',
        jsonb_build_object('run_id', v_run.id, 'step_index', i, 'definition_id', v_run.definition_id, 'result', 'passed_post_approval')
      );

    elsif v_key = 'update_record' then
      v_tbl := v_params->>'table';
      v_set := v_params#>>'{set,status}';
      v_detail := null;
      if v_tbl = 'renewal_invoices' and v_set in ('sent', 'paid') and (v_ctx->>'invoice_id') is not null then
        update renewal_invoices set status = v_set where id = (v_ctx->>'invoice_id')::uuid;
        v_detail := format('renewal_invoices.status → %s', v_set);
      elsif v_tbl = 'support_tickets' and v_set in ('open', 'pending', 'resolved', 'escalated') and (v_ctx->>'ticket_id') is not null then
        update support_tickets set status = v_set where id = (v_ctx->>'ticket_id')::uuid and tenant_id = v_run.tenant_id;
        v_detail := format('support_tickets.status → %s', v_set);
      end if;
      if v_detail is null then
        v_steps := jsonb_set(v_steps, array[i::text, 'status'], '"skipped"');
        v_steps := jsonb_set(v_steps, array[i::text, 'detail'], '"skipped: no target record in run context"');
      else
        v_steps := jsonb_set(v_steps, array[i::text, 'status'], '"done"');
        v_steps := jsonb_set(v_steps, array[i::text, 'detail'], to_jsonb(v_detail));
      end if;
      v_steps := jsonb_set(v_steps, array[i::text, 'at'], to_jsonb(v_now));
      perform append_audit_event(
        v_run.tenant_id, 'Playbook DE', 'de',
        format('Playbook [%s] — step "Update record" %s', v_acct, coalesce(v_detail, 'skipped: no target record')),
        'playbook_step',
        jsonb_build_object('run_id', v_run.id, 'step_index', i, 'definition_id', v_run.definition_id)
      );

    elsif v_key = 'log_activity' then
      v_text := coalesce(v_params->>'text_template', 'Playbook step executed');
      v_text := replace(v_text, '{{account.name}}', coalesce(v_ctx->>'account_name', 'account'));
      v_text := replace(v_text, '{{invoice.amount}}',
        '$' || to_char(round(coalesce((v_ctx->>'invoice_amount_cents')::bigint, 0) / 100.0), 'FM999,999,999'));
      v_text := replace(v_text, '{{run.id}}', v_run.id::text);
      insert into activity_events (tenant_id, actor, actor_type, event_type, text)
      values (v_run.tenant_id, 'Playbook DE', 'de', 'resolved', v_text);
      v_steps := jsonb_set(v_steps, array[i::text, 'status'], '"done"');
      v_steps := jsonb_set(v_steps, array[i::text, 'at'], to_jsonb(v_now));
      v_steps := jsonb_set(v_steps, array[i::text, 'detail'], to_jsonb(v_text));
      perform append_audit_event(
        v_run.tenant_id, 'Playbook DE', 'de',
        format('Playbook [%s] — step "Log activity" done: %s', v_acct, v_text),
        'playbook_step',
        jsonb_build_object('run_id', v_run.id, 'step_index', i, 'definition_id', v_run.definition_id)
      );

    elsif v_key = 'complete' then
      v_steps := jsonb_set(v_steps, array[i::text, 'status'], '"done"');
      v_steps := jsonb_set(v_steps, array[i::text, 'at'], to_jsonb(v_now));
      v_steps := jsonb_set(v_steps, array[i::text, 'detail'], '"Run completed"');
      update playbook_runs
        set status = 'completed', current_step = i, steps = v_steps, waiting_task_id = null, context = v_ctx
        where id = v_run.id;
      perform append_audit_event(
        v_run.tenant_id, 'Playbook DE', 'de',
        format('Playbook [%s] — run completed end-to-end', v_acct),
        'playbook_step',
        jsonb_build_object('run_id', v_run.id, 'definition_id', v_run.definition_id, 'resumed_by', 'resume_playbook_on_task')
      );
      return jsonb_build_object('resumed', true, 'run_id', v_run.id, 'status', 'completed');

    else
      -- Needs the HTTP executor (connector_action, instruction, decision,
      -- checklist, wait, sub_playbook, gap_gate, …) — park the run; the
      -- edge function's 'advance' action finishes it. A gap_gate met here
      -- pauses again through its own executor case: two outcomes only.
      update playbook_runs
        set status = 'resume_pending', current_step = i, steps = v_steps, waiting_task_id = null, context = v_ctx
        where id = v_run.id;
      perform append_audit_event(
        v_run.tenant_id, 'Playbook DE', 'de',
        format('Playbook [%s] — approved; parked at "%s" step for HTTP advance', v_acct, v_key),
        'playbook_step',
        jsonb_build_object('run_id', v_run.id, 'step_index', i, 'step_key', v_key, 'definition_id', v_run.definition_id, 'resumed_by', 'resume_playbook_on_task')
      );
      return jsonb_build_object('resumed', true, 'run_id', v_run.id, 'status', 'resume_pending', 'needs_http', true);
    end if;

    i := i + 1;
  end loop;

  update playbook_runs
    set status = 'completed', steps = v_steps, waiting_task_id = null, context = v_ctx
    where id = v_run.id;
  return jsonb_build_object('resumed', true, 'run_id', v_run.id, 'status', 'completed');
end
$function$;

CREATE OR REPLACE FUNCTION public.resume_workforce_autonomy(p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_tenant uuid := auth_tenant_id();
begin
  if v_tenant is null then raise exception 'not_authenticated'; end if;
  if not auth_has_tenant_role(array['tenant_owner','tenant_admin']) then
    raise exception 'not_allowed: only an owner or admin may restart the workforce';
  end if;

  update workforce_trust_posture set
    autonomy_paused = false, paused_at = null, paused_by = null, paused_reason = null,
    breaker_tripped_at = null, breaker_tripped_why = null,
    updated_at = now(), updated_by = auth.uid()
  where tenant_id = v_tenant;

  perform append_audit_event(v_tenant,
    coalesce((select full_name from profiles where user_id = auth.uid()), 'A workspace admin'),
    'human',
    format('Workforce autonomy RESTARTED%s', case when coalesce(btrim(p_note),'') <> '' then ' — ' || btrim(p_note) else '' end),
    'config_change',
    jsonb_build_object('kind', 'workforce_autonomy_resumed', 'note', nullif(btrim(p_note), '')));

  return jsonb_build_object('ok', true, 'paused', false);
end;
$function$;

CREATE OR REPLACE FUNCTION public.retire_guardrail_rule(p_rule_id uuid, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_rule guardrail_rules;
  v_next guardrail_rules;
begin
  select * into v_rule from guardrail_rules where id = p_rule_id;
  if v_rule.id is null then
    raise exception 'guardrail rule not found';
  end if;

  -- Same authority as set_rule_adjudicable: owner/admin of THAT rule's tenant,
  -- or platform. Reading the tenant off the ROW, never off a parameter — a
  -- tenant id supplied by the caller is not authorisation (mig 662-664).
  if not exists (
    select 1 from profiles p
     where p.user_id = auth.uid()
       and (p.layer = 'platform'
            or (p.tenant_id = v_rule.tenant_id and p.role in ('tenant_owner', 'tenant_admin')))
  ) then
    raise exception 'only workspace owners and admins can retire a guardrail';
  end if;

  -- A pack rule is a materialised copy of a shared catalogue entry, and
  -- trg_guard_compliance_guardrails refuses to switch one off. Retiring IS
  -- switching one off, so say what the operation actually is.
  if v_rule.compliance_pack_key is not null then
    raise exception 'compliance guardrail (%): it belongs to a pack — detach the pack instead of retiring one of its rules', v_rule.compliance_pack_key;
  end if;

  if v_rule.retired_at is not null then
    return jsonb_build_object('ok', true, 'already_retired', true,
      'rule_id', v_rule.id, 'retired_at', v_rule.retired_at, 'version', v_rule.version);
  end if;

  update guardrail_rules
     set retired_at = now(),
         retired_by = auth.uid(),
         -- ⚠ THIS LINE is what stops enforcement. retired_at is the filing
         -- decision; active=false is the effect, and every reader asks it.
         active     = false,
         version    = version + 1
   where id = p_rule_id
  returning * into v_next;

  -- Same transaction, and the return value is discarded but the EXCEPTION is
  -- not: append_audit_event raises on failure, so no audit row means no
  -- retirement. The full rule is frozen into detail because the row can later
  -- be edited and there is no version history anywhere else.
  perform append_audit_event(
    v_rule.tenant_id, 'You', 'human',
    format('Guardrail retired — "%s" (%s). It no longer applies; the record of what it blocked is kept.',
           v_rule.rule, v_rule.rule_type),
    'config_change',
    jsonb_build_object(
      'event', 'guardrail_retired',
      'rule_id', v_rule.id, 'rule', v_rule.rule, 'rule_type', v_rule.rule_type,
      'pattern', v_rule.pattern, 'threshold', v_rule.threshold,
      'severity', v_rule.severity, 'scope', v_rule.scope, 'scope_ref', v_rule.scope_ref,
      'was_active', v_rule.active, 'version', v_next.version,
      'reason', nullif(btrim(coalesce(p_reason, '')), '')));

  return jsonb_build_object('ok', true, 'rule_id', v_next.id,
    'retired_at', v_next.retired_at, 'version', v_next.version);
end;
$function$;

CREATE OR REPLACE FUNCTION public.retire_playbook_knowledge()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.status = 'archived' and coalesce(old.status, '') <> 'archived' then
    update knowledge_docs
      set is_current = false
      where tenant_id = new.tenant_id
        and external_ref = 'playbook:' || new.id::text;
  end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.retry_answerable_blockers(p_tenant_id uuid, p_limit integer DEFAULT 100)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_retried int := 0;
  v_skipped int := 0;
  r record;
begin
  if auth.role() is not null and auth.role() <> 'service_role' then
    if auth.uid() is null then raise exception 'not_authenticated'; end if;
    if not auth_has_tenant_role(array['tenant_owner','tenant_admin','tenant_manager']) then
      raise exception 'insufficient_role';
    end if;
  end if;

  -- mig 487: this is a sanctioned path for touching decision columns.
  perform set_config('app.allow_task_decision', 'on', true);

  for r in
    -- Drive from the BLOCKED ITEM, not from how somebody happened to file the
    -- escalation. mig 513 drove from human_tasks.related_table='de_work_items'
    -- and therefore could not see the seven items whose escalation was filed
    -- against the goal instead.
    select w.id as item_id, w.payload, w.objective_id
      from de_work_items w
      left join de_objectives o on o.id = w.objective_id
     where w.tenant_id = p_tenant_id
       and w.status = 'waiting_human'
       and tenant_is_operational(w.tenant_id)
       -- Still worth doing: a finished or dropped goal is closed by the
       -- trigger above, not retried here.
       and (o.id is null or o.status not in ('achieved', 'abandoned'))
       -- Somebody is actually waiting on this, filed either way.
       and exists (
         select 1 from human_tasks h
          where h.status = 'pending' and h.type = 'escalation'
            and ((h.related_table = 'de_work_items' and h.related_id = w.id)
              or (h.related_table = 'de_objectives'  and h.related_id = w.objective_id)))
     order by w.created_at
     limit greatest(1, p_limit)
  loop
    -- Once only. A step that fails a fair retry is a genuine human decision.
    if r.payload ? 'retried_at' then
      v_skipped := v_skipped + 1;
      continue;
    end if;

    update de_work_items set
      status = 'queued', scheduled_for = now(), attempts = 0, last_error = null,
      locked_at = null, locked_by = null, updated_at = now(),
      payload = payload || jsonb_build_object(
        'retried_at', now(),
        'retry_reason', 'This step was blocked before the employee had the tools it was asking for. Try again with what you have now; if it still cannot be done, say precisely what is missing today.')
    where id = r.item_id;

    -- Resolve whichever escalation was raised for it — item-level or goal-level.
    update human_tasks set
      status = 'rejected',
      disposition = 'retried',
      decision_note = 'Retried automatically: this was raised before the employee had the capability it asked for. No human ruling was made.',
      decided_at = now(), updated_at = now()
    where status = 'pending' and type = 'escalation'
      and ((related_table = 'de_work_items' and related_id = r.item_id)
        or (related_table = 'de_objectives'  and related_id = r.objective_id));

    -- A goal parked on that step gets its chance again too, or the item runs
    -- and the goal stays blocked forever regardless.
    update de_objectives set status = 'in_progress', updated_at = now()
     where id = r.objective_id and status = 'blocked';

    update de_exceptions set
      status = 'auto_resolved',
      outcome = 'Retried under current capabilities — no human ruling.',
      decided_at = now()
    where human_task_id in (
      select id from human_tasks
       where (related_table = 'de_work_items' and related_id = r.item_id)
          or (related_table = 'de_objectives'  and related_id = r.objective_id))
      and status = 'proposed';

    v_retried := v_retried + 1;
  end loop;

  return jsonb_build_object('ok', true, 'retried', v_retried, 'already_retried_left_alone', v_skipped);
end;
$function$;

CREATE OR REPLACE FUNCTION public.retry_ingestion_job(p_job_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tenant uuid := auth_tenant_id(); v_lvl int; v_retried int; v_terminal int;
BEGIN
  IF v_tenant IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  IF NOT EXISTS (SELECT 1 FROM knowledge_ingestion_jobs WHERE id = p_job_id AND tenant_id = v_tenant) THEN
    RAISE EXCEPTION 'job_not_found';
  END IF;

  -- Retrying creates documents, so it needs the same right as creating the job.
  SELECT coalesce(max(knowledge_permission_rank(g.permission)), 0) INTO v_lvl
    FROM knowledge_access_grants g
   WHERE g.tenant_id = v_tenant AND g.resource_type = 'workspace'
     AND knowledge_grant_matches_caller(g);
  IF v_lvl < 2 AND NOT is_platform_admin() THEN
    RAISE EXCEPTION 'insufficient_permission: retrying an import requires contributor';
  END IF;

  SELECT count(*) INTO v_terminal FROM knowledge_ingestion_items
   WHERE job_id = p_job_id AND status = 'failed' AND error_kind = 'terminal';

  UPDATE knowledge_ingestion_items
     SET status = 'queued', attempts = 0, next_attempt_at = now(),
         last_error = NULL, error_kind = NULL, updated_at = now()
   WHERE job_id = p_job_id AND status = 'failed' AND error_kind IS DISTINCT FROM 'terminal';
  GET DIAGNOSTICS v_retried = ROW_COUNT;

  -- Reopen the job so the rollup can close it again honestly.
  IF v_retried > 0 THEN
    UPDATE knowledge_ingestion_jobs
       SET status = 'running', finished_at = NULL
     WHERE id = p_job_id;
  END IF;

  RETURN jsonb_build_object('ok', true, 'retried', v_retried, 'not_retryable', v_terminal);
END $function$;

CREATE OR REPLACE FUNCTION public.revert_entity_amendment(p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_am workforce_entity_amendments; v_cfg jsonb; v_who text;
begin
  select * into v_am from workforce_entity_amendments where id = p_id;
  if not found then raise exception 'amendment not found'; end if;
  -- Caller must be a member of the amendment's tenant with admin rights,
  -- unless this is the service runtime acting on a measured regression.
  if coalesce(auth.role(), '') <> 'service_role' then
    -- IS DISTINCT FROM: a null-authed caller must be refused, not waved through
    -- on a NULL comparison (this exact hole was caught by this migration's own
    -- proof block on first apply — the runner context passed `<>` against NULL).
    if v_am.tenant_id is distinct from auth_tenant_id() then raise exception 'amendment not found'; end if;
    if not auth_has_tenant_role(array['tenant_owner', 'tenant_admin']) then
      raise exception 'only a workspace owner or admin may revert an amendment';
    end if;
  end if;
  if v_am.status <> 'applied' then
    return jsonb_build_object('ok', false, 'reason', 'status is ' || v_am.status || ', only applied amendments revert');
  end if;

  v_cfg := v_am.current_config;   -- the pre-amendment truth, stored since day one
  if v_am.entity_kind = 'de' then
    update digital_employees set
      persona_name      = coalesce(v_cfg->>'persona_name', persona_name),
      description       = coalesce(v_cfg->>'description', description),
      purpose_statement = coalesce(v_cfg->>'purpose_statement', purpose_statement)
    where id = v_am.entity_id and tenant_id = v_am.tenant_id;
  else
    update specialist_profiles set charter = coalesce(v_cfg->>'charter', charter)
      where id = v_am.entity_id and tenant_id = v_am.tenant_id;
  end if;

  update workforce_entity_amendments set status = 'reverted' where id = p_id;
  select coalesce(d.persona_name, d.name, 'entity') into v_who
    from digital_employees d where d.id = v_am.entity_id;
  begin
    perform append_audit_event(v_am.tenant_id, 'Practice Engine', 'de',
      format('%s amendment REVERTED — prior configuration restored for %s', v_am.entity_kind, coalesce(v_who, 'entity')),
      'config_change', jsonb_build_object('kind','entity_amendment_reverted','amendment_id',p_id,
        'entity_kind',v_am.entity_kind,'entity_id',v_am.entity_id,'origin','production'));
  exception when others then null; end;
  return jsonb_build_object('ok', true, 'entity_id', v_am.entity_id, 'restored_from', 'current_config');
end; $function$;

CREATE OR REPLACE FUNCTION public.review_de_for(p_tenant_id uuid)
 RETURNS uuid
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select de.id
  from digital_employees de
  where de.tenant_id = p_tenant_id
    and de.status = 'active'
    and de.archetype_key in ('renewal_manager', 'cs_manager')
  -- Deterministic: the same employee every period, so the review history
  -- reads as one desk's work rather than a rota nobody chose.
  order by (de.archetype_key = 'renewal_manager') desc, de.created_at asc
  limit 1;
$function$;

CREATE OR REPLACE FUNCTION public.review_de_incident(p_incident_id uuid, p_status text, p_resolution_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tenant uuid;
  v_row de_incidents;
begin
  if p_status not in ('reviewed', 'closed', 'open') then
    raise exception 'status must be reviewed, closed, or open';
  end if;
  v_tenant := auth_tenant_id();
  if v_tenant is null then raise exception 'not a member of any tenant'; end if;
  if not auth_has_tenant_role(array['tenant_owner', 'tenant_admin']) then
    raise exception 'only workspace owners/admins can review incidents';
  end if;

  select * into v_row from de_incidents where id = p_incident_id and tenant_id = v_tenant;
  if v_row.id is null then raise exception 'incident not found in this workspace'; end if;

  update de_incidents set
    status = p_status,
    resolution_note = coalesce(p_resolution_note, resolution_note),
    reviewed_by = auth.uid(),
    reviewed_at = now()
  where id = p_incident_id
  returning * into v_row;

  perform append_audit_event_internal(
    v_tenant, 'You', 'human',
    format('Incident %s — %s%s', p_status, v_row.title,
      case when p_resolution_note is not null and p_resolution_note <> '' then format(' ("%s")', left(p_resolution_note, 160)) else '' end),
    'config_change',
    jsonb_build_object('kind', 'incident_review', 'incident_id', p_incident_id, 'status', p_status, 'incident_kind', v_row.kind)
  );

  return jsonb_build_object('ok', true, 'status', v_row.status);
end;
$function$;

CREATE OR REPLACE FUNCTION public.revive_unit(p_de_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_u unit_tripwires; v_who text;
begin
  select u.* into v_u from unit_tripwires u
   where u.de_id = p_de_id and u.tenant_id = auth_tenant_id();
  if v_u.id is null then raise exception 'no tripwire record for this employee in your workspace'; end if;
  if not auth_has_tenant_role(array['tenant_owner', 'tenant_admin']) then
    raise exception 'only a workspace owner or admin may revive a unit';
  end if;
  if v_u.state <> 'resting' then
    return jsonb_build_object('revived', false, 'reason', 'unit is ' || v_u.state || ', not resting');
  end if;

  update unit_tripwires set
    state = case when first_fed_at is not null then 'fed' else 'dormant' end,
    review_due_at = case when first_fed_at is not null then now() + interval '90 days' end,
    feeding_deadline = case when first_fed_at is null then now() + interval '45 days' end,
    rested_at = null, rest_reason = null, updated_at = now()
  where id = v_u.id;

  update work_watchers set active = true, updated_at = now()
   where de_id = p_de_id and tenant_id = v_u.tenant_id and not active;

  select coalesce(d.persona_name, d.name) into v_who from digital_employees d where d.id = p_de_id;
  perform append_audit_event(v_u.tenant_id, 'workspace admin', 'human',
    'Unit revived — ' || v_who || ' returns to ' ||
    case when v_u.first_fed_at is not null then 'FED (next review in 90 days)'
         else 'DORMANT (fresh 45-day feeding deadline)' end,
    'governance', jsonb_build_object('de_id', p_de_id, 'origin', 'production'));
  return jsonb_build_object('revived', true,
    'state', case when v_u.first_fed_at is not null then 'fed' else 'dormant' end);
end;
$function$;

CREATE OR REPLACE FUNCTION public.revoke_access_grant(p_subject_kind text, p_subject_id uuid, p_resource_kind text, p_resource_id uuid, p_resource_category text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_tenant uuid; v_user uuid := auth.uid(); v_role text; v_is_active boolean; v_before text; v_subject_label text; v_resource_label text;
begin
  if v_user is not null then
    select tenant_id, role, coalesce(is_active, true) into v_tenant, v_role, v_is_active from profiles where user_id = v_user;
    if v_tenant is null then return jsonb_build_object('ok', false, 'error', 'no_tenant'); end if;
    if not v_is_active then return jsonb_build_object('ok', false, 'error', 'admin_role_required'); end if;
    if v_role not in ('tenant_owner', 'tenant_admin') then return jsonb_build_object('ok', false, 'error', 'admin_role_required'); end if;
  elsif coalesce(auth.role(), '') <> 'service_role' then
    return jsonb_build_object('ok', false, 'error', 'admin_role_required');
  else
    -- specialist subjects are digital_employees now (subject_id = DE id)
    select tenant_id into v_tenant from digital_employees where id = p_subject_id;
    if v_tenant is null then return jsonb_build_object('ok', false, 'error', 'subject_not_found'); end if;
  end if;

  select name into v_subject_label from digital_employees where id = p_subject_id and tenant_id = v_tenant;
  v_resource_label := case when p_resource_kind = 'connector'
    then coalesce((select display_name from connectors where id = p_resource_id and tenant_id = v_tenant), 'connector')
    else 'all ' || p_resource_category || ' systems' end;

  delete from data_access_grants
   where tenant_id = v_tenant and subject_kind = p_subject_kind and subject_id = p_subject_id
     and resource_kind = p_resource_kind
     and coalesce(resource_id::text, resource_category) = coalesce(p_resource_id::text, p_resource_category)
  returning permission into v_before;

  if v_before is null then return jsonb_build_object('ok', true, 'removed', false, 'note', 'no grant existed — already default-deny'); end if;

  perform append_audit_event(v_tenant,
    coalesce((select full_name from profiles where user_id = v_user), 'service'),
    case when v_user is null then 'system' else 'human' end,
    'Data access grant REVOKED — ' || coalesce(v_subject_label, 'subject') || ' on ' || v_resource_label || ': ' || v_before || ' → none (default-deny)',
    'access_control',
    jsonb_build_object('kind', 'access_grant_changed', 'subject_kind', p_subject_kind, 'subject_id', p_subject_id, 'subject_label', v_subject_label,
      'resource_kind', p_resource_kind, 'resource_id', p_resource_id, 'resource_category', p_resource_category, 'resource_label', v_resource_label, 'before', v_before, 'after', null));
  return jsonb_build_object('ok', true, 'removed', true, 'before', v_before);
end; $function$;

CREATE OR REPLACE FUNCTION public.revoke_de_certification(p_cert_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tenant uuid;
  v_row de_certifications;
  v_actor text;
  v_de_name text;
begin
  if p_reason is null or trim(p_reason) = '' then raise exception 'a revocation reason is required'; end if;
  v_tenant := auth_tenant_id();
  if v_tenant is null then raise exception 'not a member of any tenant'; end if;
  if not auth_has_tenant_role(array['tenant_owner', 'tenant_admin']) then
    raise exception 'only workspace owners/admins can revoke a certification';
  end if;
  update de_certifications set status = 'revoked', revoked_reason = trim(p_reason)
  where id = p_cert_id and tenant_id = v_tenant and status = 'active'
  returning * into v_row;
  if v_row.id is null then raise exception 'active certification not found in this workspace'; end if;

  select name into v_de_name from digital_employees where id = v_row.de_id;
  select full_name into v_actor from profiles where user_id = auth.uid();
  perform append_audit_event_internal(
    v_tenant, coalesce(v_actor, 'A workspace admin'), 'human',
    format('%s certification (%s) REVOKED — %s', coalesce(v_de_name, 'employee'), v_row.cert_type, left(trim(p_reason), 200)),
    'config_change',
    jsonb_build_object('kind', 'de_certification_revoked', 'cert_id', p_cert_id, 'de_id', v_row.de_id)
  );
  return jsonb_build_object('ok', true);
end;
$function$;

CREATE OR REPLACE FUNCTION public.revoke_de_delegation_token(p_token_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'revoke_de_delegation_token is service-role only';
  end if;
  update de_delegation_tokens set revoked_at = now() where id = p_token_id and revoked_at is null;
end;
$function$;

CREATE OR REPLACE FUNCTION public.revoke_knowledge_access(p_grant_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tenant uuid := auth_tenant_id();
  v_g knowledge_access_grants; v_my int; v_space uuid; v_admins int;
BEGIN
  IF v_tenant IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  SELECT * INTO v_g FROM knowledge_access_grants WHERE id = p_grant_id AND tenant_id = v_tenant;
  IF v_g.id IS NULL THEN RAISE EXCEPTION 'grant_not_found'; END IF;

  v_space := CASE WHEN v_g.resource_type = 'collection' THEN v_g.resource_id END;
  v_my := public.knowledge_my_admin_level(v_space);
  IF v_my < 5 THEN
    RAISE EXCEPTION 'insufficient_permission: changing who can see knowledge requires knowledge manager';
  END IF;
  -- Symmetric with granting: you cannot remove an access level you could not
  -- have handed out. Otherwise a knowledge manager can demote an owner.
  IF knowledge_permission_rank(v_g.permission) > v_my THEN
    RAISE EXCEPTION 'insufficient_permission: that grant is above your level';
  END IF;

  -- Never leave a workspace with nobody who can administer it.
  IF v_g.permission = 'workspace_admin' THEN
    SELECT count(*) INTO v_admins FROM knowledge_access_grants
     WHERE tenant_id = v_tenant AND permission = 'workspace_admin' AND id <> p_grant_id;
    IF v_admins = 0 THEN
      RAISE EXCEPTION 'that is the last full-access grant in this workspace — add another before removing it';
    END IF;
  END IF;

  DELETE FROM knowledge_access_grants WHERE id = p_grant_id;

  PERFORM append_audit_event(
    v_tenant, 'Knowledge', 'human',
    format('Removed %s access', v_g.permission),
    'access_control',
    jsonb_build_object('grant_id', p_grant_id, 'resource_type', v_g.resource_type,
                       'resource_id', v_g.resource_id, 'permission', v_g.permission,
                       'principal_type', v_g.principal_type));
  RETURN jsonb_build_object('ok', true);
END $function$;

CREATE OR REPLACE FUNCTION public.revoke_platform_capability_grant(p_target_user_id uuid, p_capability text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_target_layer text;
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;
  if not resolve_platform_capability(auth.uid(), 'team.manage') then
    raise exception 'only a platform team manager may change a teammate''s permissions';
  end if;
  if auth.uid() = p_target_user_id then
    raise exception 'you cannot change your own permissions here';
  end if;

  select layer into v_target_layer from profiles where user_id = p_target_user_id;
  if v_target_layer is distinct from 'platform' then
    raise exception 'that account is not a platform team member';
  end if;

  if p_capability = 'team.manage'
     and platform_capability_remaining_holders(p_target_user_id, 'team.manage') = 0 then
    raise exception 'this change would leave zero active platform accounts able to manage the team -- at least one must always remain';
  end if;

  delete from platform_capability_grants where user_id = p_target_user_id and capability = p_capability;

  return jsonb_build_object('ok', true, 'user_id', p_target_user_id, 'capability', p_capability, 'reverted_to_role_default', true);
end;
$function$;

CREATE OR REPLACE FUNCTION public.revoke_platform_invite(p_invite_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_invite platform_invites;
begin
  if not resolve_platform_capability(auth.uid(), 'team.manage') then
    raise exception 'only a platform team manager may revoke a platform invite';
  end if;

  select * into v_invite from platform_invites where id = p_invite_id for update;
  if not found then
    raise exception 'invite not found';
  end if;
  if v_invite.status <> 'pending' then
    raise exception 'this invite is already % and cannot be revoked', v_invite.status;
  end if;

  update platform_invites set status = 'revoked' where id = p_invite_id;

  return jsonb_build_object('ok', true, 'invite_id', p_invite_id, 'status', 'revoked');
end;
$function$;

CREATE OR REPLACE FUNCTION public.revoke_tenant_api_key(p_key_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tenant uuid;
  v_name text;
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;

  select tenant_id, name into v_tenant, v_name from tenant_api_keys where id = p_key_id;
  if v_tenant is null then
    raise exception 'API key not found';
  end if;

  if not (
    is_platform_admin()
    or exists (
      select 1 from profiles p
      where p.user_id = auth.uid() and p.tenant_id = v_tenant
        and coalesce(p.is_active, true) = true
        and p.role in ('tenant_owner', 'tenant_admin')
    )
  ) then
    raise exception 'only workspace owners/admins can revoke an API key';
  end if;

  update tenant_api_keys set revoked_at = now() where id = p_key_id and revoked_at is null;

  perform append_audit_event_internal(
    v_tenant, 'You', 'human',
    format('API key revoked: %s', v_name),
    'config_change',
    jsonb_build_object('kind', 'api_key_revoked', 'key_id', p_key_id, 'name', v_name)
  );

  return jsonb_build_object('ok', true);
end;
$function$;

CREATE OR REPLACE FUNCTION public.rotate_widget_identity_secret(p_widget_key_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tenant uuid; v_secret text; v_is_new boolean;
BEGIN
  SELECT tenant_id INTO v_tenant FROM widget_keys WHERE id = p_widget_key_id;
  IF v_tenant IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'widget_key_not_found');
  END IF;
  IF coalesce(auth.role(), '') <> 'service_role'
     AND NOT (v_tenant = public.auth_tenant_id()
              AND public.auth_has_tenant_role(ARRAY['tenant_owner','tenant_admin'])) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_permitted');
  END IF;

  v_secret := encode(gen_random_bytes(32), 'hex');   -- 256-bit, 64 hex chars
  SELECT NOT EXISTS (SELECT 1 FROM widget_key_secrets WHERE widget_key_id = p_widget_key_id) INTO v_is_new;
  INSERT INTO widget_key_secrets (widget_key_id, tenant_id, secret)
  VALUES (p_widget_key_id, v_tenant, v_secret)
  ON CONFLICT (widget_key_id) DO UPDATE SET secret = EXCLUDED.secret, rotated_at = now();
  RETURN jsonb_build_object('ok', true, 'secret', v_secret, 'is_new', v_is_new);
END $function$;

CREATE OR REPLACE FUNCTION public.run_account_review_sweep(p_tenant_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 100)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  t          record;
  acct       record;
  k          record;
  v_de       uuid;
  v_draft    jsonb;
  v_review   uuid;
  v_task     uuid;
  v_raised_t int;
  v_tenants  int := 0;
  v_nodesk   int := 0;
  v_seen     int := 0;
  v_raised   int := 0;
  v_current  int := 0;
  v_detail   jsonb := '[]'::jsonb;
begin
  for t in
    select tn.id, tn.slug from tenants tn
    where (p_tenant_id is null or tn.id = p_tenant_id)
      and tenant_is_operational(tn.id)
  loop
    v_de := review_de_for(t.id);
    if v_de is null then
      v_nodesk := v_nodesk + 1;
      continue;
    end if;
    v_tenants := v_tenants + 1;
    v_raised_t := 0;

    for acct in
      select ca.id, ca.name from customer_accounts ca
      where ca.tenant_id = t.id and coalesce(ca.status, '') <> 'churned'
      order by ca.renewal_date asc nulls last, ca.created_at asc
    loop
      exit when v_raised_t >= p_limit;
      v_seen := v_seen + 1;

      -- Today's evidence, not last month's: refresh before drafting. The
      -- core function is mig-510-honest — an unmeasured account stays
      -- unmeasured and the draft says so.
      perform compute_account_health_core(acct.id);

      for k in
        select * from (values
          ('health_check', to_char(current_date, 'YYYY-MM')),
          ('lifecycle',    to_char(current_date, 'YYYY-"Q"Q')),
          ('churn_risk',   to_char(current_date, 'YYYY-MM'))
        ) as kinds(kind, period)
      loop
        exit when v_raised_t >= p_limit;

        -- churn_risk is due only while the account IS at risk — evaluated
        -- AFTER the refresh, so a flip this morning counts this morning.
        if k.kind = 'churn_risk' and not exists (
          select 1 from customer_accounts ca2 where ca2.id = acct.id and ca2.status = 'at_risk'
        ) then continue; end if;

        -- THE dedupe: the unique index decides, not a marker. Losing the
        -- race or repeating the period both land here as "already current".
        insert into account_reviews (tenant_id, account_id, review_kind, period_key, de_id)
        values (t.id, acct.id, k.kind, k.period, v_de)
        on conflict (tenant_id, account_id, review_kind, period_key) do nothing
        returning id into v_review;

        if v_review is null then
          v_current := v_current + 1;
          continue;
        end if;

        v_draft := account_review_draft(k.kind, acct.id);
        if v_draft ? 'error' then
          -- The review row exists but no task can carry it: say so loudly in
          -- the return rather than leaving a silent ledger row.
          v_detail := v_detail || jsonb_build_object('tenant', t.slug, 'account', acct.name,
                                                     'kind', k.kind, 'error', v_draft->>'error');
          continue;
        end if;

        insert into human_tasks (tenant_id, type, source, origin, title, detail,
                                 related_table, related_id, de_id, account_id)
        values (t.id, 'account_review', 'de', 'production',
                v_draft->>'title', v_draft->>'detail',
                'account_reviews', v_review, v_de, acct.id)
        returning id into v_task;

        update account_reviews
           set task_id = v_task, findings = coalesce(v_draft->'findings', '{}'::jsonb)
         where id = v_review;

        v_raised := v_raised + 1;
        v_raised_t := v_raised_t + 1;
      end loop;
    end loop;
  end loop;

  return jsonb_build_object(
    'tenants_swept', v_tenants,
    'tenants_without_a_review_desk', v_nodesk,
    'accounts_seen', v_seen,
    'raised', v_raised,
    'already_current', v_current,
    'detail', v_detail);
end;
$function$;

CREATE OR REPLACE FUNCTION public.run_analytics_query(p_tenant_id uuid, p_key text, p_params jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is null then
    raise exception 'not authenticated: running an analytics query against a workspace named in a parameter is not an anonymous operation';
  end if;
  if not exists (select 1 from profiles p where p.user_id = auth.uid()
                   and (p.tenant_id = p_tenant_id or p.layer = 'platform')) then
    raise exception 'not authorized for this tenant';
  end if;
  return public.run_analytics_query_internal(p_tenant_id, p_key, p_params);
end;
$function$;

CREATE OR REPLACE FUNCTION public.run_analytics_query_internal(p_tenant_id uuid, p_key text, p_params jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  -- NO USER CHECK. de-work/index.ts:824 runs the DE's `run_analytics` tool on
  -- the service-role admin client. EXECUTE is service_role only.
  return case p_key
    when 'de_workload'   then public.analytics_de_workload(p_tenant_id, (p_params->>'de_id')::uuid)
    when 'action_volume' then public.analytics_action_volume(p_tenant_id, coalesce((p_params->>'days')::int, 30))
    else jsonb_build_object('error', 'unknown_query_key', 'key', p_key)
  end;
end;
$function$;

CREATE OR REPLACE FUNCTION public.run_case_timeline(p_tenant_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE e de_case_events; v_fired integer := 0;
BEGIN
  FOR e IN
    SELECT * FROM de_case_events
    WHERE status = 'pending' AND fire_at <= now()
      AND (p_tenant_id IS NULL OR tenant_id = p_tenant_id)
      AND tenant_is_operational(tenant_id)
    ORDER BY fire_at LIMIT 500
  LOOP
    UPDATE de_case_events SET status = 'fired', decided_at = now() WHERE id = e.id;

    -- Re-open the case with the continuation instruction attached, so de-work
    -- resumes the motion where it paused.
    UPDATE de_objectives
       SET status = CASE WHEN status IN ('achieved','abandoned') THEN status ELSE 'open' END,
           next_wake_at = now(),
           description = coalesce(description,'') || E'\n\n[Follow-up ' || to_char(now(),'Mon DD') || ']: '
             || coalesce(nullif(e.instruction,''),
                  CASE WHEN e.awaiting_ref IS NOT NULL THEN 'No reply received by the deadline — continue the motion.' ELSE 'Scheduled continuation — continue the motion.' END),
           updated_at = now()
     WHERE id = e.objective_id;

    BEGIN
      PERFORM append_audit_event_internal(e.tenant_id,
        (SELECT coalesce(persona_name, name) FROM digital_employees WHERE id = e.de_id), 'de',
        'Case resumed — ' || e.kind || (CASE WHEN e.awaiting_ref IS NOT NULL THEN ' (no reply by deadline)' ELSE '' END)
          || ': ' || left(coalesce(e.instruction,'continue the motion'), 120),
        'playbook_step',
        jsonb_build_object('kind','case_continuation_fired','event_id',e.id,'objective_id',e.objective_id,'continuation_kind',e.kind));
    EXCEPTION WHEN OTHERS THEN NULL; END;

    v_fired := v_fired + 1;
  END LOOP;
  RETURN jsonb_build_object('ok', true, 'fired', v_fired);
END; $function$;

CREATE OR REPLACE FUNCTION public.run_dormancy_writer_audit()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_names text;
  v_count int;
begin
  select count(*), string_agg(function_name, ', ' order by function_name)
    into v_count, v_names
    from audit_unguarded_dormancy_writers();

  if v_count > 0 then
    perform raise_ops_alert(
      'dormancy_writer_unguarded',
      format('%s work-creating function(s) can queue work for a SUSPENDED workspace without checking: %s. '
             || 'Either add the suspension check, or record why it is safe in dormancy_writer_exemptions.',
             v_count, v_names),
      jsonb_build_object('kind', 'dormancy_writer_unguarded', 'count', v_count,
                         'functions', string_to_array(v_names, ', '))
    );
  end if;

  return jsonb_build_object('unguarded', v_count, 'functions', coalesce(v_names, ''));
end;
$function$;

CREATE OR REPLACE FUNCTION public.run_dunning_sweep(p_tenant_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 200)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  t          record;
  inv        record;
  v_de       uuid;
  v_ad       uuid;
  v_conn     uuid;
  v_provider text;
  v_exec     text;
  v_dedupe   text;
  v_note     text;
  v_mail     jsonb;
  v_emails   boolean;
  v_org      text;
  v_params   jsonb;
  v_gate     jsonb;
  v_decision text;
  v_content  text;
  v_detail_txt text;
  v_raised   int := 0;
  v_skipped  int := 0;
  v_noexec   int := 0;
  v_noconn   int := 0;
  v_nodesk   int := 0;
  v_emailed  int := 0;
  v_noaddr   int := 0;
  v_tenants  int := 0;
  v_detail   jsonb := '[]'::jsonb;
begin
  for t in
    select tn.id, tn.slug, tn.name from tenants tn
    where (p_tenant_id is null or tn.id = p_tenant_id)
      and tenant_is_operational(tn.id)
  loop
    v_de := dunning_de_for(t.id);
    if v_de is null then
      v_nodesk := v_nodesk + 1;
      continue;
    end if;
    v_tenants := v_tenants + 1;
    v_org := coalesce(nullif(t.name, ''), 'Accounts Receivable');

    for inv in
      select d.*, ri.source_provider, ri.source_currency, ri.due_date, ri.contact_email
      from dunning_position(t.id) d
      join renewal_invoices ri on ri.id = d.invoice_id
      where d.actionable
      order by d.days_overdue desc
      limit p_limit
    loop
      v_provider := coalesce(nullif(inv.source_provider, ''), 'erpnext');
      v_dedupe   := format('dunning:%s:%s', inv.invoice_id, inv.due_stage);

      if exists (
        select 1 from action_executions ae
        where ae.tenant_id = t.id and ae.dedupe_key = v_dedupe and ae.decision <> 'failed'
      ) then
        v_skipped := v_skipped + 1;
        continue;
      end if;

      v_exec := dunning_execution_key(v_provider, inv.action_key,
                                      nullif(btrim(coalesce(inv.contact_email,'')), '') is not null);
      v_ad   := dunning_action_for(t.id, inv.action_key, v_exec);
      if v_ad is null then
        v_noexec := v_noexec + 1;
        v_detail := v_detail || jsonb_build_object(
          'tenant', t.slug, 'invoice', inv.invoice_ref, 'skipped', 'no_executor',
          'wanted', inv.action_key, 'provider', v_provider, 'execution_key', v_exec);
        continue;
      end if;

      -- KNOWING WHICH VERB IS NOT KNOWING WHICH SYSTEM. Without this, the row
      -- is raised with a null connector and the approved re-entry path returns
      -- `connector_id_required` — silently, after the human has been told the
      -- work is done. Same refusal shape as `no_executor` directly above, for
      -- the same reason 589 introduced that one.
      v_conn := dunning_connector_for(t.id, v_ad);
      if v_conn is null then
        v_noconn := v_noconn + 1;
        v_detail := v_detail || jsonb_build_object(
          'tenant', t.slug, 'invoice', inv.invoice_ref, 'skipped', 'no_connector',
          'wanted', inv.action_key, 'provider', v_provider, 'execution_key', v_exec,
          'why', 'no single connected connector in this workspace matches the executor''s provider and category');
        continue;
      end if;

      v_emails := (v_exec = 'erpnext_send_invoice_email'
                   or v_exec like '%_send_invoice_reminder');
      v_note   := dunning_note_text(inv.due_stage, inv.customer, inv.invoice_ref,
                                    inv.days_overdue, inv.outstanding_cents, inv.source_currency);
      v_mail   := dunning_email(inv.due_stage, inv.customer, inv.invoice_ref, inv.days_overdue,
                                inv.outstanding_cents, inv.source_currency, inv.due_date, v_org);

      -- The internal note and the customer email are built from the same facts
      -- but are never the same string. The note tells a colleague how to pitch
      -- it; the email is what a customer reads.
      if v_emails and v_mail is not null then
        v_params := jsonb_build_object(
          'external_ref', inv.invoice_ref,
          'recipient',    inv.contact_email,
          'subject',      v_mail->>'subject',
          'body',         v_mail->>'body',
          'invoice_id',   inv.invoice_id, 'stage', inv.due_stage,
          'days_overdue', inv.days_overdue, 'outstanding_cents', inv.outstanding_cents);
        v_content := v_mail->>'body';
        v_detail_txt := format(E'%s\n\nThis EMAILS THE CUSTOMER at %s.\n\nSubject: %s\n\n%s',
                          inv.why, inv.contact_email, v_mail->>'subject', v_mail->>'body');
        v_emailed := v_emailed + 1;
      else
        -- No address, or a rung that must not reach the customer.
        v_params := jsonb_build_object(
          'external_ref', inv.invoice_ref, 'note', v_note,
          'invoice_id',   inv.invoice_id, 'stage', inv.due_stage,
          'days_overdue', inv.days_overdue, 'outstanding_cents', inv.outstanding_cents,
          'tone', inv.tone);
        v_content := v_note;
        if inv.action_key <> 'flag_for_collections'
           and nullif(btrim(coalesce(inv.contact_email,'')), '') is null then
          v_noaddr := v_noaddr + 1;
          v_detail_txt := format(E'%s\n\n⚠ THE CUSTOMER WILL NOT SEE THIS. No email address is recorded on invoice %s, so this writes an internal note in ERPNext instead of chasing anyone. Add a contact email to the invoice and re-run to send a real reminder.\n\nWhat will be written:\n%s',
                            inv.why, inv.invoice_ref, v_note);
        else
          v_detail_txt := format(E'%s\n\nInternal note only — the customer is not contacted at this stage.\n\nWhat will be written:\n%s',
                            inv.why, v_note);
        end if;
      end if;

      v_gate := decide_action_execution(
        t.id,
        format('%s — %s', inv.rung_label, inv.customer),
        'erp_financials',
        coalesce(inv.requires_approval, true),
        v_de,
        inv.outstanding_cents,
        inv.action_key,
        -- Guardrails scan the CONTENT, so they must see the words that will
        -- actually leave the building, not a summary of them.
        v_content
      );
      v_decision := coalesce(v_gate->>'decision', 'human_gated_destructive');

      perform record_action_execution(
        p_tenant_id            => t.id,
        p_action_definition_id => v_ad,
        p_connector_id         => v_conn,
        p_subject_kind         => 'de',
        p_subject_id           => v_de,
        p_mode                 => 'execute',
        p_params               => v_params,
        p_decision      => v_decision,
        p_destructive   => coalesce(inv.requires_approval, true),
        p_idempotent    => false,
        p_dedupe_key    => v_dedupe,
        p_request_summary => format('%s for %s — invoice %s, %s day(s) overdue.%s',
                              inv.rung_label, inv.customer, inv.invoice_ref, inv.days_overdue,
                              case when v_emails and v_mail is not null
                                   then ' Emails the customer.' else ' Internal note only.' end),
        p_receipt   => null,
        p_result    => null,
        p_task_title  => format('%s%s: %s — %s, %s days overdue',
                           case when v_emails and v_mail is not null then 'Email ' else '' end,
                           inv.rung_label, inv.customer, inv.invoice_ref, inv.days_overdue),
        p_task_detail => v_detail_txt,
        p_create_task => true,
        p_origin_kind => 'dunning_sweep',
        p_origin_id   => inv.invoice_id
      );

      v_raised := v_raised + 1;
    end loop;
  end loop;

  return jsonb_build_object(
    'tenants_swept',      v_tenants,
    'raised',             v_raised,
    'emails_drafted',     v_emailed,
    'notes_only_no_address', v_noaddr,
    'already_proposed',   v_skipped,
    'no_executor',        v_noexec,
    'no_connector',       v_noconn,
    'tenants_without_a_finance_employee', v_nodesk,
    'detail',             v_detail
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.run_reply_mode_gate_internal()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_de record;
  v_g record;
  v_m record;
  v_reason text;
  v_demoted integer := 0;
  v_name text;
begin
  for v_de in
    select d.id, d.tenant_id, coalesce(d.persona_name, d.name) as name
      from digital_employees d
      join tenants t on t.id = d.tenant_id
     where d.external_reply_mode = 'auto'
       and coalesce(d.lifecycle_status, 'active') not in ('paused', 'retired', 'archived')
       and t.status in ('active', 'trial')
  loop
    v_reason := null;

    select * into v_g from public.de_records_gate(v_de.tenant_id, v_de.id);
    if v_g.gated then
      v_reason := 'records gate: ' || array_to_string(v_g.reasons, ', ');
    end if;

    if v_reason is null and exists (
      select 1 from de_incidents i
       where i.tenant_id = v_de.tenant_id and i.de_id = v_de.id
         and i.status = 'open' and i.severity = 'critical'
    ) then
      v_reason := 'an open critical incident';
    end if;

    if v_reason is null then
      select * into v_m from get_de_performance_metrics(v_de.tenant_id, 8) m
       where m.de_id = v_de.id limit 1;
      if found and coalesce(v_m.total_decisions, 0) >= 10
         and (v_m.escalation_rate > 50 or v_m.error_rate > 15) then
        v_reason := format('degraded 8-week metrics (escalation %s%%, errors %s%%)',
                           round(coalesce(v_m.escalation_rate, 0)), round(coalesce(v_m.error_rate, 0)));
      end if;
    end if;

    if v_reason is null then continue; end if;

    if exists (
      select 1 from human_tasks t
       where t.tenant_id = v_de.tenant_id and t.de_id = v_de.id
         and t.type = 'trust_demotion_notice'
         and t.created_at > now() - interval '7 days'
    ) then continue; end if;

    update digital_employees set external_reply_mode = 'draft', updated_at = now()
     where id = v_de.id;

    insert into human_tasks (tenant_id, de_id, type, source, title, detail)
    values (v_de.tenant_id, v_de.id, 'trust_demotion_notice', 'de',
      format('%s moved to draft-for-approval — %s', v_de.name, v_reason),
      format('%s was auto-answering customers, but their employment record no longer supports it: %s. '
             || 'Every reply now waits for your approval. To restore auto-answering, resolve the underlying record '
             || '(re-certify / close the incident / improve the metrics) and flip the mode back on the employee''s Channels settings — '
             || 'that restoration is deliberately a human decision.', v_de.name, v_reason));

    perform append_audit_event_internal(
      v_de.tenant_id, 'Records gate', 'system',
      format('%s demoted from auto-answer to draft-for-approval — %s', v_de.name, v_reason),
      'config_change',
      jsonb_build_object('kind', 'reply_mode_demotion', 'de_id', v_de.id, 'reason', v_reason));

    insert into activity_events (tenant_id, actor, actor_type, event_type, text)
    values (v_de.tenant_id, v_de.name, 'de', 'config_change',
      format('Moved to draft-for-approval by the records gate — %s', v_reason));

    v_demoted := v_demoted + 1;
  end loop;

  return jsonb_build_object('demoted', v_demoted);
end;
$function$;

CREATE OR REPLACE FUNCTION public.run_tenant_feature_parity_audit()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_count int; v_list text;
begin
  select count(*), string_agg(finding_kind || ': ' || subject, '; ' order by finding_kind, subject)
    into v_count, v_list
    from audit_tenant_feature_parity() a
   where not exists (select 1 from tenant_parity_exemptions e
                      where e.finding_kind = a.finding_kind and e.subject = a.subject);

  if v_count > 0 then
    perform raise_ops_alert(
      'tenant_feature_parity',
      format('%s workspace parity finding(s): %s. Either make the capability reach every workspace, '
             || 'or record why the difference is correct in tenant_parity_exemptions.', v_count, v_list),
      jsonb_build_object('kind', 'tenant_feature_parity', 'count', v_count));
  end if;

  return jsonb_build_object('findings', v_count, 'detail', coalesce(v_list, ''));
end $function$;

CREATE OR REPLACE FUNCTION public.run_unit_tripwires_sweep()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_fed int := 0; v_deadline_rests int := 0; v_review_rests int := 0; v_continues int := 0;
  r record;
  v_days numeric; v_pulse numeric; v_ok_pulse boolean; v_ok_quality boolean;
  v_appr bigint; v_dec bigint; v_open_inc bigint;
begin
  -- 1. Dormant units whose demand has arrived become FED (clock starts).
  update unit_tripwires u
     set state = 'fed', first_fed_at = fed.first_ts,
         review_due_at = greatest(fed.first_ts + interval '90 days', now() + interval '7 days'),
         feeding_deadline = null, updated_at = now()
    from (
      select u2.id as uid, least(
        (select min(w.created_at) from de_work_items w where w.de_id = u2.de_id and w.status = 'done'),
        (select min(c.created_at) from de_conversations c where c.de_id = u2.de_id and c.channel <> 'exam'),
        (select min(a.created_at) from action_executions a
          where a.subject_kind = 'de' and a.subject_id = u2.de_id
            and public.action_execution_landed(a))) as first_ts
      from unit_tripwires u2 where u2.state = 'dormant'
    ) fed
   where fed.uid = u.id and fed.first_ts is not null;
  get diagnostics v_fed = row_count;

  -- 2. Dormant past the feeding deadline → rest, loudly.
  for r in select u.*, coalesce(d.persona_name, d.name) as who
             from unit_tripwires u join digital_employees d on d.id = u.de_id
            where u.state = 'dormant' and u.feeding_deadline is not null
              and u.feeding_deadline <= now()
  loop
    update unit_tripwires set state = 'resting', rested_at = now(), updated_at = now(),
           last_verdict = 'rest', last_verdict_at = now(),
           rest_reason = 'feeding deadline passed — staffed 45+ days with no real demand'
     where id = r.id;
    update work_watchers set active = false, updated_at = now()
     where de_id = r.de_id and active;
    if not exists (select 1 from human_tasks h where h.related_table = 'unit_tripwires'
                     and h.related_id = r.id and h.status = 'pending') then
      insert into human_tasks (tenant_id, type, source, title, detail, related_table, related_id, origin)
      values (r.tenant_id, 'escalation', 'de',
              'Unit resting — ' || r.who || ' (never fed)',
              r.who || ' was staffed on ' || to_char(r.staffed_at, 'FMDD FMMonth YYYY')
              || ' and has received no real demand in 45 days. Its watchers are paused and it is resting'
              || ' — the employee remains and nothing is deleted. To wake it: load its demand'
              || ' (book, channel, or records) and revive the unit.',
              'unit_tripwires', r.id, 'production');
    end if;
    v_deadline_rests := v_deadline_rests + 1;
  end loop;

  -- 3. Fed units at review: pulse floor + quality floor, exam-filtered.
  for r in select u.*, coalesce(d.persona_name, d.name) as who
             from unit_tripwires u join digital_employees d on d.id = u.de_id
            where u.state = 'fed' and u.review_due_at is not null and u.review_due_at <= now()
  loop
    v_days := least(90, greatest(7, extract(epoch from now() - r.first_fed_at) / 86400));
    select (select count(*) from de_work_items w where w.de_id = r.de_id and w.status = 'done'
              and w.created_at >= now() - interval '90 days')
         + (select count(*) from de_conversations c where c.de_id = r.de_id and c.channel <> 'exam'
              and c.created_at >= now() - interval '90 days')
         + (select count(*) from action_executions a where a.subject_kind = 'de' and a.subject_id = r.de_id
              and public.action_execution_landed(a)
              and a.created_at >= now() - interval '90 days')
      into v_pulse;
    v_ok_pulse := v_pulse >= r.pulse_floor_per_week * (v_days / 7.0);

    select count(*) filter (where status = 'approved'), count(*)
      into v_appr, v_dec
      from human_tasks
     where de_id = r.de_id and status in ('approved', 'rejected')
       and decided_at >= now() - interval '90 days'
       and evidence_is_production(origin)
       and type in ('action_approval', 'approval_gate', 'inquiry_review', 'escalation', 'review_gate');
    select count(*) into v_open_inc from de_incidents
     where de_id = r.de_id and status not in ('resolved', 'closed', 'dismissed');
    v_ok_quality := (v_open_inc = 0)
                and (v_dec = 0 or v_appr::numeric / v_dec >= r.min_approval_rate);

    if v_ok_pulse and v_ok_quality then
      update unit_tripwires set last_verdict = 'continue', last_verdict_at = now(),
             review_due_at = now() + interval '90 days', updated_at = now()
       where id = r.id;
      v_continues := v_continues + 1;
    else
      update unit_tripwires set state = 'resting', rested_at = now(), updated_at = now(),
             last_verdict = 'rest', last_verdict_at = now(),
             rest_reason = trim(both ' ' from
               case when not v_ok_pulse then format('pulse %s in %s days is below the floor of %s/week. ', round(v_pulse), round(v_days), r.pulse_floor_per_week) else '' end
               || case when v_open_inc > 0 then v_open_inc || ' open incident(s). ' else '' end
               || case when v_dec > 0 and v_appr::numeric / v_dec < r.min_approval_rate
                       then format('approval rate %s%% is below %s%%.', round(100.0 * v_appr / v_dec), round(100 * r.min_approval_rate)) else '' end)
       where id = r.id;
      update work_watchers set active = false, updated_at = now()
       where de_id = r.de_id and active;
      if not exists (select 1 from human_tasks h where h.related_table = 'unit_tripwires'
                       and h.related_id = r.id and h.status = 'pending') then
        insert into human_tasks (tenant_id, type, source, title, detail, related_table, related_id, origin)
        values (r.tenant_id, 'escalation', 'de',
                'Unit resting — ' || r.who || ' (below floor at review)',
                r.who || '''s 90-day review tripped: '
                || (select rest_reason from unit_tripwires where id = r.id)
                || ' Watchers are paused; the employee remains. Revive when its demand or quality recovers.',
                'unit_tripwires', r.id, 'production');
      end if;
      v_review_rests := v_review_rests + 1;
    end if;
  end loop;

  return jsonb_build_object('fed', v_fed, 'deadline_rests', v_deadline_rests,
                            'review_rests', v_review_rests, 'continues', v_continues);
end;
$function$;

CREATE OR REPLACE FUNCTION public.run_work_watchers(p_tenant_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  w work_watchers; v_new integer; v_total integer := 0; v_watchers integer := 0;
  v_obj_id uuid; v_inserted boolean; r record; v_h integer; v_occ text;
  v_title text; v_de_name text; v_src text; v_date_field text; v_motion text;
  v_cat watch_source_catalog; v_row jsonb; v_id text; v_where text; v_sql text;
  v_field text; v_op text; v_vt text; v_cast text; v_datef text; v_label text; v_subject jsonb; v_cap int;
BEGIN
  FOR w IN SELECT * FROM work_watchers WHERE active AND kind <> 'inbox'
      AND (p_tenant_id IS NULL OR tenant_id = p_tenant_id)
      AND tenant_is_operational(tenant_id) ORDER BY created_at
  LOOP
    v_new := 0; v_watchers := v_watchers + 1;
    v_src := coalesce(w.config->>'source','customer_accounts');
    SELECT coalesce(persona_name, name) INTO v_de_name FROM digital_employees WHERE id = w.de_id;

    BEGIN
    -- ── date_horizon ──
    IF w.kind = 'date_horizon' AND v_src = 'customer_accounts' THEN
      FOR r IN
        SELECT ca.id, ca.name, ca.renewal_date, ca.arr_cents, ca.health_score,
               (ca.renewal_date - current_date) AS days_left
        FROM customer_accounts ca
        WHERE ca.tenant_id = w.tenant_id AND ca.renewal_date IS NOT NULL AND ca.renewal_date >= current_date
          AND (w.config->'status_filter' IS NULL OR ca.status IN (SELECT jsonb_array_elements_text(w.config->'status_filter')))
      LOOP
        SELECT min(h) INTO v_h FROM (SELECT (jsonb_array_elements_text(coalesce(w.config->'horizons_days','[90,60,30]'::jsonb)))::int AS h) hs WHERE h >= r.days_left;
        IF v_h IS NULL THEN CONTINUE; END IF;
        v_occ := r.id::text || '|' || r.renewal_date::text || '|' || v_h::text;
        INSERT INTO work_watcher_matches (tenant_id, watcher_id, subject_ref, occurrence_key)
        VALUES (w.tenant_id, w.id, r.id::text, v_occ) ON CONFLICT (watcher_id, occurrence_key) DO NOTHING;
        GET DIAGNOSTICS v_inserted = ROW_COUNT; IF NOT v_inserted THEN CONTINUE; END IF;
        v_title := w.label || ' — ' || r.name || ' (' || v_h || '-day checkpoint, renews ' || to_char(r.renewal_date, 'Mon DD') || ')';
        INSERT INTO de_objectives (tenant_id, de_id, title, description, entity_kind, entity_ref, status, priority, due_at, plan)
        VALUES (w.tenant_id, w.de_id, left(v_title, 200),
          'Opened by the Book of Work: ' || r.name || ' renews on ' || r.renewal_date::text || ' (' || r.days_left || ' days out). Work the ' || v_h || '-day motion per the playbook.',
          'customer_account', r.id::text, 'open', (case when v_h <= 14 then 1 when v_h <= 30 then 2 when v_h <= 60 then 3 else 4 end), r.renewal_date::timestamptz,
          jsonb_build_object('source','book_of_work','watcher_id',w.id,'kind',w.kind,'horizon_days',v_h,
            'subject', jsonb_build_object('name', r.name, 'renewal_date', r.renewal_date, 'arr_cents', r.arr_cents, 'health_score', r.health_score))
        ) RETURNING id INTO v_obj_id;
        UPDATE work_watcher_matches SET objective_id = v_obj_id WHERE watcher_id = w.id AND occurrence_key = v_occ;
        v_new := v_new + 1;
      END LOOP;

    ELSIF w.kind = 'date_horizon' AND v_src = 'opportunities' THEN
      FOR r IN
        SELECT o.id, coalesce(o.name, o.company_name, 'opportunity') AS name, o.close_date, o.amount_cents, o.stage,
               (o.close_date - current_date) AS days_left
        FROM opportunities o
        WHERE o.tenant_id = w.tenant_id AND o.close_date IS NOT NULL AND o.close_date >= current_date AND o.closed_at IS NULL
          AND (w.config->'stage_filter' IS NULL OR o.stage IN (SELECT jsonb_array_elements_text(w.config->'stage_filter')))
      LOOP
        SELECT min(h) INTO v_h FROM (SELECT (jsonb_array_elements_text(coalesce(w.config->'horizons_days','[30,14,7]'::jsonb)))::int AS h) hs WHERE h >= r.days_left;
        IF v_h IS NULL THEN CONTINUE; END IF;
        v_occ := r.id::text || '|' || r.close_date::text || '|' || v_h::text;
        INSERT INTO work_watcher_matches (tenant_id, watcher_id, subject_ref, occurrence_key)
        VALUES (w.tenant_id, w.id, r.id::text, v_occ) ON CONFLICT (watcher_id, occurrence_key) DO NOTHING;
        GET DIAGNOSTICS v_inserted = ROW_COUNT; IF NOT v_inserted THEN CONTINUE; END IF;
        v_title := w.label || ' — ' || r.name || ' (' || v_h || '-day, closes ' || to_char(r.close_date, 'Mon DD') || ')';
        INSERT INTO de_objectives (tenant_id, de_id, title, description, entity_kind, entity_ref, status, priority, due_at, plan)
        VALUES (w.tenant_id, w.de_id, left(v_title, 200),
          'Opened by the Book of Work: opportunity ' || r.name || ' is in stage "' || coalesce(r.stage,'?') || '" and closes on ' || r.close_date::text || ' (' || r.days_left || ' days out). Advance it per the playbook.',
          'opportunity', r.id::text, 'open', (case when v_h <= 14 then 1 when v_h <= 30 then 2 when v_h <= 60 then 3 else 4 end), r.close_date::timestamptz,
          jsonb_build_object('source','book_of_work','watcher_id',w.id,'kind',w.kind,'horizon_days',v_h,
            'subject', jsonb_build_object('name', r.name, 'close_date', r.close_date, 'amount_cents', r.amount_cents, 'stage', r.stage))
        ) RETURNING id INTO v_obj_id;
        UPDATE work_watcher_matches SET objective_id = v_obj_id WHERE watcher_id = w.id AND occurrence_key = v_occ;
        v_new := v_new + 1;
      END LOOP;

    -- ── NEW: date_horizon on commercial_agreements (configurable date_field) ──
    -- Opens a de_objectives case AND its typed continuity_cases facet, stamped
    -- with the motion (explicit config override, else derived from the date_field).
    ELSIF w.kind = 'date_horizon' AND v_src = 'commercial_agreements' THEN
      v_date_field := coalesce(w.config->>'date_field','renewal_date');
      FOR r IN
        SELECT sub.* FROM (
          SELECT a.id, coalesce(a.counterparty_name, a.title) AS name, a.account_id, a.party_side,
                 a.baseline_value_cents, a.status, a.agreement_type,
                 (CASE v_date_field
                    WHEN 'renewal_date'            THEN a.renewal_date
                    WHEN 'notice_deadline'         THEN a.notice_deadline
                    WHEN 'warranty_expiry'         THEN a.warranty_expiry
                    WHEN 'next_reorder_date'       THEN a.next_reorder_date
                    WHEN 'cancellation_deadline'   THEN a.cancellation_deadline
                    WHEN 'pricing_notice_deadline' THEN a.pricing_notice_deadline
                    WHEN 'replacement_date'        THEN a.replacement_date
                    ELSE a.renewal_date END) AS target_date
          FROM commercial_agreements a
          WHERE a.tenant_id = w.tenant_id
            AND (w.config->'status_filter' IS NULL OR a.status IN (SELECT jsonb_array_elements_text(w.config->'status_filter')))
        ) sub
        WHERE sub.target_date IS NOT NULL AND sub.target_date >= current_date
      LOOP
        SELECT min(h) INTO v_h FROM (SELECT (jsonb_array_elements_text(coalesce(w.config->'horizons_days','[90,60,30]'::jsonb)))::int AS h) hs WHERE h >= (r.target_date - current_date);
        IF v_h IS NULL THEN CONTINUE; END IF;
        v_occ := r.id::text || '|' || v_date_field || '|' || r.target_date::text || '|' || v_h::text;
        INSERT INTO work_watcher_matches (tenant_id, watcher_id, subject_ref, occurrence_key)
        VALUES (w.tenant_id, w.id, r.id::text, v_occ) ON CONFLICT (watcher_id, occurrence_key) DO NOTHING;
        GET DIAGNOSTICS v_inserted = ROW_COUNT; IF NOT v_inserted THEN CONTINUE; END IF;

        v_motion := coalesce(nullif(w.config->>'motion',''),
          CASE v_date_field
            WHEN 'renewal_date'            THEN 'renew'
            WHEN 'notice_deadline'         THEN 'renew'
            WHEN 'warranty_expiry'         THEN 'replace'
            WHEN 'next_reorder_date'       THEN 'reorder'
            WHEN 'replacement_date'        THEN 'replace'
            WHEN 'cancellation_deadline'   THEN 'renew'
            WHEN 'pricing_notice_deadline' THEN 'renegotiate'
            ELSE 'renew' END);

        v_title := w.label || ' — ' || r.name || ' (' || v_h || '-day, ' || v_date_field || ' ' || to_char(r.target_date, 'Mon DD') || ')';
        INSERT INTO de_objectives (tenant_id, de_id, title, description, entity_kind, entity_ref, status, priority, due_at, plan)
        VALUES (w.tenant_id, w.de_id, left(v_title, 200),
          'Opened by the Book of Work: ' || r.name || ' — ' || v_motion || ' motion. The ' || replace(v_date_field,'_',' ')
            || ' is ' || r.target_date::text || ' (' || (r.target_date - current_date) || ' days out). Work the ' || v_h || '-day motion per the playbook.',
          'commercial_agreement', r.id::text, 'open', (case when v_h <= 14 then 1 when v_h <= 30 then 2 when v_h <= 60 then 3 else 4 end), r.target_date::timestamptz,
          jsonb_build_object('source','book_of_work','watcher_id',w.id,'kind',w.kind,'horizon_days',v_h,'motion',v_motion,'date_field',v_date_field,
            'subject', jsonb_build_object('name', r.name, 'agreement_type', r.agreement_type, 'party_side', r.party_side,
              'target_date', r.target_date, 'baseline_value_cents', r.baseline_value_cents))
        ) RETURNING id INTO v_obj_id;
        UPDATE work_watcher_matches SET objective_id = v_obj_id WHERE watcher_id = w.id AND occurrence_key = v_occ;

        -- The typed facet: exactly one per case, driven off the SAME objective.
        INSERT INTO continuity_cases (objective_id, tenant_id, de_id, agreement_id, account_id, motion, stage_key, party_side, baseline_cents)
        VALUES (v_obj_id, w.tenant_id, w.de_id, r.id, r.account_id, v_motion, 'discovered', coalesce(r.party_side,'sell'), r.baseline_value_cents)
        ON CONFLICT (objective_id) DO NOTHING;
        INSERT INTO continuity_case_events (tenant_id, objective_id, to_stage, motion, actor_kind, summary, detail)
        VALUES (w.tenant_id, v_obj_id, 'discovered', v_motion, 'system',
          'Case opened by Book of Work — ' || v_motion || ' on ' || r.name || ' (' || replace(v_date_field,'_',' ') || ')',
          jsonb_build_object('watcher_id', w.id, 'date_field', v_date_field, 'horizon_days', v_h));
        v_new := v_new + 1;
      END LOOP;


    -- GENERIC date_horizon (catalog-driven; any non-legacy source)
    ELSIF w.kind = 'date_horizon' THEN
      SELECT * INTO v_cat FROM watch_source_catalog WHERE source_key = v_src AND active AND NOT legacy_bespoke;
      IF v_cat.source_key IS NULL THEN CONTINUE; END IF;
      v_datef := coalesce(w.config->>'date_field',
                   (SELECT column_name FROM watch_source_fields WHERE source_key = v_src AND role='date' ORDER BY column_name LIMIT 1));
      IF v_datef IS NULL OR NOT EXISTS (SELECT 1 FROM watch_source_fields WHERE source_key=v_src AND role='date' AND column_name=v_datef) THEN CONTINUE; END IF;
      v_cap := least(coalesce((w.config->>'max_per_run')::int, 1000), 1000);
      v_where := format('%I = $1 AND %I IS NOT NULL AND %I >= current_date', v_cat.tenant_column, v_datef, v_datef)
                 || build_base_predicates(v_cat.base_predicates)
                 || format(' AND ($2::text[] IS NULL OR %I = ANY($2))', v_cat.status_column);
      v_sql := format('SELECT %I::text AS _id, to_jsonb(t.*) AS _row FROM %I t WHERE %s ORDER BY %I LIMIT %s',
                      v_cat.id_column, v_cat.table_name, v_where, v_datef, v_cap);
      FOR r IN EXECUTE v_sql USING w.tenant_id,
                 CASE WHEN w.config ? 'status_filter' THEN ARRAY(SELECT jsonb_array_elements_text(w.config->'status_filter')) ELSE NULL::text[] END
      LOOP
        v_row := r._row; v_id := r._id;
        SELECT min(h) INTO v_h FROM (SELECT (jsonb_array_elements_text(coalesce(w.config->'horizons_days', v_cat.default_horizons)))::int AS h) hs WHERE h >= ((v_row->>v_datef)::date - current_date);
        IF v_h IS NULL THEN CONTINUE; END IF;
        v_occ := v_id || '|' || v_datef || '|' || (v_row->>v_datef) || '|' || v_h::text;
        INSERT INTO work_watcher_matches (tenant_id, watcher_id, subject_ref, occurrence_key)
        VALUES (w.tenant_id, w.id, v_id, v_occ) ON CONFLICT (watcher_id, occurrence_key) DO NOTHING;
        GET DIAGNOSTICS v_inserted = ROW_COUNT; IF NOT v_inserted THEN CONTINUE; END IF;
        v_label := watcher_label(v_cat.label_columns, v_row, v_cat.entity_kind, v_id);
        v_subject := jsonb_object_agg_subset(v_row, v_cat.subject_columns);
        v_title := w.label || ' — ' || v_label || ' (' || v_h || '-day, ' || replace(v_datef,'_',' ') || ' ' || to_char((v_row->>v_datef)::date,'Mon DD') || ')';
        INSERT INTO de_objectives (tenant_id, de_id, title, description, entity_kind, entity_ref, status, priority, due_at, plan)
        VALUES (w.tenant_id, w.de_id, left(v_title,200),
          'Opened by the Book of Work: ' || v_label || ' — ' || replace(v_datef,'_',' ') || ' is ' || (v_row->>v_datef) || ' (' || (((v_row->>v_datef)::date - current_date)) || ' days out). Work the ' || v_h || '-day motion per the playbook.',
          v_cat.entity_kind, v_id, 'open', (case when v_h <= 14 then 1 when v_h <= 30 then 2 when v_h <= 60 then 3 else 4 end), (v_row->>v_datef)::timestamptz,
          jsonb_build_object('source','book_of_work','watcher_id',w.id,'kind',w.kind,'watch_source',v_src,'date_field',v_datef,'horizon_days',v_h,'subject', v_subject))
        RETURNING id INTO v_obj_id;
        UPDATE work_watcher_matches SET objective_id=v_obj_id WHERE watcher_id=w.id AND occurrence_key=v_occ;
        v_new := v_new + 1;
      END LOOP;

    -- ── state_condition ──
    ELSIF w.kind = 'state_condition' AND v_src = 'customer_accounts' THEN
      FOR r IN
        SELECT ca.id, ca.name, ca.health_score, ca.status, ca.arr_cents, ca.tier
        FROM customer_accounts ca WHERE ca.tenant_id = w.tenant_id
          AND CASE w.config->>'field'
                WHEN 'health_score' THEN CASE w.config->>'op'
                    WHEN 'lt' THEN ca.health_score < (w.config->>'value')::numeric WHEN 'lte' THEN ca.health_score <= (w.config->>'value')::numeric
                    WHEN 'gt' THEN ca.health_score > (w.config->>'value')::numeric WHEN 'gte' THEN ca.health_score >= (w.config->>'value')::numeric
                    WHEN 'eq' THEN ca.health_score = (w.config->>'value')::numeric ELSE ca.health_score <> (w.config->>'value')::numeric END
                WHEN 'arr_cents' THEN CASE w.config->>'op'
                    WHEN 'lt' THEN ca.arr_cents < (w.config->>'value')::numeric WHEN 'lte' THEN ca.arr_cents <= (w.config->>'value')::numeric
                    WHEN 'gt' THEN ca.arr_cents > (w.config->>'value')::numeric WHEN 'gte' THEN ca.arr_cents >= (w.config->>'value')::numeric
                    WHEN 'eq' THEN ca.arr_cents = (w.config->>'value')::numeric ELSE ca.arr_cents <> (w.config->>'value')::numeric END
                WHEN 'status' THEN CASE w.config->>'op' WHEN 'eq' THEN ca.status = w.config->>'value' ELSE ca.status <> w.config->>'value' END
                WHEN 'tier' THEN CASE w.config->>'op' WHEN 'eq' THEN ca.tier = w.config->>'value' ELSE ca.tier <> w.config->>'value' END
                ELSE false END
      LOOP
        v_occ := r.id::text || '|' || (w.config->>'field') || (w.config->>'op') || (w.config->>'value');
        INSERT INTO work_watcher_matches (tenant_id, watcher_id, subject_ref, occurrence_key)
        VALUES (w.tenant_id, w.id, r.id::text, v_occ) ON CONFLICT (watcher_id, occurrence_key) DO NOTHING;
        GET DIAGNOSTICS v_inserted = ROW_COUNT; IF NOT v_inserted THEN CONTINUE; END IF;
        v_title := w.label || ' — ' || r.name;
        INSERT INTO de_objectives (tenant_id, de_id, title, description, entity_kind, entity_ref, status, priority, due_at, plan)
        VALUES (w.tenant_id, w.de_id, left(v_title, 200),
          'Opened by the Book of Work: ' || r.name || ' matched "' || (w.config->>'field') || ' ' || (w.config->>'op') || ' ' || (w.config->>'value') || '". Assess and work per the playbook.',
          'customer_account', r.id::text, 'open', 2,
          response_window_due_at(w.config, now()),
          jsonb_build_object('source','book_of_work','watcher_id',w.id,'kind',w.kind,'condition', w.config,
            'subject', jsonb_build_object('name', r.name, 'health_score', r.health_score, 'status', r.status))
        ) RETURNING id INTO v_obj_id;
        UPDATE work_watcher_matches SET objective_id = v_obj_id WHERE watcher_id = w.id AND occurrence_key = v_occ;
        v_new := v_new + 1;
      END LOOP;

    ELSIF w.kind = 'state_condition' AND v_src = 'opportunities' THEN
      FOR r IN
        SELECT o.id, coalesce(o.name, o.company_name, 'opportunity') AS name, o.stage, o.amount_cents, o.close_date
        FROM opportunities o WHERE o.tenant_id = w.tenant_id AND o.closed_at IS NULL
          AND CASE w.config->>'field'
                WHEN 'amount_cents' THEN CASE w.config->>'op'
                    WHEN 'lt' THEN o.amount_cents < (w.config->>'value')::numeric WHEN 'lte' THEN o.amount_cents <= (w.config->>'value')::numeric
                    WHEN 'gt' THEN o.amount_cents > (w.config->>'value')::numeric WHEN 'gte' THEN o.amount_cents >= (w.config->>'value')::numeric
                    WHEN 'eq' THEN o.amount_cents = (w.config->>'value')::numeric ELSE o.amount_cents <> (w.config->>'value')::numeric END
                WHEN 'stage' THEN CASE w.config->>'op' WHEN 'eq' THEN o.stage = w.config->>'value' ELSE o.stage <> w.config->>'value' END
                ELSE false END
      LOOP
        v_occ := r.id::text || '|' || (w.config->>'field') || (w.config->>'op') || (w.config->>'value');
        INSERT INTO work_watcher_matches (tenant_id, watcher_id, subject_ref, occurrence_key)
        VALUES (w.tenant_id, w.id, r.id::text, v_occ) ON CONFLICT (watcher_id, occurrence_key) DO NOTHING;
        GET DIAGNOSTICS v_inserted = ROW_COUNT; IF NOT v_inserted THEN CONTINUE; END IF;
        v_title := w.label || ' — ' || r.name;
        INSERT INTO de_objectives (tenant_id, de_id, title, description, entity_kind, entity_ref, status, priority, due_at, plan)
        VALUES (w.tenant_id, w.de_id, left(v_title, 200),
          'Opened by the Book of Work: opportunity ' || r.name || ' matched "' || (w.config->>'field') || ' ' || (w.config->>'op') || ' ' || (w.config->>'value') || '". Advance it per the playbook.',
          'opportunity', r.id::text, 'open', 2,
          response_window_due_at(w.config, now()),
          jsonb_build_object('source','book_of_work','watcher_id',w.id,'kind',w.kind,'condition', w.config,
            'subject', jsonb_build_object('name', r.name, 'stage', r.stage, 'amount_cents', r.amount_cents, 'close_date', r.close_date))
        ) RETURNING id INTO v_obj_id;
        UPDATE work_watcher_matches SET objective_id = v_obj_id WHERE watcher_id = w.id AND occurrence_key = v_occ;
        v_new := v_new + 1;
      END LOOP;


    -- GENERIC state_condition (catalog-driven; any non-legacy source)
    ELSIF w.kind = 'state_condition' THEN
      SELECT * INTO v_cat FROM watch_source_catalog WHERE source_key = v_src AND active AND NOT legacy_bespoke;
      IF v_cat.source_key IS NULL THEN CONTINUE; END IF;
      v_field := w.config->>'field'; v_op := w.config->>'op';
      SELECT value_type INTO v_vt FROM watch_source_fields WHERE source_key=v_src AND role='state' AND column_name=v_field AND v_op = ANY (allowed_ops);
      IF v_vt IS NULL THEN CONTINUE; END IF;
      v_cast := CASE WHEN v_vt = 'numeric' THEN '::numeric' ELSE '' END;
      v_where := format('%I = $1', v_cat.tenant_column) || build_base_predicates(v_cat.base_predicates)
                 || format(' AND %I %s $2%s', v_field, sql_op(v_op), v_cast)
                 || format(' AND NOT EXISTS (SELECT 1 FROM work_watcher_matches m WHERE m.watcher_id = $3 AND m.subject_ref = t.%I::text)', v_cat.id_column);
      v_sql := format('SELECT %I::text AS _id, to_jsonb(t.*) AS _row FROM %I t WHERE %s', v_cat.id_column, v_cat.table_name, v_where);
      FOR r IN EXECUTE v_sql USING w.tenant_id, (w.config->>'value'), w.id
      LOOP
        v_row := r._row; v_id := r._id;
        v_occ := v_id || '|' || v_field || v_op || (w.config->>'value');
        INSERT INTO work_watcher_matches (tenant_id, watcher_id, subject_ref, occurrence_key)
        VALUES (w.tenant_id, w.id, v_id, v_occ) ON CONFLICT (watcher_id, occurrence_key) DO NOTHING;
        GET DIAGNOSTICS v_inserted = ROW_COUNT; IF NOT v_inserted THEN CONTINUE; END IF;
        v_label := watcher_label(v_cat.label_columns, v_row, v_cat.entity_kind, v_id);
        v_subject := jsonb_object_agg_subset(v_row, v_cat.subject_columns);
        INSERT INTO de_objectives (tenant_id, de_id, title, description, entity_kind, entity_ref, status, priority, due_at, plan)
        VALUES (w.tenant_id, w.de_id, left(w.label || ' — ' || v_label,200),
          'Opened by the Book of Work: ' || v_label || ' matched "' || v_field || ' ' || v_op || ' ' || (w.config->>'value') || '". Assess and work per the playbook.',
          v_cat.entity_kind, v_id, 'open', 2,
          response_window_due_at(w.config, now()),
          jsonb_build_object('source','book_of_work','watcher_id',w.id,'kind',w.kind,'watch_source',v_src,'condition',w.config,'subject', v_subject))
        RETURNING id INTO v_obj_id;
        UPDATE work_watcher_matches SET objective_id=v_obj_id WHERE watcher_id=w.id AND occurrence_key=v_occ;
        v_new := v_new + 1;
      END LOOP;

    -- ── metric_threshold (unchanged from mig 220) ──
    ELSIF w.kind = 'metric_threshold' THEN
      SELECT k.metric_key AS mkey, k.value, k.as_of INTO r
      FROM de_kpi_readings k WHERE k.tenant_id = w.tenant_id AND k.de_id = w.de_id AND k.metric_key = w.config->>'metric_key'
      ORDER BY k.as_of DESC, k.created_at DESC LIMIT 1;
      IF r.mkey IS NOT NULL AND ((w.config->>'op' = 'lt' AND r.value < (w.config->>'value')::numeric) OR (w.config->>'op' = 'gt' AND r.value > (w.config->>'value')::numeric)) THEN
        v_occ := r.mkey || '|' || r.as_of::text || '|' || (w.config->>'op') || (w.config->>'value');
        INSERT INTO work_watcher_matches (tenant_id, watcher_id, subject_ref, occurrence_key)
        VALUES (w.tenant_id, w.id, r.mkey, v_occ) ON CONFLICT (watcher_id, occurrence_key) DO NOTHING;
        GET DIAGNOSTICS v_inserted = ROW_COUNT;
        IF v_inserted THEN
          INSERT INTO de_objectives (tenant_id, de_id, title, description, entity_kind, entity_ref, status, priority, due_at, plan)
          VALUES (w.tenant_id, w.de_id, left(w.label || ' — ' || r.mkey || ' at ' || r.value, 200),
            'Opened by the Book of Work: metric "' || r.mkey || '" read ' || r.value || ' on ' || r.as_of || ', crossing the ' || (w.config->>'op') || ' ' || (w.config->>'value') || ' line. Investigate per the playbook.',
            'metric', r.mkey, 'open', 2,
            response_window_due_at(w.config, now()),
            jsonb_build_object('source','book_of_work','watcher_id',w.id,'kind',w.kind,'reading', jsonb_build_object('metric_key', r.mkey, 'value', r.value, 'as_of', r.as_of))
          ) RETURNING id INTO v_obj_id;
          UPDATE work_watcher_matches SET objective_id = v_obj_id WHERE watcher_id = w.id AND occurrence_key = v_occ;
          v_new := v_new + 1;
        END IF;
      END IF;

    -- ── schedule (unchanged from mig 220) ──
    ELSIF w.kind = 'schedule' THEN
      IF w.next_fire_at IS NULL THEN
        UPDATE work_watchers SET next_fire_at = now() + make_interval(mins => (w.config->>'interval_minutes')::int) WHERE id = w.id;
      ELSIF now() >= w.next_fire_at THEN
        v_occ := to_char(w.next_fire_at, 'YYYY-MM-DD"T"HH24:MI');
        INSERT INTO work_watcher_matches (tenant_id, watcher_id, subject_ref, occurrence_key)
        VALUES (w.tenant_id, w.id, 'schedule', v_occ) ON CONFLICT (watcher_id, occurrence_key) DO NOTHING;
        GET DIAGNOSTICS v_inserted = ROW_COUNT;
        IF v_inserted THEN
          INSERT INTO de_objectives (tenant_id, de_id, title, description, entity_kind, entity_ref, status, priority, due_at, plan)
          VALUES (w.tenant_id, w.de_id, left(w.label, 200),
            'Opened by the Book of Work on schedule (' || coalesce(w.description, w.label) || '). Run the recurring motion per the playbook.',
            'schedule', v_occ, 'open', 3, response_window_due_at(w.config, now()), jsonb_build_object('source','book_of_work','watcher_id',w.id,'kind',w.kind,'fired_at', now())
          ) RETURNING id INTO v_obj_id;
          UPDATE work_watcher_matches SET objective_id = v_obj_id WHERE watcher_id = w.id AND occurrence_key = v_occ;
          v_new := v_new + 1;
        END IF;
        UPDATE work_watchers SET next_fire_at = now() + make_interval(mins => (w.config->>'interval_minutes')::int) WHERE id = w.id;
      END IF;
    END IF;
    EXCEPTION WHEN OTHERS THEN
      BEGIN PERFORM append_audit_event_internal(w.tenant_id, 'system', 'system',
        'Book of Work watcher "' || w.label || '" errored and was skipped this tick', 'playbook_step',
        jsonb_build_object('kind','book_of_work_error','watcher_id', w.id, 'error', SQLERRM));
      EXCEPTION WHEN OTHERS THEN NULL; END;
      CONTINUE;
    END;

    UPDATE work_watchers SET last_run_at = now(), last_match_count = v_new WHERE id = w.id;
    v_total := v_total + v_new;
    IF v_new > 0 THEN
      BEGIN PERFORM append_audit_event_internal(w.tenant_id, coalesce(v_de_name, 'DE'), 'de',
          coalesce(v_de_name, 'DE') || ' found ' || v_new || ' new work item(s) via Book of Work watcher "' || w.label || '"',
          'playbook_step', jsonb_build_object('kind','book_of_work','watcher_id', w.id, 'watcher_kind', w.kind, 'new_cases', v_new));
      EXCEPTION WHEN OTHERS THEN NULL; END;
    END IF;
  END LOOP;
  RETURN jsonb_build_object('ok', true, 'watchers_run', v_watchers, 'cases_opened', v_total);
END; $function$;

CREATE OR REPLACE FUNCTION public.sample_messages_for_online_eval(p_limit integer DEFAULT 5, p_window_minutes integer DEFAULT 90, p_tenant_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(message_id uuid, tenant_id uuid, de_id uuid, conversation_id uuid, question text, answer text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select m.id, m.tenant_id, c.de_id, m.conversation_id,
         -- the most recent customer turn before this answer
         (select um.content from de_messages um
           where um.conversation_id = m.conversation_id and um.role = 'user' and um.created_at <= m.created_at
           order by um.created_at desc limit 1) as question,
         m.content as answer
  from de_messages m
  join de_conversations c on c.id = m.conversation_id
  where m.role = 'assistant'
    and m.delivery = 'sent'                     -- only answers a customer actually received
    and not m.escalated
    -- mig 706: A CERTIFICATION EXAM IS NOT PRODUCTION WORK (571 lineage,
    -- on the channel axis 671 split the corpus by). Exams run the live
    -- pipeline on purpose and their answers are marked delivered, so without
    -- this line the "continuous production quality" organ grades the exam:
    -- measured 2026-08-12, 38 of 141 online judgments were exam answers.
    -- A null channel is KEPT — unknown provenance must not erase real work.
    and c.channel is distinct from 'exam'
    and m.created_at >= now() - make_interval(mins => greatest(5, p_window_minutes))
    and (p_tenant_id is null or m.tenant_id = p_tenant_id)
    and not exists (select 1 from eval_judgments j where j.message_id = m.id)
    and exists (select 1 from de_messages um where um.conversation_id = m.conversation_id and um.role = 'user' and um.created_at <= m.created_at)
  order by m.created_at desc
  limit greatest(1, least(50, p_limit));
$function$;

CREATE OR REPLACE FUNCTION public.save_adapter_template(p_name text, p_description text, p_category text, p_definition jsonb, p_id uuid DEFAULT NULL::uuid, p_tenant_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tenant uuid;
  v_is_active boolean;
  v_id uuid;
  v_op record;
  v_legal jsonb := '{
    "crm":            ["search_accounts","get_account","search_conversations","search_opportunities"],
    "helpdesk":       ["search_tickets","get_ticket","search_articles"],
    "knowledge_base": ["search_articles","get_article"],
    "erp_financials": ["search_invoices","get_invoice"],
    "billing":        ["get_subscription","search_invoices"],
    "payroll_hcm":    ["get_employee","search_time_off"],
    "pos":            ["search_orders","get_order"],
    "product_system": ["get_record","search_records"],
    "other":          ["get_record","search_records"]
  }'::jsonb;
  v_auth_type text;
begin
  if coalesce(auth.role(), '') = 'service_role' then
    v_tenant := p_tenant_id;
  else
    select coalesce(is_active, true) into v_is_active from profiles where user_id = auth.uid();
    if v_is_active is false then
      raise exception 'account is deactivated';
    end if;
    v_tenant := auth_tenant_id();
  end if;
  if v_tenant is null then
    raise exception 'no tenant — sign in as a workspace member (or pass p_tenant_id with the service role)';
  end if;

  if p_name is null or length(trim(p_name)) = 0 then
    raise exception 'template needs a name';
  end if;
  if not (v_legal ? p_category) then
    raise exception 'unknown category "%"', p_category;
  end if;

  v_auth_type := p_definition #>> '{auth,type}';
  if v_auth_type is null or v_auth_type not in ('api_key_header','bearer','basic','oauth2_client_credentials','none') then
    raise exception 'definition.auth.type must be one of api_key_header, bearer, basic, oauth2_client_credentials, none';
  end if;
  if v_auth_type = 'api_key_header' and coalesce(p_definition #>> '{auth,header_name}', '') = '' then
    raise exception 'API-key auth needs auth.header_name (which header carries the key)';
  end if;
  if v_auth_type = 'oauth2_client_credentials' and coalesce(p_definition #>> '{auth,token_url}', '') = '' then
    raise exception 'OAuth2 client-credentials auth needs auth.token_url';
  end if;
  if coalesce(p_definition ->> 'base_url_template', '') !~ '^https?://' then
    raise exception 'definition.base_url_template must be a full URL starting with https://';
  end if;
  if p_definition -> 'ops' is null or p_definition -> 'ops' = '{}'::jsonb then
    raise exception 'bind at least one operation (definition.ops is empty)';
  end if;
  for v_op in select key, value from jsonb_each(p_definition -> 'ops') loop
    if not (v_legal -> p_category) ? v_op.key then
      raise exception '"%" is not a legal operation for the % category — legal ops: %',
        v_op.key, p_category, (select string_agg(x, ', ') from jsonb_array_elements_text(v_legal -> p_category) x);
    end if;
    if v_op.value #> '{response,items_path}' is null then
      raise exception 'operation "%": response.items_path is required — where in the response do the results live? Use "" if the response root is the list', v_op.key;
    end if;
    if coalesce(v_op.value #>> '{response,id_path}', '') = '' then
      raise exception 'operation "%": response.id_path is required (which field is the record id?)', v_op.key;
    end if;
    if coalesce(v_op.value #>> '{response,title_path}', '') = '' then
      raise exception 'operation "%": response.title_path is required (which field is the title?)', v_op.key;
    end if;
    if coalesce(v_op.value ->> 'method', '') not in ('GET','POST') then
      raise exception 'operation "%": method must be GET or POST', v_op.key;
    end if;
    if coalesce(v_op.value ->> 'path_template', '') !~ '^/' then
      raise exception 'operation "%": path_template must start with "/"', v_op.key;
    end if;
  end loop;
  if coalesce(p_definition #>> '{test_op,op}', '') = '' then
    raise exception 'definition.test_op is required — which operation proves the connection works?';
  end if;
  if p_definition -> 'ops' -> (p_definition #>> '{test_op,op}') is null then
    raise exception 'test_op "%" is not one of the bound operations', p_definition #>> '{test_op,op}';
  end if;

  if p_id is not null then
    update adapter_templates
      set name = trim(p_name), description = coalesce(p_description, ''),
          category = p_category, definition = p_definition
      where id = p_id and scope = 'tenant' and tenant_id = v_tenant
      returning id into v_id;
    if v_id is null then
      raise exception 'template not found in your workspace (platform templates cannot be edited — save a copy instead)';
    end if;
  else
    insert into adapter_templates (scope, tenant_id, name, description, category, definition, created_by)
    values ('tenant', v_tenant, trim(p_name), coalesce(p_description, ''), p_category, p_definition, auth.uid())
    returning id into v_id;
  end if;
  return v_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.save_de_config(p_de_id uuid, p_template_key text, p_values jsonb)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tenant_id UUID := public.auth_tenant_id();
  v_user_id UUID := auth.uid();
  v_instance_id UUID;
BEGIN
  IF v_user_id IS NULL OR v_tenant_id IS NULL THEN
    RAISE EXCEPTION 'not_authenticated';
  END IF;
  -- DE must belong to the caller's tenant
  PERFORM 1 FROM digital_employees WHERE id = p_de_id AND tenant_id = v_tenant_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'de_not_in_tenant'; END IF;

  INSERT INTO config_schema_instances (tenant_id, de_id, template_key, values, updated_by)
  VALUES (v_tenant_id, p_de_id, p_template_key, p_values, v_user_id)
  ON CONFLICT (tenant_id, de_id, template_key)
  DO UPDATE SET values = EXCLUDED.values, updated_at = now(), updated_by = v_user_id
  RETURNING instance_id INTO v_instance_id;

  RETURN json_build_object('ok', true, 'instance_id', v_instance_id, 'updated_at', now()::text);
END$function$;

CREATE OR REPLACE FUNCTION public.schedule_case_continuation(p_objective_id uuid, p_kind text, p_fire_at timestamp with time zone, p_instruction text DEFAULT ''::text, p_awaiting_ref text DEFAULT NULL::text, p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tenant uuid; v_de uuid; v_event uuid; v_is_service boolean := coalesce(auth.role(),'') = 'service_role';
BEGIN
  IF p_kind NOT IN ('wait','follow_up') THEN RETURN jsonb_build_object('ok', false, 'error', 'bad_kind'); END IF;
  IF p_fire_at IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'fire_at_required'); END IF;

  SELECT tenant_id, de_id INTO v_tenant, v_de FROM de_objectives WHERE id = p_objective_id;
  IF v_tenant IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'objective_not_found'); END IF;
  -- A JWT caller must be a member of the case's tenant; service role (de-work,
  -- playbook-execute) is trusted with an explicit objective it already resolved.
  IF NOT v_is_service AND v_tenant IS DISTINCT FROM public.auth_tenant_id() THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_tenant_member');
  END IF;

  INSERT INTO de_case_events (tenant_id, de_id, objective_id, kind, fire_at, awaiting_ref, instruction, payload, created_by)
  VALUES (v_tenant, v_de, p_objective_id, p_kind, p_fire_at, p_awaiting_ref, left(coalesce(p_instruction,''), 2000), coalesce(p_payload,'{}'::jsonb), auth.uid())
  RETURNING id INTO v_event;

  -- Park the case: it sleeps until the continuation is due. de-work only
  -- re-plans status='open' cases, so an in_progress case is left alone.
  UPDATE de_objectives
     SET status = CASE WHEN status IN ('achieved','abandoned') THEN status ELSE 'in_progress' END,
         next_wake_at = p_fire_at,
         updated_at = now()
   WHERE id = p_objective_id;

  BEGIN
    PERFORM append_audit_event_internal(v_tenant,
      (SELECT coalesce(persona_name, name) FROM digital_employees WHERE id = v_de), 'de',
      'Case paused — ' || p_kind || (CASE WHEN p_awaiting_ref IS NOT NULL THEN ' awaiting reply' ELSE '' END)
        || ' until ' || to_char(p_fire_at, 'Mon DD HH24:MI') || ': ' || left(coalesce(p_instruction,''), 120),
      'playbook_step',
      jsonb_build_object('kind','case_continuation_scheduled','event_id',v_event,'objective_id',p_objective_id,'continuation_kind',p_kind,'fire_at',p_fire_at,'awaiting_ref',p_awaiting_ref));
  EXCEPTION WHEN OTHERS THEN NULL; END;

  RETURN jsonb_build_object('ok', true, 'event_id', v_event, 'fire_at', p_fire_at);
END; $function$;

CREATE OR REPLACE FUNCTION public.scim_link_matches_profile()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_profile_tenant uuid; v_profile_user uuid; v_found boolean;
BEGIN
  SELECT p.tenant_id, p.user_id, true INTO v_profile_tenant, v_profile_user, v_found
    FROM public.profiles p WHERE p.id = NEW.profile_id;

  IF v_found IS NOT TRUE THEN
    RAISE EXCEPTION 'scim_user_links: profile % does not exist', NEW.profile_id;
  END IF;
  -- IS DISTINCT FROM, not <>: a NULL profile tenant (an unclaimed account) must
  -- FAIL this check, and `NULL <> NEW.tenant_id` would evaluate to NULL and let
  -- the row through. Same null-logic trap migration 369 fixed in a guard.
  IF v_profile_tenant IS DISTINCT FROM NEW.tenant_id THEN
    RAISE EXCEPTION 'scim_user_links: profile % belongs to tenant %, refusing to link it to tenant %',
      NEW.profile_id, coalesce(v_profile_tenant::text, '<none>'), NEW.tenant_id;
  END IF;
  IF v_profile_user IS DISTINCT FROM NEW.user_id THEN
    RAISE EXCEPTION 'scim_user_links: user_id % is not the auth user of profile %',
      NEW.user_id, NEW.profile_id;
  END IF;
  RETURN NEW;
END $function$;

CREATE OR REPLACE FUNCTION public.scim_provision_begin(p_token text, p_user_name text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_ctx jsonb; v_tenant uuid; v_adopt boolean; v_uname text;
  v_link public.scim_user_links; v_auth_id uuid; v_meta_tenant text;
  v_profile_tenant uuid; v_has_profile boolean := false;
BEGIN
  v_ctx := public.scim_token_context(p_token);
  IF v_ctx IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'unauthorized'); END IF;
  v_tenant := (v_ctx->>'tenant_id')::uuid;
  v_adopt  := coalesce((v_ctx->>'allow_account_adoption')::boolean, false);

  v_uname := lower(btrim(coalesce(p_user_name, '')));
  -- Documented constraint: userName IS the login email here. Supabase Auth is
  -- keyed on email, so a userName that is not an email could never be matched
  -- to an account and the record would be permanently unusable. Better to
  -- refuse at provisioning time than to create a ghost.
  IF v_uname = '' OR position('@' IN v_uname) < 2 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_username',
                              'detail', 'userName must be the user''s email address');
  END IF;

  SELECT * INTO v_link FROM public.scim_user_links
   WHERE tenant_id = v_tenant AND lower(user_name) = v_uname;

  IF v_link.id IS NOT NULL AND v_link.deleted_at IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'conflict',
                              'detail', 'a user with this userName already exists');
  END IF;
  IF v_link.id IS NOT NULL THEN
    -- Rehire: the record was soft-deleted. Reuse it rather than mint a second
    -- SCIM id for the same human.
    RETURN jsonb_build_object('ok', true, 'mode', 'link', 'tenant_id', v_tenant,
                              'user_id', v_link.user_id,
                              'reason', 'reviving a previously deprovisioned record');
  END IF;

  SELECT u.id, u.raw_app_meta_data->>'scim_tenant' INTO v_auth_id, v_meta_tenant
    FROM auth.users u WHERE lower(u.email) = v_uname;

  IF v_auth_id IS NULL THEN
    -- tenant_id is echoed back so the edge function can stamp it into the new
    -- account's app_metadata. It is not a tenant the caller chose: it came from
    -- the token, and scim_user_upsert re-derives it rather than trusting it.
    RETURN jsonb_build_object('ok', true, 'mode', 'create', 'tenant_id', v_tenant);
  END IF;

  -- FOUND, not a `SELECT ..., true INTO` sentinel: a SELECT INTO that matches
  -- no rows sets EVERY target variable to NULL, including the sentinel, so the
  -- sentinel would be NULL rather than false and the branches below would be
  -- three-valued instead of two.
  SELECT p.tenant_id INTO v_profile_tenant FROM public.profiles p WHERE p.user_id = v_auth_id;
  v_has_profile := FOUND;

  IF v_has_profile AND v_profile_tenant = v_tenant THEN
    -- Already a member of THIS workspace — SCIM simply starts managing them.
    -- This is the ordinary path for a team that existed before SCIM was turned
    -- on, and it crosses no boundary: v_tenant came from the token.
    RETURN jsonb_build_object('ok', true, 'mode', 'link', 'tenant_id', v_tenant,
                              'user_id', v_auth_id,
                              'reason', 'existing member of this workspace');
  END IF;

  IF v_has_profile AND v_profile_tenant IS NOT NULL THEN
    -- ⚠ THE TAKEOVER ATTEMPT. Refused unconditionally: there is no flag, no
    -- setting and no request shape that re-homes another workspace's account.
    -- The message says nothing about which workspace — that would turn this
    -- endpoint into a directory of who-works-where across all 16 tenants.
    RETURN jsonb_build_object('ok', false, 'error', 'conflict',
      'detail', 'this email is already in use by an account outside this workspace');
  END IF;

  -- Account exists but belongs to no workspace.
  IF v_meta_tenant = v_tenant::text THEN
    -- We minted it ourselves for this tenant. raw_app_meta_data is writable
    -- only by the service role — never by the account holder — so this is a
    -- provenance marker, not a self-asserted claim.
    RETURN jsonb_build_object('ok', true, 'mode', 'link', 'tenant_id', v_tenant,
                              'user_id', v_auth_id,
                              'reason', 'completing a provisioning run this token started');
  END IF;
  IF v_adopt THEN
    RETURN jsonb_build_object('ok', true, 'mode', 'link', 'tenant_id', v_tenant,
                              'user_id', v_auth_id,
                              'reason', 'account adoption is enabled for this token');
  END IF;

  RETURN jsonb_build_object('ok', false, 'error', 'conflict',
    'detail', 'an account with this email exists but is not a member of this workspace; '
              'a workspace admin must add it, or enable account adoption on this SCIM token');
END $function$;

CREATE OR REPLACE FUNCTION public.scim_token_context(p_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_hash text; v_id uuid; v_tenant uuid; v_adopt boolean; v_name text;
BEGIN
  IF p_token IS NULL OR length(p_token) < 32 THEN RETURN NULL; END IF;

  v_hash := encode(extensions.digest(p_token, 'sha256'), 'hex');

  -- One indexed equality on the digest. There is no comparison against the
  -- secret itself anywhere, so there is no byte-at-a-time timing signal to
  -- leak — the lookup either hits the unique index or it does not.
  --
  -- A suspended tenant's token stops working here rather than at 200 call
  -- sites: status is joined in, not checked later.
  SELECT k.id, k.tenant_id, k.allow_account_adoption, k.name
    INTO v_id, v_tenant, v_adopt, v_name
    FROM public.scim_tokens k
    JOIN public.tenants t ON t.id = k.tenant_id
   WHERE k.token_hash = v_hash
     AND k.revoked_at IS NULL
     AND t.status IN ('active', 'trial');

  IF v_tenant IS NULL THEN RETURN NULL; END IF;

  UPDATE public.scim_tokens SET last_used_at = now() WHERE id = v_id;

  RETURN jsonb_build_object('token_id', v_id, 'tenant_id', v_tenant,
                            'allow_account_adoption', v_adopt, 'name', v_name);
END $function$;

CREATE OR REPLACE FUNCTION public.scim_token_issue(p_tenant uuid, p_name text, p_allow_account_adoption boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_body text; v_token text; v_hash text; v_id uuid; v_actor text;
BEGIN
  -- coalesce(..., false) IS NOT TRUE, never `IF NOT can_admin...`.
  -- can_admin_tenant_internal returns NULL for a caller with no tenant (NULL =
  -- p_tenant is NULL, not false), and `IF NOT NULL THEN` does not fire — the
  -- guard would silently pass. This is the fail-open shape migration 369
  -- removed from set_improvement_publish_scope; it does not get to come back.
  IF coalesce(public.can_admin_tenant_internal(p_tenant), false) IS NOT TRUE THEN
    RAISE EXCEPTION 'not authorized to issue SCIM tokens for this workspace';
  END IF;
  IF p_name IS NULL OR btrim(p_name) = '' THEN
    RAISE EXCEPTION 'a name is required so this token can be told apart from the others';
  END IF;

  -- 32 random bytes = 256 bits. Not guessable, so the rate limit on the edge
  -- function is about abuse volume, not about protecting this secret.
  v_body  := encode(extensions.gen_random_bytes(32), 'hex');
  v_token := 'dtscim_' || v_body;
  v_hash  := encode(extensions.digest(v_token, 'sha256'), 'hex');

  INSERT INTO public.scim_tokens (tenant_id, token_hash, token_prefix, name,
                                  allow_account_adoption, created_by)
  VALUES (p_tenant, v_hash, 'dtscim_' || substr(v_hash, 1, 6), btrim(p_name),
          coalesce(p_allow_account_adoption, false), auth.uid())
  RETURNING id INTO v_id;

  SELECT coalesce(full_name, 'a workspace admin') INTO v_actor
    FROM public.profiles WHERE user_id = auth.uid();

  PERFORM public.append_audit_event_internal(
    p_tenant, coalesce(v_actor, 'a workspace admin'), 'human',
    format('Issued SCIM provisioning token "%s"', btrim(p_name)),
    'access_control',
    jsonb_build_object('kind', 'scim_token_issued', 'token_id', v_id,
                       'prefix', 'dtscim_' || substr(v_hash, 1, 6),
                       'allow_account_adoption', coalesce(p_allow_account_adoption, false)));

  -- The only moment the plaintext exists outside the caller's IdP config.
  RETURN jsonb_build_object(
    'ok', true, 'id', v_id, 'token', v_token,
    'prefix', 'dtscim_' || substr(v_hash, 1, 6), 'name', btrim(p_name));
END $function$;

CREATE OR REPLACE FUNCTION public.scim_token_revoke(p_token_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tenant uuid; v_name text; v_actor text;
BEGIN
  SELECT tenant_id, name INTO v_tenant, v_name
    FROM public.scim_tokens WHERE id = p_token_id;
  IF v_tenant IS NULL THEN RAISE EXCEPTION 'token not found'; END IF;
  IF coalesce(public.can_admin_tenant_internal(v_tenant), false) IS NOT TRUE THEN
    RAISE EXCEPTION 'not authorized';
  END IF;

  UPDATE public.scim_tokens
     SET revoked_at = coalesce(revoked_at, now()), revoked_by = auth.uid()
   WHERE id = p_token_id;

  SELECT coalesce(full_name, 'a workspace admin') INTO v_actor
    FROM public.profiles WHERE user_id = auth.uid();
  PERFORM public.append_audit_event_internal(
    v_tenant, coalesce(v_actor, 'a workspace admin'), 'human',
    format('Revoked SCIM provisioning token "%s"', v_name), 'access_control',
    jsonb_build_object('kind', 'scim_token_revoked', 'token_id', p_token_id));

  RETURN jsonb_build_object('ok', true);
END $function$;

CREATE OR REPLACE FUNCTION public.scim_tokens_list(p_tenant uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_rows jsonb;
BEGIN
  IF coalesce(public.can_admin_tenant_internal(p_tenant), false) IS NOT TRUE THEN
    RAISE EXCEPTION 'not authorized';
  END IF;
  -- token_hash is deliberately absent from this projection.
  SELECT coalesce(jsonb_agg(jsonb_build_object(
           'id', t.id, 'name', t.name, 'prefix', t.token_prefix,
           'allow_account_adoption', t.allow_account_adoption,
           'created_at', t.created_at, 'last_used_at', t.last_used_at,
           'revoked_at', t.revoked_at) ORDER BY t.created_at DESC), '[]'::jsonb)
    INTO v_rows FROM public.scim_tokens t WHERE t.tenant_id = p_tenant;
  RETURN jsonb_build_object('ok', true, 'tokens', v_rows);
END $function$;

CREATE OR REPLACE FUNCTION public.scim_user_delete(p_token text, p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_ctx jsonb; v_tenant uuid; v_token_id uuid; v_token_name text;
  v_link public.scim_user_links; v_auth_user uuid;
BEGIN
  v_ctx := public.scim_token_context(p_token);
  IF v_ctx IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'unauthorized'); END IF;
  v_tenant     := (v_ctx->>'tenant_id')::uuid;
  v_token_id   := (v_ctx->>'token_id')::uuid;
  v_token_name := v_ctx->>'name';

  SELECT * INTO v_link FROM public.scim_user_links
   WHERE id = p_id AND tenant_id = v_tenant AND deleted_at IS NULL FOR UPDATE;
  IF v_link.id IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'not_found'); END IF;

  IF EXISTS (SELECT 1 FROM public.profiles p
              WHERE p.id = v_link.profile_id AND p.role IN ('tenant_owner', 'tenant_admin'))
     AND NOT EXISTS (SELECT 1 FROM public.profiles p
                      WHERE p.tenant_id = v_tenant AND p.id <> v_link.profile_id
                        AND p.role IN ('tenant_owner', 'tenant_admin')
                        AND coalesce(p.is_active, true) = true)
  THEN
    RETURN jsonb_build_object('ok', false, 'error', 'last_admin',
      'detail', 'refusing to remove the only remaining administrator of this workspace');
  END IF;

  UPDATE public.scim_user_links
     SET active = false, deleted_at = now(), last_token_id = v_token_id, updated_at = now()
   WHERE id = v_link.id;

  UPDATE public.profiles
     SET is_active = false, updated_at = now()
   WHERE id = v_link.profile_id AND tenant_id = v_tenant
  RETURNING user_id INTO v_auth_user;

  PERFORM public.append_audit_event_internal(
    v_tenant, 'SCIM: ' || coalesce(v_token_name, 'provisioning'), 'system',
    format('Deprovisioned %s via SCIM — access revoked', v_link.user_name),
    'access_control',
    jsonb_build_object('kind', 'scim_user_deprovisioned', 'scim_id', v_link.id,
                       'profile_id', v_link.profile_id, 'token_id', v_token_id));

  -- auth_user_id is returned so the edge function can ban the account through
  -- the GoTrue admin API. It is scoped by everything above: it is the auth user
  -- of a profile in this token's tenant, and nothing else can be returned here.
  RETURN jsonb_build_object('ok', true, 'auth_user_id', v_auth_user);
END $function$;

CREATE OR REPLACE FUNCTION public.scim_user_get(p_token text, p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_ctx jsonb; v_tenant uuid; v_res jsonb;
BEGIN
  v_ctx := public.scim_token_context(p_token);
  IF v_ctx IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'unauthorized'); END IF;
  v_tenant := (v_ctx->>'tenant_id')::uuid;

  -- THE ATTACK THIS LINE ANSWERS: the caller supplies an id belonging to
  -- another tenant. tenant_id = v_tenant makes that indistinguishable from an
  -- id that does not exist — same not_found, no existence oracle.
  SELECT public.scim_user_resource_json(l.id) INTO v_res
    FROM public.scim_user_links l
   WHERE l.id = p_id AND l.tenant_id = v_tenant AND l.deleted_at IS NULL;

  IF v_res IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'not_found'); END IF;
  RETURN jsonb_build_object('ok', true, 'resource', v_res);
END $function$;

CREATE OR REPLACE FUNCTION public.scim_user_patch(p_token text, p_id uuid, p_changes jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_ctx jsonb; v_tenant uuid; v_token_id uuid; v_token_name text;
  v_link public.scim_user_links; v_active boolean; v_full text; v_uname text;
BEGIN
  v_ctx := public.scim_token_context(p_token);
  IF v_ctx IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'unauthorized'); END IF;
  v_tenant     := (v_ctx->>'tenant_id')::uuid;
  v_token_id   := (v_ctx->>'token_id')::uuid;
  v_token_name := v_ctx->>'name';

  SELECT * INTO v_link FROM public.scim_user_links
   WHERE id = p_id AND tenant_id = v_tenant AND deleted_at IS NULL FOR UPDATE;
  IF v_link.id IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'not_found'); END IF;

  -- jsonb_exists(), not the `?` operator: `?` is a bind placeholder to several
  -- client drivers and this SQL travels through more than one of them.
  v_active := CASE WHEN jsonb_exists(p_changes, 'active')
                   THEN coalesce((p_changes->>'active')::boolean, v_link.active)
                   ELSE v_link.active END;

  -- Refuse to strip the workspace's last admin. Migration 359 established this
  -- rule for the in-app path; an IdP that deprovisions the wrong person must
  -- not be able to route around it and leave a workspace nobody can administer.
  -- Okta surfaces this as a visible error, which is the outcome we want.
  IF v_active IS FALSE AND v_link.active IS TRUE THEN
    IF EXISTS (SELECT 1 FROM public.profiles p
                WHERE p.id = v_link.profile_id
                  AND p.role IN ('tenant_owner', 'tenant_admin'))
       AND NOT EXISTS (SELECT 1 FROM public.profiles p
                        WHERE p.tenant_id = v_tenant AND p.id <> v_link.profile_id
                          AND p.role IN ('tenant_owner', 'tenant_admin')
                          AND coalesce(p.is_active, true) = true)
    THEN
      RETURN jsonb_build_object('ok', false, 'error', 'last_admin',
        'detail', 'refusing to deactivate the only remaining administrator of this workspace');
    END IF;
  END IF;

  -- userName is stored, but the login email in auth.users is NOT changed. An
  -- IdP that renames a userName must not be able to repoint a live credential
  -- at an address its operator does not control. Documented deviation.
  v_uname := nullif(btrim(coalesce(p_changes->>'userName', '')), '');
  IF v_uname IS NOT NULL AND EXISTS (
       SELECT 1 FROM public.scim_user_links
        WHERE tenant_id = v_tenant AND lower(user_name) = lower(v_uname)
          AND id <> v_link.id) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'conflict',
                              'detail', 'a user with this userName already exists');
  END IF;

  UPDATE public.scim_user_links
     SET active      = v_active,
         user_name   = coalesce(v_uname, user_name),
         given_name  = coalesce(nullif(btrim(coalesce(p_changes->>'givenName','')), ''), given_name),
         family_name = coalesce(nullif(btrim(coalesce(p_changes->>'familyName','')), ''), family_name),
         external_id = coalesce(nullif(btrim(coalesce(p_changes->>'externalId','')), ''), external_id),
         last_token_id = v_token_id,
         updated_at  = now()
   WHERE id = v_link.id;

  v_full := nullif(btrim(coalesce(p_changes->>'displayName', '')), '');

  -- THE DEPROVISION. is_active = false makes auth_tenant_id() return NULL,
  -- which makes all 232 policies that call it deny — measured today, see the
  -- header. The `tenant_id = v_tenant` predicate is redundant given the link
  -- lookup above and the trigger invariant; it is here so this UPDATE is safe
  -- read in isolation, without reconstructing the argument.
  UPDATE public.profiles
     SET is_active  = v_active,
         full_name  = coalesce(v_full, full_name),
         updated_at = now()
   WHERE id = v_link.profile_id AND tenant_id = v_tenant;

  PERFORM public.append_audit_event_internal(
    v_tenant, 'SCIM: ' || coalesce(v_token_name, 'provisioning'), 'system',
    format('%s %s via SCIM',
           CASE WHEN v_active THEN 'Reactivated' ELSE 'Deactivated' END, v_link.user_name),
    'access_control',
    jsonb_build_object('kind', 'scim_user_patched', 'scim_id', v_link.id,
                       'profile_id', v_link.profile_id, 'token_id', v_token_id,
                       'active', v_active, 'changed', p_changes - 'password'));

  -- auth_user_id is returned so the edge function can ban/unban the account
  -- through the GoTrue admin API WITHOUT ever querying scim_user_links itself.
  -- That matters: the edge function runs as service_role, so a direct read
  -- there would be unconstrained by tenant and would be the one exception to
  -- "this function never reaches a row the token did not authorise". There is
  -- no exception. The value is v_link.user_id, already proven in-tenant above.
  RETURN jsonb_build_object('ok', true, 'auth_user_id', v_link.user_id,
                            'resource', public.scim_user_resource_json(v_link.id));
END $function$;

CREATE OR REPLACE FUNCTION public.scim_user_resource_json(p_link_id uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT jsonb_build_object(
    'schemas', jsonb_build_array('urn:ietf:params:scim:schemas:core:2.0:User'),
    'id', l.id::text,
    'externalId', l.external_id,
    'userName', l.user_name,
    'name', jsonb_strip_nulls(jsonb_build_object(
              'givenName', l.given_name, 'familyName', l.family_name,
              'formatted', p.full_name)),
    'displayName', p.full_name,
    'emails', jsonb_build_array(jsonb_build_object(
                'value', l.user_name, 'type', 'work', 'primary', true)),
    'active', l.active,
    'meta', jsonb_build_object(
      'resourceType', 'User',
      'created', to_char(l.created_at  AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
      'lastModified', to_char(l.updated_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
      -- ETag over the row's own mutable state. The edge function adds
      -- meta.location, which needs the request URL and is not knowable here.
      'version', 'W/"' || md5(l.id::text || l.updated_at::text || l.active::text) || '"'))
  FROM public.scim_user_links l
  JOIN public.profiles p ON p.id = l.profile_id
  WHERE l.id = p_link_id;
$function$;

CREATE OR REPLACE FUNCTION public.scim_user_upsert(p_token text, p_user_id uuid, p_user_name text, p_external_id text DEFAULT NULL::text, p_given_name text DEFAULT NULL::text, p_family_name text DEFAULT NULL::text, p_active boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_ctx jsonb; v_tenant uuid; v_adopt boolean; v_token_id uuid; v_token_name text;
  v_uname text; v_full text; v_meta_tenant text;
  v_profile public.profiles; v_link_id uuid; v_link_state text;
BEGIN
  v_ctx := public.scim_token_context(p_token);
  IF v_ctx IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'unauthorized'); END IF;
  v_tenant     := (v_ctx->>'tenant_id')::uuid;
  v_adopt      := coalesce((v_ctx->>'allow_account_adoption')::boolean, false);
  v_token_id   := (v_ctx->>'token_id')::uuid;
  v_token_name := v_ctx->>'name';

  v_uname := lower(btrim(coalesce(p_user_name, '')));
  IF v_uname = '' OR position('@' IN v_uname) < 2 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_username');
  END IF;
  v_full := nullif(btrim(concat_ws(' ', nullif(btrim(coalesce(p_given_name, '')), ''),
                                        nullif(btrim(coalesce(p_family_name, '')), ''))), '');

  SELECT (u.raw_app_meta_data->>'scim_tenant') INTO v_meta_tenant
    FROM auth.users u WHERE u.id = p_user_id;

  -- FOR UPDATE: two IdP pushes for the same person can land concurrently, and
  -- the window between "read tenant_id" and "write tenant_id" is exactly where
  -- a double-claim would happen.
  SELECT * INTO v_profile FROM public.profiles WHERE user_id = p_user_id FOR UPDATE;

  IF v_profile.id IS NOT NULL AND v_profile.tenant_id IS NOT NULL
     AND v_profile.tenant_id <> v_tenant THEN
    -- Unconditional. Re-checked here and not merely in scim_provision_begin.
    RETURN jsonb_build_object('ok', false, 'error', 'conflict',
      'detail', 'this email is already in use by an account outside this workspace');
  END IF;

  -- ⚠ PLATFORM STAFF ARE NOT PROVISIONABLE. EVER. NO FLAG.
  -- `layer` was referenced nowhere in this file except a comment and an INSERT
  -- column list — it was never CHECKED. Both platform_super_admin profiles have
  -- layer='platform' and tenant_id IS NULL, so they fell into the "unassigned
  -- account" branch below. The full path, with no exotic steps:
  --   a tenant admin ticks allow_account_adoption (a self-service checkbox)
  --   -> POST /Users with a platform admin's email
  --   -> mode 'link' -> tenant_id is set, layer stays 'platform', role preserved
  --   -> DELETE /Users/{id} sets is_active=false
  --   -> is_platform_admin() is layer='platform' AND is_active, so it now
  --      returns false, plus GoTrue gets a 100-year ban
  -- Two emails and one checkbox removes every platform administrator. The
  -- last-admin guard does not help: it counts only tenant_owner/tenant_admin.
  IF v_profile.id IS NOT NULL AND coalesce(v_profile.layer, 'tenant') <> 'tenant' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'conflict',
      'detail', 'this email belongs to a platform account and cannot be managed by workspace provisioning');
  END IF;

  IF v_profile.id IS NULL OR v_profile.tenant_id IS NULL THEN
    -- Claiming an unassigned account. Allowed only with service-role-written
    -- provenance, or with the token's explicit opt-in.
    --
    -- ⚠ coalesce is load-bearing, and this is the migration-369 shape again.
    -- v_meta_tenant is NULL for every organically-signed-up account, so
    -- `NULL = v_tenant::text OR false` evaluates to NULL, `NOT NULL` is NULL,
    -- and the IF never fires — the refusal was skipped for exactly the accounts
    -- it was written to protect. Verified on production:
    --   select (NOT (null::text = 'x' OR false)) is null  ->  true
    IF NOT (coalesce(v_meta_tenant, '') = v_tenant::text OR v_adopt) THEN
      RETURN jsonb_build_object('ok', false, 'error', 'conflict',
        'detail', 'an account with this email exists but is not a member of this workspace');
    END IF;
  END IF;

  IF v_profile.id IS NULL THEN
    -- An auth user with no profile row. handle_new_user() normally prevents
    -- this; if it ever happens, mint the same row that trigger would have — no
    -- more privilege, same 'agent' default. handle_new_user itself is untouched.
    INSERT INTO public.profiles (user_id, tenant_id, full_name, role, layer,
                                 is_active, department, invited_by)
    VALUES (p_user_id, v_tenant, v_full, 'agent', 'tenant',
            coalesce(p_active, true), '', 'SCIM: ' || coalesce(v_token_name, 'provisioning'))
    RETURNING * INTO v_profile;
  ELSE
    UPDATE public.profiles
       SET tenant_id  = v_tenant,
           full_name  = coalesce(v_full, full_name),
           -- Role is NEVER set from SCIM input, so an IdP push can neither grant
           -- nor strip tenant_admin.
           --
           -- ⚠ But "keep the existing role" is only safe for an EXISTING MEMBER.
           -- The comment here used to claim a first claim "still carries
           -- handle_new_user's 'agent'" — measured on production, that is false:
           -- there is a profile with layer='tenant', role='tenant_owner',
           -- tenant_id IS NULL, is_active=true. Adopting that row would have made
           -- the adopting workspace hand a stranger tenant_owner — able to mint
           -- further SCIM tokens and read everything.
           -- So: adopting an unassigned account starts at the floor; only a row
           -- that was ALREADY a member of this tenant keeps its role.
           role       = CASE WHEN profiles.tenant_id IS NULL THEN 'agent' ELSE profiles.role END,
           is_active  = coalesce(p_active, true),
           invited_by = coalesce(invited_by, 'SCIM: ' || coalesce(v_token_name, 'provisioning')),
           updated_at = now()
     WHERE id = v_profile.id
    RETURNING * INTO v_profile;
  END IF;

  -- userName collision with a DIFFERENT person in this tenant. Soft-deleted
  -- rows are INCLUDED here even though they are invisible over the API: the
  -- unique index on (tenant_id, lower(user_name)) covers them, so excluding
  -- them would turn a clean 409 into an unhandled unique-violation and a 500.
  IF EXISTS (SELECT 1 FROM public.scim_user_links
              WHERE tenant_id = v_tenant AND lower(user_name) = v_uname
                AND profile_id <> v_profile.id) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'conflict',
                              'detail', 'a user with this userName already exists');
  END IF;

  -- Three states, not a nullable boolean: no link, a live link, or a
  -- soft-deleted one. A `SELECT (deleted_at IS NOT NULL) INTO flag` would
  -- report "no link at all" as NULL and get coalesced into the wrong answer.
  SELECT CASE WHEN deleted_at IS NULL THEN 'live' ELSE 'deleted' END INTO v_link_state
    FROM public.scim_user_links WHERE profile_id = v_profile.id;
  v_link_state := coalesce(v_link_state, 'none');

  INSERT INTO public.scim_user_links (
      tenant_id, profile_id, user_id, user_name, external_id,
      given_name, family_name, active, created_by_token, last_token_id)
  VALUES (v_tenant, v_profile.id, p_user_id, btrim(p_user_name), nullif(btrim(coalesce(p_external_id,'')), ''),
          nullif(btrim(coalesce(p_given_name,'')), ''), nullif(btrim(coalesce(p_family_name,'')), ''),
          coalesce(p_active, true), v_token_id, v_token_id)
  ON CONFLICT (profile_id) DO UPDATE
     SET user_name   = excluded.user_name,
         external_id = coalesce(excluded.external_id, public.scim_user_links.external_id),
         given_name  = coalesce(excluded.given_name,  public.scim_user_links.given_name),
         family_name = coalesce(excluded.family_name, public.scim_user_links.family_name),
         active      = excluded.active,
         deleted_at  = NULL,            -- rehire: the record comes back to life
         last_token_id = excluded.last_token_id,
         updated_at  = now()
  RETURNING id INTO v_link_id;

  PERFORM public.append_audit_event_internal(
    v_tenant, 'SCIM: ' || coalesce(v_token_name, 'provisioning'), 'system',
    format('%s %s via SCIM',
           CASE v_link_state WHEN 'deleted' THEN 'Re-provisioned'
                             WHEN 'live'    THEN 'Updated'
                             ELSE 'Provisioned' END, v_uname),
    'access_control',
    jsonb_build_object('kind', 'scim_user_provisioned', 'scim_id', v_link_id,
                       'profile_id', v_profile.id, 'token_id', v_token_id,
                       'link_state_before', v_link_state, 'active', coalesce(p_active, true)));

  -- 'created' drives 201-vs-200 in the edge function. A revive is a 201 (the
  -- resource did not exist over the API a moment ago); an update to a live
  -- record is a 200.
  RETURN jsonb_build_object('ok', true, 'created', v_link_state <> 'live',
                            'resource', public.scim_user_resource_json(v_link_id));
END $function$;

CREATE OR REPLACE FUNCTION public.scim_users_list(p_token text, p_user_name text DEFAULT NULL::text, p_external_id text DEFAULT NULL::text, p_start_index integer DEFAULT 1, p_count integer DEFAULT 100)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_ctx jsonb; v_tenant uuid;
  v_start integer; v_count integer; v_total integer; v_rows jsonb;
BEGIN
  v_ctx := public.scim_token_context(p_token);
  IF v_ctx IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'unauthorized'); END IF;
  v_tenant := (v_ctx->>'tenant_id')::uuid;

  v_start := greatest(coalesce(p_start_index, 1), 1);          -- SCIM is 1-based
  v_count := least(greatest(coalesce(p_count, 100), 0), 200);  -- count=0 is legal

  SELECT count(*) INTO v_total
    FROM public.scim_user_links l
   WHERE l.tenant_id = v_tenant                                -- ← derived, never supplied
     AND l.deleted_at IS NULL
     AND (p_user_name   IS NULL OR lower(l.user_name) = lower(btrim(p_user_name)))
     AND (p_external_id IS NULL OR l.external_id = p_external_id);

  SELECT coalesce(jsonb_agg(r ORDER BY ord), '[]'::jsonb) INTO v_rows
    FROM (
      SELECT public.scim_user_resource_json(l.id) AS r,
             row_number() OVER (ORDER BY l.created_at, l.id) AS ord
        FROM public.scim_user_links l
       WHERE l.tenant_id = v_tenant
         AND l.deleted_at IS NULL
         AND (p_user_name   IS NULL OR lower(l.user_name) = lower(btrim(p_user_name)))
         AND (p_external_id IS NULL OR l.external_id = p_external_id)
       ORDER BY l.created_at, l.id
       OFFSET v_start - 1 LIMIT v_count
    ) s;

  RETURN jsonb_build_object('ok', true, 'totalResults', v_total,
                            'startIndex', v_start, 'itemsPerPage', jsonb_array_length(v_rows),
                            'resources', v_rows);
END $function$;

CREATE OR REPLACE FUNCTION public.score_frustration_internal(p_tenant_id uuid, p_text text)
 RETURNS integer
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_rule   record;
  v_text   text := lower(coalesce(p_text, ''));
  v_frag   text;
  v_hit    boolean;
  v_score  integer := 0;
begin
  for v_rule in
    select id, pattern from guardrail_rules
    where tenant_id = p_tenant_id and active and rule_type = 'frustration_signal'
  loop
    if v_rule.pattern is null then continue; end if;
    foreach v_frag in array string_to_array(v_rule.pattern, '|') loop
      v_frag := trim(both from lower(v_frag));
      if v_frag = '' then continue; end if;
      begin
        v_hit := v_text ~ v_frag;
      exception when others then
        v_hit := position(v_frag in v_text) > 0;
      end;
      if v_hit then
        v_score := v_score + 25;
        exit;
      end if;
    end loop;
  end loop;

  return least(100, v_score);
end;
$function$;

CREATE OR REPLACE FUNCTION public.search_knowledge(p_tenant_id uuid, p_query text, p_audience text DEFAULT NULL::text, p_limit integer DEFAULT 5)
 RETURNS TABLE(id uuid, title text, summary text, body text, audience text, category text, tags text[], rank real)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select ka.id, ka.title, ka.summary, ka.body, ka.audience, ka.category, ka.tags,
         ts_rank(ka.search_tsv, websearch_to_tsquery('english', p_query)) as rank
  from public.knowledge_articles ka
  where ka.tenant_id = p_tenant_id
    and (
      (p_tenant_id in (select tenant_id from public.profiles where user_id = auth.uid() and coalesce(is_active, true) = true))
      or (auth.uid() is null and coalesce(auth.role(), '') = 'service_role')
    )
    and ka.status = 'published'
    and (p_audience is null or ka.audience = p_audience or ka.audience = 'all')
    and ka.search_tsv @@ websearch_to_tsquery('english', p_query)
  order by rank desc
  limit greatest(p_limit, 1);
$function$;

CREATE OR REPLACE FUNCTION public.search_knowledge_docs(p_query text DEFAULT NULL::text, p_tags text[] DEFAULT NULL::text[], p_source text DEFAULT NULL::text, p_visibility text DEFAULT NULL::text, p_collection_id uuid DEFAULT NULL::uuid, p_current_only boolean DEFAULT true, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0, p_lifecycle text DEFAULT NULL::text, p_unfiled boolean DEFAULT false)
 RETURNS TABLE(id uuid, title text, preview text, tags text[], source text, visibility text, share_archetype_key text, authority integer, last_verified_at timestamp with time zone, is_current boolean, chunk_count integer, embedded_count integer, updated_at timestamp with time zone, citation_count integer, last_cited_at timestamp with time zone, lifecycle_status text, verification_state text, total_count bigint)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tenant uuid := public.auth_tenant_id();
  v_q text := nullif(btrim(coalesce(p_query, '')), '');
BEGIN
  IF v_tenant IS NULL THEN RETURN; END IF;
  RETURN QUERY
  WITH filtered AS (
    SELECT d.* FROM knowledge_docs d
     WHERE d.tenant_id = v_tenant
       AND (NOT p_current_only OR d.is_current)
       AND (p_source     IS NULL OR d.source = p_source)
       AND (p_visibility IS NULL OR d.visibility = p_visibility)
       AND (p_tags       IS NULL OR d.tags && p_tags)
       AND (p_lifecycle  IS NULL OR d.lifecycle_status = p_lifecycle)
       -- Documents filed nowhere. Asked for explicitly, because a NULL
       -- collection has always meant everywhere and there was no way to
       -- express the opposite.
       AND (NOT p_unfiled OR NOT EXISTS (
              SELECT 1 FROM knowledge_doc_collections dcx WHERE dcx.doc_id = d.id))
       AND (p_unfiled OR p_collection_id IS NULL OR EXISTS (
              -- Closure, not the direct junction: selecting a Space now finds
              -- documents filed anywhere beneath it, which is what clicking a
              -- folder means to a human.
              SELECT 1 FROM knowledge_doc_access_paths ap
               WHERE ap.doc_id = d.id AND ap.collection_id = p_collection_id))
       AND (v_q IS NULL OR d.search_tsv @@ websearch_to_tsquery('english', v_q))
  ), counted AS (SELECT count(*) AS n FROM filtered)
  SELECT f.id, f.title, left(coalesce(f.content, ''), 200) AS preview, f.tags, f.source, f.visibility,
         f.share_archetype_key, f.authority, f.last_verified_at, f.is_current,
         coalesce(f.chunk_count, 0), coalesce(f.embedded_count, 0), f.updated_at,
         coalesce(f.citation_count, 0), f.last_cited_at,
         f.lifecycle_status,
         public.knowledge_verification_state(f.*),
         (SELECT n FROM counted) AS total_count
    FROM filtered f
   ORDER BY
     CASE WHEN v_q IS NULL THEN 0 ELSE ts_rank(f.search_tsv, websearch_to_tsquery('english', v_q)) END DESC,
     f.updated_at DESC
   LIMIT greatest(1, least(200, coalesce(p_limit, 50)))
  OFFSET greatest(0, coalesce(p_offset, 0));
END $function$;

CREATE OR REPLACE FUNCTION public.seed_approval_baseline(p_tenant_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_existing  int;
  v_has_owner boolean;
  v_seeded    int;
begin
  if p_tenant_id is null then return 0; end if;

  -- Idempotent, and deliberately blunt: if a workspace has declared ANY
  -- authority we leave it entirely alone. Re-running must never duplicate a
  -- grant, and must never resurrect one somebody deactivated on purpose.
  select count(*) into v_existing from approval_authority where tenant_id = p_tenant_id;
  if v_existing > 0 then return 0; end if;

  select exists (
    select 1 from profiles
     where tenant_id = p_tenant_id and role = 'tenant_owner' and is_active
  ) into v_has_owner;

  -- 1. The escape hatch by RANK — survives the person leaving. Seeded even
  --    where no owner exists yet, so a promotion needs no follow-up config.
  insert into approval_authority
    (tenant_id, role, category, max_amount_cents, second_approver_above_cents, note)
  values
    (p_tenant_id, 'tenant_owner', null, null, null,
     'Owner — final authority, any work, any amount. This row is what stops a '
     'category nobody wrote a rule for from freezing the queue. Do not delete it.');

  -- 2. The same authority pinned to each owner PERSONALLY, so changing a role
  --    cannot lock the workspace out.
  insert into approval_authority
    (tenant_id, user_id, category, max_amount_cents, second_approver_above_cents, note)
  select p_tenant_id, p.user_id, null, null, null,
         'The owner personally — the same authority pinned to the person rather '
         'than the role, so changing a role cannot lock the workspace out.'
  from profiles p
  where p.tenant_id = p_tenant_id and p.role = 'tenant_owner' and p.is_active;

  -- 3. Admin — DERIVED. See the header: a ceiling is only a control if
  --    somebody exists above it.
  if v_has_owner then
    insert into approval_authority
      (tenant_id, role, category, max_amount_cents, second_approver_above_cents, note)
    values
      (p_tenant_id, 'tenant_admin', null, 25000000, 10000000,
       'Admin — any kind of work up to $250,000. Over $100,000 a second person '
       'must also approve; the owner can always be that second person.');
  else
    insert into approval_authority
      (tenant_id, role, category, max_amount_cents, second_approver_above_cents, note)
    values
      (p_tenant_id, 'tenant_admin', null, null, null,
       'Admin — final authority in this workspace, because it has no owner. '
       'Capping the most senior person, with nobody above them to escalate to, '
       'would freeze work rather than govern it. Narrow this once an owner exists.');
  end if;

  -- 4. Manager — routine amounts only.
  insert into approval_authority
    (tenant_id, role, category, max_amount_cents, second_approver_above_cents, note)
  values
    (p_tenant_id, 'tenant_manager', null, 2500000, null,
     'Manager — any kind of work up to $25,000, so routine items only.');

  -- 5. Everyone else — the support queue, and nothing carrying money. A zero
  --    ceiling is not a formality: with an amount attached the check refuses,
  --    so priced work rises to a manager instead of being waved through.
  insert into approval_authority
    (tenant_id, role, category, max_amount_cents, second_approver_above_cents, note)
  select p_tenant_id, 'tenant_user', c, 0, null,
         'Support staff — may clear ' || c || ', but nothing carrying money; '
         'anything with an amount goes to a manager.'
  from unnest(array['helpdesk','escalation','inquiry_review','checklist','knowledge_revision']) as c;

  select count(*) into v_seeded from approval_authority where tenant_id = p_tenant_id;
  return v_seeded;
end;
$function$;

CREATE OR REPLACE FUNCTION public.seed_de_trust_policy(p_de_id uuid, p_capability_key text, p_display_name text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tenant uuid := auth_tenant_id();
  v_cand record;
  v_id uuid;
  v_row trust_policies;
  v_new boolean;
BEGIN
  IF v_tenant IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  IF NOT (is_platform_admin()
          OR auth_has_tenant_role(ARRAY['tenant_owner', 'tenant_admin', 'tenant_manager'])) THEN
    RAISE EXCEPTION 'insufficient_permission: seeding a trust policy requires a manager';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM digital_employees d
                  WHERE d.id = p_de_id AND d.tenant_id = v_tenant) THEN
    RAISE EXCEPTION 'that digital employee does not belong to this workspace';
  END IF;
  -- Second axis (docs/29): the role tier alone is not enough — the caller
  -- must also sit on this employee's reporting line. Identical to
  -- set_trust_ladder's per-employee branch.
  IF NOT can_access_de(p_de_id) THEN
    RAISE EXCEPTION 'insufficient_permission: you are not assigned to this digital employee';
  END IF;

  SELECT * INTO v_cand
    FROM de_trust_surface_candidates(v_tenant, p_de_id) c
   WHERE c.capability_key = p_capability_key
   LIMIT 1;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'capability "%" is not on this employee''s trust surface', p_capability_key;
  END IF;
  IF NOT v_cand.dialable THEN
    RAISE EXCEPTION 'capability "%" always requires human approval — it cannot carry a trust policy', p_capability_key;
  END IF;

  INSERT INTO trust_policies (tenant_id, de_id, action_category, display_name)
  VALUES (v_tenant, p_de_id, p_capability_key, nullif(trim(coalesce(p_display_name, '')), ''))
  ON CONFLICT (tenant_id, action_category, coalesce(source_category, ''), coalesce(de_id::text, ''))
  DO UPDATE SET
    -- Idempotent: an existing policy keeps everything; a missing display name
    -- may be filled in, never overwritten.
    display_name = coalesce(trust_policies.display_name, excluded.display_name),
    updated_at   = now()
  -- Scalar targets only (the set_de_assignment idiom): RETURNING a composite
  -- plus a scalar into mixed targets is not a supported plpgsql shape.
  RETURNING id, (xmax = 0) INTO v_id, v_new;
  SELECT * INTO v_row FROM trust_policies WHERE id = v_id;

  -- Record only genuine creation (idempotent re-calls stay silent). AFTER the
  -- write: an event claiming a change that then failed is worse than no event.
  IF v_new THEN
    PERFORM append_audit_event(
      v_tenant,
      coalesce((SELECT full_name FROM profiles WHERE user_id = auth.uid()), 'A manager'),
      'human',
      format('Created a level-0 trust policy for "%s" on a digital employee', p_capability_key),
      'config_change',
      jsonb_build_object('kind', 'trust_policy_seeded', 'policy_id', v_row.id,
                         'de_id', p_de_id, 'capability_key', p_capability_key,
                         'seeded_by', auth.uid()));
  END IF;

  RETURN to_jsonb(v_row);
END $function$;

CREATE OR REPLACE FUNCTION public.seed_default_grants(p_subject_kind text, p_subject_id uuid, p_domain text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_tenant uuid; v_label text; v_pairs text[][]; v_pair text[]; v_seeded integer := 0;
begin
  if p_subject_kind in ('de', 'specialist') then
    select tenant_id, name into v_tenant, v_label from digital_employees where id = p_subject_id;
  else
    return jsonb_build_object('ok', false, 'error', 'bad_subject_kind');
  end if;
  if v_tenant is null then return jsonb_build_object('ok', false, 'error', 'subject_not_found'); end if;

  v_pairs := case p_domain
    when 'support'   then array[['helpdesk','read'], ['knowledge_base','read'], ['product_system','read']]
    when 'technical' then array[['helpdesk','read'], ['knowledge_base','read'], ['product_system','read'], ['crm','read']]
    when 'sales'     then array[['crm','read'], ['knowledge_base','read']]
    when 'finance'   then array[['erp_financials','read'], ['billing','read'], ['crm','search']]
    else null end;
  if v_pairs is null then return jsonb_build_object('ok', false, 'error', 'unknown_domain', 'detail', 'domain must be one of: support, technical, sales, finance'); end if;

  foreach v_pair slice 1 in array v_pairs loop
    insert into data_access_grants (tenant_id, subject_kind, subject_id, resource_kind, resource_category, permission, granted_by, note)
    values (v_tenant, p_subject_kind, p_subject_id, 'category', v_pair[1], v_pair[2], null, 'seeded default (' || p_domain || ') — editable like any grant')
    on conflict (tenant_id, subject_kind, subject_id, resource_kind, coalesce(resource_id::text, resource_category)) do nothing;
    if found then v_seeded := v_seeded + 1; end if;
  end loop;

  begin
  perform append_audit_event(v_tenant, 'DreamTeam', 'system',
    'Default data-access grants seeded for ' || coalesce(v_label, 'subject') || ' (' || p_domain || ' domain): ' || v_seeded || ' category grant(s). No financial, billing or payroll access is ever granted by default.',
    'access_control', jsonb_build_object('kind', 'access_grant_changed', 'seeded', v_seeded, 'subject_kind', p_subject_kind, 'subject_id', p_subject_id, 'subject_label', v_label, 'domain', p_domain));
  exception when others then null; end;
  return jsonb_build_object('ok', true, 'seeded', v_seeded, 'domain', p_domain);
end; $function$;

CREATE OR REPLACE FUNCTION public.seed_default_learning_policy()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  insert into de_learning_policies (tenant_id, category, enabled)
  values (new.id, null, true)
  on conflict do nothing;
  return new;
end; $function$;

CREATE OR REPLACE FUNCTION public.seed_support_triage_baseline(p_tenant_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_seeded integer := 0;
begin
  if p_tenant_id is null then return 0; end if;
  if not exists (select 1 from tenants where id = p_tenant_id) then return 0; end if;

  insert into support_triage_rules
    (tenant_id, rule_order, name, match_pattern, set_category, set_priority, set_severity, active)
  select p_tenant_id, r.rule_order, r.name, r.match_pattern, r.set_category, r.set_priority, r.set_severity, true
  from (values
    (10,   'Safety',          'injury|someone is hurt|unsafe|not safe|fire|smoke|gas leak|hazard|electric shock|danger',                                                        'safety',          'urgent', 'sev1'),
    (20,   'Security',        'data breach|breach of|hacked|unauthorized access|security incident|leaked|phishing|malware|ransomware|compromised account',                       'security',        'urgent', 'sev1'),
    (30,   'Legal/Regulatory','lawsuit|legal action|threaten to sue|gdpr|hipaa|regulator|compliance violation|subpoena|data protection',                                          'legal',           'high',   'sev2'),
    (40,   'Outage',          'outage|is down|system down|everything is broken|all users affected|cannot access at all|completely broken|nothing works|not working at all|major disruption', 'outage', 'high', 'sev2'),
    (50,   'Data loss',       'data loss|lost my data|deleted everything|missing records|records are gone|corrupted data',                                                        'data',            'high',   'sev2'),
    (60,   'Billing',         'invoice|refund|overcharged|billing|payment failed|charged twice|double charged|credit note|wrong amount',                                          'billing',         'normal', 'sev3'),
    (70,   'Access',          'locked out|reset password|cannot log in|unable to log in|access denied|unlock my account|forgot password|mfa|two factor',                          'access',          'normal', 'sev3'),
    (80,   'Complaint',       'complaint|unacceptable|terrible service|worst|extremely disappointed|want to escalate|speak to a manager|this is ridiculous',                      'complaint',       'high',   'sev3'),
    (90,   'Feature request', 'feature request|would be great if|can you add|please add|it would be nice|suggestion for',                                                         'feature_request', 'low',    'sev4'),
    (100,  'How-to',          'how do i|how to|how can i|where do i|where is|is it possible|walk me through|step by step|tutorial|guide',                                         'how_to',          'low',    'sev4'),
    -- The catch-all. Its match_pattern is NULL by design: classify_support_text
    -- treats a null pattern as "always matches", and rule_order 9999 puts it
    -- last. Without this row the classifier reaches its hardcoded 'general'
    -- fallback instead — the same answer, but with no rule anywhere saying so,
    -- which is precisely the invisible state this migration exists to remove.
    (9999, 'Default',         null,                                                                                                                                              'general',         'normal', 'sev3')
  ) as r(rule_order, name, match_pattern, set_category, set_priority, set_severity)
  where not exists (
    select 1 from support_triage_rules s
     where s.tenant_id = p_tenant_id and s.name = r.name
  );
  get diagnostics v_seeded = row_count;
  return v_seeded;
end;
$function$;

CREATE OR REPLACE FUNCTION public.send_human_reply(p_conversation_id uuid, p_content text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_tenant uuid; v_id uuid; v_de uuid;
begin
  if coalesce(trim(p_content), '') = '' then raise exception 'empty_message'; end if;
  v_tenant := _assert_conv_member(p_conversation_id);
  -- DE scoping (mig 385/406). _assert_conv_member above proved WORKSPACE
  -- membership; this proves responsibility for the EMPLOYEE. Two axes,
  -- both required. Null-tolerant to match the mig-386 policy.
  select de_id into v_de from de_conversations where id = p_conversation_id;
  if v_de is not null and not public.can_access_de(v_de) then
    raise exception 'not_responsible_for_de: this employee is not in your reporting line';
  end if;

  insert into de_messages (tenant_id, conversation_id, role, content, confidence, escalated, delivery)
  values (v_tenant, p_conversation_id, 'assistant', p_content, 100, false, 'sent')
  returning id into v_id;
  update de_conversations set owner_user_id = coalesce(owner_user_id, auth.uid()), status = 'human_owned', last_message_at = now()
  where id = p_conversation_id;
  return v_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.set_access_grant(p_subject_kind text, p_subject_id uuid, p_resource_kind text, p_resource_id uuid, p_resource_category text, p_permission text, p_note text DEFAULT ''::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_tenant uuid; v_user uuid := auth.uid(); v_role text; v_is_active boolean; v_before text; v_grant_id uuid; v_subject_label text; v_resource_label text;
begin
  if v_user is not null then
    select tenant_id, role, coalesce(is_active, true) into v_tenant, v_role, v_is_active from profiles where user_id = v_user;
    if v_tenant is null then return jsonb_build_object('ok', false, 'error', 'no_tenant'); end if;
    if not v_is_active then return jsonb_build_object('ok', false, 'error', 'admin_role_required', 'detail', 'Only workspace owners/admins can change data access rules.'); end if;
    if v_role not in ('tenant_owner', 'tenant_admin') then return jsonb_build_object('ok', false, 'error', 'admin_role_required', 'detail', 'Only workspace owners/admins can change data access rules.'); end if;
  elsif coalesce(auth.role(), '') <> 'service_role' then
    return jsonb_build_object('ok', false, 'error', 'admin_role_required', 'detail', 'Only workspace owners/admins can change data access rules.');
  else
    select tenant_id into v_tenant from digital_employees where id = p_subject_id;
    if v_tenant is null then return jsonb_build_object('ok', false, 'error', 'subject_not_found'); end if;
  end if;

  if p_subject_kind in ('de', 'specialist') then
    select name into v_subject_label from digital_employees where id = p_subject_id and tenant_id = v_tenant;
  else
    return jsonb_build_object('ok', false, 'error', 'bad_subject_kind');
  end if;
  if v_subject_label is null then return jsonb_build_object('ok', false, 'error', 'subject_not_in_tenant'); end if;

  if p_resource_kind = 'connector' then
    select display_name into v_resource_label from connectors where id = p_resource_id and tenant_id = v_tenant;
    if v_resource_label is null then return jsonb_build_object('ok', false, 'error', 'connector_not_in_tenant'); end if;
  elsif p_resource_kind = 'category' then
    v_resource_label := 'all ' || p_resource_category || ' systems';
  else
    return jsonb_build_object('ok', false, 'error', 'bad_resource_kind');
  end if;

  if access_permission_level(p_permission) = 0 then return jsonb_build_object('ok', false, 'error', 'bad_permission'); end if;

  select permission into v_before from data_access_grants
   where tenant_id = v_tenant and subject_kind = p_subject_kind and subject_id = p_subject_id and resource_kind = p_resource_kind
     and coalesce(resource_id::text, resource_category) = coalesce(p_resource_id::text, p_resource_category);

  insert into data_access_grants (tenant_id, subject_kind, subject_id, resource_kind, resource_id, resource_category, permission, granted_by, note)
  values (v_tenant, p_subject_kind, p_subject_id, p_resource_kind,
     case when p_resource_kind = 'connector' then p_resource_id else null end,
     case when p_resource_kind = 'category' then p_resource_category else null end,
     p_permission, v_user, coalesce(p_note, ''))
  on conflict (tenant_id, subject_kind, subject_id, resource_kind, coalesce(resource_id::text, resource_category))
  do update set permission = excluded.permission, granted_by = excluded.granted_by, note = excluded.note, updated_at = now()
  returning id into v_grant_id;

  perform append_audit_event(v_tenant,
    coalesce((select full_name from profiles where user_id = v_user), 'service'),
    case when v_user is null then 'system' else 'human' end,
    'Data access grant changed — ' || v_subject_label || ' on ' || v_resource_label || ': ' || coalesce(v_before, 'none') || ' → ' || p_permission ||
      case when coalesce(p_note, '') <> '' then ' (' || p_note || ')' else '' end,
    'access_control', jsonb_build_object('kind', 'access_grant_changed', 'grant_id', v_grant_id, 'subject_kind', p_subject_kind, 'subject_id', p_subject_id, 'subject_label', v_subject_label,
      'resource_kind', p_resource_kind, 'resource_id', p_resource_id, 'resource_category', p_resource_category, 'resource_label', v_resource_label, 'before', v_before, 'after', p_permission));
  return jsonb_build_object('ok', true, 'grant_id', v_grant_id, 'before', v_before, 'after', p_permission);
end; $function$;

CREATE OR REPLACE FUNCTION public.set_account_contact(p_account_id uuid, p_first_name text, p_last_name text, p_email text, p_title text DEFAULT NULL::text, p_phone text DEFAULT NULL::text, p_mobile text DEFAULT NULL::text, p_is_primary boolean DEFAULT false, p_contact_id uuid DEFAULT NULL::uuid, p_role text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tenant uuid := auth_tenant_id();
  v_email  text := nullif(btrim(lower(p_email)), '');
  v_role   text := nullif(btrim(lower(p_role)), '');
  v_id     uuid;
begin
  if v_tenant is null then raise exception 'not_authenticated'; end if;
  if not auth_has_tenant_role(array['tenant_owner','tenant_admin','tenant_manager']) then
    raise exception 'not_allowed: only an owner, admin or manager may record a customer contact';
  end if;
  if not exists (select 1 from customer_accounts where id = p_account_id and tenant_id = v_tenant) then
    raise exception 'that account is not in this workspace';
  end if;
  if coalesce(btrim(p_first_name),'') = '' and coalesce(btrim(p_last_name),'') = '' then
    raise exception 'a contact needs at least a name';
  end if;
  if v_email is null then
    raise exception 'a contact needs an email address — it is how the customer is recognised';
  end if;

  -- Refuse an unknown role by NAME rather than letting the CHECK reject the row
  -- with a constraint error nobody can read. The vocabulary is the CHECK's, read
  -- from it rather than duplicated here, so the two can never drift.
  if v_role is not null and v_role not in
     ('decision_maker','economic_buyer','billing','technical','exec_sponsor',
      'day_to_day','procurement','legal','other') then
    raise exception 'unknown contact role "%": use one of decision_maker, economic_buyer, billing, technical, exec_sponsor, day_to_day, procurement, legal, other', p_role;
  end if;

  if coalesce(p_is_primary, false) then
    update customer_account_contacts
       set is_primary = false, updated_at = now()
     where tenant_id = v_tenant and account_id = p_account_id and is_primary
       and (p_contact_id is null or id <> p_contact_id);
  end if;

  if p_contact_id is not null then
    update customer_account_contacts set
      first_name = nullif(btrim(p_first_name),''), last_name = nullif(btrim(p_last_name),''),
      email = v_email, end_user_ref = v_email, title = nullif(btrim(p_title),''),
      phone = nullif(btrim(p_phone),''), mobile = nullif(btrim(p_mobile),''),
      is_primary = coalesce(p_is_primary, false),
      -- NULL means "leave it alone" on an edit. Blanking a role that someone
      -- deliberately set, just because this form did not send one, would lose
      -- information silently.
      role = coalesce(v_role, role),
      updated_at = now()
    where id = p_contact_id and tenant_id = v_tenant
    returning id into v_id;
    if v_id is null then raise exception 'no such contact in this workspace'; end if;
  else
    insert into customer_account_contacts
      (tenant_id, account_id, end_user_ref, first_name, last_name, email, title, phone, mobile, is_primary, role)
    values (v_tenant, p_account_id, v_email,
            nullif(btrim(p_first_name),''), nullif(btrim(p_last_name),''),
            v_email, nullif(btrim(p_title),''),
            nullif(btrim(p_phone),''), nullif(btrim(p_mobile),''),
            coalesce(p_is_primary, false), v_role)
    returning id into v_id;
  end if;

  return jsonb_build_object('ok', true, 'contact_id', v_id);
end;
$function$;

CREATE OR REPLACE FUNCTION public.set_authority_rule(p_actor_kind text, p_dimension text, p_comparator text, p_threshold numeric, p_outcome text, p_category text DEFAULT NULL::text, p_actor_id uuid DEFAULT NULL::uuid, p_actor_role text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_tenant uuid := auth_tenant_id();
  v_id     uuid;
begin
  if v_tenant is null then raise exception 'not_authenticated'; end if;
  if not auth_has_tenant_role(array['tenant_owner','tenant_admin']) then
    raise exception 'insufficient_role';
  end if;

  -- The shape CHECK in 770 would catch these, but its message names a
  -- constraint. These name the mistake.
  if p_actor_kind = 'role' and coalesce(btrim(p_actor_role), '') = '' then
    raise exception 'actor_role_required: a rule scoped to a role must name the role';
  end if;
  if p_actor_kind in ('user','org_unit','de') and p_actor_id is null then
    raise exception 'actor_id_required: a rule scoped to % must name which one', p_actor_kind;
  end if;

  -- ⛔ AN ACTOR ID SUPPLIED BY A CALLER IS AN ASSERTION, NOT AUTHORISATION.
  -- Without these, an owner could scope a rule onto another workspace's
  -- employee or org unit — the tenant-id-param trap, one level down.
  if p_actor_kind = 'user' and not exists (
       select 1 from profiles where user_id = p_actor_id and tenant_id = v_tenant) then
    raise exception 'actor_not_in_workspace: no profile for that user here';
  end if;
  if p_actor_kind = 'de' and not exists (
       select 1 from digital_employees where id = p_actor_id and tenant_id = v_tenant) then
    raise exception 'actor_not_in_workspace: no digital employee with that id here';
  end if;
  if p_actor_kind = 'org_unit' and not exists (
       select 1 from org_units where id = p_actor_id and tenant_id = v_tenant) then
    raise exception 'actor_not_in_workspace: no org unit with that id here';
  end if;

  insert into authority_rules
    (tenant_id, actor_kind, actor_id, actor_role, category,
     dimension, comparator, threshold, outcome, created_by)
  values
    (v_tenant, p_actor_kind,
     case when p_actor_kind in ('user','org_unit','de') then p_actor_id end,
     case when p_actor_kind = 'role' then btrim(p_actor_role) end,
     nullif(btrim(coalesce(p_category, '')), ''),
     p_dimension, p_comparator, p_threshold, p_outcome, auth.uid())
  returning id into v_id;

  return v_id;
end
$function$;

CREATE OR REPLACE FUNCTION public.set_connector_ingest_config(p_connector_id uuid, p_config jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_tenant uuid;
begin
  select tenant_id into v_tenant from connectors where id = p_connector_id;
  if v_tenant is null or v_tenant <> auth_tenant_id()
     or not auth_has_tenant_role(array['tenant_owner','tenant_admin', 'tenant_manager']) then
    raise exception 'only workspace owners/admins can change a connector''s ingest settings';
  end if;
  update connectors
     set config = coalesce(config, '{}'::jsonb) || jsonb_build_object('ingest', coalesce(p_config, '{}'::jsonb))
   where id = p_connector_id;
end $function$;

CREATE OR REPLACE FUNCTION public.set_connector_schedule(p_connector_id uuid, p_enabled boolean, p_interval_mins integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tenant uuid;
BEGIN
  SELECT tenant_id INTO v_tenant FROM connectors WHERE id = p_connector_id;
  IF v_tenant IS NULL OR v_tenant IS DISTINCT FROM public.auth_tenant_id()
     OR NOT public.auth_has_tenant_role(array['tenant_owner','tenant_admin', 'tenant_manager', 'knowledge_manager']) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_permitted');
  END IF;
  UPDATE connectors
     SET scheduled_sync_enabled = coalesce(p_enabled, false),
         sync_interval_mins     = greatest(60, coalesce(p_interval_mins, 1440))
   WHERE id = p_connector_id;
  RETURN jsonb_build_object('ok', true);
END $function$;

CREATE OR REPLACE FUNCTION public.set_connector_secret(p_connector_id uuid, p_secret text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tenant   uuid;
  v_existing uuid;
  v_name     text := 'connector:' || p_connector_id::text;
begin
  select tenant_id into v_tenant from connectors where id = p_connector_id;
  if v_tenant is null then
    raise exception 'connector not found';
  end if;

  -- Unchanged authorization: service role, or an owner/admin/manager of the
  -- workspace that owns the connector.
  if coalesce(auth.role(), '') <> 'service_role'
     and not (v_tenant = auth_tenant_id() and auth_has_tenant_role(array['tenant_owner', 'tenant_admin', 'tenant_manager']))
  then
    raise exception 'only workspace owners/admins can set a connector''s credential';
  end if;

  -- Prefer the reference already on the row; fall back to finding the vault
  -- entry by name, so a re-connect after a partial write reuses it rather than
  -- colliding on vault.secrets' unique name.
  select secret_id into v_existing from connector_secrets where connector_id = p_connector_id;
  if v_existing is null then
    select id into v_existing from vault.secrets where name = v_name;
  end if;

  if v_existing is not null then
    perform vault.update_secret(v_existing, p_secret);
    update connector_secrets
       set secret_id = v_existing, secret = null, updated_at = now()
     where connector_id = p_connector_id;
    if not found then
      insert into connector_secrets (connector_id, secret_id, secret)
      values (p_connector_id, v_existing, null);
    end if;
  else
    insert into connector_secrets (connector_id, secret_id, secret)
    values (p_connector_id, vault.create_secret(p_secret, v_name, 'Connector credential'), null)
    on conflict (connector_id) do update
      set secret_id = excluded.secret_id, secret = null, updated_at = now();
  end if;
end $function$;

CREATE OR REPLACE FUNCTION public.set_connector_secret_sysadmin(p_connector_id uuid, p_secret text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'vault'
AS $function$
declare v_existing uuid;
begin
  select secret_id into v_existing from connector_secrets where connector_id = p_connector_id;
  if v_existing is null then
    insert into connector_secrets (connector_id, secret_id, updated_at)
      values (p_connector_id, vault.create_secret(p_secret, 'connector_secret:' || p_connector_id, 'OAuth tokens via oauth-callback'), now());
  else
    perform vault.update_secret(v_existing, p_secret);
    update connector_secrets set updated_at = now() where connector_id = p_connector_id;
  end if;
end $function$;

CREATE OR REPLACE FUNCTION public.set_conversation_fact(p_tenant_id uuid, p_conversation_id uuid, p_fact_key text, p_fact_value jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_id uuid;
begin
  if not is_feature_enabled_internal(p_tenant_id, 'de_memory') then
    return null;
  end if;

  insert into conversation_facts (tenant_id, conversation_id, fact_key, fact_value)
  values (p_tenant_id, p_conversation_id, p_fact_key, p_fact_value)
  on conflict (conversation_id, fact_key) do update set
    fact_value = excluded.fact_value,
    updated_at = now()
  returning id into v_id;
  return v_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.set_de_assignment(p_de_id uuid, p_user_id uuid, p_relation text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tenant uuid := auth_tenant_id(); v_id uuid; v_new_row boolean;
BEGIN
  IF v_tenant IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  IF NOT auth_has_tenant_role(ARRAY['tenant_owner', 'tenant_admin', 'tenant_manager']) THEN
    RAISE EXCEPTION 'insufficient_permission: assigning responsibility requires manager';
  END IF;
  IF p_relation NOT IN ('primary', 'manager', 'executive') THEN
    RAISE EXCEPTION 'relation must be primary, manager or executive';
  END IF;

  -- Both sides must belong to the caller's workspace. Without these two checks
  -- a manager could name a person from another tenant, or attach themselves to
  -- a DE they cannot see — the cross-tenant shape that has to be closed at the
  -- point of write, not left to the reader.
  IF NOT EXISTS (SELECT 1 FROM digital_employees d WHERE d.id = p_de_id AND d.tenant_id = v_tenant) THEN
    RAISE EXCEPTION 'that digital employee does not belong to this workspace';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM profiles p WHERE p.user_id = p_user_id AND p.tenant_id = v_tenant) THEN
    RAISE EXCEPTION 'that person does not belong to this workspace';
  END IF;

  INSERT INTO de_assignments (tenant_id, de_id, user_id, relation, assigned_by)
  VALUES (v_tenant, p_de_id, p_user_id, p_relation, auth.uid())
  ON CONFLICT (de_id, user_id, relation) DO UPDATE SET assigned_by = excluded.assigned_by
  RETURNING id, (xmax = 0) INTO v_id, v_new_row;

  -- Governance record (mig 429). AFTER the write: an event claiming a
  -- change that then failed is worse than no event. category is
  -- access_control and actor_type human because the audit_events CHECK
  -- constraints allow no others — see this migration's header.
  PERFORM append_audit_event(
    v_tenant,
    coalesce((SELECT full_name FROM profiles WHERE user_id = auth.uid()), 'A manager'),
    'human',
    format('%s %s as %s for a digital employee',
           CASE WHEN v_new_row THEN 'Assigned' ELSE 'Re-confirmed' END,
           coalesce((SELECT full_name FROM profiles WHERE user_id = p_user_id), 'a teammate'),
           p_relation),
    'access_control',
    jsonb_build_object('kind', 'de_assignment_set', 'de_id', p_de_id,
                       'user_id', p_user_id, 'relation', p_relation,
                       'assignment_id', v_id, 'was_new', v_new_row,
                       'assigned_by', auth.uid()));

  RETURN v_id;
END $function$;

CREATE OR REPLACE FUNCTION public.set_de_config(p_tenant_id uuid, p_entity_kind text, p_entity_id uuid, p_config jsonb)
 RETURNS TABLE(config_id uuid, tenant_id uuid, entity_kind text, entity_id uuid, schema_id uuid, data jsonb, created_at timestamp with time zone, updated_at timestamp with time zone, updated_by uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_config_id UUID;
BEGIN
  PERFORM public._assert_caller_tenant(p_tenant_id);
  INSERT INTO de_config (config_id, tenant_id, entity_kind, entity_id, data, updated_by)
  VALUES (gen_random_uuid(), p_tenant_id, p_entity_kind, p_entity_id, p_config, auth.uid())
  ON CONFLICT ON CONSTRAINT de_config_entity_uniq
  DO UPDATE SET data = p_config, updated_at = NOW(), updated_by = auth.uid()
  RETURNING de_config.config_id INTO v_config_id;
  RETURN QUERY SELECT * FROM de_config dc WHERE dc.config_id = v_config_id;
END$function$;

CREATE OR REPLACE FUNCTION public.set_de_custom_escalation_rules(p_de_id uuid, p_rules jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tenant uuid := auth_tenant_id();
BEGIN
  IF v_tenant IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  IF NOT auth_has_tenant_role(ARRAY['tenant_owner','tenant_admin']) THEN RAISE EXCEPTION 'insufficient_role'; END IF;
  IF NOT EXISTS (SELECT 1 FROM digital_employees WHERE id = p_de_id AND tenant_id = v_tenant) THEN
    RAISE EXCEPTION 'de_not_found';
  END IF;
  IF jsonb_typeof(p_rules) <> 'array' THEN RAISE EXCEPTION 'rules_must_be_an_array'; END IF;

  INSERT INTO de_escalation_rules (tenant_id, de_id, custom_rules, updated_by, updated_at)
  VALUES (v_tenant, p_de_id, p_rules, auth.uid(), now())
  ON CONFLICT (de_id) DO UPDATE
    SET custom_rules = excluded.custom_rules, updated_by = excluded.updated_by, updated_at = now();

  PERFORM append_audit_event(
    v_tenant, 'Workspace', 'human', 'Escalation rules updated', 'config_change',
    jsonb_build_object('de_id', p_de_id, 'rule_count', jsonb_array_length(p_rules))
  );
  RETURN jsonb_build_object('ok', true, 'rule_count', jsonb_array_length(p_rules));
END$function$;

CREATE OR REPLACE FUNCTION public.set_de_escalation_rules(p_de_id uuid DEFAULT NULL::uuid, p_frustration_threshold integer DEFAULT NULL::integer, p_topics text[] DEFAULT NULL::text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tenant uuid;
  v_de_name text := 'workspace default';
  v_topics text[] := coalesce(p_topics, '{}'::text[]);
begin
  if p_frustration_threshold is not null and (p_frustration_threshold < 0 or p_frustration_threshold > 100) then
    raise exception 'frustration threshold must be between 0 and 100';
  end if;
  v_tenant := auth_tenant_id();
  if v_tenant is null then raise exception 'not a member of any tenant'; end if;
  if not auth_has_tenant_role(array['tenant_owner', 'tenant_admin']) then
    raise exception 'only workspace owners/admins can set escalation rules';
  end if;

  if p_de_id is not null then
    select name into v_de_name from digital_employees where id = p_de_id and tenant_id = v_tenant;
    if v_de_name is null then raise exception 'employee not found in this workspace'; end if;
  end if;

  if p_frustration_threshold is null and array_length(v_topics, 1) is null then
    delete from de_escalation_rules
    where tenant_id = v_tenant and coalesce(de_id::text, '') = coalesce(p_de_id::text, '');
    perform append_audit_event_internal(
      v_tenant, 'You', 'human',
      format('Escalation rules for %s cleared — falls back to the shared default', v_de_name),
      'config_change',
      jsonb_build_object('kind', 'escalation_rules_cleared', 'de_id', p_de_id)
    );
    return jsonb_build_object('ok', true, 'cleared', true);
  end if;

  insert into de_escalation_rules (tenant_id, de_id, frustration_threshold, always_escalate_topics, updated_by)
  values (v_tenant, p_de_id, p_frustration_threshold, v_topics, auth.uid())
  on conflict (tenant_id, coalesce(de_id::text, ''))
  do update set frustration_threshold = excluded.frustration_threshold,
                always_escalate_topics = excluded.always_escalate_topics,
                updated_by = excluded.updated_by,
                updated_at = now();

  perform append_audit_event_internal(
    v_tenant, 'You', 'human',
    format('Escalation rules for %s set — frustration threshold %s, %s always-escalate topic(s)',
      v_de_name,
      coalesce(p_frustration_threshold::text, 'inherited'),
      coalesce(array_length(v_topics, 1), 0)),
    'config_change',
    jsonb_build_object('kind', 'escalation_rules_set', 'de_id', p_de_id,
      'frustration_threshold', p_frustration_threshold, 'topics', v_topics)
  );

  return jsonb_build_object('ok', true);
end;
$function$;

CREATE OR REPLACE FUNCTION public.set_de_external_reply_mode(p_de_id uuid, p_mode text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tenant uuid;
begin
  if auth.uid() is null then raise exception 'not authenticated'; end if;
  if p_mode not in ('draft', 'auto') then raise exception 'mode must be draft or auto'; end if;
  select tenant_id into v_tenant from digital_employees where id = p_de_id;
  if v_tenant is null then raise exception 'digital_employee_not_found'; end if;
  if not (is_platform_admin() or exists (select 1 from profiles p where p.user_id = auth.uid() and p.tenant_id = v_tenant)) then
    raise exception 'not authorized for this workspace';
  end if;
  -- Role gate (mig 433). Membership above proves WHICH WORKSPACE; this
  -- proves the caller is accountable for it. Owner/admin only, not manager:
  -- switching to auto does not approve one reply, it removes the approval
  -- step for every future one.
  if not (is_platform_admin() or public.auth_has_tenant_role(ARRAY['tenant_owner', 'tenant_admin'])) then
    raise exception 'insufficient_permission: turning external replies on or off requires an owner or admin';
  end if;
  update digital_employees set external_reply_mode = p_mode where id = p_de_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.set_de_kpi(p_de_id uuid, p_metric_key text, p_name text, p_target numeric, p_direction text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tenant uuid;
  v_de_name text;
  v_actor text;
begin
  v_tenant := auth_tenant_id();
  if v_tenant is null then raise exception 'not a member of any tenant'; end if;
  if not auth_has_tenant_role(array['tenant_owner', 'tenant_admin']) then
    raise exception 'only workspace owners/admins can set KPIs';
  end if;
  select name into v_de_name from digital_employees
  where id = p_de_id and tenant_id = v_tenant and lifecycle_status not in ('retired', 'archived');
  if v_de_name is null then raise exception 'employee not found in this workspace (or retired)'; end if;

  select full_name into v_actor from profiles where user_id = auth.uid();

  if p_target is null then
    delete from de_kpis where tenant_id = v_tenant and de_id = p_de_id and metric_key = p_metric_key;
    perform append_audit_event_internal(
      v_tenant, coalesce(v_actor, 'A workspace admin'), 'human',
      format('%s KPI removed (%s)', v_de_name, p_metric_key),
      'config_change',
      jsonb_build_object('kind', 'de_kpi_removed', 'de_id', p_de_id, 'metric_key', p_metric_key)
    );
    return jsonb_build_object('ok', true, 'removed', true);
  end if;

  if p_direction not in ('higher', 'lower') then raise exception 'direction must be higher or lower'; end if;
  if p_name is null or trim(p_name) = '' then raise exception 'a KPI needs a name'; end if;

  insert into de_kpis (tenant_id, de_id, name, metric_key, target, direction, owner_user_id)
  values (v_tenant, p_de_id, trim(p_name), p_metric_key, p_target, p_direction, auth.uid())
  on conflict (tenant_id, de_id, metric_key)
  do update set name = excluded.name, target = excluded.target, direction = excluded.direction;

  perform append_audit_event_internal(
    v_tenant, coalesce(v_actor, 'A workspace admin'), 'human',
    format('%s KPI set — "%s": %s %s %s', v_de_name, trim(p_name), p_metric_key,
      case when p_direction = 'higher' then '≥' else '≤' end, p_target),
    'config_change',
    jsonb_build_object('kind', 'de_kpi_set', 'de_id', p_de_id, 'metric_key', p_metric_key, 'target', p_target)
  );
  return jsonb_build_object('ok', true);
end;
$function$;

CREATE OR REPLACE FUNCTION public.set_de_mission_state(p_mission_id uuid, p_action text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tenant uuid; v_status text; v_next text; v_de uuid;
BEGIN
  v_tenant := public.auth_tenant_id();
  IF v_tenant IS NULL OR NOT public.auth_has_tenant_role(
       ARRAY['tenant_owner','tenant_admin','tenant_manager']) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_permitted');
  END IF;
  SELECT status, de_id INTO v_status, v_de FROM de_missions
   WHERE id = p_mission_id AND tenant_id = v_tenant FOR UPDATE;
  IF v_status IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_found');
  END IF;
  -- DE scoping (mig 385/423). DEFENCE IN DEPTH: the manager+ gate above
  -- already implies this. NULL-TOLERANT because de_missions.de_id is NULL
  -- for every TEAM mission (targeting lives in target_spec) — the plain
  -- form would refuse those while the reader still shows them.
  -- KNOWN GAP: this does not walk target_spec, so a team mission is not
  -- scoped by it. See the header and docs/30.
  IF v_de IS NOT NULL AND NOT public.can_access_de(v_de) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_responsible_for_de');
  END IF;
  v_next := CASE
    WHEN p_action = 'pause'  AND v_status IN ('approved','running') THEN 'paused'
    WHEN p_action = 'resume' AND v_status = 'paused'                THEN 'running'
    WHEN p_action = 'cancel' AND v_status IN ('draft','awaiting_approval',
                                              'approved','running','paused')
                                                                    THEN 'cancelled'
    ELSE NULL END;
  IF v_next IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_transition',
                              'from', v_status, 'action', p_action);
  END IF;
  UPDATE de_missions SET status = v_next, updated_at = now(),
         finished_at = CASE WHEN v_next = 'cancelled' THEN now() ELSE finished_at END
   WHERE id = p_mission_id;

  IF v_next = 'paused' THEN
    UPDATE work_watchers SET active = false, updated_at = now()
     WHERE mission_id = p_mission_id AND tenant_id = v_tenant;
  ELSIF v_next = 'running' AND p_action = 'resume' THEN
    UPDATE work_watchers SET active = true, updated_at = now()
     WHERE mission_id = p_mission_id AND tenant_id = v_tenant;
  ELSIF v_next = 'cancelled' THEN
    -- stop future ticks FIRST (matches cascade-cleans work_watcher_matches),
    -- then unwind queued/open work — same order the adversary asked for.
    DELETE FROM work_watchers
     WHERE mission_id = p_mission_id AND tenant_id = v_tenant;
    UPDATE de_work_items w SET status = 'cancelled', updated_at = now()
      FROM de_objectives o
     WHERE w.objective_id = o.id AND o.mission_id = p_mission_id
       AND w.tenant_id = v_tenant AND w.status = 'queued';
    UPDATE de_objectives SET status = 'abandoned', updated_at = now()
     WHERE mission_id = p_mission_id AND status IN ('open','in_progress','blocked');
  END IF;
  RETURN jsonb_build_object('ok', true, 'status', v_next);
END $function$;

CREATE OR REPLACE FUNCTION public.set_de_objective_status(p_id uuid, p_status text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is null then
    raise exception 'not authenticated: setting an objective''s status is not an anonymous operation';
  end if;
  if not exists (select 1 from de_objectives o join profiles p on p.user_id = auth.uid()
                  where o.id = p_id and (p.tenant_id = o.tenant_id or p.layer = 'platform')) then
    raise exception 'not authorized';
  end if;
  perform public.set_de_objective_status_internal(p_id, p_status);
end;
$function$;

CREATE OR REPLACE FUNCTION public.set_de_objective_status_internal(p_id uuid, p_status text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  -- NO USER CHECK. de-work drives the objective lifecycle on the service-role
  -- admin client (index.ts:265, :328, :2147). EXECUTE is service_role only.
  update de_objectives set status = p_status, updated_at = now() where id = p_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.set_de_operate_login(p_system_id uuid, p_secret text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tenant uuid; v_existing uuid; v_new uuid;
BEGIN
  SELECT tenant_id, login_secret_id INTO v_tenant, v_existing
    FROM de_connected_systems WHERE id = p_system_id;
  IF v_tenant IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'binding_not_found'); END IF;
  IF NOT public.can_admin_tenant_internal(v_tenant) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_permitted');
  END IF;
  IF nullif(btrim(coalesce(p_secret,'')),'') IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'secret_required');
  END IF;

  IF v_existing IS NOT NULL THEN
    PERFORM vault.update_secret(v_existing, p_secret);
  ELSE
    v_new := vault.create_secret(p_secret, 'de_operate_login:' || p_system_id, 'DE Browser Operator UI login (mig 244)');
    UPDATE de_connected_systems SET login_secret_id = v_new WHERE id = p_system_id;
  END IF;
  RETURN jsonb_build_object('ok', true);
END; $function$;

CREATE OR REPLACE FUNCTION public.set_de_org_unit(p_de_id uuid, p_org_unit_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tenant uuid := auth_tenant_id();
begin
  if v_tenant is null then raise exception 'not_authenticated'; end if;
  if not auth_has_tenant_role(array['tenant_owner','tenant_admin','tenant_manager']) then
    raise exception 'not_allowed: only an owner, admin or manager may move an employee between departments';
  end if;
  if not exists (select 1 from digital_employees where id = p_de_id and tenant_id = v_tenant) then
    raise exception 'no_such_employee_in_this_workspace';
  end if;
  if p_org_unit_id is not null and not exists (
    select 1 from org_units where id = p_org_unit_id and tenant_id = v_tenant and is_active
  ) then
    raise exception 'that is not a department in this workspace';
  end if;

  -- department follows via trg_sync_de_department.
  update digital_employees set org_unit_id = p_org_unit_id, updated_at = now() where id = p_de_id;

  return jsonb_build_object('ok', true,
    'department', coalesce((select name from org_units where id = p_org_unit_id), ''));
end;
$function$;

CREATE OR REPLACE FUNCTION public.set_de_skill_proficiency(p_de_id uuid, p_skill_key text, p_proficiency integer, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tenant uuid := auth_tenant_id();
  v_is_custom boolean;
  v_rater text;
BEGIN
  IF v_tenant IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  IF NOT auth_has_tenant_role(ARRAY['tenant_owner','tenant_admin']) THEN
    RAISE EXCEPTION 'insufficient_role';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM digital_employees WHERE id = p_de_id AND tenant_id = v_tenant) THEN
    RAISE EXCEPTION 'de_not_found';
  END IF;

  SELECT (tenant_id IS NOT NULL) INTO v_is_custom
    FROM skill_catalog
   WHERE skill_key = p_skill_key AND (tenant_id IS NULL OR tenant_id = v_tenant);
  IF v_is_custom IS NULL THEN RAISE EXCEPTION 'unknown_skill: %', p_skill_key; END IF;

  -- The guarantee that makes built-in proficiency trustworthy.
  IF NOT v_is_custom THEN
    RAISE EXCEPTION 'builtin_skill_is_evidence_assessed: % cannot be set by hand', p_skill_key;
  END IF;

  IF p_proficiency IS NOT NULL AND (p_proficiency < 1 OR p_proficiency > 5) THEN
    RAISE EXCEPTION 'proficiency must be between 1 and 5';
  END IF;

  SELECT coalesce(full_name, 'a workspace admin') INTO v_rater FROM profiles WHERE user_id = auth.uid();

  INSERT INTO de_skills (tenant_id, de_id, skill_key, proficiency, sample_size, signal_value, detail, assessed_at)
  VALUES (
    v_tenant, p_de_id, p_skill_key, p_proficiency, 0, NULL,
    CASE WHEN p_proficiency IS NULL
      THEN 'Not rated yet — this skill is rated by a person, not measured automatically.'
      ELSE format('Rated %s by %s%s', p_proficiency, v_rater,
                  CASE WHEN coalesce(p_note,'') <> '' THEN ' — ' || p_note ELSE '' END)
    END,
    now()
  )
  ON CONFLICT (de_id, skill_key) DO UPDATE
    SET proficiency = excluded.proficiency,
        detail      = excluded.detail,
        assessed_at = now();

  RETURN jsonb_build_object('ok', true, 'skill_key', p_skill_key, 'proficiency', p_proficiency);
END$function$;

CREATE OR REPLACE FUNCTION public.set_de_supervisor(p_de_id uuid, p_enable boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_tenant uuid;
begin
  select tenant_id into v_tenant from digital_employees where id = p_de_id;
  if v_tenant is null then raise exception 'digital employee not found'; end if;
  if not (public.is_platform_admin()
          or (v_tenant = public.auth_tenant_id()
              and public.auth_has_tenant_role(array['tenant_owner','tenant_admin']))) then
    raise exception 'only a workspace owner/admin can designate a supervisor';
  end if;
  if p_enable then
    -- Clear the current supervisor first (the partial unique index would
    -- otherwise reject a second true row), then set this one.
    update digital_employees set is_supervisor = false
     where tenant_id = v_tenant and is_supervisor and id <> p_de_id;
    update digital_employees set is_supervisor = true where id = p_de_id;
  else
    update digital_employees set is_supervisor = false where id = p_de_id;
  end if;
end;
$function$;

CREATE OR REPLACE FUNCTION public.set_doc_lifecycle(p_doc_id uuid, p_owner_user_id uuid DEFAULT NULL::uuid, p_review_interval_days integer DEFAULT NULL::integer, p_authority integer DEFAULT NULL::integer, p_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tenant uuid := public.auth_tenant_id();
BEGIN
  IF v_tenant IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'no_tenant'); END IF;
  UPDATE knowledge_docs SET
    owner_user_id        = p_owner_user_id,
    review_interval_days = CASE WHEN p_review_interval_days IS NULL THEN NULL
                                ELSE greatest(1, p_review_interval_days) END,
    authority            = CASE WHEN p_authority IS NULL THEN authority
                                ELSE greatest(0, least(100, p_authority)) END,
    expires_at           = p_expires_at,
    updated_at           = now()
   WHERE id = p_doc_id AND tenant_id = v_tenant;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'error', 'doc_not_found'); END IF;
  RETURN jsonb_build_object('ok', true);
END $function$;

CREATE OR REPLACE FUNCTION public.set_doc_scope(p_doc_id uuid, p_subjects jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user uuid := auth.uid(); v_caller_tenant uuid; v_is_active boolean;
  v_doc_tenant uuid; v_doc_title text; v_before text; v_after text; v_archetype text;
  v_subj jsonb; v_kind text; v_sid uuid; v_label text; v_labels text[] := '{}'; v_count integer := 0;
begin
  select tenant_id, title, visibility, share_archetype_key
    into v_doc_tenant, v_doc_title, v_before, v_archetype
    from knowledge_docs where id = p_doc_id;
  if v_doc_tenant is null then return jsonb_build_object('ok', false, 'error', 'doc_not_found'); end if;

  if v_user is not null then
    select tenant_id, coalesce(is_active, true) into v_caller_tenant, v_is_active from profiles where user_id = v_user;
    if v_caller_tenant is null or v_caller_tenant <> v_doc_tenant then return jsonb_build_object('ok', false, 'error', 'not_tenant_member', 'detail', 'Only members of this workspace can change who uses a document.'); end if;
    if not v_is_active then return jsonb_build_object('ok', false, 'error', 'not_tenant_member', 'detail', 'Only members of this workspace can change who uses a document.'); end if;
  elsif coalesce(auth.role(), '') <> 'service_role' then
    return jsonb_build_object('ok', false, 'error', 'not_tenant_member', 'detail', 'Only members of this workspace can change who uses a document.');
  end if;

  if p_subjects is null or jsonb_typeof(p_subjects) <> 'array' then return jsonb_build_object('ok', false, 'error', 'bad_subjects', 'detail', 'p_subjects must be a JSON array of {kind, id}.'); end if;

  for v_subj in select * from jsonb_array_elements(p_subjects) loop
    v_kind := v_subj->>'kind';
    begin v_sid := (v_subj->>'id')::uuid; exception when others then return jsonb_build_object('ok', false, 'error', 'bad_subject_id'); end;
    if v_kind in ('de', 'specialist') then
      select name into v_label from digital_employees where id = v_sid and tenant_id = v_doc_tenant;
    elsif v_kind = 'de_team' then
      -- 363: a team of employees is an audience. Still tenant-checked, so a
      -- team id from another workspace cannot be attached.
      select name into v_label from workforce_teams where id = v_sid and tenant_id = v_doc_tenant;
    else
      return jsonb_build_object('ok', false, 'error', 'bad_subject_kind');
    end if;
    if v_label is null then return jsonb_build_object('ok', false, 'error', 'subject_not_in_tenant', 'detail', v_kind || ' ' || v_sid || ' is not in this workspace.'); end if;
    v_labels := array_append(v_labels, v_label || ' (' || v_kind || ')');
    v_count := v_count + 1;
  end loop;

  delete from knowledge_doc_scopes where doc_id = p_doc_id;
  for v_subj in select * from jsonb_array_elements(p_subjects) loop
    insert into knowledge_doc_scopes (tenant_id, doc_id, subject_kind, subject_id)
    values (v_doc_tenant, p_doc_id, v_subj->>'kind', (v_subj->>'id')::uuid)
    on conflict (doc_id, subject_kind, subject_id) do nothing;
  end loop;

  -- 363: THE CLOBBER FIX. Clearing the subject list on an archetype-shared
  -- document used to drop it to 'tenant', silently WIDENING its audience to
  -- every employee. It now returns to 'role', which is where it came from.
  v_after := case
    when v_count > 0 then 'scoped'
    when v_before = 'role' and v_archetype is not null then 'role'
    else 'tenant' end;
  update knowledge_docs set visibility = v_after where id = p_doc_id;

  begin
    perform append_audit_event(v_doc_tenant,
      coalesce((select full_name from profiles where user_id = v_user), 'service'),
      case when v_user is null then 'system' else 'human' end,
      'Knowledge scope changed — "' || v_doc_title || '": ' || v_before || ' → ' || v_after ||
        case when v_count > 0 then ' (only ' || array_to_string(v_labels, ', ') || ' will use this document)'
             when v_after = 'role' then ' (shared with the ' || v_archetype || ' role)'
             else ' (all digital employees will use this document)' end,
      'access_control', jsonb_build_object('kind', 'knowledge_scope_changed', 'doc_id', p_doc_id, 'doc_title', v_doc_title, 'before', v_before, 'after', v_after, 'subjects', p_subjects, 'subject_labels', v_labels));
  exception when others then null; end;
  return jsonb_build_object('ok', true, 'visibility', v_after, 'subjects', v_count);
end; $function$;

CREATE OR REPLACE FUNCTION public.set_employee_compensation(p_user_id uuid, p_amount_cents bigint, p_currency text, p_pay_frequency text, p_effective_from date, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tenant uuid := auth_tenant_id();
  v_id     uuid;
begin
  if v_tenant is null then raise exception 'not_authenticated'; end if;
  -- Owners and admins only. Deliberately NOT self: being able to read your own
  -- pay is reasonable, being able to set it is not.
  if not auth_has_tenant_role(array['tenant_owner','tenant_admin']) then
    raise exception 'not_allowed: only an owner or admin may set pay';
  end if;
  if not exists (select 1 from profiles where user_id = p_user_id and tenant_id = v_tenant) then
    raise exception 'no_such_employee_in_this_workspace';
  end if;
  if p_amount_cents is null or p_amount_cents < 0 then
    raise exception 'amount must be zero or more';
  end if;

  -- Close the previous open record the day before this one starts, rather than
  -- overwriting it. What somebody used to be paid is the record you need when
  -- a pay question arrives, and it is gone forever if a raise is an UPDATE.
  update profile_compensation
     set effective_to = p_effective_from - 1
   where tenant_id = v_tenant and user_id = p_user_id and effective_to is null
     and effective_from < p_effective_from;

  insert into profile_compensation
    (user_id, tenant_id, amount_cents, currency, pay_frequency, effective_from, note, created_by)
  values
    (p_user_id, v_tenant, p_amount_cents, coalesce(nullif(p_currency,''), 'USD'),
     coalesce(nullif(p_pay_frequency,''), 'annual'), p_effective_from, nullif(btrim(p_note),''), auth.uid())
  returning id into v_id;

  -- Pay changes are the kind of thing that must be answerable later.
  perform append_audit_event(
    v_tenant,
    coalesce((select full_name from profiles where user_id = auth.uid()), 'An administrator'),
    'human',
    format('Set pay for %s', coalesce((select full_name from profiles where user_id = p_user_id), 'an employee')),
    'access_control',
    jsonb_build_object('kind','compensation_set','subject_user_id',p_user_id,
                       'effective_from',p_effective_from,'record_id',v_id));

  return jsonb_build_object('ok', true, 'id', v_id);
end;
$function$;

CREATE OR REPLACE FUNCTION public.set_improvement_publish_scope(p_improvement_id uuid, p_scope text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE imp de_improvements;
BEGIN
  IF p_scope NOT IN ('de', 'role') THEN
    RAISE EXCEPTION 'invalid scope %', p_scope;
  END IF;

  SELECT * INTO imp FROM de_improvements WHERE id = p_improvement_id FOR UPDATE;
  IF imp.id IS NULL THEN RAISE EXCEPTION 'improvement not found'; END IF;

  -- The service role is the trusted backend and passes. EVERY other caller,
  -- including an anonymous one, must be a member of the improvement's tenant or
  -- platform staff. Previously an anonymous caller matched neither branch and
  -- fell straight through.
  IF coalesce(auth.role(), '') <> 'service_role'
     AND NOT EXISTS (
       SELECT 1 FROM profiles p
        WHERE p.user_id = auth.uid()
          AND (p.layer = 'platform' OR p.tenant_id = imp.tenant_id))
  THEN
    RAISE EXCEPTION 'not authorized';
  END IF;

  IF imp.status = 'applied' THEN
    RAISE EXCEPTION 'improvement already published — scope is locked';
  END IF;
  IF imp.status = 'rejected' THEN
    RAISE EXCEPTION 'improvement was rejected';
  END IF;

  UPDATE de_improvements
     SET publish_scope = p_scope, updated_at = now()
   WHERE id = p_improvement_id;
END $function$;

CREATE OR REPLACE FUNCTION public.set_knowledge_freshness_config(p_key text, p_value numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT public.is_platform_admin() THEN RETURN jsonb_build_object('ok', false, 'error', 'forbidden'); END IF;
  IF p_key NOT IN ('knowledge.freshness_weight', 'knowledge.freshness_halflife_days', 'knowledge.freshness_expired_penalty') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'bad_key');
  END IF;
  IF p_value IS NULL OR p_value < 0 THEN RETURN jsonb_build_object('ok', false, 'error', 'bad_value'); END IF;
  -- platform_config.value is a plain text column; store the number as text.
  INSERT INTO platform_config (key, value) VALUES (p_key, p_value::text)
  ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value;
  RETURN jsonb_build_object('ok', true, 'key', p_key, 'value', p_value);
END $function$;

CREATE OR REPLACE FUNCTION public.set_knowledge_lifecycle(p_doc_id uuid, p_status text, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tenant uuid := auth_tenant_id();
  v_doc knowledge_docs;
  v_level int;
  v_needed int;
BEGIN
  IF v_tenant IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  IF p_status NOT IN ('draft','in_review','published','archived') THEN
    RAISE EXCEPTION 'unknown lifecycle state: %', p_status;
  END IF;

  SELECT * INTO v_doc FROM knowledge_docs WHERE id = p_doc_id AND tenant_id = v_tenant;
  IF v_doc.id IS NULL THEN RAISE EXCEPTION 'document_not_found'; END IF;

  -- Publishing and archiving are governance acts; drafting is authorship.
  v_needed := CASE WHEN p_status IN ('published','archived') THEN 4 ELSE 2 END;
  v_level := knowledge_effective_level(p_doc_id);
  IF v_level < v_needed THEN
    RAISE EXCEPTION 'insufficient_permission: % requires %, you have level %',
      p_status, CASE WHEN v_needed = 4 THEN 'publisher' ELSE 'contributor' END, v_level;
  END IF;

  UPDATE knowledge_docs SET lifecycle_status = p_status WHERE id = p_doc_id;

  PERFORM append_audit_event(
    v_tenant, 'Knowledge', 'human',
    format('%s moved to %s — %s', left(coalesce(v_doc.title,'a document'), 80), p_status, coalesce(p_note,'no note')),
    'approval',
    jsonb_build_object('doc_id', p_doc_id, 'from', v_doc.lifecycle_status, 'to', p_status));

  RETURN jsonb_build_object('ok', true, 'from', v_doc.lifecycle_status, 'to', p_status);
END $function$;

CREATE OR REPLACE FUNCTION public.set_learned_action_status(p_tenant_id uuid, p_action_id uuid, p_status text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_n int;
BEGIN
  IF p_status NOT IN ('active', 'draft', 'disabled') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'bad_status');
  END IF;
  -- Publishing hands a write tool to the whole workforce: owners/admins only.
  IF coalesce(auth.role(), '') <> 'service_role' AND NOT EXISTS (
    SELECT 1 FROM profiles p
     WHERE p.user_id = auth.uid() AND p.tenant_id = p_tenant_id
       AND (p.layer = 'platform' OR p.role IN ('tenant_owner', 'tenant_admin'))
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_authorized');
  END IF;

  UPDATE action_definitions
     SET status = p_status, updated_at = now()
   WHERE id = p_action_id AND tenant_id = p_tenant_id
     AND scope = 'tenant' AND provider = 'learned_http';
  GET DIAGNOSTICS v_n = ROW_COUNT;
  IF v_n = 0 THEN RETURN jsonb_build_object('ok', false, 'error', 'not_found_or_not_learned'); END IF;
  RETURN jsonb_build_object('ok', true, 'status', p_status);
END $function$;

CREATE OR REPLACE FUNCTION public.set_oauth_app(p_provider text, p_client_id text, p_client_secret text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not is_platform_admin() then
    raise exception 'only platform admins can configure OAuth apps';
  end if;
  if p_provider !~ '^[a-z0-9_]+$' then
    raise exception 'invalid provider';
  end if;
  perform platform_config_set(jsonb_build_object(
    'oauth:' || p_provider || ':client_id', coalesce(p_client_id, ''),
    'oauth:' || p_provider || ':client_secret', coalesce(p_client_secret, '')
  ));
end $function$;

CREATE OR REPLACE FUNCTION public.set_onboarding_project_status(p_project_id uuid, p_status text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_proj onboarding_projects;
begin
  if p_status not in ('active', 'on_hold', 'cancelled') then
    return jsonb_build_object('error', 'invalid_status');
  end if;
  select * into v_proj from onboarding_projects where id = p_project_id;
  if not found then return jsonb_build_object('error', 'project_not_found'); end if;
  if not exists (
    select 1 from profiles where user_id = auth.uid() and tenant_id = v_proj.tenant_id and coalesce(is_active, true) = true
  ) then
    raise exception 'not a member of this tenant';
  end if;
  if v_proj.status = 'completed' then
    return jsonb_build_object('error', 'project_completed');
  end if;
  if v_proj.status = p_status then
    return jsonb_build_object('status', p_status);
  end if;

  update onboarding_projects set status = p_status where id = p_project_id;

  perform append_audit_event_internal(
    v_proj.tenant_id, 'You', 'human',
    format('Onboarding project %s — %s', case p_status when 'cancelled' then 'cancelled'
           when 'on_hold' then 'put on hold' else 'reactivated' end, v_proj.name),
    'config_change',
    jsonb_build_object('kind', 'onboarding_project_' || p_status, 'project_id', p_project_id,
                       'old_status', v_proj.status, 'new_status', p_status));

  return jsonb_build_object('status', p_status);
end;
$function$;

CREATE OR REPLACE FUNCTION public.set_platform_capability_grant(p_target_user_id uuid, p_capability text, p_effect text, p_note text DEFAULT ''::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_target_layer text;
  v_grant platform_capability_grants;
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;
  if not resolve_platform_capability(auth.uid(), 'team.manage') then
    raise exception 'only a platform team manager may change a teammate''s permissions';
  end if;
  if auth.uid() = p_target_user_id then
    raise exception 'you cannot change your own permissions here';
  end if;
  if p_effect not in ('grant', 'deny') then
    raise exception 'effect must be grant or deny';
  end if;
  if p_capability not in (
    'tenants.view', 'tenants.manage', 'tenants.provision',
    'remote_access.use', 'remote_access.audit',
    'team.manage', 'billing.manage', 'support.cross_tenant'
  ) then
    raise exception 'unrecognized capability: %', p_capability;
  end if;

  select layer into v_target_layer from profiles where user_id = p_target_user_id;
  if v_target_layer is distinct from 'platform' then
    raise exception 'that account is not a platform team member';
  end if;

  if p_capability = 'team.manage' and p_effect = 'deny'
     and platform_capability_remaining_holders(p_target_user_id, 'team.manage') = 0 then
    raise exception 'this change would leave zero active platform accounts able to manage the team -- at least one must always remain';
  end if;

  insert into platform_capability_grants (user_id, capability, effect, granted_by, note)
  values (p_target_user_id, p_capability, p_effect, auth.uid(), coalesce(p_note, ''))
  on conflict (user_id, capability) do update
    set effect = excluded.effect, granted_by = excluded.granted_by,
        note = excluded.note, updated_at = now()
  returning * into v_grant;

  return jsonb_build_object('ok', true, 'grant', to_jsonb(v_grant));
end;
$function$;

CREATE OR REPLACE FUNCTION public.set_platform_team_active(p_target_user_id uuid, p_is_active boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_target_layer text;
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;
  if not resolve_platform_capability(auth.uid(), 'team.manage') then
    raise exception 'only a platform team manager may change a teammate''s active status';
  end if;
  if auth.uid() = p_target_user_id then
    raise exception 'you cannot change your own active status here';
  end if;

  select layer into v_target_layer from profiles where user_id = p_target_user_id;
  if v_target_layer is distinct from 'platform' then
    raise exception 'that account is not a platform team member';
  end if;

  if not p_is_active and platform_capability_remaining_holders(p_target_user_id, 'team.manage') = 0 then
    raise exception 'this change would leave zero active platform accounts able to manage the team -- at least one must always remain';
  end if;

  update profiles set is_active = p_is_active where user_id = p_target_user_id;

  return jsonb_build_object('ok', true, 'user_id', p_target_user_id, 'is_active', p_is_active);
end;
$function$;

CREATE OR REPLACE FUNCTION public.set_review_minutes(p_task_type text, p_minutes numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_tenant uuid; v_updated int;
begin
  v_tenant := public.auth_tenant_id();
  if v_tenant is null or not public.auth_has_tenant_role(array['tenant_owner','tenant_admin']) then
    return jsonb_build_object('ok', false, 'error', 'not_permitted');
  end if;
  if p_task_type not in ('approval_gate','review_gate','escalation','override','training_feedback',
                         'trust_promotion','trust_demotion_notice','checklist','knowledge_revision',
                         'inquiry_review','action_approval') then
    return jsonb_build_object('ok', false, 'error', 'unknown_task_type', 'task_type', p_task_type);
  end if;
  if p_minutes is null or p_minutes <= 0 or p_minutes > 60 then
    return jsonb_build_object('ok', false, 'error', 'minutes_out_of_range',
                              'detail', 'minutes must be greater than 0 and at most 60');
  end if;

  update review_time_standards
     set minutes = p_minutes, source = 'founder', updated_at = now()
   where tenant_id = v_tenant and task_type = p_task_type;
  get diagnostics v_updated = row_count;
  if v_updated = 0 then
    insert into review_time_standards (tenant_id, task_type, minutes, source)
    values (v_tenant, p_task_type, p_minutes, 'founder');
  end if;

  return jsonb_build_object('ok', true, 'task_type', p_task_type,
                            'effective_minutes', public.resolve_review_minutes(v_tenant, p_task_type),
                            'overridden', true);
end $function$;

CREATE OR REPLACE FUNCTION public.set_review_narrative(p_review_id uuid, p_narrative text, p_model text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_n int;
begin
  if coalesce(btrim(p_narrative), '') = '' then
    raise exception 'narrative_empty: refusing to store an empty commentary';
  end if;
  if coalesce(btrim(p_model), '') = '' then
    raise exception 'model_required: a narrative with no recorded author cannot be weighed';
  end if;

  update de_performance_reviews
     set ai_narrative       = p_narrative,
         ai_narrative_model = p_model,
         ai_narrative_at    = now()
   where id = p_review_id;

  get diagnostics v_n = row_count;
  return v_n = 1;
end
$function$;

CREATE OR REPLACE FUNCTION public.set_review_narrative_settings(p_enabled boolean, p_instructions text DEFAULT NULL::text, p_de_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_tenant uuid := auth_tenant_id();
  v_id     uuid;
begin
  if v_tenant is null then raise exception 'not_authenticated'; end if;
  if not auth_has_tenant_role(array['tenant_owner','tenant_admin']) then
    raise exception 'insufficient_role';
  end if;

  -- An employee override may only name an employee of THIS workspace. A
  -- tenant id resolved from the caller is authorisation; a de_id supplied by
  -- the caller is an assertion, and gets checked.
  if p_de_id is not null and not exists (
      select 1 from digital_employees d where d.id = p_de_id and d.tenant_id = v_tenant) then
    raise exception 'de_not_in_workspace';
  end if;

  if length(coalesce(p_instructions, '')) > 2000 then
    raise exception 'instructions_too_long: % characters, limit 2000', length(p_instructions);
  end if;

  -- ⚠ ON CONFLICT matches ONE index, and these are two PARTIAL indexes with
  -- different predicates. Branch on which row is being written — a single
  -- statement naming either target would raise on the other kind rather than
  -- fall through to it.
  if p_de_id is not null then
    insert into de_review_narrative_settings (tenant_id, de_id, enabled, instructions, updated_by)
    values (v_tenant, p_de_id, coalesce(p_enabled, false), nullif(btrim(coalesce(p_instructions,'')), ''), auth.uid())
    on conflict (tenant_id, de_id) where de_id is not null
    do update set enabled = excluded.enabled, instructions = excluded.instructions,
                  updated_by = excluded.updated_by, updated_at = now()
    returning id into v_id;
  else
    insert into de_review_narrative_settings (tenant_id, de_id, enabled, instructions, updated_by)
    values (v_tenant, null, coalesce(p_enabled, false), nullif(btrim(coalesce(p_instructions,'')), ''), auth.uid())
    on conflict (tenant_id) where de_id is null
    do update set enabled = excluded.enabled, instructions = excluded.instructions,
                  updated_by = excluded.updated_by, updated_at = now()
    returning id into v_id;
  end if;

  return v_id;
end
$function$;

CREATE OR REPLACE FUNCTION public.set_rule_adjudicable(p_rule_id uuid, p_on boolean, p_justification text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_rule  guardrail_rules;
  v_actor text;
BEGIN
  SELECT * INTO v_rule FROM guardrail_rules WHERE id = p_rule_id;
  IF v_rule.id IS NULL THEN RAISE EXCEPTION 'guardrail rule not found'; END IF;

  IF NOT EXISTS (
    SELECT 1 FROM profiles p
     WHERE p.user_id = auth.uid()
       AND (p.layer = 'platform'
            OR (p.tenant_id = v_rule.tenant_id AND p.role IN ('tenant_owner','tenant_admin'))))
  THEN RAISE EXCEPTION 'only workspace owners/admins can change what a machine may overrule'; END IF;

  IF v_rule.severity <> 'blocking' OR v_rule.rule_type NOT IN ('blocked_phrase','blocked_topic') THEN
    RAISE EXCEPTION 'only blocking phrase/topic rules can be adjudicated';
  END IF;

  IF p_on THEN
    IF p_justification IS NULL OR length(btrim(p_justification)) < 40 THEN
      RAISE EXCEPTION 'a written justification of at least 40 characters is required to let a machine overrule this rule';
    END IF;
    -- Compliance-pack rules are described by this product as un-toggleable.
    -- That promise now also covers "un-clearable": the same owner-only escape
    -- hatch detach_compliance_pack requires (160:108) applies here.
    IF v_rule.compliance_pack_key IS NOT NULL
       AND coalesce(current_setting('app.allow_compliance_change', true), '') <> 'on' THEN
      RAISE EXCEPTION 'rule "%" comes from the % compliance pack — making it machine-clearable is an explicit compliance decision and requires the owner override', v_rule.rule, v_rule.compliance_pack_key;
    END IF;

    INSERT INTO guardrail_rule_adjudicable (tenant_id, rule_id, granted_by, justification)
    VALUES (v_rule.tenant_id, p_rule_id, auth.uid(), btrim(p_justification))
    ON CONFLICT (tenant_id, rule_id) DO UPDATE
      SET justification = excluded.justification, granted_by = excluded.granted_by, granted_at = now();
  ELSE
    DELETE FROM guardrail_rule_adjudicable WHERE tenant_id = v_rule.tenant_id AND rule_id = p_rule_id;
  END IF;

  SELECT full_name INTO v_actor FROM profiles WHERE user_id = auth.uid();
  -- Same transaction as the row write: the grant and its record commit together.
  PERFORM append_audit_event_internal(
    v_rule.tenant_id, coalesce(v_actor, 'A workspace admin'), 'human',
    format('%s: guardrail rule "%s" %s machine-clearable',
           CASE WHEN p_on THEN 'GRANTED' ELSE 'REVOKED' END, v_rule.rule,
           CASE WHEN p_on THEN 'is now' ELSE 'is no longer' END),
    'guardrail_adjudication',
    jsonb_build_object('kind', CASE WHEN p_on THEN 'adjudicable_granted' ELSE 'adjudicable_revoked' END,
                       'rule_id', p_rule_id, 'rule', v_rule.rule, 'pattern', v_rule.pattern,
                       'compliance_pack_key', v_rule.compliance_pack_key,
                       'justification', btrim(coalesce(p_justification, '')))
  );
  RETURN jsonb_build_object('rule_id', p_rule_id, 'adjudicable', p_on);
END $function$;

CREATE OR REPLACE FUNCTION public.set_space_restricted(p_space_id uuid, p_restricted boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tenant uuid := auth_tenant_id(); v_my int; v_name text; v_reachable int;
BEGIN
  IF v_tenant IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  SELECT name INTO v_name FROM knowledge_collections
   WHERE id = p_space_id AND tenant_id = v_tenant AND is_space;
  IF v_name IS NULL THEN RAISE EXCEPTION 'space_not_found'; END IF;

  v_my := public.knowledge_my_admin_level(p_space_id);
  IF v_my < 5 THEN
    RAISE EXCEPTION 'insufficient_permission: locking a space requires knowledge manager';
  END IF;

  UPDATE knowledge_collections SET is_restricted = p_restricted, updated_at = now()
   WHERE id = p_space_id;

  -- Locking a space with no explicit grants makes it reachable by nobody but
  -- platform staff. That is a legitimate thing to want, and a terrible thing to
  -- do BY ACCIDENT, so it is reported rather than silently done.
  v_reachable := 0;
  IF p_restricted THEN
    SELECT count(*) INTO v_reachable FROM knowledge_access_grants
     WHERE tenant_id = v_tenant AND resource_type = 'collection' AND resource_id = p_space_id;
  END IF;

  PERFORM append_audit_event(
    v_tenant, 'Knowledge', 'human',
    format('%s the space "%s"', CASE WHEN p_restricted THEN 'Restricted' ELSE 'Opened' END, v_name),
    'access_control',
    jsonb_build_object('space_id', p_space_id, 'restricted', p_restricted));

  RETURN jsonb_build_object('ok', true, 'restricted', p_restricted, 'explicit_grants', v_reachable);
END $function$;

CREATE OR REPLACE FUNCTION public.set_support_conversation_state(p_conversation_id uuid, p_status text DEFAULT NULL::text, p_priority text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_tenant uuid; v_de uuid;
begin
  perform set_config('app.allow_task_decision', 'on', true);   -- mig 486: sanctioned decision path
  v_tenant := _assert_conv_member(p_conversation_id);
  if p_status is not null and p_status not in ('ai_handling','needs_human','human_owned','resolved') then raise exception 'bad_status'; end if;
  if p_priority is not null and p_priority not in ('low','normal','high','urgent') then raise exception 'bad_priority'; end if;
  -- DE scoping (mig 385/408). Guards BOTH mutations below: the state change
  -- and the escalation auto-approval that p_status = ''resolved'' triggers.
  -- Placed after the argument validation so a bad status still fails as a
  -- bad status. Null-tolerant to match the mig-386 policy.
  select de_id into v_de from de_conversations where id = p_conversation_id;
  if v_de is not null and not public.can_access_de(v_de) then
    raise exception 'not_responsible_for_de: this employee is not in your reporting line';
  end if;

  update de_conversations
    set status = coalesce(p_status, status), priority = coalesce(p_priority, priority), last_message_at = now()
  where id = p_conversation_id;
  if p_status = 'resolved' then
    update human_tasks
       set status = 'approved', decided_by = auth.uid(), decided_at = now(), updated_at = now()
     where tenant_id = v_tenant and related_table = 'de_conversations'
       and related_id = p_conversation_id and type = 'escalation' and status = 'pending';
  end if;
end;
$function$;

CREATE OR REPLACE FUNCTION public.set_team_member_status(p_target_user_id uuid, p_is_active boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_caller_tenant uuid;
  v_caller_role text;
  v_target_tenant uuid;
  v_target_role text;
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;
  if auth.uid() = p_target_user_id then
    raise exception 'you cannot change your own active status here';
  end if;

  select tenant_id, role into v_caller_tenant, v_caller_role
  from profiles where user_id = auth.uid() and coalesce(is_active, true) = true;
  if v_caller_tenant is null or v_caller_role not in ('tenant_owner', 'tenant_admin') then
    raise exception 'only workspace owners/admins can change a teammate''s status';
  end if;

  select tenant_id, role into v_target_tenant, v_target_role
  from profiles where user_id = p_target_user_id;
  if v_target_tenant is null or v_target_tenant is distinct from v_caller_tenant then
    raise exception 'that person is not a member of this workspace';
  end if;
  if v_target_role = 'tenant_owner' then
    raise exception 'the workspace owner cannot be deactivated';
  end if;

  update profiles set is_active = p_is_active where user_id = p_target_user_id;

  perform append_audit_event_internal(
    v_caller_tenant, 'You', 'human',
    case when p_is_active then 'Team member reactivated' else 'Team member deactivated' end,
    'config_change',
    jsonb_build_object('kind', 'team_status_change', 'target_user_id', p_target_user_id, 'is_active', p_is_active)
  );

  return jsonb_build_object('ok', true);
end;
$function$;

CREATE OR REPLACE FUNCTION public.set_tenant_brand_identity(p_brand jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tenant uuid;
  v_key    text;
  v_hex    text;
BEGIN
  v_tenant := public.auth_tenant_id();
  IF v_tenant IS NULL OR NOT public.auth_has_tenant_role(ARRAY['tenant_owner','tenant_admin']) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_permitted');
  END IF;

  IF p_brand IS NULL OR jsonb_typeof(p_brand) <> 'object' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'brand_must_be_object');
  END IF;

  IF length(p_brand::text) > 20000 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'brand_too_large');
  END IF;

  -- Whitelist top-level sections; an unknown key is a hard refusal, not a skip.
  FOR v_key IN SELECT jsonb_object_keys(p_brand) LOOP
    IF v_key NOT IN ('overview','colors','typography','logo','voice','contact','outputs') THEN
      RETURN jsonb_build_object('ok', false, 'error', 'unknown_section', 'section', v_key);
    END IF;
    IF jsonb_typeof(p_brand -> v_key) <> 'object' THEN
      RETURN jsonb_build_object('ok', false, 'error', 'section_must_be_object', 'section', v_key);
    END IF;
  END LOOP;

  -- Every non-empty color value must be a 6-digit hex.
  IF p_brand ? 'colors' THEN
    FOR v_key IN SELECT jsonb_object_keys(p_brand -> 'colors') LOOP
      v_hex := nullif(lower(btrim(p_brand -> 'colors' ->> v_key)), '');
      IF v_hex IS NOT NULL AND v_hex !~ '^#[0-9a-f]{6}$' THEN
        RETURN jsonb_build_object('ok', false, 'error', 'color_must_be_hex6', 'field', v_key);
      END IF;
    END LOOP;
  END IF;

  INSERT INTO tenant_brand_identity (tenant_id, brand, updated_by, updated_at)
  VALUES (v_tenant, p_brand, auth.uid(), now())
  ON CONFLICT (tenant_id) DO UPDATE
    SET brand = excluded.brand, updated_by = excluded.updated_by, updated_at = now();

  RETURN jsonb_build_object('ok', true);
END; $function$;

CREATE OR REPLACE FUNCTION public.set_tenant_branding(p_accent_hex text, p_surface_key text DEFAULT 'midnight'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tenant uuid; v_hex text;
BEGIN
  v_tenant := public.auth_tenant_id();
  IF v_tenant IS NULL OR NOT public.auth_has_tenant_role(ARRAY['tenant_owner','tenant_admin']) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_permitted');
  END IF;
  IF p_surface_key NOT IN ('midnight','graphite') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'unknown_surface');
  END IF;
  v_hex := nullif(lower(btrim(coalesce(p_accent_hex,''))), '');
  IF v_hex IS NOT NULL AND v_hex !~ '^#[0-9a-f]{6}$' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'accent_must_be_hex6');
  END IF;
  INSERT INTO tenant_branding (tenant_id, accent_hex, surface_key, updated_at)
  VALUES (v_tenant, v_hex, p_surface_key, now())
  ON CONFLICT (tenant_id) DO UPDATE
    SET accent_hex = excluded.accent_hex, surface_key = excluded.surface_key, updated_at = now();
  RETURN jsonb_build_object('ok', true);
END; $function$;

CREATE OR REPLACE FUNCTION public.set_tenant_comms_settings(p_from_email text, p_from_name text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tenant uuid := public.auth_tenant_id();
BEGIN
  IF v_tenant IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'no_tenant'); END IF;
  IF NOT public.auth_has_tenant_role(ARRAY['tenant_owner','tenant_admin']) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'admin_role_required');
  END IF;
  IF coalesce(p_from_email,'') !~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'bad_email');
  END IF;
  INSERT INTO tenant_comms_settings (tenant_id, from_email, from_name, updated_by, updated_at)
  VALUES (v_tenant, lower(trim(p_from_email)), nullif(trim(coalesce(p_from_name,'')),''), auth.uid(), now())
  ON CONFLICT (tenant_id) DO UPDATE SET from_email = excluded.from_email, from_name = excluded.from_name, updated_by = excluded.updated_by, updated_at = now();
  RETURN jsonb_build_object('ok', true, 'from_email', lower(trim(p_from_email)));
END; $function$;

CREATE OR REPLACE FUNCTION public.set_tenant_feature_override(p_tenant_id uuid, p_feature_key text, p_enabled boolean, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not resolve_platform_capability(auth.uid(), 'tenants.manage') then
    raise exception 'only a platform team member with tenant management access may set a tenant feature override';
  end if;

  if not exists (select 1 from feature_registry where key = p_feature_key) then
    raise exception 'unknown feature key: %', p_feature_key;
  end if;

  insert into tenant_feature_overrides (tenant_id, feature_key, enabled, set_by, note, updated_at)
  values (p_tenant_id, p_feature_key, p_enabled, auth.uid(), p_note, now())
  on conflict (tenant_id, feature_key)
  do update set enabled = excluded.enabled, set_by = excluded.set_by, note = excluded.note, updated_at = now();

  perform reconcile_tenant_feature(p_tenant_id, p_feature_key, p_enabled);

  if exists (select 1 from profiles where user_id = auth.uid() and tenant_id = p_tenant_id) then
    perform append_audit_event(
      p_tenant_id, 'Platform admin', 'human',
      format('Feature "%s" set to %s for this tenant', p_feature_key, case when p_enabled then 'ON' else 'OFF' end),
      'config_change',
      jsonb_build_object('kind', 'tenant_feature_override_set', 'feature_key', p_feature_key,
        'enabled', p_enabled, 'set_by', auth.uid(), 'note', p_note)
    );
  end if;

  return jsonb_build_object('ok', true);
end;
$function$;

CREATE OR REPLACE FUNCTION public.set_tenant_ip_allowlist_enabled(p_tenant_id uuid, p_enabled boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;
  if not (
    is_platform_admin()
    or exists (
      select 1 from profiles p
      where p.user_id = auth.uid() and p.tenant_id = p_tenant_id
        and coalesce(p.is_active, true) = true
        and p.role in ('tenant_owner', 'tenant_admin')
    )
  ) then
    raise exception 'only workspace owners/admins can change the IP allowlist';
  end if;
  if p_enabled and not exists (select 1 from tenant_ip_allowlist_entries where tenant_id = p_tenant_id) then
    raise exception 'add at least one IP range before turning this on -- otherwise every sign-in would be blocked';
  end if;

  insert into tenant_ip_allowlists (tenant_id, enabled, updated_by)
  values (p_tenant_id, p_enabled, auth.uid())
  on conflict (tenant_id) do update set enabled = excluded.enabled, updated_at = now(), updated_by = excluded.updated_by;

  perform append_audit_event_internal(
    p_tenant_id, 'You', 'human',
    format('IP allowlist %s', case when p_enabled then 'enabled' else 'disabled' end),
    'config_change',
    jsonb_build_object('kind', 'ip_allowlist_toggled', 'enabled', p_enabled)
  );

  return jsonb_build_object('ok', true);
end;
$function$;

CREATE OR REPLACE FUNCTION public.set_tenant_llm_key(p_tenant_id uuid, p_provider_key text, p_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_existing uuid; v_secret uuid; v_name text;
BEGIN
  IF coalesce(trim(p_value), '') = '' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'A key is required.');
  END IF;
  IF p_provider_key !~ '^[A-Z0-9_]{3,60}$' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Unrecognised provider key name.');
  END IF;

  -- A tenant's own owner/admin may set their tenant's key. A platform admin may
  -- set it for any tenant. Service role for automation. Nobody else.
  IF auth.role() IS NOT NULL AND auth.role() <> 'service_role' THEN
    IF auth.uid() IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
    IF NOT (is_platform_admin()
            OR (EXISTS (SELECT 1 FROM profiles p
                         WHERE p.user_id = auth.uid() AND p.tenant_id = p_tenant_id)
                AND auth_has_tenant_role(ARRAY['tenant_owner', 'tenant_admin']))) THEN
      RAISE EXCEPTION 'not authorized to set this workspace''s model key';
    END IF;
  END IF;

  SELECT secret_id INTO v_existing FROM tenant_llm_credentials
   WHERE tenant_id = p_tenant_id AND provider_key = p_provider_key;

  IF v_existing IS NOT NULL THEN
    PERFORM vault.update_secret(v_existing, trim(p_value));
    UPDATE tenant_llm_credentials
       SET status = 'untested', last_verified_at = NULL, last_error = NULL, updated_at = now()
     WHERE tenant_id = p_tenant_id AND provider_key = p_provider_key;
  ELSE
    v_name := 'tenant_llm:' || p_tenant_id::text || ':' || p_provider_key;
    -- A vault secret can outlive the row that pointed at it — an aborted
    -- transaction leaves the secret behind, and vault.secrets has a unique index
    -- on name, so a naive create_secret would fail for ever afterwards. Adopt an
    -- existing secret of this name instead of colliding with it.
    SELECT id INTO v_secret FROM vault.secrets WHERE name = v_name;
    IF v_secret IS NOT NULL THEN
      PERFORM vault.update_secret(v_secret, trim(p_value));
    ELSE
      v_secret := vault.create_secret(trim(p_value), v_name, 'Set via set_tenant_llm_key');
    END IF;
    INSERT INTO tenant_llm_credentials (tenant_id, provider_key, secret_id, added_by)
    VALUES (p_tenant_id, p_provider_key, v_secret, auth.uid());
  END IF;

  RETURN jsonb_build_object('ok', true, 'provider_key', p_provider_key);
END $function$;

CREATE OR REPLACE FUNCTION public.set_tenant_llm_key_mode(p_tenant_id uuid, p_mode text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_prev text;
  v_name text;
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;
  -- The gate. Deliberately the SAME capability as set_tenant_plan: both decide
  -- what a customer is charged for.
  if not resolve_platform_capability(auth.uid(), 'tenants.manage') then
    raise exception 'only DreamTeam AI staff may change which account pays for a workspace';
  end if;
  if p_mode is null or p_mode not in ('platform', 'byo') then
    raise exception 'mode must be platform or byo';
  end if;

  select llm_key_mode, name into v_prev, v_name from tenants where id = p_tenant_id;
  if v_name is null then
    raise exception 'workspace not found';
  end if;

  if v_prev is not distinct from p_mode then
    return jsonb_build_object('ok', true, 'tenant_id', p_tenant_id, 'llm_key_mode', p_mode, 'changed', false);
  end if;

  update tenants set llm_key_mode = p_mode, updated_at = now() where id = p_tenant_id;

  perform append_audit_event(p_tenant_id, 'DreamTeam AI', 'platform',
    format('Billing for AI usage changed from "%s" to "%s". %s',
           v_prev, p_mode,
           case when p_mode = 'byo'
                then 'This workspace now pays its own provider account, and may set its own token budget.'
                else 'DreamTeam AI now pays for this workspace''s usage, and its token budget is set by its plan.' end),
    'config_change',
    jsonb_build_object('kind', 'llm_key_mode_changed', 'from', v_prev, 'to', p_mode));

  return jsonb_build_object('ok', true, 'tenant_id', p_tenant_id, 'llm_key_mode', p_mode, 'changed', true);
end;
$function$;

CREATE OR REPLACE FUNCTION public.set_tenant_monthly_budget(p_tenant_id uuid, p_budget integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_demo_tenant_id constant uuid := 'a0000000-0000-0000-0000-000000000001';
  v_max_self_serve_budget constant integer := 10000000; -- 100x the 100k default; revisit once real plan-based billing exists
  v_caller_tenant uuid;
  v_role text;
  v_is_active boolean;
  v_mode text;
  v_is_platform boolean := resolve_platform_capability(auth.uid(), 'tenants.manage');
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;
  if p_tenant_id = v_demo_tenant_id then
    raise exception 'the demo tenant''s budget cannot be changed';
  end if;
  if p_budget is null or p_budget < 0 then
    raise exception 'budget must be a non-negative number';
  end if;

  if not v_is_platform then
    select tenant_id, role, coalesce(is_active, true) into v_caller_tenant, v_role, v_is_active
    from profiles where user_id = auth.uid();

    if v_caller_tenant is distinct from p_tenant_id or v_role not in ('tenant_owner', 'tenant_admin') then
      raise exception 'only an owner or admin of this organization may change the token budget';
    end if;
    if not v_is_active then
      raise exception 'account is deactivated';
    end if;

    -- ⚠ WHOSE MONEY. This is the whole migration. Everything else in this
    -- function is unchanged from before.
    select llm_key_mode into v_mode from tenants where id = p_tenant_id;
    if coalesce(v_mode, 'platform') <> 'byo' then
      raise exception 'this workspace runs on DreamTeam AI''s provider account, so its token budget is set by your plan — connect your own provider key to control it yourself, or contact us to change it';
    end if;

    -- Self-serve (non-platform-admin) callers are capped. A platform
    -- admin (tenants.manage) can still set a higher budget by hand for
    -- a legitimate enterprise customer who genuinely needs more.
    if p_budget > v_max_self_serve_budget then
      raise exception 'requested budget exceeds the self-serve limit (%); contact DreamTeam AI to raise it', v_max_self_serve_budget;
    end if;
  end if;

  update tenants set monthly_token_budget = p_budget, updated_at = now() where id = p_tenant_id;

  return jsonb_build_object('ok', true, 'tenant_id', p_tenant_id, 'monthly_token_budget', p_budget);
end;
$function$;

CREATE OR REPLACE FUNCTION public.set_tenant_plan(p_tenant_id uuid, p_plan text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_demo_tenant_id constant uuid := 'a0000000-0000-0000-0000-000000000001';
  v_found boolean;
  v_new_budget integer;
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;
  if not resolve_platform_capability(auth.uid(), 'tenants.manage') then
    raise exception 'only a platform team member with tenant-management access may change a tenant''s plan';
  end if;
  if p_plan not in ('starter', 'growth', 'enterprise') then
    raise exception 'unrecognized plan: %', p_plan;
  end if;
  if p_tenant_id = v_demo_tenant_id then
    raise exception 'the demo tenant''s plan cannot be changed';
  end if;

  select true into v_found from tenants where id = p_tenant_id;
  if not found then
    raise exception 'tenant not found';
  end if;

  v_new_budget := case p_plan
    when 'starter' then 100000
    when 'growth' then 500000
    when 'enterprise' then 2000000
  end;

  update tenants set plan = p_plan, monthly_token_budget = v_new_budget, updated_at = now() where id = p_tenant_id;

  return jsonb_build_object('ok', true, 'tenant_id', p_tenant_id, 'plan', p_plan, 'monthly_token_budget', v_new_budget);
end;
$function$;

