CREATE OR REPLACE FUNCTION public.set_trust_ladder(p_policy_id uuid, p_ladder jsonb, p_display_name text DEFAULT NULL::text, p_criteria jsonb DEFAULT NULL::jsonb, p_clear_ladder boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tenant uuid := auth_tenant_id();
  v_pol trust_policies;
  v_uses_conf boolean;
  v_uses_amt boolean;
  v_levels int := NULL;
  v_clear boolean := false;
  v_k text; v_v jsonb; v_num numeric;
BEGIN
  IF v_tenant IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;

  SELECT * INTO v_pol FROM trust_policies WHERE id = p_policy_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'trust policy not found'; END IF;
  -- Same message as not-found: never confirm a foreign policy id exists.
  IF v_pol.tenant_id <> v_tenant AND NOT is_platform_admin() THEN
    RAISE EXCEPTION 'trust policy not found';
  END IF;

  IF v_pol.de_id IS NULL THEN
    IF NOT (is_platform_admin()
            OR auth_has_tenant_role(ARRAY['tenant_owner', 'tenant_admin'])) THEN
      RAISE EXCEPTION 'insufficient_permission: the workspace-wide ladder requires an owner or admin';
    END IF;
  ELSE
    IF NOT (is_platform_admin()
            OR auth_has_tenant_role(ARRAY['tenant_owner', 'tenant_admin', 'tenant_manager'])) THEN
      RAISE EXCEPTION 'insufficient_permission: customizing a trust ladder requires a manager';
    END IF;
    IF NOT can_access_de(v_pol.de_id) THEN
      RAISE EXCEPTION 'insufficient_permission: you are not assigned to this digital employee';
    END IF;
  END IF;

  -- Enforcement flags follow the capability key (see header: measured live).
  v_uses_conf := v_pol.action_category IN ('answer_dock', 'answer_widget');
  v_uses_amt  := NOT v_uses_conf;

  IF coalesce(p_clear_ladder, false) THEN
    -- Explicit reset: p_ladder is ignored entirely (see header — PostgREST
    -- cannot deliver an in-band jsonb 'null', so the flag is the only
    -- reliable clear path from the UI).
    v_clear := true;
  ELSIF p_ladder IS NOT NULL THEN
    IF jsonb_typeof(p_ladder) = 'null' THEN
      v_clear := true;  -- direct-SQL belt; unreachable via PostgREST
    ELSE
      v_levels := validate_trust_ladder(p_ladder, v_uses_conf, v_uses_amt,
                                        coalesce(v_pol.max_level, 3));
    END IF;
  END IF;

  IF p_criteria IS NOT NULL THEN
    IF jsonb_typeof(p_criteria) <> 'object' THEN
      RAISE EXCEPTION 'criteria must be an object';
    END IF;
    FOR v_k, v_v IN SELECT key, value FROM jsonb_each(p_criteria) LOOP
      IF v_k NOT IN ('window_days', 'min_eval_samples', 'min_human_samples',
                     'min_eval_pass_rate', 'max_guardrail_blocks', 'min_human_approval_rate') THEN
        RAISE EXCEPTION 'criteria field "%" is not part of the evidence contract', v_k;
      END IF;
      IF jsonb_typeof(v_v) <> 'number' THEN
        RAISE EXCEPTION 'criteria field "%" must be a number', v_k;
      END IF;
      v_num := (p_criteria ->> v_k)::numeric;
      IF v_k = 'window_days' AND (v_num <> trunc(v_num) OR v_num < 1 OR v_num > 365) THEN
        RAISE EXCEPTION 'window_days must be a whole number of days between 1 and 365';
      ELSIF v_k IN ('min_eval_samples', 'min_human_samples', 'max_guardrail_blocks')
            AND (v_num <> trunc(v_num) OR v_num < 0 OR v_num > 100000) THEN
        RAISE EXCEPTION '% must be a whole number of at least 0', v_k;
      ELSIF v_k IN ('min_eval_pass_rate', 'min_human_approval_rate')
            AND (v_num < 0 OR v_num > 1) THEN
        RAISE EXCEPTION '% is a fraction between 0 and 1', v_k;
      END IF;
    END LOOP;
  END IF;

  UPDATE trust_policies SET
    ladder       = CASE WHEN v_clear THEN NULL
                        WHEN p_ladder IS NULL THEN ladder
                        ELSE p_ladder END,
    display_name = coalesce(nullif(trim(coalesce(p_display_name, '')), ''), display_name),
    criteria     = coalesce(p_criteria, criteria),
    updated_at   = now()
  WHERE id = p_policy_id
  RETURNING * INTO v_pol;

  -- An already-EARNED level must keep meaning what the (new) ladder says:
  -- re-apply through the engine's own writer so the enforced dial row stays
  -- in step. Level 0 is never re-applied — writing an explicit disabled row
  -- where none exists would SHADOW a wider workspace row in the resolver's
  -- cascade and silently narrow behaviour.
  IF v_pol.current_level > 0 AND (v_clear OR v_levels IS NOT NULL) THEN
    PERFORM trust_apply_level(v_pol.tenant_id, v_pol.action_category,
                              v_pol.current_level, auth.uid(),
                              v_pol.source_category, v_pol.de_id);
  END IF;

  PERFORM append_audit_event(
    v_pol.tenant_id,
    coalesce((SELECT full_name FROM profiles WHERE user_id = auth.uid()), 'A manager'),
    'human',
    format('Customized the trust ladder for "%s"%s',
           coalesce(v_pol.display_name, v_pol.action_category),
           CASE WHEN v_clear THEN ' — reset to the built-in levels'
                WHEN v_levels IS NOT NULL THEN format(' — %s custom level(s)', v_levels)
                ELSE ' — settings only' END),
    'config_change',
    jsonb_build_object('kind', 'trust_ladder_set', 'policy_id', v_pol.id,
                       'de_id', v_pol.de_id, 'capability_key', v_pol.action_category,
                       'levels', v_levels, 'ladder_reset', v_clear,
                       'criteria_changed', p_criteria IS NOT NULL,
                       'display_name_changed', p_display_name IS NOT NULL,
                       'current_level', v_pol.current_level,
                       'changed_by', auth.uid()));

  RETURN to_jsonb(v_pol);
END $function$;

CREATE OR REPLACE FUNCTION public.set_widget_key_de(p_widget_key_id uuid, p_de_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tenant uuid; v_n int;
BEGIN
  SELECT tenant_id INTO v_tenant FROM widget_keys WHERE id = p_widget_key_id;
  IF v_tenant IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'key_not_found'); END IF;

  IF coalesce(auth.role(), '') <> 'service_role' AND NOT EXISTS (
    SELECT 1 FROM profiles p WHERE p.user_id = auth.uid() AND p.tenant_id = v_tenant
      AND (p.layer = 'platform' OR p.role IN ('tenant_owner', 'tenant_admin'))
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_authorized');
  END IF;

  IF p_de_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM digital_employees d WHERE d.id = p_de_id AND d.tenant_id = v_tenant
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'de_not_in_tenant');
  END IF;

  UPDATE widget_keys SET de_id = p_de_id WHERE id = p_widget_key_id;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  RETURN jsonb_build_object('ok', v_n > 0, 'de_id', p_de_id);
END $function$;

CREATE OR REPLACE FUNCTION public.set_workforce_team_member(p_team_id uuid, p_de_id uuid, p_fallback_rank integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tenant uuid;
  v_team workforce_teams;
  v_de_name text;
  v_holder text;
  v_actor text;
begin
  v_tenant := auth_tenant_id();
  if v_tenant is null then raise exception 'not a member of any tenant'; end if;
  if not auth_has_tenant_role(array['tenant_owner', 'tenant_admin']) then
    raise exception 'only workspace owners/admins can manage workforce teams';
  end if;

  select * into v_team from workforce_teams where id = p_team_id and tenant_id = v_tenant;
  if v_team.id is null then raise exception 'team not found in this workspace'; end if;

  select name into v_de_name from digital_employees
  where id = p_de_id and tenant_id = v_tenant and lifecycle_status not in ('retired', 'archived');
  if v_de_name is null then raise exception 'employee not found in this workspace (or retired)'; end if;

  select full_name into v_actor from profiles where user_id = auth.uid();

  if p_fallback_rank is null then
    delete from workforce_team_members where team_id = p_team_id and de_id = p_de_id;
    perform append_audit_event_internal(
      v_tenant, coalesce(v_actor, 'A workspace admin'), 'human',
      format('%s removed from workforce team "%s"', v_de_name, v_team.name),
      'config_change',
      jsonb_build_object('kind', 'workforce_team_member_removed', 'team_id', p_team_id, 'de_id', p_de_id)
    );
    return jsonb_build_object('ok', true, 'removed', true);
  end if;

  if p_fallback_rank < 1 then raise exception 'fallback rank must be 1 or higher (1 = primary responder)'; end if;

  -- Explicit rank-conflict message beats a raw unique-violation error.
  select de.name into v_holder
  from workforce_team_members m join digital_employees de on de.id = m.de_id
  where m.team_id = p_team_id and m.fallback_rank = p_fallback_rank and m.de_id <> p_de_id;
  if v_holder is not null then
    raise exception 'rank % is already held by % — move them first or pick another rank', p_fallback_rank, v_holder;
  end if;

  insert into workforce_team_members (tenant_id, team_id, de_id, fallback_rank)
  values (v_tenant, p_team_id, p_de_id, p_fallback_rank)
  on conflict (team_id, de_id) do update set fallback_rank = excluded.fallback_rank;

  perform append_audit_event_internal(
    v_tenant, coalesce(v_actor, 'A workspace admin'), 'human',
    format('%s set as %s on workforce team "%s"', v_de_name,
      case when p_fallback_rank = 1 then 'primary responder' else format('backup #%s', p_fallback_rank - 1) end,
      v_team.name),
    'config_change',
    jsonb_build_object('kind', 'workforce_team_member_set', 'team_id', p_team_id, 'de_id', p_de_id, 'fallback_rank', p_fallback_rank)
  );
  return jsonb_build_object('ok', true, 'fallback_rank', p_fallback_rank);
end;
$function$;

CREATE OR REPLACE FUNCTION public.settle_billable_outcomes()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_n integer;
begin
  with due as (
    select r.id,
      (exists (select 1 from billable_outcomes e where e.conversation_id = r.conversation_id and e.kind='escalation')
       or exists (select 1 from de_conversations c where c.id = r.conversation_id
                    and (c.csat_score = -1 or c.status = 'human_owned'))
       or exists (select 1 from de_messages m where m.conversation_id = r.conversation_id
                    and m.role = 'user' and m.created_at > r.occurred_at)   -- customer wrote back = not resolved
      ) as reversed
    from billable_outcomes r
    where r.kind = 'resolution' and r.status = 'pending' and r.settle_after <= now()
  )
  update billable_outcomes b set
    status           = case when d.reversed then 'unbilled' else 'confirmed' end,
    billable         = not d.reversed,
    unit_price_cents = case when d.reversed then 0 else b.unit_price_cents end,
    settled_at       = now()
  from due d where b.id = d.id;
  get diagnostics v_n = row_count;
  return v_n;
end $function$;

CREATE OR REPLACE FUNCTION public.settle_due_payment_promises()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE n_kept int; n_broken int; n_unver int;
BEGIN
  WITH due AS (
    SELECT p.id, p.promised_cents, p.balance_at_promise_cents, r.outstanding_cents
      FROM payment_promises p JOIN renewal_invoices r ON r.id = p.invoice_id
     WHERE p.status = 'open'
       AND current_date > p.promised_on + p.grace_days
       AND tenant_is_operational(p.tenant_id)
  ), judged AS (
    SELECT id,
      CASE
        -- No verified balance today: we cannot say. Saying "broken" here would
        -- escalate a customer over OUR missing data.
        WHEN outstanding_cents IS NULL OR balance_at_promise_cents IS NULL THEN 'unverifiable'
        WHEN (balance_at_promise_cents - outstanding_cents) >= promised_cents THEN 'kept'
        ELSE 'broken'
      END AS verdict,
      coalesce(balance_at_promise_cents - outstanding_cents, 0) AS moved
      FROM due
  )
  UPDATE payment_promises p SET status = j.verdict, settled_at = now(),
         settled_note = CASE j.verdict
           WHEN 'kept'   THEN format('Balance fell by %s, covering the %s promised.',
                                     money_text(j.moved), money_text(p.promised_cents))
           WHEN 'broken' THEN format('Promised %s by %s; the balance moved %s.',
                                     money_text(p.promised_cents), to_char(p.promised_on,'FMDD Mon'), money_text(j.moved))
           ELSE 'The balance on this invoice is not verified, so whether the promise was kept cannot be established.'
         END
    FROM judged j WHERE p.id = j.id;

  SELECT count(*) FILTER (WHERE status='kept'   AND settled_at > now() - interval '1 minute'),
         count(*) FILTER (WHERE status='broken' AND settled_at > now() - interval '1 minute'),
         count(*) FILTER (WHERE status='unverifiable' AND settled_at > now() - interval '1 minute')
    INTO n_kept, n_broken, n_unver FROM payment_promises;

  RETURN jsonb_build_object('ok', true, 'kept', n_kept, 'broken', n_broken, 'unverifiable', n_unver);
END $function$;

CREATE OR REPLACE FUNCTION public.snapshot_all_de_kpi_readings()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare d record; v_total int := 0; v_des int := 0;
begin
  for d in
    select id from digital_employees
     where coalesce(lifecycle_status, 'active') not in ('retired', 'archived')
       and tenant_is_operational(tenant_id)
  loop
    begin
      v_total := v_total + public.snapshot_de_kpi_readings(d.id);   -- per-DE isolation
      v_des := v_des + 1;
    exception when others then
      raise warning 'snapshot_de_kpi_readings(%) failed: %', d.id, sqlerrm;
    end;
  end loop;
  -- Retention: system snapshots are cheap to recompute; keep 180 days.
  delete from de_kpi_readings where source = 'system' and as_of < current_date - 180;
  return jsonb_build_object('des', v_des, 'written', v_total);
end $function$;

CREATE OR REPLACE FUNCTION public.snapshot_de_kpi_readings(p_de_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_tenant uuid; m record; v_csat numeric; v_vals jsonb;
  rec record; v_last numeric; v_written int := 0;
begin
  -- Cron-safe: resolves tenant from the DE; never calls auth.uid()/auth_tenant_id().
  select tenant_id into v_tenant from digital_employees where id = p_de_id;
  if v_tenant is null then return 0; end if;

  -- Platform conversation/perf arm — reproduced VERBATIM from get_de_kpi_status
  -- (mig 263:58-72). CSAT sample count is unused here (no fallback), so omitted.
  select * into m from get_de_performance_metrics(v_tenant, 13) where de_id = p_de_id;
  select round(100.0 * count(*) filter (where csat_score = 1) / nullif(count(*) filter (where csat_submitted_at is not null), 0), 1)
    into v_csat
  from de_conversations where tenant_id = v_tenant and de_id = p_de_id;

  v_vals := jsonb_strip_nulls(jsonb_build_object(
    'resolution_rate',        case when coalesce(m.total_decisions, 0) >= 1 then m.resolution_rate end,
    'avg_confidence',         case when coalesce(m.total_decisions, 0) >= 1 then m.avg_confidence end,
    'escalation_rate',        case when coalesce(m.total_decisions, 0) >= 1 then m.escalation_rate end,
    'error_rate',             case when coalesce(m.total_runs, 0) >= 1 then m.error_rate end,
    'csat_pct',               v_csat,
    'high_frustration_count', case when coalesce(m.total_decisions, 0) >= 1 then m.high_frustration_count::numeric end,
    'total_decisions',        coalesce(m.total_decisions, 0)::numeric
  ));

  -- Target set S = configured KPI targets ∪ active metric_threshold watcher keys
  -- for this DE. For each, resolve the PLATFORM value (computed v_vals, else the
  -- action arm from mig 263:85-100) — NEVER the manual fallback.
  for rec in
    with s as (
      select distinct mk from (
        select metric_key mk from de_kpis where de_id = p_de_id and metric_key is not null
        union
        select config->>'metric_key' from work_watchers
          where de_id = p_de_id and kind = 'metric_threshold' and active
            and config->>'metric_key' is not null
      ) u
    )
    select s.mk as metric_key,
           coalesce(
             (v_vals->>s.mk)::numeric,
             -- mig 501: the source guard must wrap the WHOLE subquery, not sit
             -- inside its WHERE. Without this wrapper a computed metric with no
             -- platform value resolves to 0 rather than NULL, and the snapshot
             -- PERSISTS that zero — which run_work_watchers then reads to open
             -- autonomous objectives against a number nobody measured.
             -- mig 757: one arm (mig 756). It carries mig 501's guard
             -- INTERNALLY — a non-'action' metric still returns NULL, never 0 —
             -- so that wrapper moved into the function rather than being lost.
             (select a.v from public.de_kpi_action_value(v_tenant, p_de_id, cat.source, cat.source_config) a)
           ) as val
    from s
    left join kpi_metric_catalog cat
      on cat.metric_key = s.mk and (cat.tenant_id is null or cat.tenant_id = v_tenant)
  loop
    if rec.val is null then continue; end if;                      -- fix #2: NOT NULL guard
    select value into v_last from de_kpi_readings
      where de_id = p_de_id and metric_key = rec.metric_key and source = 'system'
      order by as_of desc, created_at desc limit 1;
    if v_last is not distinct from rec.val then continue; end if;  -- fix #1: value-change only
    insert into de_kpi_readings (tenant_id, de_id, metric_key, value, as_of, recorded_by, source)
    values (v_tenant, p_de_id, rec.metric_key, rec.val, current_date, null, 'system')
    on conflict (de_id, metric_key, as_of) where source = 'system'  -- fix #2: partial-index predicate
      do update set value = excluded.value, created_at = now();
    v_written := v_written + 1;
  end loop;
  return v_written;
end $function$;

CREATE OR REPLACE FUNCTION public.sql_op(p text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT CASE p WHEN 'lt' THEN '<' WHEN 'lte' THEN '<=' WHEN 'gt' THEN '>'
               WHEN 'gte' THEN '>=' WHEN 'eq' THEN '=' WHEN 'neq' THEN '<>'
               ELSE '=' END $function$;

CREATE OR REPLACE FUNCTION public.sso_login_compliance(p_user_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_is_service boolean;
  v_caller     uuid;
  v_target     uuid;
  v_tenant     uuid;
  v_required   boolean := false;
  v_is_sso     boolean := false;
BEGIN
  v_is_service := COALESCE(auth.role(), '') = 'service_role';
  v_caller     := auth.uid();
  v_target     := COALESCE(p_user_id, v_caller);

  IF NOT v_is_service THEN
    IF v_caller IS NULL OR v_target IS DISTINCT FROM v_caller THEN
      RAISE EXCEPTION 'not authorized';
    END IF;
  END IF;
  IF v_target IS NULL THEN
    RAISE EXCEPTION 'not authorized';
  END IF;

  SELECT pr.tenant_id INTO v_tenant FROM public.profiles pr WHERE pr.user_id = v_target;
  SELECT COALESCE(u.is_sso_user, false) INTO v_is_sso FROM auth.users u WHERE u.id = v_target;

  IF v_tenant IS NOT NULL THEN
    SELECT COALESCE(sp.sso_required, false) INTO v_required
      FROM public.tenant_sso_policy sp WHERE sp.tenant_id = v_tenant;
  END IF;
  v_required := COALESCE(v_required, false);

  RETURN jsonb_build_object(
    'tenant_id',    v_tenant,
    'sso_required', v_required,
    'is_sso_user',  COALESCE(v_is_sso, false),
    'compliant',    (NOT v_required) OR COALESCE(v_is_sso, false),
    -- Surfaced so the UI can say WHY it is ejecting a session instead of
    -- showing a bare "signed out".
    'reason',       CASE WHEN NOT v_required THEN 'sso_not_required'
                         WHEN COALESCE(v_is_sso, false) THEN 'sso_session'
                         ELSE 'password_session_on_sso_required_workspace' END);
END $function$;

CREATE OR REPLACE FUNCTION public.stale_humanize_interval(p_span interval)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select case
    when extract(epoch from p_span) >= 86400 then
      round(extract(epoch from p_span) / 86400.0, 1)::text || ' day' || case when round(extract(epoch from p_span) / 86400.0, 1) = 1 then '' else 's' end
    when extract(epoch from p_span) >= 3600 then
      round(extract(epoch from p_span) / 3600.0, 1)::text || ' hour' || case when round(extract(epoch from p_span) / 3600.0, 1) = 1 then '' else 's' end
    else
      greatest(1, round(extract(epoch from p_span) / 60.0))::text || ' minute' ||
        case when greatest(1, round(extract(epoch from p_span) / 60.0)) = 1 then '' else 's' end
  end;
$function$;

CREATE OR REPLACE FUNCTION public.stale_upsert_escalation(p_tenant_id uuid, p_target_kind text, p_target_id uuid, p_tier text, p_task_title text, p_task_detail text, p_related_table text, p_related_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_task_id uuid;
  v_esc_id  uuid;
begin
  -- Mig 545: fix at the primitive, not only at the caller. A suspended
  -- workspace never gains new escalations regardless of who asks.
  if not tenant_is_operational(p_tenant_id) then
    return null;
  end if;

  -- Cooldown/dedup: an OPEN escalation for this exact
  -- (tenant, target_kind, target_id, tier) means do nothing — this is what
  -- stops the same stale item re-firing every 5-minute tick.
  if exists (
    select 1 from staleness_escalations
    where tenant_id = p_tenant_id and target_kind = p_target_kind
      and target_id = p_target_id and tier = p_tier and resolved_at is null
  ) then
    return null;
  end if;

  if p_related_table = 'human_tasks' then
    -- The stale thing is already IN the queue. Creating a second row about it
    -- is the amplifier this migration exists to remove. Point the escalation
    -- at the real task so the badge lands where the decision is owed.
    v_task_id := p_related_id;
  else
    insert into human_tasks (tenant_id, type, title, detail, source, related_table, related_id, status)
    values (p_tenant_id, 'escalation', p_task_title, p_task_detail, 'system', p_related_table, p_related_id, 'pending')
    returning id into v_task_id;
  end if;

  insert into staleness_escalations (tenant_id, target_kind, target_id, tier, human_task_id)
  values (p_tenant_id, p_target_kind, p_target_id, p_tier, v_task_id)
  returning id into v_esc_id;

  perform append_audit_event_internal(
    p_tenant_id, 'System', 'system',
    format('Staleness watchdog: %s escalation — %s', p_tier, p_task_title),
    'escalated',
    jsonb_build_object('kind', 'staleness_escalation', 'target_kind', p_target_kind,
                       'target_id', p_target_id, 'tier', p_tier, 'human_task_id', v_task_id,
                       'raised_new_task', p_related_table <> 'human_tasks')
  );

  return v_esc_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.stamp_gap_cluster_on_apply()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.status = 'applied' AND NEW.status IS DISTINCT FROM OLD.status
     AND NEW.gap_cluster_id IS NOT NULL THEN
    UPDATE knowledge_gap_clusters
       SET fix_applied_at = coalesce(fix_applied_at, now()), updated_at = now()
     WHERE id = NEW.gap_cluster_id AND tenant_id = NEW.tenant_id;
  END IF;
  RETURN NEW;
END $function$;

CREATE OR REPLACE FUNCTION public.stamp_objective_mission_from_watcher()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE v_mid uuid; v_wid text;
BEGIN
  IF NEW.mission_id IS NULL AND jsonb_typeof(NEW.plan) = 'object' THEN
    v_wid := NEW.plan->>'watcher_id';
    IF v_wid ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      SELECT mission_id INTO v_mid FROM work_watchers
        WHERE id = v_wid::uuid AND tenant_id = NEW.tenant_id;
      IF v_mid IS NOT NULL THEN NEW.mission_id := v_mid; END IF;
    END IF;
  END IF;
  RETURN NEW;
END $function$;

CREATE OR REPLACE FUNCTION public.start_discovery_session(p_tenant_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_session_id uuid;
  v_coverage   jsonb;
begin
  if p_tenant_id is null then
    raise exception 'start_discovery_session requires a tenant';
  end if;
  if not exists (select 1 from public.tenants where id = p_tenant_id) then
    raise exception 'unknown tenant: %', p_tenant_id;
  end if;

  select coalesce(
           jsonb_object_agg(d.key, jsonb_build_object('state', 'not_heard', 'evidence', null)),
           '{}'::jsonb
         )
    into v_coverage
    from public.discovery_dimensions d
   where d.active;

  insert into public.discovery_sessions (tenant_id, status, coverage, created_by)
  values (p_tenant_id, 'running', v_coverage, auth.uid())
  returning id into v_session_id;

  return v_session_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.start_platform_remote_access(p_tenant_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_session uuid := gen_random_uuid();
  v_operator_name text;
  v_tenant tenants;
begin
  if not resolve_platform_capability(auth.uid(), 'remote_access.use') then
    raise exception 'only a platform team member with remote access may start a remote access session';
  end if;

  if exists (select 1 from auth.mfa_factors where user_id = auth.uid() and status = 'verified') then
    if coalesce(auth.jwt() ->> 'aal', 'aal1') <> 'aal2' then
      raise exception 'Please verify your two-factor authentication code to use Remote Access.';
    end if;
  end if;

  select * into v_tenant from tenants where id = p_tenant_id;
  if not found then
    raise exception 'tenant not found';
  end if;

  select full_name into v_operator_name from profiles where user_id = auth.uid();

  insert into platform_access_events (tenant_id, operator_user_id, operator_name, event, session_key, detail)
  values (p_tenant_id, auth.uid(), coalesce(v_operator_name, 'Platform admin'), 'start', v_session,
    jsonb_build_object('tenant_name', v_tenant.name));

  return jsonb_build_object('ok', true, 'session_key', v_session, 'tenant_id', p_tenant_id, 'tenant_name', v_tenant.name);
end;
$function$;

CREATE OR REPLACE FUNCTION public.starter_onboarding_template()
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select jsonb_build_object(
    'description',
    '16-step implementation checklist: kickoff (sales handover, ownership, discovery) '
    '→ data → config → validation → go-live → support/success handoff. Sign-off gates '
    'on discovery, settings, leave rules, UAT, go-live, and the handover.',
    'items',
    $items$[
      {"key":"sales_handover","label":"Sales handover received","phase":"kickoff","owner_type":"human","requires_signoff":false,"description":"The deal team hands over what was actually sold: scope, commitments, promised dates, pricing, and the customer contacts. Delivery starts from what was promised, not from a guess."},
      {"key":"account_owner_assigned","label":"Internal account owner assigned","phase":"kickoff","owner_type":"human","requires_signoff":false,"description":"Name the person who owns this customer internally — the day-to-day contact and the executive sponsor. Nothing downstream has an owner until this does."},
      {"key":"kickoff_call","label":"Kickoff call held","phase":"kickoff","owner_type":"human","requires_signoff":false,"description":"Intro call: goals, timeline, points of contact."},
      {"key":"discovery_requirements","label":"Discovery — customer requirements documented","phase":"kickoff","owner_type":"either","requires_signoff":true,"description":"Employee count, locations, leave rules, billing preferences, and anything custom — written down against this account. Configuration must never assume defaults or copy another customer's settings, so this is signed off before any of it starts."},
      {"key":"onboarding_plan_agreed","label":"Onboarding plan and check-in cadence agreed","phase":"kickoff","owner_type":"human","requires_signoff":false,"description":"Milestones, target go-live, and how often we report progress to the customer. This is the one-off agreement; ongoing progress is computed from this checklist, not ticked off here."},
      {"key":"data_export_received","label":"Data export received from customer","phase":"data","owner_type":"either","requires_signoff":false,"description":"Customer sends their employee/location export (CSV or spreadsheet)."},
      {"key":"employees_imported","label":"Employees imported","phase":"data","owner_type":"de","requires_signoff":false,"description":"Employee records loaded and normalized in the platform."},
      {"key":"locations_configured","label":"Locations configured","phase":"config","owner_type":"de","requires_signoff":false,"description":"Sites, time zones, and operating hours set up."},
      {"key":"settings_review","label":"Account settings reviewed","phase":"config","owner_type":"human","requires_signoff":true,"description":"Human sign-off on core account configuration."},
      {"key":"leave_rules_configured","label":"Leave rules configured","phase":"config","owner_type":"either","requires_signoff":true,"description":"Accrual, carryover, and approval chains — needs human sign-off."},
      {"key":"test_scenario_run","label":"Test scenario run","phase":"validation","owner_type":"de","requires_signoff":false,"description":"End-to-end test with sample data."},
      {"key":"uat_approved","label":"UAT approved by customer","phase":"validation","owner_type":"human","requires_signoff":true,"description":"Customer confirms acceptance testing passed."},
      {"key":"training_session","label":"Training session delivered","phase":"golive","owner_type":"human","requires_signoff":false,"description":"Admin + end-user training completed."},
      {"key":"go_live","label":"Go-live","phase":"golive","owner_type":"human","requires_signoff":true,"description":"Production cutover — final human sign-off."},
      {"key":"post_golive_checkin","label":"Post-go-live check-in with the customer","phase":"handoff","owner_type":"either","requires_signoff":false,"description":"First check-in after cutover: confirm the customer is actually using it, catch anything that broke in production, and log what support needs to know."},
      {"key":"support_handoff","label":"Support and success handover","phase":"handoff","owner_type":"human","requires_signoff":true,"description":"Brief the support and success owners on the configuration, the quirks, and the open risks, and transfer day-to-day ownership. Onboarding is finished when someone else owns the customer, not when the system goes live."}
    ]$items$::jsonb
  );
$function$;

CREATE OR REPLACE FUNCTION public.submit_csat(p_conversation_id uuid, p_tenant_id uuid, p_score integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if p_score not in (1, -1) then
    raise exception 'score must be 1 or -1';
  end if;

  update de_conversations
    set csat_score = p_score, csat_submitted_at = now()
    where id = p_conversation_id and tenant_id = p_tenant_id;

  if not found then
    raise exception 'conversation not found for this tenant';
  end if;

  return jsonb_build_object('ok', true);
end;
$function$;

CREATE OR REPLACE FUNCTION public.submit_draft_for_review(p_de_id uuid, p_conversation_id uuid, p_user_question text, p_draft_content text, p_confidence numeric DEFAULT NULL::numeric, p_sources jsonb DEFAULT '[]'::jsonb, p_review_timeout_minutes integer DEFAULT 30)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_draft_id UUID;
  v_tenant_id UUID;
BEGIN
  -- The employee decides the workspace. A draft cannot belong anywhere else.
  SELECT tenant_id INTO v_tenant_id FROM digital_employees WHERE id = p_de_id;
  IF v_tenant_id IS NULL THEN
    RAISE EXCEPTION 'de_not_found: no such employee, so no workspace to file the draft under';
  END IF;
  -- SECURITY DEFINER + a caller-supplied id: without this, any signed-in user
  -- could file a draft against another workspace's employee.
  PERFORM public._assert_caller_tenant(v_tenant_id);

  INSERT INTO draft_responses (
    tenant_id, de_id, conversation_id, user_question,
    draft_content, confidence, sources, expires_at
  ) VALUES (
    v_tenant_id, p_de_id, p_conversation_id, p_user_question,
    p_draft_content, p_confidence, COALESCE(p_sources, '[]'::jsonb),
    now() + (p_review_timeout_minutes || ' minutes')::interval
  )
  RETURNING draft_id INTO v_draft_id;

  RETURN json_build_object(
    'draft_id', v_draft_id,
    'de_id', p_de_id,
    'conversation_id', p_conversation_id,
    'user_question', p_user_question,
    'draft_content', p_draft_content,
    'confidence', p_confidence,
    'sources', COALESCE(p_sources, '[]'::jsonb),
    'created_at', now()::text,
    'expires_at', (now() + (p_review_timeout_minutes || ' minutes')::interval)::text
  );
END;
$function$;

CREATE OR REPLACE FUNCTION public.submit_evidence_feedback(p_evidence_run_id uuid, p_verdict text, p_notes text DEFAULT ''::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user           uuid := auth.uid();
  v_tenant         uuid;
  v_caller_tenant  uuid;
  v_is_active      boolean;
  v_run            record;
  v_feedback_id    uuid;
  v_revision_id    uuid;
  v_task_id        uuid;
  v_source_doc_id  uuid;
  v_current_title  text;
  v_current_body   text;
  v_gap_lines      text := '';
  v_step           jsonb;
  v_citation       jsonb;
  v_proposed_title text;
  v_proposed_body  text;
  v_reviewer_name  text;
begin
  if p_verdict not in ('accurate', 'needs_improvement', 'inaccurate') then
    return jsonb_build_object('ok', false, 'error', 'bad_verdict');
  end if;

  select * into v_run from evidence_runs where id = p_evidence_run_id;
  if v_run.id is null then
    return jsonb_build_object('ok', false, 'error', 'evidence_run_not_found');
  end if;
  v_tenant := v_run.tenant_id;

  -- Membership guard (JWT path); a genuine service_role connection is
  -- also trusted (same test append_audit_event / set_doc_scope use).
  if v_user is not null then
    select tenant_id, coalesce(is_active, true) into v_caller_tenant, v_is_active from profiles where user_id = v_user;
    if v_caller_tenant is null or v_caller_tenant <> v_tenant then
      return jsonb_build_object('ok', false, 'error', 'not_tenant_member');
    end if;
    if not v_is_active then
      return jsonb_build_object('ok', false, 'error', 'not_tenant_member');
    end if;
  elsif coalesce(auth.role(), '') <> 'service_role' then
    return jsonb_build_object('ok', false, 'error', 'not_tenant_member');
  end if;

  select full_name into v_reviewer_name from profiles where user_id = v_user;
  v_reviewer_name := coalesce(v_reviewer_name, 'A reviewer');

  -- DE scoping (mig 385/424). NULL-TOLERANT, and here the null case is the
  -- MAJORITY: 149 of 203 live evidence runs carry no de_id. The plain form
  -- would refuse feedback on ~73% of runs for a scoped user while the
  -- readers still show them. Exact negation of the mig-386 predicate.
  -- The subject is intentionally NOT tested: the run is the work of
  -- de_id, and being consulted does not transfer ownership of the verdict.
  if v_run.de_id is not null and not public.can_access_de(v_run.de_id) then
    return jsonb_build_object('ok', false, 'error', 'not_responsible_for_de');
  end if;
  insert into evidence_feedback (tenant_id, evidence_run_id, reviewer_user_id, verdict, notes)
  values (v_tenant, p_evidence_run_id, v_user, p_verdict, coalesce(p_notes, ''))
  returning id into v_feedback_id;

  perform append_audit_event(
    v_tenant, v_reviewer_name, case when v_user is null then 'system' else 'human' end,
    v_reviewer_name || ' marked evidence run evidence as "' || p_verdict || '"'
      || case when coalesce(p_notes, '') <> '' then ' — "' || p_notes || '"' else '' end,
    'evidence_step',
    jsonb_build_object('kind', 'evidence_feedback_submitted', 'evidence_run_id', p_evidence_run_id,
      'feedback_id', v_feedback_id, 'verdict', p_verdict, 'notes', coalesce(p_notes, ''))
  );

  if p_verdict = 'accurate' then
    return jsonb_build_object('ok', true, 'feedback_id', v_feedback_id, 'revision_request_id', null, 'task_id', null);
  end if;

  -- ── Build the template-composed proposed revision ──
  -- Try to find an existing knowledge doc this evidence run cited, so
  -- the revision proposes an edit rather than always a fresh doc.
  select (c->>'ref')::uuid into v_source_doc_id
  from jsonb_array_elements(v_run.steps) s,
       jsonb_array_elements(s->'citations') c
  where s->>'kind' = 'knowledge_search' and c->>'system' = 'DreamTeam knowledge'
  limit 1;

  if v_source_doc_id is not null then
    select title, content into v_current_title, v_current_body
      from knowledge_docs where id = v_source_doc_id and tenant_id = v_tenant and is_current;
  end if;

  -- Gap lines: every non-"ok" or human-flagged step, plain-language.
  for v_step in select * from jsonb_array_elements(v_run.steps) loop
    if (v_step->>'outcome') in ('failed', 'skipped_not_connected', 'denied_no_access') then
      v_gap_lines := v_gap_lines || '- ' || coalesce(v_step->>'summary', v_step->>'kind') || E'\n';
    end if;
  end loop;

  v_proposed_title := coalesce(v_current_title, 'Follow-up: ' || left(v_run.inquiry, 80));
  v_proposed_body := coalesce(v_current_body, '') || E'\n\n'
    || '## Reviewer feedback (' || p_verdict || ')' || E'\n'
    || coalesce(nullif(p_notes, ''), '(no note provided)') || E'\n\n'
    || '## Evidence gaps noted at review time' || E'\n'
    || case when v_gap_lines = '' then '(no gaps recorded in the evidence trail)' || E'\n' else v_gap_lines end
    || E'\n## Source inquiry' || E'\n' || v_run.inquiry;

  insert into knowledge_revision_requests (
    tenant_id, source_doc_id, evidence_run_id, feedback_id,
    proposed_title, proposed_body_md, status, created_by
  ) values (
    v_tenant, v_source_doc_id, p_evidence_run_id, v_feedback_id,
    v_proposed_title, v_proposed_body, 'pending_approval', v_user
  ) returning id into v_revision_id;

  insert into human_tasks (
    tenant_id, type, title, detail, source, related_table, related_id, status
  ) values (
    v_tenant, 'knowledge_revision',
    'Review proposed knowledge update: ' || v_proposed_title,
    'Evidence run flagged "' || p_verdict || '" — a knowledge revision has been drafted for review.',
    'system', 'knowledge_revision_requests', v_revision_id, 'pending'
  ) returning id into v_task_id;

  perform append_audit_event(
    v_tenant, v_reviewer_name, case when v_user is null then 'system' else 'human' end,
    'Knowledge revision proposed from evidence feedback — "' || v_proposed_title || '"',
    'knowledge_revision',
    jsonb_build_object('kind', 'knowledge_revision_requested', 'revision_request_id', v_revision_id,
      'evidence_run_id', p_evidence_run_id, 'feedback_id', v_feedback_id, 'task_id', v_task_id,
      'source_doc_id', v_source_doc_id)
  );

  return jsonb_build_object('ok', true, 'feedback_id', v_feedback_id,
    'revision_request_id', v_revision_id, 'task_id', v_task_id);
end;
$function$;

CREATE OR REPLACE FUNCTION public.suggest_de_amendments(p_de_id uuid, p_metric_type text DEFAULT 'csat'::text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_tenant_id UUID;
  v_de_name TEXT;
  v_current_csat NUMERIC;
  v_escalation_rate NUMERIC;
  v_suggestion TEXT;
  v_confidence_score NUMERIC;
BEGIN
  SELECT tenant_id, name INTO v_tenant_id, v_de_name FROM digital_employees WHERE id = p_de_id;
  IF v_tenant_id IS NULL THEN RAISE EXCEPTION 'DE not found'; END IF;
  IF NOT (v_tenant_id = auth_tenant_id() AND auth_has_tenant_role(array['tenant_owner', 'tenant_admin', 'tenant_manager'])) THEN RAISE EXCEPTION 'Unauthorized'; END IF;

  SELECT COALESCE(AVG(score), 0) INTO v_current_csat FROM csat_surveys WHERE de_id = p_de_id AND created_at > now() - '30 days'::interval;
  SELECT COALESCE(COUNT(*)::NUMERIC / NULLIF((SELECT COUNT(*) FROM action_executions WHERE de_id = p_de_id AND created_at > now() - '30 days'::interval), 0) * 100, 0) INTO v_escalation_rate FROM action_executions WHERE de_id = p_de_id AND status = 'escalated' AND created_at > now() - '30 days'::interval;

  v_confidence_score := 0.7;
  IF p_metric_type = 'csat' AND v_current_csat < 80 THEN
    v_suggestion := 'CSAT ' || ROUND(v_current_csat, 1) || '%. Suggested: increase empathy.';
    v_confidence_score := 0.75;
  ELSIF p_metric_type = 'escalation' AND v_escalation_rate > 15 THEN
    v_suggestion := 'Escalation ' || ROUND(v_escalation_rate, 1) || '% (goal <5%). Suggested: expand actions.';
    v_confidence_score := 0.80;
  ELSE
    v_suggestion := 'DE performing well.';
    v_confidence_score := 0.90;
  END IF;

  RETURN json_build_object('de_id', p_de_id, 'de_name', v_de_name, 'suggestion', v_suggestion, 'metric_type', p_metric_type, 'current_csat', ROUND(v_current_csat, 1), 'current_escalation_rate', ROUND(v_escalation_rate, 1), 'confidence_score', v_confidence_score, 'recommendation', CASE WHEN v_confidence_score >= 0.75 THEN 'HIGH' WHEN v_confidence_score >= 0.5 THEN 'MEDIUM' ELSE 'LOW' END, 'generated_at', now());
END;
$function$;

CREATE OR REPLACE FUNCTION public.sync_amendment_decision()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if NEW.related_table = 'playbook_amendments' and NEW.status in ('approved','rejected')
     and OLD.status is distinct from NEW.status then
    begin
      if NEW.status = 'approved' then
        perform public.apply_playbook_amendment(NEW.related_id);
      else
        perform public.reject_playbook_amendment(NEW.related_id);
      end if;
    exception when others then
      -- never let a failed apply roll back the human's decision
      raise warning 'sync_amendment_decision: % for amendment %: %', NEW.status, NEW.related_id, SQLERRM;
    end;
  end if;
  return NEW;
end; $function$;

CREATE OR REPLACE FUNCTION public.sync_colleague_consultation_grants()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.lifecycle_status not in ('active','published','improving') then
    return new;
  end if;

  -- The (re)activated employee may consult every working colleague…
  insert into de_consultation_grants (tenant_id, requester_de_id, target_de_id, category, active)
  select new.tenant_id, new.id, d.id, 'other', true
  from digital_employees d
  where d.tenant_id = new.tenant_id and d.id <> new.id
    and d.lifecycle_status in ('active','published','improving')
  on conflict (tenant_id, requester_de_id, target_de_id, category) do nothing;

  -- …and every working colleague may consult them.
  insert into de_consultation_grants (tenant_id, requester_de_id, target_de_id, category, active)
  select new.tenant_id, d.id, new.id, 'other', true
  from digital_employees d
  where d.tenant_id = new.tenant_id and d.id <> new.id
    and d.lifecycle_status in ('active','published','improving')
  on conflict (tenant_id, requester_de_id, target_de_id, category) do nothing;

  return new;
end; $function$;

CREATE OR REPLACE FUNCTION public.sync_computer_use_approval()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if NEW.related_table = 'computer_use_tasks' and NEW.status in ('approved', 'rejected')
     and OLD.status is distinct from NEW.status then
    update computer_use_tasks
       set status = case when NEW.status = 'approved' then 'approved' else 'rejected' end,
           updated_at = now()
     where id = NEW.related_id and status = 'pending_approval';
  end if;
  return NEW;
end;
$function$;

CREATE OR REPLACE FUNCTION public.sync_conversation_draft_decision()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_channel text;
  v_msg     uuid;
  v_after   text;
begin
  if NEW.related_table is distinct from 'de_conversations' then return NEW; end if;
  if NEW.related_id is null                                then return NEW; end if;
  -- Reject sends nothing. Said once, here, so it cannot drift.
  if NEW.status <> 'approved'                              then return NEW; end if;
  if OLD.status is not distinct from NEW.status            then return NEW; end if;

  begin
    select channel into v_channel
      from de_conversations
     where id = NEW.related_id and tenant_id = NEW.tenant_id;
    if v_channel is null then return NEW; end if;

    -- ALLOW-LIST. Only channels where the customer reads de_messages directly.
    if v_channel not in ('widget', 'hosted', 'portal', 'dock', 'exam') then
      raise warning 'sync_conversation_draft_decision: channel % is carrier-delivered; the draft stays with the outbound path (task %)',
        v_channel, NEW.id;
      return NEW;
    end if;

    select id into v_msg
      from de_messages
     where conversation_id = NEW.related_id
       and tenant_id       = NEW.tenant_id
       and delivery        = 'draft_pending'
     order by created_at asc
     limit 1;
    if v_msg is null then return NEW; end if;

    -- Approve-with-edits: the CORRECTED text is what the customer must get.
    -- Same rule as approve_draft_reply's p_edited_content, so the two paths
    -- cannot diverge on what "approved" published.
    v_after := nullif(btrim(coalesce(NEW.decision_edit->>'after', '')), '');

    update de_messages
       set delivery  = 'sent',
           escalated = false,
           content   = coalesce(v_after, content)
     where id = v_msg and delivery = 'draft_pending';

    -- Mirrors approve_draft_reply exactly: approving is taking the thread.
    update de_conversations
       set owner_user_id   = coalesce(owner_user_id, NEW.decided_by),
           status          = 'human_owned',
           last_message_at = now()
     where id = NEW.related_id;

  exception when others then
    -- Never roll back the human's decision. The client re-reads the message
    -- row and will say the reply did NOT go out — see the header.
    raise warning 'sync_conversation_draft_decision failed for task %: %', NEW.id, sqlerrm;
  end;

  return NEW;
end;
$function$;

CREATE OR REPLACE FUNCTION public.sync_de_department()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  -- Same shape as sync_profile_department (mig 599), including the lesson that
  -- cost that migration a revision: `BEFORE INSERT OR UPDATE OF col` still
  -- fires on EVERY insert, so a new employee arriving with a department NAME
  -- and no unit must be RESOLVED, not blanked.
  if tg_op = 'INSERT'
     and new.org_unit_id is null
     and coalesce(btrim(new.department), '') <> '' then
    select u.id into new.org_unit_id
    from org_units u
    where u.tenant_id = new.tenant_id
      and u.kind in ('department', 'team')
      and lower(btrim(u.name)) = lower(btrim(new.department))
      and u.is_active
    limit 1;
  end if;

  if new.org_unit_id is not null then
    select u.name into new.department from org_units u where u.id = new.org_unit_id;
  elsif tg_op = 'UPDATE' then
    new.department := '';
  end if;

  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.sync_de_lifecycle_auto_internal()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_row record;
  v_count integer := 0;
begin
  for v_row in
    select de.id, de.tenant_id, de.name from digital_employees de
    where de.lifecycle_status = 'assigned'
      and tenant_is_operational(de.tenant_id)
      and exists (select 1 from evidence_runs er where er.tenant_id = de.tenant_id and er.de_id = de.id)
  loop
    update digital_employees set lifecycle_status = 'active', updated_at = now() where id = v_row.id;
    insert into de_lifecycle_events (tenant_id, de_id, from_stage, to_stage, actor_label, note)
    values (v_row.tenant_id, v_row.id, 'assigned', 'active', 'system', 'First live execution observed — activated automatically.');
    v_count := v_count + 1;
  end loop;
  return jsonb_build_object('activated', v_count);
end;
$function$;

CREATE OR REPLACE FUNCTION public.sync_de_lifecycle_from_development(p_de_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_de digital_employees;
  v_open_count integer;
begin
  select * into v_de from digital_employees where id = p_de_id;
  if v_de.id is null then return; end if;

  select count(*) into v_open_count from de_development_items
  where de_id = p_de_id and status in ('proposed', 'in_progress');

  if v_open_count > 0 and v_de.lifecycle_status = 'active' then
    update digital_employees set lifecycle_status = 'improving', updated_at = now() where id = p_de_id;
  elsif v_open_count = 0 and v_de.lifecycle_status = 'improving' then
    update digital_employees set lifecycle_status = 'active', updated_at = now() where id = p_de_id;
  end if;
end;
$function$;

CREATE OR REPLACE FUNCTION public.sync_de_task_from_objective()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.status IS DISTINCT FROM OLD.status
     AND NEW.entity_kind = 'de_task'
     AND NEW.status IN ('achieved','blocked') THEN
    UPDATE de_task_requests
       SET status       = CASE WHEN NEW.status = 'achieved' THEN 'completed' ELSE 'failed' END,
           completed_at = coalesce(completed_at, now()),
           responded_at = coalesce(responded_at, now())
     WHERE objective_id = NEW.id
       AND status IN ('requested','accepted','in_progress');
  END IF;
  RETURN NEW;
END; $function$;

CREATE OR REPLACE FUNCTION public.sync_de_work_escalation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_disposition text;
begin
  if new.related_table is distinct from 'de_work_items' then return new; end if;
  if new.status not in ('approved','rejected') then return new; end if;
  if old.status is not distinct from new.status then return new; end if;

  -- An explicit disposition wins. Otherwise derive one — a bare approve means
  -- "yes, proceed"; a bare reject means "no, stop this work", which is a real
  -- outcome and must be recorded as such rather than evaporating.
  v_disposition := coalesce(new.disposition,
    case when new.status = 'approved' then 'answered' else 'cancelled' end);

  -- House pattern (mirrors the five existing status-sync triggers): a failed
  -- side effect must never roll back the human's decision.
  begin
    perform resume_de_work_from_decision(new.id, v_disposition,
      coalesce(nullif(btrim(coalesce(new.decision_note, '')), ''), new.handoff_summary));
  exception when others then
    raise warning 'sync_de_work_escalation failed for task %: %', new.id, sqlerrm;
  end;

  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.sync_entity_amendment_decision()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if NEW.related_table = 'workforce_entity_amendments' and NEW.status in ('approved','rejected')
     and OLD.status is distinct from NEW.status then
    begin
      if NEW.status = 'approved' then perform public.apply_entity_amendment(NEW.related_id);
      else perform public.reject_entity_amendment(NEW.related_id); end if;
    exception when others then
      raise warning 'sync_entity_amendment_decision: % for %: %', NEW.status, NEW.related_id, SQLERRM;
    end;
  end if;
  return NEW;
end; $function$;

CREATE OR REPLACE FUNCTION public.sync_improvement_decision()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_after  text;
  v_before text;
  v_de     uuid;
begin
  if NEW.related_table = 'de_improvements' and NEW.status in ('approved', 'rejected')
     and OLD.status is distinct from NEW.status then

    -- ── 1. Apply the approver's correction BEFORE publishing ──────────────
    -- Its own block: a failure here must not stop the publish, and a failure
    -- in the publish below must not roll back the training pair.
    if NEW.status = 'approved' and NEW.decision_edit is not null then
      begin
        v_after := nullif(btrim(NEW.decision_edit->>'after'), '');

        select proposed_content, de_id into v_before, v_de
          from de_improvements where id = NEW.related_id;

        -- Only a real change counts. Equal text is not a training signal and
        -- would violate de_learning_edits_actually_changed_check.
        if v_after is not null and v_before is not null
           and btrim(v_before) <> btrim(v_after) then

          -- THIS is what makes the edit real: apply_improvement publishes
          -- proposed_content, so the corrected text is what reaches the
          -- knowledge base.
          update de_improvements
             set proposed_content = v_after, updated_at = now()
           where id = NEW.related_id;

          insert into de_learning_edits
            (tenant_id, de_id, source_kind, source_id,
             before_text, after_text, reason_code, note, edited_by)
          values
            (NEW.tenant_id, v_de, 'human_task', NEW.id,
             v_before, v_after, NEW.decision_reason_code, NEW.decision_note,
             NEW.decided_by);
        end if;
      exception when others then
        raise warning 'sync_improvement_decision: edit capture failed for task %: %', NEW.id, SQLERRM;
      end;
    end if;

    -- ── 2. Publish or reject — unchanged behaviour ────────────────────────
    begin
      if NEW.status = 'approved' then
        perform public.apply_improvement(NEW.related_id);
      else
        perform public.reject_improvement(NEW.related_id);
      end if;
    exception when others then
      -- Never roll back the human's decision; leave the improvement in
      -- review_pending where it is visibly stuck rather than silently lost.
      raise warning 'sync_improvement_decision: % for improvement %: %', NEW.status, NEW.related_id, SQLERRM;
    end;
  end if;
  return NEW;
end;
$function$;

CREATE OR REPLACE FUNCTION public.sync_outbound_draft_status()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if NEW.related_table = 'outbound_drafts' and NEW.status in ('approved', 'rejected')
     and OLD.status is distinct from NEW.status then
    update outbound_drafts set status = NEW.status, updated_at = now()
     where id = NEW.related_id and status = 'pending_approval';
  end if;
  return NEW;
end;
$function$;

CREATE OR REPLACE FUNCTION public.sync_primary_unit_membership()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if tg_op = 'UPDATE' and new.org_unit_id is not distinct from old.org_unit_id then
    return new;
  end if;

  -- Retire the previous primary. Memberships somebody added by hand are
  -- is_primary = false and are none of this trigger's business.
  delete from org_unit_members m
   where m.user_id = new.user_id and m.is_primary
     and (new.org_unit_id is null or m.org_unit_id <> new.org_unit_id);

  if new.org_unit_id is not null and new.user_id is not null then
    insert into org_unit_members (tenant_id, org_unit_id, user_id, role_in_unit, is_active, is_primary)
    values (new.tenant_id, new.org_unit_id, new.user_id, 'member', true, true)
    on conflict (org_unit_id, user_id)
      -- Already a member by hand: promote that row rather than duplicating it,
      -- and do NOT demote a lead to a member on the way past.
      do update set is_primary = true, is_active = true;
  end if;

  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.sync_profile_department()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  -- INSERT: the invite carries a NAME. Bind it to the real unit if one exists.
  if tg_op = 'INSERT'
     and new.org_unit_id is null
     and coalesce(btrim(new.department), '') <> '' then
    select u.id into new.org_unit_id
    from org_units u
    where u.tenant_id = new.tenant_id
      and u.kind in ('department', 'team')
      and lower(btrim(u.name)) = lower(btrim(new.department))
      and u.is_active
    limit 1;
  end if;

  if new.org_unit_id is not null then
    select u.name into new.department from org_units u where u.id = new.org_unit_id;
  elsif tg_op = 'UPDATE' then
    -- Explicitly moved out of a unit. Blank it, so the last department someone
    -- was in does not sit there looking current.
    new.department := '';
  end if;
  -- INSERT with no matching unit: keep whatever the inviter typed.

  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.task_approval_facts(p_task_id uuid)
 RETURNS TABLE(category text, amount_cents bigint)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select
    -- An action approval is classified by the action's own category
    -- (erp_financials, helpdesk, ads…); everything else by its task type
    -- (escalation, review_gate, checklist…). The two vocabularies do not
    -- overlap, so one column holds both without ambiguity.
    coalesce(ad.category, h.type),
    -- ⚠ `amount_cents` is the param name the platform's money gates already
    -- read; `outstanding_cents` is what the dunning sweep carries. Reading
    -- only one would leave a whole class of money silently unpriced.
    coalesce(
      nullif(ae.params->>'amount_cents', '')::bigint,
      nullif(ae.params->>'outstanding_cents', '')::bigint
    )
  from human_tasks h
  left join action_executions ae
    on ae.id = h.related_id and h.related_table = 'action_executions'
  left join action_definitions ad on ad.id = ae.action_definition_id
  where h.id = p_task_id
  limit 1;
$function$;

CREATE OR REPLACE FUNCTION public.tenant_ancestors(p_tenant_id uuid)
 RETURNS TABLE(tenant_id uuid, depth integer)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not caller_has_tenant_relationship(p_tenant_id) then
    raise exception 'not authorized to view ancestors of this tenant';
  end if;
  return query
    select ta.ancestor_id, ta.depth
    from tenant_ancestry ta
    where ta.tenant_id = p_tenant_id and ta.ancestor_id <> p_tenant_id
    order by ta.depth, ta.ancestor_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.tenant_deletion_receipts_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  RAISE EXCEPTION 'tenant_deletion_receipts is append-only — a deletion receipt that can be altered proves nothing';
END $function$;

CREATE OR REPLACE FUNCTION public.tenant_descendants(p_tenant_id uuid)
 RETURNS TABLE(tenant_id uuid, depth integer)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not caller_has_tenant_relationship(p_tenant_id) then
    raise exception 'not authorized to view descendants of this tenant';
  end if;
  return query
    select ta.tenant_id, ta.depth
    from tenant_ancestry ta
    where ta.ancestor_id = p_tenant_id and ta.tenant_id <> p_tenant_id
    order by ta.depth, ta.tenant_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.tenant_domain_dns_record_name(p_domain text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT '_dreamteam-verify.' || p_domain;
$function$;

CREATE OR REPLACE FUNCTION public.tenant_is_operational(p_tenant_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select case
    when p_tenant_id is null then true
    else exists (select 1 from tenants t
                  where t.id = p_tenant_id and t.status in ('active', 'trial'))
  end;
$function$;

CREATE OR REPLACE FUNCTION public.tenant_llm_key_status(p_tenant_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_mode text; v_keys jsonb;
BEGIN
  IF auth.role() IS NOT NULL AND auth.role() <> 'service_role' THEN
    IF auth.uid() IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
    IF NOT (is_platform_admin() OR EXISTS (SELECT 1 FROM profiles p
              WHERE p.user_id = auth.uid() AND p.tenant_id = p_tenant_id)) THEN
      RAISE EXCEPTION 'not authorized';
    END IF;
  END IF;

  SELECT llm_key_mode INTO v_mode FROM tenants WHERE id = p_tenant_id;
  SELECT coalesce(jsonb_agg(jsonb_build_object(
           'provider_key', c.provider_key, 'status', c.status,
           'last_verified_at', c.last_verified_at, 'last_error', c.last_error)
         ORDER BY c.provider_key), '[]'::jsonb)
    INTO v_keys FROM tenant_llm_credentials c WHERE c.tenant_id = p_tenant_id;

  RETURN jsonb_build_object('ok', true, 'mode', v_mode, 'keys', v_keys);
END $function$;

CREATE OR REPLACE FUNCTION public.tenant_rows_remaining(p_tenant_id uuid)
 RETURNS TABLE(table_name text, remaining_rows bigint, counts_as_residue boolean)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  r record;
  v_n bigint;
  -- Tables that legitimately hold rows for a deleted tenant. Returned in the
  -- result set with counts_as_residue = false rather than filtered out, so a
  -- reader can see the exclusion instead of trusting it. §7 asserts this list
  -- stays exactly one element long.
  v_retained constant text[] := ARRAY['tenant_deletion_receipts'];
BEGIN
  -- session_user='postgres' is the direct-connection path (psql, db-query.mjs,
  -- this migration's own assertions). Measured: on a direct connection
  -- auth.role() and auth.uid() are both NULL, so without this the function
  -- would refuse to run for the owner role that already has rolbypassrls and
  -- owns every table — it grants nothing new. PostgREST connects as
  -- 'authenticator' and switches role, so no request from the API can reach it.
  IF session_user <> 'postgres'
     AND coalesce(auth.role(), '') <> 'service_role'
     AND NOT is_platform_admin()
     AND NOT can_admin_tenant_internal(p_tenant_id)
  THEN
    RAISE EXCEPTION 'not authorized to enumerate tenant data';
  END IF;

  FOR r IN
    SELECT c.relname::text AS rel
      FROM pg_class c
      JOIN pg_namespace n ON n.oid = c.relnamespace
      JOIN pg_attribute a ON a.attrelid = c.oid
                         AND a.attname = 'tenant_id'
                         AND a.attnum > 0 AND NOT a.attisdropped
     WHERE n.nspname = 'public'
       -- Ordinary and partitioned tables only. VIEWS are excluded because they
       -- own no rows: eval_gate and pipeline_summary are relkind='v' (verified
       -- in pg_class), so counting them would double-count their base tables.
       -- Partition members are excluded so their parent is not counted twice;
       -- measured: 0 partitioned tables exist today, this is future-proofing.
       AND c.relkind IN ('r','p')
       AND NOT c.relispartition
       -- uuid only: every one of the 216 is uuid today, and a text tenant_id
       -- would make the `= $1` comparison below throw rather than mis-count.
       AND a.atttypid = 'uuid'::regtype
     ORDER BY c.relname
  LOOP
    EXECUTE format('SELECT count(*) FROM public.%I WHERE tenant_id = $1', r.rel)
      INTO v_n USING p_tenant_id;
    table_name        := r.rel;
    remaining_rows    := v_n;
    counts_as_residue := NOT (r.rel = ANY(v_retained));
    RETURN NEXT;
  END LOOP;
END $function$;

CREATE OR REPLACE FUNCTION public.touch_inbox_watch_state(p_tenant_id uuid, p_connector_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
begin
  insert into inbox_watch_state (tenant_id, connector_id, last_polled_at)
  values (p_tenant_id, p_connector_id, now())
  on conflict (tenant_id, connector_id) do update set last_polled_at = now();
end;
$function$;

CREATE OR REPLACE FUNCTION public.transfer_tenant_ownership(p_new_owner_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_caller_tenant uuid;
  v_caller_role text;
  v_target_tenant uuid;
  v_target_active boolean;
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;
  if auth.uid() = p_new_owner_user_id then
    raise exception 'you are already the owner';
  end if;

  select tenant_id, role into v_caller_tenant, v_caller_role
  from profiles where user_id = auth.uid() and coalesce(is_active, true) = true;
  if v_caller_tenant is null or v_caller_role <> 'tenant_owner' then
    raise exception 'only the current workspace owner can transfer ownership';
  end if;

  select tenant_id, coalesce(is_active, true) into v_target_tenant, v_target_active
  from profiles where user_id = p_new_owner_user_id;
  if v_target_tenant is null or v_target_tenant is distinct from v_caller_tenant then
    raise exception 'the new owner must already be a member of this workspace';
  end if;
  if not v_target_active then
    raise exception 'the new owner must be an active team member';
  end if;

  update profiles set role = 'tenant_admin' where user_id = auth.uid();
  update profiles set role = 'tenant_owner' where user_id = p_new_owner_user_id;

  perform append_audit_event_internal(
    v_caller_tenant, 'You', 'human',
    'Workspace ownership transferred',
    'config_change',
    jsonb_build_object('kind', 'ownership_transfer', 'previous_owner', auth.uid(), 'new_owner', p_new_owner_user_id)
  );

  return jsonb_build_object('ok', true);
end;
$function$;

CREATE OR REPLACE FUNCTION public.trg_assign_human_task()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  perform assign_human_task(new.id);
  return null;
exception when others then
  -- Routing must never be able to stop an approval from being raised. A task
  -- nobody owns is a problem; a task that was never created is a worse one.
  return null;
end;
$function$;

CREATE OR REPLACE FUNCTION public.trg_provision_onboarding_architect()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
begin
  begin
    perform provision_onboarding_architect(new.id);
  exception when others then
    null; -- best-effort; tenant creation must always succeed
  end;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.trg_recompute_tenant_ancestry()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_descendant uuid;
begin
  perform recompute_tenant_ancestry(NEW.id);

  if TG_OP = 'UPDATE' and NEW.parent_tenant_id is distinct from OLD.parent_tenant_id then
    for v_descendant in
      select tenant_id from tenant_ancestry where ancestor_id = NEW.id and tenant_id <> NEW.id
    loop
      perform recompute_tenant_ancestry(v_descendant);
    end loop;
  end if;

  return NEW;
end;
$function$;

CREATE OR REPLACE FUNCTION public.trg_recompute_trust_badge()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
begin
  if TG_OP = 'INSERT' then
    perform public.recompute_de_trust_badge(NEW.tenant_id, NEW.de_id);
  else
    perform public.recompute_de_trust_badge(NEW.tenant_id, NEW.de_id);
    if OLD.de_id is distinct from NEW.de_id then
      perform public.recompute_de_trust_badge(OLD.tenant_id, OLD.de_id);
    end if;
  end if;
  return null;
end;
$function$;

CREATE OR REPLACE FUNCTION public.trg_support_sentiment()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF coalesce(NEW.role, '') <> 'user' THEN RETURN NEW; END IF;
  BEGIN
    UPDATE de_conversations
       SET sentiment = public.classify_sentiment_text(NEW.content)
     WHERE id = NEW.conversation_id;
  EXCEPTION WHEN OTHERS THEN
    NULL;  -- sentiment must never block a customer message landing
  END;
  RETURN NEW;
END; $function$;

CREATE OR REPLACE FUNCTION public.trg_triage_support_conversation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_conv de_conversations; v_first boolean; v_cls jsonb;
BEGIN
  IF coalesce(NEW.role,'') <> 'user' THEN RETURN NEW; END IF;
  BEGIN
    SELECT count(*) = 1 INTO v_first FROM de_messages
      WHERE conversation_id = NEW.conversation_id AND role = 'user';
    IF NOT v_first THEN RETURN NEW; END IF;

    SELECT * INTO v_conv FROM de_conversations WHERE id = NEW.conversation_id;
    IF v_conv.id IS NULL OR v_conv.category IS NOT NULL THEN RETURN NEW; END IF;  -- don't override
    -- ⚠ Mig 671: a SUPPORT taxonomy classifies SUPPORT traffic. Exams,
    -- voice-lab runs and whatever channels come next stay untriaged rather
    -- than mislabelled — 282 exam conversations wearing customer-support
    -- categories is how the first taxonomy analysis reached a false verdict.
    IF v_conv.channel NOT IN ('widget','hosted','portal','email','dock') THEN RETURN NEW; END IF;

    v_cls := public.classify_support_text(v_conv.tenant_id, coalesce(v_conv.subject,'') || ' ' || coalesce(NEW.content,''));
    UPDATE de_conversations
       SET category   = v_cls->>'category',
           severity   = v_cls->>'severity',
           priority   = v_cls->>'priority',
           triaged_at = now()
     WHERE id = NEW.conversation_id AND category IS NULL;
  EXCEPTION WHEN OTHERS THEN
    NULL;  -- triage must never block a customer message landing
  END;
  RETURN NEW;
END; $function$;

CREATE OR REPLACE FUNCTION public.trust_apply_level(p_tenant_id uuid, p_category text, p_level integer, p_actor uuid, p_source_category text DEFAULT NULL::text, p_de_id uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_policy trust_policies;
  v_s jsonb;
begin
  -- Ladder-as-data (trust program mig 1): when the exact-scope policy
  -- carries a configured ladder its per-level settings drive the dial;
  -- a policy without one — and a scope with no policy row at all — takes
  -- the same immutable defaults as always. No auth context is read here:
  -- promotion (user/service) and demotion (trigger, no auth) pass
  -- through unchanged.
  select * into v_policy from trust_policies
  where tenant_id = p_tenant_id and action_category = p_category
    and source_category is not distinct from p_source_category
    and de_id is not distinct from p_de_id
  limit 1;
  if found then
    v_s := trust_ladder_settings(v_policy, p_level);
  else
    v_s := trust_level_settings(p_category, p_level);
  end if;
  insert into de_autonomy (tenant_id, action_type, source_category, de_id, enabled, max_amount_cents, min_confidence, updated_by)
  values (
    p_tenant_id, p_category, p_source_category, p_de_id,
    (v_s->>'enabled')::boolean,
    nullif(v_s->>'max_amount_cents', '')::bigint,
    nullif(v_s->>'min_confidence', '')::integer,
    p_actor
  )
  on conflict (tenant_id, action_type, coalesce(de_id, '00000000-0000-0000-0000-000000000000'::uuid), coalesce(playbook_id, '00000000-0000-0000-0000-000000000000'::uuid), coalesce(source_category, '')) do update set
    enabled          = excluded.enabled,
    max_amount_cents = excluded.max_amount_cents,
    min_confidence   = excluded.min_confidence,
    updated_by       = excluded.updated_by,
    updated_at       = now();
end;
$function$;

CREATE OR REPLACE FUNCTION public.trust_check_eval_regression()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_rate   numeric;
  v_policy record;
begin
  if new.finished_at is null or new.status not in ('passed', 'failed') or coalesce(new.total, 0) = 0 then
    return new;
  end if;
  if tg_op = 'UPDATE' and old.finished_at is not null then
    return new; -- only fire on the completion transition
  end if;

  v_rate := new.passed::numeric / new.total;
  begin
    for v_policy in
      select * from trust_policies
      where tenant_id = new.tenant_id and status = 'active' and current_level > baseline_level
        and v_rate < coalesce((criteria->>'min_eval_pass_rate')::numeric, 0.9)
    loop
      perform trust_demote(
        new.tenant_id, v_policy.action_category,
        format('evaluation pass rate fell to %s%% — below the %s%% floor',
          round(v_rate * 100), round(coalesce((v_policy.criteria->>'min_eval_pass_rate')::numeric, 0.9) * 100)),
        jsonb_build_object('eval_run_id', new.id, 'passed', new.passed, 'total', new.total, 'pass_rate', round(v_rate, 4)),
        v_policy.de_id, v_policy.source_category
      );
    end loop;
  exception when others then
    raise warning 'trust_check_eval_regression: %', sqlerrm;
  end;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.trust_check_guardrail_block()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_policy record;
begin
  if new.category <> 'guardrail_block' then
    return new;
  end if;
  begin
    for v_policy in
      select * from trust_policies
      where tenant_id = new.tenant_id and status = 'active' and current_level > baseline_level
        and coalesce((criteria->>'max_guardrail_blocks')::integer, 0) = 0
        and (de_id is null
             or new.detail->>'de_id' is null
             or de_id::text = new.detail->>'de_id')
    loop
      perform trust_demote(
        new.tenant_id, v_policy.action_category,
        'a guardrail block occurred — zero-tolerance policy',
        jsonb_build_object('audit_event_id', new.id, 'blocked_action', new.action),
        v_policy.de_id, v_policy.source_category
      );
    end loop;
  exception when others then
    raise warning 'trust_check_guardrail_block: %', sqlerrm;
  end;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.trust_demote(p_tenant_id uuid, p_category text, p_reason text, p_evidence jsonb, p_de_id uuid DEFAULT NULL::uuid, p_source_category text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_policy trust_policies;
  v_new    integer;
  v_label  text;
begin
  -- Target the EXACT policy (per-DE + per-source), not an arbitrary tenant/
  -- category row. NULL de_id / source_category match the tenant-wide policy.
  select * into v_policy
  from trust_policies
  where tenant_id = p_tenant_id and action_category = p_category
    and de_id is not distinct from p_de_id
    and source_category is not distinct from p_source_category
    and status = 'active' and current_level > baseline_level
  for update;
  if not found then
    return;
  end if;

  v_new := greatest(v_policy.current_level - 1, v_policy.baseline_level);
  v_label := replace(p_category, '_', ' ');

  -- GI-3: demote at the SAME scope the promotion was granted at.
  perform trust_apply_level(p_tenant_id, p_category, v_new, null, p_source_category, p_de_id);
  update trust_policies
  set current_level = v_new,
      pending_task_id = null, pending_evidence = null, requested_by = null, requested_at = null
  where id = v_policy.id;

  perform append_audit_event(
    p_tenant_id, 'Trust engine', 'system',
    format('Trust demoted — %s level %s → %s (%s). Demotion is automatic and immediate.',
      v_label, v_policy.current_level, v_new, p_reason),
    'config_change',
    jsonb_build_object('kind', 'trust_demoted', 'policy_id', v_policy.id,
      'action_category', p_category, 'de_id', p_de_id, 'from_level', v_policy.current_level,
      'to_level', v_new, 'reason', p_reason, 'evidence', p_evidence)
  );

  insert into human_tasks (tenant_id, type, title, detail, source, related_table, related_id)
  values (
    p_tenant_id, 'trust_demotion_notice',
    format('Trust reduced — %s dropped to level %s', v_label, v_new),
    format('Reason: %s. The dial was lowered automatically to stay safe. Approve to acknowledge — trust can be re-earned through the same evidence path.', p_reason),
    'system', 'trust_policies', v_policy.id
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.trust_level_settings(p_category text, p_level integer)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select case
    when p_level <= 0 then jsonb_build_object('enabled', false, 'max_amount_cents', null, 'min_confidence', null)
    when p_category = 'invoice_auto_send' then jsonb_build_object(
      'enabled', true,
      'max_amount_cents', (array[100000, 500000, 1000000])[least(p_level, 3)],
      'min_confidence', null)
    when p_category = 'action_execute' then jsonb_build_object(
      'enabled', true, 'max_amount_cents', null, 'min_confidence', null)
    else jsonb_build_object(
      'enabled', true,
      'max_amount_cents', null,
      'min_confidence', (array[90, 75, 60])[least(p_level, 3)])
  end;
$function$;

CREATE OR REPLACE FUNCTION public.unassign_doc_collection(p_doc_id uuid, p_collection_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tenant uuid := public.auth_tenant_id();
BEGIN
  IF v_tenant IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'no_tenant'); END IF;
  -- The original did not even check the document existed.
  IF NOT EXISTS (SELECT 1 FROM knowledge_docs WHERE id = p_doc_id AND tenant_id = v_tenant)
    THEN RETURN jsonb_build_object('ok', false, 'error', 'doc_not_found'); END IF;

  -- 359: THE BYPASS THIS CLOSES. Un-filing rebuilds the ancestry closure, which
  -- nulls restricted_space_id, which lets the workspace-wide grant reach a
  -- document that was in a locked room. Unrestricted by any policy, because
  -- this function is SECURITY DEFINER.
  IF NOT public.is_platform_admin() THEN
    IF public.knowledge_effective_level(p_doc_id) < 3 THEN
      RETURN jsonb_build_object('ok', false, 'error', 'insufficient_permission',
                                'detail', 'you need edit access to that document');
    END IF;
    IF public.knowledge_my_admin_level(p_collection_id) < 3 THEN
      RETURN jsonb_build_object('ok', false, 'error', 'insufficient_permission',
                                'detail', 'you need access to the space you are removing it from');
    END IF;
  END IF;

  DELETE FROM knowledge_doc_collections
   WHERE tenant_id = v_tenant AND doc_id = p_doc_id AND collection_id = p_collection_id;
  RETURN jsonb_build_object('ok', true);
END $function$;

CREATE OR REPLACE FUNCTION public.unpark_support_conversation(p_conversation_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_de uuid;
begin
  perform _assert_conv_member(p_conversation_id);
  select de_id into v_de from de_conversations where id = p_conversation_id;
  if v_de is not null and not public.can_access_de(v_de) then
    raise exception 'not_responsible_for_de: this employee is not in your reporting line';
  end if;
  update de_conversations
     set snoozed_at = null, snoozed_until = null
   where id = p_conversation_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.update_custom_metric(p_metric_id uuid, p_updates jsonb)
 RETURNS TABLE(metric_id uuid, tenant_id uuid, name text, key text, type text, created_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_owner UUID;
BEGIN
  SELECT cm.tenant_id INTO v_owner FROM customer_metrics cm WHERE cm.metric_id = p_metric_id;
  IF v_owner IS NULL THEN RAISE EXCEPTION 'metric_not_found'; END IF;
  PERFORM public._assert_caller_tenant(v_owner);

  UPDATE customer_metrics cm
  SET name = COALESCE((p_updates->>'name')::TEXT, cm.name),
      description = COALESCE((p_updates->>'description')::TEXT, cm.description),
      unit = COALESCE((p_updates->>'unit')::TEXT, cm.unit),
      thresholds = COALESCE((p_updates->'thresholds')::JSONB, cm.thresholds)
  WHERE cm.metric_id = p_metric_id;

  RETURN QUERY SELECT cm.metric_id, cm.tenant_id, cm.name, cm.key, cm.type, cm.created_at
  FROM customer_metrics cm WHERE cm.metric_id = p_metric_id;
END$function$;

CREATE OR REPLACE FUNCTION public.update_employee_private(p_user_id uuid, p_patch jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tenant uuid := auth_tenant_id();
  v_ok     boolean;
begin
  if v_tenant is null then raise exception 'not_authenticated'; end if;
  v_ok := (p_user_id = auth.uid()) or auth_has_tenant_role(array['tenant_owner','tenant_admin']);
  if not v_ok then
    raise exception 'not_allowed: personal details are visible to the person and to owners and admins only';
  end if;
  if not exists (select 1 from profiles where user_id = p_user_id and tenant_id = v_tenant) then
    raise exception 'no_such_employee_in_this_workspace';
  end if;

  insert into profile_private as pp (user_id, tenant_id) values (p_user_id, v_tenant)
  on conflict (user_id) do nothing;

  update profile_private pp set
    date_of_birth   = case when p_patch ? 'date_of_birth'   then nullif(p_patch->>'date_of_birth','')::date else pp.date_of_birth end,
    personal_email  = case when p_patch ? 'personal_email'  then nullif(p_patch->>'personal_email','')  else pp.personal_email end,
    personal_phone  = case when p_patch ? 'personal_phone'  then nullif(p_patch->>'personal_phone','')  else pp.personal_phone end,
    address_line1   = case when p_patch ? 'address_line1'   then nullif(p_patch->>'address_line1','')   else pp.address_line1 end,
    address_line2   = case when p_patch ? 'address_line2'   then nullif(p_patch->>'address_line2','')   else pp.address_line2 end,
    city            = case when p_patch ? 'city'            then nullif(p_patch->>'city','')            else pp.city end,
    state_region    = case when p_patch ? 'state_region'    then nullif(p_patch->>'state_region','')    else pp.state_region end,
    postal_code     = case when p_patch ? 'postal_code'     then nullif(p_patch->>'postal_code','')     else pp.postal_code end,
    country         = case when p_patch ? 'country'         then nullif(p_patch->>'country','')         else pp.country end,
    emergency_contact_name         = case when p_patch ? 'emergency_contact_name'         then nullif(p_patch->>'emergency_contact_name','')         else pp.emergency_contact_name end,
    emergency_contact_relationship = case when p_patch ? 'emergency_contact_relationship' then nullif(p_patch->>'emergency_contact_relationship','') else pp.emergency_contact_relationship end,
    emergency_contact_phone        = case when p_patch ? 'emergency_contact_phone'        then nullif(p_patch->>'emergency_contact_phone','')        else pp.emergency_contact_phone end,
    updated_at = now()
  where pp.user_id = p_user_id and pp.tenant_id = v_tenant;

  return jsonb_build_object('ok', true);
end;
$function$;

CREATE OR REPLACE FUNCTION public.update_employee_profile(p_user_id uuid, p_patch jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tenant  uuid := auth_tenant_id();
  v_is_hr   boolean := auth_has_tenant_role(array['tenant_owner','tenant_admin','tenant_manager']);
  v_is_self boolean := (p_user_id = auth.uid());
  v_key     text;
  -- What the person may change about themselves: their name, how to reach them
  -- and how they are addressed. Not their job, their manager or their start
  -- date. full_name is here because a person owning what they are CALLED is
  -- the least controversial edit in the product, and because it is the only
  -- name field signup ever fills in.
  v_self_ok text[] := array['full_name','preferred_name','pronouns','work_phone','mobile_phone','time_zone','locale'];
  v_hr_ok   text[] := array['employee_number','full_name','first_name','middle_name','last_name','preferred_name',
                            'pronouns','work_email','work_phone','mobile_phone','job_title',
                            'employment_type','employment_status','hire_date','end_date',
                            'org_unit_id','reports_to_user_id','work_location','time_zone','locale'];
  v_allowed text[];
  v_applied text[] := '{}';
begin
  if v_tenant is null then raise exception 'not_authenticated'; end if;
  if not exists (select 1 from profiles where user_id = p_user_id and tenant_id = v_tenant) then
    raise exception 'no_such_employee_in_this_workspace';
  end if;
  if not (v_is_hr or v_is_self) then
    raise exception 'not_allowed: only an owner, admin or manager may edit someone else''s record';
  end if;

  v_allowed := case when v_is_hr then v_hr_ok else v_self_ok end;

  for v_key in select jsonb_object_keys(p_patch) loop
    if not (v_key = any(v_allowed)) then
      -- Named explicitly rather than skipped. Silently dropping a field the
      -- caller asked to change is how a UI reports success on a write that
      -- never happened.
      raise exception 'field_not_editable: %', v_key;
    end if;
    v_applied := v_applied || v_key;
  end loop;

  if array_length(v_applied, 1) is null then
    return jsonb_build_object('ok', true, 'changed', 0);
  end if;

  -- A manager cannot report to themselves; a cycle here would hang any org
  -- chart that walks the line.
  if p_patch ? 'reports_to_user_id'
     and nullif(p_patch->>'reports_to_user_id','')::uuid = p_user_id then
    raise exception 'a person cannot report to themselves';
  end if;

  update profiles p set
    employee_number    = case when p_patch ? 'employee_number'    then nullif(p_patch->>'employee_number','')    else p.employee_number end,
    full_name          = case when p_patch ? 'full_name'          then nullif(p_patch->>'full_name','')          else p.full_name end,
    first_name         = case when p_patch ? 'first_name'         then nullif(p_patch->>'first_name','')         else p.first_name end,
    middle_name        = case when p_patch ? 'middle_name'        then nullif(p_patch->>'middle_name','')        else p.middle_name end,
    last_name          = case when p_patch ? 'last_name'          then nullif(p_patch->>'last_name','')          else p.last_name end,
    preferred_name     = case when p_patch ? 'preferred_name'     then nullif(p_patch->>'preferred_name','')     else p.preferred_name end,
    pronouns           = case when p_patch ? 'pronouns'           then nullif(p_patch->>'pronouns','')           else p.pronouns end,
    work_email         = case when p_patch ? 'work_email'         then nullif(p_patch->>'work_email','')         else p.work_email end,
    work_phone         = case when p_patch ? 'work_phone'         then nullif(p_patch->>'work_phone','')         else p.work_phone end,
    mobile_phone       = case when p_patch ? 'mobile_phone'       then nullif(p_patch->>'mobile_phone','')       else p.mobile_phone end,
    job_title          = case when p_patch ? 'job_title'          then nullif(p_patch->>'job_title','')          else p.job_title end,
    employment_type    = case when p_patch ? 'employment_type'    then nullif(p_patch->>'employment_type','')    else p.employment_type end,
    employment_status  = case when p_patch ? 'employment_status'  then nullif(p_patch->>'employment_status','')  else p.employment_status end,
    hire_date          = case when p_patch ? 'hire_date'          then nullif(p_patch->>'hire_date','')::date    else p.hire_date end,
    end_date           = case when p_patch ? 'end_date'           then nullif(p_patch->>'end_date','')::date     else p.end_date end,
    org_unit_id        = case when p_patch ? 'org_unit_id'        then nullif(p_patch->>'org_unit_id','')::uuid  else p.org_unit_id end,
    reports_to_user_id = case when p_patch ? 'reports_to_user_id' then nullif(p_patch->>'reports_to_user_id','')::uuid else p.reports_to_user_id end,
    work_location      = case when p_patch ? 'work_location'      then nullif(p_patch->>'work_location','')      else p.work_location end,
    time_zone          = case when p_patch ? 'time_zone'          then nullif(p_patch->>'time_zone','')          else p.time_zone end,
    locale             = case when p_patch ? 'locale'             then nullif(p_patch->>'locale','')             else p.locale end,
    updated_at         = now()
  where p.user_id = p_user_id and p.tenant_id = v_tenant;

  return jsonb_build_object('ok', true, 'changed', array_length(v_applied, 1), 'fields', to_jsonb(v_applied));
end;
$function$;

CREATE OR REPLACE FUNCTION public.update_onboarding_item(p_project_id uuid, p_key text, p_status text DEFAULT NULL::text, p_assignee text DEFAULT NULL::text, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_proj      onboarding_projects;
  v_ver       onboarding_template_versions;
  v_def       jsonb;
  v_item      jsonb;
  v_idx       integer := -1;
  v_i         integer := 0;
  v_old       text;
  v_task_id   uuid;
  v_acct_name text;
  v_completed boolean := false;
  v_signoff   boolean;
begin
  select * into v_proj from onboarding_projects where id = p_project_id;
  if not found then return jsonb_build_object('error', 'project_not_found'); end if;
  if not exists (
    select 1 from profiles where user_id = auth.uid() and tenant_id = v_proj.tenant_id and coalesce(is_active, true) = true
  ) then
    raise exception 'not a member of this tenant';
  end if;
  if v_proj.status <> 'active' then
    return jsonb_build_object('error', 'project_not_active');
  end if;
  if p_status is not null and p_status not in ('pending', 'in_progress', 'done', 'blocked') then
    return jsonb_build_object('error', 'invalid_status');
  end if;

  select * into v_ver from onboarding_template_versions where id = v_proj.template_version_id;
  select d into v_def from jsonb_array_elements(v_ver.items) d where d->>'key' = p_key limit 1;
  if v_def is null then return jsonb_build_object('error', 'item_not_found'); end if;
  v_signoff := coalesce((v_def->>'requires_signoff')::boolean, false);

  for v_item in select * from jsonb_array_elements(v_proj.items_state) loop
    if v_item->>'key' = p_key then v_idx := v_i; exit; end if;
    v_i := v_i + 1;
  end loop;
  if v_idx < 0 then return jsonb_build_object('error', 'item_state_missing'); end if;
  v_old := v_item->>'status';

  if v_old = 'signed_off' then
    return jsonb_build_object('error', 'item_already_signed_off');
  end if;

  if p_assignee is not null then v_item := v_item || jsonb_build_object('assignee', nullif(trim(p_assignee), '')); end if;
  if p_note is not null then v_item := v_item || jsonb_build_object('note', p_note); end if;

  if p_status is not null and p_status <> v_old then
    v_item := v_item || jsonb_build_object('status', p_status);
    if p_status = 'done' then
      v_item := v_item || jsonb_build_object('done_at', now());
      if v_signoff then
        insert into human_tasks (tenant_id, type, title, detail, source, related_table, related_id)
        values (v_proj.tenant_id, 'review_gate',
                format('Onboarding sign-off — %s · %s', v_def->>'label', v_proj.name),
                format('Item "%s" is marked done and needs a human sign-off before the project can complete.', v_def->>'label'),
                'system', 'onboarding_projects', p_project_id)
        returning id into v_task_id;
        v_item := v_item || jsonb_build_object('signoff_task_id', v_task_id);
      end if;
    end if;

    select name into v_acct_name from customer_accounts where id = v_proj.account_id;
    insert into activity_events (tenant_id, account_id, actor, actor_type, event_type, text)
    values (v_proj.tenant_id, v_proj.account_id, 'You', 'human',
            case when p_status = 'blocked' then 'escalated' else 'config_change' end,
            format('Onboarding — %s: %s → %s%s (%s)', v_def->>'label', v_old, p_status,
                   case when v_task_id is not null then ' · awaiting sign-off' else '' end,
                   coalesce(v_acct_name, v_proj.name)));
  end if;

  update onboarding_projects
    set items_state = jsonb_set(items_state, array[v_idx::text], v_item)
    where id = p_project_id;

  -- non-signoff items can complete the project directly
  if p_status = 'done' and not v_signoff then
    v_completed := onboarding_check_complete(p_project_id);
  end if;

  select to_jsonb(p.*) into v_item from onboarding_projects p where p.id = p_project_id;
  return jsonb_build_object('project', v_item, 'signoff_task_id', v_task_id, 'completed', v_completed);
end;
$function$;

CREATE OR REPLACE FUNCTION public.update_onboarding_item_as_de(p_project_id uuid, p_de_id uuid, p_key text, p_status text DEFAULT NULL::text, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_proj      onboarding_projects;
  v_ver       onboarding_template_versions;
  v_def       jsonb;
  v_item      jsonb;
  v_idx       integer := -1;
  v_i         integer := 0;
  v_old       text;
  v_task_id   uuid;
  v_acct_name text;
  v_de_name   text;
  v_signoff   boolean;
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'update_onboarding_item_as_de is a runtime path; a person uses update_onboarding_item';
  end if;

  select * into v_proj from onboarding_projects where id = p_project_id;
  if not found then return jsonb_build_object('error', 'project_not_found'); end if;

  -- The employee must belong to THIS project's workspace. A de_id from another
  -- tenant resolves to nothing here — the same shape as the cross-tenant write
  -- holes mig 636 closed, refused before it can be exploited.
  select coalesce(persona_name, name) into v_de_name
    from digital_employees where id = p_de_id and tenant_id = v_proj.tenant_id;
  if v_de_name is null then
    return jsonb_build_object('error', 'employee_not_in_this_workspace');
  end if;

  if v_proj.status <> 'active' then
    return jsonb_build_object('error', 'project_not_active');
  end if;

  -- No employee signs off its own work. Ever.
  if p_status = 'signed_off' then
    return jsonb_build_object('error', 'signoff_is_a_human_decision');
  end if;
  if p_status is not null and p_status not in ('pending', 'in_progress', 'done', 'blocked') then
    return jsonb_build_object('error', 'bad_status');
  end if;

  select * into v_ver from onboarding_template_versions where id = v_proj.template_version_id;
  if not found then return jsonb_build_object('error', 'template_version_not_found'); end if;

  select d into v_def from jsonb_array_elements(v_ver.items) d where d->>'key' = p_key limit 1;
  if v_def is null then return jsonb_build_object('error', 'item_not_found'); end if;
  v_signoff := coalesce((v_def->>'requires_signoff')::boolean, false);

  for v_item in select * from jsonb_array_elements(v_proj.items_state) loop
    if v_item->>'key' = p_key then v_idx := v_i; exit; end if;
    v_i := v_i + 1;
  end loop;
  if v_idx < 0 then return jsonb_build_object('error', 'item_state_missing'); end if;
  v_old := v_item->>'status';

  if v_old = 'signed_off' then
    return jsonb_build_object('error', 'item_already_signed_off');
  end if;

  if p_note is not null then
    v_item := v_item || jsonb_build_object('note', p_note);
  end if;
  -- Who did it, on the item itself — not just in the activity feed.
  v_item := v_item || jsonb_build_object('last_actor_de', p_de_id, 'last_actor_name', v_de_name);

  if p_status is not null and p_status <> v_old then
    v_item := v_item || jsonb_build_object('status', p_status);
    if p_status = 'done' then
      v_item := v_item || jsonb_build_object('done_at', now());
      if v_signoff then
        insert into human_tasks (tenant_id, type, title, detail, source, related_table, related_id)
        values (v_proj.tenant_id, 'review_gate',
                format('Onboarding sign-off — %s · %s', v_def->>'label', v_proj.name),
                format('%s marked "%s" done. It needs a human sign-off before the project can complete.',
                       v_de_name, v_def->>'label'),
                'de', 'onboarding_projects', p_project_id)
        returning id into v_task_id;
        v_item := v_item || jsonb_build_object('signoff_task_id', v_task_id);
      end if;
    end if;

    select name into v_acct_name from customer_accounts where id = v_proj.account_id;
    insert into activity_events (tenant_id, account_id, actor, actor_type, event_type, text)
    values (v_proj.tenant_id, v_proj.account_id, v_de_name, 'de',
            case when p_status = 'blocked' then 'escalated' else 'config_change' end,
            format('Onboarding — %s: %s → %s%s (%s)', v_def->>'label', v_old, p_status,
                   case when v_task_id is not null then ' · awaiting sign-off' else '' end,
                   coalesce(v_acct_name, v_proj.name)));
  end if;

  update onboarding_projects
     set items_state = jsonb_set(items_state, array[v_idx::text], v_item)
   where id = p_project_id;

  -- A non-signoff item completing the project is the human function's rule and
  -- stays the human function's rule: an employee must not be able to drive a
  -- project to completed as a side effect of ticking the last box.
  return jsonb_build_object(
    'ok', true, 'item', p_key, 'status', coalesce(p_status, v_old),
    'signoff_task_id', v_task_id, 'recorded_by', v_de_name);
end;
$function$;

CREATE OR REPLACE FUNCTION public.update_platform_team_role(p_target_user_id uuid, p_new_role text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_target_layer text;
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;
  if not resolve_platform_capability(auth.uid(), 'team.manage') then
    raise exception 'only a platform team manager may change a teammate''s role';
  end if;
  if auth.uid() = p_target_user_id then
    raise exception 'you cannot change your own role here';
  end if;
  if p_new_role not in ('platform_super_admin', 'platform_support', 'platform_billing') then
    raise exception 'unrecognized platform role: %', p_new_role;
  end if;

  select layer into v_target_layer from profiles where user_id = p_target_user_id;
  if v_target_layer is distinct from 'platform' then
    raise exception 'that account is not a platform team member';
  end if;

  if platform_capability_remaining_holders(p_target_user_id, 'team.manage') = 0 then
    raise exception 'this change would leave zero active platform accounts able to manage the team -- at least one must always remain';
  end if;

  update profiles set role = p_new_role where user_id = p_target_user_id;

  return jsonb_build_object('ok', true, 'user_id', p_target_user_id, 'role', p_new_role);
end;
$function$;

CREATE OR REPLACE FUNCTION public.update_team_member_department(p_target_user_id uuid, p_org_unit_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_caller_tenant uuid;
  v_caller_role   text;
  v_target_tenant uuid;
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;

  select tenant_id, role into v_caller_tenant, v_caller_role
  from profiles where user_id = auth.uid() and coalesce(is_active, true) = true;
  if v_caller_tenant is null or v_caller_role not in ('tenant_owner', 'tenant_admin') then
    raise exception 'only workspace owners/admins can change a teammate''s department';
  end if;

  select tenant_id into v_target_tenant from profiles where user_id = p_target_user_id;
  if v_target_tenant is null or v_target_tenant is distinct from v_caller_tenant then
    raise exception 'that person is not a member of this workspace';
  end if;

  -- A unit from another workspace would place someone in an org chart their
  -- employer cannot see.
  if p_org_unit_id is not null and not exists (
    select 1 from org_units u
    where u.id = p_org_unit_id and u.tenant_id = v_caller_tenant and u.is_active
  ) then
    raise exception 'that is not a department in this workspace';
  end if;

  -- department is maintained by trigger from org_unit_id.
  update profiles set org_unit_id = p_org_unit_id where user_id = p_target_user_id;

  return jsonb_build_object('ok', true,
    'department', coalesce((select name from org_units where id = p_org_unit_id), ''));
end;
$function$;

CREATE OR REPLACE FUNCTION public.update_team_member_role(p_target_user_id uuid, p_new_role text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_caller_tenant uuid;
  v_caller_role text;
  v_target_tenant uuid;
  v_target_role text;
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;
  if auth.uid() = p_target_user_id then
    raise exception 'use a different flow to change your own role';
  end if;
  if p_new_role in ('tenant_owner', 'dt_super_admin', 'dt_god_access', 'dt_support', 'dt_billing', 'platform_super_admin', 'platform_support', 'platform_billing') then
    raise exception 'use transfer_tenant_ownership to hand off ownership; this function cannot grant owner or platform-tier roles';
  end if;

  select tenant_id, role into v_caller_tenant, v_caller_role
  from profiles where user_id = auth.uid() and coalesce(is_active, true) = true;
  if v_caller_tenant is null or v_caller_role not in ('tenant_owner', 'tenant_admin') then
    raise exception 'only workspace owners/admins can change a teammate''s role';
  end if;

  select tenant_id, role into v_target_tenant, v_target_role
  from profiles where user_id = p_target_user_id;
  if v_target_tenant is null or v_target_tenant is distinct from v_caller_tenant then
    raise exception 'that person is not a member of this workspace';
  end if;
  if v_target_role = 'tenant_owner' then
    raise exception 'the workspace owner''s role can only be changed by transferring ownership';
  end if;

  update profiles set role = p_new_role where user_id = p_target_user_id;

  perform append_audit_event_internal(
    v_caller_tenant, 'You', 'human',
    format('Team member role changed to %s', p_new_role),
    'config_change',
    jsonb_build_object('kind', 'team_role_change', 'target_user_id', p_target_user_id, 'new_role', p_new_role)
  );

  return jsonb_build_object('ok', true);
end;
$function$;

CREATE OR REPLACE FUNCTION public.update_tenant_billing(p_tenant_id uuid, p_billing_config jsonb)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
  IF NOT is_platform_admin() THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;

  INSERT INTO tenant_billing_config (
    tenant_id, sophie_config_cost, amendment_journeys_cost,
    metrics_tracking_cost, reply_mode_cost, hosted_chat_cost,
    cost_per_1k_responses, cost_per_amendment, cost_per_de,
    billing_email, payment_method
  ) VALUES (
    p_tenant_id,
    COALESCE((p_billing_config->>'sophie_config_cost')::numeric, 100),
    COALESCE((p_billing_config->>'amendment_cost')::numeric, 50),
    COALESCE((p_billing_config->>'metrics_cost')::numeric, 75),
    COALESCE((p_billing_config->>'reply_mode_cost')::numeric, 150),
    COALESCE((p_billing_config->>'hosted_chat_cost')::numeric, 200),
    COALESCE((p_billing_config->>'cost_per_1k_responses')::numeric, 0.50),
    COALESCE((p_billing_config->>'cost_per_amendment')::numeric, 5),
    COALESCE((p_billing_config->>'cost_per_de')::numeric, 20),
    p_billing_config->>'billing_email',
    COALESCE(p_billing_config->>'payment_method', 'invoice')
  )
  ON CONFLICT (tenant_id)
  DO UPDATE SET
    sophie_config_cost = EXCLUDED.sophie_config_cost,
    amendment_journeys_cost = EXCLUDED.amendment_journeys_cost,
    metrics_tracking_cost = EXCLUDED.metrics_tracking_cost,
    reply_mode_cost = EXCLUDED.reply_mode_cost,
    hosted_chat_cost = EXCLUDED.hosted_chat_cost,
    cost_per_1k_responses = EXCLUDED.cost_per_1k_responses,
    cost_per_amendment = EXCLUDED.cost_per_amendment,
    cost_per_de = EXCLUDED.cost_per_de,
    billing_email = EXCLUDED.billing_email,
    payment_method = EXCLUDED.payment_method,
    updated_at = now();

  RETURN json_build_object('ok', true, 'updated_at', now()::text);
END;
$function$;

CREATE OR REPLACE FUNCTION public.update_tenant_features(p_tenant_id uuid, p_features jsonb)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_user_id UUID;
BEGIN
  IF NOT is_platform_admin() THEN
    RAISE EXCEPTION 'Unauthorized';
  END IF;

  v_user_id := auth.uid();

  INSERT INTO tenant_feature_toggles (
    tenant_id, sophie_config_enabled, amendment_journeys_enabled,
    metrics_tracking_enabled, reply_mode_enabled, hosted_chat_enabled,
    amendment_replay_testing, trust_adaptive_execution, playbook_mining,
    updated_by
  ) VALUES (
    p_tenant_id,
    COALESCE(p_features->>'sophie_config_enabled', 'true')::boolean,
    COALESCE(p_features->>'amendment_journeys_enabled', 'true')::boolean,
    COALESCE(p_features->>'metrics_tracking_enabled', 'true')::boolean,
    COALESCE(p_features->>'reply_mode_enabled', 'true')::boolean,
    COALESCE(p_features->>'hosted_chat_enabled', 'true')::boolean,
    COALESCE(p_features->>'replay_testing', 'false')::boolean,
    COALESCE(p_features->>'trust_adaptive', 'false')::boolean,
    COALESCE(p_features->>'playbook_mining', 'false')::boolean,
    v_user_id
  )
  ON CONFLICT (tenant_id)
  DO UPDATE SET
    sophie_config_enabled = EXCLUDED.sophie_config_enabled,
    amendment_journeys_enabled = EXCLUDED.amendment_journeys_enabled,
    metrics_tracking_enabled = EXCLUDED.metrics_tracking_enabled,
    reply_mode_enabled = EXCLUDED.reply_mode_enabled,
    hosted_chat_enabled = EXCLUDED.hosted_chat_enabled,
    amendment_replay_testing = EXCLUDED.amendment_replay_testing,
    trust_adaptive_execution = EXCLUDED.trust_adaptive_execution,
    playbook_mining = EXCLUDED.playbook_mining,
    updated_at = now(),
    updated_by = v_user_id;

  RETURN json_build_object('ok', true, 'updated_at', now()::text);
END;
$function$;

CREATE OR REPLACE FUNCTION public.update_tenant_general_settings(p_tenant_id uuid, p_name text, p_industry text, p_accent_color text, p_vocabulary jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_demo_tenant_id constant uuid := 'a0000000-0000-0000-0000-000000000001';
  v_caller_tenant uuid;
  v_role text;
  v_is_active boolean;
  v_is_platform boolean := resolve_platform_capability(auth.uid(), 'tenants.manage');
begin
  if auth.uid() is null then
    raise exception 'not authenticated';
  end if;
  if p_tenant_id = v_demo_tenant_id then
    raise exception 'the demo tenant''s settings cannot be changed';
  end if;
  if coalesce(btrim(p_name), '') = '' then
    raise exception 'organization name is required';
  end if;
  if p_vocabulary is not null and jsonb_typeof(p_vocabulary) <> 'object' then
    raise exception 'vocabulary must be a JSON object';
  end if;

  if not v_is_platform then
    select tenant_id, role, coalesce(is_active, true) into v_caller_tenant, v_role, v_is_active
    from profiles where user_id = auth.uid();

    if v_caller_tenant is distinct from p_tenant_id or v_role not in ('tenant_owner', 'tenant_admin') then
      raise exception 'only an owner or admin of this organization may change these settings';
    end if;
    if not v_is_active then
      raise exception 'account is deactivated';
    end if;
  end if;

  update tenants
  set name = btrim(p_name), industry = nullif(btrim(coalesce(p_industry, '')), ''),
      accent_color = p_accent_color,
      vocabulary = coalesce(p_vocabulary, vocabulary),
      updated_at = now()
  where id = p_tenant_id;

  return jsonb_build_object('ok', true, 'tenant_id', p_tenant_id);
end;
$function$;

CREATE OR REPLACE FUNCTION public.update_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  new.updated_at = now();
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.upsert_commercial_agreement(p_id uuid DEFAULT NULL::uuid, p_title text DEFAULT NULL::text, p_counterparty_name text DEFAULT NULL::text, p_account_id uuid DEFAULT NULL::uuid, p_party_side text DEFAULT 'sell'::text, p_agreement_type text DEFAULT 'subscription'::text, p_status text DEFAULT 'active'::text, p_baseline_value_cents bigint DEFAULT NULL::bigint, p_auto_renew boolean DEFAULT false, p_notice_period_days integer DEFAULT NULL::integer, p_start_date date DEFAULT NULL::date, p_end_date date DEFAULT NULL::date, p_renewal_date date DEFAULT NULL::date, p_notice_deadline date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tenant uuid; v_id uuid;
BEGIN
  v_tenant := public.auth_tenant_id();
  IF v_tenant IS NULL OR NOT public.auth_has_tenant_role(
       ARRAY['tenant_owner','tenant_admin','tenant_manager']) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_permitted');
  END IF;
  IF p_id IS NULL AND (length(btrim(coalesce(p_title,''))) < 2
       OR length(btrim(coalesce(p_counterparty_name,''))) < 2) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'title_and_counterparty_required');
  END IF;
  IF p_account_id IS NOT NULL AND NOT EXISTS (
       SELECT 1 FROM customer_accounts WHERE id = p_account_id AND tenant_id = v_tenant) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'unknown_account');
  END IF;

  IF p_id IS NULL THEN
    INSERT INTO commercial_agreements (
      tenant_id, title, counterparty_name, account_id, party_side, agreement_type,
      status, baseline_value_cents, auto_renew, notice_period_days,
      start_date, end_date, renewal_date, notice_deadline, created_by)
    VALUES (
      v_tenant, btrim(p_title), btrim(p_counterparty_name), p_account_id, p_party_side,
      p_agreement_type, p_status, p_baseline_value_cents, coalesce(p_auto_renew,false),
      p_notice_period_days, p_start_date, p_end_date, p_renewal_date, p_notice_deadline,
      auth.uid())
    RETURNING id INTO v_id;
  ELSE
    UPDATE commercial_agreements SET
      title = coalesce(btrim(p_title), title),
      counterparty_name = coalesce(btrim(p_counterparty_name), counterparty_name),
      account_id = coalesce(p_account_id, account_id),
      party_side = coalesce(p_party_side, party_side),
      agreement_type = coalesce(p_agreement_type, agreement_type),
      status = coalesce(p_status, status),
      baseline_value_cents = coalesce(p_baseline_value_cents, baseline_value_cents),
      auto_renew = coalesce(p_auto_renew, auto_renew),
      notice_period_days = coalesce(p_notice_period_days, notice_period_days),
      start_date = coalesce(p_start_date, start_date),
      end_date = coalesce(p_end_date, end_date),
      renewal_date = coalesce(p_renewal_date, renewal_date),
      notice_deadline = coalesce(p_notice_deadline, notice_deadline),
      updated_at = now()
    WHERE id = p_id AND tenant_id = v_tenant
    RETURNING id INTO v_id;
    IF v_id IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'not_found'); END IF;
  END IF;

  BEGIN
    PERFORM public.append_audit_event(
      p_tenant_id => v_tenant, p_actor => 'You', p_actor_type => 'human',
      p_action => CASE WHEN p_id IS NULL THEN 'Agreement created — "' || btrim(p_title) || '"'
                       ELSE 'Agreement updated — ' || v_id::text END,
      p_category => 'config_change',
      p_detail => jsonb_build_object('kind','commercial_agreement','agreement_id', v_id));
  EXCEPTION WHEN OTHERS THEN NULL; -- audit best-effort; the write itself stands
  END;
  RETURN jsonb_build_object('ok', true, 'agreement_id', v_id);
EXCEPTION WHEN check_violation THEN
  RETURN jsonb_build_object('ok', false, 'error', 'invalid_value: ' || SQLERRM);
END $function$;

CREATE OR REPLACE FUNCTION public.upsert_de_objective(p_de_id uuid, p_title text, p_id uuid DEFAULT NULL::uuid, p_description text DEFAULT NULL::text, p_priority integer DEFAULT 3, p_due_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_status text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tenant uuid := auth_tenant_id(); v_id uuid; v_de_name text;
BEGIN
  IF v_tenant IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  IF NOT auth_has_tenant_role(ARRAY['tenant_owner','tenant_admin']) THEN
    RAISE EXCEPTION 'insufficient_role';
  END IF;
  SELECT name INTO v_de_name FROM digital_employees
   WHERE id = p_de_id AND tenant_id = v_tenant;
  IF v_de_name IS NULL THEN RAISE EXCEPTION 'de_not_found'; END IF;
  IF coalesce(trim(p_title), '') = '' THEN RAISE EXCEPTION 'an objective needs a title'; END IF;
  IF p_priority IS NOT NULL AND (p_priority < 1 OR p_priority > 5) THEN
    RAISE EXCEPTION 'priority must be between 1 and 5';
  END IF;

  IF p_id IS NULL THEN
    -- description is NOT NULL on this table; default it to the title rather
    -- than forcing the caller to type boilerplate.
    INSERT INTO de_objectives (tenant_id, de_id, title, description, priority, due_at, status, created_by)
    VALUES (v_tenant, p_de_id, trim(p_title), coalesce(p_description, trim(p_title)),
            coalesce(p_priority, 3), p_due_at, coalesce(p_status, 'open'), auth.uid())
    RETURNING id INTO v_id;
  ELSE
    UPDATE de_objectives SET
      title       = trim(p_title),
      description = coalesce(p_description, description),
      priority    = coalesce(p_priority, priority),
      due_at      = p_due_at,
      status      = coalesce(p_status, status),
      updated_at  = now()
    WHERE id = p_id AND tenant_id = v_tenant AND de_id = p_de_id
    RETURNING id INTO v_id;
    IF v_id IS NULL THEN RAISE EXCEPTION 'objective_not_found'; END IF;
  END IF;

  PERFORM append_audit_event(
    v_tenant, 'Workspace', 'human',
    format('%s objective %s — "%s"', v_de_name,
           CASE WHEN p_id IS NULL THEN 'created' ELSE 'updated' END, trim(p_title)),
    'config_change',
    jsonb_build_object('de_id', p_de_id, 'objective_id', v_id, 'status', coalesce(p_status, 'open'))
  );
  RETURN v_id;
END$function$;

CREATE OR REPLACE FUNCTION public.upsert_de_operate_binding(p_de_id uuid, p_system_id uuid, p_system_key text, p_label text, p_can_operate boolean, p_operate_domain text DEFAULT NULL::text, p_connector_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tenant uuid; v_key text; v_label text; v_domain text; v_id uuid;
  v_conn_tenant uuid; v_has_conn_url boolean := false;
BEGIN
  SELECT tenant_id INTO v_tenant FROM digital_employees WHERE id = p_de_id;
  IF v_tenant IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'de_not_found'); END IF;
  IF NOT public.can_admin_tenant_internal(v_tenant) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_permitted');
  END IF;

  v_domain := public.normalize_operate_domain(p_operate_domain);

  -- A linked connector must belong to this tenant; note whether it yields a host.
  IF p_connector_id IS NOT NULL THEN
    SELECT tenant_id, (public.normalize_operate_domain(base_url) IS NOT NULL)
      INTO v_conn_tenant, v_has_conn_url FROM connectors WHERE id = p_connector_id;
    IF v_conn_tenant IS NULL OR v_conn_tenant <> v_tenant THEN
      RETURN jsonb_build_object('ok', false, 'error', 'connector_not_in_tenant');
    END IF;
  END IF;

  -- Operable systems MUST resolve to a domain (else the bridge can't allowlist).
  IF p_can_operate AND v_domain IS NULL AND NOT v_has_conn_url THEN
    RETURN jsonb_build_object('ok', false, 'error', 'operate_domain_required');
  END IF;

  IF p_system_id IS NOT NULL THEN
    -- Update the operate fields on an existing binding (keep its read config).
    UPDATE de_connected_systems
       SET label          = coalesce(nullif(btrim(p_label),''), label),
           can_operate    = p_can_operate,
           operate_domain = v_domain,
           connector_id   = p_connector_id,
           active         = true
     WHERE id = p_system_id AND de_id = p_de_id AND tenant_id = v_tenant
     RETURNING id INTO v_id;
    IF v_id IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'binding_not_found'); END IF;
  ELSE
    -- Create a new operate-only binding.
    v_key := nullif(btrim(p_system_key), '');
    IF v_key IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'system_key_required'); END IF;
    v_label := coalesce(nullif(btrim(p_label),''), v_key);
    IF EXISTS (SELECT 1 FROM de_connected_systems WHERE de_id = p_de_id AND system_key = v_key) THEN
      RETURN jsonb_build_object('ok', false, 'error', 'system_key_exists');
    END IF;
    INSERT INTO de_connected_systems (
      tenant_id, de_id, system_key, label, binding_kind, source_table,
      can_read, can_write, can_verify, can_operate, operate_domain, connector_id, active
    ) VALUES (
      v_tenant, p_de_id, v_key, v_label, 'connector', NULL,
      false, false, false, p_can_operate, v_domain, p_connector_id, true
    ) RETURNING id INTO v_id;
  END IF;

  RETURN jsonb_build_object('ok', true, 'system_id', v_id,
    'resolved_domain', public.operate_domain_of((SELECT t FROM de_connected_systems t WHERE t.id = v_id)));
END; $function$;

CREATE OR REPLACE PROCEDURE public.upsert_de_skill(IN p_tenant_id uuid, IN p_de_id uuid, IN p_skill_key text, IN p_prof integer, IN p_sample integer, IN p_value numeric, IN p_detail text, INOUT p_prev integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $procedure$
declare
  v_name text;
begin
  select proficiency into p_prev from de_skills
  where tenant_id = p_tenant_id and de_id = p_de_id and skill_key = p_skill_key;

  insert into de_skills (tenant_id, de_id, skill_key, proficiency, sample_size, signal_value, detail, assessed_at)
  values (p_tenant_id, p_de_id, p_skill_key, p_prof, p_sample, p_value, p_detail, now())
  on conflict (tenant_id, de_id, skill_key)
  do update set proficiency = excluded.proficiency, sample_size = excluded.sample_size,
                signal_value = excluded.signal_value, detail = excluded.detail, assessed_at = now();

  -- §4.4: a material change in a skill's proficiency emits a
  -- skill_updated event. Only a real level change (both sides
  -- non-null and different) counts — first assessment / evidence
  -- appearing is noted but not spammed as a "change".
  if p_prev is not null and p_prof is not null and p_prev <> p_prof then
    select name into v_name from skill_catalog where skill_key = p_skill_key;
    perform append_audit_event_internal(
      p_tenant_id, 'Skills assessment', 'system',
      format('%s proficiency changed from level %s to level %s', coalesce(v_name, p_skill_key), p_prev, p_prof),
      'config_change',
      jsonb_build_object('kind', 'skill_updated', 'de_id', p_de_id, 'skill_key', p_skill_key, 'from', p_prev, 'to', p_prof)
    );
  end if;
end;
$procedure$;

CREATE OR REPLACE FUNCTION public.upsert_external_ap_record(p_tenant_id uuid, p_provider text, p_supplier_external_ref text, p_supplier_name text, p_invoice_external_ref text, p_amount_cents bigint, p_outstanding_cents bigint DEFAULT NULL::bigint, p_due_date date DEFAULT NULL::date, p_status text DEFAULT ''::text, p_currency text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_id uuid;
begin
  if p_tenant_id is null or coalesce(p_provider, '') = ''
     or coalesce(p_invoice_external_ref, '') = '' or coalesce(p_supplier_external_ref, '') = '' then
    raise exception 'tenant, provider, supplier ref and invoice ref are all required';
  end if;

  insert into purchase_invoices (tenant_id, supplier_external_ref, supplier_name,
                                 source_provider, source_external_ref,
                                 amount_cents, outstanding_cents, due_date, status, currency)
  values (p_tenant_id, p_supplier_external_ref,
          coalesce(nullif(p_supplier_name, ''), p_supplier_external_ref),
          p_provider, p_invoice_external_ref,
          coalesce(p_amount_cents, 0), p_outstanding_cents, p_due_date,
          coalesce(p_status, ''), p_currency)
  on conflict (tenant_id, source_provider, source_external_ref)
  do update set supplier_external_ref = excluded.supplier_external_ref,
                supplier_name = excluded.supplier_name,
                amount_cents = excluded.amount_cents,
                -- Same rule as the AR mirror: a sync that omits the balance
                -- must not ERASE a balance we already knew; a sync that
                -- states one always wins, because the ledger is the
                -- authority on what is owed.
                outstanding_cents = coalesce(excluded.outstanding_cents, purchase_invoices.outstanding_cents),
                due_date = excluded.due_date,
                status = excluded.status,
                currency = excluded.currency,
                updated_at = now()
  returning id into v_id;

  return jsonb_build_object('invoice_id', v_id, 'outstanding_known', p_outstanding_cents is not null);
end;
$function$;

CREATE OR REPLACE FUNCTION public.upsert_external_ar_record(p_tenant_id uuid, p_provider text, p_customer_external_ref text, p_customer_name text, p_invoice_external_ref text, p_amount_cents bigint, p_due_date date, p_status text, p_currency text, p_outstanding_cents bigint DEFAULT NULL::bigint, p_contact_email text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_account_id uuid;
  v_invoice_id uuid;
  v_status text;
begin
  if p_tenant_id is null or coalesce(p_provider,'') = ''
     or coalesce(p_invoice_external_ref,'') = '' or coalesce(p_customer_external_ref,'') = '' then
    raise exception 'tenant, provider, customer ref and invoice ref are all required';
  end if;

  v_status := case when p_status in ('pending_generation','awaiting_approval','sent','paid','overdue')
                   then p_status else 'sent' end;

  insert into customer_accounts (tenant_id, name, external_ref, source_provider, source_external_ref)
  values (p_tenant_id,
          coalesce(nullif(p_customer_name,''), p_customer_external_ref),
          p_customer_external_ref, p_provider, p_customer_external_ref)
  on conflict (tenant_id, source_provider, source_external_ref) where source_external_ref is not null
  do update set name = excluded.name, external_ref = excluded.external_ref, updated_at = now()
  returning id into v_account_id;

  insert into renewal_invoices (tenant_id, account_id, amount_cents, status, due_date, cadence_stage,
                                source_provider, source_external_ref, source_currency,
                                outstanding_cents, payments_reconciled_at, contact_email)
  values (p_tenant_id, v_account_id, coalesce(p_amount_cents, 0), v_status, p_due_date, 0,
          p_provider, p_invoice_external_ref, p_currency,
          p_outstanding_cents,
          -- Only stamp "we know the balance" when the source actually said so.
          case when p_outstanding_cents is not null then now() end,
          nullif(btrim(p_contact_email), ''))
  on conflict (tenant_id, source_provider, source_external_ref) where source_external_ref is not null
  do update set account_id = excluded.account_id, amount_cents = excluded.amount_cents,
                status = excluded.status, due_date = excluded.due_date,
                source_currency = excluded.source_currency,
                -- A later sync that omits the balance must not ERASE a balance
                -- we already knew — but a sync that states one always wins,
                -- because the ledger is the authority on what is owed.
                outstanding_cents = coalesce(excluded.outstanding_cents, renewal_invoices.outstanding_cents),
                payments_reconciled_at = case
                  when excluded.outstanding_cents is not null then now()
                  else renewal_invoices.payments_reconciled_at end,
                -- Same rule for the addressee: a sync that did not mention it
                -- must not silently downgrade the next chase from an email to
                -- an internal note.
                contact_email = coalesce(excluded.contact_email, renewal_invoices.contact_email),
                updated_at = now()
  returning id into v_invoice_id;

  return jsonb_build_object('account_id', v_account_id, 'invoice_id', v_invoice_id,
                            'outstanding_known', p_outstanding_cents is not null,
                            'can_email', nullif(btrim(coalesce(p_contact_email,'')), '') is not null);
end;
$function$;

CREATE OR REPLACE FUNCTION public.upsert_external_contact(p_tenant_id uuid, p_provider text, p_external_ref text, p_first_name text, p_last_name text, p_email text, p_phone text DEFAULT NULL::text, p_mobile text DEFAULT NULL::text, p_title text DEFAULT NULL::text, p_customer_external_ref text DEFAULT NULL::text, p_customer_name text DEFAULT NULL::text, p_is_primary boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_account uuid;
  v_email   text := nullif(btrim(lower(p_email)), '');
  v_ref     text;
  v_id      uuid;
begin
  if p_tenant_id is null or coalesce(p_provider,'') = '' or coalesce(p_external_ref,'') = '' then
    raise exception 'tenant, provider and external ref are all required';
  end if;

  -- The identity key. Email where the record has one, because that is what a
  -- person presents; otherwise the source reference, which is stable and
  -- unique but not guessable by someone who is not that customer.
  v_ref := coalesce(v_email, p_provider || ':' || p_external_ref);

  v_account := resolve_external_account(p_tenant_id, p_provider, p_customer_external_ref, p_customer_name);

  -- account_id is NOT NULL, and rightly so: a contact nobody is the contact FOR
  -- answers nothing. The question an employee asks is "who holds THIS
  -- relationship". Refuse loudly rather than file an orphan the DE will later
  -- fail to find.
  if v_account is null then
    return jsonb_build_object('ok', false, 'error', 'no_account',
      'detail', format('contact %s names no customer this workspace knows (%s)',
                       p_external_ref, coalesce(p_customer_external_ref, 'none given')));
  end if;

  -- Clear the old primary BEFORE claiming it: (account_id) WHERE is_primary is
  -- UNIQUE, so setting a second one in the same statement fails outright.
  if coalesce(p_is_primary, false) and v_account is not null then
    update customer_account_contacts
       set is_primary = false, updated_at = now()
     where tenant_id = p_tenant_id and account_id = v_account and is_primary
       and coalesce(external_ref,'') is distinct from p_external_ref;
  end if;

  insert into customer_account_contacts
    (tenant_id, account_id, end_user_ref, first_name, last_name, email, phone, mobile, title,
     is_primary, source, external_ref)
  values
    (p_tenant_id, v_account, v_ref,
     nullif(btrim(p_first_name),''), nullif(btrim(p_last_name),''),
     v_email, nullif(btrim(p_phone),''), nullif(btrim(p_mobile),''),
     nullif(btrim(p_title),''), coalesce(p_is_primary, false), p_provider, p_external_ref)
  on conflict (tenant_id, source, external_ref) where external_ref is not null
  do update set
    account_id   = coalesce(excluded.account_id, customer_account_contacts.account_id),
    end_user_ref = excluded.end_user_ref,
    first_name   = excluded.first_name,
    last_name    = excluded.last_name,
    -- A sync that omits a field must not ERASE one we already hold: the same
    -- rule the invoice ingest needed for contact_email (mig 595).
    email        = coalesce(excluded.email,  customer_account_contacts.email),
    phone        = coalesce(excluded.phone,  customer_account_contacts.phone),
    mobile       = coalesce(excluded.mobile, customer_account_contacts.mobile),
    title        = coalesce(excluded.title,  customer_account_contacts.title),
    is_primary   = excluded.is_primary,
    updated_at   = now()
  returning id into v_id;

  return jsonb_build_object('contact_id', v_id, 'account_id', v_account, 'identity_key', v_ref);
end;
$function$;

CREATE OR REPLACE FUNCTION public.upsert_external_journal_entry(p_tenant_id uuid, p_provider text, p_external_ref text, p_entry_date date, p_memo text, p_debit numeric, p_credit numeric)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_id uuid;
BEGIN
  IF p_tenant_id IS NULL OR coalesce(btrim(p_external_ref), '') = '' THEN
    RAISE EXCEPTION 'tenant_id and external_ref are required';
  END IF;

  INSERT INTO journal_entries (tenant_id, source, external_ref, entry_date, memo, debit, credit)
  VALUES (p_tenant_id, coalesce(nullif(btrim(p_provider), ''), 'external'), btrim(p_external_ref),
          p_entry_date, nullif(btrim(p_memo), ''),
          -- debit/credit are NOT NULL. A missing figure becomes 0, never a
          -- guess: a ledger that invents an amount is worse than one that is
          -- visibly incomplete.
          coalesce(p_debit, 0), coalesce(p_credit, 0))
  ON CONFLICT (tenant_id, source, external_ref) WHERE external_ref IS NOT NULL
  DO UPDATE SET
    entry_date = excluded.entry_date,
    memo       = excluded.memo,
    debit      = excluded.debit,
    credit     = excluded.credit
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$function$;

CREATE OR REPLACE FUNCTION public.upsert_external_opportunity(p_tenant_id uuid, p_provider text, p_external_ref text, p_name text, p_company_name text, p_stage text, p_amount_cents bigint, p_close_date date, p_owner text, p_customer_external_ref text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_account uuid;
  v_stage   text;
  v_id      uuid;
begin
  if p_tenant_id is null or coalesce(p_provider,'') = '' or coalesce(p_external_ref,'') = '' then
    raise exception 'tenant, provider and external ref are all required';
  end if;

  -- The pipeline board reads a closed vocabulary. Anything unrecognised lands
  -- at the top of the funnel rather than as a stage the UI cannot render.
  v_stage := case lower(coalesce(p_stage, ''))
    when 'open' then 'prospect'
    when 'quotation' then 'proposal'
    when 'converted' then 'won'
    when 'closed' then 'won'
    when 'lost' then 'lost'
    when 'replied' then 'qualified'
    else case when lower(coalesce(p_stage,'')) in
      ('prospect','qualified','proposal','negotiation','won','lost')
      then lower(p_stage) else 'prospect' end
  end;

  v_account := resolve_external_account(p_tenant_id, p_provider, p_customer_external_ref, p_company_name);

  insert into opportunities (tenant_id, account_id, name, company_name, stage, amount_cents,
                             close_date, owner, source, external_ref)
  values (p_tenant_id, v_account,
          coalesce(nullif(btrim(p_name),''), p_external_ref),
          nullif(btrim(p_company_name),''), v_stage, coalesce(p_amount_cents, 0),
          p_close_date, nullif(btrim(p_owner),''), p_provider, p_external_ref)
  on conflict (tenant_id, source, external_ref) where external_ref is not null
  do update set
    account_id   = coalesce(excluded.account_id, opportunities.account_id),
    name         = excluded.name,
    company_name = coalesce(excluded.company_name, opportunities.company_name),
    stage        = excluded.stage,
    amount_cents = excluded.amount_cents,
    close_date   = excluded.close_date,
    owner        = coalesce(excluded.owner, opportunities.owner),
    updated_at   = now()
  returning id into v_id;

  return jsonb_build_object('opportunity_id', v_id, 'account_id', v_account, 'stage', v_stage);
end;
$function$;

CREATE OR REPLACE FUNCTION public.upsert_external_ticket(p_tenant_id uuid, p_provider text, p_external_ref text, p_subject text, p_body text, p_status text, p_priority text, p_customer_external_ref text DEFAULT NULL::text, p_customer_name text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_account  uuid;
  v_status   text;
  v_priority text;
  v_id       uuid;
begin
  if p_tenant_id is null or coalesce(p_provider,'') = '' or coalesce(p_external_ref,'') = '' then
    raise exception 'tenant, provider and external ref are all required';
  end if;

  -- CHECK constraints, not preferences: status must be one of four and priority
  -- one of p1..p4. A passthrough would fail on the first real row.
  v_status := case lower(coalesce(p_status,''))
    when 'open' then 'open'
    when 'replied' then 'pending'
    when 'on hold' then 'pending'
    when 'pending' then 'pending'
    when 'resolved' then 'resolved'
    when 'closed' then 'resolved'
    when 'escalated' then 'escalated'
    else 'open' end;

  v_priority := case lower(coalesce(p_priority,''))
    when 'urgent' then 'p1'
    when 'critical' then 'p1'
    when 'high' then 'p2'
    when 'medium' then 'p3'
    when 'low' then 'p4'
    else case when lower(coalesce(p_priority,'')) in ('p1','p2','p3','p4')
      then lower(p_priority) else 'p3' end
  end;

  v_account := resolve_external_account(p_tenant_id, p_provider, p_customer_external_ref, p_customer_name);

  insert into support_tickets (tenant_id, account_id, subject, body, status, priority,
                               assignee, source, external_ref, resolved_at)
  values (p_tenant_id, v_account,
          left(coalesce(nullif(btrim(p_subject),''), p_external_ref), 300),
          p_body, v_status, v_priority,
          -- Arrived from a system of record, so a person owns it until a
          -- digital employee is explicitly given it.
          'human', p_provider, p_external_ref,
          case when v_status = 'resolved' then now() end)
  on conflict (tenant_id, source, external_ref) where external_ref is not null
  do update set
    account_id  = coalesce(excluded.account_id, support_tickets.account_id),
    subject     = excluded.subject,
    body        = coalesce(excluded.body, support_tickets.body),
    status      = excluded.status,
    priority    = excluded.priority,
    resolved_at = case when excluded.status = 'resolved'
                       then coalesce(support_tickets.resolved_at, now()) else null end,
    updated_at  = now()
  returning id into v_id;

  return jsonb_build_object('ticket_id', v_id, 'account_id', v_account,
                            'status', v_status, 'priority', v_priority);
end;
$function$;

CREATE OR REPLACE FUNCTION public.upsert_inbox_watch_state(p_tenant_id uuid, p_connector_id uuid, p_external_ref text, p_timestamp timestamp with time zone)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
begin
  insert into inbox_watch_state (tenant_id, connector_id, last_seen_external_ref, last_seen_timestamp, last_polled_at)
  values (p_tenant_id, p_connector_id, p_external_ref, p_timestamp, now())
  on conflict (tenant_id, connector_id) do update set
    last_seen_external_ref = excluded.last_seen_external_ref,
    last_seen_timestamp = excluded.last_seen_timestamp,
    last_polled_at = now(),
    updated_at = now();
end;
$function$;

CREATE OR REPLACE FUNCTION public.upsert_kpi_metric(p_metric_key text, p_label text, p_direction text DEFAULT 'higher'::text, p_unit text DEFAULT NULL::text, p_description text DEFAULT NULL::text, p_source text DEFAULT 'manual'::text, p_source_config jsonb DEFAULT NULL::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tenant uuid := auth_tenant_id();
  v_id     uuid;
  v_source text := coalesce(nullif(btrim(p_source), ''), 'manual');
  v_cfg    jsonb;
  v_bad    text;
begin
  if v_tenant is null then raise exception 'not_authenticated'; end if;
  if not auth_has_tenant_role(array['tenant_owner','tenant_admin']) then raise exception 'insufficient_role'; end if;
  if p_metric_key !~ '^[a-z0-9_]{2,60}$' then
    raise exception 'metric_key must be lowercase letters, numbers and underscores';
  end if;
  -- A tenant may not shadow a built-in key; that would silently change
  -- which value the computed lookup returns.
  if exists (select 1 from kpi_metric_catalog where tenant_id is null and metric_key = p_metric_key) then
    raise exception 'metric_key_reserved: % is a built-in metric', p_metric_key;
  end if;

  if v_source not in ('manual', 'action') then
    raise exception 'source_not_supported: % — a workspace metric is manual (you record it) or action (the platform counts it)', v_source;
  end if;

  if v_source = 'manual' then
    if p_source_config is not null and p_source_config <> '{}'::jsonb then
      raise exception 'source_config_not_allowed: a manual metric takes no source_config';
    end if;
    -- NOT NULL with default {} — see the suite note above: setting this
    -- to NULL broke the EXISTING manual path, which is the path that already
    -- worked. Caught only because the suite tested the old behaviour too.
    v_cfg := '{}'::jsonb;
  else
    v_cfg := coalesce(p_source_config, '{}'::jsonb);
    if jsonb_typeof(v_cfg) <> 'object' then
      raise exception 'source_config_must_be_an_object';
    end if;
    -- An unrecognised key is NOT harmless: the arm treats a missing filter as
    -- "match everything", so a typo turns a narrow metric into a count of all
    -- actions. Refuse instead of measuring the wrong thing quietly.
    select string_agg(k, ', ') into v_bad
      from jsonb_object_keys(v_cfg) k
     where k not in ('agg', 'category', 'action_label');
    if v_bad is not null then
      raise exception 'source_config_unknown_key: % — only agg, category, action_label', v_bad;
    end if;
    if coalesce(v_cfg->>'agg', 'count') not in ('count', 'auto_rate') then
      raise exception 'source_config_agg_invalid: % — count or auto_rate', v_cfg->>'agg';
    end if;
    if coalesce(v_cfg->>'category', '') <> ''
       and not exists (select 1 from system_categories sc where sc.key = v_cfg->>'category') then
      raise exception 'source_config_category_unknown: %', v_cfg->>'category';
    end if;
  end if;

  insert into kpi_metric_catalog (tenant_id, metric_key, label, direction, unit, description, source, source_config)
  values (v_tenant, p_metric_key, p_label, coalesce(p_direction,'higher'), p_unit, p_description, v_source, v_cfg)
  on conflict (tenant_id, metric_key) where tenant_id is not null
  do update set label = excluded.label, direction = excluded.direction,
                unit = excluded.unit, description = excluded.description,
                -- Without these two, a metric could never be switched from
                -- manual to computed after it was first created — which is
                -- the whole point of this migration.
                source = excluded.source, source_config = excluded.source_config
  returning id into v_id;
  return v_id;
end$function$;

CREATE OR REPLACE FUNCTION public.upsert_tenant_skill(p_skill_key text, p_name text, p_category text, p_description text DEFAULT NULL::text, p_signal_label text DEFAULT NULL::text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tenant uuid := auth_tenant_id(); v_key text;
BEGIN
  IF v_tenant IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  IF NOT auth_has_tenant_role(ARRAY['tenant_owner','tenant_admin']) THEN RAISE EXCEPTION 'insufficient_role'; END IF;
  IF p_skill_key !~ '^[a-z0-9_]{2,60}$' THEN
    RAISE EXCEPTION 'skill_key must be lowercase letters, numbers and underscores';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM skill_categories WHERE key = p_category AND (tenant_id IS NULL OR tenant_id = v_tenant)
  ) THEN
    RAISE EXCEPTION 'unknown_skill_category: %', p_category;
  END IF;

  -- Namespaced so one tenant's "refunds" never collides with another's.
  v_key := 't' || substr(replace(v_tenant::text, '-', ''), 1, 8) || '_' || p_skill_key;

  -- description / signal_label are NOT NULL on this table; fall back to the
  -- name rather than making the caller supply boilerplate.
  INSERT INTO skill_catalog (tenant_id, skill_key, name, category, description, signal_label, higher_is_better, min_sample, sort_order)
  VALUES (v_tenant, v_key, p_name, p_category,
          coalesce(nullif(p_description, ''), p_name),
          coalesce(nullif(p_signal_label, ''), 'Assessed from work signals'),
          true, 5, 500)
  ON CONFLICT (skill_key) DO UPDATE
    SET name = excluded.name, category = excluded.category,
        description = excluded.description, signal_label = excluded.signal_label
    WHERE skill_catalog.tenant_id = v_tenant;   -- never overwrite a built-in
  RETURN v_key;
END$function$;

CREATE OR REPLACE FUNCTION public.validate_onboarding_items(p_items jsonb, p_tenant_id uuid)
 RETURNS text[]
 LANGUAGE plpgsql
 STABLE
AS $function$
declare
  v_errors       text[] := '{}';
  v_item         jsonb;
  v_verify       jsonb;
  v_keys         text[] := '{}';
  v_key          text;
  v_n            integer;
  v_match        text;
  v_action_key   text;
  v_params       jsonb;
  v_schema       jsonb;
  v_schema_item  jsonb;
  v_pkey         text;
  v_pval         jsonb;
  v_category     text;
  v_verdict      jsonb;
  v_desk_unknown boolean := false;
begin
  -- A validator that cannot decide must refuse, not guess. With a NULL tenant
  -- the reachability rule below matches no connectors and would reject every
  -- binding ever written — a silent, total refusal that looks exactly like a
  -- correctly-strict validator. Fail loudly at the call site instead.
  if p_tenant_id is null then
    raise exception 'validate_onboarding_items: p_tenant_id is required — reachability cannot be decided without a workspace';
  end if;

  if p_items is null or jsonb_typeof(p_items) <> 'array' then
    return array['items must be a JSON array'];
  end if;
  v_n := jsonb_array_length(p_items);
  -- ::text on these four literals is a BUG FIX from mig 685, not a style
  -- choice. Without it `text[] || <unknown literal>` resolves to
  -- anyarray||anyarray and throws 22P02 instead of appending the message.
  if v_n < 1 then v_errors := v_errors || 'template needs at least 1 item'::text; end if;
  if v_n > 50 then v_errors := v_errors || 'template cannot exceed 50 items'::text; end if;

  for v_item in select * from jsonb_array_elements(p_items) loop
    v_key := coalesce(v_item->>'key', '');
    if v_key = '' then
      v_errors := v_errors || 'every item needs a non-empty key'::text;
    elsif v_key = any(v_keys) then
      v_errors := v_errors || format('duplicate item key "%s"', v_key);
    end if;
    v_keys := v_keys || v_key;
    if coalesce(v_item->>'label', '') = '' then
      v_errors := v_errors || format('item "%s" needs a label', v_key);
    end if;
    -- mig 685: 'handoff' added. A support/success handover happens AFTER
    -- go-live, so the vocabulary needed a sixth phase; the go-live rule at the
    -- bottom of this function is unchanged and still enforced.
    if coalesce(v_item->>'phase', '') not in ('kickoff', 'data', 'config', 'validation', 'golive', 'handoff') then
      v_errors := v_errors || format('item "%s" has an invalid phase', v_key);
    end if;
    if coalesce(v_item->>'owner_type', '') not in ('human', 'de', 'either') then
      v_errors := v_errors || format('item "%s" has an invalid owner_type', v_key);
    end if;
    if coalesce((v_item->>'requires_signoff')::boolean, false)
       and coalesce(v_item->>'owner_type', '') = 'de' then
      v_errors := v_errors || format('sign-off item "%s" must be owned by human or either — a DE cannot sign off its own work', v_key);
    end if;

    v_verify := v_item->'verify';
    if v_verify is not null and jsonb_typeof(v_verify) = 'object' then
      if coalesce(v_item->>'owner_type', '') = 'human' then
        v_errors := v_errors || format('item "%s" is human-owned — automated verification only applies to de/either items', v_key);
      end if;
      if coalesce(v_verify->>'category', '') not in
        ('crm', 'helpdesk', 'knowledge_base', 'erp_financials', 'billing', 'payroll_hcm', 'pos', 'product_system', 'other') then
        v_errors := v_errors || format('item "%s" has an invalid verify.category', v_key);
      end if;
      if coalesce(v_verify->>'op', '') = '' then
        v_errors := v_errors || format('item "%s" needs a verify.op', v_key);
      end if;
      v_match := coalesce(v_verify->>'match', '');
      if v_match not in ('exists', 'contains') then
        v_errors := v_errors || format('item "%s" has an invalid verify.match (must be exists or contains)', v_key);
      end if;
      if v_match = 'contains' and coalesce(v_verify->>'contains_text', '') = '' then
        v_errors := v_errors || format('item "%s" verify.match=contains needs contains_text', v_key);
      end if;
      if coalesce(v_verify->>'query_template', '') = '' and coalesce(v_verify->>'ref_template', '') = '' then
        v_errors := v_errors || format('item "%s" needs a verify.query_template or verify.ref_template', v_key);
      end if;
    end if;

    -- ---- action binding rules (a)-(g) ----
    -- (a)-(e) mig 674, (f) mig 681, (g) mig 693. (b) and (f) now read their
    -- answer from onboarding_verb_verdict; their wording is unchanged.
    v_action_key := v_item->>'action_key';
    if v_action_key is not null and v_action_key <> '' then
      -- (a) an item that names a verb must be DE-owned; a human or "either"
      -- item cannot be bound to automated execution.
      if coalesce(v_item->>'owner_type', '') <> 'de' then
        v_errors := v_errors || format('item "%s" names an action but owner_type must be "de" to bind one', v_key);
      end if;

      v_verdict  := public.onboarding_verb_verdict(p_tenant_id, v_action_key);
      -- jsonb_build_object turns a SQL NULL into the jsonb null 'null', which
      -- is NOT NULL — without this nullif every unreachable verb would carry a
      -- non-null "schema" and rules (c)-(e) would iterate over it.
      v_schema   := nullif(v_verdict->'param_schema', 'null'::jsonb);
      v_category := v_verdict->>'category';

      if not coalesce((v_verdict->>'reachable')::boolean, false) then
        -- (f) then (b): no connected system that can run it, or no such verb.
        if not coalesce((v_verdict->>'visible')::boolean, false) then
          v_errors := v_errors || format('item "%s" names action_key "%s" which has no active action definition visible to this workspace', v_key, v_action_key);
        else
          v_errors := v_errors || format('item "%s" names action_key "%s" but this workspace has no connected %s system that can run it — connect one, or bind a different verb', v_key, v_action_key, coalesce(v_category, 'matching'));
        end if;

      elsif not coalesce((v_verdict->>'desk_known')::boolean, false) then
        -- (g) SKIPPED, loudly. No employee has been given onboarding work in
        -- this workspace yet, so there is nobody to check the role against.
        -- Failing here would make a fresh workspace unable to publish at all.
        v_desk_unknown := true;

      elsif not coalesce((v_verdict->>'role_ok')::boolean, false) then
        -- (g) ROLE REACHABILITY. The verb is reachable by connector and still
        -- dead: it demands a role the onboarding desk does not hold, so
        -- get_agentic_tools_for_de never offers it, de-work never declares
        -- perform_onboarding_item, and the item can never be executed.
        v_errors := v_errors || format(
          'item "%s" names action_key "%s", which needs the "%s" role — the employee(s) this workspace gives onboarding work to (%s) do not have it, so it never reaches their tool list and the item could never run. Bind a verb they can run, or give onboarding to an employee that holds that role',
          v_key, v_action_key,
          coalesce(v_verdict->>'required_roles', 'required'),
          coalesce(v_verdict->>'desk', 'none named'));
      end if;

      if v_schema is not null then
        v_params := v_item->'params';
        if v_params is null then
          v_params := '{}'::jsonb;
        end if;
        if jsonb_typeof(v_params) <> 'object' then
          v_errors := v_errors || format('item "%s" params must be an object', v_key);
        else
          -- (c) every params value must be '@account', '@ask', or a scalar
          -- literal — never an object/array/null a later step could misread.
          for v_pkey, v_pval in select key, value from jsonb_each(v_params) loop
            if jsonb_typeof(v_pval) not in ('string', 'number', 'boolean') then
              v_errors := v_errors || format('item "%s" param "%s" must be "@account", "@ask", or a scalar literal', v_key, v_pkey);
            end if;
          end loop;

          -- (e) params may not name a parameter the verb does not have — a
          -- typo must be caught here, not silently dropped at execution time.
          for v_pkey in select jsonb_object_keys(v_params) loop
            if not exists (
              select 1 from jsonb_array_elements(v_schema) s where s->>'name' = v_pkey
            ) then
              v_errors := v_errors || format('item "%s" names parameter "%s" which action "%s" does not have', v_key, v_pkey, v_action_key);
            end if;
          end loop;

          -- (d) every REQUIRED param of the verb must appear as a key —
          -- named, not necessarily answered yet; '@ask' satisfies this.
          for v_schema_item in select * from jsonb_array_elements(v_schema) loop
            if coalesce((v_schema_item->>'required')::boolean, false)
               and not (v_params ? (v_schema_item->>'name')) then
              v_errors := v_errors || format('item "%s" is missing required parameter "%s" for action "%s"', v_key, v_schema_item->>'name', v_action_key);
            end if;
          end loop;
        end if;
      end if;
    end if;
  end loop;

  if not exists (
    select 1 from jsonb_array_elements(p_items) i where i->>'phase' = 'golive'
  ) then
    v_errors := v_errors || 'template needs at least one go-live phase item'::text;
  end if;

  -- A skipped check that says nothing is indistinguishable from a check that
  -- passed. This is the only channel a text[]-returning validator has that is
  -- not an error the publish would be blocked on.
  if v_desk_unknown then
    raise notice 'validate_onboarding_items: role reachability NOT CHECKED for workspace % — no employee owns an onboarding watcher and no onboarding case has ever been opened, so there is nobody to check the verb against. Bindings were accepted on connector reachability alone.', p_tenant_id;
  end if;

  return v_errors;
end;
$function$;

CREATE OR REPLACE FUNCTION public.validate_trust_ladder(p_ladder jsonb, p_uses_confidence boolean, p_uses_amount boolean, p_max_level integer DEFAULT 3)
 RETURNS integer
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE
  v_n int; v_e jsonb; v_settings jsonb;
  v_name text; v_mode text;
  v_lvl numeric; v_level int;
  v_seen int[] := '{}';
  v_rank int; v_prev_rank int := 0;  -- the implicit level-0 floor ranks as draft
  v_conf numeric; v_prev_conf numeric := NULL;
  v_amt numeric; v_prev_amt numeric := NULL;
BEGIN
  IF p_max_level IS NULL OR p_max_level < 1 OR p_max_level > 3 THEN
    RAISE EXCEPTION 'max_level must be between 1 and 3, got %', p_max_level;
  END IF;
  IF jsonb_typeof(p_ladder) IS DISTINCT FROM 'array' THEN
    RAISE EXCEPTION 'ladder must be a JSON array of levels';
  END IF;
  v_n := jsonb_array_length(p_ladder);
  IF v_n < 1 OR v_n > p_max_level THEN
    RAISE EXCEPTION 'a ladder has 1 to % stored levels (level 0 is implicit and always human-gated), got %', p_max_level, v_n;
  END IF;

  -- Pass 1 (array order): shape + the level key. REQUIRED, integer, unique,
  -- 1..p_max_level — reject otherwise. Level 0 is never stored.
  FOR i IN 0 .. v_n - 1 LOOP
    v_e := p_ladder -> i;
    IF jsonb_typeof(v_e) <> 'object' THEN
      RAISE EXCEPTION 'ladder entry %: each level must be an object', i;
    END IF;
    IF EXISTS (SELECT 1 FROM jsonb_object_keys(v_e) k
                WHERE k NOT IN ('level', 'name', 'mode', 'settings')) THEN
      RAISE EXCEPTION 'ladder entry %: unknown field — allowed: level, name, mode, settings', i;
    END IF;
    IF NOT (v_e ? 'level') OR jsonb_typeof(v_e -> 'level') <> 'number' THEN
      RAISE EXCEPTION 'ladder entry %: an explicit integer "level" is required', i;
    END IF;
    v_lvl := (v_e ->> 'level')::numeric;
    IF v_lvl <> trunc(v_lvl) THEN
      RAISE EXCEPTION 'ladder entry %: "level" must be a whole number', i;
    END IF;
    v_level := v_lvl::int;
    IF v_level < 1 OR v_level > p_max_level THEN
      RAISE EXCEPTION 'ladder entry %: "level" must be between 1 and % (level 0 is implicit and always human-gated)', i, p_max_level;
    END IF;
    IF v_level = ANY (v_seen) THEN
      RAISE EXCEPTION 'ladder entry %: duplicate level % — each level may be defined once', i, v_level;
    END IF;
    v_seen := v_seen || v_level;
  END LOOP;

  -- Pass 2 (LEVEL order): names, modes and monotonicity — modes never narrow
  -- and limits only widen as levels rise.
  FOR v_e IN
    SELECT e.entry FROM jsonb_array_elements(p_ladder) e(entry)
    ORDER BY (e.entry ->> 'level')::integer
  LOOP
    v_level := (v_e ->> 'level')::integer;

    v_name := trim(coalesce(v_e ->> 'name', ''));
    IF v_name = '' OR length(v_name) > 80 THEN
      RAISE EXCEPTION 'ladder level %: a name of 1-80 characters is required', v_level;
    END IF;

    v_mode := v_e ->> 'mode';
    IF v_mode IS NULL
       OR v_mode NOT IN ('draft', 'act_with_approval', 'act_within_limits', 'act') THEN
      RAISE EXCEPTION 'ladder level %: mode must be draft, act_with_approval, act_within_limits or act', v_level;
    END IF;
    v_rank := CASE v_mode WHEN 'draft' THEN 0 WHEN 'act_with_approval' THEN 1
                          WHEN 'act_within_limits' THEN 2 ELSE 3 END;
    IF v_rank < v_prev_rank THEN
      RAISE EXCEPTION 'ladder level %: modes must not narrow as levels rise', v_level;
    END IF;
    v_prev_rank := v_rank;

    v_settings := coalesce(v_e -> 'settings', '{}'::jsonb);
    IF jsonb_typeof(v_settings) <> 'object' THEN
      RAISE EXCEPTION 'ladder level %: settings must be an object', v_level;
    END IF;
    -- Only fields this capability's enforcement actually reads may be set.
    -- ('enabled' is never a settings key — it is derived from the mode by
    -- trust_ladder_settings, the M1 reader.)
    IF EXISTS (SELECT 1 FROM jsonb_object_keys(v_settings) k
                WHERE NOT (k = 'min_confidence'   AND p_uses_confidence)
                  AND NOT (k = 'max_amount_cents' AND p_uses_amount)) THEN
      RAISE EXCEPTION 'ladder level %: settings may only carry the field(s) this capability enforces (%)',
        v_level, concat_ws(', ',
              CASE WHEN p_uses_confidence THEN 'min_confidence' END,
              CASE WHEN p_uses_amount     THEN 'max_amount_cents' END);
    END IF;
    IF v_mode IN ('draft', 'act_with_approval') AND v_settings <> '{}'::jsonb THEN
      RAISE EXCEPTION 'ladder level %: % levels take no settings — nothing executes without a human there', v_level, v_mode;
    END IF;
    IF v_mode = 'act_within_limits' AND v_settings = '{}'::jsonb THEN
      RAISE EXCEPTION 'ladder level %: act_within_limits requires at least one limit', v_level;
    END IF;

    IF v_settings ? 'min_confidence' THEN
      IF jsonb_typeof(v_settings -> 'min_confidence') <> 'number' THEN
        RAISE EXCEPTION 'ladder level %: min_confidence must be a number', v_level;
      END IF;
      v_conf := (v_settings ->> 'min_confidence')::numeric;
      IF v_conf <> trunc(v_conf) OR v_conf < 0 OR v_conf > 100 THEN
        RAISE EXCEPTION 'ladder level %: min_confidence must be a whole number between 0 and 100', v_level;
      END IF;
      IF v_prev_conf IS NOT NULL AND v_conf > v_prev_conf THEN
        RAISE EXCEPTION 'ladder level %: confidence floors must not RISE with level — higher trust means a lower floor', v_level;
      END IF;
      v_prev_conf := v_conf;
    END IF;

    IF v_settings ? 'max_amount_cents' THEN
      IF jsonb_typeof(v_settings -> 'max_amount_cents') <> 'number' THEN
        RAISE EXCEPTION 'ladder level %: max_amount_cents must be a number', v_level;
      END IF;
      v_amt := (v_settings ->> 'max_amount_cents')::numeric;
      IF v_amt <> trunc(v_amt) OR v_amt <= 0 THEN
        RAISE EXCEPTION 'ladder level %: max_amount_cents must be a whole number above zero', v_level;
      END IF;
      IF v_prev_amt IS NOT NULL AND v_amt < v_prev_amt THEN
        RAISE EXCEPTION 'ladder level %: amount caps must not SHRINK with level — higher trust means a higher cap', v_level;
      END IF;
      v_prev_amt := v_amt;
    END IF;
  END LOOP;

  RETURN v_n;
END $function$;

CREATE OR REPLACE FUNCTION public.validate_watcher_config(p_kind text, p_config jsonb, p_tenant_id uuid, p_de_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  c    jsonb := coalesce(p_config, '{}'::jsonb);
  src  text  := coalesce(p_config->>'source', 'customer_accounts');
  s    watch_source_catalog;
  f    watch_source_fields;
  v_op text := coalesce(c->>'op', '');
  v_datef text;
  v_grant_ok boolean;
  v_rw jsonb; v_ru text; v_ra text;
BEGIN
  -- ── the response window: a DECLARED service standard ──────────────────────
  -- Settable on any watcher that opens a case from a condition, in minutes,
  -- hours, days, or as a specific calendar date. Refused at write time when
  -- malformed, because a typo would otherwise silently mean "no deadline" —
  -- which reads identically to "nobody has declared one", and telling those two
  -- apart is the entire point of the field.
  IF c ? 'response_window' THEN
    v_rw := c->'response_window';
    IF jsonb_typeof(v_rw) <> 'object' THEN
      RETURN 'Set a response window as an amount and a unit, or as a specific date.';
    END IF;
    v_ru := v_rw->>'unit'; v_ra := v_rw->>'amount';

    -- A date watcher already HAS a deadline: the date it counts down to. A
    -- second one would compete with it, and there is no honest way to say which
    -- of two deadlines is the real one.
    IF p_kind = 'date_horizon' THEN
      RETURN 'This watcher already has a deadline — the date it counts down to.';
    END IF;

    IF v_ru = 'date' THEN
      IF v_rw->>'at' IS NULL THEN
        RETURN 'Pick the date this has to be handled by.';
      END IF;
      BEGIN
        PERFORM (v_rw->>'at')::timestamptz;
      EXCEPTION WHEN OTHERS THEN
        RETURN 'That deadline is not a real date.';
      END;
    ELSIF v_ru IN ('minutes','hours','days') THEN
      IF v_ra IS NULL OR v_ra !~ '^[0-9]{1,9}$' OR v_ra::bigint < 1 THEN
        RETURN format('Respond within how many %s? Give a whole number above zero.', v_ru);
      END IF;
      IF (v_ru = 'minutes' AND v_ra::bigint > 5256000)
      OR (v_ru = 'hours'   AND v_ra::bigint > 87600)
      OR (v_ru = 'days'    AND v_ra::bigint > 3650) THEN
        RETURN 'A response window longer than ten years is not a deadline.';
      END IF;
    ELSE
      RETURN 'A response window is set in minutes, hours, days, or by a specific date.';
    END IF;
  END IF;

  IF p_kind IN ('date_horizon','state_condition') THEN
    SELECT * INTO s FROM watch_source_catalog WHERE source_key = src AND active;
    IF s.source_key IS NULL THEN
      RETURN format('There is no watchable source called "%s" here.', src);
    END IF;
    IF NOT (p_kind = ANY (s.supports_kinds)) THEN
      RETURN format('"%s" can''t be watched by %s.', src, replace(p_kind, '_', ' '));
    END IF;

    IF p_kind = 'date_horizon' THEN
      v_datef := coalesce(c->>'date_field',
                   (SELECT column_name FROM watch_source_fields
                     WHERE source_key = src AND role = 'date' ORDER BY column_name LIMIT 1));
      IF v_datef IS NULL OR NOT EXISTS (
           SELECT 1 FROM watch_source_fields
            WHERE source_key = src AND role = 'date' AND column_name = v_datef) THEN
        RETURN format('"%s" isn''t a date we can count down to on %s.',
                      coalesce(c->>'date_field', '(none)'), src);
      END IF;
      IF c ? 'horizons_days' AND jsonb_typeof(c->'horizons_days') <> 'array' THEN
        RETURN 'Reminder windows must be a list like [90, 60, 30].';
      END IF;

    ELSE  -- state_condition
      SELECT * INTO f FROM watch_source_fields
        WHERE source_key = src AND role = 'state' AND column_name = c->>'field';
      IF f.column_name IS NULL THEN
        RETURN format('"%s" isn''t a state we can watch on %s.',
                      coalesce(c->>'field', '(none)'), src);
      END IF;
      IF NOT (v_op = ANY (f.allowed_ops)) THEN
        RETURN format('"%s" can''t be compared with "%s".', f.column_name, v_op);
      END IF;
      IF c->>'value' IS NULL THEN RETURN 'This condition needs a value.'; END IF;
      IF f.value_type = 'numeric' AND (c->>'value') !~ '^-?[0-9]+(\.[0-9]+)?$' THEN
        RETURN format('"%s" needs a number.', f.column_name);
      END IF;
    END IF;

    IF s.require_domain_grant THEN
      SELECT EXISTS (SELECT 1 FROM data_access_grants g
                      WHERE g.tenant_id = p_tenant_id AND g.subject_kind = 'de'
                        AND g.subject_id = p_de_id
                        AND g.resource_category = s.domain_category)
        INTO v_grant_ok;
      IF NOT v_grant_ok THEN
        RETURN format('This employee isn''t cleared to work %s.',
                      coalesce(s.domain_category, src));
      END IF;
    END IF;

  ELSIF p_kind = 'metric_threshold' THEN
    IF c->>'metric_key' IS NULL THEN RETURN 'A metric watcher needs a metric.'; END IF;
    IF NOT (v_op IN ('lt','gt'))  THEN RETURN 'A metric watcher uses above/below only.'; END IF;
    IF c->>'value' IS NULL        THEN RETURN 'A metric watcher needs a threshold.'; END IF;
  ELSIF p_kind = 'schedule' THEN
    IF coalesce((c->>'interval_minutes')::int, 0) < 60 THEN
      RETURN 'A recurring schedule must run at least hourly.';
    END IF;
  ELSE
    RETURN format('"%s" isn''t an installable watcher kind.', p_kind);
  END IF;
  RETURN NULL;
END $function$;

CREATE OR REPLACE FUNCTION public.validate_work_watcher()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE v_err text;
BEGIN
  IF TG_OP = 'UPDATE'
     AND NEW.config IS NOT DISTINCT FROM OLD.config
     AND NEW.kind   IS NOT DISTINCT FROM OLD.kind THEN
    RETURN NEW;  -- only active/next_fire_at/bookkeeping changed → no re-validation
  END IF;
  v_err := public.validate_watcher_config(NEW.kind, NEW.config, NEW.tenant_id, NEW.de_id);
  IF v_err IS NOT NULL THEN
    RAISE EXCEPTION '%', v_err;
  END IF;
  RETURN NEW;
END $function$;

CREATE OR REPLACE FUNCTION public.verified_domain_tenant(p_email_or_domain text)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_tenant uuid;
BEGIN
  -- Named explicitly. NEVER written as "if auth.uid() is null then trust" —
  -- anon also has a NULL uid, which is the exact bug migration 369 fixed.
  IF coalesce(auth.role(), '') <> 'service_role' THEN
    RAISE EXCEPTION 'verified_domain_tenant is a backend-only lookup'
      USING ERRCODE = 'insufficient_privilege';
  END IF;

  SELECT d.tenant_id INTO v_tenant
    FROM tenant_domains d
    JOIN tenants t ON t.id = d.tenant_id
   WHERE d.status = 'verified'
     AND d.domain = public.normalize_email_domain(p_email_or_domain)
     AND coalesce(t.status, 'active') <> 'suspended'
   LIMIT 1;

  RETURN v_tenant;
END $function$;

CREATE OR REPLACE FUNCTION public.verify_and_bind_widget_identity(p_widget_key_id uuid, p_conversation_id uuid, p_end_user_ref text, p_account_ref text, p_user_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_tenant uuid; v_secret text; v_canon text; v_expected text; v_provided text;
  v_key text; v_account_id uuid; v_existing text; v_r bytea; v_ok boolean;
BEGIN
  SELECT tenant_id INTO v_tenant FROM widget_keys WHERE id = p_widget_key_id AND active;
  IF v_tenant IS NULL THEN
    RETURN jsonb_build_object('verified', false, 'reason', 'unknown_widget_key');
  END IF;

  SELECT secret INTO v_secret FROM widget_key_secrets WHERE widget_key_id = p_widget_key_id;
  IF v_secret IS NULL THEN
    -- No identity verification configured for this widget → legitimately
    -- unverified (expected, silent). Answers still flow; no identity memory.
    RETURN jsonb_build_object('verified', false, 'reason', 'no_secret');
  END IF;

  v_provided := lower(btrim(coalesce(p_user_hash, '')));
  IF v_provided = '' THEN
    RETURN jsonb_build_object('verified', false, 'reason', 'no_hash');
  END IF;

  v_key := nullif(lower(btrim(coalesce(p_end_user_ref, ''))), '');
  IF v_key IS NULL THEN
    RETURN jsonb_build_object('verified', false, 'reason', 'blank_ref');
  END IF;

  -- canonical(end_user_ref, account_ref) — account_ref BOUND into the signature
  v_canon := 'dtwidget.v1' || chr(10)
             || 'euid=' || b64url(p_end_user_ref) || chr(10)
             || 'acct=' || b64url(coalesce(p_account_ref, ''));
  v_expected := lower(encode(hmac(v_canon, v_secret, 'sha256'::text), 'hex'));

  -- constant-time compare via double-HMAC with a per-call random key: timing
  -- reveals nothing about v_expected because both sides are blinded by v_r.
  v_r := gen_random_bytes(32);
  v_ok := length(v_provided) = 64
          AND hmac(decode(v_provided, 'hex'), v_r, 'sha256'::text) = hmac(decode(v_expected, 'hex'), v_r, 'sha256'::text);
  IF NOT v_ok THEN
    RETURN jsonb_build_object('verified', false, 'reason', 'mismatch');
  END IF;

  -- account_id resolved ONLY from the tenant allow-list, keyed on the verified ref
  SELECT account_id INTO v_account_id FROM customer_account_contacts
    WHERE tenant_id = v_tenant AND lower(btrim(end_user_ref)) = v_key;

  -- immutable bind: never rebind a conversation already carrying a DIFFERENT key
  SELECT verified_identity_key INTO v_existing FROM de_conversations
    WHERE id = p_conversation_id AND tenant_id = v_tenant;
  IF v_existing IS NOT NULL AND v_existing <> v_key THEN
    -- possible hijack (someone else's verified thread) → deny memory this turn
    RETURN jsonb_build_object('verified', false, 'reason', 'identity_conflict');
  END IF;
  IF v_existing IS NULL THEN
    UPDATE de_conversations
       SET identity_verified = true, verified_identity_key = v_key,
           identity_method = 'widget_hmac',
           account_id = COALESCE(account_id, v_account_id)
     WHERE id = p_conversation_id AND tenant_id = v_tenant;
  ELSIF v_account_id IS NOT NULL THEN
    -- same identity already bound; fill account_id if it wasn't set before
    UPDATE de_conversations SET account_id = COALESCE(account_id, v_account_id)
     WHERE id = p_conversation_id AND tenant_id = v_tenant;
  END IF;

  RETURN jsonb_build_object(
    'verified', true,
    'method', 'widget_hmac',
    'verified_key', v_key,
    'memory_ref', 'widget_hmac:' || v_key,   -- method-namespaced (no cross-method stitch)
    'account_id', v_account_id);
END $function$;

CREATE OR REPLACE FUNCTION public.verify_audit_chain(p_tenant_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare v_is_active boolean;
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    select coalesce(is_active, true) into v_is_active
      from profiles where user_id = auth.uid() and tenant_id = p_tenant_id;
    if v_is_active is null or not v_is_active then
      raise exception 'not a member of this tenant';
    end if;
  end if;
  return public.verify_audit_chain_internal(p_tenant_id);
end $function$;

CREATE OR REPLACE FUNCTION public.verify_audit_chain_internal(p_tenant_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_total     bigint;
  v_reachable bigint;
  v_genesis   bigint;
  v_bad       uuid;
  v_forks     int := 0;
  v_known     int := 0;
  r           record;
  v_reg       public.audit_chain_anomalies;
begin
  select count(*) into v_total from audit_events where tenant_id = p_tenant_id;
  if v_total = 0 then
    return jsonb_build_object('intact', true, 'checked', 0, 'broken_at', null,
      'reason', null, 'forks', 0, 'known_anomalies', 0);
  end if;

  -- CONTENT. Order-independent, and the check that actually catches an edit:
  -- each row's hash must be the digest of its own stored contents.
  select e.id into v_bad
    from audit_events e
   where e.tenant_id = p_tenant_id
     and e.hash <> encode(digest(
           coalesce(e.prev_hash, '') || e.tenant_id::text || coalesce(e.action, '') ||
           coalesce(e.detail::text, '{}') || e.created_at::text, 'sha256'), 'hex')
   limit 1;
  if v_bad is not null then
    return jsonb_build_object('intact', false, 'checked', v_total, 'broken_at', v_bad,
      'reason', 'content_hash_mismatch', 'forks', 0, 'known_anomalies', 0);
  end if;

  -- GENESIS: exactly one root.
  select count(*) into v_genesis
    from audit_events where tenant_id = p_tenant_id and coalesce(prev_hash, '') = '';
  if v_genesis <> 1 then
    return jsonb_build_object('intact', false, 'checked', v_total, 'broken_at', null,
      'reason', format('expected exactly one genesis row, found %s', v_genesis),
      'forks', 0, 'known_anomalies', 0);
  end if;

  -- REACHABILITY: follow the linkage from genesis. Every row must be reached.
  -- Each row stores exactly one prev_hash, so no row can be visited twice; a
  -- shortfall means a row was deleted mid-chain or never linked in. The old
  -- verifier could not detect either.
  with recursive w as (
    select e.id, e.hash from audit_events e
     where e.tenant_id = p_tenant_id and coalesce(e.prev_hash, '') = ''
    union all
    select e.id, e.hash from audit_events e
      join w on e.prev_hash = w.hash
     where e.tenant_id = p_tenant_id)
  select count(*) into v_reachable from w;

  if v_reachable <> v_total then
    return jsonb_build_object('intact', false, 'checked', v_reachable, 'broken_at', null,
      'reason', format('%s of %s rows unreachable from genesis', v_total - v_reachable, v_total),
      'forks', 0, 'known_anomalies', 0);
  end if;

  -- LINEARITY: a parent with two children is a fork. Known ones are reported;
  -- an unknown one, or a known one whose membership changed, fails.
  for r in
    select e.prev_hash as parent, array_agg(e.id order by e.id) as kids
      from audit_events e
     where e.tenant_id = p_tenant_id and coalesce(e.prev_hash, '') <> ''
     group by e.prev_hash having count(*) > 1
  loop
    v_forks := v_forks + 1;
    select * into v_reg from audit_chain_anomalies
     where tenant_id = p_tenant_id and parent_hash = r.parent;

    if v_reg.id is null then
      return jsonb_build_object('intact', false, 'checked', v_total, 'broken_at', r.kids[1],
        'reason', 'unregistered fork: two records share a parent',
        'forks', v_forks, 'known_anomalies', v_known);
    end if;

    if v_reg.child_event_ids <> r.kids then
      return jsonb_build_object('intact', false, 'checked', v_total, 'broken_at', r.kids[1],
        'reason', 'records at a known fork changed since it was recorded',
        'forks', v_forks, 'known_anomalies', v_known);
    end if;
    v_known := v_known + 1;
  end loop;

  -- A registered anomaly whose fork no longer exists means rows went missing.
  if (select count(*) from audit_chain_anomalies where tenant_id = p_tenant_id) <> v_known then
    return jsonb_build_object('intact', false, 'checked', v_total, 'broken_at', null,
      'reason', 'a recorded anomaly no longer matches the log',
      'forks', v_forks, 'known_anomalies', v_known);
  end if;

  return jsonb_build_object('intact', true, 'checked', v_total, 'broken_at', null,
    'reason', null, 'forks', v_forks, 'known_anomalies', v_known);
end $function$;

CREATE OR REPLACE FUNCTION public.verify_de_delegation_token(p_raw text, p_required_scope text, p_expected_de uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare v_row de_delegation_tokens;
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'verify_de_delegation_token is service-role only';
  end if;
  update de_delegation_tokens
     set used_count = used_count + 1
   where token_hash = encode(digest(coalesce(p_raw, ''), 'sha256'), 'hex')
     and revoked_at is null
     and expires_at > now()
     and used_count < max_uses
     and p_required_scope = any(scopes)
     and (p_expected_de is null or de_id = p_expected_de)
   returning * into v_row;
  if v_row.id is null then return jsonb_build_object('valid', false); end if;
  return jsonb_build_object('valid', true, 'tenant_id', v_row.tenant_id, 'de_id', v_row.de_id,
                            'scopes', v_row.scopes, 'token_id', v_row.id,
                            'originating_kind', v_row.originating_kind, 'originating_ref', v_row.originating_ref);
end;
$function$;

CREATE OR REPLACE FUNCTION public.verify_de_system(p_de_id uuid, p_system_key text, p_entity_ref text, p_expectation jsonb, p_objective_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_read jsonb; v_actual jsonb; v_matched boolean := true; v_diffs jsonb := '[]'::jsonb;
  k text; v_exp text; v_act text; v_tenant uuid;
BEGIN
  SELECT tenant_id INTO v_tenant FROM digital_employees WHERE id = p_de_id;
  v_read := public.read_de_system(p_de_id, p_system_key, p_entity_ref);
  IF (v_read->>'ok') <> 'true' THEN RETURN v_read; END IF;
  v_actual := v_read->'record';

  FOR k IN SELECT jsonb_object_keys(p_expectation) LOOP
    v_exp := p_expectation->>k;
    v_act := v_actual->>k;
    IF v_exp IS DISTINCT FROM v_act THEN
      v_matched := false;
      v_diffs := v_diffs || jsonb_build_object('field', k, 'expected', v_exp, 'actual', v_act);
    END IF;
  END LOOP;

  INSERT INTO de_system_verifications (tenant_id, de_id, objective_id, system_key, entity_ref, expectation, actual, matched)
  VALUES (v_tenant, p_de_id, p_objective_id, p_system_key, p_entity_ref, p_expectation, v_actual, v_matched);

  RETURN jsonb_build_object('ok', true, 'matched', v_matched, 'diffs', v_diffs, 'actual', v_actual);
END; $function$;

CREATE OR REPLACE FUNCTION public.verify_decide_discovery_proposal()
 RETURNS text[]
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_caller          text;
  v_seen_role       text;
  v_notes           text[] := '{}';
  v_probes_done     integer := 0;
  v_abort           text;

  v_tenant          uuid;
  v_admin_uid       uuid;
  v_user_uid        uuid;
  v_other_tenant    uuid;
  v_other_admin     uuid;
  v_platform_uid    uuid;
  v_dim             text;

  v_prop_before     bigint;
  v_prop_after      bigint;
  v_sess_before     bigint;
  v_sess_after      bigint;
  v_conn_before     bigint;
  v_conn_after      bigint;
  v_audit_before    bigint;
  v_audit_after     bigint;
  v_leak_conn       bigint;
  v_leak_prop       bigint;
  v_admin_active    boolean;

  v_session         uuid;
  v_session_b       uuid;
  v_conn            uuid;
  v_conn_b          uuid;
  v_conn_other      uuid;
  v_prop            uuid;
  v_prop_b          uuid;
  v_prop_other      uuid;

  v_res             jsonb;
  v_res2            jsonb;

  -- one per probe: did the sub-block reach its sentinel? An aborted probe must
  -- not have its assertions evaluated against NULLs.
  v_d1              boolean := false;
  v_d3              boolean := false;
  v_d4              boolean := false;
  v_d5              boolean := false;
  v_d6              boolean := false;
  v_d7              boolean := false;

  -- ── added by 754, for probe 18 ──────────────────────────────────────────
  -- v_p18_topics is the FIXTURE the denominator is read off: every "expected"
  -- count in probe 18 is array_length(v_p18_topics, 1), never a literal. 752
  -- blocked on a probe that said 10 when it made 11.
  v_p18_topics      text[][];
  v_p18_expected    integer;
  v_p18_inserted    integer := 0;
  v_p18_accepted    integer := 0;
  v_p18_props       uuid[] := '{}';
  v_p18_rules       uuid[] := '{}';
  v_p18_prop        uuid;
  v_p18_rule        uuid;
  v_p18_rule_other  uuid;
  v_p18_ins_err     text[] := '{}';
  v_p18_acc_err     text[] := '{}';
  v_p18_first       jsonb;
  v_p18_rows        bigint;
  v_p18_cats        bigint;
  v_p18_ids         bigint;
  v_p18_orders      bigint;
  v_p18_cls_hit     text;
  v_p18_cls_miss    text;
  v_p18_cls_shadow  text;
  v_p18_dup_refused boolean;
  v_p18_dup_state   text;
  v_p18_new_ok      boolean;
  v_p18_new_err     text;
  -- ── added by the 754 FIX ROUND: the idempotency index, asked as a question.
  -- support_triage_rules_source_proposal_uq was described in this file as "the
  -- guarantee … enforced by the database rather than by the browser not
  -- clicking twice" and was pinned by NOTHING: a reviewer DROPPED it and got
  -- 18/18 probes, 262 assertions and zero findings. Probe 18(g2) drives the
  -- RPC's source_proposal_id CHECK, which is the stamp reading a column — not
  -- the database refusing a second row under the race the index exists for.
  v_p18_race_rule   uuid;
  v_p18_race_refused boolean;
  v_p18_race_state  text;
  v_p18_race_msg    text;
  v_p18_null_ok     boolean;
  v_p18_null_err    text;
  v_p18_own_n       bigint;
  v_p18_del_n       integer;
  v_p18_del_err     text;
  v_p18_still       bigint;
  v_p18_tagged      bigint;
  v_p18_untagged    bigint;
  v_p18_g1          text;
  v_p18_g2          text;
  v_p18_g3          text;
  v_p18_g4          text;
  v_p18_g5          text;
  v_p18_g5_order    integer;
  v_p18_g6          text;
  v_p18_g7          text;
  v_p18_g8          text;
  v_p18_user_refused boolean := false;
  v_p18_user_msg    text;
  v_p18_owner_ok    boolean := false;
  v_i               integer;
  v_d18             boolean := false;

  -- ── added by 760, for PROBE 19 — A TOPIC DECIDES WHO ANSWERS ───────────
  v_p19_de          uuid;     -- the employee hired in this session to own a topic
  v_p19_prop_emp    uuid;
  v_p19_prop        uuid;
  v_p19_rule        uuid;
  v_p19_res         jsonb;
