  CONSTRAINT continuity_cases_motion_check CHECK ((motion = ANY (ARRAY['renew'::text, 'extend'::text, 'early_renew'::text, 'reorder'::text, 'replenish'::text, 'replace'::text, 'upgrade'::text, 'downgrade'::text, 'expand'::text, 'contract'::text, 'consolidate'::text, 'split'::text, 'renegotiate'::text, 'pause'::text, 'terminate'::text, 'allow_expiry'::text, 'switch_supplier'::text]))),
  CONSTRAINT continuity_cases_party_side_check CHECK ((party_side = ANY (ARRAY['sell'::text, 'buy'::text]))),
  CONSTRAINT continuity_cases_probability_pct_check CHECK (((probability_pct IS NULL) OR ((probability_pct >= 0) AND (probability_pct <= 100)))),
  CONSTRAINT continuity_cases_readiness_score_check CHECK (((readiness_score IS NULL) OR ((readiness_score >= 0) AND (readiness_score <= 100)))),
  CONSTRAINT continuity_cases_risk_level_check CHECK (((risk_level IS NULL) OR (risk_level = ANY (ARRAY['low'::text, 'medium'::text, 'high'::text, 'critical'::text])))),
