CREATE TABLE IF NOT EXISTS public.semantic_guardrail_shadow_log (
  "id" uuid DEFAULT gen_random_uuid() NOT NULL,
  "tenant_id" uuid NOT NULL,
  "de_id" uuid,
  "surface" text NOT NULL,
  "verdict" text NOT NULL,
  "rule_id" uuid,
  "rationale" text,
  "content_preview" text,
  "created_at" timestamp with time zone DEFAULT now() NOT NULL,
  CONSTRAINT semantic_guardrail_shadow_log_pkey PRIMARY KEY (id)
);
CREATE TABLE IF NOT EXISTS public.sim_runs (
  "id" uuid DEFAULT gen_random_uuid() NOT NULL,
  "tenant_id" uuid NOT NULL,
  "de_id" uuid NOT NULL,
  "mode" text DEFAULT 'synthetic'::text NOT NULL,
  "status" text DEFAULT 'running'::text NOT NULL,
  "total" integer DEFAULT 0 NOT NULL,
  "passed" integer DEFAULT 0 NOT NULL,
  "failed" integer DEFAULT 0 NOT NULL,
  "avg_score" numeric DEFAULT 0 NOT NULL,
  "threshold_pct" integer DEFAULT 80 NOT NULL,
  "results" jsonb DEFAULT '[]'::jsonb NOT NULL,
  "created_by" uuid,
  "started_at" timestamp with time zone DEFAULT now() NOT NULL,
  "finished_at" timestamp with time zone,
  "candidate" boolean DEFAULT false NOT NULL,
  "config_fingerprint" text,
  CONSTRAINT sim_runs_mode_check CHECK ((mode = ANY (ARRAY['golden'::text, 'synthetic'::text, 'historical'::text]))),
  CONSTRAINT sim_runs_status_check CHECK ((status = ANY (ARRAY['running'::text, 'passed'::text, 'failed'::text, 'blocked_llm'::text, 'error'::text]))),
  CONSTRAINT sim_runs_pkey PRIMARY KEY (id)
);
CREATE TABLE IF NOT EXISTS public.skill_categories (
  "id" uuid DEFAULT gen_random_uuid() NOT NULL,
  "tenant_id" uuid,
  "key" text NOT NULL,
  "label" text NOT NULL,
  "sort_order" integer DEFAULT 100 NOT NULL,
  CONSTRAINT skill_categories_pkey PRIMARY KEY (id)
);
CREATE TABLE IF NOT EXISTS public.specialist_source_secrets (
  "source_id" uuid NOT NULL,
  "created_at" timestamp with time zone DEFAULT now() NOT NULL,
  "updated_at" timestamp with time zone DEFAULT now() NOT NULL,
  "secret_id" uuid,
  CONSTRAINT specialist_source_secrets_pkey PRIMARY KEY (source_id)
);
CREATE TABLE IF NOT EXISTS public.sso_attribute_role_map (
  "id" uuid DEFAULT gen_random_uuid() NOT NULL,
  "tenant_id" uuid NOT NULL,
  "attribute_name" text NOT NULL,
  "attribute_value" text NOT NULL,
  "role" text NOT NULL,
  "created_by" uuid,
  "created_at" timestamp with time zone DEFAULT now() NOT NULL,
  "updated_at" timestamp with time zone DEFAULT now() NOT NULL,
  CONSTRAINT sso_attribute_role_map_attribute_name_check CHECK (((length(btrim(attribute_name)) >= 1) AND (length(btrim(attribute_name)) <= 128))),
  CONSTRAINT sso_attribute_role_map_attribute_value_check CHECK (((length(btrim(attribute_value)) >= 1) AND (length(btrim(attribute_value)) <= 256))),
  CONSTRAINT sso_attribute_role_map_role_check CHECK ((role = ANY (ARRAY['tenant_user'::text, 'tenant_admin'::text]))),
  CONSTRAINT sso_attribute_role_map_pkey PRIMARY KEY (id)
);
CREATE TABLE IF NOT EXISTS public.staleness_escalations (
  "id" uuid DEFAULT gen_random_uuid() NOT NULL,
  "tenant_id" uuid NOT NULL,
  "target_kind" text NOT NULL,
  "target_id" uuid NOT NULL,
  "tier" text NOT NULL,
  "first_detected_at" timestamp with time zone DEFAULT now() NOT NULL,
  "last_escalated_at" timestamp with time zone DEFAULT now() NOT NULL,
  "resolved_at" timestamp with time zone,
  "human_task_id" uuid,
  "created_at" timestamp with time zone DEFAULT now() NOT NULL,
  CONSTRAINT staleness_escalations_tier_check CHECK ((tier = ANY (ARRAY['warning'::text, 'breach'::text]))),
  CONSTRAINT staleness_escalations_pkey PRIMARY KEY (id)
);
CREATE TABLE IF NOT EXISTS public.staleness_policies (
  "id" uuid DEFAULT gen_random_uuid() NOT NULL,
  "tenant_id" uuid NOT NULL,
  "target_kind" text NOT NULL,
  "warning_after" interval NOT NULL,
  "breach_after" interval NOT NULL,
  "enabled" boolean DEFAULT true NOT NULL,
  "created_at" timestamp with time zone DEFAULT now() NOT NULL,
  "updated_at" timestamp with time zone DEFAULT now() NOT NULL,
  CONSTRAINT staleness_policies_tier_order CHECK ((breach_after > warning_after)),
  CONSTRAINT staleness_policies_pkey PRIMARY KEY (id),
  CONSTRAINT staleness_policies_tenant_id_target_kind_key UNIQUE (tenant_id, target_kind)
);
CREATE TABLE IF NOT EXISTS public.support_tickets (
  "id" uuid DEFAULT gen_random_uuid() NOT NULL,
  "tenant_id" uuid NOT NULL,
  "account_id" uuid,
  "subject" text NOT NULL,
  "body" text DEFAULT ''::text NOT NULL,
  "status" text DEFAULT 'open'::text NOT NULL,
  "priority" text DEFAULT 'p3'::text NOT NULL,
  "assignee" text DEFAULT 'de'::text NOT NULL,
  "de_confidence" integer,
  "resolved_at" timestamp with time zone,
  "created_at" timestamp with time zone DEFAULT now() NOT NULL,
  "updated_at" timestamp with time zone DEFAULT now() NOT NULL,
  "external_ref" text,
  "source" text DEFAULT 'native'::text NOT NULL,
  CONSTRAINT support_tickets_assignee_check CHECK ((assignee = ANY (ARRAY['de'::text, 'human'::text]))),
  CONSTRAINT support_tickets_de_confidence_check CHECK (((de_confidence >= 0) AND (de_confidence <= 100))),
  CONSTRAINT support_tickets_priority_check CHECK ((priority = ANY (ARRAY['p1'::text, 'p2'::text, 'p3'::text, 'p4'::text]))),
  CONSTRAINT support_tickets_status_check CHECK ((status = ANY (ARRAY['open'::text, 'pending'::text, 'resolved'::text, 'escalated'::text]))),
  CONSTRAINT support_tickets_pkey PRIMARY KEY (id)
);
CREATE TABLE IF NOT EXISTS public.support_triage_rules (
  "id" uuid DEFAULT gen_random_uuid() NOT NULL,
  "tenant_id" uuid NOT NULL,
  "rule_order" integer DEFAULT 100 NOT NULL,
  "name" text NOT NULL,
  "match_pattern" text,
  "set_category" text NOT NULL,
  "set_priority" text DEFAULT 'normal'::text NOT NULL,
  "set_severity" text DEFAULT 'sev3'::text NOT NULL,
  "active" boolean DEFAULT true NOT NULL,
  "created_at" timestamp with time zone DEFAULT now() NOT NULL,
  "source_proposal_id" uuid,
  "owner_de_id" uuid,
  CONSTRAINT support_triage_rules_set_priority_check CHECK ((set_priority = ANY (ARRAY['low'::text, 'normal'::text, 'high'::text, 'urgent'::text]))),
  CONSTRAINT support_triage_rules_pkey PRIMARY KEY (id)
);
CREATE TABLE IF NOT EXISTS public.tenant_activity_log (
  "id" bigint GENERATED ALWAYS AS IDENTITY NOT NULL,
  "tenant_id" uuid NOT NULL,
  "actor_user_id" uuid NOT NULL,
