CREATE TABLE IF NOT EXISTS public.tenant_billing_config (
  "config_id" uuid DEFAULT gen_random_uuid() NOT NULL,
  "tenant_id" uuid NOT NULL,
  "sophie_config_cost" numeric(10,2) DEFAULT 100,
