  "billing_email" text,
  "payment_method" text DEFAULT 'invoice'::text,
  "auto_pay_enabled" boolean DEFAULT false,
  "created_at" timestamp without time zone DEFAULT now(),
  "updated_at" timestamp without time zone DEFAULT now(),
  CONSTRAINT tenant_billing_config_pkey PRIMARY KEY (config_id),
  CONSTRAINT tenant_billing_config_tenant_id_key UNIQUE (tenant_id)
