  "position" integer DEFAULT 0 NOT NULL,
  "created_by" uuid,
  "created_at" timestamp with time zone DEFAULT now() NOT NULL,
  CONSTRAINT tenant_entity_fields_field_key_check CHECK ((field_key ~ '^[a-z][a-z0-9_]*$'::text)),
  CONSTRAINT tenant_entity_fields_field_type_check CHECK ((field_type = ANY (ARRAY['text'::text, 'number'::text, 'date'::text]))),
  CONSTRAINT tenant_entity_fields_pkey PRIMARY KEY (id),
  CONSTRAINT tenant_entity_fields_tenant_id_field_key_key UNIQUE (tenant_id, field_key)
);
