-- ── Views ───────────────────────────────────────────────────────────────────
CREATE OR REPLACE VIEW public.connector_secrets_decrypted AS
 SELECT cs.connector_id,
    vs.decrypted_secret AS secret
   FROM connector_secrets cs
     JOIN vault.decrypted_secrets vs ON vs.id = cs.secret_id;
CREATE OR REPLACE VIEW public.discovery_capability_demand AS
 SELECT capability,
    dimension_key,
    dimension_title,
    count(DISTINCT tenant_id)::integer AS tenants_surfaced,
    count(DISTINCT session_id)::integer AS sessions_surfaced,
    min(surfaced_at) AS first_surfaced_at,
    max(surfaced_at) AS last_surfaced_at
   FROM discovery_capability_demand_log l
  GROUP BY capability, dimension_key, dimension_title;
CREATE OR REPLACE VIEW public.discovery_capability_gaps AS
 SELECT d.key AS dimension_key,
    d.title,
    d.serves_archetypes,
    gaps.planned_archetypes,
    ('We do not have a ready-made '::text || array_to_string(gaps.planned_labels, ' / '::text)) || ' capability yet — we will build one around what you have described.'::text AS customer_message
   FROM discovery_dimensions d
     CROSS JOIN LATERAL ( SELECT array_agg(a.a ORDER BY a.a) AS planned_archetypes,
            array_agg(
                CASE
                    WHEN regexp_replace(a.a, '^planned_'::text, ''::text) = 'qa'::text THEN 'QA'::text
                    ELSE regexp_replace(a.a, '^planned_'::text, ''::text)
                END ORDER BY a.a) AS planned_labels
           FROM unnest(d.serves_archetypes) a(a)
          WHERE a.a ~ '^planned_'::text) gaps
  WHERE d.active AND gaps.planned_archetypes IS NOT NULL;
CREATE OR REPLACE VIEW public.eval_gate AS
 SELECT DISTINCT ON (tenant_id) tenant_id,
    id AS run_id,
    status,
    total,
    passed,
    failed,
    finished_at
   FROM eval_runs
  WHERE finished_at IS NOT NULL AND (status = ANY (ARRAY['passed'::text, 'failed'::text]))
  ORDER BY tenant_id, finished_at DESC;
CREATE OR REPLACE VIEW public.pipeline_summary AS
 SELECT tenant_id,
    stage,
    count(*)::integer AS opp_count,
    COALESCE(sum(amount_cents), 0::numeric)::bigint AS amount_cents,
    ( SELECT
                CASE
                    WHEN count(*) = 0 THEN NULL::integer
                    ELSE round(100.0 * count(*) FILTER (WHERE o2.stage = 'won'::text)::numeric / count(*)::numeric)::integer
                END AS round
           FROM opportunities o2
          WHERE o2.tenant_id = o.tenant_id AND (o2.stage = ANY (ARRAY['won'::text, 'lost'::text])) AND o2.closed_at > (now() - '90 days'::interval)) AS win_rate_90d
   FROM opportunities o
  GROUP BY tenant_id, stage;
CREATE OR REPLACE VIEW public.specialist_source_secrets_decrypted AS
 SELECT sss.source_id,
    vs.decrypted_secret AS secret
   FROM specialist_source_secrets sss
     JOIN vault.decrypted_secrets vs ON vs.id = sss.secret_id;
CREATE OR REPLACE VIEW public.tenant_sso_effective_policy AS
 SELECT tenant_id,
    sso_required,
    jit_enabled,
    jit_default_role,
    COALESCE(( SELECT array_agg(DISTINCT lower(d.domain) ORDER BY (lower(d.domain))) AS array_agg
           FROM tenant_domains d
          WHERE d.tenant_id = p.tenant_id AND d.status = 'verified'::text), ARRAY[]::text[]) AS allowed_domains,
    updated_at
   FROM tenant_sso_policy p;

-- ── Functions that name a table row type (RETURNS SETOF <table>) ───────────
CREATE OR REPLACE FUNCTION public.action_execution_landed(ae action_executions)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
AS $function$
  -- (1) a terminal-SUCCESSFUL decision. A WHITELIST — never a not-a-failure
  --     blacklist, which admits previewed, rejected, expired and both gates.
  select ae.decision in ('auto_executed', 'executed_after_approval')
  -- (2) evidence the call RETURNED. A blank receipt is not a receipt.
     and (coalesce(btrim(ae.receipt), '') <> '' or ae.result is not null)
  -- (3) no contradicting result. `#>>` so a non-object result yields null.
     and coalesce(ae.result #>> array['ok'], 'true') <> 'false'
  -- (4) not undone
     and ae.rolled_back_at is null;
$function$;

CREATE OR REPLACE FUNCTION public.append_audit_event(p_tenant_id uuid, p_actor text, p_actor_type text, p_action text, p_category text, p_detail jsonb DEFAULT '{}'::jsonb)
 RETURNS audit_events
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_prev  text;
  v_now   timestamptz;
  v_hash  text;
  v_row   audit_events;
  v_actor text := coalesce(nullif(p_actor, ''), 'system');
  v_type  text := coalesce(nullif(p_actor_type, ''), 'system');
  v_detail jsonb := coalesce(p_detail, '{}'::jsonb);
  v_block_de uuid;
BEGIN
  IF coalesce(auth.role(), '') <> 'service_role' THEN
    IF NOT EXISTS (
      SELECT 1 FROM profiles WHERE user_id = auth.uid() AND tenant_id = p_tenant_id
    ) THEN
      RAISE EXCEPTION 'not a member of this tenant';
    END IF;
    -- Server-attested identity: whoever holds this JWT is a USER; what
    -- they claimed to be is preserved in detail for transparency.
    IF v_actor IS DISTINCT FROM '' AND (p_actor IS DISTINCT FROM null) THEN
      v_detail := v_detail || jsonb_build_object('claimed_actor', p_actor, 'claimed_actor_type', p_actor_type);
    END IF;
    SELECT coalesce(nullif(trim(full_name), ''), 'user') INTO v_actor
    FROM profiles WHERE user_id = auth.uid() AND tenant_id = p_tenant_id LIMIT 1;
    -- MUST be one of the audit_events actor_type CHECK values
    -- ('de','human','system'). A JWT caller is a human; using 'user' here
    -- silently broke every user-initiated audit write until it was caught
    -- by the Wave 1 end-to-end test.
    v_type := 'human';
    v_detail := v_detail || jsonb_build_object('_user_submitted', true, '_submitted_by', auth.uid());
  END IF;

  -- Per-employee attribution (trust program docs/31 Q7, item 4): a guardrail
  -- block written by an employee actor is stamped with that employee's id so
  -- employee-scoped trust policies can count an honest, per-employee block
  -- record. The actor string every writer passes is the employee's effective
  -- display name (persona name when set, else record name); the stamp is
  -- only applied when that name resolves to EXACTLY ONE employee in the
  -- tenant — ambiguous or unknown names are left unstamped rather than
  -- guessed. Writers that already provide detail.de_id win untouched. The
  -- stamp happens before the hash below, so the tamper-evident chain covers
  -- it and verify_audit_chain still passes.
  IF p_category = 'guardrail_block' AND v_type = 'de' AND NOT (v_detail ? 'de_id') THEN
    SELECT min(id) INTO v_block_de
    FROM digital_employees
    WHERE tenant_id = p_tenant_id
      AND coalesce(nullif(persona_name, ''), name) = v_actor
    HAVING count(*) = 1;
    IF v_block_de IS NOT NULL THEN
      v_detail := v_detail || jsonb_build_object('de_id', v_block_de);
    END IF;
  END IF;

  PERFORM pg_advisory_xact_lock(hashtext('audit_' || p_tenant_id::text));

  -- mig 549: both AFTER the lock. Taking the clock first is what let a row be
  -- stamped earlier than its own parent; taking the head by timestamp is what
  -- then forked the chain.
  v_now  := clock_timestamp();
  v_prev := public.audit_chain_tip(p_tenant_id);

  v_hash := encode(digest(
    v_prev || p_tenant_id::text || coalesce(p_action, '') ||
    coalesce(v_detail::text, '{}') || v_now::text,
    'sha256'), 'hex');

  INSERT INTO audit_events (tenant_id, actor, actor_type, action, category, detail, prev_hash, hash, created_at)
  VALUES (p_tenant_id, v_actor, v_type, p_action, p_category, v_detail, v_prev, v_hash, v_now)
  RETURNING * INTO v_row;

  INSERT INTO audit_chain_state AS s (tenant_id, head_hash, head_event_id, events, updated_at)
  VALUES (p_tenant_id, v_row.hash, v_row.id, 1, v_now)
  ON CONFLICT (tenant_id) DO UPDATE
    SET head_hash = excluded.head_hash, head_event_id = excluded.head_event_id,
        events = s.events + 1, updated_at = excluded.updated_at;

  RETURN v_row;
END;
$function$;

CREATE OR REPLACE FUNCTION public.assess_de_skills()
 RETURNS SETOF de_skills
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_tenant uuid;
begin
  v_tenant := auth_tenant_id();
  if v_tenant is null then raise exception 'not a member of any workspace'; end if;
  if not auth_has_tenant_role(array['tenant_owner', 'tenant_admin']) then
    raise exception 'only workspace owners/admins can run a skills assessment';
  end if;
  perform assess_de_skills_internal(v_tenant);
  return query select * from de_skills where tenant_id = v_tenant;
end;
$function$;

CREATE OR REPLACE FUNCTION public.certify_digital_employee(p_de_id uuid, p_cert_type text, p_scope text, p_note text, p_valid_days integer DEFAULT 180)
 RETURNS de_certifications
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tenant uuid;
  v_de_name text;
  v_actor text;
  v_row de_certifications;
begin
  if p_cert_type not in ('workspace', 'compliance', 'capability') then
    raise exception 'certification type must be workspace, compliance, or capability';
  end if;
  if p_note is null or trim(p_note) = '' then
    raise exception 'a certification requires a note stating what was reviewed';
  end if;
  if coalesce(p_valid_days, 0) < 1 or p_valid_days > 730 then
    raise exception 'validity must be between 1 and 730 days';
  end if;
  v_tenant := auth_tenant_id();
  if v_tenant is null then raise exception 'not a member of any tenant'; end if;
  if not auth_has_tenant_role(array['tenant_owner', 'tenant_admin']) then
    raise exception 'only workspace owners/admins can certify a Digital Employee';
  end if;
  select name into v_de_name from digital_employees
  where id = p_de_id and tenant_id = v_tenant and lifecycle_status not in ('retired', 'archived');
  if v_de_name is null then raise exception 'employee not found in this workspace (or retired)'; end if;

  select full_name into v_actor from profiles where user_id = auth.uid();

  insert into de_certifications (tenant_id, de_id, cert_type, scope, note, issued_by, issued_by_name, expires_at)
  values (v_tenant, p_de_id, p_cert_type, coalesce(p_scope, ''), trim(p_note), auth.uid(),
          coalesce(v_actor, 'A workspace admin'), now() + make_interval(days => p_valid_days))
  returning * into v_row;

  perform append_audit_event_internal(
    v_tenant, coalesce(v_actor, 'A workspace admin'), 'human',
    format('%s certified (%s%s) — valid %s days: "%s"', v_de_name, p_cert_type,
      case when coalesce(p_scope, '') <> '' then format(': %s', p_scope) else '' end,
      p_valid_days, left(trim(p_note), 160)),
    'config_change',
    jsonb_build_object('kind', 'de_certified', 'de_id', p_de_id, 'cert_id', v_row.id,
      'cert_type', p_cert_type, 'expires_at', v_row.expires_at)
  );
  return v_row;
end;
$function$;

CREATE OR REPLACE FUNCTION public.claim_de_work_items(p_limit integer DEFAULT 10, p_worker text DEFAULT 'worker'::text, p_tenant_id uuid DEFAULT NULL::uuid)
 RETURNS SETOF de_work_items
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  return query
  with due as (
    select w.id
    from de_work_items w
    join digital_employees de on de.id = w.de_id
      left join de_objectives o on o.id = w.objective_id
      left join role_archetypes ro on ro.key = de.archetype_key
    where w.status = 'queued'
      and w.scheduled_for <= now()
      and (p_tenant_id is null or w.tenant_id = p_tenant_id)
      and tenant_is_operational(w.tenant_id)
      -- WAVE-1 FIX (mig 249): an unavailable employee's items stay queued.
      and de.status = 'active'
      and de.lifecycle_status not in ('paused', 'retired', 'archived')
      -- T2.4: a paused/cancelled mission's fanned work stops claiming at once,
      -- for single AND team missions. NULL-safe: non-mission items (objective_id
      -- null, or objective without a mission) are unaffected.
      and not exists (
        select 1 from de_objectives o
        join de_missions m on m.id = o.mission_id
        where o.id = w.objective_id and m.status in ('paused', 'cancelled'))
      and (w.depends_on is null
           or exists (select 1 from de_work_items d where d.id = w.depends_on and d.status = 'done'))
    order by
      -- URGENCY FIRST, except where the founder ruled otherwise.
      --
      -- A role whose claim_order is 'arrival' sorts purely by when the work
      -- arrived — support answering is a response queue, and whoever has been
      -- waiting longest must be served first regardless of any deadline
      -- elsewhere. Its sort key IS scheduled_for, so it keeps exactly the
      -- behaviour it has today.
      --
      -- Every other role sorts by a REAL deadline first. Goals without one keep
      -- arrival order, because the tiebreak below is still scheduled_for — so
      -- nothing that lacks a deadline changes position relative to its peers.
      --
      -- NOTE ON priority: it is deliberately NOT used. That column holds two
      -- incompatible numbering systems — a 1-5 scale for health and sweep goals
      -- (2, 3) and the HORIZON DAYS of a checkpoint for renewal goals (30, 60,
      -- 90), written by run_work_watchers. Sorting on it ascending would put
      -- every routine daily sweep ahead of every contract notice deadline.
      -- Fixing that column is separate work; sorting on it now would encode the
      -- bug into the claim order.
      case when coalesce(ro.claim_order, 'urgency') = 'arrival'
           then w.scheduled_for
           else coalesce(o.due_at, 'infinity'::timestamptz) end asc,
      w.scheduled_for asc
    limit greatest(1, least(100, p_limit))
    for update of w skip locked
  )
  update de_work_items w
     set status = 'running', locked_at = now(), locked_by = p_worker,
         attempts = w.attempts + 1, updated_at = now()
    from due
   where w.id = due.id
  returning w.*;
end;
$function$;

CREATE OR REPLACE FUNCTION public.claim_ingestion_items(p_limit integer DEFAULT 10, p_tenant_id uuid DEFAULT NULL::uuid)
 RETURNS SETOF knowledge_ingestion_items
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  -- ⚠ REACHABLE BY NOBODY AFTER THIS MIGRATION, and see the header for why
  -- that is the deliberate answer rather than an oversight: `authenticated`
  -- has never held EXECUTE here, so the platform-admin bar below has never
  -- been able to fire. The body now refuses an unidentified caller instead of
  -- waving it through, which is what makes granting this name to a platform
  -- UI a one-line decision later rather than a re-audit.
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'not authenticated: claiming ingestion work is a platform operation, not an anonymous one';
  END IF;
  IF NOT is_platform_admin() THEN
    RAISE EXCEPTION 'claim_ingestion_items is not callable by tenant users';
  END IF;
  RETURN QUERY SELECT * FROM public.claim_ingestion_items_internal(p_limit, p_tenant_id);
END $function$;

CREATE OR REPLACE FUNCTION public.claim_ingestion_items_internal(p_limit integer DEFAULT 10, p_tenant_id uuid DEFAULT NULL::uuid)
 RETURNS SETOF knowledge_ingestion_items
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  -- NO USER CHECK. The drain runs on a schedule with the service-role client.
  RETURN QUERY
  WITH picked AS (
    SELECT i.id FROM knowledge_ingestion_items i
     WHERE i.status = 'queued'
       AND i.next_attempt_at <= now()
       AND (p_tenant_id IS NULL OR i.tenant_id = p_tenant_id)
     ORDER BY i.next_attempt_at
     LIMIT greatest(1, p_limit)
     FOR UPDATE SKIP LOCKED
  )
  UPDATE knowledge_ingestion_items i
     SET status = 'running', attempts = i.attempts + 1, updated_at = now()
    FROM picked p WHERE i.id = p.id
  RETURNING i.*;
END $function$;

CREATE OR REPLACE FUNCTION public.create_de_development_item(p_de_id uuid, p_description text, p_target_metric text DEFAULT NULL::text, p_target_value numeric DEFAULT NULL::numeric, p_priority text DEFAULT 'medium'::text, p_due_date date DEFAULT NULL::date, p_assigned_to uuid DEFAULT NULL::uuid)
 RETURNS de_development_items
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_tenant uuid; v_row de_development_items;
begin
  v_tenant := auth_tenant_id();
  if v_tenant is null then raise exception 'not a member of any tenant'; end if;
  if not auth_has_tenant_role(array['tenant_owner', 'tenant_admin']) then raise exception 'only workspace owners/admins can create a development item'; end if;
  if not exists (select 1 from digital_employees where id = p_de_id and tenant_id = v_tenant) then
    raise exception 'employee not found in this workspace';
  end if;
  if p_assigned_to is not null and not exists (select 1 from profiles where user_id = p_assigned_to and tenant_id = v_tenant and coalesce(is_active, true)) then
    raise exception 'assignee must be an active member of this workspace';
  end if;

  insert into de_development_items (tenant_id, de_id, item_type, source, priority, description, target_metric, target_value, status, assigned_to, due_date, created_by)
  values (v_tenant, p_de_id, 'manual', 'manual', p_priority, p_description, p_target_metric, p_target_value, 'proposed', p_assigned_to, p_due_date, auth.uid())
  returning * into v_row;

  perform sync_de_lifecycle_from_development(p_de_id);
  return v_row;
end;
$function$;

CREATE OR REPLACE FUNCTION public.create_digital_employee(p_name text, p_description text DEFAULT ''::text, p_category text DEFAULT 'Customer'::text, p_department text DEFAULT ''::text, p_persona_name text DEFAULT NULL::text, p_trust_level text DEFAULT 'supervised'::text, p_confidence_threshold integer DEFAULT 75, p_required_approval boolean DEFAULT false)
 RETURNS digital_employees
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_tenant uuid;
  v_role   text;
  v_is_active boolean;
  v_user   uuid := auth.uid();
  v_row    digital_employees;
  v_assignment_id uuid;
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    select tenant_id, role, coalesce(is_active, true) into v_tenant, v_role, v_is_active from profiles where user_id = v_user;
    if v_tenant is null then
      raise exception 'not a member of any tenant';
    end if;
    if not v_is_active then
      raise exception 'account is deactivated';
    end if;
    if v_role not in ('tenant_owner', 'tenant_admin') then
      raise exception 'only workspace owners/admins can create a new Digital Employee';
    end if;
  else
    raise exception 'service-role callers must pass a tenant explicitly — use the seed do-block pattern for migration-time creation';
  end if;

  if trim(coalesce(p_name, '')) = '' then
    raise exception 'a Digital Employee needs a name';
  end if;
  if p_trust_level not in ('supervised', 'established', 'trusted', 'autonomous') then
    raise exception 'trust_level must be one of: supervised, established, trusted, autonomous';
  end if;
  if p_confidence_threshold < 0 or p_confidence_threshold > 100 then
    raise exception 'confidence_threshold must be between 0 and 100';
  end if;

  insert into digital_employees (
    tenant_id, name, persona_name, description, category, department,
    status, lifecycle_status, trust_level, confidence_threshold, required_approval, created_by
  ) values (
    v_tenant, trim(p_name), nullif(trim(coalesce(p_persona_name, '')), ''), coalesce(p_description, ''),
    coalesce(p_category, 'Customer'), coalesce(p_department, ''),
    'active', 'designed', p_trust_level, p_confidence_threshold, coalesce(p_required_approval, false), v_user
  )
  returning * into v_row;

  perform append_audit_event(
    v_tenant, coalesce((select full_name from profiles where user_id = v_user), 'you'), 'human',
    format('New Digital Employee created — %s%s (%s / %s)', v_row.name,
      case when v_row.persona_name is not null then format(' ("%s")', v_row.persona_name) else '' end,
      v_row.category, coalesce(nullif(v_row.department, ''), 'unassigned department')),
    'config_change',
    jsonb_build_object('kind', 'digital_employee_created', 'de_id', v_row.id, 'name', v_row.name,
      'persona_name', v_row.persona_name, 'category', v_row.category, 'department', v_row.department,
      'trust_level', v_row.trust_level, 'created_by', v_user)
  );

  -- The creator becomes this employee's primary responsible person on the
  -- assignment axis (docs/29: the DE line lives in de_assignments). Write
  -- shape mirrors set_de_assignment, mig 429: upsert on the natural key,
  -- then the governance record AFTER the write. category access_control and
  -- actor_type human are the only values the audit_events CHECK allows here.
  insert into de_assignments (tenant_id, de_id, user_id, relation, assigned_by)
  values (v_tenant, v_row.id, v_user, 'primary', v_user)
  on conflict (de_id, user_id, relation) do update set assigned_by = excluded.assigned_by
  returning id into v_assignment_id;

  perform append_audit_event(
    v_tenant,
    coalesce((select full_name from profiles where user_id = v_user), 'A manager'),
    'human',
    format('Assigned %s as primary for a digital employee',
           coalesce((select full_name from profiles where user_id = v_user), 'a teammate')),
    'access_control',
    jsonb_build_object('kind', 'de_assignment_set', 'de_id', v_row.id,
                       'user_id', v_user, 'relation', 'primary',
                       'assignment_id', v_assignment_id, 'was_new', true,
                       'assigned_by', v_user));

  return v_row;
end;
$function$;

CREATE OR REPLACE FUNCTION public.de_config_fingerprint_row(d digital_employees)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_guard text; v_pb text;
begin
  -- mig 462: the employee badge is a DERIVED read-model (recomputed from the
  -- earned ladder + records gate), so it is an output of governance state,
  -- not configuration — deriving it must never stale a certification.
  select coalesce(count(*)::text, '0') || '|' || coalesce(max(updated_at)::text, '')
    into v_guard from guardrail_rules
   where tenant_id = d.tenant_id and active and scope = 'employee' and scope_ref = d.id::text;
  select coalesce(count(*)::text, '0') || '|' || coalesce(max(version)::text, '') || '|' || coalesce(max(updated_at)::text, '')
    into v_pb from playbook_definitions
   where tenant_id = d.tenant_id and de_id = d.id and status = 'published';
  return md5(concat_ws('~',
    coalesce(d.persona_name, ''), coalesce(d.description, ''),
    coalesce(d.model_provider, ''), coalesce(d.model_id, ''),
    coalesce(d.escalation_model_id, ''), coalesce(d.escalation_threshold::text, ''),
    coalesce(d.confidence_threshold::text, ''),
    coalesce(d.required_approval::text, ''), coalesce(d.task_type, ''),
    coalesce(d.external_reply_mode, ''), coalesce(d.capabilities::text, ''),
    coalesce(d.responsibilities::text, ''), coalesce(d.channels::text, ''),
    coalesce(d.knowledge_sources::text, ''), coalesce(d.skills::text, ''),
    coalesce(d.model_config::text, ''), coalesce(d.attributes::text, ''),
    v_guard, v_pb));
end;
$function$;

CREATE OR REPLACE FUNCTION public.decide_human_task(p_task_id uuid, p_decision text, p_reason_code text DEFAULT NULL::text, p_note text DEFAULT NULL::text, p_edit jsonb DEFAULT NULL::jsonb)
 RETURNS human_tasks
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tenant uuid := auth_tenant_id();
  v_task   human_tasks;
  v_row    human_tasks;
  v_cat    text;
  v_amt    bigint;
  v_auth   jsonb;
  v_risk jsonb;
BEGIN
  perform set_config('app.allow_task_decision', 'on', true);   -- mig 486: sanctioned decision path
  IF v_tenant IS NULL THEN RAISE EXCEPTION 'not_authenticated'; END IF;
  IF p_decision NOT IN ('approved', 'rejected') THEN
    RAISE EXCEPTION 'decision must be approved or rejected';
  END IF;
  -- A rejection with no reason teaches nothing. This is the one place the
  -- friction is worth it; a clean approval needs no code.
  IF p_decision = 'rejected' AND coalesce(btrim(p_reason_code), '') = '' THEN
    RAISE EXCEPTION 'reason_required: a rejection must carry a reason code';
  END IF;

  SELECT * INTO v_task FROM human_tasks WHERE id = p_task_id AND tenant_id = v_tenant;
  IF v_task.id IS NULL THEN RAISE EXCEPTION 'task_not_found'; END IF;

  -- DE scoping (mig 385). Null-tolerant, matching the mig-386/452 policies:
  -- an unattributed task is decidable by the whole workspace, exactly as it is
  -- visible to them. A bare guard here would be stricter than the table.
  IF v_task.de_id IS NOT NULL AND NOT public.can_access_de(v_task.de_id) THEN
    RAISE EXCEPTION 'not_responsible_for_de: this employee is not in your reporting line';
  END IF;

  -- ── mig 593: AUTHORITY ──────────────────────────────────
  -- Everything above answers "may you SEE this?". Nothing has ever asked
  -- "are you entitled to SIGN it?" — a PKR 45,000 credit hold and a five
  -- pound refund passed the identical test, and 238 of 320 pending items
  -- name no employee at all, so the scoping clause never even bit.
  --
  -- REJECTIONS ARE DELIBERATELY NOT GATED. Declining is the conservative
  -- direction, and a rule that stops someone saying "no" is not an
  -- authority model, it is a way of forcing things through.
  IF p_decision = 'approved' THEN
    SELECT category, amount_cents INTO v_cat, v_amt FROM task_approval_facts(p_task_id);
    v_auth := has_approval_authority(auth.uid(), v_tenant, v_cat, v_amt);

    IF NOT coalesce((v_auth->>'allowed')::boolean, true) THEN
      RAISE EXCEPTION 'not_authorised_to_approve: %', v_auth->>'reason';
    END IF;

    -- ── THE SECOND QUESTION (spec §3.6) ──────────────────────────────────
    -- Entitlement above answered "may you sign this at all?" — a property of
    -- a PERSON, deny-by-default, because the absence of a grant means nobody
    -- gave you that authority. This asks "does this action need more
    -- scrutiny?" — a property of an ACTION, escalate-only, because the
    -- absence of a restriction means nobody said it was dangerous.
    -- Composed, never merged: the two models have OPPOSITE polarity, and
    -- replacing one with the other would flip deny to allow for every
    -- workspace that has declared authority.
    --
    -- With authority_rules EMPTY this is exactly a no-op, which is the point:
    -- it ships dark and begins to matter only when someone writes a rule.
    v_risk := evaluate_authority(v_tenant, 'user', auth.uid(), v_cat,
                                 case when v_amt is null then '{}'::jsonb
                                      else jsonb_build_object('amount_cents', v_amt) end);

    -- A NULL RESULT IS NOT PERMISSION. `NULL = 'deny'` evaluates to NULL,
    -- not false, so without this guard a null risk result would fall straight
    -- through the test below into an approval. Same polarity error the rest
    -- of this model exists to prevent.
    IF v_risk IS NULL THEN
      RAISE EXCEPTION 'authority_evaluator_unavailable: refusing rather than approving unchecked';
    END IF;

    IF v_risk->>'outcome' = 'deny' THEN
      RAISE EXCEPTION 'not_authorised_to_approve: %',
        coalesce(v_risk->'reasons'->0->>'why', 'a workspace rule denies this');
    END IF;

    -- THE HOLE THIS MIGRATION EXISTS TO CLOSE.
    --
    -- evaluate_authority downgrades a rule it could not CHECK to
    -- `require_human`, because it cannot know whether the rule would have
    -- tripped. That is right for a require_human rule. It was catastrophic
    -- for a `deny` rule: require_human is deliberately treated as already
    -- satisfied here (a human IS approving), so a workspace's `deny` turned
    -- into an approval the moment its measure went unreported. Measured when
    -- this was found: 409 of 412 pending approvals report no amount_cents,
    -- so the unmeasured case was the normal case, not the corner.
    --
    -- The evaluator now carries the DECLARED outcome as `rule_outcome`. A
    -- deny we could not verify refuses. "We could not tell" must never be
    -- spelled the same way as "permitted".
    IF v_risk->'reasons' @> '[{"rule_outcome": "deny", "unverified": true}]'::jsonb THEN
      RAISE EXCEPTION 'not_authorised_to_approve: %',
        coalesce(
          (select x->>'why' from jsonb_array_elements(v_risk->'reasons') x
            where x->>'rule_outcome' = 'deny' and (x->>'unverified')::boolean limit 1),
          'a workspace rule denies this, and the measure it depends on was not reported');
    END IF;

    -- ⚠ require_human is ALREADY SATISFIED on this path — a human IS
    -- approving. Treating it as a refusal would make every unmeasured rule
    -- block every approval. The outcomes that bite here are `deny` above and
    -- `require_second_approver`, which is OR-ed into the existing needs_second
    -- below rather than replacing it: a second pair of eyes required by
    -- EITHER the grant model or a risk rule is still a second pair of eyes.

    -- A second pair of eyes. The first approval is RECORDED and the task
    -- stays pending; it completes when a DIFFERENT person approves.
    -- Recording rather than refusing is what stops the first approver
    -- having to remember they already looked at it.
    IF (coalesce((v_auth->>'needs_second')::boolean, false)
        OR v_risk->>'outcome' = 'require_second_approver')
       AND (v_task.first_approver_id IS NULL OR v_task.first_approver_id = auth.uid()) THEN
      UPDATE human_tasks
         SET first_approver_id = auth.uid(), first_approved_at = now(), updated_at = now()
       WHERE id = p_task_id AND status = 'pending';
      RETURN NULL;   -- contract: NULL means the caller MUST skip its hooks
    END IF;
  END IF;

  -- ⚠ The pending-only clause is the double-approval guard the caller depends
  -- on. No row back means "already decided" and the caller MUST skip its side
  -- effects (invoice send, gated-action execute, write-backs). Do not relax.
  UPDATE human_tasks
     SET status               = p_decision,
         decided_by           = auth.uid(),
         decided_at           = now(),
         updated_at           = now(),
         decision_reason_code = nullif(btrim(p_reason_code), ''),
         decision_note        = nullif(btrim(p_note), ''),
         decision_edit        = p_edit
   WHERE id = p_task_id AND tenant_id = v_tenant AND status = 'pending'
   RETURNING * INTO v_row;

  IF v_row.id IS NULL THEN RETURN NULL; END IF;   -- already decided; caller skips hooks

  -- Governance record. 'approval' is constraint-legal (checked against
  -- audit_events_category_check); p_category is NOT normalised by
  -- append_audit_event, so an invented category would raise and abort the
  -- decision — the mig-429 lesson.
  PERFORM append_audit_event(
    v_tenant,
    coalesce((SELECT full_name FROM profiles WHERE user_id = auth.uid()), 'An approver'),
    'human',
    format('Task %s: %s%s', p_decision, v_row.title,
           CASE WHEN p_reason_code IS NOT NULL THEN ' (' || p_reason_code || ')' ELSE '' END),
    'approval',
    jsonb_build_object(
      'kind', 'human_task_decision', 'task_id', p_task_id, 'task_type', v_row.type,
      'decision', p_decision, 'reason_code', nullif(btrim(p_reason_code), ''),
      'de_id', v_row.de_id, 'edited', (p_edit IS NOT NULL),
      'related_table', v_row.related_table, 'related_id', v_row.related_id));

  RETURN v_row;
END $function$;

CREATE OR REPLACE FUNCTION public.detect_de_development_needs(p_tenant_id uuid)
 RETURNS SETOF de_development_items
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_tenant uuid;
begin
  v_tenant := auth_tenant_id();
  if v_tenant is null or v_tenant <> p_tenant_id then raise exception 'not a member of this workspace'; end if;
  if not auth_has_tenant_role(array['tenant_owner', 'tenant_admin']) then raise exception 'only workspace owners/admins can scan for development needs'; end if;
  return query select * from detect_de_development_needs_internal(p_tenant_id);
end;
$function$;

CREATE OR REPLACE FUNCTION public.detect_de_development_needs_internal(p_tenant_id uuid DEFAULT NULL::uuid)
 RETURNS SETOF de_development_items
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  t record;
  m record;
  v_candidate record;
  v_row de_development_items;
begin
  for t in
    select id from tenants
    where (p_tenant_id is null or id = p_tenant_id)
      and status in ('active', 'trial')
  loop
    for m in select * from get_de_performance_metrics(t.id, 8) where total_decisions >= 10
    loop
      for v_candidate in
        select * from (values
          ('escalation_spike', m.escalation_rate > 50, 'escalation_rate'::text, 30::numeric, m.escalation_rate,
            format('%s escalated %s%% of %s decisions over the last 8 weeks — more than half. Target: bring escalation rate under 30%%.', m.de_name, round(m.escalation_rate), m.total_decisions)),
          ('confidence_gap', m.avg_confidence < 50, 'avg_confidence', 65::numeric, m.avg_confidence,
            format('%s''s average confidence across %s decisions is %s%% — evidence or knowledge coverage may be thin. Target: 65%%+.', m.de_name, m.total_decisions, round(m.avg_confidence))),
          ('error_rate', m.error_rate > 15, 'error_rate', 5::numeric, m.error_rate,
            format('%s had a %s%% run error rate over the last 8 weeks (%s runs). Target: under 5%%.', m.de_name, round(m.error_rate), m.total_runs)),
          ('guardrail_pattern', m.total_runs > 0 and m.blocked_guardrail_count::numeric / m.total_runs > 0.1, 'blocked_guardrail_count', 0::numeric, m.blocked_guardrail_count::numeric,
            format('%s was blocked by a guardrail on %s of %s runs (%s%%) — review whether this is a knowledge gap or a genuinely out-of-scope request pattern.', m.de_name, m.blocked_guardrail_count, m.total_runs, round(m.blocked_guardrail_count::numeric / m.total_runs * 100)))
        ) as c(item_type, triggered, target_metric, target_value, baseline_value, description)
        where c.triggered
      loop
        insert into de_development_items (tenant_id, de_id, item_type, source, priority, description, target_metric, target_value, baseline_value, status)
        values (t.id, m.de_id, v_candidate.item_type, 'detected', 'medium', v_candidate.description, v_candidate.target_metric, v_candidate.target_value, v_candidate.baseline_value, 'proposed')
        on conflict (tenant_id, de_id, item_type) where source = 'detected' and status in ('proposed', 'in_progress')
        do update set description = excluded.description, baseline_value = excluded.baseline_value, updated_at = now()
        returning * into v_row;
        perform sync_de_lifecycle_from_development(m.de_id);
        return next v_row;
      end loop;
      -- Recovery pass (docs/31 Q10, mig 453): each opening bar above, inverted,
      -- releases the entry it opened once the measure is back inside the line;
      -- the employee lifecycle is then re-derived so the flip back to active
      -- fires when the last open entry goes. The two filters keep this
      -- statement away from human-created entries and from the kinds the
      -- other two sweeps own — each of those closes its own.
      update de_development_items i
         set status = 'completed', completed_at = now(), updated_at = now()
       where i.tenant_id = t.id and i.de_id = m.de_id
         and i.source = 'detected'
         and i.status in ('proposed', 'in_progress')
         and ((i.item_type = 'escalation_spike'  and m.escalation_rate <= 50)
           or (i.item_type = 'confidence_gap'    and m.avg_confidence >= 50)
           or (i.item_type = 'error_rate'        and m.error_rate <= 15)
           or (i.item_type = 'guardrail_pattern' and m.blocked_guardrail_count::numeric <= 0.1 * m.total_runs));
      if found then
        perform sync_de_lifecycle_from_development(m.de_id);
      end if;
    end loop;
  end loop;
  return;
end;
$function$;

CREATE OR REPLACE FUNCTION public.get_escalation_signals()
 RETURNS SETOF escalation_signals
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select * from public.escalation_signals
   where tenant_id is null or tenant_id = public.auth_tenant_id()
   order by sort_order, label;
$function$;

CREATE OR REPLACE FUNCTION public.guardrail_rules_for_de(p_tenant_id uuid, p_de_id uuid, p_rule_types text[], p_playbook_def_id uuid DEFAULT NULL::uuid)
 RETURNS SETOF guardrail_rules
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
  select g.*
  from guardrail_rules g
  where g.tenant_id = p_tenant_id
    and g.active
    -- Redundant while the CHECK stands, and deliberately so: this is the
    -- resolver behind the answer path, the action gate and both triage
    -- decisions, and it should not need a constraint elsewhere to be correct.
    and g.retired_at is null
    and g.rule_type = any(p_rule_types)
    and (
          g.scope = 'workspace'
      or (g.scope = 'employee'   and p_de_id is not null
            and g.scope_ref = p_de_id::text)
      or (g.scope = 'department' and p_de_id is not null
            and g.scope_ref = (select de.department
                                 from digital_employees de
                                where de.id = p_de_id))
      or (g.scope = 'playbook'   and p_playbook_def_id is not null
            and g.scope_ref = p_playbook_def_id::text)
    );
$function$;

CREATE OR REPLACE FUNCTION public.knowledge_grant_matches_caller(g knowledge_access_grants)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT public.knowledge_grant_matches_user(g, auth.uid());
$function$;

CREATE OR REPLACE FUNCTION public.knowledge_grant_matches_user(g knowledge_access_grants, p_user uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT CASE g.principal_type
    WHEN 'everyone' THEN true
    WHEN 'user'  THEN g.principal_user_id = p_user
    WHEN 'guest' THEN g.principal_user_id = p_user
    WHEN 'group' THEN EXISTS (SELECT 1 FROM knowledge_principal_group_members m
                               WHERE m.group_id = g.principal_group_id AND m.user_id = p_user)
    WHEN 'role'  THEN EXISTS (SELECT 1 FROM profiles pr
                               WHERE pr.user_id = p_user AND pr.tenant_id = g.tenant_id
                                 AND coalesce(pr.is_active, true) AND pr.role = g.principal_role)
    ELSE false END;
$function$;

CREATE OR REPLACE FUNCTION public.knowledge_verification_state(p_doc knowledge_docs)
 RETURNS text
 LANGUAGE sql
 STABLE
AS $function$
  SELECT CASE
    WHEN p_doc.lifecycle_status <> 'published' THEN p_doc.lifecycle_status
    WHEN p_doc.expires_at IS NOT NULL AND p_doc.expires_at < now() THEN 'needs_verification'
    WHEN coalesce(p_doc.review_interval_days,
                  (SELECT t.knowledge_review_interval_days FROM tenants t WHERE t.id = p_doc.tenant_id)) IS NOT NULL
         AND coalesce(p_doc.last_verified_at, p_doc.created_at)
             < now() - make_interval(days => coalesce(p_doc.review_interval_days,
                 (SELECT t.knowledge_review_interval_days FROM tenants t WHERE t.id = p_doc.tenant_id)))
      THEN 'needs_verification'
    ELSE 'published' END;
$function$;

CREATE OR REPLACE FUNCTION public.list_platform_capability_grants(p_target_user_id uuid DEFAULT NULL::uuid)
 RETURNS SETOF platform_capability_grants
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not resolve_platform_capability(auth.uid(), 'team.manage') then
    raise exception 'only a platform team manager may view capability grants';
  end if;
  if p_target_user_id is not null then
    return query select * from platform_capability_grants where user_id = p_target_user_id order by capability;
  end if;
  return query select * from platform_capability_grants order by user_id, capability;
end;
$function$;

CREATE OR REPLACE FUNCTION public.list_platform_invites()
 RETURNS SETOF platform_invites
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not resolve_platform_capability(auth.uid(), 'team.manage') then
    raise exception 'only a platform team manager may view platform invites';
  end if;
  return query select * from platform_invites order by created_at desc;
end;
$function$;

CREATE OR REPLACE FUNCTION public.list_tenant_deletion_receipts(p_limit integer DEFAULT 100)
 RETURNS SETOF tenant_deletion_receipts
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  -- Not written as "auth.uid() is not null and ..." on purpose: anon has a
  -- NULL uid, and that shape skips the check entirely (see migration 369).
  IF coalesce(auth.role(), '') <> 'service_role'
     AND NOT resolve_platform_capability(auth.uid(), 'tenants.view')
  THEN
    RAISE EXCEPTION 'not authorized to read tenant deletion receipts';
  END IF;

  RETURN QUERY
    SELECT * FROM tenant_deletion_receipts
     ORDER BY deleted_at DESC
     LIMIT greatest(1, least(coalesce(p_limit, 100), 1000));
END $function$;

CREATE OR REPLACE FUNCTION public.operate_domain_of(p_system de_connected_systems)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
DECLARE v_url text;
BEGIN
  IF nullif(btrim(coalesce(p_system.operate_domain,'')),'') IS NOT NULL THEN
    RETURN lower(regexp_replace(regexp_replace(p_system.operate_domain, '^https?://', ''), '/.*$', ''));
  END IF;
  SELECT base_url INTO v_url FROM connectors WHERE id = p_system.connector_id;
  IF v_url IS NULL THEN RETURN NULL; END IF;
  RETURN lower(regexp_replace(regexp_replace(v_url, '^https?://', ''), '/.*$', ''));
END; $function$;

CREATE OR REPLACE FUNCTION public.resolve_action_definition_for_category(p_tenant_id uuid, p_category text)
 RETURNS SETOF action_definitions
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select *
  from action_definitions
  where category = p_category
    and status = 'active'
    and (scope = 'platform' or tenant_id = p_tenant_id)
  order by
    (scope = 'tenant') desc,          -- tenant override wins
    (risk->>'destructive')::boolean asc nulls last,  -- prefer non-destructive candidates
    created_at asc
  limit 1;
$function$;

CREATE OR REPLACE FUNCTION public.resolve_action_execution_for_task(p_task_id uuid)
 RETURNS action_executions
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_task_tenant uuid;
  v_row action_executions;
begin
  select tenant_id into v_task_tenant from human_tasks where id = p_task_id;
  if v_task_tenant is null then
    return null;
  end if;
  if v_task_tenant not in (select tenant_id from profiles where user_id = auth.uid() and coalesce(is_active, true) = true)
     and not resolve_platform_capability(auth.uid(), 'support.cross_tenant') then
    raise exception 'tenant access denied';
  end if;
  select ae.* into v_row from action_executions ae
    where ae.task_id = p_task_id and ae.tenant_id = v_task_tenant
    order by ae.created_at desc limit 1;
  -- DE scoping (mig 385/427). A READER, so it filters rather than raising:
  -- an action the caller may not see returns NULL, exactly as a task that
  -- does not exist already does. Scoped on the ACTION subject, not on
  -- human_tasks.de_id, which is NULL on 82% of rows.
  if v_row.id is not null and v_row.subject_kind = 'de'
     and v_row.subject_id is not null
     and not public.can_access_de(v_row.subject_id) then
    return null;
  end if;
  return v_row;
end;
$function$;

CREATE OR REPLACE FUNCTION public.retire_digital_employee(p_de_id uuid, p_reason text)
 RETURNS digital_employees
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_tenant uuid;
  v_de digital_employees;
  v_readiness jsonb;
  v_owner_name text;
begin
  if p_reason is null or trim(p_reason) = '' then
    raise exception 'a retirement reason is required';
  end if;

  v_tenant := auth_tenant_id();
  if v_tenant is null then raise exception 'not a member of any tenant'; end if;
  if not auth_has_tenant_role(array['tenant_owner', 'tenant_admin']) then raise exception 'only workspace owners/admins can retire a Digital Employee'; end if;

  select * into v_de from digital_employees where id = p_de_id and tenant_id = v_tenant;
  if v_de.id is null then raise exception 'employee not found in this workspace'; end if;
  if v_de.lifecycle_status = 'retired' then raise exception 'this employee is already retired'; end if;

  v_readiness := check_de_retirement_readiness(p_de_id);
  if not (v_readiness->>'ready')::boolean then
    raise exception 'cannot retire — unresolved dependencies: %', (
      select string_agg(b->>'message', '; ') from jsonb_array_elements(v_readiness->'blockers') b
    );
  end if;

  update digital_employees set status = 'disabled', lifecycle_status = 'retired', updated_at = now()
  where id = p_de_id and tenant_id = v_tenant
  returning * into v_de;

  update de_playbook_charter set active = false where tenant_id = v_tenant and de_id = p_de_id and active;
  update de_autonomy set enabled = false where tenant_id = v_tenant and de_id = p_de_id and enabled;

  select full_name into v_owner_name from profiles where user_id = v_de.owner_id;

  perform append_audit_event(
    v_tenant, coalesce(v_owner_name, 'A workspace admin'), 'human',
    format('%s retired — %s', v_de.name, p_reason),
    'config_change',
    jsonb_build_object('kind', 'de_retirement', 'de_id', p_de_id, 'reason', p_reason)
  );

  return v_de;
end;
$function$;

CREATE OR REPLACE FUNCTION public.run_de_performance_review()
 RETURNS SETOF de_performance_reviews
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_tenant uuid;
begin
  v_tenant := auth_tenant_id();
  if v_tenant is null then raise exception 'not a member of any workspace'; end if;
  if not auth_has_tenant_role(array['tenant_owner', 'tenant_admin']) then
    raise exception 'only workspace owners/admins can run a performance review';
  end if;
  return query select * from run_de_performance_review_internal(v_tenant, null);
end;
$function$;

CREATE OR REPLACE FUNCTION public.run_de_performance_review_internal(p_tenant_id uuid DEFAULT NULL::uuid, p_de_id uuid DEFAULT NULL::uuid, p_window_weeks integer DEFAULT 13)
 RETURNS SETOF de_performance_reviews
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_t             record;
  m               record;
  v_skills        jsonb;
  v_verdict       text;
  v_summary       text;
  v_row           de_performance_reviews;
  v_goals         jsonb;
  v_n_goals       int;
  v_n_measured    int;
  v_n_unmet       int;
  v_unmet_text    text;
  v_first_name    text;
  v_first_key     text;
  v_first_target  numeric;
  v_first_current numeric;
  v_window_label  text;
  v_period_end    date := current_date;
  v_period_start  date;
begin
  if coalesce(p_window_weeks, 0) < 1 then
    raise exception 'window_weeks_invalid: % — a review window is at least one week', p_window_weeks;
  end if;

  -- The window the row CLAIMS is the window the numbers COME FROM.
  v_period_start := v_period_end - (p_window_weeks * 7);
  v_window_label := format('%s week%s to %s', p_window_weeks,
                           case when p_window_weeks = 1 then '' else 's' end, v_period_end);

  for v_t in
    select distinct de.tenant_id as tid from digital_employees de
    where de.lifecycle_status not in ('retired', 'archived')
      and (p_tenant_id is null or de.tenant_id = p_tenant_id)
      and tenant_is_operational(de.tenant_id)
  loop
    for m in
      select * from get_de_performance_metrics(v_t.tid, p_window_weeks)
      where (p_de_id is null or de_id = p_de_id)
    loop
      if not exists (select 1 from digital_employees d where d.id = m.de_id
                     and d.lifecycle_status in ('assigned', 'active', 'improving', 'paused')) then
        continue;
      end if;

      select coalesce(jsonb_agg(jsonb_build_object(
               'skill', s.skill_key, 'proficiency', s.proficiency, 'value', s.signal_value)), '[]'::jsonb)
        into v_skills from de_skills s where s.de_id = m.de_id;

      -- The goals this workspace actually set, resolved over THIS window. One
      -- call; every count and every sentence below is derived from it.
      select coalesce(jsonb_agg(jsonb_build_object(
               'metric_key', k.metric_key, 'name', k.name, 'target', k.target,
               'direction', k.direction, 'current', k.current, 'met', k.met) order by k.name), '[]'::jsonb)
        into v_goals
        from de_kpi_status_internal(v_t.tid, m.de_id, p_window_weeks) k;

      select count(*),
             count(*) filter (where g->>'current' is not null),
             count(*) filter (where g->>'current' is not null and coalesce((g->>'met')::boolean, false) = false)
        into v_n_goals, v_n_measured, v_n_unmet
        from jsonb_array_elements(v_goals) g;

      select string_agg(format('%s (%s vs target %s)',
                               g->>'name', round((g->>'current')::numeric, 1), round((g->>'target')::numeric, 1)),
                        '; ' order by g->>'name')
        into v_unmet_text
        from jsonb_array_elements(v_goals) g
       where g->>'current' is not null and coalesce((g->>'met')::boolean, false) = false;

      select g->>'name', g->>'metric_key', (g->>'target')::numeric, (g->>'current')::numeric
        into v_first_name, v_first_key, v_first_target, v_first_current
        from jsonb_array_elements(v_goals) g
       where g->>'current' is not null and coalesce((g->>'met')::boolean, false) = false
       order by g->>'name' limit 1;

      if v_n_goals = 0 then
        v_verdict := 'insufficient_data';
        v_summary := format('No goals are set for %s, so there is nothing to review it against. Set goals on this employee and the next review (%s) will measure them.',
                            m.de_name, v_window_label);
      elsif m.total_decisions < 10 then
        v_verdict := 'insufficient_data';
        v_summary := format('%s handled %s decisions over %s — below the 10 needed for a meaningful verdict. No judgment recorded on thin evidence.',
                            m.de_name, m.total_decisions, v_window_label);
      elsif v_n_measured = 0 then
        v_verdict := 'insufficient_data';
        v_summary := format('%s goal%s set for %s, but none has a measured value over %s yet. No judgment recorded on an unmeasured goal.',
                            v_n_goals, case when v_n_goals = 1 then ' is' else 's are' end,
                            m.de_name, v_window_label);
      elsif v_n_unmet > 0 then
        v_verdict := 'below';
        v_summary := format('%s missed %s of %s measured goal%s over %s: %s. A Performance Improvement Plan has been opened.',
                            m.de_name, v_n_unmet, v_n_measured,
                            case when v_n_measured = 1 then '' else 's' end, v_window_label, v_unmet_text);
      else
        v_verdict := 'meets';
        v_summary := format('%s met all %s measured goal%s over %s, across %s decisions.',
                            m.de_name, v_n_measured, case when v_n_measured = 1 then '' else 's' end,
                            v_window_label, m.total_decisions);
      end if;

      insert into de_performance_reviews (tenant_id, de_id, period_start, period_end, verdict, summary, metrics_snapshot)
      values (v_t.tid, m.de_id, v_period_start, v_period_end, v_verdict, v_summary,
        jsonb_build_object(
          'window_weeks', p_window_weeks,
          'total_decisions', m.total_decisions, 'resolution_rate', m.resolution_rate,
          'avg_confidence', m.avg_confidence, 'escalation_rate', m.escalation_rate,
          'error_rate', m.error_rate, 'blocked_guardrail_count', m.blocked_guardrail_count,
          'avg_frustration_score', m.avg_frustration_score, 'skills', v_skills,
          -- The goals are evidence now, so a past verdict can be read back
          -- against what it was actually judged on.
          'goals', v_goals))
      on conflict (tenant_id, de_id, period_start)
      do update set period_end = excluded.period_end, verdict = excluded.verdict,
                    summary = excluded.summary, metrics_snapshot = excluded.metrics_snapshot
      returning * into v_row;

      if v_verdict = 'below' then
        insert into de_development_items (tenant_id, de_id, item_type, source, priority, description,
          target_metric, target_value, baseline_value, status, due_date, consequence)
        values (v_t.tid, m.de_id, 'pip', 'detected', 'high',
          format('Performance Improvement Plan for %s (review of %s): meet %s within 30 days. Currently missing: %s.',
                 m.de_name, v_window_label, v_first_name, v_unmet_text),
          v_first_key, v_first_target, v_first_current,
          'proposed', current_date + 30,
          'If targets are not met by the due date, a CRITICAL incident is raised for trust review — possible outcomes decided by a human there: trust reduction, added approval gates, or pause.')
        on conflict (tenant_id, de_id, item_type) where source = 'detected' and status in ('proposed', 'in_progress')
        -- due_date IS DELIBERATELY NOT REFRESHED. It used to be
        -- `due_date = excluded.due_date`, which reset the deadline to +30 days
        -- on every run, so at any cadence faster than monthly the PIP could
        -- never come due. The description updates; the clock does not restart.
        do update set description    = excluded.description,
                      target_metric  = excluded.target_metric,
                      target_value   = excluded.target_value,
                      baseline_value = excluded.baseline_value,
                      updated_at     = now();
      elsif v_verdict = 'meets' then
        update de_development_items set status = 'completed', completed_at = now(), updated_at = now()
        where tenant_id = v_t.tid and de_id = m.de_id and item_type = 'pip'
          and source = 'detected' and status in ('proposed', 'in_progress');

      elsif v_verdict = 'insufficient_data' and v_n_goals = 0 then
        -- ⛔ THE STRANDING THIS FIXES. `insufficient_data` reached neither
        -- branch above, so an already-open plan could never be closed by the
        -- review again -- it just sat there, overdue, carrying a consequence
        -- clause promising a critical incident.
        --
        -- ONLY the no-goals case. The other two routes to insufficient_data --
        -- thin evidence, and goals with nothing measured yet -- are "not yet",
        -- not "never": that employee may well be judgeable next window, and
        -- withdrawing its plan on a quiet fortnight would be its own defect.
        -- With no goals at all there is nothing a future window can change
        -- until someone sets them.
        update de_development_items set status = 'dismissed', updated_at = now()
        where tenant_id = v_t.tid and de_id = m.de_id and item_type = 'pip'
          and source = 'detected' and status in ('proposed', 'in_progress');
      end if;

      return next v_row;
    end loop;
  end loop;
  return;
end;
$function$;

CREATE OR REPLACE FUNCTION public.seed_trust_policies()
 RETURNS SETOF trust_policies
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_tenant uuid;
  v_is_active boolean;
begin
  select coalesce(is_active, true) into v_is_active from profiles where user_id = auth.uid() limit 1;
  if v_is_active is false then
    raise exception 'account is deactivated';
  end if;
  v_tenant := auth_tenant_id();
  if v_tenant is null then
    raise exception 'no tenant for the current session';
  end if;
  if v_tenant = 'a0000000-0000-0000-0000-000000000001'::uuid then
    raise exception 'demo tenant uses the demo story — earned trust is a live-tenant feature';
  end if;

  -- Role gate (mig 441). These policies are tenant-wide (de_id is NULL), so
  -- there is no employee to scope — the missing axis is role. Owner/admin,
  -- matching migs 433/434: this is the ladder governing how far EVERY
  -- employee may go without a human.
  if not (is_platform_admin() or auth_has_tenant_role(ARRAY['tenant_owner', 'tenant_admin'])) then
    raise exception 'insufficient_permission: seeding trust policy requires an owner or admin';
  end if;

  insert into trust_policies (tenant_id, de_id, action_category, criteria)
  values
    (v_tenant, null, 'invoice_auto_send', '{"window_days":30,"min_eval_pass_rate":0.9,"min_eval_samples":25,"min_human_approval_rate":0.9,"min_human_samples":5,"max_guardrail_blocks":0}'::jsonb),
    (v_tenant, null, 'answer_dock',       '{"window_days":30,"min_eval_pass_rate":0.9,"min_eval_samples":25,"min_human_approval_rate":0.9,"min_human_samples":0,"max_guardrail_blocks":0}'::jsonb),
    (v_tenant, null, 'answer_widget',     '{"window_days":30,"min_eval_pass_rate":0.95,"min_eval_samples":40,"min_human_approval_rate":0.9,"min_human_samples":0,"max_guardrail_blocks":0}'::jsonb)
  on conflict (tenant_id, action_category, coalesce(source_category, ''), coalesce(de_id::text, '')) do nothing;

  return query select * from trust_policies where tenant_id = v_tenant order by action_category;
end;
$function$;

CREATE OR REPLACE FUNCTION public.set_de_attributes(p_de_id uuid, p_attributes jsonb)
 RETURNS digital_employees
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tenant uuid;
  v_row digital_employees;
  v_actor text;
  v_key text;
begin
  v_tenant := auth_tenant_id();
  if v_tenant is null then raise exception 'not a member of any tenant'; end if;
  if not auth_has_tenant_role(array['tenant_owner', 'tenant_admin']) then
    raise exception 'only workspace owners/admins can edit a Digital Employee''s profile fields';
  end if;
  if p_attributes is null or jsonb_typeof(p_attributes) <> 'object' then
    raise exception 'attributes must be a JSON object';
  end if;

  select * into v_row from digital_employees where id = p_de_id and tenant_id = v_tenant;
  if v_row.id is null then raise exception 'employee not found in this workspace'; end if;
  if v_row.lifecycle_status in ('retired', 'archived') then
    raise exception 'this employee is retired — configuration is locked read-only';
  end if;

  -- Every key must be a DEFINED custom field for this tenant — no
  -- freestyle keys (schema stays intentional, like tenant_entity_fields).
  for v_key in select jsonb_object_keys(p_attributes) loop
    if not exists (select 1 from de_profile_fields f
                   where f.tenant_id = v_tenant and f.field_key = v_key) then
      raise exception 'unknown profile field "%" — define it first under Profile fields', v_key;
    end if;
  end loop;

  -- Merge: provided keys overwrite; a JSON null value REMOVES the key.
  update digital_employees set
    attributes = jsonb_strip_nulls(attributes || p_attributes),
    config_version = config_version + 1,
    updated_at = now()
  where id = p_de_id
  returning * into v_row;

  select full_name into v_actor from profiles where user_id = auth.uid();
  perform append_audit_event_internal(
    v_tenant, coalesce(v_actor, 'A workspace admin'), 'human',
    format('%s profile fields updated — config v%s', v_row.name, v_row.config_version),
    'config_change',
    jsonb_build_object('kind', 'de_attributes_update', 'de_id', p_de_id,
                       'keys', (select jsonb_agg(k) from jsonb_object_keys(p_attributes) k),
                       'config_version', v_row.config_version)
  );
  return v_row;
end;
$function$;

CREATE OR REPLACE FUNCTION public.set_de_autonomy(p_action_type text, p_enabled boolean, p_max_amount_cents bigint, p_min_confidence integer, p_de_id uuid, p_source_category text, p_playbook_id uuid DEFAULT NULL::uuid)
 RETURNS de_autonomy
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tenant uuid := auth_tenant_id();
  v_row    de_autonomy;
begin
  if v_tenant is null then raise exception 'not_authenticated'; end if;
  if not auth_has_tenant_role(array['tenant_owner','tenant_admin','tenant_manager']) then
    raise exception 'not_allowed: only an owner, admin or manager may change what an employee may do on its own';
  end if;
  -- ⚠ An employee is REQUIRED. A NULL de_id used to mean "workspace default,
  -- applies to everybody", which migration 618 removed.
  if p_de_id is null then
    raise exception 'a rule must name the employee it governs — workspace-wide defaults were removed in migration 618';
  end if;
  if not exists (select 1 from digital_employees where id = p_de_id and tenant_id = v_tenant) then
    raise exception 'that employee is not in this workspace';
  end if;
  if p_playbook_id is not null
     and not exists (select 1 from playbook_definitions where id = p_playbook_id and tenant_id = v_tenant) then
    raise exception 'that playbook is not in this workspace';
  end if;

  insert into de_autonomy (tenant_id, action_type, enabled, max_amount_cents, min_confidence,
                           de_id, source_category, playbook_id, updated_by, updated_at)
  values (v_tenant, p_action_type, coalesce(p_enabled, false), p_max_amount_cents, p_min_confidence,
          p_de_id, nullif(btrim(p_source_category), ''), p_playbook_id, auth.uid(), now())
  on conflict (tenant_id, action_type,
               coalesce(de_id, '00000000-0000-0000-0000-000000000000'::uuid),
               coalesce(playbook_id, '00000000-0000-0000-0000-000000000000'::uuid),
               coalesce(source_category, ''))
  do update set enabled = excluded.enabled,
                max_amount_cents = excluded.max_amount_cents,
                min_confidence = excluded.min_confidence,
                updated_by = excluded.updated_by,
                updated_at = now()
  returning * into v_row;

  return v_row;
end;
$function$;

CREATE OR REPLACE FUNCTION public.set_de_availability(p_de_id uuid, p_mode text, p_timezone text DEFAULT 'UTC'::text, p_start_hour integer DEFAULT 9, p_end_hour integer DEFAULT 17, p_days integer[] DEFAULT ARRAY[1, 2, 3, 4, 5])
 RETURNS digital_employees
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tenant uuid;
  v_row digital_employees;
  v_actor text;
  v_avail jsonb;
  v_probe timestamp;
begin
  if p_mode not in ('always_on', 'business_hours') then
    raise exception 'availability mode must be always_on or business_hours';
  end if;
  v_tenant := auth_tenant_id();
  if v_tenant is null then raise exception 'not a member of any tenant'; end if;
  if not auth_has_tenant_role(array['tenant_owner', 'tenant_admin']) then
    raise exception 'only workspace owners/admins can set availability';
  end if;
  select * into v_row from digital_employees where id = p_de_id and tenant_id = v_tenant;
  if v_row.id is null then raise exception 'employee not found in this workspace'; end if;

  if p_mode = 'business_hours' then
    if p_start_hour < 0 or p_start_hour > 23 or p_end_hour < 1 or p_end_hour > 24 or p_start_hour >= p_end_hour then
      raise exception 'hours must satisfy 0 <= start < end <= 24';
    end if;
    if p_days is null or array_length(p_days, 1) is null then
      raise exception 'business hours need at least one working day (1=Mon … 7=Sun)';
    end if;
    begin
      v_probe := now() at time zone p_timezone;  -- validates the tz name
    exception when others then
      raise exception 'unknown timezone "%"', p_timezone;
    end;
    v_avail := jsonb_build_object('mode', 'business_hours', 'timezone', p_timezone,
      'start_hour', p_start_hour, 'end_hour', p_end_hour, 'days', to_jsonb(p_days));
  else
    v_avail := '{"mode": "always_on"}'::jsonb;
  end if;

  update digital_employees set availability = v_avail, updated_at = now()
  where id = p_de_id returning * into v_row;

  select full_name into v_actor from profiles where user_id = auth.uid();
  perform append_audit_event_internal(
    v_tenant, coalesce(v_actor, 'A workspace admin'), 'human',
    format('%s availability set to %s%s', v_row.name, p_mode,
      case when p_mode = 'business_hours' then format(' (%s–%s %s)', p_start_hour, p_end_hour, p_timezone) else '' end),
    'config_change',
    jsonb_build_object('kind', 'de_availability_set', 'de_id', p_de_id, 'availability', v_avail)
  );
  return v_row;
end;
$function$;

CREATE OR REPLACE FUNCTION public.set_de_identity(p_de_id uuid, p_display_title text DEFAULT NULL::text, p_purpose_statement text DEFAULT NULL::text, p_primary_business_outcome text DEFAULT NULL::text, p_responsibilities text[] DEFAULT NULL::text[], p_employee_code text DEFAULT NULL::text, p_location text DEFAULT NULL::text, p_cost_center text DEFAULT NULL::text)
 RETURNS digital_employees
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tenant uuid;
  v_row digital_employees;
  v_actor text;
begin
  v_tenant := auth_tenant_id();
  if v_tenant is null then raise exception 'not a member of any tenant'; end if;
  if not auth_has_tenant_role(array['tenant_owner', 'tenant_admin']) then
    raise exception 'only workspace owners/admins can edit a Digital Employee''s identity';
  end if;
  select * into v_row from digital_employees where id = p_de_id and tenant_id = v_tenant;
  if v_row.id is null then raise exception 'employee not found in this workspace'; end if;
  if v_row.lifecycle_status in ('retired', 'archived') then
    raise exception 'this employee is retired — configuration is locked read-only';
  end if;

  update digital_employees set
    display_title = coalesce(p_display_title, display_title),
    purpose_statement = coalesce(p_purpose_statement, purpose_statement),
    primary_business_outcome = coalesce(p_primary_business_outcome, primary_business_outcome),
    responsibilities = coalesce(p_responsibilities, responsibilities),
    employee_code = coalesce(p_employee_code, employee_code),
    location = coalesce(p_location, location),
    cost_center = coalesce(p_cost_center, cost_center),
    config_version = config_version + 1,
    updated_at = now()
  where id = p_de_id
  returning * into v_row;

  select full_name into v_actor from profiles where user_id = auth.uid();
  perform append_audit_event_internal(
    v_tenant, coalesce(v_actor, 'A workspace admin'), 'human',
    format('%s identity updated (title/purpose/responsibilities) — config v%s', v_row.name, v_row.config_version),
    'config_change',
    jsonb_build_object('kind', 'de_identity_update', 'de_id', p_de_id, 'config_version', v_row.config_version)
  );
  return v_row;
end;
$function$;

CREATE OR REPLACE FUNCTION public.set_de_voice(p_de_id uuid, p_voice text DEFAULT NULL::text, p_context_turns integer DEFAULT NULL::integer)
 RETURNS digital_employees
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tenant uuid;
  v_row digital_employees;
  v_actor text;
  v_voice text;
begin
  v_tenant := auth_tenant_id();
  if v_tenant is null then raise exception 'not a member of any tenant'; end if;
  if not auth_has_tenant_role(array['tenant_owner', 'tenant_admin']) then
    raise exception 'only workspace owners/admins can edit a Digital Employee''s voice';
  end if;
  select * into v_row from digital_employees where id = p_de_id and tenant_id = v_tenant;
  if v_row.id is null then raise exception 'employee not found in this workspace'; end if;
  if v_row.lifecycle_status in ('retired', 'archived') then
    raise exception 'this employee is retired — configuration is locked read-only';
  end if;

  -- Empty string means "clear it and go back to the house voice"; NULL means
  -- "leave it alone" (so a caller can update turns without touching voice).
  v_voice := case when p_voice is null then v_row.voice
                  when btrim(p_voice) = '' then null
                  else left(btrim(p_voice), 2000) end;

  update digital_employees set
    voice = v_voice,
    -- 0 restores single-turn behaviour; 30 is the ceiling the edge functions
    -- clamp to anyway, enforced here so the stored value never lies.
    context_turns = coalesce(least(greatest(p_context_turns, 0), 30), context_turns),
    config_version = config_version + 1,
    updated_at = now()
  where id = p_de_id
  returning * into v_row;

  select full_name into v_actor from profiles where user_id = auth.uid();
  perform append_audit_event_internal(
    v_tenant, coalesce(v_actor, 'A workspace admin'), 'human',
    format('%s voice updated (tone + conversation memory) — config v%s', v_row.name, v_row.config_version),
    'config_change',
    jsonb_build_object('kind', 'de_voice_update', 'de_id', p_de_id,
                       'config_version', v_row.config_version,
                       'has_custom_voice', v_row.voice is not null,
                       'context_turns', v_row.context_turns)
  );
  return v_row;
end;
$function$;

CREATE OR REPLACE FUNCTION public.set_pipeline_stages(p_stages jsonb)
 RETURNS SETOF tenant_pipeline_stages
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user uuid := auth.uid();
  v_tenant uuid;
  v_role text;
  v_is_active boolean;
  v_stage record;
  v_keys text[] := '{}';
  v_pos integer := 0;
  v_orphan record;
begin
  -- Trusted-server gate (migration-125 pattern).
  if auth.role() is not null and auth.role() <> 'service_role' then
    select tenant_id, role, coalesce(is_active, true) into v_tenant, v_role, v_is_active
      from profiles where user_id = v_user;
    if v_tenant is null then raise exception 'not a member of any tenant'; end if;
    if not v_is_active then raise exception 'account is deactivated'; end if;
    if v_role not in ('tenant_owner', 'tenant_admin') then
      raise exception 'only workspace owners/admins can change pipeline stages';
    end if;
  else
    raise exception 'set_pipeline_stages requires an authenticated tenant caller';
  end if;

  if jsonb_typeof(p_stages) <> 'array' or jsonb_array_length(p_stages) < 1 then
    raise exception 'stages must be a non-empty array of {key, label}';
  end if;
  if jsonb_array_length(p_stages) > 12 then
    raise exception 'at most 12 pipeline stages';
  end if;

  for v_stage in select * from jsonb_to_recordset(p_stages) as x(key text, label text) loop
    if v_stage.key is null or v_stage.key !~ '^[a-z][a-z0-9_]*$' then
      raise exception 'stage key "%" must be lowercase letters/digits/underscores', coalesce(v_stage.key, '(null)');
    end if;
    if v_stage.key in ('won', 'lost') then
      raise exception '"won" and "lost" are fixed terminal stages and cannot be redefined';
    end if;
    if coalesce(btrim(v_stage.label), '') = '' then
      raise exception 'stage "%" needs a label', v_stage.key;
    end if;
    if v_stage.key = any(v_keys) then
      raise exception 'duplicate stage key "%"', v_stage.key;
    end if;
    v_keys := array_append(v_keys, v_stage.key);
  end loop;

  -- No open opportunity may be left in a stage that no longer exists.
  select o.stage, count(*) as n into v_orphan
  from opportunities o
  where o.tenant_id = v_tenant
    and o.stage not in ('won', 'lost')
    and not (o.stage = any(v_keys))
  group by o.stage limit 1;
  if found then
    raise exception 'cannot remove stage "%" — % open opportunity(ies) still in it; move them first',
      v_orphan.stage, v_orphan.n;
  end if;

  delete from tenant_pipeline_stages where tenant_id = v_tenant;
  for v_stage in select * from jsonb_to_recordset(p_stages) as x(key text, label text) loop
    v_pos := v_pos + 1;
    insert into tenant_pipeline_stages (tenant_id, stage_key, label, position)
    values (v_tenant, v_stage.key, btrim(v_stage.label), v_pos);
  end loop;

  perform append_audit_event_internal(
    v_tenant, 'You', 'human',
    format('Pipeline stages updated — %s', array_to_string(v_keys, ' → ')),
    'config_change',
    jsonb_build_object('kind', 'pipeline_stages', 'stages', p_stages));

  return query select * from tenant_pipeline_stages where tenant_id = v_tenant order by position;
end;
$function$;

CREATE OR REPLACE FUNCTION public.set_work_item_framing(p_category text, p_template text)
 RETURNS work_item_framing
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tenant uuid;
  v_role   text;
  v_is_active boolean;
  v_row    work_item_framing;
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    select tenant_id, role, coalesce(is_active, true) into v_tenant, v_role, v_is_active from profiles where user_id = auth.uid();
    if v_tenant is null then
      raise exception 'not a member of any tenant';
    end if;
    if not v_is_active then
      raise exception 'account is deactivated';
    end if;
    if v_role not in ('tenant_owner', 'tenant_admin') then
      raise exception 'only workspace owners/admins can customize work-item framing';
    end if;
  else
    raise exception 'service-role callers must pass a tenant via the platform-seed path, not this RPC';
  end if;

  if trim(coalesce(p_template, '')) = '' then
    raise exception 'template must not be empty';
  end if;
  if position('{title}' in p_template) = 0 then
    raise exception 'template must include a {title} placeholder';
  end if;

  insert into work_item_framing (scope, tenant_id, category, template, created_by)
  values ('tenant', v_tenant, p_category, p_template, auth.uid())
  on conflict (scope, coalesce(tenant_id::text, ''), category) do update set
    template = excluded.template, updated_at = now()
  returning * into v_row;

  perform append_audit_event(
    v_tenant, coalesce((select full_name from profiles where user_id = auth.uid()), 'you'), 'human',
    format('Work-item framing customized for %s: "%s"', p_category, left(p_template, 140)),
    'config_change',
    jsonb_build_object('kind', 'work_item_framing_changed', 'category', p_category, 'template', p_template)
  );

  return v_row;
end;
$function$;

CREATE OR REPLACE FUNCTION public.set_workforce_baselines(p_avg_fte_cost_monthly_usd numeric DEFAULT NULL::numeric, p_inquiry_minutes numeric DEFAULT NULL::numeric, p_action_minutes numeric DEFAULT NULL::numeric, p_conversation_minutes numeric DEFAULT NULL::numeric)
 RETURNS workforce_baselines
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tenant uuid;
  v_row workforce_baselines;
  v_actor text;
begin
  v_tenant := auth_tenant_id();
  if v_tenant is null then raise exception 'not a member of any tenant'; end if;
  if not auth_has_tenant_role(array['tenant_owner', 'tenant_admin']) then
    raise exception 'only workspace owners/admins can set workforce baselines';
  end if;
  if p_avg_fte_cost_monthly_usd is not null and p_avg_fte_cost_monthly_usd <= 0 then raise exception 'FTE cost must be positive'; end if;
  if p_inquiry_minutes is not null and p_inquiry_minutes <= 0 then raise exception 'minutes must be positive'; end if;
  if p_action_minutes is not null and p_action_minutes <= 0 then raise exception 'minutes must be positive'; end if;
  if p_conversation_minutes is not null and p_conversation_minutes <= 0 then raise exception 'minutes must be positive'; end if;

  insert into workforce_baselines (tenant_id, avg_fte_cost_monthly_usd, inquiry_minutes, action_minutes, conversation_minutes, updated_by)
  values (v_tenant, p_avg_fte_cost_monthly_usd, p_inquiry_minutes, p_action_minutes, p_conversation_minutes, auth.uid())
  on conflict (tenant_id) do update set
    avg_fte_cost_monthly_usd = excluded.avg_fte_cost_monthly_usd,
    inquiry_minutes = excluded.inquiry_minutes,
    action_minutes = excluded.action_minutes,
    conversation_minutes = excluded.conversation_minutes,
    updated_by = excluded.updated_by,
    updated_at = now()
  returning * into v_row;

  select full_name into v_actor from profiles where user_id = auth.uid();
  perform append_audit_event_internal(
    v_tenant, coalesce(v_actor, 'A workspace admin'), 'human',
    format('Workforce baselines set — FTE cost %s/mo; minutes per task: inquiry %s, action %s, conversation %s (nulls = unconfigured)',
      coalesce('$' || p_avg_fte_cost_monthly_usd::text, '—'),
      coalesce(p_inquiry_minutes::text, '—'), coalesce(p_action_minutes::text, '—'), coalesce(p_conversation_minutes::text, '—')),
    'config_change',
    jsonb_build_object('kind', 'workforce_baselines_set',
      'avg_fte_cost_monthly_usd', p_avg_fte_cost_monthly_usd, 'inquiry_minutes', p_inquiry_minutes,
      'action_minutes', p_action_minutes, 'conversation_minutes', p_conversation_minutes)
  );
  return v_row;
end;
$function$;

CREATE OR REPLACE FUNCTION public.transfer_de_ownership(p_de_id uuid, p_new_owner_user_id uuid, p_note text DEFAULT NULL::text)
 RETURNS digital_employees
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_tenant uuid;
  v_row digital_employees;
  v_old_owner_name text;
  v_new_owner_name text;
begin
  v_tenant := auth_tenant_id();
  if v_tenant is null then raise exception 'not a member of any tenant'; end if;
  if not auth_has_tenant_role(array['tenant_owner', 'tenant_admin']) then raise exception 'only workspace owners/admins can transfer Digital Employee ownership'; end if;

  select * into v_row from digital_employees where id = p_de_id and tenant_id = v_tenant;
  if v_row.id is null then raise exception 'employee not found in this workspace'; end if;
  if v_row.lifecycle_status = 'retired' then raise exception 'this employee is retired — ownership cannot be transferred'; end if;

  if not exists (
    select 1 from profiles where user_id = p_new_owner_user_id and tenant_id = v_tenant and coalesce(is_active, true)
  ) then
    raise exception 'the new owner must be an active member of this workspace';
  end if;

  select full_name into v_old_owner_name from profiles where user_id = v_row.owner_id;
  select full_name into v_new_owner_name from profiles where user_id = p_new_owner_user_id;

  update digital_employees set owner_id = p_new_owner_user_id, updated_at = now()
  where id = p_de_id and tenant_id = v_tenant
  returning * into v_row;

  perform append_audit_event(
    v_tenant,
    coalesce(v_new_owner_name, 'A workspace admin'),
    'human',
    format('Ownership of %s transferred from %s to %s%s', v_row.name,
      coalesce(v_old_owner_name, 'unassigned'), coalesce(v_new_owner_name, 'unassigned'),
      case when p_note is not null and p_note <> '' then format(' — "%s"', p_note) else '' end),
    'config_change',
    jsonb_build_object('kind', 'de_ownership_transfer', 'de_id', p_de_id,
      'old_owner_user_id', v_row.owner_id, 'new_owner_user_id', p_new_owner_user_id, 'note', p_note)
  );

  return v_row;
end;
$function$;

CREATE OR REPLACE FUNCTION public.trust_evidence_for(p_policy trust_policies)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  c              jsonb := p_policy.criteria;
  v_window       integer := coalesce((c->>'window_days')::integer, 30);
  v_since        timestamptz := now() - make_interval(days => coalesce((c->>'window_days')::integer, 30));
  -- eval evidence
  v_eval_total   bigint := 0;
  v_eval_passed  bigint := 0;
  v_eval_rate    numeric := 0;
  v_eval_skipped bigint := 0;
  -- human evidence
  v_h_total      bigint := 0;
  v_h_approved   bigint := 0;
  v_h_rate       numeric := 0;
  -- guardrail evidence
  v_blocks       bigint := 0;
  -- criteria thresholds
  v_min_rate     numeric := coalesce((c->>'min_eval_pass_rate')::numeric, 0.9);
  v_min_samples  integer := coalesce((c->>'min_eval_samples')::integer, 25);
  v_min_h_rate   numeric := coalesce((c->>'min_human_approval_rate')::numeric, 0.9);
  v_min_h_n      integer := coalesce((c->>'min_human_samples')::integer, 0);
  v_max_blocks   integer := coalesce((c->>'max_guardrail_blocks')::integer, 0);
  -- 692: the ladder's true ceiling — founder's per-policy cap, hard-limited to 3.
  v_ceiling      integer := least(3, coalesce(p_policy.max_level, 3));
  v_criteria     jsonb;
  v_eligible     boolean;
begin
  -- Source 1: Proving Ground — finished eval runs in the window. An
  -- employee-scoped policy counts only runs attributed to that employee
  -- (eval_runs.de_id); a tenant-scoped policy keeps the historical
  -- whole-workspace count.
  -- Counted per ITEM from results, not from the run counters, and an item the
  -- employee never actually answered is not a wrong answer.
  --
  -- Two defects were inflating the failure count. Runs whose AI budget ran out
  -- mid-way recorded every remaining question as a FAILED ANSWER, reason
  -- "de-answer error: ai_budget_exceeded" — the employee was never asked. And
  -- two runs carried total=24 with only 16 recorded results, so 8 items each
  -- counted as failures with no item behind them at all. Together that is 30
  -- of 59 failures in the window: half the apparent quality problem was the
  -- harness, not the work.
  --
  -- This is NOT grading on a curve. Genuinely wrong answers still count in
  -- full and the bar has not moved. Questions that were never put to the
  -- employee simply leave the denominator, the way an exam paper that was
  -- never handed out is not a zero.
  select
    count(*) filter (where coalesce((x->>'passed')::boolean, false)
                        or coalesce(x->>'reason','') !~* '(budget|de-answer error|llm_|provider|timeout|unavailable|not_configured)'),
    count(*) filter (where coalesce((x->>'passed')::boolean, false))
    into v_eval_total, v_eval_passed
  from eval_runs r, jsonb_array_elements(coalesce(r.results, '[]'::jsonb)) x
  where r.tenant_id = p_policy.tenant_id
    and r.finished_at is not null
    and r.finished_at >= v_since
    and r.status in ('passed', 'failed')
    and (p_policy.de_id is null or r.de_id = p_policy.de_id);

  select count(*) into v_eval_skipped
  from eval_runs r, jsonb_array_elements(coalesce(r.results, '[]'::jsonb)) x
  where r.tenant_id = p_policy.tenant_id
    and r.finished_at is not null
    and r.finished_at >= v_since
    and r.status in ('passed', 'failed')
    and (p_policy.de_id is null or r.de_id = p_policy.de_id)
    and coalesce((x->>'passed')::boolean, false) = false
    and coalesce(x->>'reason','') ~* '(budget|de-answer error|llm_|provider|timeout|unavailable|not_configured)';
  v_eval_rate := case when v_eval_total > 0 then round(v_eval_passed::numeric / v_eval_total, 4) else 0 end;

  -- Source 2: human task outcomes in the window. invoice category
  -- reads invoice approval gates; answer categories read
  -- escalation / review outcomes (sparse until LLM activation —
  -- min_human_samples defaults to 0 there, honestly noted).
  -- An employee-scoped policy counts only tasks attributed to that
  -- employee (human_tasks.de_id); unattributed tasks are not another
  -- employee's evidence and are excluded from scoped policies.
  -- 682: an exam-origin task is not evidence about production conduct —
  -- deciding an exam escalation must not move the autonomy dial.
  select count(*), count(*) filter (where status = 'approved')
    into v_h_total, v_h_approved
  from human_tasks
  where tenant_id = p_policy.tenant_id
    and status in ('approved', 'rejected')
    and decided_at is not null
    and decided_at >= v_since
    and evidence_is_production(origin)   -- 682
    and case
      when p_policy.action_category = 'invoice_auto_send'
        then (related_table = 'renewal_invoices' or type = 'approval_gate')
      -- An approval IS the evidence. A human looking at what an employee
      -- wants to do and saying yes is the most direct proof it can be
      -- trusted, and it was being discarded: 17 of 22 decisions in the last
      -- 30 days were action_approval and none of them counted.
      -- Deliberately matched to what each policy GOVERNS rather than counted
      -- everywhere: approving a payment reminder must not earn the right to
      -- auto-send customer answers.
      when p_policy.action_category = 'action_execute'
        then type in ('action_approval', 'approval_gate', 'escalation', 'review_gate')
      else type in ('inquiry_review', 'escalation', 'review_gate')
    end
    and (p_policy.de_id is null or de_id = p_policy.de_id);
  v_h_rate := case when v_h_total > 0 then round(v_h_approved::numeric / v_h_total, 4) else 0 end;

  -- Source 3: guardrail blocks in the window. A tenant-scoped policy counts
  -- every block in the tenant (historical behavior). An employee-scoped
  -- policy counts blocks stamped with this employee's id in detail — rows
  -- written before the stamp existed carry no id and age out of the
  -- evidence window naturally.
  -- 682: a block provoked by a marked exercise is the CONTROL being tested,
  -- not the employee misbehaving. Unmarked history ages out of the window;
  -- the chain itself is never edited.
  select count(*) into v_blocks
  from audit_events
  where tenant_id = p_policy.tenant_id
    and category = 'guardrail_block'
    and created_at >= v_since
    and evidence_is_production(detail->>'origin')   -- 682
    and (p_policy.de_id is null or detail->>'de_id' = p_policy.de_id::text);

  v_criteria := jsonb_build_array(
    jsonb_build_object(
      'key', 'eval_pass_rate', 'label', 'Evaluation pass rate',
      'actual', v_eval_rate, 'required', v_min_rate,
      -- Mirror of the human_approval_rate criterion two entries below, which
      -- already reads `v_min_h_n = 0 or (...)`. A policy that sets
      -- min_eval_samples = 0 is saying this employee is not examined on
      -- answering — Finance DE and Account Success DE execute actions, they do
      -- not staff an answer desk. Without this, zero samples produced a zero
      -- rate which failed a 0.9 bar FOREVER: an employee excused from the exam
      -- was permanently marked as having failed it.
      'met', (v_min_samples = 0 or (v_eval_total >= v_min_samples and v_eval_rate >= v_min_rate)),
      'detail', format('%s of %s answered questions passed in the last %s days%s', v_eval_passed, v_eval_total, v_window,
        case when v_eval_skipped > 0
             then format(' (%s never put to the employee — e.g. the AI budget ran out mid-run — and excluded rather than counted wrong)', v_eval_skipped)
             else '' end)),
    jsonb_build_object(
      'key', 'eval_samples', 'label', 'Evaluation sample size',
      'actual', v_eval_total, 'required', v_min_samples,
      'met', v_eval_total >= v_min_samples,
      'detail', format('%s evaluated answers (needs %s)', v_eval_total, v_min_samples)),
    jsonb_build_object(
      'key', 'human_approval_rate', 'label', 'Human approval rate',
      'actual', v_h_rate, 'required', v_min_h_rate,
      'met', (v_min_h_n = 0 or (v_h_total >= v_min_h_n and v_h_rate >= v_min_h_rate)),
      'detail', format('%s of %s human reviews approved in the last %s days', v_h_approved, v_h_total, v_window)),
    jsonb_build_object(
      'key', 'human_samples', 'label', 'Human review sample size',
      'actual', v_h_total, 'required', v_min_h_n,
      'met', v_h_total >= v_min_h_n,
      'detail', format('%s decided reviews (needs %s)', v_h_total, v_min_h_n)),
    jsonb_build_object(
      'key', 'guardrail_blocks', 'label', 'Guardrail blocks',
      'actual', v_blocks, 'required', v_max_blocks,
      'met', v_blocks <= v_max_blocks,
      'detail', format('%s guardrail blocks in the last %s days (max %s)', v_blocks, v_window, v_max_blocks))
  );

  select bool_and((x->>'met')::boolean) into v_eligible
  from jsonb_array_elements(v_criteria) x;

  return jsonb_build_object(
    'policy_id', p_policy.id,
    'action_category', p_policy.action_category,
    'current_level', p_policy.current_level,
    'target_level', p_policy.target_level,
    'window_days', v_window,
    'criteria', v_criteria,
    -- 692: the door only shows green if it can actually open.
    'eligible', coalesce(v_eligible, false) and p_policy.current_level < v_ceiling and p_policy.status = 'active',
    'at_max_level', p_policy.current_level >= v_ceiling,
    'computed_at', now()
  );
end;
$function$;

CREATE OR REPLACE FUNCTION public.trust_ladder_settings(p_policy trust_policies, p_level integer)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select case
    when p_level <= 0 then jsonb_build_object('enabled', false, 'max_amount_cents', null, 'min_confidence', null)
    when p_policy.ladder is null then public.trust_level_settings(p_policy.action_category, p_level)
    else coalesce(
      (
        select jsonb_build_object(
          'enabled',          coalesce((e.entry->>'mode') in ('act_within_limits', 'act'), false),
          'max_amount_cents', nullif(e.entry->'settings'->>'max_amount_cents', '')::bigint,
          'min_confidence',   nullif(e.entry->'settings'->>'min_confidence', '')::integer)
        from jsonb_array_elements(p_policy.ladder) e(entry)
        where (e.entry->>'level')::integer <= least(p_level, coalesce(p_policy.max_level, 3))
        order by (e.entry->>'level')::integer desc
        limit 1
      ),
      jsonb_build_object('enabled', false, 'max_amount_cents', null, 'min_confidence', null))
  end;
$function$;

CREATE OR REPLACE FUNCTION public.update_de_development_item_status(p_item_id uuid, p_status text)
 RETURNS de_development_items
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_tenant uuid; v_row de_development_items;
begin
  if p_status not in ('proposed', 'in_progress', 'completed', 'dismissed') then
    raise exception 'invalid status %', p_status;
  end if;
  v_tenant := auth_tenant_id();
  if v_tenant is null then raise exception 'not a member of any tenant'; end if;
  if not auth_has_tenant_role(array['tenant_owner', 'tenant_admin']) then raise exception 'only workspace owners/admins can update a development item'; end if;

  select * into v_row from de_development_items where id = p_item_id and tenant_id = v_tenant;
  if v_row.id is null then raise exception 'development item not found in this workspace'; end if;

  update de_development_items set
    status = p_status, updated_at = now(),
    completed_at = case when p_status = 'completed' then now() else completed_at end
  where id = p_item_id
  returning * into v_row;

  perform sync_de_lifecycle_from_development(v_row.de_id);
  return v_row;
end;
$function$;

CREATE OR REPLACE FUNCTION public.update_digital_employee(p_de_id uuid, p_name text DEFAULT NULL::text, p_persona_name text DEFAULT NULL::text, p_description text DEFAULT NULL::text, p_department text DEFAULT NULL::text, p_icon text DEFAULT NULL::text, p_confidence_threshold integer DEFAULT NULL::integer, p_required_approval boolean DEFAULT NULL::boolean, p_model_provider text DEFAULT NULL::text, p_model_id text DEFAULT NULL::text, p_task_type text DEFAULT NULL::text, p_escalation_model_id text DEFAULT NULL::text, p_escalation_threshold integer DEFAULT NULL::integer)
 RETURNS digital_employees
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
declare
  v_tenant uuid;
  v_row digital_employees;
  v_name text; v_persona_name text; v_description text; v_department text; v_icon text;
  v_confidence_threshold integer; v_required_approval boolean;
  v_model_provider text; v_model_id text; v_task_type text;
  v_escalation_model_id text; v_escalation_threshold integer;
  v_changed boolean;
begin
  v_tenant := auth_tenant_id();
  if v_tenant is null then raise exception 'not a member of any tenant'; end if;
  if not auth_has_tenant_role(array['tenant_owner', 'tenant_admin']) then raise exception 'only workspace owners/admins can edit a Digital Employee'; end if;

  select * into v_row from digital_employees where id = p_de_id and tenant_id = v_tenant;
  if v_row.id is null then raise exception 'employee not found in this workspace'; end if;
  if v_row.lifecycle_status = 'retired' then raise exception 'this employee is retired — configuration is locked read-only'; end if;

  v_name                := coalesce(p_name, v_row.name);
  v_persona_name        := coalesce(p_persona_name, v_row.persona_name);
  v_description         := coalesce(p_description, v_row.description);
  v_department          := coalesce(p_department, v_row.department);
  v_icon                := coalesce(p_icon, v_row.icon);
  v_confidence_threshold:= coalesce(p_confidence_threshold, v_row.confidence_threshold);
  v_required_approval   := coalesce(p_required_approval, v_row.required_approval);
  v_model_provider      := coalesce(p_model_provider, v_row.model_provider);
  v_model_id            := coalesce(p_model_id, v_row.model_id);
  v_task_type           := coalesce(p_task_type, v_row.task_type);
  v_escalation_model_id := coalesce(p_escalation_model_id, v_row.escalation_model_id);
  v_escalation_threshold:= coalesce(p_escalation_threshold, v_row.escalation_threshold);

  v_changed := v_name is distinct from v_row.name
    or v_persona_name is distinct from v_row.persona_name
    or v_description is distinct from v_row.description
    or v_department is distinct from v_row.department
    or v_icon is distinct from v_row.icon
    or v_confidence_threshold is distinct from v_row.confidence_threshold
    or v_required_approval is distinct from v_row.required_approval
    or v_model_provider is distinct from v_row.model_provider
    or v_model_id is distinct from v_row.model_id
    or v_task_type is distinct from v_row.task_type
    or v_escalation_model_id is distinct from v_row.escalation_model_id
    or v_escalation_threshold is distinct from v_row.escalation_threshold;

  if not v_changed then
    return v_row;
  end if;

  update digital_employees set
    name = v_name, persona_name = v_persona_name, description = v_description,
    department = v_department, icon = v_icon,
    confidence_threshold = v_confidence_threshold, required_approval = v_required_approval,
    model_provider = v_model_provider, model_id = v_model_id, task_type = v_task_type,
    escalation_model_id = v_escalation_model_id, escalation_threshold = v_escalation_threshold,
    config_version = v_row.config_version + 1,
    updated_at = now()
  where id = p_de_id and tenant_id = v_tenant
  returning * into v_row;

  return v_row;
end;
$function$;

CREATE OR REPLACE FUNCTION public.upsert_action_definition(p_id uuid, p_scope text, p_tenant_id uuid, p_category text, p_action_key text, p_label text, p_description text, p_provider text, p_template_id uuid, p_param_schema jsonb, p_risk jsonb, p_execution jsonb)
 RETURNS action_definitions
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_row action_definitions;
  v_user uuid := auth.uid();
  v_role text;
  v_is_active boolean;
  v_tenant_check uuid;
  v_existing_tenant uuid;
begin
  if p_scope not in ('platform', 'tenant') then
    raise exception 'scope must be platform or tenant';
  end if;
  if p_scope = 'tenant' and p_tenant_id is null then
    raise exception 'tenant scope requires tenant_id';
  end if;
  if p_scope = 'platform' and p_tenant_id is not null then
    raise exception 'platform scope must not carry a tenant_id';
  end if;

  if coalesce(auth.role(), '') <> 'service_role' then
    if p_scope = 'platform' then
      raise exception 'only the platform (service role) can define platform-scope actions';
    end if;
    select tenant_id, role, coalesce(is_active, true) into v_tenant_check, v_role, v_is_active from profiles where user_id = v_user;
    if v_tenant_check is distinct from p_tenant_id then
      raise exception 'not a member of this tenant';
    end if;
    if not v_is_active then
      raise exception 'account is deactivated';
    end if;
    if v_role not in ('tenant_owner', 'tenant_admin') then
      raise exception 'only workspace owners/admins can register actions';
    end if;

    -- Restored (dropped by 059): the row named by p_id, if it already
    -- exists, must actually belong to p_tenant_id — otherwise a
    -- caller could pass another tenant's known/guessed id alongside
    -- their own tenant_id and silently overwrite that tenant's action
    -- definition (including its destructive/idempotent risk flags).
    if p_id is not null then
      select tenant_id into v_existing_tenant from action_definitions where id = p_id;
      if found and v_existing_tenant is distinct from p_tenant_id then
        raise exception 'not authorized to modify this action definition';
      end if;
    end if;
  end if;

  if p_provider = 'template' and p_template_id is null then
    raise exception 'template provider requires template_id';
  end if;
  if not (p_risk ? 'destructive') or not (p_risk ? 'idempotent') then
    raise exception 'risk must include destructive and idempotent booleans';
  end if;

  insert into action_definitions (
    id, scope, tenant_id, category, action_key, label, description,
    provider, template_id, param_schema, risk, execution, created_by
  ) values (
    coalesce(p_id, gen_random_uuid()), p_scope, p_tenant_id, p_category, p_action_key, p_label, p_description,
    p_provider, p_template_id, coalesce(p_param_schema, '[]'::jsonb), p_risk, coalesce(p_execution, '{}'::jsonb), v_user
  )
  on conflict (id) do update set
    category = excluded.category, action_key = excluded.action_key,
    label = excluded.label, description = excluded.description,
    provider = excluded.provider, template_id = excluded.template_id,
    param_schema = excluded.param_schema, risk = excluded.risk,
    execution = excluded.execution, updated_at = now()
  returning * into v_row;

  return v_row;
end;
$function$;

CREATE OR REPLACE FUNCTION public.upsert_event_definition(p_id uuid, p_scope text, p_tenant_id uuid, p_event_key text, p_label text, p_description text, p_kind text, p_params_schema jsonb)
 RETURNS event_definitions
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_row event_definitions;
  v_user uuid := auth.uid();
  v_role text;
  v_is_active boolean;
  v_tenant_check uuid;
  v_existing_tenant uuid;
begin
  if p_scope not in ('platform','tenant') then
    raise exception 'scope must be platform or tenant';
  end if;
  if p_scope = 'tenant' and p_tenant_id is null then
    raise exception 'tenant scope requires tenant_id';
  end if;
  if p_scope = 'platform' and p_tenant_id is not null then
    raise exception 'platform scope must not carry a tenant_id';
  end if;
  if p_kind not in ('polled','emitted') then
    raise exception 'kind must be polled or emitted';
  end if;
  if p_event_key !~ '^[a-z][a-z0-9_]*$' then
    raise exception 'event_key must be lowercase letters, digits and underscores (e.g. deal_signed)';
  end if;

  -- Trusted-server gate: auth.role() is NULL for direct DB connections
  -- (postgres / pg_cron / Management API) and 'service_role' for the
  -- service key — both trusted. Only real PostgREST callers are gated.
  if auth.role() is not null and auth.role() <> 'service_role' then
    if p_scope = 'platform' then
      raise exception 'only the platform (service role) can define platform-scope events';
    end if;
    if p_kind <> 'emitted' then
      raise exception 'tenants can only define emitted events (polled events need platform code)';
    end if;
    select tenant_id, role, coalesce(is_active, true) into v_tenant_check, v_role, v_is_active
      from profiles where user_id = v_user;
    if v_tenant_check is distinct from p_tenant_id then
      raise exception 'not a member of this tenant';
    end if;
    if not v_is_active then
      raise exception 'account is deactivated';
    end if;
    if v_role not in ('tenant_owner', 'tenant_admin') then
      raise exception 'only workspace owners/admins can register events';
    end if;
    if p_id is not null then
      select tenant_id into v_existing_tenant from event_definitions where id = p_id;
      if found and v_existing_tenant is distinct from p_tenant_id then
        raise exception 'not authorized to modify this event definition';
      end if;
    end if;
  end if;

  insert into event_definitions (id, scope, tenant_id, event_key, label, description, kind, params_schema, created_by)
  values (coalesce(p_id, gen_random_uuid()), p_scope, p_tenant_id, p_event_key, p_label,
          coalesce(p_description, ''), p_kind, coalesce(p_params_schema, '[]'::jsonb), v_user)
  on conflict (id) do update set
    event_key = excluded.event_key, label = excluded.label, description = excluded.description,
    kind = excluded.kind, params_schema = excluded.params_schema, updated_at = now()
  returning * into v_row;

  return v_row;
end;
$function$;

CREATE OR REPLACE FUNCTION public.upsert_workforce_team(p_name text, p_purpose text DEFAULT ''::text, p_team_id uuid DEFAULT NULL::uuid)
 RETURNS workforce_teams
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_tenant uuid;
  v_row workforce_teams;
  v_actor text;
begin
  if p_name is null or trim(p_name) = '' then raise exception 'a team needs a name'; end if;
  v_tenant := auth_tenant_id();
  if v_tenant is null then raise exception 'not a member of any tenant'; end if;
  if not auth_has_tenant_role(array['tenant_owner', 'tenant_admin']) then
    raise exception 'only workspace owners/admins can manage workforce teams';
  end if;

  if p_team_id is null then
    insert into workforce_teams (tenant_id, name, purpose, created_by)
    values (v_tenant, trim(p_name), coalesce(p_purpose, ''), auth.uid())
    returning * into v_row;
  else
    update workforce_teams set name = trim(p_name), purpose = coalesce(p_purpose, ''), updated_at = now()
    where id = p_team_id and tenant_id = v_tenant
    returning * into v_row;
    if v_row.id is null then raise exception 'team not found in this workspace'; end if;
  end if;

  select full_name into v_actor from profiles where user_id = auth.uid();
  perform append_audit_event_internal(
    v_tenant, coalesce(v_actor, 'A workspace admin'), 'human',
    format('Workforce team "%s" %s', v_row.name, case when p_team_id is null then 'created' else 'updated' end),
    'config_change',
    jsonb_build_object('kind', 'workforce_team_upsert', 'team_id', v_row.id)
  );
  return v_row;
end;
$function$;

CREATE OR REPLACE FUNCTION public.wake_due_objectives(p_limit integer DEFAULT 5)
 RETURNS SETOF de_objectives
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select * from de_objectives
   where status in ('open', 'in_progress', 'blocked')
     and next_wake_at is not null
     and next_wake_at <= now()
     and tenant_is_operational(tenant_id)
   order by next_wake_at asc
   limit greatest(1, least(20, p_limit));
$function$;

CREATE OR REPLACE FUNCTION public.withdraw_human_task(p_task_id uuid, p_note text DEFAULT NULL::text)
 RETURNS human_tasks
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_row    human_tasks;
  -- Captured once. Never gated on an identity test: the "auth.uid() is not
  -- null and" prefix SKIPS a check for a caller with no identity instead of
  -- failing it. 29 of those were closed in mig 749 and
  -- scripts/secdef-authority-prefix.mjs ratchets against a 30th.
  v_tenant uuid := auth_tenant_id();
  v_n      integer;
begin
  -- Mig 794's bar, kept.
  if v_tenant is null then
    raise exception 'not_authenticated';
  end if;

  -- ⚠ 'other', not 'withdrawn'. See this migration's header: 'withdrawn' is
  -- not admitted by human_tasks_decision_reason_code_check and never was, so
  -- every call raised 23514 from 790 until now. The withdrawal stays findable
  -- through disposition='cancelled' plus a non-null reason code, which the
  -- sweeps do not write.
  v_row := public.decide_human_task(p_task_id, 'rejected', 'other', p_note);

  -- NULL composite = already decided.
  if v_row.id is null then
    return null;
  end if;

  update human_tasks
     set disposition = 'cancelled'
   where id = p_task_id
     and tenant_id = v_tenant;

  -- A predicate that can miss must be able to SAY it missed (mig 798).
  get diagnostics v_n = row_count;
  if v_n <> 1 then
    raise exception 'withdraw_incomplete: task % was decided but the withdrawal mark reached % row(s); refusing to report a partial write as success', p_task_id, v_n;
  end if;

  select * into v_row from human_tasks where id = p_task_id and tenant_id = v_tenant;
  return v_row;
end;
$function$;


